        private VisualElement _toastHost;
        private HashSet<LayoutNode> _collapsedNodes = new HashSet<LayoutNode>();
        private Toggle _interactToggleRef;

        // Flat, ordered snapshot of every hierarchy row, rebuilt each RefreshHierarchy/RenderTree.
        // Handed to the drag engine (via HierarchyRowsProvider/GetHierRowInfos) which maps a cursor's
        // X position to an ancestor depth (Unity-style indent reparenting). Mirrors visual row order.
        private struct HierRow
        {
            public LayoutNode Node;
            public int Depth;
            public ContainerNode Parent;   // model parent (null for root and ItemLayout templates)
            public int IndexInParent;      // -1 for root / ItemLayout templates
            public bool Nestable;          // non-Tabs ContainerNode living outside an item template
            public bool Collapsed;         // _collapsedNodes.Contains(node)
            public bool InItemTemplate;    // node lives under a CollectionNode.ItemLayout (excluded from gesture)
            public VisualElement Row;
        }
        private readonly List<HierRow> _hierRows = new();

        // Hands the engine a copy of the flat row metadata for its hierarchy drop snapshot.
        private List<HierRowInfo> GetHierRowInfos()
        {
            var infos = new List<HierRowInfo>(_hierRows.Count);
            foreach (var r in _hierRows)
            {
                infos.Add(new HierRowInfo
                {
                    Node = r.Node,
                    Depth = r.Depth,
                    Parent = r.Parent,
                    IndexInParent = r.IndexInParent,
                    Nestable = r.Nestable,
                    Collapsed = r.Collapsed,
                    InItemTemplate = r.InItemTemplate,
                    Row = r.Row
                });
            }
            return infos;
        }

        [SerializeField] private bool _leftVisible = true;
        [SerializeField] private bool _centerVisible = true;
        [SerializeField] private bool _rightVisible = true;
        private VisualElement _conflictWarningBox;

        // NOTE: The designer is normally opened in-context for a specific type — via the component header's
        // pencil-ruler icon, the header right-click ▸ "Edit Sasquatch Layout", or OpenWindowForType(...). There is
        // ALSO a "Tools ▸ Sasquatch Inspector ▸ Layout Designer" menu item (see OpenLayoutDesignerMenu) as a
        // self-sufficient fallback for when a third-party asset replaces the inspector header and hides those
        // entry points. It opens the window with no target; the blank-state canvas card (RefreshPreview) then
        // lets the user pick any editable script to design. Programmatic callers still use OpenWindowForType.

        private void OnEnable()
        {
            // Join the open-designer registry that answers IsEditingType (see _openDesigners). Guarded
            // against double-add: OnEnable is the only entry point, but a duplicate would make the list a
            // slow leak rather than a wrong answer, and neither is worth risking on a static.
            if (!_openDesigners.Contains(this)) _openDesigners.Add(this);

            Selection.selectionChanged += OnSelectionChanged;
            Undo.undoRedoPerformed += OnUndoRedo;

            if (_presetMode && _presetTarget != null)
            {
                // The preset editor's sample + synthetic layout are transient — rebuild them after a domain reload.
                EnsurePresetSample();
                EnterPresetCategory(_presetCategory);
            }
            else if (_layoutAsset == null)
            {
                LoadSelectedAsset();
            }
            else if (_clonedLayoutAsset != null && _selectedNodeIndexPath != null && _selectedNodeIndexPath.Count > 0)
            {
                _selectedNode = LocateNodeByIndexPath(_selectedNodeIndexPath, _clonedLayoutAsset.Root);
            }

            // hasUnsavedChanges is NOT serialized by EditorWindow, but _isDirty/_clonedLayoutAsset are
            // [SerializeField] and survive domain reloads — so re-assert the unsaved-changes guard after a reload,
            // or the save prompt would be lost while un-persisted clone edits are still showing. The preset editor
            // saves to its asset per-edit, so it never carries database-style unsaved changes.
            hasUnsavedChanges = !_presetMode && _isDirty;

            // A script compile can add/remove/rename serialized fields while this window holds a working clone:
            // the clone ([SerializeField]) SURVIVES the domain reload but is now stale, and the inspectors'
            // auto-sync stays suppressed the whole time we hold the type (IsEditingType). Worse, the
            // _fieldsAtCloneTime baseline does NOT survive the reload, so a later Save used to fall back to
            // ledgering ALL current code fields against the stale tree — permanently excluding just-added
            // fields from AutoAppend (the "auto-append sometimes does nothing, no pattern" bug). Catch the
            // clone up with the script once the editor settles (delayCall — OnEnable runs mid-reload, before
            // settings/assets are reliably loadable). Strict no-op when nothing changed, so re-enables that
            // aren't reloads (docking) cost nothing.
            if (!_presetMode && string.IsNullOrEmpty(_showcaseOverrideKey) && _clonedLayoutAsset != null)
                EditorApplication.delayCall += ReconcileCloneWithScript;
        }

        // One-shot post-reload catch-up for a surviving working clone (see OnEnable). The FIELD reconcile is
        // AutoAppend mode only — the other modes keep script/layout drift user-visible by design. The button
        // rename self-heal runs in EVERY mode (it repairs bindings the user already made rather than
        // importing fields). IN-MEMORY on purpose: the clone must never write to disk except through the
        // user's own Save.
        private void ReconcileCloneWithScript()
        {
            if (this == null || _clonedLayoutAsset == null || _presetMode || !string.IsNullOrEmpty(_showcaseOverrideKey)) return;
            var settings = SasquatchSettingsManager.Current;
            var type = ResolveTargetType();
            if (type == null) return;

            // Button rename self-heal. The clone heals in memory; the REGISTERED layout — still rendered by
            // real inspectors, whose own heal suppresses itself while this window holds the type
            // (IsEditingType) — heals with persistence, mirroring the field reconcile's registered pass below.
            int healed = ButtonMethodSync.HealLayoutInMemory(type, _clonedLayoutAsset);
            if (LayoutRegistry.TryGet(type, _testTarget, out var healTarget) &&
                !ReferenceEquals(healTarget, _clonedLayoutAsset) &&
                ButtonMethodSync.HealLayout(type, healTarget) > 0)
            {
                SasquatchEditorRegistrar.RefreshInspectorsForType(type);
            }
            if (healed > 0)
            {
                OnModification();
                RefreshAll(disableScrollPreservation: true);
                ShowToolToast($"{healed} button{(healed == 1 ? "" : "s")} relinked to renamed method{(healed == 1 ? "" : "s")}.", ToastKind.Success);
            }

            if (settings == null || settings.UnboundFieldHandling != UnboundFieldSyncMode.AutoAppend) return;

            int changes = UnboundFieldSync.ReconcileLayoutInMemory(type, _clonedLayoutAsset, settings.ApplyScriptAttributesOnSync);

            // Re-baseline the save ledger's clone-time snapshot if the reload dropped it. Safe AFTER the
            // reconcile: everything just appended is now bound in the clone, so it lands in the save ledger
            // through GatherBoundPaths regardless of the snapshot.
            if (_fieldsAtCloneTime == null) SnapshotFieldsAtCloneTime();

            // The clone is current now, but the REAL inspectors are still frozen: their auto-sync suppresses
            // itself the whole time this window holds the type (IsEditingType), and nothing above touched the
            // REGISTERED layout they render. Reconcile it too (the same persisting call the inspector hot path
            // would have made — a strict no-op when already in sync) and refresh that type's inspectors in
            // place, so a compile's field changes show up in the inspector WHILE the designer stays open, not
            // only after it closes (CleanupClone's refresh covers only that exit). Safe alongside a dirty
            // clone: Save overwrites the registered tree wholesale, and both trees were reconciled against the
            // same code, so nothing here can be lost or duplicated by the eventual Save.
            if (LayoutRegistry.TryGet(type, _testTarget, out var registeredLayout) &&
                !ReferenceEquals(registeredLayout, _clonedLayoutAsset))
            {
                int registeredChanges = UnboundFieldSync.ReconcileLayout(type, registeredLayout, settings.ApplyScriptAttributesOnSync);
                if (registeredChanges > 0) SasquatchEditorRegistrar.RefreshInspectorsForType(type);
            }

            if (changes > 0)
            {
                OnModification();
                RefreshAll(disableScrollPreservation: true);
                ShowToolToast($"Layout synced with {type.Name}: {changes} script change{(changes == 1 ? "" : "s")} applied.", ToastKind.Success);
            }
        }

        private void OnDisable()
        {
            // Leave the open-designer registry. Also sweeps fake-null entries: OnDisable is reliable, but a
            // stale entry here would suppress the inspectors' auto-sync for that type forever, so the list is
            // kept honest on the way out rather than trusted to be.
            _openDesigners.RemoveAll(w => w == null || w == this);

            // A mid-burst text edit's deferred save must land before teardown (close / domain reload) —
            // the scheduled commit dies with the window's scheduler.
            CommitPendingTextEdit();
            CommitPendingValueEdit(); // same for an in-flight slider/color drag
            Selection.selectionChanged -= OnSelectionChanged;
            Undo.undoRedoPerformed -= OnUndoRedo;
            DestroyMockTarget();
        }

        private void OnDestroy()
        {
            CleanupClone();
            // Shared with the domain-reload sweep (see RegisterPresetSampleReloadTeardown) — closing the window is
            // only ONE of the two ways the sample must be released, and the helper is safe if the other ran first.
            DestroyPresetSample();
        }

        private void OnGUI()
        {
            var e = Event.current;
            if (e == null) return;

            // Escape cancels an in-progress drag (canvas or hierarchy) — the modern "oops" gesture.
            // The user is still holding the button; the card snaps back and releasing the mouse no-ops.
            if (e.type == EventType.KeyDown && e.keyCode == KeyCode.Escape &&
                _canvasDragController != null && _canvasDragController.IsDragging)
            {
                _canvasDragController.CancelDrag();
                e.Use();
                return;
            }

            // F2 renames the selected container's hierarchy row. This OnGUI path is the one that
            // actually fires in the common case: clicking a hierarchy row focuses nothing, and with
            // no focused element UI Toolkit never dispatches KeyDown — only OnGUI sees the key (the
            // Escape handler above has the same split). The UITK root handler covers the
            // field-focused case; both are idempotent (rename-in-progress early-outs).
            if (e.type == EventType.KeyDown && e.keyCode == KeyCode.F2 && _selectedNode is ContainerNode
                && !IsTypingInTextField())
            {
                BeginHierarchyRename(_selectedNode);
                e.Use();
                return;
            }

            // Alt+← walks the drill-in trail back one level (the browser/Unity convention). Same dual-route
            // reasoning as F2 above; TryHandleNavBackShortcut guards text editing and depth 0 itself.
            if (e.type == EventType.KeyDown && e.keyCode == KeyCode.LeftArrow && e.alt && TryHandleNavBackShortcut())
            {
                e.Use();
                return;
            }

            // Arrow keys walk the hierarchy. This OnGUI route carries them in the common case — a hierarchy
            // or canvas row click leaves NOTHING focused, and with no focused element UI Toolkit never
            // dispatches KeyDown at all. Must sit AFTER the Alt+← handler above; it also refuses the chord
            // itself, so the order is belt and braces rather than the only guard.
            if (e.type == EventType.KeyDown && TryHandleHierarchyArrowKey(e.keyCode, e.alt))
            {
                e.Use();
                return;
            }

            if (e.type == EventType.KeyDown && e.keyCode == KeyCode.Delete && TryHandleDeleteShortcut())
            {
                e.Use();
            }

            // Ctrl/Cmd+D duplicates the selection. Same split as Delete: this route fires when nothing is
            // focused, the root UITK handler covers a focused canvas element.
            if (e.type == EventType.KeyDown && e.keyCode == KeyCode.D && (e.control || e.command)
                && TryHandleDuplicateShortcut())
            {
                e.Use();
                return;
            }

            // Unity binds the SAME chord to Edit ▸ Duplicate, which acts on Selection — so a press this window
            // doesn't consume duplicates whatever GameObject or asset is selected in the project instead. Editor
            // versions differ on whether the focused window sees the raw key or the resulting command, so claim
            // BOTH: validating it tells Unity this window owns Duplicate, which stops the fall-through. Only
            // while a layout is actually loaded — the empty picker has nothing to copy and shouldn't swallow the
            // editor's own shortcut. TryHandleDuplicateCommand skips the work when it's an echo of a key press
            // the route above already handled.
            if ((e.type == EventType.ValidateCommand || e.type == EventType.ExecuteCommand)
                && e.commandName == "Duplicate" && _clonedLayoutAsset?.Root != null && !IsTypingInTextField())
            {
                if (e.type == EventType.ExecuteCommand) TryHandleDuplicateCommand();
                e.Use();
            }
        }

        // True when keyboard focus is somewhere text is being edited — the guard every global
        // shortcut (Delete, F2) uses so it never steals a text-editing key. Focus lands on the
        // field ROOT (TextField/…Input), not the inner input element, hence the type-name probe.
        private bool IsTypingInTextField()
        {
            var focused = rootVisualElement.focusController?.focusedElement;
            return focused != null && (focused is TextField ||
                focused.GetType().Name.Contains("Text") || focused.GetType().Name.Contains("Input"));
        }

        // The Delete-key action, shared by BOTH key routes: OnGUI (fires when nothing is focused —
        // hierarchy clicks) and the UITK root handler (fires when focus sits on a canvas element:
        // clicking a card inside a Foldout focuses the Foldout's toggle, and with a focused element
        // UITK consumes the key before OnGUI — the "Delete only works from the hierarchy" bug).
        // Returns true when it deleted something (callers then consume the event).
        private bool TryHandleDeleteShortcut()
        {
            // Delete (not Backspace) is the canonical "remove selected object" key on Windows and in
            // Unity's own Hierarchy, so node/binding/widget/tab removal is Delete-only. Backspace stays a
            // pure text-editing key everywhere. Never steal Delete from a text field that's being edited.
            if (IsTypingInTextField()) return false;

            // Organizer card selection takes priority: remove those tab items (fields go back to
            // unused) while the Tabs container stays selected — same as deleting in hierarchy/canvas.
            if (_clonedLayoutAsset != null && _organizerSelection.Count > 0)
            {
                DeleteNodes(new List<LayoutNode>(_organizerSelection));
                return true;
            }

            bool canDelete = _clonedLayoutAsset != null &&
                             (HasMultiSelection || (_selectedNode != null && _selectedNode != _clonedLayoutAsset.Root));
            if (canDelete)
            {
                if (HasMultiSelection) DeleteSelectedNodes();
                else DeleteNode(_selectedNode);
                return true;
            }
            return false;
        }

        /// <summary>Captures the selected node's index path so the selection survives a domain reload.</summary>
        public void OnBeforeSerialize()
        {
            if (_clonedLayoutAsset != null && _selectedNode != null)
            {
                _selectedNodeIndexPath = GetNodeIndexPath(_selectedNode, _clonedLayoutAsset.Root);
            }
            else
            {
                _selectedNodeIndexPath = null;
            }
        }

        /// <summary>No-op; the selection is restored lazily once the layout reloads.</summary>
        public void OnAfterDeserialize()
        {
        }

        /// <summary>
        /// THE single place a working clone stops being the working copy. Every designer edit records
        /// `Undo.RecordObject(_clonedLayoutAsset, …)` — ~265 call sites — and nothing ever cleared them, so
        /// each discarded clone left its whole edit history in the global undo stack naming an object that
        /// is about to be destroyed. Ctrl+Z past a save or a retarget then walks entries that can only
        /// restore a dead instance: the stack visibly "eats" presses without changing anything.
        ///
        /// Flush BEFORE clearing: an open `RecordObject` snapshot is not yet an undo record, so
        /// `ClearUndo` alone would leave it to land after the object is gone.
        /// </summary>
        private void ReleaseClone(InspectorLayoutAsset clone)
        {
            if (clone == null) return;
            Undo.FlushUndoRecordObjects();
            Undo.ClearUndo(clone);
            DestroyImmediate(clone);
        }

        /// <summary>
        /// Re-clone the working copy from whatever it persists to, so the designer's graph stops BEING the
        /// persisted graph. No-op unless that alias actually exists.
        ///
        /// Both save branches hand the persisted asset the caller's tree by REFERENCE —
        /// `LayoutRegistry.Save`'s `asset.Root = root` and the standalone branch's
        /// `_layoutAsset.Root = _clonedLayoutAsset.Root` — and the de-aliasing re-clone that normally
        /// follows is gated on `!_autoSave`, deliberately: a per-keystroke re-clone would orphan the
        /// Properties panel's live field closures, so edits would land on a dead node and appear not to take.
        /// While Auto-Save is ON that alias is harmless, because every edit is written immediately. It
        /// becomes wrong the moment Auto-Save is switched off: the next edit paints "Save*" while ALREADY
        /// being the registered layout in both render paths, closing and answering "Discard" cannot undo it
        /// (CleanupClone destroys the ScriptableObject, not the managed node graph the registry now owns),
        /// and a later live-inspector resize flushes those discarded edits to disk via PersistLayoutEdit.
        /// </summary>
        private void ReclaimCloneFromPersistedLayout()
        {
            if (_clonedLayoutAsset?.Root == null) return;

            // Act only on a REAL alias, and re-clone from whichever asset owns it.
            InspectorLayoutAsset source = null;
            if (_layoutAsset != null && ReferenceEquals(_layoutAsset.Root, _clonedLayoutAsset.Root))
            {
                source = _layoutAsset;
            }
            else
            {
                var targetType = ResolveTargetType();
                if (targetType != null && LayoutRegistry.TryGet(targetType, out var registered)
                    && registered != null && ReferenceEquals(registered.Root, _clonedLayoutAsset.Root))
                    source = registered;
            }
            if (source == null) return;

            // Every node reference and panel closure is stale after this, exactly as after the post-save
            // re-clone — so re-point the whole node state and rebuild, the same way SaveActiveAsset does.
            var nodeState = SnapshotNodeState(_clonedLayoutAsset.Root);
            var stale = _clonedLayoutAsset;
            AdoptWorkingClone(Instantiate(source));
            ReleaseClone(stale);

            RestoreNodeState(nodeState, _clonedLayoutAsset.Root);
            if (_selectedNode == null) SetPrimarySelection(_clonedLayoutAsset.Root);

            // Fresh clone → the designer has not resized anything in it yet, and the field baseline re-bases.
            _designerResizedSinceClone = false;
            SnapshotFieldsAtCloneTime();
            RefreshAll();
        }

        /// <summary>
        /// The single place a working clone is taken ownership of. Exists to stamp the SAME
        /// <see cref="HideFlags.DontSave"/> the rest of the package gives its transient ScriptableObjects
        /// (see LayoutRegistry's cache and the preset sample) — a clone is a working copy in memory, never an
        /// asset, and it must not depend on ambient reachability to stay alive.
        ///
        /// <para>Measured 2026-08-23: with the default flags the clone is a plain unreferenced
        /// ScriptableObject, and Unity's EditMode test runner destroys those when a run starts. Opening the
        /// designer and then running the suite left the WINDOW up but its working copy DESTROYED — and because
        /// <c>_clonedLayoutAsset</c> is a <c>[SerializeField]</c> holding a now-fake-null, the session silently
        /// reverted to the blank picker with the user's unsaved design work gone. <c>CleanupClone</c> was never
        /// called, so nothing in the product could see it happen.</para>
        ///
        /// <para>DontSave costs nothing here: the clone still survives a domain reload through the serialized
        /// reference (verified both ways), and DontSave additionally includes DontUnloadUnusedAsset, so an
        /// <c>UnloadUnusedAssets</c> can never reclaim it either.</para>
        /// </summary>
        private void AdoptWorkingClone(InspectorLayoutAsset clone)
        {
            _clonedLayoutAsset = clone;
            if (clone != null) clone.hideFlags = HideFlags.DontSave;
        }

        private void CleanupClone()
        {
            if (_clonedLayoutAsset != null)
            {
                // Resolve BEFORE destroying — ResolveTargetType reads the clone. Preset/showcase sessions
                // never suppressed real inspectors, so they have nothing to release.
                var releasedType = (!_presetMode && string.IsNullOrEmpty(_showcaseOverrideKey)) ? ResolveTargetType() : null;

                var stale = _clonedLayoutAsset;
                _clonedLayoutAsset = null;
                ReleaseClone(stale);

                // Releasing the clone releases this window's hold on the type (IsEditingType), which
                // is what gates the removed-header scan — re-arm it now so an orphan that was blocked
                // while this window was open gets its prompt without waiting for another compile.
                // Close, switch-asset, and remove-layout all funnel through here; the scan is a
                // debounced no-op when there is nothing to show.
                OrphanedHeaderCleanup.ScheduleScan();

                // Releasing the type also lifts the inspectors' auto-sync suppression — but nothing else
                // would rebuild them until the user happens to reselect. Refresh the released type's
                // inspectors NOW so a field added to the script while this window held the type
                // auto-appends the moment the window closes / switches away, not at some later
                // incidental rebuild ("I compiled and nothing got added").
                if (releasedType != null) SasquatchEditorRegistrar.RefreshInspectorsForType(releasedType);
            }
            DestroyMockTarget();
        }

        private void DestroyMockTarget()
        {
            if (_mockTarget != null)
            {
                if (_mockTarget is MonoBehaviour mb)
                {
                    if (mb != null && mb.gameObject != null)
                    {
                        DestroyImmediate(mb.gameObject);
                    }
                }
                else
                {
                    DestroyImmediate(_mockTarget);
                }
                _mockTarget = null;
            }
            _mockSeedSource = null;
        }

        // ===== Preset Editor =====
        // A focused "preset mode" of this window: left = type-category list, center = live preview, right = the
        // SAME deep per-widget options panel the designer uses. It drives a one-binding synthetic layout against a
        // PresetSampleObject (whose real fields make field-type resolution + preview work unchanged), and syncs the
        // edited binding back into the active SasquatchLayoutPreset asset.
        [SerializeField] private bool _presetMode;
        [SerializeField] private SasquatchLayoutPreset _presetTarget;
        [SerializeField] private PresetCategory _presetCategory;
        // When true the preset editor is editing a palette-widget default (_presetWidgetKind) rather than a
        // field-type category (_presetCategory). The _preset*Expanded pair below persists the left-panel
        // foldout open-states.
        [SerializeField] private bool _presetTargetIsWidget;
        [SerializeField] private WidgetPresetKind _presetWidgetKind;
        // Which collection context of the current field-type category is being edited: null = Base (the standalone
        // template in `entries`), else the List/Table override in `contextEntries`. Not serialized — a domain reload
        // harmlessly resets to Base (the editor re-enters on retarget).
        private CollectionFieldContext? _presetContext;
        // Set while programmatically re-seeding the preview (e.g. Reset to Base) so the retarget's initial
        // SyncCurrentPreset() doesn't capture the outgoing preview back into the entry we're clearing.
        private bool _suppressPresetSync;
        [SerializeField] private bool _presetTypesExpanded = true;
        [SerializeField] private bool _presetWidgetsExpanded = true;
        private PresetSampleObject _presetSample;
        // Preset mode's own unsaved-changes flag. Deliberately NOT _isDirty: that one drives the layout-database
        // flow (auto-save, hasUnsavedChanges, the "unsaved changes on <path>" prompt LoadExplicitLayout raises on
        // every category switch), none of which applies here. Edits land in the preset ASSET immediately, so this
        // tracks the one thing left — the asset isn't on disk yet. [SerializeField] to survive a domain reload,
        // matching _isDirty.
        [SerializeField] private bool _presetDirty;
        // The live Base / In List / In Table switcher under the selected category, plus the ● marker bits it was
        // last filled with — so a capture that creates or prunes an override can re-fill it in place.
        private VisualElement _presetContextSwitcher;
        private int _presetOverrideMarkers;

        /// <summary>Opens the Layout Presets editor for <paramref name="preset"/>. Never hijacks an open Layout
        /// Designer — reuses an existing preset-mode window or creates a dedicated one.</summary>
        public static void OpenForPreset(SasquatchLayoutPreset preset)
        {
            if (preset == null) return;

            SasquatchLayoutDesignerWindow window = null;
            foreach (var w in Resources.FindObjectsOfTypeAll<SasquatchLayoutDesignerWindow>())
                if (w != null && w._presetMode) { window = w; break; }
            bool fresh = window == null;
            if (fresh) window = CreateWindow<SasquatchLayoutDesignerWindow>();

            if (!fresh) window.SyncCurrentPreset(); // flush the outgoing preset (type or widget) before retargeting

            window.titleContent = new GUIContent("Sasquatch Preset Editor");
            window.minSize = new Vector2(820, 560);
            window._presetMode = true;
            window._presetTarget = preset;
            // Save's dirty face always refers to the asset currently OPEN. _presetDirty is [SerializeField], so
            // without this a flag left over from the previous target (or from before a domain reload) shows a
            // stale "Save*" against a preset that has nothing pending. The outgoing target was just flushed above,
            // and preset edits live in their asset from the moment they're made, so nothing is lost by clearing.
            window._presetDirty = false;
            window.EnsurePresetSample();
            window.EnterPresetCategory(window.FirstEnabledCategory());
            window.UpdateSaveButtonText(); // repaint Save for the newly targeted asset

            // If a UI was already built (reused window, or CreateGUI ran before _presetMode was set), rebuild it in
            // preset mode now. Otherwise Show() triggers CreateGUI with _presetMode already true.
            if (window.rootVisualElement != null && window.rootVisualElement.childCount > 0)
            {
                window.rootVisualElement.Clear();
                window.CreateGUI();
            }

            window.Show();
            window.Focus();
        }

        // Fallback entry point into the designer (priority 1 seats it just under Welcome). Unlike the header
        // pencil, this is NOT gated on the override toggle — it must be reachable precisely when a third-party
        // asset has replaced the inspector header and suppressed the pencil / right-click paths. Opens with no
        // target: a fresh window lands in the blank state, whose centered canvas card (RefreshPreview) lets the
        // user pick any editable script. An already-open window keeps whatever it was editing.
        [MenuItem("Tools/Sasquatch Inspector/Layout Designer", false, 1)]
        private static void OpenLayoutDesignerMenu()
        {
            var window = GetWindow<SasquatchLayoutDesignerWindow>("Sasquatch Layout Designer");
            window.minSize = new Vector2(900, 600);
            window.Show();
            window.Focus();
            // Deliberately NO LoadTypeLayout here — see the note above; the blank-state picker card takes over.
        }

        [MenuItem("Tools/Sasquatch Inspector/Layout Presets", false, 11)]
        private static void OpenPresetEditorMenu() => OpenForPreset(LayoutPresetManager.EnsureActivePreset());

        private void EnsurePresetSample()
        {
            if (_presetSample != null) return;
            _presetSample = ScriptableObject.CreateInstance<PresetSampleObject>();
            _presetSample.hideFlags = HideFlags.HideAndDontSave;
            PresetSampleObject.SeedSampleValues(_presetSample);
        }

        // ---- domain-reload teardown for the preset sample ----
        // The sample is HideAndDontSave, so the NATIVE object survives a domain reload while _presetSample — a
        // plain field, deliberately not [SerializeField] because OnEnable re-mints a freshly seeded one — does
        // not. Without this sweep every recompile with the preset editor open stranded the previous sample
        // PERMANENTLY: DontSave includes DontUnloadUnusedAsset, so UnloadUnusedAssets can never reclaim it.
        // OnDestroy covers only the other exit, CLOSING the window. Windows are enumerated the same way
        // OpenForPreset finds them, so a hidden/unfocused preset window is swept too.
        [InitializeOnLoadMethod]
        private static void RegisterPresetSampleReloadTeardown()
        {
            AssemblyReloadEvents.beforeAssemblyReload += DestroyAllPresetSamples;
            EditorApplication.quitting += DestroyAllPresetSamples;
        }

        private static void DestroyAllPresetSamples()
        {
            foreach (var w in Resources.FindObjectsOfTypeAll<SasquatchLayoutDesignerWindow>())
                if (w != null) w.DestroyPresetSample();
        }

        /// <summary>Releases this window's preset sample object. Idempotent — the reload sweep and OnDestroy both
        /// call it, and clearing the field is what stops a second call from touching a destroyed object.
        /// EnsurePresetSample re-mints on demand, so releasing an in-use sample only costs a re-seed.</summary>
        internal void DestroyPresetSample()
        {
            _presetSample = ReleaseTransient(_presetSample);
        }

        /// <summary>Destroys a transient (non-asset) object and hands back null, so a caller clears its field in
        /// one move; a real project asset is handed back untouched — never ours to destroy. A null or
        /// already-destroyed input returns a clean null, which is what makes a second teardown a no-op.</summary>
        internal static T ReleaseTransient<T>(T obj) where T : UnityEngine.Object
        {
            // Cast out of the type parameter first: `obj == null` on a T binds to a REFERENCE comparison (operator
            // overloads are never considered for type parameters), which misses Unity's destroyed-object null.
            UnityEngine.Object o = obj;
            if (o == null) return null;
            if (AssetDatabase.Contains(o)) return obj;
            UnityEngine.Object.DestroyImmediate(o);
            return null;
        }

        private PresetCategory FirstEnabledCategory()
        {
            if (_presetTarget != null)
                foreach (var e in _presetTarget.Entries)
                    if (e != null && e.enabled) return e.category;
            return PresetCategory.String;
        }

        // Selects a category: persists the previous one, builds a one-binding synthetic layout for this category
        // against the sample object, and shows its options + live preview.
        private void EnterPresetCategory(PresetCategory c, CollectionFieldContext? ctx = null)
        {
            if (_presetTarget == null) return;
            // A category whose PresetSampleObject field is compiled out with its REMOVABLE built-in module (audio,
            // particle system) has no property to bind — fall back to the first enabled category rather than handing
            // the synthetic binding below a null PropertyPath. A pure no-op while every module is present: FieldFor
            // is non-null for every category then. Module-agnostic on purpose, so it needs no #if of its own.
            if (PresetSampleObject.FieldFor(c) == null)
            {
                var fallback = FirstEnabledCategory();
                if (PresetSampleObject.FieldFor(fallback) == null) return;
                c = fallback;
            }
            SyncCurrentPreset();
            _presetTargetIsWidget = false;
            _presetCategory = c;
            _presetContext = ctx;
            EnsurePresetSample();

            // Base always resolves (lazily created); a context override seeds its preview from the base template so
            // it starts identical and the user just tweaks the differences. An unedited context leaves no trace —
            // SyncCurrentCategoryToPreset prunes any override that still equals base.
            var entry = _presetTarget.Find(c);
            if (entry == null)
            {
                entry = new LayoutPresetEntry { category = c, template = LayoutPresetDefaults.BuildTemplate(c) };
                _presetTarget.Entries.Add(entry);
            }
            if (entry.template == null) entry.template = LayoutPresetDefaults.BuildTemplate(c);

            BindingNode templateSource = entry.template;
            if (ctx.HasValue)
            {
                var ctxEntry = _presetTarget.FindContext(c, ctx.Value);
                if (ctxEntry != null && ctxEntry.template != null) templateSource = ctxEntry.template;
            }

            var binding = LayoutPresetApplier.DeepClone(templateSource);
            binding.PropertyPath = PresetSampleObject.FieldFor(c);

            var root = new ContainerNode { Type = ContainerType.Rows };
            root.Children.Add(binding);

            var synthetic = ScriptableObject.CreateInstance<InspectorLayoutAsset>();
            synthetic.hideFlags = HideFlags.HideAndDontSave;
            synthetic.Root = root;

            _designMode = false; // always live preview in the preset editor
            LoadExplicitLayout(synthetic, _presetSample, typeof(PresetSampleObject));
            DestroyImmediate(synthetic); // LoadExplicitLayout cloned it; the original is no longer needed

            // Select the CLONE's binding (LoadExplicitLayout Instantiated the synthetic) so the options + preview
            // target the node that actually lives in _clonedLayoutAsset.
            var cloned = (_clonedLayoutAsset?.Root as ContainerNode)?.Children;
            if (cloned != null && cloned.Count > 0 && cloned[0] is BindingNode clonedBinding)
                SelectSingle(clonedBinding);

            RefreshTokens(); // re-render the category list (current-row highlight)
        }

        // Captures the current synthetic binding's full config back into its preset entry (base or the active
        // collection-context override).
        private void SyncCurrentCategoryToPreset()
        {
            if (!_presetMode || _presetTarget == null) return;
            if (!(_clonedLayoutAsset?.Root is ContainerNode root) || root.Children == null || root.Children.Count == 0) return;
            if (!(root.Children[0] is BindingNode binding)) return;

            var captured = LayoutPresetApplier.CaptureTemplateFrom(binding);

            if (_presetContext.HasValue)
            {
                var existing = _presetTarget.FindContext(_presetCategory, _presetContext.Value);
                if (existing == null)
                {
                    existing = new ContextPresetEntry { category = _presetCategory, context = _presetContext.Value };
                    _presetTarget.ContextEntries.Add(existing);
                }
                existing.template = captured;
            }
            else
            {
                var entry = _presetTarget.Find(_presetCategory);
                if (entry == null)
                {
                    entry = new LayoutPresetEntry { category = _presetCategory };
                    _presetTarget.Entries.Add(entry);
                }
                entry.template = captured;
            }

            PruneRedundantContextOverrides(_presetCategory);
            EditorUtility.SetDirty(_presetTarget);
        }

        /// <summary>
        /// Drops every collection-context override of <paramref name="c"/> that no longer says anything different
        /// from Base — it carries no information, so a mode flip shouldn't needlessly reskin the type and the ●
        /// indicator shouldn't claim an override exists.
        /// <para>Runs after EVERY capture, base or context, because redundancy is reached from BOTH directions:
        /// editing the override back onto Base's values, or moving BASE onto the override's values. The base
        /// direction was the gap — a capture that only touched `entries` left stale In List / In Table dots lit,
        /// and they survived until the user edited that override itself.</para>
        /// </summary>
        private void PruneRedundantContextOverrides(PresetCategory c)
        {
            var baseTemplate = _presetTarget?.Find(c)?.template;
            if (baseTemplate == null) return; // nothing to be redundant WITH — keep every override

            var list = _presetTarget.ContextEntries;
            for (int i = list.Count - 1; i >= 0; i--)
            {
                var e = list[i];
                if (e == null || e.category != c || e.template == null) continue;
                if (LayoutPresetApplier.TemplatesEqual(e.template, baseTemplate)) list.RemoveAt(i);
            }
        }

        // Flushes whichever preset target is currently open (a field-type category or a palette-widget kind) back
        // into the asset. Call this before switching targets or retargeting the window.
        private void SyncCurrentPreset()
        {
            if (_suppressPresetSync) return;
            if (_presetTargetIsWidget) SyncCurrentWidgetToPreset();
            else SyncCurrentCategoryToPreset();
            RefreshPresetContextSwitcher(); // a capture can create or prune an override → the ● follows immediately
        }

        // Selects a palette-widget kind: persists the previous target, builds a one-node synthetic layout for a
        // fresh node of this kind (stamped with the saved styling), and shows its options + live preview. Widgets
        // aren't bound, so — unlike EnterPresetCategory — there's no sample field / PropertyPath to wire.
        private void EnterWidgetPreset(WidgetPresetKind kind)
        {
            if (_presetTarget == null) return;
            SyncCurrentPreset();
            _presetTargetIsWidget = true;
            _presetContext = null; // widgets have no collection context
            _presetWidgetKind = kind;
            EnsurePresetSample();

            var entry = _presetTarget.FindWidget(kind);
            if (entry == null)
            {
                entry = new WidgetPresetEntry { kind = kind, template = WidgetPresetCatalog.MakeDefaultNode(kind) };
                _presetTarget.WidgetEntries.Add(entry);
            }
            if (entry.template == null) entry.template = WidgetPresetCatalog.MakeDefaultNode(kind);

            // A fresh default node stamped with the saved styling — the node the user edits in the preview.
            var node = WidgetPresetCatalog.MakeDefaultNode(kind);
            ApplyWidgetTemplate(entry.template, node);

            var root = new ContainerNode { Type = ContainerType.Rows };
            root.Children.Add(node);

            var synthetic = ScriptableObject.CreateInstance<InspectorLayoutAsset>();
            synthetic.hideFlags = HideFlags.HideAndDontSave;
            synthetic.Root = root;

            _designMode = false; // always live preview in the preset editor
            LoadExplicitLayout(synthetic, _presetSample, typeof(PresetSampleObject));
            DestroyImmediate(synthetic); // LoadExplicitLayout cloned it; the original is no longer needed

            // Select the CLONE's node so the options + preview target the node that lives in _clonedLayoutAsset.
            var cloned = (_clonedLayoutAsset?.Root as ContainerNode)?.Children;
            if (cloned != null && cloned.Count > 0 && cloned[0] != null)
                SelectSingle(cloned[0]);

            RefreshTokens(); // re-render the widget list (current-row highlight)
        }

        /// <summary>
        /// One funnel for "the user just changed the preset asset" — dirties the asset AND paints Save as unsaved.
        /// Every preset-mode write goes through here (widget/field option edits via <see cref="OnModification"/>,
        /// the per-row enable toggles, the Default Containers pickers, Reset to Base, undo/redo).
        /// <para>NOT called from the sync/capture methods themselves: those also run as a FLUSH when the user merely
        /// navigates to another category or widget, and a navigation must not light up the Save button.</para>
        /// </summary>
        private void MarkPresetDirty()
        {
            if (!_presetMode) return;
            if (_presetTarget != null) EditorUtility.SetDirty(_presetTarget);
            _presetDirty = true;
            UpdateSaveButtonText();
        }

        /// <summary>
        /// Stamps a stored widget-preset <paramref name="template"/>'s styling onto a fresh <paramref name="node"/> of
        /// that kind — the one path both the Preset Editor's own preview and a palette drop go through.
        /// <para>The kind's own container Type always wins over the template's. <c>ContainerTransfers</c> copies Type
        /// (correct for Copy/Paste Style, where the whole look including the kind is the point), but here the kind IS
        /// the identity of the preset row being applied: you dropped a Card. A template captured while the Preset
        /// Editor still offered a Container Type row could hold some other kind, and would silently re-type every
        /// drop — so it is re-asserted here, which also heals the stored template on the next capture.</para>
        /// </summary>
        private static void ApplyWidgetTemplate(LayoutNode template, LayoutNode node)
        {
            var kindType = (node as ContainerNode)?.Type;
            // Full scope, explicitly: a stored template is AUTHORED, so it is meant to carry the field's value
            // contract and its unit suffix as well as its look. Copy/Paste Style and the format painter ask for
            // Appearance instead — see StyleScope.
            StyleClipboard.TransferStyling(template, node, StyleScope.Full);
            if (kindType.HasValue && node is ContainerNode container) container.Type = kindType.Value;
        }

        // The preset asset is on disk again (Save, or the reset-to-defaults path, which saves for you).
        private void ClearPresetDirty()
        {
            _presetDirty = false;
            UpdateSaveButtonText();
        }

        // Captures the current synthetic widget node's STYLING back into its widget preset entry (styling only —
        // TransferStyling never copies content/identity). Mirrors SyncCurrentCategoryToPreset for widgets.
        private void SyncCurrentWidgetToPreset()
        {
            if (!_presetMode || _presetTarget == null) return;
            if (!(_clonedLayoutAsset?.Root is ContainerNode root) || root.Children == null || root.Children.Count == 0) return;
            var edited = root.Children[0];
            if (edited == null) return;

            var entry = _presetTarget.FindWidget(_presetWidgetKind);
            if (entry == null)
            {
                entry = new WidgetPresetEntry { kind = _presetWidgetKind };
                _presetTarget.WidgetEntries.Add(entry);
            }

            // Snapshot styling onto a fresh detached template of this kind so the stored template never aliases the
            // live preview node.
            var template = WidgetPresetCatalog.MakeDefaultNode(_presetWidgetKind);
            // Full scope: capture must be the mirror of ApplyWidgetTemplate's stamp, or a Preset Editor row the
            // user can see and edit would be silently discarded on save.
            StyleClipboard.TransferStyling(edited, template, StyleScope.Full);
            entry.template = template;
            EditorUtility.SetDirty(_presetTarget);
        }

        private void ResetPresetToDefaults()
        {
            if (_presetTarget == null) return;
            if (!EditorUtility.DisplayDialog("Reset Layout Presets",
                    "Reset every type category, collection override and widget style to its built-in recommended " +
                    "default? This discards your customizations.",
                    "Reset", "Cancel")) return;
            Undo.RecordObject(_presetTarget, "Reset Layout Presets");
            // Populate owns the whole reset — all four tiers, including the collection-context overrides and
            // widget styling that ship as recommended defaults. Clearing either here would delete them.
            LayoutPresetDefaults.Populate(_presetTarget);
            EditorUtility.SetDirty(_presetTarget);
            AssetDatabase.SaveAssets();
            // Re-seed the preview from the freshly reset entry, with the retarget's flush suppressed — the canvas is
            // still showing the OLD customized preview, and capturing that would write the customization straight
            // back over the category we just reset (the same trap the Reset to Base path guards against). The
            // toolbar button is live in BOTH modes, so re-enter whichever one is actually selected: bouncing a
            // widget row to a type row would leave the just-reset widget preview on screen, unreset.
            _suppressPresetSync = true;
            try
            {
                if (_presetTargetIsWidget) EnterWidgetPreset(_presetWidgetKind);
                else EnterPresetCategory(_presetCategory);
            }
            finally { _suppressPresetSync = false; }
            ClearPresetDirty(); // just written to disk
        }

        // The container types offered as structural import defaults — the kinds that read well as a section/root
        // wrapper (the others — Columns/Grid/Tabs — don't make sense for a [Header] section).
        private static readonly System.Collections.Generic.List<ContainerType> DefaultContainerChoices =
            new System.Collections.Generic.List<ContainerType> { ContainerType.Card, ContainerType.Foldout, ContainerType.Rows };

        private static string FormatDefaultContainerChoice(ContainerType t) =>
            t == ContainerType.Rows ? "Plain (Rows)" : t.ToString();

        // A small pinned panel above the category list: the structural import defaults (which container a script
        // [Header] section becomes, and the layout Root — kept separate because Root is usually wanted flat).
        private VisualElement BuildDefaultContainersPanel()
        {
            var panel = new VisualElement();
            panel.style.marginBottom = 8;
            panel.style.paddingTop = 6; panel.style.paddingBottom = 6;
            panel.style.paddingLeft = 8; panel.style.paddingRight = 8;
            panel.style.backgroundColor = TokenRowNormalBg;
            panel.style.borderTopLeftRadius = panel.style.borderTopRightRadius =
                panel.style.borderBottomLeftRadius = panel.style.borderBottomRightRadius = 4;

            var title = new Label("Default Containers");
            title.style.unityFontStyleAndWeight = FontStyle.Bold;
            title.style.color = DesignerPalette.TextPrimary;
            title.style.marginBottom = 2;
            panel.Add(title);

            var hint = new Label("Applied when a script [Header] creates a section on import. Root is separate.");
            hint.AddToClassList("sasq-palettewin-hint");
            hint.style.whiteSpace = WhiteSpace.Normal;
            hint.style.marginBottom = 4;
            panel.Add(hint);

            ContainerType headerVal = DefaultContainerChoices.Contains(_presetTarget.DefaultHeaderContainerType)
                ? _presetTarget.DefaultHeaderContainerType : ContainerType.Card;
            var headerField = new PopupField<ContainerType>("Header Sections", DefaultContainerChoices, headerVal,
                FormatDefaultContainerChoice, FormatDefaultContainerChoice);
            headerField.RegisterValueChangedCallback(evt =>
            {
                Undo.RecordObject(_presetTarget, "Set Default Header Container");
                _presetTarget.DefaultHeaderContainerType = evt.newValue;
                MarkPresetDirty();
            });
            panel.Add(headerField);

            ContainerType rootVal = DefaultContainerChoices.Contains(_presetTarget.DefaultRootContainerType)
                ? _presetTarget.DefaultRootContainerType : ContainerType.Rows;
            var rootField = new PopupField<ContainerType>("Root Container", DefaultContainerChoices, rootVal,
                FormatDefaultContainerChoice, FormatDefaultContainerChoice);
            rootField.RegisterValueChangedCallback(evt =>
            {
                Undo.RecordObject(_presetTarget, "Set Default Root Container");
                _presetTarget.DefaultRootContainerType = evt.newValue;
                MarkPresetDirty();
            });
            panel.Add(rootField);

            return panel;
        }

        // Renders the left-panel list of preset categories (one row each: enable toggle + name + [Type]).
        private void RenderPresetCategories()
        {
            if (_tokenBankContainer == null) return;
            _tokenBankContainer.Clear();
            // Any switcher from the previous pass just left the tree — drop the reference so the in-place ● refresh
            // can only ever touch the one built during THIS pass (or nothing, when the target is a widget).
            _presetContextSwitcher = null;
            if (_presetTarget == null) return;

            _tokenBankContainer.Add(BuildDefaultContainersPanel());

            // TYPES — the default widget for each field TYPE (applied when importing a script's fields).
            var typesContent = CreateToolSection("TYPES", _presetTypesExpanded, v => _presetTypesExpanded = v, 4f);
            foreach (PresetCategory c in System.Enum.GetValues(typeof(PresetCategory)))
            {
                // Skip a category whose sample field was compiled out with its built-in module (see
                // EnterPresetCategory). No-op while every module is present.
                if (PresetSampleObject.FieldFor(c) == null) continue;
                var capturedC = c;
                var entry = _presetTarget.Find(c);
                bool enabled = entry == null || entry.enabled;
                string typeTag = LayoutPresetCategories.TypeTag(c); // NOT the raw representative type — see TypeTag
                bool isCurrent = !_presetTargetIsWidget && c == _presetCategory;

                var row = new VisualElement();
                row.style.flexDirection = FlexDirection.Row;
                row.style.alignItems = Align.Center;
                row.style.paddingTop = 4;
                row.style.paddingBottom = 4;
                row.style.paddingLeft = 6;
                row.style.paddingRight = 6;
                row.style.marginBottom = 4;
                row.style.borderTopLeftRadius = 4;
                row.style.borderTopRightRadius = 4;
                row.style.borderBottomLeftRadius = 4;
                row.style.borderBottomRightRadius = 4;
                row.style.backgroundColor = isCurrent ? TokenRowSelectedBg : TokenRowNormalBg;
                row.style.opacity = enabled ? 1f : 0.5f;

                var enableToggle = new Toggle { value = enabled };
                enableToggle.tooltip = "When off, fields of this type import as the plain default field.";
                enableToggle.style.marginRight = 4;
                enableToggle.RegisterCallback<MouseDownEvent>(e => e.StopPropagation()); // don't select the row
                enableToggle.RegisterValueChangedCallback(evt =>
                {
                    var e = _presetTarget.Find(capturedC);
                    if (e == null)
                    {
                        e = new LayoutPresetEntry { category = capturedC, template = LayoutPresetDefaults.BuildTemplate(capturedC) };
                        _presetTarget.Entries.Add(e);
                    }
                    Undo.RecordObject(_presetTarget, "Toggle Preset Category");
                    e.enabled = evt.newValue;
                    MarkPresetDirty();
                    row.style.opacity = evt.newValue ? 1f : 0.5f;
                });
                row.Add(enableToggle);

                var icon = SasquatchIcons.Create(SasquatchIcons.Ids.Diamond, 12);
                icon.style.marginRight = 6;
                row.Add(icon);

                var nameLbl = new Label(LayoutPresetCategories.DisplayName(c));
                nameLbl.style.color = DesignerPalette.TextPrimary;
                nameLbl.style.flexShrink = 1;
                row.Add(nameLbl);

                if (!string.IsNullOrEmpty(typeTag))
                {
                    var typeLbl = new Label($"[{typeTag}]");
                    typeLbl.style.fontSize = 10f;
                    typeLbl.style.color = DesignerPalette.TypeAccent;
                    StyleTypeTagRowLabels(nameLbl, typeLbl); // squish rules, shared with the Bindings token rows
                    row.Add(typeLbl);
                }
                else
                {
                    nameLbl.style.flexGrow = 1;
                }

                row.RegisterCallback<MouseDownEvent>(evt =>
                {
                    if (evt.button != 0) return;
                    EnterPresetCategory(capturedC);
                    evt.StopPropagation();
                });
                row.RegisterCallback<MouseEnterEvent>(_ => { if (_presetTargetIsWidget || capturedC != _presetCategory) row.style.backgroundColor = TokenRowHoverBg; });
                row.RegisterCallback<MouseLeaveEvent>(_ => { if (_presetTargetIsWidget || capturedC != _presetCategory) row.style.backgroundColor = TokenRowNormalBg; });
                EditorSpringFX.HoverScale(row, 1.03f, EditorSpringFX.HoverLiftConfig);

                typesContent.Add(row);
                // Under the selected category: the Base / In List / In Table collection-context switcher.
                if (isCurrent) typesContent.Add(BuildPresetContextSwitcher(capturedC));
            }

            // WIDGETS — the default STYLING for each palette widget (applied when the widget is dropped onto a
            // canvas). Styling only; content/identity is never captured. Lazily-created entries mean drops behave
            // exactly as before until a widget is customized here.
            var widgetsContent = CreateToolSection("WIDGETS", _presetWidgetsExpanded, v => _presetWidgetsExpanded = v, 10f);
            foreach (var w in WidgetPresetCatalog.All)
            {
                var kind = w.Kind;
                var wEntry = _presetTarget.FindWidget(kind);
                bool wEnabled = wEntry == null || wEntry.enabled;
                bool wIsCurrent = _presetTargetIsWidget && kind == _presetWidgetKind;
                widgetsContent.Add(BuildWidgetPresetRow(w, wEnabled, wIsCurrent, kind));
            }
        }

        // The Base / In List / In Table switcher shown under the selected TYPES category. Base edits the standalone
        // template (the `entries` row); In List / In Table edit a collection-context override (seeded from Base and
        // auto-pruned when the user leaves it equal to Base). A ● marks a context that currently overrides Base.
        private VisualElement BuildPresetContextSwitcher(PresetCategory c)
        {
            var panel = new VisualElement();
            panel.style.flexDirection = FlexDirection.Column;
            panel.style.marginLeft = 20;
            panel.style.marginBottom = 6;
            _presetContextSwitcher = panel; // the live one — RefreshPresetContextSwitcher re-fills it in place
            FillPresetContextSwitcher(panel, c);
            return panel;
        }

        /// <summary>True when this category currently carries a real override for <paramref name="ctx"/> — the
        /// single definition of "wears a ●", shared by the chip and the refresh check.</summary>
        private bool HasContextOverride(PresetCategory c, CollectionFieldContext ctx) =>
            _presetTarget != null
            && _presetTarget.FindContext(c, ctx) is ContextPresetEntry e && e.enabled && e.template != null;

        // One bit per collection context: does an override exist right now? Cheap to recompute after every capture.
        private int PresetOverrideMarkers(PresetCategory c)
        {
            int bits = 0;
            if (HasContextOverride(c, CollectionFieldContext.InList)) bits |= 1;
            if (HasContextOverride(c, CollectionFieldContext.InTable)) bits |= 2;
            return bits;
        }

        /// <summary>
        /// The ● markers and the "Reset to Base" link are DERIVED from the asset, and a capture can create or prune
        /// an override — so re-fill the switcher whenever the marker set actually moves. Without this the dots only
        /// caught up on the next full left-panel render, i.e. when the user clicked away to another chip or row.
        /// Gated on an actual change so a slider drag (which captures per tick) can't rebuild the chips under the
        /// pointer every frame.
        /// </summary>
        private void RefreshPresetContextSwitcher()
        {
            if (!_presetMode || _presetTargetIsWidget) return;
            var panel = _presetContextSwitcher;
            if (panel == null) return; // no switcher in the current render (widget target, or none built yet)
            if (PresetOverrideMarkers(_presetCategory) == _presetOverrideMarkers) return;
            FillPresetContextSwitcher(panel, _presetCategory);
        }

        private void FillPresetContextSwitcher(VisualElement panel, PresetCategory c)
        {
            panel.Clear();
            _presetOverrideMarkers = PresetOverrideMarkers(c);

            var chips = new VisualElement();
            chips.style.flexDirection = FlexDirection.Row;
            chips.style.alignItems = Align.Center;
            chips.Add(BuildContextChip(c, null, "Base"));
            chips.Add(BuildContextChip(c, CollectionFieldContext.InList, "In List"));
            chips.Add(BuildContextChip(c, CollectionFieldContext.InTable, "In Table"));
            panel.Add(chips);

            // A "reset to Base" affordance for the active override (removes it → inherit Base in this context).
            if (_presetContext.HasValue && HasContextOverride(c, _presetContext.Value))
            {
                var ctx = _presetContext.Value;
                var reset = new Label("↺ Reset to Base");
                reset.tooltip = $"Remove this override so {LayoutPresetCategories.DisplayName(c)} fields inherit the Base preset inside a {(ctx == CollectionFieldContext.InTable ? "Table" : "List")}.";
                reset.style.fontSize = 10;
                reset.style.marginTop = 3;
                reset.style.color = DesignerPalette.TypeAccent;
                reset.RegisterCallback<MouseDownEvent>(evt =>
                {
                    if (evt.button != 0) return;
                    Undo.RecordObject(_presetTarget, "Reset Context Preset");
                    var e = _presetTarget.FindContext(c, ctx);
                    if (e != null) _presetTarget.ContextEntries.Remove(e);
                    MarkPresetDirty();
                    // Re-seed the preview from Base (entry now gone). Suppress the retarget's initial sync so it
                    // doesn't re-capture the still-showing override back into the entry we just removed.
                    _suppressPresetSync = true;
                    try { EnterPresetCategory(c, ctx); } finally { _suppressPresetSync = false; }
                    evt.StopPropagation();
                });
                panel.Add(reset);
            }
        }

        // One context chip. null ctx = Base; a value = that List/Table override. Click enters it for editing.
        private VisualElement BuildContextChip(PresetCategory c, CollectionFieldContext? ctx, string label)
        {
            bool active = !_presetTargetIsWidget && _presetContext == ctx;
            bool hasOverride = ctx.HasValue && HasContextOverride(c, ctx.Value);

            var chip = new Label(hasOverride ? label + "  ●" : label);
            chip.tooltip = ctx.HasValue
                ? $"How {LayoutPresetCategories.DisplayName(c)} fields look inside a {(ctx.Value == CollectionFieldContext.InTable ? "Table" : "List")} collection."
                : "The default look everywhere — and the fallback when a collection context has no override.";
            chip.style.fontSize = 10;
            chip.style.paddingLeft = 7;
            chip.style.paddingRight = 7;
            chip.style.paddingTop = 2;
            chip.style.paddingBottom = 2;
            chip.style.marginRight = 4;
            chip.style.borderTopLeftRadius = 3;
            chip.style.borderTopRightRadius = 3;
            chip.style.borderBottomLeftRadius = 3;
            chip.style.borderBottomRightRadius = 3;
            chip.style.backgroundColor = active ? TokenRowSelectedBg : TokenRowNormalBg;
            chip.style.color = DesignerPalette.TextPrimary;
            chip.RegisterCallback<MouseDownEvent>(evt =>
            {
                if (evt.button != 0) return;
                EnterPresetCategory(c, ctx);
                evt.StopPropagation();
            });
            chip.RegisterCallback<MouseEnterEvent>(_ => { if (!active) chip.style.backgroundColor = TokenRowHoverBg; });
            chip.RegisterCallback<MouseLeaveEvent>(_ => { if (!active) chip.style.backgroundColor = TokenRowNormalBg; });
            return chip;
        }

        // One WIDGETS-section row (enable toggle + palette icon + name), mirroring the TYPES category row. Click
        // enters the widget's styling editor; the toggle gates whether the saved styling is applied on drop.
        private VisualElement BuildWidgetPresetRow(WidgetPresetCatalog.Entry w, bool enabled, bool isCurrent, WidgetPresetKind kind)
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.paddingTop = 4;
            row.style.paddingBottom = 4;
            row.style.paddingLeft = 6;
            row.style.paddingRight = 6;
            row.style.marginBottom = 4;
            row.style.borderTopLeftRadius = 4;
            row.style.borderTopRightRadius = 4;
            row.style.borderBottomLeftRadius = 4;
            row.style.borderBottomRightRadius = 4;
            row.style.backgroundColor = isCurrent ? TokenRowSelectedBg : TokenRowNormalBg;
            row.style.opacity = enabled ? 1f : 0.5f;

            var enableToggle = new Toggle { value = enabled };
            enableToggle.tooltip = "When off, this widget drops at its plain built-in default (ignores your saved styling).";
            enableToggle.style.marginRight = 4;
            enableToggle.RegisterCallback<MouseDownEvent>(e => e.StopPropagation()); // don't select the row
            enableToggle.RegisterValueChangedCallback(evt =>
            {
                var e = _presetTarget.FindWidget(kind);
                if (e == null)
                {
                    e = new WidgetPresetEntry { kind = kind, template = WidgetPresetCatalog.MakeDefaultNode(kind) };
                    _presetTarget.WidgetEntries.Add(e);
                }
                Undo.RecordObject(_presetTarget, "Toggle Widget Preset");
                e.enabled = evt.newValue;
                MarkPresetDirty();
                row.style.opacity = evt.newValue ? 1f : 0.5f;
            });
            row.Add(enableToggle);

            var icon = SasquatchIcons.Create(w.IconId, 12);
            icon.style.marginRight = 6;
            row.Add(icon);

            var nameLbl = new Label(w.DisplayName);
            nameLbl.style.color = DesignerPalette.TextPrimary;
            nameLbl.style.flexGrow = 1;
            nameLbl.style.flexShrink = 1;
            nameLbl.style.minWidth = 0; // clip, don't spill: a narrowed panel must ellipsize the name (see TYPES rows)
            nameLbl.style.whiteSpace = WhiteSpace.NoWrap;
            nameLbl.style.overflow = Overflow.Hidden;
            nameLbl.style.textOverflow = TextOverflow.Ellipsis;
            row.Add(nameLbl);

            row.RegisterCallback<MouseDownEvent>(evt =>
            {
                if (evt.button != 0) return;
                EnterWidgetPreset(kind);
                evt.StopPropagation();
            });
            row.RegisterCallback<MouseEnterEvent>(_ => { if (!(_presetTargetIsWidget && kind == _presetWidgetKind)) row.style.backgroundColor = TokenRowHoverBg; });
            row.RegisterCallback<MouseLeaveEvent>(_ => { if (!(_presetTargetIsWidget && kind == _presetWidgetKind)) row.style.backgroundColor = TokenRowNormalBg; });
            EditorSpringFX.HoverScale(row, 1.03f, EditorSpringFX.HoverLiftConfig);

            return row;
        }

        private void CreateGUI()
        {
            // Message shown in Unity's native "save before closing?" dialog (driven by hasUnsavedChanges).
            saveChangesMessage = "You have unsaved layout changes. Save them to the inspector database?";

            if (_clonedLayoutAsset != null && _selectedNode == null)
            {
                if (_selectedNodeIndexPath != null && _selectedNodeIndexPath.Count > 0)
                {
                    _selectedNode = LocateNodeByIndexPath(_selectedNodeIndexPath, _clonedLayoutAsset.Root);
                }
                if (_selectedNode == null)
                {
                    _selectedNode = _clonedLayoutAsset.Root;
                }
            }

            // Root panel style
            rootVisualElement.style.flexDirection = FlexDirection.Column;
            rootVisualElement.style.backgroundColor = DesignerPalette.WindowBg;

            // 1. TOP TOOLBAR
            var toolbar = new VisualElement();
            toolbar.style.flexDirection = FlexDirection.Row;
            toolbar.style.alignItems = Align.Center;
            toolbar.style.paddingTop = 6;
            toolbar.style.paddingBottom = 6;
            toolbar.style.paddingLeft = 10;
            toolbar.style.paddingRight = 10;
            toolbar.style.backgroundColor = DesignerPalette.ToolbarBg;
            toolbar.style.borderBottomWidth = 1;
            toolbar.style.borderBottomColor = DesignerPalette.ToolbarBorder;

            // The designer follows the selected object automatically (see OnSelectionChanged) and the layout is
            // keyed by type in the central database, so the top bar carries no target/asset fields — just Save +
            // Auto-Save plus the view controls.
            // Save button and Auto-Save toggle share an explicit 22px height and zeroed vertical margins so the
            // toolbar's center alignment lines them up on the same centerline (a default Button and a Toggle
            // otherwise have different intrinsic box heights, which read as "the label sits low").
            // Text derived, not hardcoded: _isDirty/_presetDirty are [SerializeField] and survive a domain reload,
            // so a rebuilt toolbar must come back already saying "Save*" — the face is painted from the flag
            // either way, and a hardcoded label would read as an orange button labelled "Save".
            _saveButton = new Button(SaveActiveAsset) { text = IsSaveDirty ? "Save*" : "Save" };
            _saveButton.style.height = 22;
            _saveButton.style.marginTop = 0;
            _saveButton.style.marginBottom = 0;
            _saveButton.style.unityTextAlign = TextAnchor.MiddleCenter;
            _saveButton.style.paddingLeft = 12;
            _saveButton.style.paddingRight = 12;
            _saveButton.style.marginRight = 8;
            toolbar.Add(_saveButton);
            EditorSpringFX.ButtonSpring(_saveButton);
            // Fill AND label come from the one paint funnel — Save wears two faces (emerald at rest, burnt
            // orange when dirty) and the label is derived from whichever is painted. UpdateSaveButtonText
            // routes through the same funnel, so a dirty flip under the cursor keeps the hover tint.
            PaintSaveButtonFace();
            AddChromeHoverRepaint(_saveButton, PaintSaveButtonFace);

            // Format painter (paint roller): click = copy the selected node's style and paint it
            // onto the next node clicked; double-click = keep painting; Esc cancels.
            toolbar.Add(BuildStylePainterButton());

            _autoSaveToggle = new Toggle("Auto-Save");
            _autoSaveToggle.value = _autoSave;
            _autoSaveToggle.AddToClassList("sq-toggle");
            _autoSaveToggle.AddToClassList("sq-toggle--rounded");
            EditorSpringFX.SpringToggleKnob(_autoSaveToggle);   // same thrown knob the Toggle widget uses
            _autoSaveToggle.style.height = 22;
            _autoSaveToggle.style.marginTop = 0;
            _autoSaveToggle.style.marginBottom = 0;
            _autoSaveToggle.style.alignItems = Align.Center;
            if (_autoSaveToggle.labelElement != null)
            {
                _autoSaveToggle.labelElement.style.fontSize = 10;
                _autoSaveToggle.labelElement.style.color = DesignerPalette.TextHeader;
                _autoSaveToggle.labelElement.style.marginRight = 4;
                _autoSaveToggle.labelElement.style.minWidth = 0;
                _autoSaveToggle.labelElement.style.alignSelf = Align.Center;
                _autoSaveToggle.labelElement.style.unityTextAlign = TextAnchor.MiddleLeft;
            }
            _autoSaveToggle.RegisterValueChangedCallback(evt =>
            {
                _autoSave = evt.newValue;
                if (_autoSave)
                {
                    SaveActiveAsset();
                }
                else
                {
                    // Turning Auto-Save OFF has to BREAK the alias turning it on established. There used to
                    // be no else-branch at all, so it never did.
                    ReclaimCloneFromPersistedLayout();
                }
            });
            toolbar.Add(_autoSaveToggle);

            // Edited-type breadcrumb. At depth 0 it is a single "Type: X ▾" crumb — it shows the targeted type
            // and climbs the ancestor chain to author a BASE class's layout instead (the entry point for
            // inheritable layouts, including abstract bases that have no instances to open the designer from).
            // Once you drill into an In-Line Editor's script it grows the trail back to where you started;
            // see SasquatchLayoutDesignerWindow.Navigation.cs.
            toolbar.Add(BuildBreadcrumbBar());
            UpdateTypeSwitcherButton();

            // Flexible spacer (left) — centers the column-visibility box in the toolbar.
            var toolbarSpacerL = new VisualElement();
            toolbarSpacerL.style.flexGrow = 1;
            toolbar.Add(toolbarSpacerL);

            // --- Column visibility: a small bordered box with 3 icons (left / center / right).
            // Click an icon to show/hide that column; a hidden column's button looks pushed-in.
            var columnBox = new VisualElement();
            columnBox.style.flexDirection = FlexDirection.Row;
            columnBox.style.alignItems = Align.Center;
            columnBox.style.borderTopWidth = 1;
            columnBox.style.borderBottomWidth = 1;
            columnBox.style.borderLeftWidth = 1;
            columnBox.style.borderRightWidth = 1;
            var boxBorder = DesignerPalette.BoxBorder;
            columnBox.style.borderTopColor = boxBorder;
            columnBox.style.borderBottomColor = boxBorder;
            columnBox.style.borderLeftColor = boxBorder;
            columnBox.style.borderRightColor = boxBorder;
            columnBox.style.borderTopLeftRadius = 4;
            columnBox.style.borderTopRightRadius = 4;
            columnBox.style.borderBottomLeftRadius = 4;
            columnBox.style.borderBottomRightRadius = 4;
            columnBox.style.paddingLeft = 3;
            columnBox.style.paddingRight = 3;
            columnBox.style.paddingTop = 2;
            columnBox.style.paddingBottom = 2;

            for (int i = 0; i < 3; i++)
            {
                var btn = MakeColumnToggle(i);
                _columnButtons[i] = btn;
                columnBox.Add(btn);
            }
            toolbar.Add(columnBox);

            // Flexible spacer (right) — balances the left spacer so the column box stays centered.
            var toolbarSpacerR = new VisualElement();
            toolbarSpacerR.style.flexGrow = 1;
            toolbar.Add(toolbarSpacerR);

            // "Hide in Inspector" eye (top-right, just left of Export): switches THIS type's layout off in the REAL
            // inspector without deleting or altering it, so the type shows what it would show without Sasquatch
            // Inspector — its own [CustomEditor] when it has one (displacement simply releases the row), otherwise
            // Unity's default inspector. Built for before/after screenshots and comparisons, and doubles as a
            // non-destructive way to park a layout you're unsure about.
            //
            // It sits with Export/Revert rather than in the canvas header because those three are the "what happens
            // to this layout OUTSIDE the designer" run — the canvas header's controls all act on the canvas itself.
            //
            // Writes STRAIGHT THROUGH to the saved asset (LayoutRegistry.SetLayoutHidden), never the designer's
            // working clone: the whole point is that the inspector you're looking at changes on the click, with no
            // Save round-trip — and the flag is display state, not layout data, so a later Save must not carry it
            // (LayoutRegistry.Save leaves it alone, exactly as it does ForceTakeover).
            _hideLayoutIconRef = SasquatchIcons.Create(SasquatchIcons.Ids.Eye, 14, DesignerPalette.IconMuted);
            _hideLayoutBtnRef = new Button();
            _hideLayoutBtnRef.Add(_hideLayoutIconRef);
            _hideLayoutBtnRef.style.height = 22;   // the toolbar's icon-button rhythm (see BuildStylePainterButton)
            _hideLayoutBtnRef.style.width = 26;
            _hideLayoutBtnRef.style.marginTop = 0;
            _hideLayoutBtnRef.style.marginBottom = 0;
            _hideLayoutBtnRef.style.marginLeft = 8;
            _hideLayoutBtnRef.style.paddingLeft = 0;
            _hideLayoutBtnRef.style.paddingRight = 0;
            _hideLayoutBtnRef.style.alignItems = Align.Center;
            _hideLayoutBtnRef.style.justifyContent = Justify.Center;
            _hideLayoutBtnRef.clicked += () =>
            {
                var hideType = ResolveTargetType();
                if (hideType == null) return;
                LayoutRegistry.SetLayoutHidden(hideType, !LayoutRegistry.IsLayoutHiddenOwn(hideType));
                EditorSpringFX.LandPunch(_hideLayoutBtnRef, 0.35f);
                SyncHideLayoutButton();
            };
            // The hover MARKER route, not a pair of tint callbacks: SyncHideLayoutButton is this button's only
            // painter and it honours the marker class, so the repaint that follows the click — fired while the
            // cursor is still sitting on the button — comes back wearing the hover look instead of wiping it.
            // That is the exact bug the ChromeHover convention exists for; see AddChromeHoverRepaint.
            AddChromeHoverRepaint(_hideLayoutBtnRef, SyncHideLayoutButton);
            EditorSpringFX.ButtonSpring(_hideLayoutBtnRef);
            toolbar.Add(_hideLayoutBtnRef);
            SyncHideLayoutButton();

            // Export Standalone Editor (top-right, just left of Revert): writes a self-contained [CustomEditor]
            // script that reproduces this layout with no dependency on Sasquatch Inspector — for handing off to
            // teammates who don't own the package. Neutral chrome (it isn't destructive like Revert).
            _exportButton = new Button(ExportStandaloneEditor) { text = "Export Editor" };
            _exportButton.style.paddingLeft = 10;
            _exportButton.style.paddingRight = 10;
            _exportButton.style.marginLeft = 8;
            _exportButton.tooltip = "Export this layout as a standalone [CustomEditor] script that works without " +
                "Sasquatch Inspector — hand it (plus your script) to teammates who don't own the package.";
            toolbar.Add(_exportButton);
            EditorSpringFX.ButtonSpring(_exportButton);

            // Revert-to-Default (top-right): removes this type's layout so the inspector falls back to
            // Unity's stock inspector. Red to signal it's destructive; confirmed via dialog.
            _revertButton = new Button(RevertToDefault) { text = "Revert to Default" };
            _revertButton.style.paddingLeft = 10;
            _revertButton.style.paddingRight = 10;
            _revertButton.style.marginLeft = 8;
            _revertButton.tooltip = "Remove this type's Sasquatch layout. Its inspector reverts to Unity's default.";
            toolbar.Add(_revertButton);
            StyleGhostDangerButton(_revertButton);

            // Preset editor: repurpose the toolbar — title on the left, hide database/canvas controls, and a red
            // "Reset to Recommended Defaults" on the right. Save still flushes the asset (SaveActiveAsset branches).
            if (_presetMode)
            {
                _autoSaveToggle.style.display = DisplayStyle.None;
                _revertButton.style.display = DisplayStyle.None;
                _exportButton.style.display = DisplayStyle.None;
                _hideLayoutBtnRef.style.display = DisplayStyle.None; // no target type in preset mode (SyncHideLayoutButton agrees)
                columnBox.style.display = DisplayStyle.None;
                _saveButton.tooltip = "Save the preset asset.";

                var presetTitle = new Label("Layout Presets");
                presetTitle.style.unityFontStyleAndWeight = FontStyle.Bold;
                presetTitle.style.fontSize = 13;
                presetTitle.style.color = DesignerPalette.TextPrimary;
                presetTitle.style.marginRight = 12;
                toolbar.Insert(0, presetTitle);

                var resetBtn = new Button(ResetPresetToDefaults) { text = "Reset to Recommended Defaults" };
                resetBtn.style.paddingLeft = 10;
                resetBtn.style.paddingRight = 10;
                resetBtn.style.marginLeft = 8;
                resetBtn.tooltip = "Reset every type category, collection override and widget style to its " +
                                   "built-in recommended default.";
                toolbar.Add(resetBtn);
                StyleGhostDangerButton(resetBtn); // Revert's preset-mode twin — same ghost treatment
            }

            rootVisualElement.Add(toolbar);

            // Escape cancels an in-progress drag. OnGUI catches this when nothing is focused (e.g.
            // hierarchy drags), but a canvas drag often leaves a field focused, so UI Toolkit dispatches
            // the key to that field and OnGUI never sees it. This capture-phase root handler catches it
            // before any focused child can swallow it, covering canvas drags too.
            // Held in a field and explicitly unregistered first. CreateGUI is re-run on the SAME root when
            // the Preset Editor retargets a reused window (OpenForPreset does Clear() + CreateGUI()), and
            // rootVisualElement.Clear() removes CHILDREN — it does not touch callbacks registered on the
            // root itself. UI Toolkit does de-duplicate an identical (delegate, event, phase) triple, which
            // is why this never actually double-fired, but that is a recalled semantic rather than a
            // guarantee this package should lean on. Unregistering makes the re-run correct by construction.
            if (_rootKeyDownHandler != null) rootVisualElement.UnregisterCallback(_rootKeyDownHandler, TrickleDown.TrickleDown);
            _rootKeyDownHandler = evt =>
            {
                // Esc disarms the format painter before anything else (it's the top "mode").
                if (HandleStylePainterKeyDown(evt))
                {
                    evt.StopPropagation();
                    return;
                }
                if (evt.keyCode == KeyCode.Escape && _canvasDragController != null && _canvasDragController.IsDragging)
                {
                    _canvasDragController.CancelDrag();
                    evt.StopPropagation();
                }
                // F2 renames the selected container's hierarchy row (cosmetic name only). Capture
                // phase, so the guard matters: never hijack F2 while the user is typing in any text
                // input (including the rename field itself).
                if (evt.keyCode == KeyCode.F2 && _selectedNode is ContainerNode && !IsTypingInTextField())
                {
                    BeginHierarchyRename(_selectedNode);
                    evt.StopPropagation();
                }
                // Delete removes the selection. This UITK route is the one that fires when focus
                // sits on a canvas element (a card inside a Foldout focuses the Foldout's toggle,
                // which swallows the key before OnGUI); the OnGUI route covers the nothing-focused
                // case. Both share TryHandleDeleteShortcut, which guards text editing itself.
                if (evt.keyCode == KeyCode.Delete && TryHandleDeleteShortcut())
                {
                    evt.StopPropagation();
                }
                // Ctrl/Cmd+D duplicates the selection — same dual-route reasoning as Delete above, and the
                // same text-field guard inside. Consuming it here also keeps Unity's Edit ▸ Duplicate (bound
                // to the same chord, acting on the project Selection) from firing behind the designer's back.
                if (evt.keyCode == KeyCode.D && evt.actionKey && TryHandleDuplicateShortcut())
                {
                    evt.StopPropagation();
                }
                // Alt+← walks the drill-in trail back — same dual-route reasoning as Delete above.
                if (evt.keyCode == KeyCode.LeftArrow && evt.altKey && TryHandleNavBackShortcut())
                {
                    evt.StopPropagation();
                }
                // Arrow keys walk the hierarchy. This UITK route covers the focused-element case; the OnGUI
                // route covers the (far more common) nothing-focused one. HierarchyOwnsArrowKeys is what
                // stops this capture-phase handler from stealing arrows out of a field being edited.
                if (TryHandleHierarchyArrowKey(evt.keyCode, evt.altKey))
                {
                    evt.StopPropagation();
                }
            };
            rootVisualElement.RegisterCallback(_rootKeyDownHandler, TrickleDown.TrickleDown);

            // 2. MAIN WORKSPACE ROW
            _outerSplit = new TwoPaneSplitView(0, 300, TwoPaneSplitViewOrientation.Horizontal);
            _outerSplit.style.flexGrow = 1;

            _innerSplit = new TwoPaneSplitView(0, 500, TwoPaneSplitViewOrientation.Horizontal);
            _innerSplit.style.flexGrow = 1;

            // Column 1: Left Panel (Hierarchy + Token Bank)
            _leftPanel = new VisualElement();
            _leftPanel.style.backgroundColor = DesignerPalette.PanelBg;
            _leftPanel.style.flexDirection = FlexDirection.Column;

            var leftSplit = new TwoPaneSplitView(0, 300, TwoPaneSplitViewOrientation.Vertical);
            leftSplit.style.flexGrow = 1;

            // Column 1a: Hierarchy Tree
            var hierarchyPanel = new VisualElement();
            hierarchyPanel.style.flexDirection = FlexDirection.Column;

            var hierarchyHeaderRow = new VisualElement();
            hierarchyHeaderRow.style.flexDirection = FlexDirection.Row;
            hierarchyHeaderRow.style.alignItems = Align.Center;
            hierarchyHeaderRow.style.height = 32;
            hierarchyHeaderRow.style.borderBottomWidth = 1;
            hierarchyHeaderRow.style.borderBottomColor = DesignerPalette.DividerLine;
            hierarchyHeaderRow.style.backgroundColor = DesignerPalette.PaneHeaderBg;

            // "Hierarchy" title + its inline search (magnifier hugging the title, then the field and a compact
            // count). Built once here and persists across RefreshHierarchy rebuilds; see
            // SasquatchLayoutDesignerWindow.HierarchySearch.cs.
            BuildHierarchySearchHeader(hierarchyHeaderRow);

            var gearBtn = new Button(() =>
            {
                var menu = new GenericMenu();
                menu.AddItem(new GUIContent("Show Hierarchy Lines"), _showHierarchyLines, () =>
                {
                    _showHierarchyLines = !_showHierarchyLines;
                    RefreshHierarchy();
                });
                menu.AddItem(new GUIContent("Show Ordering Arrows"), _showHierarchyArrows, () =>
                {
                    _showHierarchyArrows = !_showHierarchyArrows;
                    RefreshHierarchy();
                });
                menu.AddItem(new GUIContent("Show Delete Buttons"), _showDeleteButtons, () =>
                {
                    _showDeleteButtons = !_showDeleteButtons;
                    RefreshHierarchy();
                });
                menu.AddItem(new GUIContent("Show Binding Types"), _showBindingTypes, () =>
                {
                    _showBindingTypes = !_showBindingTypes;
                    RefreshTokens();
                });
                menu.AddSeparator("");
                menu.AddItem(new GUIContent("Disable Duplicate Bindings"), _preventDuplicateBindings, () =>
                {
                    _preventDuplicateBindings = !_preventDuplicateBindings;
                    // Re-render so already-bound tokens lock (or unlock) their drag handles to match.
                    RefreshTokens();
                });
                menu.AddSeparator("");
                menu.AddItem(new GUIContent("Show Add Container Button"), _showAddContainerBtn, () =>
                {
                    _showAddContainerBtn = !_showAddContainerBtn;
                    RefreshHierarchy();
                });
                menu.AddItem(new GUIContent("Show Add Child Binding Button"), _showAddChildBindingBtn, () =>
                {
                    _showAddChildBindingBtn = !_showAddChildBindingBtn;
                    RefreshHierarchy();
                });
                menu.AddItem(new GUIContent("Show Add Child Collection/List Button"), _showAddChildCollectionBtn, () =>
                {
                    _showAddChildCollectionBtn = !_showAddChildCollectionBtn;
                    RefreshHierarchy();
                });
                // Deliberately no motion toggle here: "Enable Motion (Spring Animations)" lives in Project
                // Settings → Sasquatch Inspector (per-user, EditorPrefs-backed, on by default), and the
                // Spring Physics Sandbox is where the motion itself can be felt.
                menu.ShowAsContext();
            });
            var gearIcon = SasquatchIcons.Create(SasquatchIcons.Ids.Settings, 14, DesignerPalette.IconMuted);
            gearBtn.Add(gearIcon);
            gearBtn.style.alignItems = Align.Center;
            gearBtn.style.justifyContent = Justify.Center;
            gearBtn.style.width = 18;
            gearBtn.style.height = 18;
            gearBtn.style.marginRight = 6;
            gearBtn.style.paddingTop = 0;
            gearBtn.style.paddingBottom = 0;
            gearBtn.style.paddingLeft = 0;
            gearBtn.style.paddingRight = 0;
            gearBtn.style.backgroundColor = new Color(0f, 0f, 0f, 0f);
            gearBtn.style.borderTopWidth = 0;
            gearBtn.style.borderBottomWidth = 0;
            gearBtn.style.borderLeftWidth = 0;
            gearBtn.style.borderRightWidth = 0;
            gearBtn.RegisterCallback<MouseOverEvent>(evt =>
            {
                gearIcon.Tint = DesignerPalette.IconStrong;
            });
            gearBtn.RegisterCallback<MouseOutEvent>(evt =>
            {
                gearIcon.Tint = DesignerPalette.IconMuted;
            });
            var addRootContainerBtn = new Button(() =>
            {
                if (_clonedLayoutAsset != null && _clonedLayoutAsset.Root != null)
                {
                    _scrollToBottomOnHierarchyRefresh = true;
                    AddChildNode(_clonedLayoutAsset.Root as ContainerNode, 0);
                }
            });
            addRootContainerBtn.tooltip = "Add Container to Root";
            var addContainerIcon = SasquatchIcons.Create(SasquatchIcons.Ids.FolderPlus, 14, DesignerPalette.IconMuted);
            addRootContainerBtn.Add(addContainerIcon);
            addRootContainerBtn.style.alignItems = Align.Center;
            addRootContainerBtn.style.justifyContent = Justify.Center;
            addRootContainerBtn.style.width = 18;
            addRootContainerBtn.style.height = 18;
            addRootContainerBtn.style.marginRight = 6;
            addRootContainerBtn.style.paddingTop = 0;
            addRootContainerBtn.style.paddingBottom = 0;
            addRootContainerBtn.style.paddingLeft = 0;
            addRootContainerBtn.style.paddingRight = 0;
            addRootContainerBtn.style.backgroundColor = Color.clear;
            addRootContainerBtn.style.borderTopWidth = 0;
            addRootContainerBtn.style.borderBottomWidth = 0;
            addRootContainerBtn.style.borderLeftWidth = 0;
            addRootContainerBtn.style.borderRightWidth = 0;
            addRootContainerBtn.RegisterCallback<MouseOverEvent>(evt =>
            {
                addContainerIcon.Tint = DesignerPalette.IconStrong;
            });
            addRootContainerBtn.RegisterCallback<MouseOutEvent>(evt =>
            {
                addContainerIcon.Tint = DesignerPalette.IconMuted;
            });
            // Flexible spacer — inside the search's middle region, so the search bar (an absolute overlay on
            // that region) covers this whole run, both header buttons included, without displacing anything.
            var hierHeaderSpacer = new VisualElement();
            hierHeaderSpacer.style.flexGrow = 1;
            _hierHeaderMiddle.Add(hierHeaderSpacer);

            _hierHeaderMiddle.Add(addRootContainerBtn);
            _hierHeaderMiddle.Add(gearBtn);

            AddColumnContextMenu(hierarchyHeaderRow, 0);
            hierarchyPanel.Add(hierarchyHeaderRow);

            _hierarchyContainer = new ScrollView();
            _hierarchyContainer.style.flexGrow = 1;
            _hierarchyContainer.style.paddingTop = 5;
            _hierarchyContainer.style.paddingLeft = 5;
            _hierarchyContainer.style.paddingRight = 5;
            hierarchyPanel.Add(_hierarchyContainer);

            // Click on empty hierarchy space deselects (rows handle their own clicks and stop here).
            _hierarchyContainer.RegisterCallback<MouseDownEvent>(evt =>
            {
                if (evt.button != 0) return;
                if (!ResolvesToLayoutNode(evt.target as VisualElement))
                {
                    SelectSingle(null);
                }
            });

            // Column 1b: Token Bank / Widgets Panel
            var tokenBankPanel = new VisualElement();
            tokenBankPanel.style.flexDirection = FlexDirection.Column;

            // ---- Left tab bar: three FOLDER tabs seated in a recessed track ---------------------------
            // The active tab is painted PanelBg — the SAME colour as the panel below it — with rounded TOP
            // corners and a 1px negative bottom margin, so it overhangs the bar's divider and that hairline
            // visibly stops at its edges. The tab is not a button pointing AT the panel; it IS the top of
            // the panel. Its 2px top border is the only saturated pixel in the bar.
            //
            // Why the accent cap is a top BORDER and not a child strip: Yoga only runs a measure function on
            // LEAF nodes, so giving a Button ANY child kills its text self-sizing (a 22px stepper button once
            // measured 22x4 that way). A border respects the corner radius natively and needs no child — the
            // same reason the unbound count below rides as rich text rather than a badge Label.
            const int tabBarHeight = 33; // 4 top inset + 28 tab + 1 divider
            const int tabTopInset = 4;
            const int tabCornerRadius = 6;

            var leftTabToolbar = new VisualElement();
            leftTabToolbar.style.flexDirection = FlexDirection.Row;
            leftTabToolbar.style.height = tabBarHeight;
            leftTabToolbar.style.paddingTop = tabTopInset;
            leftTabToolbar.style.paddingLeft = 3;
            leftTabToolbar.style.paddingRight = 3;
            leftTabToolbar.style.borderBottomWidth = 1;
            leftTabToolbar.style.borderBottomColor = DesignerPalette.DividerLine;
            leftTabToolbar.style.backgroundColor = DesignerPalette.TabTrackBg;

            _dataTokensTabBtn = new Button();
            _dataTokensTabBtn.text = "Bindings";
            _dataTokensTabBtn.enableRichText = true;

            _widgetsTabBtn = new Button();
            _widgetsTabBtn.text = "Widgets";

            _toolsTabBtn = new Button();
            _toolsTabBtn.text = "Tools";

            _dataTokensTabBtn.clicked += () =>
            {
                _activeLeftTab = 0;
                if (_tokenBankContainer != null)
                {
                    _tokenBankContainer.scrollOffset = Vector2.zero;
                }
                UpdateTabVisuals();
                RefreshTokens();
            };

            _widgetsTabBtn.clicked += () =>
            {
                _activeLeftTab = 1;
                if (_tokenBankContainer != null)
                {
                    _tokenBankContainer.scrollOffset = Vector2.zero;
                }
                UpdateTabVisuals();
                RefreshTokens();
            };

            _toolsTabBtn.clicked += () =>
            {
                _activeLeftTab = 2;
                if (_tokenBankContainer != null)
                {
                    _tokenBankContainer.scrollOffset = Vector2.zero;
                }
                UpdateTabVisuals();
                RefreshTokens();
            };

            // Even thirds in the folder shape. Zero the default Button margins and let flex-basis:0 split the
            // bar equally, so the three tabs are the same width regardless of how long each label is. Every
            // tab carries the 2px top edge — accent on the active one, transparent on the others — so all
            // three labels keep an identical content box and sit on one baseline.
            foreach (var tabBtn in new[] { _dataTokensTabBtn, _widgetsTabBtn, _toolsTabBtn })
            {
                tabBtn.style.flexGrow = 1;
                tabBtn.style.flexBasis = 0;
                tabBtn.style.marginLeft = 0;
                tabBtn.style.marginRight = 0;
                tabBtn.style.marginTop = 0;
                tabBtn.style.marginBottom = 0;
                tabBtn.style.borderTopWidth = 2;
                tabBtn.style.borderBottomWidth = 0;
                tabBtn.style.borderLeftWidth = 0;
                tabBtn.style.borderRightWidth = 0;
                tabBtn.style.borderTopLeftRadius = tabCornerRadius;
                tabBtn.style.borderTopRightRadius = tabCornerRadius;
                tabBtn.style.borderBottomLeftRadius = 0;
                tabBtn.style.borderBottomRightRadius = 0;
                // A tab switch is a mouse gesture, never a tab stop. Left focusable, the Button picks up the
                // editor theme's `.unity-button:focus` rule on mouse-DOWN, which repaints border-color with
                // the blue focus accent — and because the top corners are rounded, UITK still tessellates a
                // sliver of the zero-width side borders into each corner arc. The result was a pinprick of
                // blue in the corner of the accent cap the moment you pressed a tab. The side colours below
                // pin the same leak shut from the other end.
                tabBtn.focusable = false;
            }

            // Hover feedback on the IDLE tabs so they still read as clickable. The palette is read LIVE at
            // fire time and never captured, per the DesignerPalette convention — a skin flip lands on the
            // next hover instead of repainting a stale colour.
            void WireTabHover(Button tabBtn, int tabIndex)
            {
                tabBtn.RegisterCallback<MouseOverEvent>(_ =>
                {
                    if (_activeLeftTab != tabIndex) tabBtn.style.backgroundColor = DesignerPalette.TabHoverBg;
                });
                tabBtn.RegisterCallback<MouseOutEvent>(_ =>
                {
                    if (_activeLeftTab != tabIndex) tabBtn.style.backgroundColor = Color.clear;
                });
            }
            WireTabHover(_dataTokensTabBtn, 0);
            WireTabHover(_widgetsTabBtn, 1);
            WireTabHover(_toolsTabBtn, 2);

            // Paint the initial state from _activeLeftTab rather than hardcoding tab 0 as selected.
            UpdateTabVisuals();

            leftTabToolbar.Add(_dataTokensTabBtn);
            leftTabToolbar.Add(_widgetsTabBtn);
            leftTabToolbar.Add(_toolsTabBtn);

            tokenBankPanel.Add(leftTabToolbar);

            _tokenBankContainer = new ScrollView();
            _tokenBankContainer.style.flexGrow = 1;
            _tokenBankContainer.style.paddingTop = 8;
            _tokenBankContainer.style.paddingBottom = 8;
            _tokenBankContainer.style.paddingLeft = 8;
            _tokenBankContainer.style.paddingRight = 8;
            tokenBankPanel.Add(_tokenBankContainer);

            if (_presetMode)
            {
                // Preset editor: the left panel is just the type-category list — no hierarchy, no tabs.
                leftTabToolbar.style.display = DisplayStyle.None;
                _leftPanel.Add(tokenBankPanel);
            }
            else
            {
                leftSplit.Add(hierarchyPanel);
                leftSplit.Add(tokenBankPanel);
                _leftPanel.Add(leftSplit);
            }

            // Column 2: Center Canvas
            var previewPanel = new VisualElement();
            previewPanel.style.backgroundColor = DesignerPalette.CanvasBg;
            previewPanel.style.flexDirection = FlexDirection.Column;

            var previewHeaderRow = new VisualElement();
            previewHeaderRow.style.flexDirection = FlexDirection.Row;
            previewHeaderRow.style.alignItems = Align.Center;
            previewHeaderRow.style.height = 32;
            previewHeaderRow.style.paddingLeft = 10;
            previewHeaderRow.style.paddingRight = 10;
            previewHeaderRow.style.borderBottomWidth = 1;
            previewHeaderRow.style.borderBottomColor = DesignerPalette.DividerLine;
            previewHeaderRow.style.backgroundColor = DesignerPalette.PaneHeaderBg;

            // "Canvas" title + its inline search (magnifier hugging the title, then the field and a compact
            // count). Built once here and persists across RefreshPreview rebuilds; see
            // SasquatchLayoutDesignerWindow.CanvasSearch.cs.
            BuildCanvasSearchHeader(previewHeaderRow);

            // (Panel-collapse, Focus, and zoom controls now live in the top toolbar.)

            // Flexible Spacer — inside the search's middle region, so the search bar (an absolute overlay on
            // that region) covers this whole run, Layout menu included, without displacing anything.
            var headerSpacer = new VisualElement();
            headerSpacer.style.flexGrow = 1;
            _canvasHeaderMiddle.Add(headerSpacer);

            var modeToggleGroup = new VisualElement();
            modeToggleGroup.style.flexDirection = FlexDirection.Row;
            modeToggleGroup.style.alignItems = Align.Center;

            var designBtn = new Button(() =>
            {
                _designMode = true;
                RefreshPreview();
            }) { text = "Design Mode" };
            designBtn.style.paddingLeft = 8;
            designBtn.style.paddingRight = 8;
            designBtn.style.fontSize = 10;
            // White stays on the accent fill; the idle button needs the skin's strong ink (white text
            // on the light skin's near-white neutral face was unreadable). IconStrong == white on dark.
            designBtn.style.backgroundColor = _designMode ? DesignerPalette.AccentFill : DesignerPalette.ButtonNeutralBg;
            designBtn.style.color = _designMode ? Color.white : DesignerPalette.IconStrong;
            EditorSpringFX.ButtonSpring(designBtn);

            var previewBtn = new Button(() =>
            {
                _designMode = false;
                _previewHasAppeared = false; // replay Appear animations once on entering preview
                RefreshPreview();
            }) { text = "Live Preview" };
            previewBtn.style.paddingLeft = 8;
            previewBtn.style.paddingRight = 8;
            previewBtn.style.fontSize = 10;
            previewBtn.style.backgroundColor = !_designMode ? DesignerPalette.AccentFill : DesignerPalette.ButtonNeutralBg;
            previewBtn.style.color = !_designMode ? Color.white : DesignerPalette.IconStrong;
            EditorSpringFX.ButtonSpring(previewBtn);

            var interactToggle = new Toggle("Interact");
            interactToggle.value = _designInteract;
            interactToggle.AddToClassList("sq-toggle");
            interactToggle.AddToClassList("sq-toggle--rounded");
            EditorSpringFX.SpringToggleKnob(interactToggle);
            interactToggle.tooltip = "Make fields editable in Design Mode so you can test values and visibility conditions.";
            interactToggle.style.marginRight = 10;
            interactToggle.style.alignItems = Align.Center;
            if (interactToggle.labelElement != null)
            {
                interactToggle.labelElement.style.fontSize = 10;
                interactToggle.labelElement.style.color = DesignerPalette.TextHeader;
                interactToggle.labelElement.style.marginRight = 4;
                interactToggle.labelElement.style.minWidth = 0;
            }
            interactToggle.RegisterValueChangedCallback(evt =>
            {
                _designInteract = evt.newValue;
                RefreshPreview();
            });

            // A gear menu (mirrors the hierarchy's settings cog) holding the Condition Debugger toggle, so the
            // header stays compact instead of an inline toggle shoving the mode buttons over.
            var debugGearBtn = new Button(() =>
            {
                var menu = new GenericMenu();
                menu.AddItem(new GUIContent("Debug Conditions"), _debugConditions, () =>
                {
                    _debugConditions = !_debugConditions;
                    RefreshPreview();
                });
                menu.ShowAsContext();
            });
            debugGearBtn.tooltip = "Debugging options (reveal fields hidden/disabled by conditions).";
            var debugGearIcon = SasquatchIcons.Create(SasquatchIcons.Ids.Settings, 14, DesignerPalette.IconMuted);
            debugGearBtn.Add(debugGearIcon);
            debugGearBtn.style.alignItems = Align.Center;
            debugGearBtn.style.justifyContent = Justify.Center;
            debugGearBtn.style.width = 18;
            debugGearBtn.style.height = 18;
            debugGearBtn.style.marginLeft = 6;
            debugGearBtn.style.paddingTop = 0;
            debugGearBtn.style.paddingBottom = 0;
            debugGearBtn.style.paddingLeft = 0;
            debugGearBtn.style.paddingRight = 0;
            debugGearBtn.style.backgroundColor = new Color(0f, 0f, 0f, 0f);
            debugGearBtn.style.borderTopWidth = 0;
            debugGearBtn.style.borderBottomWidth = 0;
            debugGearBtn.style.borderLeftWidth = 0;
            debugGearBtn.style.borderRightWidth = 0;
            debugGearBtn.RegisterCallback<MouseOverEvent>(_ => debugGearIcon.Tint = DesignerPalette.IconStrong);
            debugGearBtn.RegisterCallback<MouseOutEvent>(_ => debugGearIcon.Tint = DesignerPalette.IconMuted);

            // "Layout ▾" dropdown — reorganization actions (expand/collapse, sort, wrap, flatten, prune)
            // that aren't really "tools".
            var layoutMenuBtn = new Button { text = "Layout ▾" };
            layoutMenuBtn.tooltip = "Layout actions: expand/collapse groups, sort, wrap in cards, flatten, prune empties.";
            layoutMenuBtn.style.paddingLeft = 8;
            layoutMenuBtn.style.paddingRight = 8;
            layoutMenuBtn.style.fontSize = 10;
            layoutMenuBtn.style.marginRight = 10;
            layoutMenuBtn.style.color = DesignerPalette.TextPrimary;
            layoutMenuBtn.style.backgroundColor = DesignerPalette.ButtonNeutralBg;
            layoutMenuBtn.clicked += () =>
            {
                EditorSpringFX.LandPunch(layoutMenuBtn, 0.35f);
                ShowLayoutActionsMenu();
            };
            // Hover only — the click already answers with LandPunch, and stacking ButtonSpring's press-dip on
            // top would have two springs fighting over the same transform.
            EditorSpringFX.HoverScale(layoutMenuBtn, 1.03f, EditorSpringFX.HoverLiftConfig);
            AddChromeHoverTint(layoutMenuBtn, () => DesignerPalette.ButtonNeutralBg);

            _designBtnRef = designBtn;
            _previewBtnRef = previewBtn;
            _interactToggleRef = interactToggle;

            // Both faces are state-dependent (accent while active, neutral while idle), and SyncModeButtonColors
            // repaints them through ChromePaint — so clicking the one you're hovering keeps its tint.
            AddChromeHoverTint(designBtn, () => _designMode ? DesignerPalette.AccentFill : DesignerPalette.ButtonNeutralBg);
            AddChromeHoverTint(previewBtn, () => !_designMode ? DesignerPalette.AccentFill : DesignerPalette.ButtonNeutralBg);

            // The Layout menu rides in the search's middle region (right-aligned by the spacer above it) rather
            // than with the mode toggles, so opening the search covers it instead of pushing it sideways.
            _canvasHeaderMiddle.Add(layoutMenuBtn);
            modeToggleGroup.Add(interactToggle);
            modeToggleGroup.Add(designBtn);
            modeToggleGroup.Add(previewBtn);
            modeToggleGroup.Add(debugGearBtn);
            previewHeaderRow.Add(modeToggleGroup);

            // Preset editor: the center pane is a single live widget preview — label it and drop the design/canvas
            // controls. Nothing to filter in a one-widget preview, so the search goes with them.
            if (_presetMode)
            {
                _canvasSearchTitle.text = "Preview";
                modeToggleGroup.style.display = DisplayStyle.None;
                _canvasSearchToggle.style.display = DisplayStyle.None;
                _canvasSearchOverlay.style.display = DisplayStyle.None;
            }
            AddColumnContextMenu(previewHeaderRow, 1);
            previewPanel.Add(previewHeaderRow);

            // Add conflict warning box below header
            _conflictWarningBox = new VisualElement();
            _conflictWarningBox.style.display = DisplayStyle.None;
            previewPanel.Add(_conflictWarningBox);

            var widgetsUss = SasquatchPaths.LoadStyleSheet("SasquatchWidgets");
            if (widgetsUss != null)
            {
                rootVisualElement.styleSheets.Add(widgetsUss);
            }

            var uss = SasquatchPaths.LoadStyleSheet("DesignerCanvas");
            if (uss != null)
            {
                rootVisualElement.styleSheets.Add(uss);
            }

            // Designer CHROME follows the EDITOR skin; the canvas preview's CONTENT follows the
            // assigned theme via its own build root (whose inner skin class re-scopes the --sasq-*
            // variables for that subtree). In a dark editor this is a visual no-op — the dark token
            // sheet equals the historical fallbacks and no override sheet loads.
            SasquatchSkin.Apply(rootVisualElement, !EditorGUIUtility.isProSkin);
            if (!EditorGUIUtility.isProSkin)
            {
                var lightUss = SasquatchPaths.LoadStyleSheet("DesignerChromeLight");
                if (lightUss != null) rootVisualElement.styleSheets.Add(lightUss);
            }

            _previewContainer = new ScrollView();
            _previewContainer.style.flexGrow = 1;
            // Top headroom lives on _canvasContent (below), NOT here: the ScrollView's own padding sits OUTSIDE its
            // inner clipping viewport, so it can't stop the topmost selected card's badge (top:-10px) from being
            // clipped. Keep a small outer inset here and let the content padding provide the badge's room.
            _previewContainer.style.paddingTop = 2;
            _previewContainer.style.paddingBottom = 12;
            _previewContainer.style.paddingLeft = 12;
            _previewContainer.style.paddingRight = 12;
            previewPanel.Add(_previewContainer);

            // Canvas content host (RefreshPreview clears/fills this). The paddingTop gives the topmost card's
            // absolutely-positioned selection badge (.selection-badge, top:-10px) room INSIDE the scroll viewport so
            // it's never clipped at the top edge (issue: "SOME selection headers get cut off").
            _canvasContent = new VisualElement();
            _canvasContent.style.flexGrow = 1;
            _canvasContent.style.paddingTop = 12;
            _previewContainer.Add(_canvasContent);

            // Grips are hidden at rest; this reveals the one belonging to the innermost
            // element under the cursor (see GripHoverTracker / DesignerCanvas.uss).
            new GripHoverTracker(_previewContainer);

            // Central drag controller. Its chip + drop indicators live on a window-root overlay
            // (so they're never clipped by the ScrollView), and it commits via these callbacks.
            _canvasDragController = new CanvasDragController(rootVisualElement, _previewContainer)
            {
                OnMoveNode = (dragged, target, rel, slot) =>
                {
                    // An Organizer-origin move routes through HandleNodeMoveDrop (which preserves the
                    // Tabs selection); only main-selection canvas/hierarchy drags move as a group.
                    bool fromOrganizer = _canvasDragController != null
                                         && _canvasDragController.CommittingOrigin == DragOrigin.Organizer;
                    if (!fromOrganizer && HasMultiSelection && _selectedNodes.Contains(dragged))
                        HandleGroupMove(target, rel, slot);
                    else
                        HandleNodeMoveDrop(dragged, target, rel, slot);
                },
                OnAddNode = (target, path, rel, slot) => HandlePropertyDrop(target, path, rel, slot),
                OnMoveCollectionItem = MoveCollectionItem,
                OnDeleteNode = DeleteNode,
                OnDeleteNodes = nodes => DeleteNodes(nodes),
                OnSelectNode = (node, additive, range) => SelectFromClick(node, additive, range),
                OnNodeContextMenu = node => ShowCanvasNodeContextMenu(node),
                // Double-clicking a card jumps to its row in the hierarchy (and flashes the card itself) —
                // the same SelectAndPingNode the hierarchy's own double-click runs, in the other direction.
                OnNodeDoubleClick = node => SelectAndPingNode(node),
                // Organizer cards & Bindings tokens select into their OWN sets (no Properties nav).
                OnSelectOrganizerNode = (node, additive, range, clicks) => SelectOrganizerCard(node, additive, range, clicks),
                OnSelectBindingToken = (path, additive, range) => SelectBindingToken(path, additive, range),
                // Clicking the "C# Properties" card opens/closes it (drag adds them all). Spring-fold
                // the rows in place rather than rebuilding the whole tokens panel (which would snap).
                OnBatchAddClick = _ =>
                {
                    _propertiesCardExpanded = !_propertiesCardExpanded;
                    EditorSpringFX.Fold(_propCardRows, _propertiesCardExpanded);
                    EditorSpringFX.SpringCaret(_propCardChevron, _propertiesCardExpanded);
                },
                OnMoveOrganizerGroup = (target, rel, slot) => HandleOrganizerGroupMove(target, rel, slot),
                OnAddNodes = (target, paths, rel, slot) => HandleMultiPropertyDrop(target, paths, rel, slot),
                // Structural tab edits (the canvas "+" and inline rename) need a FULL refresh so the
                // hierarchy + Properties organizer update too, not just a canvas re-bind.
                OnStructuralChange = () => { OnModification(); RefreshHierarchy(); RefreshProperties(); },
                ResolveDragGroup = payload =>
                {
                    // Organizer drags use the organizer's own selection; everything else uses the main one.
                    if (payload.Origin == DragOrigin.Organizer)
                        return (_organizerSelection.Count > 1 && _organizerSelection.Contains(payload.Node))
                            ? new List<LayoutNode>(_organizerSelection) : null;
                    return (HasMultiSelection && _selectedNodes.Contains(payload.Node))
                        ? new List<LayoutNode>(_selectedNodes) : null;
                },
                ResolveAddGroup = payload =>
                    // A batch payload (the "C# Properties" card) drops all its paths at once; otherwise a
                    // multi-selected binding token drags the whole Bindings-tab selection.
                    payload.BatchPaths != null && payload.BatchPaths.Count > 0
                        ? new List<string>(payload.BatchPaths)
                        : (_bindingSelection.Count > 1 && _bindingSelection.Contains(payload.Path))
                            ? new List<string>(_bindingSelection) : null
            };

            // Click on empty canvas space deselects. Bubble phase: a click that lands on a node card is
            // handled by its drag manipulator first; we only clear when the pick wasn't a node element.
            _previewContainer.RegisterCallback<PointerDownEvent>(evt =>
            {
                if (!_designMode) return;
                if (!ResolvesToLayoutNode(evt.target as VisualElement))
                {
                    SelectSingle(null);
                }
            });

            // Column 3: Right Sidebar (Properties)
            _propertiesPanel = new VisualElement();
            _propertiesPanel.style.backgroundColor = DesignerPalette.PanelBgAlt;
            _propertiesPanel.style.flexDirection = FlexDirection.Column;

            // "Properties" header, now a row bar hosting an inline field search (magnifier ▸ full-width field ▸
            // compact count). Built once here and persists across RefreshProperties rebuilds; see
            // SasquatchLayoutDesignerWindow.PropertiesSearch.cs.
            _propertiesPanel.Add(BuildPropertiesSearchHeader());

            _propertiesContainer = new ScrollView();
            _propertiesContainer.style.flexGrow = 1;
            _propertiesContainer.style.paddingTop = 10;
            _propertiesContainer.style.paddingBottom = 10;
            _propertiesContainer.style.paddingLeft = 12;
            _propertiesContainer.style.paddingRight = 12;

            // "Rails & Rhythm" — section headers, rails and the single input column are applied as one
            // idempotent pass over the finished tree (SasquatchLayoutDesignerWindow.PropertiesSkin.cs), not at
            // the ~300 control call sites. Armed once here: the ScrollView outlives every RefreshProperties,
            // which only clears its content.
            HookPropertiesSkin();

            // Animations is NOT a pane of its own any more — it is the last SECTION of this panel, appended by
            // AppendAnimationsSection on every rebuild. Three things the old fixed split cost us: the properties
            // search skipped it entirely (a separate container is excluded by construction, so searching
            // "bounce" or "hover" found nothing), it carried its own header/card styling instead of the shared
            // section skin, and — because nothing ever collapsed that split — it reserved ~220px of the column
            // whether or not the node had a single animation.
            //
            // _animationContainer is now created per REBUILD rather than once here, and stays NULL in the
            // Preset Editor: LayoutNode.Animations is stripped by ClearIdentity and named by no StyleClipboard
            // transfer list, so anything authored there would be discarded on capture. That null is still the
            // one switch RefreshAnimations early-returns on. Cleared explicitly, not merely left unset, because
            // OpenForPreset rebuilds a window whose CreateGUI already ran (before _presetMode was set) and the
            // field would otherwise still point into that discarded tree.
            _animationContainer = null;
            _propertiesPanel.Add(_propertiesContainer);

            _outerSplit.Add(_leftPanel);
            _outerSplit.Add(_innerSplit);

            _innerSplit.Add(previewPanel);
            _innerSplit.Add(_propertiesPanel);

            rootVisualElement.Add(_outerSplit);
            _canvasDragController.BringToFront();

            // Top-right overlay for tool result toasts. pickingMode Ignore so it never eats clicks,
            // and brought to front so toasts float above the canvas/drag overlay.
            _toastHost = new VisualElement { pickingMode = PickingMode.Ignore };
            _toastHost.style.position = Position.Absolute;
            _toastHost.style.top = 8;
            _toastHost.style.right = 10;
            _toastHost.style.flexDirection = FlexDirection.Column;
            _toastHost.style.alignItems = Align.FlexEnd;
            rootVisualElement.Add(_toastHost);
            _toastHost.BringToFront();

            // Let the hierarchy tree accept the same drags as the canvas. The engine snapshots the
            // flat row metadata (via the provider below) and resolves drops with Unity-style
            // indent-based reparenting — no layout gap ever opens in the tree.
            _canvasDragController.AddDropRegion(_hierarchyContainer, DropRegionKind.Hierarchy);
            _canvasDragController.HierarchyRowsProvider = GetHierRowInfos;

            // The Properties panel hosts the Tab Organizer kanban (shown when a Tabs container is
            // selected). Register it as a drop region so dragging item cards between tab columns routes
            // through the same controller -> OnMoveNode -> HandleNodeMoveDrop reparent path.
            _canvasDragController.AddDropRegion(_propertiesContainer, DropRegionKind.Organizer);

            // The Bindings token bank is an UNBIND target: dropping an existing (used) binding onto it
            // removes it from the layout, returning the field to "unused". Only while the Bindings tab
            // is actually showing (tab 0) — the same panel shows Widgets/Tools on the other tabs.
            _canvasDragController.SetRemoveZone(_tokenBankContainer, () => _activeLeftTab == 0);

            ApplyColumnVisibility();
            RefreshAll(disableScrollPreservation: true);
        }

        private void LoadSelectedAsset()
        {
            if (Selection.activeObject is InspectorLayoutAsset asset)
            {
                LoadAsset(asset);
            }
        }

        private void LoadAsset(InspectorLayoutAsset asset)
        {
            // Hand-opening an asset from the Project window is a retarget to an UNRELATED layout, exactly like
            // LoadTypeLayout and ReturnToScriptPicker — so it owes the same full session-swap teardown. It used
            // to do only half of it, and each omission was its own bug:
            //
            //   * the dirty prompt was inlined as `_isDirty && _layoutAsset != null`, which silently skips the
            //     DOMINANT session kind: a type-driven session deliberately keeps _layoutAsset null, so a whole
            //     unsaved session was destroyed by CleanupClone below with no dialog at all. PromptSaveIfDirty
            //     already carries both branches.
            //   * _showcaseOverrideKey survived, and SaveActiveAsset tests it FIRST — so a later Save wrote this
            //     layout into the Showcase EditorPrefs blob instead of the asset, and reported success.
            //   * the nav trail survived, leaving a Back button pointing at a type the user never came from —
            //     and NavigateToDepth saves without prompting, the one exit from a hand-opened asset that can
            //     write to disk silently.
            //   * _testTarget survived, so the opened layout previewed against the PREVIOUS type's instance.
            //   * the canvas/hierarchy queries survived, filtering the new tree by the old layout's search.
            ClearNavStack();
            if (!PromptSaveIfDirty()) return; // Cancel: keep the session exactly as it is

            CleanupClone();
            _collapsedNodes.Clear();
            ResetCanvasSearchForNewLayout();
            ResetHierarchySearchForNewLayout();

            _layoutAsset = asset;
            _showcaseOverrideKey = null; // opening a real asset ends any Showcase override session
            _testTarget = null;          // no instance backs a hand-opened asset; the old type's must not linger
            if (asset != null)
            {
                // A hand-opened compressed asset needs its graph hydrated before Instantiate can deep-copy it
                // (registry-served assets arrive hydrated; this is the direct-selection path).
                LayoutGraphStorage.Hydrate(asset);
                AdoptWorkingClone(Instantiate(asset));
                _designerResizedSinceClone = false;

                // Clone-time AutoAppend parity for the hand-opened path (see LoadTypeLayout): catch the CLONE
                // up with the script so fields added since this asset last synced can't be ledgered-but-never-
                // inserted by a later Save. IN-MEMORY on purpose — merely opening a hand-selected asset must
                // not write to it; the sync reaches disk only through the user's own Save.
                var syncSettings = SasquatchSettingsManager.Current;
                var cloneType = ResolveTargetType();
                if (syncSettings != null && syncSettings.UnboundFieldHandling == UnboundFieldSyncMode.AutoAppend && cloneType != null)
                    UnboundFieldSync.ReconcileLayoutInMemory(cloneType, _clonedLayoutAsset, syncSettings.ApplyScriptAttributesOnSync);

                // Button rename self-heal for the hand-opened clone (every sync mode). IN-MEMORY like the
                // reconcile above — merely opening an asset must not write to it.
                if (cloneType != null)
                    ButtonMethodSync.HealLayoutInMemory(cloneType, _clonedLayoutAsset);

                SnapshotFieldsAtCloneTime();
                SetPrimarySelection(_clonedLayoutAsset.Root);
            }
            else
            {
                _clonedLayoutAsset = null;
                SetPrimarySelection(null);
            }

            _isDirty = false;

            UpdateSaveButtonText();
            RefreshAll(disableScrollPreservation: true);
        }

        private void OnSelectionChanged()
        {
            // The preset editor never follows the Unity selection — it edits a fixed preset asset.
            if (_presetMode) return;

            // Ignore the transient selection "nudge" (clear → restore) that our own save triggers to redraw the
            // real inspectors. Reacting to it would reload the layout and rebuild this window mid-edit — the
            // systemic cause of "I changed something but it didn't take".
            if (SasquatchEditorRegistrar.IsSelectionNudgePending) return;

            if (Selection.activeObject is InspectorLayoutAsset asset)
            {
                if (asset != _layoutAsset)
                {
                    LoadAsset(asset);
                }
                return;
            }

            // Don't auto-follow the selection away from in-progress work — it would discard the
            // clone and spawn a save prompt on every click. The user can still open a type
            // explicitly via the component's "Edit Sasquatch Layout" context-menu item.
            if (_isDirty)
            {
                return;
            }

            // Never RELOAD the type the designer is already editing. Reloading rebuilds the window and resets the
            // node selection to root — and the save "nudge" (clear→restore Selection) restores the SAME object,
            // whose restore-event escapes the IsSelectionNudgePending guard (the flag is cleared before Unity
            // fires the deferred selectionChanged). Without this, every save bounced the selection to root, which
            // made Auto-Save unusable. A different type still loads normally (and the first load has no clone, so
            // ResolveTargetType() is null and the load proceeds).
            System.Type editing = ResolveTargetType();

            if (Selection.activeObject is GameObject go)
            {
                // Resolve the first component whose type is a user MonoBehaviour/ScriptableObject we can design a
                // layout for. Filtering by IsTypeEditable (rather than just "not a Transform") means selecting a
                // GameObject whose only non-Transform component is a built-in (e.g. a Global Volume's Volume) is
                // simply ignored — the designer keeps showing the current layout instead of trying to open it.
                var activeComponent = go.GetComponents<Component>()
                    .FirstOrDefault(c => c != null && SasquatchContextMenu.IsTypeEditable(c.GetType()));

                if (activeComponent != null && activeComponent.GetType() != editing)
                {
                    // While authoring an ANCESTOR's layout (type switcher), selecting a subclass instance
                    // keeps the base session open and just adopts it as the preview target — auto-following
                    // down to the subclass would silently abandon the base-authoring session.
                    if (editing != null && editing.IsAssignableFrom(activeComponent.GetType()))
                    {
                        _testTarget = activeComponent;
                        RefreshPreview();
                        return;
                    }
                    LoadTypeLayout(activeComponent.GetType(), activeComponent);
                }
            }
            else if (Selection.activeObject is ScriptableObject so)
            {
                // Our own asset types are never design targets.
                if (so is InspectorLayoutAsset || so is SasquatchInspectorDatabase || so is SasquatchThemeAsset)
                {
                    return;
                }

                if (so.GetType() != editing)
                {
                    // Same subclass-instance rule as the component branch above.
                    if (editing != null && editing.IsAssignableFrom(so.GetType()))
                    {
                        _testTarget = so;
                        RefreshPreview();
                        return;
                    }
                    LoadTypeLayout(so.GetType(), so);
                }
            }
        }

        private void OnUndoRedo()
        {
            // An undo mid-typing-burst ends the burst: the pending save still runs (the asset DID change —
            // to its undone state), and the next keystroke starts a fresh undo record instead of merging
            // into the pre-undo one.
            CommitPendingTextEdit();
            CommitPendingValueEdit(); // ditto for a slider/color drag interrupted by undo

            // Undo restores an InspectorLayoutAsset by RE-DESERIALIZING it, so every [SerializeReference]
            // LayoutNode comes back as a NEW instance and everything this window keys by instance is left
            // pointing outside the tree. Nothing used to re-point it, and none of the failures announce
            // themselves: RefreshProperties' sameNode test compared orphan to orphan and reported "same", so
            // the panel kept its scroll and its search query and looked completely live while every edit made
            // in it landed on a node the Save would never see. The hierarchy sprang open (_collapsedNodes),
            // the Tab Organizer lost its highlight, and Delete stopped recognising an orphaned root — so it
            // was accepted, cleared the selection and dirtied the asset while removing nothing.
            //
            // Round-tripping through positional paths is self-sorting, which is what makes it safe here even
            // though undoRedoPerformed is GLOBAL and fires AFTER the pop: an undo that never touched this
            // layout leaves every path resolving, so this is a no-op; one that did leaves them unresolvable,
            // so the stale state is DROPPED rather than silently edited.
            if (_clonedLayoutAsset?.Root != null)
            {
                RestoreNodeState(SnapshotNodeState(_clonedLayoutAsset.Root), _clonedLayoutAsset.Root);
                // Same fallback SaveActiveAsset uses after its re-clone: the panel always has something to show.
                if (_selectedNode == null) SetPrimarySelection(_clonedLayoutAsset.Root);
            }

            // Preset mode deliberately does NOTHING here — no capture, no dirty mark.
            //
            // undoRedoPerformed is global and post-hoc, so this handler cannot tell WHICH object the stack
            // just restored. When it was _presetTarget itself ("Reset Context Preset" / "Reset Layout
            // Presets" — the only two sites that record on it), the preview still showed the post-reset
            // template, so capturing wrote that straight back over the entry the undo had just restored, and
            // the context branch's auto-prune then DELETED the restored entry outright. Unrecoverable:
            // neither the capture nor the prune records any undo of its own, so redo re-applies a removal
            // that already happened. Both reset sites already guard themselves with _suppressPresetSync;
            // this was the uncovered third.
            //
            // The cost is that undoing a PREVIEW edit no longer pushes the reverted value into the preset
            // asset — but that coverage was always an illusion: SyncCurrentCategoryToPreset takes no undo
            // record, so the preset write was never on the stack, and this handler was faking it at the price
            // of being able to destroy a restored entry. MarkPresetDirty goes with it: it fired on ANY undo
            // anywhere in the editor, painting "Save*" over a preset nothing had touched.
            RefreshAll();
        }

        private void RefreshAll(bool disableScrollPreservation = false)
        {
            // Held-open cells are plumbing, not widgets: the moment one stops holding a position (its
            // widget moved away, or the container stopped having cells at all) it evaporates, so the user
            // never has placeholders to clean up by hand. Doing it HERE — the one point every mutation,
            // undo and re-type funnels through — is what makes that automatic rather than a fix-up command.
            // Idempotent and a no-op when there's nothing to trim, so it can't spuriously dirty a layout.
            if (_clonedLayoutAsset?.Root != null) EmptyCellFill.Normalize(_clonedLayoutAsset.Root);

            if (disableScrollPreservation)
            {
                _disableScrollPreservation = true;
                try
                {
                    RefreshHierarchy();
                    RefreshProperties();
                    RefreshTokens();
                    RefreshPreview();
                }
                finally
                {
                    _disableScrollPreservation = false;
                }
            }
            else
            {
                RefreshHierarchy();
                RefreshProperties();
                RefreshTokens();
                RefreshPreview();
            }
            UpdateWindowTitle();
        }

        // Suffixes the OS window title ("Sasquatch Layout Designer") with the type currently being edited
        // (e.g. "Sasquatch Layout Designer — PlayerStats"), so it's clear which script the window is for and
        // multiple designer windows are tellable apart. Preset mode keeps its own title.
        private void UpdateWindowTitle()
        {
            if (_presetMode) return;
            var type = ResolveTargetType();
            string title = type != null ? $"Sasquatch Layout Designer — {type.Name}" : "Sasquatch Layout Designer";
            if (titleContent != null && titleContent.text != title) titleContent.text = title;
        }

        /// <summary>True when <paramref name="node"/> is a container/collection that can hold children.</summary>
        public bool IsParentNode(LayoutNode node)
        {
            if (node == null) return false;
            if (node is ContainerNode cn && cn.Children != null && cn.Children.Count > 0)
                return true;
            if (node is CollectionNode col && col.ItemLayout != null)
                return true;
            return false;
        }

        private void ToggleNodeCollapsed(LayoutNode node)
        {
            if (_collapsedNodes.Contains(node))
            {
                _collapsedNodes.Remove(node);
            }
            else
            {
                _collapsedNodes.Add(node);
            }
            RefreshHierarchy();
        }

        private void RefreshHierarchy()
        {
            if (_hierarchyContainer == null) return;
            PreserveScroll(_hierarchyContainer, () =>
            {
                _hierarchyContainer.Clear();
                _hierRows.Clear();
                // Resolve the active search BEFORE the render — RenderTree builds only the rows it keeps, so
                // for this panel a rebuild IS the filter (there is nothing to hide and nothing to restore).
                BeginHierarchySearchPass();

            if (_clonedLayoutAsset == null)
            {
                var lbl = new Label("Select a component, ScriptableObject, or script to start designing its inspector — or click the ✎ in any inspector header.");
                lbl.style.whiteSpace = WhiteSpace.Normal;
                lbl.style.paddingTop = 15;
                lbl.style.paddingLeft = 10;
                lbl.style.color = DesignerPalette.TextDisabled;
                _hierarchyContainer.Add(lbl);
                return;
            }

            if (_clonedLayoutAsset.Root == null)
            {
                var initBtn = new Button(() =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Initialize Layout Root");
                    _clonedLayoutAsset.Root = NewRootWithScriptHeader();
                    SetPrimarySelection(_clonedLayoutAsset.Root);
                    OnModification();
                    RefreshAll();
                }) { text = "Initialize Root Container" };
                initBtn.style.marginTop = 15;
                initBtn.style.marginLeft = 10;
                initBtn.style.marginRight = 10;
                _hierarchyContainer.Add(initBtn);
                return;
            }

            RenderTree(_clonedLayoutAsset.Root, 0, _hierarchyContainer);
            });
            // Every exit above returns out of the lambda and PreserveScroll invokes it synchronously, so this
            // one call reports the pass however the render ended (count + gold frame + magnifier state).
            EndHierarchySearchPass();
        }

        private void RenderTree(LayoutNode node, int depth, VisualElement container, List<bool> prefixVerticals = null, bool isLast = true, ContainerNode parent = null, bool inItemTemplate = false)
        {
            if (node == null) return;

            // A held-open cell is plumbing, not a widget the user manages: it is not selectable, movable or
            // deletable, and it disappears on its own the moment its cell is filled (see EmptyCellNode). A
            // row for it would be a phantom entry the user is invited to act on and can't — and rows here
            // ARE the drop/selection surface, so omitting it is what makes it unreachable everywhere.
            if (node is EmptyCellNode) return;

            // Hierarchy search. The filter decides which rows get BUILT rather than hiding built ones, so a
            // Hidden node takes its whole subtree with it — safe because any node with a findable descendant is
            // itself at least AncestorOfMatch, never Hidden.
            var searchState = SearchEntryState.Match;
            bool isRootRow = _clonedLayoutAsset != null && node == _clonedLayoutAsset.Root;
            if (_hierSearchStates != null)
            {
                if (!_hierSearchStates.TryGetValue(node, out searchState)) searchState = SearchEntryState.Hidden;
                // The root row always renders: it is the drop target for the whole tree, and a blank panel
                // would read as "your layout is gone" rather than "nothing matched".
                if (searchState == SearchEntryState.Hidden && !isRootRow) return;
                if (!isRootRow) _hierSearchVisibleRows++;
            }

            bool isCollapsed = _collapsedNodes.Contains(node);
            // While filtering, the trail down to a match is held OPEN — transiently, exactly like the
            // inspector's GroupExpanderRegistry.SetTransient: _collapsedNodes is never written, so clearing the
            // query drops every branch straight back to how the user left it.
            bool heldOpenBySearch = isCollapsed && _hierSearchPinnedOpen != null && _hierSearchPinnedOpen.Contains(node);
            if (heldOpenBySearch) isCollapsed = false;

            var row = new VisualElement();
            // Tags every hierarchy row so a mode that decorates node surfaces (the format painter's source ring
            // and cursor) can find rows by class instead of walking the whole panel looking for userData.
            row.AddToClassList(HierarchyRowClass);
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            // The whole tree is shunted right by one fixed gutter so the visibility eye has a straight column of
            // its own at the row's left edge, the way Unity's own Hierarchy does it — the eye must NOT ride the
            // indent, or it would staircase away with depth. Three things measure from this origin and shift
            // with it: the tree-guide painter below (its host starts at the gutter), and DropSlotMap.HierBaseX
            // + the DropSlotMap comment that pins this expression.
            row.style.paddingLeft = HierEyeGutter + depth * 15;
            row.style.paddingTop = 3;
            row.style.paddingBottom = 3;
            row.style.borderBottomWidth = 1;
            row.style.borderBottomColor = DesignerPalette.RowHairline;

            // Tree connector lines. Absolute so they don't affect row flow. Continuous verticals
            // pass through for ancestors that still have siblings below; the current row joins its
            // parent with an elbow/tee (vertical) + a horizontal stub, per modern tree-view design.
            if (_showHierarchyLines && depth > 0)
            {
                // Snapshot the recursion state: prefixVerticals is a list reused/mutated as
                // RenderTree walks the tree, but generateVisualContent runs after layout, so the
                // painter lambda must capture this row's values, not the shared list.
                bool[] prefixSnapshot = prefixVerticals?.ToArray();
                int rowDepth = depth;
                bool rowIsLast = isLast;

                var guides = new VisualElement { pickingMode = PickingMode.Ignore };
                guides.style.position = Position.Absolute;
                // Starts at the eye gutter, not the row edge: the painter below works in coordinates local to
                // THIS element (col * 15 + 7, rowDepth * 15), so moving the host is the whole indent shift.
                guides.style.left = HierEyeGutter;
                guides.style.right = 0;
                guides.style.top = 0;
                // Extend 1px past the padding box so the verticals paint OVER the row's 1px
                // bottom border (the separator) instead of stopping just above it — children
                // render after the parent's border, so the guide wins that pixel.
                guides.style.bottom = -1;
                guides.generateVisualContent += mgc =>
                {
                    float h = guides.contentRect.height;
                    if (h < 0.01f) return;
                    float rowH = h - 1f; // visual row height (h includes the 1px separator overhang)

                    // 1px strokes centered on integer coordinates straddle two device pixels and
                    // blur; snapping to the half-pixel grid keeps the guides hairline-crisp.
                    float ppp = EditorGUIUtility.pixelsPerPoint;
                    float Snap(float v) => (Mathf.Round(v * ppp - 0.5f) + 0.5f) / ppp;

                    var painter = mgc.painter2D;
                    painter.lineWidth = 1f;
                    painter.strokeColor = DesignerPalette.TreeGuide;
                    painter.lineCap = LineCap.Butt; // round caps leave visible dots on hairlines

                    float centerY = Snap(rowH * 0.5f);
                    painter.BeginPath();

                    // Pass-through verticals for ancestor columns (0 .. depth-2).
                    if (prefixSnapshot != null)
                    {
                        for (int col = 0; col < prefixSnapshot.Length; col++)
                        {
                            if (!prefixSnapshot[col]) continue;
                            float x = Snap(col * 15 + 7);
                            painter.MoveTo(new Vector2(x, 0f));
                            painter.LineTo(new Vector2(x, h));
                        }
                    }

                    float branchX = Snap((rowDepth - 1) * 15 + 7);
                    float stubEnd = rowDepth * 15;

                    if (rowIsLast)
                    {
                        // Terminal elbow: the vertical eases into the horizontal stub with a small
                        // rounded corner instead of a hard 90° join. One continuous subpath, so the
                        // joint never double-blends.
                        float radius = Mathf.Min(3.5f, Mathf.Min(centerY, stubEnd - branchX));
                        painter.MoveTo(new Vector2(branchX, 0f));
                        painter.LineTo(new Vector2(branchX, centerY - radius));
                        painter.QuadraticCurveTo(new Vector2(branchX, centerY), new Vector2(branchX + radius, centerY));
                        painter.LineTo(new Vector2(stubEnd, centerY));
                    }
                    else
                    {
                        // Tee: full-height vertical plus a straight stub (only terminal elbows are
                        // rounded, which avoids double-drawn corners on pass-through rows). The stub
                        // starts at the vertical's right EDGE (+ half the line width), not its center —
                        // overlapping the shared pixel would double the alpha and leave a bright dot.
                        painter.MoveTo(new Vector2(branchX, 0f));
                        painter.LineTo(new Vector2(branchX, h));
                        painter.MoveTo(new Vector2(branchX + 0.5f, centerY));
                        painter.LineTo(new Vector2(stubEnd, centerY));
                    }
                    painter.Stroke();
                };
                row.Add(guides);
            }

            // Search match stripe. Absolute, like the tree guides above: a real left border would widen the
            // row's box and shunt matched rows 2px out of line with the trail rows around them.
            if (_hierSearchStates != null && searchState == SearchEntryState.Match)
            {
                var stripe = new VisualElement { pickingMode = PickingMode.Ignore };
                stripe.style.position = Position.Absolute;
                stripe.style.left = 0;
                stripe.style.top = 0;
                stripe.style.bottom = 0;
                stripe.style.width = 2;
                stripe.style.backgroundColor = DesignerPalette.Accent;
                row.Add(stripe);
            }

            // Highlight selected node(s). The primary selection is a touch brighter than other
            // members of a multi-selection.
            bool isSelected = IsNodeSelected(node);
            if (isSelected)
            {
                row.style.backgroundColor = node == _selectedNode
                    ? DesignerPalette.AccentWashStrong
                    : DesignerPalette.AccentWash;
            }
            else
            {
                row.RegisterCallback<MouseOverEvent>(evt => row.style.backgroundColor = DesignerPalette.RowHoverWash);
                row.RegisterCallback<MouseOutEvent>(evt => row.style.backgroundColor = new Color(0f, 0f, 0f, 0f));
            }

            // Mark the row as a drop target for the shared pointer-based drag controller
            // (CanvasDragController resolves drops by walking up to the nearest userData LayoutNode).
            row.userData = node;

            // Visibility eye — the gutter column the paddingLeft above reserved. Not on the root: hiding the
            // whole layout is the toolbar eye's job (LayoutRegistry.SetLayoutHidden), and a root that could
            // hide itself would empty the inspector with no row left to click.
            // The properties-panel twin of this row is gated the same way — a dictionary CELL TEMPLATE has no
            // hidden-node skip to act on, so an eye there would be a click that changes nothing.
            if (!isRootRow && !IsDictionaryCellTemplate(node)) AddHierarchyVisibilityEye(row, node);

            // Node descriptive label
            string labelText = BuildHierarchyRowLabel(node, parent);

            // Collapse/Expand caret button
            var caret = new Button();
            caret.style.width = 14;
            caret.style.height = 14;
            caret.style.paddingLeft = 0;
            caret.style.paddingRight = 0;
            caret.style.paddingTop = 0;
            caret.style.paddingBottom = 0;
            caret.style.marginLeft = 0;
            caret.style.marginRight = 4;
            caret.style.backgroundColor = Color.clear;
            caret.style.borderTopWidth = 0;
            caret.style.borderBottomWidth = 0;
            caret.style.borderLeftWidth = 0;
            caret.style.borderRightWidth = 0;
            caret.style.alignItems = Align.Center;
            caret.style.justifyContent = Justify.Center;

            if (IsParentNode(node))
            {
                // Icon child stays PickingMode.Ignore so evt.target remains the Button itself
                // (the row's MouseDown handler relies on that to skip caret clicks).
                caret.Add(SasquatchIcons.Create(
                    isCollapsed ? SasquatchIcons.Ids.ChevronRight : SasquatchIcons.Ids.ChevronDown,
                    10, DesignerPalette.IconMuted));
                caret.clicked += () => ToggleNodeCollapsed(node);
                if (heldOpenBySearch)
                {
                    // This branch is open only because a match lives inside it. Collapsing it would hide the
                    // row the query just found, and the click would look broken (the next render would force
                    // it open again anyway) — so say so instead of letting it no-op.
                    caret.SetEnabled(false);
                    caret.tooltip = "Held open by the search";
                }
            }
            else
            {
                caret.style.visibility = Visibility.Hidden;
            }
            row.Add(caret);

            // Node type icon, shared with the Tab Organizer via GetNodeIcon. Tab children keep the
            // tabs icon they had when it was baked into the label text.
            string rowIconId = (node is ContainerNode && parent != null && parent.Type == ContainerType.Tabs)
                ? SasquatchIcons.Ids.PanelsTopLeft
                : GetNodeIcon(node);
            // A hidden node's row greys out — the same signal Unity's Hierarchy gives a disabled GameObject.
            // Applied to the label and the type icon rather than the row's opacity, because the format painter
            // also writes inline styles to the row element on its 120ms reconcile tick.
            // …except on a dictionary CELL TEMPLATE, where the flag cannot hide anything (the drawer builds
            // its cells outside BuildNode, which is where the skip lives) and NOTHING can clear it: the row
            // has no eye, and neither the Properties panel nor the quick-edit popup offers the toggle. A
            // layout that picked the bit up while the popup still offered it would otherwise carry a
            // permanently greyed row the user cannot explain or undo. Read as false rather than WRITTEN
            // false — opening a layout must not dirty it (TestNoWritesOnBuild). Short-circuits on the flag,
            // so the owner walk runs only for the handful of rows that actually carry it.
            bool rowHidden = node.HiddenInInspector && !IsDictionaryCellTemplate(node);

            var typeIcon = SasquatchIcons.Create(rowIconId, 12, rowHidden ? DesignerPalette.TextDisabled : (Color?)null);
            typeIcon.style.marginRight = 5;
            row.Add(typeIcon);

            var label = new Label(labelText);
            label.name = "sasq-hier-label"; // BeginHierarchyRename swaps this for a TextField in place
            label.style.flexGrow = 1;
            label.style.color = rowHidden ? DesignerPalette.TextDisabled : DesignerPalette.TextPrimary;
            label.style.unityFontStyleAndWeight = IsNodeSelected(node) ? FontStyle.Bold : FontStyle.Normal;
            label.style.whiteSpace = WhiteSpace.NoWrap;
            label.style.textOverflow = TextOverflow.Ellipsis;
            label.style.overflow = Overflow.Hidden;
            row.Add(label);

            // Drag-and-drop is handled by the same pointer-based controller as the canvas, so dropping
            // a token/widget/node onto a hierarchy row uses the identical chip + indicator UX and the
            // same commit handlers. Non-root rows are draggable (dragAnywhere: the tree has no
            // interactive body, so the whole row is a handle); clicking selects via HandleClick. The
            // root row isn't draggable, so it gets a plain click-to-select handler.
            if (_canvasDragController != null && node != _clonedLayoutAsset.Root)
            {
                row.AddManipulator(new CanvasDragManipulator(
                    _canvasDragController, CanvasDragPayload.Move(node), dragAnywhere: true));
            }
            else
            {
                row.RegisterCallback<MouseDownEvent>(evt =>
                {
                    if (evt.button == 0 && !(evt.target is Button))
                    {
                        SelectFromClick(node, evt.actionKey, evt.shiftKey);
                    }
                });
            }

            // Double-click → jump to this node on the canvas: scroll it into view and flash it, exactly what
            // the row's right-click "Ping" does, on the gesture people try first. Deep in a long layout that
            // turns "which card is this row?" into a glance.
            //
            // PointerDOWN, not up: at press time nothing has moved, so a double-click can never be confused
            // with the tail of a drag. The drag manipulator's own callback on this row still runs (a
            // same-element callback isn't affected by StopPropagation) and re-selects the node, which
            // SelectSingle no-ops because the first click already selected it.
            row.RegisterCallback<PointerDownEvent>(evt =>
            {
                if (evt.button != 0 || evt.clickCount < 2) return;
                // The caret, the mini action buttons, and the in-place F2 rename field own their own
                // double-clicks (a word-select in a rename must stay a word-select).
                if (evt.target is VisualElement t &&
                    (t is Button || t.GetFirstAncestorOfType<Button>() != null ||
                     t is TextField || t.GetFirstAncestorOfType<TextField>() != null)) return;
                SelectAndPingNode(node);
                evt.StopPropagation();
            });

            // Right-click → wrap / delete the selection.
            AddRowContextMenu(row, node);

            // Action buttons
            if (node is ContainerNode containerNode)
            {
                if (_showAddContainerBtn)
                {
                    var addC = new Button(() => AddChildNode(containerNode, 0)) { text = "+C" };
                    addC.tooltip = "Add Child Container";
                    StyleMiniButton(addC, new Color(0.2f, 0.35f, 0.2f, 1f));
                    row.Add(addC);
                }

                if (_showAddChildBindingBtn)
                {
                    var addB = new Button(() => AddChildNode(containerNode, 1)) { text = "+B" };
                    addB.tooltip = "Add Child Binding";
                    StyleMiniButton(addB, new Color(0.2f, 0.28f, 0.38f, 1f));
                    row.Add(addB);
                }

                if (_showAddChildCollectionBtn)
                {
                    var addL = new Button(() => AddChildNode(containerNode, 2)) { text = "+L" };
                    addL.tooltip = "Add Child Collection/List";
                    StyleMiniButton(addL, new Color(0.4f, 0.25f, 0.45f, 1f));
                    row.Add(addL);
                }
            }
            else if (node is CollectionNode collectionNode)
            {
                if (collectionNode.ItemLayout == null)
                {
                    // An ATOMIC element (List<Vector2>, List<float>) has no fields to drag in afterwards, so
                    // an empty Panel would be a template you could never fill — seed it with the element
                    // binding, which is the only thing that can go in one. Struct elements keep the empty
                    // Panel: their fields are in the Bindings panel, waiting to be dropped.
                    bool seedsElement = SupportsElementTemplate(
                        ResolveCollectionElementType(collectionNode), IsManagedReferenceCollection(collectionNode));
                    var addT = new Button(() =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Create Item Template");
                        // The element template goes in BARE (no Panel), so seeding it leaves the rows
                        // looking exactly as they did — see SetElementTemplate.
                        if (seedsElement) SetElementTemplate(collectionNode);
                        else collectionNode.ItemLayout = new ContainerNode() { StyleToken = "Panel" };
                        OnModification();
                        RefreshAll();
                    }) { text = "+T" };
                    addT.tooltip = seedsElement
                        ? "Create Item Layout Template (adds a binding for the element itself, so you can style every row)"
                        : "Create Item Layout Template";
                    StyleMiniButton(addT, new Color(0.35f, 0.35f, 0.15f, 1f));
                    row.Add(addT);
                }
                else
                {
                    var delT = new Button(() =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Remove Item Template");
                        collectionNode.ItemLayout = null;
                        OnModification();
                        RefreshAll();
                    });
                    delT.Add(SasquatchIcons.Create(SasquatchIcons.Ids.X, 9, Color.white));
                    delT.Add(new Label("T") { pickingMode = PickingMode.Ignore });
                    delT.style.flexDirection = FlexDirection.Row;
                    delT.tooltip = "Remove Item Layout Template";
                    StyleMiniButton(delT, DesignerPalette.Danger);
                    row.Add(delT);
                }
            }
            // A dictionary binding gets the same affordance a collection does, for the same reason: its rows
            // are built from a template, and without one the Key and Value cells are plain fields nothing in
            // the designer can reach. +KV seeds BOTH halves at once and removes both at once — one gesture,
            // because "style my dictionary's cells" is one intention, and a seeded template is a PURE change
            // (a bare BindingNode renders exactly the cell the untemplated table drew, so seeding one cannot
            // move a pixel until the author picks a Display Type).
            else if (node is BindingNode dictNode && SupportsDictionaryCellTemplates(dictNode))
            {
                if (!HasDictionaryCellTemplate(dictNode))
                {
                    var addKV = new Button(() =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Create Cell Templates");
                        SetDictionaryCellTemplates(dictNode);
                        OnModification();
                        RefreshAll();
                    }) { text = "+KV" };
                    addKV.tooltip = "Create Key / Value cell templates — style the fields INSIDE this "
                                  + "dictionary (a Color value as a Color Palette, a float as a slider, …)";
                    StyleMiniButton(addKV, new Color(0.35f, 0.35f, 0.15f, 1f));
                    row.Add(addKV);
                }
                else
                {
                    var delKV = new Button(() =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Remove Cell Templates");
                        dictNode.DictionaryKeyTemplate = null;
                        dictNode.DictionaryValueTemplate = null;
                        OnModification();
                        RefreshAll();
                    });
                    delKV.Add(SasquatchIcons.Create(SasquatchIcons.Ids.X, 9, Color.white));
                    delKV.Add(new Label("KV") { pickingMode = PickingMode.Ignore });
                    delKV.style.flexDirection = FlexDirection.Row;
                    delKV.tooltip = "Remove Key / Value cell templates";
                    StyleMiniButton(delKV, DesignerPalette.Danger);
                    row.Add(delKV);
                }
            }

            // Ordering controls (unless root)
            if (node != _clonedLayoutAsset.Root)
            {
                if (_showHierarchyArrows)
                {
                    var up = new Button(() => MoveNode(node, -1));
                    up.tooltip = "Move Up";
                    StyleMiniButton(up, DesignerPalette.ButtonNeutralBg);
                    up.Add(SasquatchIcons.Create(SasquatchIcons.Ids.ChevronUp, 9, DesignerPalette.IconStrong));
                    row.Add(up);

                    var down = new Button(() => MoveNode(node, 1));
                    down.tooltip = "Move Down";
                    StyleMiniButton(down, DesignerPalette.ButtonNeutralBg);
                    down.Add(SasquatchIcons.Create(SasquatchIcons.Ids.ChevronDown, 9, DesignerPalette.IconStrong));
                    row.Add(down);
                }

                if (_showDeleteButtons)
                {
                    var del = new Button(() => DeleteNode(node));
                    del.tooltip = "Delete Node";
                    StyleMiniButton(del, DesignerPalette.Danger);
                    del.Add(SasquatchIcons.Create(SasquatchIcons.Ids.X, 9, Color.white));
                    row.Add(del);
                }
            }

            container.Add(row);

            // Flat row metadata for the engine's hierarchy drop snapshot (indent reparenting).
            _hierRows.Add(new HierRow
            {
                Node = node,
                Depth = depth,
                Parent = parent,
                IndexInParent = parent?.Children?.IndexOf(node) ?? -1,
                Nestable = node is ContainerNode nc && nc.Type != ContainerType.Tabs && !inItemTemplate,
                Collapsed = isCollapsed,
                InItemTemplate = inItemTemplate,
                Row = row
            });

            // Child prefix: ancestor verticals + (this node's column continues if it has more siblings).
            var childPrefix = new List<bool>(prefixVerticals ?? new List<bool>());
            if (depth > 0) childPrefix.Add(!isLast);

            // Recursively render children if it's a container and not collapsed
            if (!isCollapsed && node is ContainerNode parentContainer && parentContainer.Children != null)
            {
                // "Last child" drives the tree guide's elbow-vs-tee, so it has to mean the last child that
                // actually RENDERS: with a filter running the real last sibling may be pruned, which would
                // leave a tee reaching down into empty space below the final row.
                int lastVisible = parentContainer.Children.Count - 1;
                if (_hierSearchStates != null)
                {
                    lastVisible = -1;
                    for (int i = 0; i < parentContainer.Children.Count; i++)
                        if (RendersUnderHierarchySearch(parentContainer.Children[i])) lastVisible = i;
                }

                for (int i = 0; i < parentContainer.Children.Count; i++)
                {
                    RenderTree(parentContainer.Children[i], depth + 1, container, childPrefix, i == lastVisible, parentContainer, inItemTemplate);
                }
            }
            // Recursively render item layout template if it's a collection and not collapsed
            else if (!isCollapsed && node is CollectionNode parentCollection && parentCollection.ItemLayout != null)
            {
                RenderTree(parentCollection.ItemLayout, depth + 1, container, childPrefix, true, null, true);
            }
            // A dictionary's Key / Value cell templates, rendered as the binding's own children — the exact
            // shape a collection's item template takes, because they are the same idea: one authored node
            // that styles every row. `inItemTemplate` is passed TRUE so they inherit the item template's
            // rules (not indent-reparentable, no drag-to-nest), which is what they are.
            else if (!isCollapsed && node is BindingNode dictBinding && HasDictionaryCellTemplate(dictBinding))
            {
                bool hasValue = dictBinding.DictionaryValueTemplate != null;
                if (dictBinding.DictionaryKeyTemplate != null)
                    RenderTree(dictBinding.DictionaryKeyTemplate, depth + 1, container, childPrefix, !hasValue, null, true);
                if (hasValue)
                    RenderTree(dictBinding.DictionaryValueTemplate, depth + 1, container, childPrefix, true, null, true);
            }
        }

        /// <summary>True when <paramref name="node"/> carries either dictionary cell template.</summary>
        internal static bool HasDictionaryCellTemplate(LayoutNode node) =>
            node is BindingNode bn
            && (bn.DictionaryKeyTemplate != null || bn.DictionaryValueTemplate != null);

        /// <summary>
        /// Width in px of the hierarchy's left gutter — the straight column the visibility eye lives in, kept
        /// clear of the depth indent so the eyes line up down the whole tree the way Unity's Hierarchy does.
        /// <para>THREE places measure from this and must move together: <c>RenderTree</c>'s
        /// <c>paddingLeft = HierEyeGutter + depth * 15</c>, the tree-guide host's <c>left</c> in the same
        /// method, and <c>DropSlotMap.BuildHierarchyRegion</c>'s <c>HierBaseX</c> — which is what the indent
        /// drag reads to decide the depth you dropped at.</para>
        /// </summary>
        internal const int HierEyeGutter = 18;

        /// <summary>Name on the hierarchy row's visibility eye, so tests and the row can find it back.</summary>
        internal const string HierEyeButtonName = "sasq-hier-eye";

        /// <summary>
        /// The per-row visibility eye: hide this node (and, for a container, everything inside it) from the real
        /// Inspector without deleting it. Absolutely positioned in the row's left gutter — a flex child would
        /// ride the depth indent and staircase away down the tree.
        ///
        /// <para>Two rest states, so it needs two behaviours. VISIBLE is quiet: the eye is faded out until the
        /// pointer enters the row, the same trade the canvas cards' ✕ and the live inspector's table-row actions
        /// make. HIDDEN is loud: the eye stays pinned at full opacity whether or not you are hovering, because
        /// it is the only thing on the row saying why that field is gone from the inspector.</para>
        ///
        /// <para>A <see cref="Button"/> on purpose, not a bare element: the row's click-to-select, its
        /// double-click ping and its drag manipulator all already special-case <c>evt.target is Button</c>, so
        /// clicking the eye cannot start a drag or ping the canvas. Its icon child is picking-Ignore for the
        /// same reason the caret's is — the target has to stay the Button itself.</para>
        /// </summary>
        private void AddHierarchyVisibilityEye(VisualElement row, LayoutNode node)
        {
            bool hidden = node.HiddenInInspector;

            var icon = SasquatchIcons.Create(
                hidden ? SasquatchIcons.Ids.EyeOff : SasquatchIcons.Ids.Eye,
                11,
                hidden ? DesignerPalette.ToastWarning : DesignerPalette.IconMuted);
            icon.pickingMode = PickingMode.Ignore;

            var eye = new Button { name = HierEyeButtonName };
            eye.Add(icon);
            // Names the SCOPE, because the click can act on more than this row (see the handler below).
            bool eyeWillFanOut = _selectedNodes.Count > 1 && IsNodeSelected(node);
            string eyeScopeNote = eyeWillFanOut
                ? $" Applies to all {_selectedNodes.Count} selected elements."
                : "";
            eye.tooltip = (hidden
                ? "Hidden in the Inspector — everything around it closes up as if it were deleted. Click to show it again."
                : "Hide from the Inspector. The element stays here in the designer; the real Inspector closes up around it.")
                + eyeScopeNote;
            eye.style.position = Position.Absolute;
            eye.style.left = 1;
            eye.style.top = 0;
            eye.style.bottom = 0;
            eye.style.width = HierEyeGutter - 3;
            eye.style.marginLeft = 0;
            eye.style.marginRight = 0;
            eye.style.marginTop = 0;
            eye.style.marginBottom = 0;
            eye.style.paddingLeft = 0;
            eye.style.paddingRight = 0;
            eye.style.paddingTop = 0;
            eye.style.paddingBottom = 0;
            eye.style.backgroundColor = Color.clear;
            eye.style.borderTopWidth = 0;
            eye.style.borderBottomWidth = 0;
            eye.style.borderLeftWidth = 0;
            eye.style.borderRightWidth = 0;
            eye.style.alignItems = Align.Center;
            eye.style.justifyContent = Justify.Center;

            eye.clicked += () =>
            {
                bool nowHidden = !node.HiddenInInspector;
                // SCOPE, decided here rather than left to the multi-edit mirror. Hiding deliberately fans out
                // across a multi-selection (see the "Visible in Inspector" row in General Settings, and the
                // absence of hiddenInInspector from MultiEditMirror.IdentityFields) — but the mirror computes
                // its delta against the PRIMARY node only. That made the eye mean two different things
                // depending on which row of the selection it was clicked on: on the primary's row it hid the
                // whole selection, on any other selected row it hid just that one. Clicking the eye does not
                // move the selection (the drag manipulator skips Buttons), so the stale primary stayed put and
                // nothing on screen explained the difference.
                //
                // SET, never toggle-each: a mixed selection must converge on one value instead of inverting
                // every row independently, which is what FanOutEdit-style writes do everywhere else.
                bool fanOut = _selectedNodes.Count > 1 && IsNodeSelected(node);
                string undoName = fanOut
                    ? (nowHidden ? "Hide Elements" : "Show Elements")
                    : (nowHidden ? "Hide Element" : "Show Element");

                Undo.RecordObject(_clonedLayoutAsset, undoName);
                if (fanOut)
                {
                    foreach (var n in _selectedNodes)
                        if (n != null) n.HiddenInInspector = nowHidden;
                    // The clicked row need not be in _selectedNodes' list object itself (IsNodeSelected also
                    // matches the primary), so write it explicitly rather than assuming the loop covered it.
                    node.HiddenInInspector = nowHidden;
                }
                else
                {
                    node.HiddenInInspector = nowHidden;
                }
                OnModification();
                // RefreshAll, not the hierarchy + preview pair this used to call. General Settings' own
                // "Visible in Inspector" toggle is seeded ONCE from its getter (CreateAllowAdjustToggle has no
                // re-sync hook), so an eye click on the SELECTED node's row left that checkbox showing the
                // pre-click value. Clicking it then wrote the value the node already had — a silent no-op
                // that still took an undo record, and it took a second click to actually undo the hide.
                // Every other node-mutating row button (+C/+B/+L/+T/xT) already refreshes all three panes.
                RefreshAll(false);
            };

            row.Add(eye);

            // Pinned once hidden — see the summary. Nothing else to wire in that state.
            if (hidden)
            {
                eye.style.opacity = 1f;
                return;
            }

            eye.style.opacity = 0f;
            bool shown = false;
            void Reveal(bool on)
            {
                if (on == shown) return;
                shown = on;
                EditorSpringFX.RevealFade(eye, on);
            }

            row.RegisterCallback<MouseEnterEvent>(_ => Reveal(true));
            row.RegisterCallback<MouseLeaveEvent>(_ => Reveal(false));
            // Enter/Leave alone is not enough. Clicking the eye runs RefreshHierarchy, which is a FULL teardown
            // — the replacement row is born under a pointer that never left, so no MouseEnter is ever coming and
            // an un-hidden row would strand its eye invisible. The first pointer move re-arms it. Reveal
            // early-outs when already showing, so this costs one bool compare per move. Same fix, same reason,
            // as CardDeleteMiniButton's.
            row.RegisterCallback<MouseMoveEvent>(_ => Reveal(true));
        }

        private void StyleMiniButton(Button btn, Color bgColor)
        {
            btn.style.fontSize = 10; // 10px accessibility floor
            // Center icon children (text-only mini buttons are unaffected).
            btn.style.alignItems = Align.Center;
            btn.style.justifyContent = Justify.Center;
            btn.style.marginLeft = 2;
            btn.style.marginRight = 2;
            btn.style.paddingLeft = 4;
            btn.style.paddingRight = 4;
            btn.style.paddingTop = 1;
            btn.style.paddingBottom = 1;
            btn.style.backgroundColor = bgColor;
            btn.style.color = Color.white;
            btn.style.borderTopWidth = 0;
            btn.style.borderBottomWidth = 0;
            btn.style.borderLeftWidth = 0;
            btn.style.borderRightWidth = 0;
        }

        // Shared icon id (see SasquatchIcons) for a node, used by the hierarchy tree, the Tab Organizer,
        // and the layout-asset inspector (InspectorLayoutAssetEditor) so all node-tree surfaces stay consistent.
        internal static string GetNodeIcon(LayoutNode node)
        {
            switch (node)
            {
                case ContainerNode cn: return cn.Type == ContainerType.Tabs ? SasquatchIcons.Ids.PanelsTopLeft
                    : cn.Type == ContainerType.Frame ? SasquatchIcons.Ids.Frame
                    : SasquatchIcons.Ids.Folder;
                case BindingNode _: return SasquatchIcons.Ids.Link;
                case CollectionNode _: return SasquatchIcons.Ids.Layers;
                case PropertyNode _: return SasquatchIcons.Ids.Crosshair;
                case ButtonNode _: return SasquatchIcons.Ids.Zap;
                case HelpBoxNode _: return SasquatchIcons.Ids.TriangleAlert;
                case ScriptHeaderNode _: return SasquatchIcons.Ids.FileCode;
                case SpaceNode _: return SasquatchIcons.Ids.ChevronsUpDown;
                case LabeledDividerNode _: return SasquatchIcons.Ids.Ruler;
                case ImageBannerNode _: return SasquatchIcons.Ids.GalleryVertical;
                case TextBlockNode _: return SasquatchIcons.Ids.AlignLeft;
                case EmbeddedEditorNode _: return SasquatchIcons.Ids.PencilRuler;
#if SASQ_CUSTOM_WIDGET
                case CustomWidgetNode _: return SasquatchIcons.Ids.Sparkles;
#endif
                default: return SasquatchIcons.Ids.Dot;
            }
        }

        // Shared concise display name for a node (no type tag), used by the hierarchy label and the
        // Tab Organizer cards.
        private static string GetNodeDisplayName(LayoutNode node)
        {
            switch (node)
            {
                case ContainerNode cn:
                    if (!string.IsNullOrEmpty(cn.HierarchyName)) return cn.HierarchyName;
                    if (!string.IsNullOrEmpty(cn.TabLabel)) return cn.TabLabel;
                    if (!string.IsNullOrEmpty(cn.Title)) return cn.Title;
                    if (!string.IsNullOrEmpty(cn.PropertyPath)) return $"Scope: {cn.PropertyPath}";
                    return cn.Type == ContainerType.Frame ? "Frame" : "Container";
                case BindingNode bn:
                    // No path = an ELEMENT TEMPLATE, the binding on a collection's element itself. Every
                    // route that creates one puts it in an item layout, so "Element" is the name that
                    // matches what the user sees; "Binding" said nothing about the one node whose whole
                    // identity is what it has INSTEAD of a path.
                    return !string.IsNullOrEmpty(bn.EffectiveLabelOverride) ? bn.EffectiveLabelOverride
                         : (!string.IsNullOrEmpty(bn.PropertyPath) ? bn.PropertyPath : "Element");
                case CollectionNode colNode:
                    return !string.IsNullOrEmpty(colNode.EffectiveTitleOverride) ? colNode.EffectiveTitleOverride
                         : (!string.IsNullOrEmpty(colNode.PropertyPath) ? colNode.PropertyPath : "unbound list");
                case PropertyNode pnode:
                    return !string.IsNullOrEmpty(pnode.LabelOverride) ? pnode.LabelOverride
                         : (!string.IsNullOrEmpty(pnode.PropertyName) ? pnode.PropertyName : "C# Property");
                case ButtonNode btn:
                    return !string.IsNullOrEmpty(btn.ButtonText) ? btn.ButtonText
                         : (!string.IsNullOrEmpty(btn.MethodName) ? btn.MethodName : "Execute Action");
                case HelpBoxNode hb:
                {
                    string msg = !string.IsNullOrEmpty(hb.Message) ? hb.Message : "Diagnostic Alert";
                    return msg.Replace("\r\n", " ").Replace("\n", " ");
                }
                case ScriptHeaderNode _: return "Script Header";
                case SpaceNode _: return "Space";
                case LabeledDividerNode ld: return string.IsNullOrEmpty(ld.Title) ? "Divider" : ld.Title;
                case ImageBannerNode _: return "Image";
                case TextBlockNode tb: return string.IsNullOrEmpty(tb.Text) ? "Text Block" : tb.Text.Replace("\r\n", " ").Replace("\n", " ");
                case EmbeddedEditorNode _: return "Embedded Editor";
                case EmptyCellNode _: return "Empty Cell";
#if SASQ_CUSTOM_WIDGET
                case CustomWidgetNode _: return "Custom Widget";
#endif
                // A kind with no arm still names itself: "Node" told the user nothing about the card in
                // front of them. Mirrors BuildHierarchyRowLabel's own fallback.
                default: return ObjectNames.NicifyVariableName(StripNodeSuffix(node.GetType().Name));
            }
        }

        // ---- Tab Organizer (kanban) ----

        // Builds the Tab Organizer: a side-by-side kanban (one column per tab) shown in Properties when
        // a Tabs container is selected. Every tab — and its items — is visible at once, which is what
        // makes moving items between tabs intuitive. Cards carry userData + a CanvasDragManipulator, so
        // dragging a card onto another column routes through the shared drag controller ->
        // HandleNodeMoveDrop (reparent across tabs); a right-click "Move to" menu is the non-drag
        // fallback. Reuses GetNodeIcon/GetNodeDisplayName so cards match the hierarchy.
        private VisualElement BuildTabOrganizer(ContainerNode tabsContainer)
        {
            // Drop any organizer selection that no longer belongs to THIS Tabs container (switched
            // tabs container, or cards deleted/moved out) so highlights + multi-drag stay valid.
            _organizerSelection.RemoveAll(n => n == null || !IsAncestorOf(tabsContainer, n));

            var section = CreateFoldoutHeader("Tab Organizer");

            var hint = new Label("Drag a card onto another tab to move it. Drop on “+ Add Tab” to make a new tab. Right-click for more.");
            hint.style.whiteSpace = WhiteSpace.Normal;
            hint.style.color = DesignerPalette.TextMuted;
            hint.style.fontSize = 10;
            hint.style.marginBottom = 6;
            hint.style.unityFontStyleAndWeight = FontStyle.Normal;
            section.Add(hint);

            // Wrapping board — up to 3 tab columns per row, then it wraps to the next row (compact + easy to
            // scan), instead of scrolling sideways forever.
            var board = new VisualElement();
            board.style.flexDirection = FlexDirection.Row;
            board.style.flexWrap = Wrap.Wrap;
            board.style.marginBottom = 4;
            section.Add(board);

            var children = tabsContainer.Children ?? new List<LayoutNode>();
            for (int i = 0; i < children.Count; i++)
            {
                if (!(children[i] is ContainerNode tabNode)) continue; // tabs are always containers
                int index = i;

                string tabName = !string.IsNullOrEmpty(tabNode.TabLabel) ? tabNode.TabLabel
                               : !string.IsNullOrEmpty(tabNode.Title) ? tabNode.Title
                               : $"Tab {index + 1}";
                int itemCount = tabNode.Children?.Count ?? 0;

                // Cell = exactly 1/3 of the board width so 3 columns fit per row and the 4th wraps below the
                // 1st. userData on the cell means even the gap around a column still drops into THIS tab (no
                // dead zones between columns).
                var cell = new VisualElement();
                cell.userData = tabNode;
                cell.AddToClassList("organizer-tab-cell"); // drop-snapshot anchor for the drag engine
                cell.style.width = Length.Percent(33.3f);
                cell.style.flexGrow = 0;
                cell.style.flexShrink = 0;

                // Column = the visible card stack; its margins create the gaps between cells.
                var column = new VisualElement();
                column.style.marginRight = 5;
                column.style.marginBottom = 5;
                column.style.paddingTop = 4;
                column.style.paddingBottom = 4;
                column.style.paddingLeft = 4;
                column.style.paddingRight = 4;
                column.style.backgroundColor = DesignerPalette.KanbanColumnBg;
                column.style.borderTopLeftRadius = 4;
                column.style.borderTopRightRadius = 4;
                column.style.borderBottomLeftRadius = 4;
                column.style.borderBottomRightRadius = 4;

                // Header: name (count) + rename + delete
                var header = new VisualElement();
                header.style.flexDirection = FlexDirection.Row;
                header.style.alignItems = Align.Center;
                header.style.marginBottom = 4;

                var titleLabel = new Label($"{tabName}  ({itemCount})");
                titleLabel.style.flexGrow = 1;
                // UI Toolkit's default flex-shrink is 0 (unlike web CSS), so set it explicitly — otherwise the
                // title keeps its full width and shoves the buttons off the edge instead of ellipsizing.
                titleLabel.style.flexShrink = 1;
                titleLabel.style.minWidth = 0;
                titleLabel.style.unityFontStyleAndWeight = FontStyle.Bold;
                titleLabel.style.color = DesignerPalette.TextBright;
                titleLabel.style.whiteSpace = WhiteSpace.NoWrap;
                titleLabel.style.overflow = Overflow.Hidden;
                titleLabel.style.textOverflow = TextOverflow.Ellipsis;
                header.Add(titleLabel);

                var renameBtn = new Button { tooltip = "Rename tab" };
                StyleMiniButton(renameBtn, DesignerPalette.ButtonNeutralBg);
                renameBtn.Add(SasquatchIcons.Create(SasquatchIcons.Ids.Pencil, 10, DesignerPalette.IconStrong));
                renameBtn.style.flexShrink = 0; // never let the title squeeze the action buttons
                header.Add(renameBtn);

                var deleteBtn = new Button { tooltip = "Delete tab" };
                StyleMiniButton(deleteBtn, DesignerPalette.Danger);
                deleteBtn.Add(SasquatchIcons.Create(SasquatchIcons.Ids.Trash2, 10, Color.white));
                deleteBtn.style.flexShrink = 0;
                header.Add(deleteBtn);

                column.Add(header);

                // Inline rename: swap the title label for a text field (Enter/blur commits, Esc cancels).
                renameBtn.clicked += () =>
                {
                    var field = new TextField { value = tabName };
                    field.style.flexGrow = 1;
                    bool done = false;
                    void Commit(bool cancel)
                    {
                        if (done) return;
                        done = true;
                        if (!cancel)
                        {
                            string v = field.value?.Trim();
                            Undo.RecordObject(_clonedLayoutAsset, "Rename Tab");
                            tabNode.TabLabel = string.IsNullOrEmpty(v) ? $"Tab {index + 1}" : v;
                            OnModification();
                        }
                        RefreshAll();
                    }
                    field.RegisterCallback<KeyDownEvent>(e =>
                    {
                        if (e.keyCode == KeyCode.Return || e.keyCode == KeyCode.KeypadEnter) { Commit(false); e.StopPropagation(); }
                        else if (e.keyCode == KeyCode.Escape) { Commit(true); e.StopPropagation(); }
                    });
                    field.RegisterCallback<FocusOutEvent>(_ => Commit(false));
                    header.Insert(0, field);
                    titleLabel.style.display = DisplayStyle.None;
                    field.schedule.Execute(() => { field.Focus(); field.SelectAll(); });
                };

                deleteBtn.clicked += () =>
                {
                    if (itemCount > 0 && !EditorUtility.DisplayDialog("Delete Tab",
                            $"Delete tab \"{tabName}\" and its {itemCount} item(s)?", "Delete", "Cancel"))
                        return;
                    Undo.RecordObject(_clonedLayoutAsset, "Delete Tab");
                    tabsContainer.Children.Remove(tabNode);
                    if (tabsContainer.ActiveTabIndex >= tabsContainer.Children.Count)
                        tabsContainer.ActiveTabIndex = Mathf.Max(0, tabsContainer.Children.Count - 1);
                    OnModification();
                    RefreshAll();
                };

                // Body: drop target for "append into this tab" (userData = the tab container). The shared
                // controller resolves a drop here to AsChild on the tab and appends via HandleNodeMoveDrop.
                var body = new VisualElement();
                body.userData = tabNode;
                body.style.minHeight = 44;
                body.style.flexGrow = 1;

                if (itemCount == 0)
                {
                    var empty = new Label("drop items here");
                    empty.style.unityTextAlign = TextAnchor.MiddleCenter;
                    empty.style.color = DesignerPalette.TextDisabled;
                    empty.style.fontSize = 10;
                    empty.style.paddingTop = 12;
                    empty.style.paddingBottom = 12;
                    empty.style.whiteSpace = WhiteSpace.Normal;
                    var dash = DesignerPalette.DashEdge;
                    empty.style.borderTopWidth = 1; empty.style.borderBottomWidth = 1;
                    empty.style.borderLeftWidth = 1; empty.style.borderRightWidth = 1;
                    empty.style.borderTopColor = dash; empty.style.borderBottomColor = dash;
                    empty.style.borderLeftColor = dash; empty.style.borderRightColor = dash;
                    empty.pickingMode = PickingMode.Ignore; // let the body receive drop hovers
                    body.Add(empty);
                }
                else
                {
                    foreach (var childNode in tabNode.Children)
                    {
                        if (childNode == null) continue;
                        body.Add(BuildOrganizerCard(tabsContainer, tabNode, childNode));
                    }
                }

                column.Add(body);
                cell.Add(column);
                board.Add(cell);
            }

            // + Add Tab card placeholder (same size as other tab container cells).
            var addTabCell = new VisualElement();
            addTabCell.style.width = Length.Percent(33.3f);
            addTabCell.style.flexGrow = 0;
            addTabCell.style.flexShrink = 0;

            var addTabBox = new VisualElement { tooltip = "Add a new tab (or drop an item here to put it in a new tab)" };
            addTabBox.style.marginRight = 5;
            addTabBox.style.marginBottom = 5;
            addTabBox.style.minHeight = 71;
            addTabBox.style.paddingTop = 4;
            addTabBox.style.paddingBottom = 4;
            addTabBox.style.paddingLeft = 4;
            addTabBox.style.paddingRight = 4;
            addTabBox.style.backgroundColor = DesignerPalette.WellBg;
            addTabBox.style.borderTopLeftRadius = 4;
            addTabBox.style.borderTopRightRadius = 4;
            addTabBox.style.borderBottomLeftRadius = 4;
            addTabBox.style.borderBottomRightRadius = 4;
            addTabBox.style.borderTopWidth = 1; addTabBox.style.borderBottomWidth = 1;
            addTabBox.style.borderLeftWidth = 1; addTabBox.style.borderRightWidth = 1;

            var dashColor = DesignerPalette.DashEdgeFaint;
            addTabBox.style.borderTopColor = dashColor; addTabBox.style.borderBottomColor = dashColor;
            addTabBox.style.borderLeftColor = dashColor; addTabBox.style.borderRightColor = dashColor;
            addTabBox.style.alignItems = Align.Center;
            addTabBox.style.justifyContent = Justify.Center;

            // Use the custom clickable class for link cursor
            addTabBox.AddToClassList("sasq-clickable");

            var addLabel = new Label("+ Add Tab");
            addLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
            addLabel.style.color = DesignerPalette.TextFaint;
            addLabel.style.fontSize = 11;
            addLabel.style.unityFontStyleAndWeight = FontStyle.Bold;
            addLabel.pickingMode = PickingMode.Ignore;
            addTabBox.Add(addLabel);

            addTabBox.RegisterCallback<MouseEnterEvent>(_ =>
            {
                addTabBox.style.backgroundColor = DesignerPalette.WellHoverBg;
                addTabBox.style.borderTopColor = DesignerPalette.DashEdgeHover;
                addTabBox.style.borderBottomColor = DesignerPalette.DashEdgeHover;
                addTabBox.style.borderLeftColor = DesignerPalette.DashEdgeHover;
                addTabBox.style.borderRightColor = DesignerPalette.DashEdgeHover;
                addLabel.style.color = DesignerPalette.TextPrimary;
            });
            addTabBox.RegisterCallback<MouseLeaveEvent>(_ =>
            {
                addTabBox.style.backgroundColor = DesignerPalette.WellBg;
                addTabBox.style.borderTopColor = dashColor;
                addTabBox.style.borderBottomColor = dashColor;
                addTabBox.style.borderLeftColor = dashColor;
                addTabBox.style.borderRightColor = dashColor;
                addLabel.style.color = DesignerPalette.TextFaint;
            });

            addTabBox.RegisterCallback<PointerDownEvent>(evt =>
            {
                if (evt.button != 0) return;
                Undo.RecordObject(_clonedLayoutAsset, "Add Tab");
                tabsContainer.Children ??= new List<LayoutNode>();
                tabsContainer.Children.Add(new ContainerNode
                {
                    Type = ContainerType.Rows,
                    TabLabel = $"Tab {tabsContainer.Children.Count + 1}"
                });
                OnModification();
                RefreshAll();
                evt.StopPropagation();
            });

            // Drop zone: dropping a card here creates a new tab containing it.
            if (_canvasDragController != null) _canvasDragController.RegisterDropZone(addTabBox, tabsContainer);

            addTabCell.Add(addTabBox);
            board.Add(addTabCell);

            return section;
        }

        // A single draggable item chip inside a tab column.
        private VisualElement BuildOrganizerCard(ContainerNode tabsContainer, ContainerNode currentTab, LayoutNode childNode)
        {
            var card = new VisualElement();
            card.userData = childNode; // drop-resolution target for reorder within / move between columns
            card.AddToClassList("organizer-card"); // gives it the translate transition for gap shifts
            card.style.flexDirection = FlexDirection.Row;
            card.style.alignItems = Align.Center;
            card.style.marginBottom = 3;
            card.style.paddingTop = 3;
            card.style.paddingBottom = 3;
            card.style.paddingLeft = 5;
            card.style.paddingRight = 5;
            card.style.backgroundColor = _organizerSelection.Contains(childNode) ? OrganizerCardSelected : OrganizerCardNormal;
            card.style.borderTopLeftRadius = 3; card.style.borderTopRightRadius = 3;
            card.style.borderBottomLeftRadius = 3; card.style.borderBottomRightRadius = 3;
            card.style.overflow = Overflow.Hidden; // clip rather than let a long name push the card wider

            var grip = new VisualElement { pickingMode = PickingMode.Ignore };
            grip.AddToClassList("sasq-reorder-grip");
            grip.Add(new GripGlyph { Tint = DesignerPalette.Ink(0.25f) });
            card.Add(grip);

            var icon = SasquatchIcons.Create(GetNodeIcon(childNode), 12);
            icon.style.marginRight = 4;
            card.Add(icon);

            var name = new Label(GetNodeDisplayName(childNode)) { pickingMode = PickingMode.Ignore };
            name.style.flexGrow = 1;
            // UI Toolkit's default flex-shrink is 0, so set it explicitly (plus minWidth 0) or the label keeps
            // its full text width and the ellipsis never kicks in.
            name.style.flexShrink = 1;
            name.style.minWidth = 0;
            name.style.color = DesignerPalette.OrganizerCardText;
            name.style.whiteSpace = WhiteSpace.NoWrap;
            name.style.overflow = Overflow.Hidden;
            name.style.textOverflow = TextOverflow.Ellipsis;
            card.Add(name);

            // Selection-aware hover: a selected card keeps its blue; only unselected cards react.
            // Reads _organizerSelection LIVE so the highlight survives selection changes.
            card.RegisterCallback<MouseEnterEvent>(_ =>
            {
                if (!_organizerSelection.Contains(childNode)) card.style.backgroundColor = OrganizerCardHover;
            });
            card.RegisterCallback<MouseLeaveEvent>(_ =>
                card.style.backgroundColor = _organizerSelection.Contains(childNode) ? OrganizerCardSelected : OrganizerCardNormal);

            // Drag-to-move (between columns / reorder) + click-to-select. Origin=Organizer routes the
            // click to SelectOrganizerCard (select-only; double-click opens properties) instead of
            // navigating the Properties panel.
            if (_canvasDragController != null)
                card.AddManipulator(new CanvasDragManipulator(
                    _canvasDragController, CanvasDragPayload.Move(childNode, DragOrigin.Organizer), dragAnywhere: true));

            AddOrganizerCardMenu(card, tabsContainer, currentTab, childNode);
            return card;
        }

        // Right-click "Move to ▸ {tab}" / "New tab…" — the non-drag fallback for reassigning a card.
        private void AddOrganizerCardMenu(VisualElement card, ContainerNode tabsContainer, ContainerNode currentTab, LayoutNode childNode)
        {
            card.AddManipulator(new ContextualMenuManipulator(evt =>
            {
                var tabs = tabsContainer.Children;
                if (tabs != null)
                {
                    for (int i = 0; i < tabs.Count; i++)
                    {
                        if (!(tabs[i] is ContainerNode target)) continue;
                        string name = !string.IsNullOrEmpty(target.TabLabel) ? target.TabLabel
                                    : !string.IsNullOrEmpty(target.Title) ? target.Title
                                    : $"Tab {i + 1}";
                        var captured = target;
                        bool isCurrent = target == currentTab;
                        evt.menu.AppendAction($"Move to/{name}",
                            _ => MoveNodeToTab(childNode, currentTab, captured),
                            isCurrent ? DropdownMenuAction.Status.Disabled : DropdownMenuAction.Status.Normal);
                    }
                }
                evt.menu.AppendAction("Move to/New tab…", _ =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Move Item To New Tab");
                    tabsContainer.Children ??= new List<LayoutNode>();
                    var newTab = new ContainerNode { Type = ContainerType.Rows, TabLabel = $"Tab {tabsContainer.Children.Count + 1}" };
                    tabsContainer.Children.Add(newTab);
                    currentTab.Children?.Remove(childNode);
                    newTab.Children = new List<LayoutNode> { childNode };
                    OnModification();
                    RefreshAll();
                });
            }));
        }

        // Moves a top-level item from one tab to another (right-click menu path). Selection stays on the
        // Tabs container, so the organizer remains open and refreshes in place.
        private void MoveNodeToTab(LayoutNode node, ContainerNode fromTab, ContainerNode toTab)
        {
            if (toTab == null || fromTab == toTab) return;
            Undo.RecordObject(_clonedLayoutAsset, "Move Item To Tab");
            fromTab?.Children?.Remove(node);
            toTab.Children ??= new List<LayoutNode>();
            toTab.Children.Add(node);
            OnModification();
            RefreshAll();
        }

        // ---- Animation controls (bottom of the right column) ----

        private static Label AnimHint(string text)
        {
            var lbl = new Label(text);
            lbl.style.paddingTop = 10;
            lbl.style.whiteSpace = WhiteSpace.Normal;
            lbl.style.color = DesignerPalette.TextDisabled;
            return lbl;
        }

        /// <summary>
        /// Appends Animations as the panel's LAST section. Called at every content-bearing exit of
        /// <see cref="RefreshProperties"/> — but never on the no-selection exit, where the panel already says
        /// "Select a node…" and a second hint saying the same thing would just be noise.
        ///
        /// <para>Collapsed by default, and the state persists: animations are the least-reached-for thing in
        /// the panel, so an unused section costs one quiet line at the bottom rather than a permanent pane.
        /// Being a real <c>Foldout</c> inside <c>_propertiesContainer</c> is what makes it searchable — the
        /// properties filter force-expands a collapsed section to reveal a match, so a query for "bounce"
        /// now surfaces an animation row that no amount of scrolling would previously have found.</para>
        /// </summary>
        private void AppendAnimationsSection()
        {
            if (_propertiesContainer == null) return;
            // The Preset Editor has no animations to edit at all — see the note in CreateGUI. Null is the
            // switch RefreshAnimations gates on, so clearing it here also covers a preset rebuild.
            // Null is the switch RefreshAnimations gates on, so this covers a dictionary CELL TEMPLATE too:
            // AnimationBinder.Apply is a BuildNode step the drawer's cells never reach.
            if (_presetMode || IsDictionaryCellTemplate(_selectedNode)) { _animationContainer = null; return; }

            var section = CreatePersistedSection("Animations", _animationsExpanded, v => _animationsExpanded = v);

            // A plain host, not a ScrollView: the panel's own ScrollView already scrolls this. Rebuilt every
            // pass, so RefreshAnimations (which the "+ Add Animation" button calls on its own) keeps writing
            // into the element that is actually on screen.
            _animationContainer = new VisualElement();
            section.Add(_animationContainer);
            _propertiesContainer.Add(section);

            RefreshAnimations();
        }

        private void RefreshAnimations()
        {
            if (_animationContainer == null) return;
            // Spring every action button in the rebuilt panel (deferred so the new buttons exist first).
            _animationContainer.schedule.Execute(() => ApplyOptionButtonSprings(_animationContainer)).ExecuteLater(1);
            _animationContainer.Clear();

            if (_selectedNode == null)
            {
                _animationContainer.Add(AnimHint("Select a node to add animations."));
                return;
            }
            // NO multi-selection gate. Animations are a List on the LayoutNode BASE, so they mean the same
            // thing on every node kind — there was never a reason to hold them to one node, and the manual has
            // always said they fan out. They travel through MultiEditMirror like any other row: the section is
            // built against the primary and the delta is deep-cloned onto the followers. Because the value is a
            // LIST, an edit replaces each follower's whole list — MultiEditBanner says so above the rows when
            // they currently differ, which is the honest version of "editing here sets all of them".
            AppendMultiEditListBanner(_animationContainer, MultiEditMirror.AnimationFields, "animations");

            var node = _selectedNode;
            if (node.Animations == null) node.Animations = new List<NodeAnimation>();

            for (int i = 0; i < node.Animations.Count; i++)
            {
                _animationContainer.Add(BuildAnimationRow(node, node.Animations[i], i));
            }

            var btnRow = new VisualElement();
            btnRow.style.flexDirection = FlexDirection.Row;
            btnRow.style.marginTop = 6;

            var addBtn = new Button(() =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Add Animation");
                node.Animations.Add(new NodeAnimation());
                OnModification();
                RefreshAnimations();
            })
            { text = "+ Add Animation" };
            addBtn.style.flexGrow = 1;
            // Still opts OUT of the options-panel spring sweep — NOT for looks. The sweep's feedback is a
            // transform SCALE, and these buttons stretch to the panel width, so scaling one paints its
            // rounded edge past the panel (see the same note on the drill-in "Open" button in
            // SasquatchLayoutDesignerWindow.Navigation.cs). Hover/press feedback comes from Unity's stock
            // button USS instead, which StyleActionButton no longer overwrites with an inline face.
            addBtn.AddToClassList(OptionSprungClass);
            btnRow.Add(addBtn);

            if (node.Animations.Count > 0)
            {
                var playBtn = new Button(() => PreviewAnimations(node));
                playBtn.style.flexDirection = FlexDirection.Row;
                playBtn.style.alignItems = Align.Center;
                playBtn.style.justifyContent = Justify.Center;
                var playIcon = SasquatchIcons.Create(SasquatchIcons.Ids.Play, 10);
                playIcon.style.marginRight = 4;
                playBtn.Add(playIcon);
                playBtn.Add(new Label("Preview") { pickingMode = PickingMode.Ignore });
                playBtn.style.marginLeft = 4;
                playBtn.style.paddingLeft = 8;
                playBtn.style.paddingRight = 8;
                btnRow.Add(playBtn);
            }
            _animationContainer.Add(btnRow);
        }

        private VisualElement BuildAnimationRow(LayoutNode node, NodeAnimation anim, int index)
        {
            var card = new VisualElement();
            card.style.marginBottom = 8;
            card.style.paddingTop = 6; card.style.paddingBottom = 6;
            card.style.paddingLeft = 8; card.style.paddingRight = 8;
            card.style.backgroundColor = DesignerPalette.CardBg;
            card.style.borderTopLeftRadius = 4; card.style.borderTopRightRadius = 4;
            card.style.borderBottomLeftRadius = 4; card.style.borderBottomRightRadius = 4;

            var top = new VisualElement();
            top.style.flexDirection = FlexDirection.Row;
            top.style.alignItems = Align.Center;

            var triggerField = new EnumField("On", anim.Trigger);
            triggerField.style.flexGrow = 1;
            triggerField.RegisterValueChangedCallback(evt =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Change Animation Trigger");
                anim.Trigger = (AnimTrigger)evt.newValue;
                OnModification();
            });
            top.Add(triggerField);

            var removeBtn = DeleteMiniButton("Remove animation", () =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Remove Animation");
                if (index >= 0 && index < node.Animations.Count) node.Animations.RemoveAt(index);
                OnModification();
                RefreshAnimations();
            });
            top.Add(removeBtn);
            card.Add(top);

            var effectField = new EnumField("Effect", anim.Effect);
            effectField.RegisterValueChangedCallback(evt =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Change Animation Effect");
                anim.Effect = (AnimEffect)evt.newValue;
                OnModification();
                RefreshAnimations(); // pulse color / bounce / easing fields appear and disappear
            });
            card.Add(effectField);

            var durField = new FloatField("Duration (s)");
            durField.value = anim.DurationSeconds;
            durField.RegisterValueChangedCallback(evt =>
            {
                HandleDebouncedValueEdit("Change Animation Duration", () => anim.DurationSeconds = Mathf.Max(0.01f, evt.newValue));
            });
            FlushValueEditOnBlur(durField);
            card.Add(durField);

            if (anim.IsSpringEffect)
            {
                // Spring physics replaces easing: Bounce drives the overshoot instead.
                var bounceSlider = new Slider("Bounce", 0f, 2f) { showInputField = true };
                bounceSlider.value = anim.Bounce;
                bounceSlider.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Animation Bounce", () => anim.Bounce = evt.newValue);
                });
                FlushValueEditOnBlur(bounceSlider);
                card.Add(bounceSlider);
            }
            else
            {
                var easingField = new EnumField("Easing", anim.Easing);
                easingField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Animation Easing");
                    anim.Easing = (AnimEasing)evt.newValue;
                    OnModification();
                });
                card.Add(easingField);
            }

            if (anim.Effect == AnimEffect.ColorPulse)
            {
                var colorField = new ColorField("Pulse Color");
                colorField.value = anim.PulseColor;
                colorField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Pulse Color", () => anim.PulseColor = evt.newValue);
                });
                FlushValueEditOnBlur(colorField);
                card.Add(colorField);
            }

            return card;
        }

        // Plays the node's animations on its actual card in the canvas so you can preview them
        // without leaving design mode.
        private void PreviewAnimations(LayoutNode node)
        {
            if (_canvasContent == null || node?.Animations == null) return;
            VisualElement target = null;
            _canvasContent.Query<VisualElement>()
                .Where(e => e.userData is LayoutNode ln && ln == node)
                .ForEach(e => { if (target == null) target = e; });
            if (target == null) return;
            foreach (var anim in node.Animations) AnimationBinder.Play(target, anim);
        }

        private void RefreshProperties()
        {

            if (_propertiesContainer == null) return;
            // Spring every action button in the rebuilt panel (deferred so the new buttons exist first).
            _propertiesContainer.schedule.Execute(() => ApplyOptionButtonSprings(_propertiesContainer)).ExecuteLater(1);
            // "Same panel" = same primary node AND same multi-selection set, so multi-edit tweaks
            // (which rebuild the panel) keep the scroll position exactly like single-node edits do.
            bool sameNode = (_selectedNode == _lastPropertiesNode)
                && (_lastPropertiesSelection == null
                    ? _selectedNodes.Count <= 1
                    : _lastPropertiesSelection.SetEquals(_selectedNodes));
            _lastPropertiesNode = _selectedNode;
            _lastPropertiesSelection = new HashSet<LayoutNode>(_selectedNodes);

            // A genuine node change resets the active property search (the bar stays open for the new node); a
            // same-node rebuild keeps the query so it re-applies below. Mirrors the inspector's per-target reset.
            if (!sameNode) _propertiesSearchQuery = "";

            // Open "T" text-style boxes belong to the node whose panel they were opened on. A same-node
            // rebuild (a save, an edit that re-runs the panel, a preset apply) re-opens them; genuinely
            // moving to another node starts them closed.
            if (!sameNode) _openTextStylePanels.Clear();

            // The Tab Organizer only exists while a Tabs container is selected — drop its drag-only
            // selection whenever Properties shows anything else.
            if (!(_selectedNode is ContainerNode tabsSel && tabsSel.Type == ContainerType.Tabs))
                _organizerSelection.Clear();
            var scrollPos = sameNode ? CaptureScrollOffset(_propertiesContainer) : Vector2.zero;
            _propertiesContainer.Clear();

            if (_selectedNode == null)
            {
                var lbl = new Label("Select a node from the tree to modify its properties.");
                lbl.style.paddingTop = 15;
                lbl.style.color = DesignerPalette.TextDisabled;
                _propertiesContainer.Add(lbl);
                ReapplyPropertiesSearchAfterRebuild();
                return;
            }

            // A multi-selection is offered as much of this panel as its nodes provably have in common —
            // MultiEditTier. The top tier does NOT get a second, smaller hand-written panel: it falls through
            // and builds the REAL one against the last-clicked node, with MultiEditMirror fanning each edit out
            // to the rest and FinishMultiEditFullPanel (at the bottom of this method) stripping the rows that
            // can only mean one node. Arming here — on every rebuild, and a rebuild follows every selection
            // change — is what stops a mirror outliving the panel it belongs to.
            //
            // The LOWER tiers take the same bargain for the four sections that do not depend on a node's type at
            // all — Conditionals, Animations, Prefix & Suffix, Validation. They reuse the real single-node
            // builders (see AppendMultiEditSharedSections) and arm the mirror with a SCOPE limited to those
            // sections' fields, so nothing else fans out just because the panel got bigger.
            var multiTier = GetMultiEditTier();
            ArmMultiEditMirror(multiTier);

            if (multiTier == MultiEditTier.MixedKinds || multiTier == MultiEditTier.SameKind)
            {
                BuildMultiEditPanel(multiTier);
                AppendAnimationsSection();
                RestoreScrollOffsetRobust(_propertiesContainer, scrollPos);
                ReapplyPropertiesSearchAfterRebuild();
                // LAST, exactly as the top tier does it — so an identity row stays hidden even while the search
                // above is filtering the panel, and so the animations section is covered too.
                HideMultiEditIdentityRows();
                return;
            }

            // Preset Editor: say up front why the content rows aren't here. Without it their absence reads as a
            // missing feature rather than the rule it is (manual.html §2.7 is the long version).
            if (_presetMode)
            {
                var presetNote = new Label(
                    "Presets carry styling only — text, methods, icons, images and bindings stay with each widget you drop.");
                presetNote.style.whiteSpace = WhiteSpace.Normal;
                presetNote.style.fontSize = 10f;
                presetNote.style.color = DesignerPalette.TextDisabled;
                presetNote.style.marginBottom = 6;
                _propertiesContainer.Add(presetNote);
            }

            // General section
            var generalSection = CreateFoldoutHeader("General Settings");

            // Visible in Inspector — the properties-panel twin of the eye on the node's Hierarchy row, and the
            // FIRST row in the section because it decides whether any of the rows under it will be seen at all.
            //
            // Sits here, above every `is BindingNode` / `is ContainerNode` branch, precisely because this is the
            // section's only kind-agnostic run: one row then covers all 14 node kinds with no per-kind wiring.
            //
            // Phrased positively (checked = shown) so it reads the same direction as the eye — a "Hidden"
            // checkbox would make every glance a double negative.
            //
            // NOT wrapped in Identity(): hiding is not per-node identity, so it deliberately FANS OUT across a
            // multi-selection (select five fields, uncheck once, all five go). Its data twin is the absence of
            // "hiddenInInspector" from MultiEditMirror.IdentityFields — keep the two decisions together.
            //
            // Never on the root (there would be no row left to bring it back from — that is the toolbar eye's
            // job) and never in the Preset Editor: a preset carries styling, and LayoutPresetApplier.
            // ClearIdentity strips the flag on capture for exactly that reason.
            bool generalIsRootNode = _clonedLayoutAsset != null && _selectedNode == _clonedLayoutAsset.Root;
            // …and never on a dictionary CELL TEMPLATE: the drawer builds its cells outside BuildNode, which
            // is where the hidden-node skip lives, so the flag would be a checkbox that changes nothing. See
            // IsDictionaryCellTemplate for the full list this gate belongs to.
            if (!_presetMode && !generalIsRootNode && !IsDictionaryCellTemplate(_selectedNode))
            {
                generalSection.Add(CreateAllowAdjustToggle(
                    "Visible in Inspector",
                    "Off = this element (and anything inside it) is not drawn in the real Inspector at all, and " +
                    "everything around it closes up exactly as if it were deleted. It stays here in the designer, " +
                    "dimmed, so you can bring it back at any time.",
                    () => !_selectedNode.HiddenInInspector,
                    v => _selectedNode.HiddenInInspector = !v,
                    // The canvas rebuild is RefreshPreview's job; the row's grey-out and eye glyph are the
                    // hierarchy's, and only a full RenderTree pass repaints those.
                    after: RefreshHierarchy));
            }

            // NOTE: LayoutNode.StyleToken is deliberately NOT surfaced here. The property + its serialization
            // are retained as the hook for a future theme system, but with no theme asset behind it the field
            // would do nothing — re-expose it inside the Themes UI when that lands.

            // "Display Style/Options" is its own top-level section: built in the BindingNode branch, assigned
            // here, and added to _propertiesContainer directly above Appearance.
            VisualElement displayStyleSection = null;

            // The Tab Organizer kanban (built in the Tabs branch, added right below General Settings).
            VisualElement tabOrganizerSection = null;

            // Extra top-level sections a type branch can contribute, added in order directly below General
            // Settings. Only a CollectionNode uses this today: it carries ~17 options, and a single flat column
            // of them was unreadable, so they are split into Rows / Search, Sort & Paging / In-Line Editors /
            // Polymorphic Menu. They are separate PEER sections (not nested foldouts) so each one collapses on
            // its own and reads the same as Appearance / Spacing / Conditionals — to the eye and to the
            // Properties search, which classifies any Foldout as a section trail.
            List<VisualElement> extraSections = null;

            // Appearance ▸ Background Color is a DEAD control once a node renders as our collapsible group
            // shell — .sasq-group-header / .sasq-group-content paint opaque fills over the root, so the color
            // is never visible (LayoutTreeBuilder.RendersAsOpaqueGroupShell). The row is therefore hidden for
            // those nodes. "Expandable" is a plain toggle that does NOT rebuild this panel, so the gate has to
            // be re-runnable: the Appearance builder below assigns this, and every toggle that can flip a node
            // in or out of the shell calls it. Null-safe — the branches run before the assignment.
            Action syncGroupShellGatedRows = null;

            // Tooltip is shown for non-container nodes. BindingNode renders its Tooltip in a specific slot
            // below (after Label, per the panel ordering), so the shared Tooltip here is only for the other
            // non-container types (Button / HelpBox / Collection).
            // Never in the Preset Editor: LayoutNode.Tooltip is content, stripped by ClearIdentity and absent
            // from every StyleClipboard transfer list — see BuildPresetTextStyleRow.
            if (!_presetMode
                && !(_selectedNode is ContainerNode) && !(_selectedNode is BindingNode) && !(_selectedNode is SpaceNode)
                && !(_selectedNode is LabeledDividerNode) && !(_selectedNode is ImageBannerNode)
                && !(_selectedNode is TextBlockNode))
            {
                // Tooltip: the code [Tooltip] shows greyed as the default; type to override, clear it to hide
                // the tooltip entirely (no fallback to code), and the reset arrow restores the code default.
                generalSection.Add(Identity(BuildOverridableField(
                    "Tooltip",
                    _selectedNode.Tooltip,
                    ResolveCodeTooltip(_selectedNode),
                    "Change Tooltip",
                    v => _selectedNode.Tooltip = v,
                    refreshHierarchy: false,
                    debounceText: true)));
            }

            if (_selectedNode is BindingNode bindingNode)
            {
                var targetType = ResolveTargetType();

                // An ELEMENT TEMPLATE has no path by definition — the empty path IS what makes it bind the
                // collection's element — so it gets a read-only statement of what it binds instead of the
                // editable Property Path below. An editable field there would show blank, invite a value,
                // and quietly turn the template into an ordinary (broken) sub-field binding.
                var templateOwner = string.IsNullOrEmpty(bindingNode.PropertyPath)
                    ? FindOwningCollection(bindingNode) : null;
                if (!_presetMode && templateOwner != null)
                {
                    var elemType = ResolveCollectionElementType(templateOwner);
                    var bindsRow = new TextField("Binds")
                    {
                        value = elemType != null
                            ? $"one {SasquatchReflectionUtility.GetFriendlyTypeName(elemType)} of \"{templateOwner.PropertyPath}\""
                            : $"one element of \"{templateOwner.PropertyPath}\""
                    };
                    bindsRow.SetEnabled(false);
                    bindsRow.tooltip =
                        "This binding IS the element. Every row of the list renders with the widget and " +
                        "styling you give it here.";
                    generalSection.Add(Identity(bindsRow));
                }
                // Property Path — the binding's identity, and the ONE field the Preset Editor must never show:
                // ClearIdentity nulls it on capture, and the path showing there belongs to the synthetic
                // PresetSampleObject field driving the preview, so editing it would only break the preview.
                else if (!_presetMode)
                {
                    var pathField = new TextField("Property Path");
                    pathField.value = bindingNode.PropertyPath;
                    pathField.RegisterValueChangedCallback(evt =>
                        HandleDebouncedTextEdit("Change Property Path", () => bindingNode.PropertyPath = evt.newValue,
                            refreshHierarchy: true, refreshTokens: true));
                    FlushTextEditOnBlur(pathField);
                    AutocompleteTextField.Attach(pathField, () =>
                    {
                        var pathTargetType = ResolveTargetType();
                        if (pathTargetType == null) return Array.Empty<string>();
                        var all = SasquatchReflectionUtility.GetSerializableProperties(pathTargetType);
                        // Bindings store paths relative to their scope. Suggest paths for the node's scope:
                        // inside a collection item / scoped container, offer element-relative names ("modName");
                        // at top level, offer non-collection leaf fields (excluding collection element fields).
                        string basePath = GetEffectiveBasePath(bindingNode, _clonedLayoutAsset?.Root, "") ?? "";
                        if (!string.IsNullOrEmpty(basePath))
                        {
                            string prefix = basePath + ".";
                            return all.Where(p => !p.isCollection && p.path.StartsWith(prefix))
                                      .Select(p => p.path.Substring(prefix.Length));
                        }
                        var collPrefixes = all.Where(p => p.isCollection).Select(p => p.path + ".").ToList();
                        return all.Where(p => !p.isCollection && !collPrefixes.Any(cp => p.path.StartsWith(cp)))
                                  .Select(p => p.path);
                    }, s => FieldPathSnippet(s.Value, GetEffectiveBasePath(bindingNode, _clonedLayoutAsset?.Root, "")));
                    generalSection.Add(Identity(pathField));
                }

                // Curated widget list, filtered to the kinds that actually apply to this binding's field
                // type (e.g. a bool offers only Default + Toggle). Shares the resolver + catalog with the
                // inspector quick-edit popup. A kind that no longer fits the field's CODE type (e.g. the
                // field changed Color → Gradient while the node still says ColorPalette) drops out of the
                // list; an unresolvable type returns the unfiltered list (current retained) rather than
                // hiding options on a bad guess.
                var offeredWidgets = DisplayTypeCatalog.OfferedForField(
                    bindingNode.DisplayType, ResolveSelectedNodeFieldType(bindingNode));

                // The stored kind may not be offered (a stale SpringConfig value from a prior version, or a
                // widget orphaned by a field-type change as above). PopupField throws if its default isn't
                // in the list, so fall back to the first offered kind and persist that correction on the node.
                var currentWidget = offeredWidgets.Contains(bindingNode.DisplayType) ? bindingNode.DisplayType : offeredWidgets[0];
                if (currentWidget != bindingNode.DisplayType) bindingNode.DisplayType = currentWidget;

                // "Something else already draws this field" — see CustomDrawerNoticeRow. Null (and skipped)
                // for the overwhelming majority of fields, which nothing but Unity draws.
                var drawerNotice = CustomDrawerNoticeRow.TryCreate(
                    ResolveSelectedNodeFieldInfo(bindingNode, out _), currentWidget);

                var widgetField = new PopupField<DisplayType>("Display Type", offeredWidgets, currentWidget, FormatDisplayType, FormatDisplayType);
                widgetField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Display Type");
                    bindingNode.DisplayType = evt.newValue;
                    if (evt.newValue == DisplayType.ProgressBar)
                    {
                        bindingNode.ProgressBarInteractive = true;
                    }
                    // This panel is not rebuilt on a Display Type change, so the notice has to re-render
                    // itself — the warning must appear on the SAME interaction that causes it.
                    drawerNotice?.Sync(evt.newValue);
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(widgetField);
                if (drawerNotice != null) generalSection.Add(drawerNotice);

                // Header — an optional bold section header above the field. The code [Header] shows greyed as
                // the default; type to override, clear it to hide the header (suppresses the code one too), and
                // the reset arrow restores the default.
                // In the Preset Editor the TEXT is stripped by ClearIdentity while HeaderTextStyle travels, so
                // only the "T" survives — a header a preset can style still arrives, from a script's [Header].
                if (_presetMode)
                    generalSection.Add(BuildPresetTextStyleRow("Header",
                        "styles a [Header] when one is imported",
                        () => bindingNode.HeaderTextStyle, v => bindingNode.HeaderTextStyle = v, "header"));
                else
                    generalSection.Add(Identity(WithTextButton(BuildOverridableField(
                        "Header",
                        bindingNode.Header,
                        ResolveCodeHeader(_selectedNode),
                        "Change Field Header",
                        v => bindingNode.Header = v,
                        refreshHierarchy: true,
                        fieldTooltip: "Optional bold section header rendered above this field (like a C# [Header]). Clear it to hide the header.",
                        debounceText: true, liveRebuild: true),
                        () => bindingNode.HeaderTextStyle, v => bindingNode.HeaderTextStyle = v, "header")));

                // Label — the code-derived label (nicified field name) shows greyed as the default; type to
                // override, clear it to hide the label entirely, and the reset arrow restores the default.
                // (Replaces the old explicit "Hide Label" toggle.) Styling-only in the Preset Editor, as Header.
                if (_presetMode)
                    generalSection.Add(BuildPresetTextStyleRow("Label",
                        "each field keeps its own label text",
                        () => bindingNode.LabelTextStyle, v => bindingNode.LabelTextStyle = v, "label"));
                else
                    generalSection.Add(Identity(WithTextButton(BuildOverridableField(
                        "Label",
                        bindingNode.LabelOverride,
                        ResolveCodeLabel(_selectedNode),
                        "Change Label Override",
                        v => bindingNode.LabelOverride = v,
                        refreshHierarchy: true,
                        fieldTooltip: "The field's label. Clear it to hide the label entirely.",
                        debounceText: true, liveRebuild: true),
                        () => bindingNode.LabelTextStyle, v => bindingNode.LabelTextStyle = v, "label")));

                // Label Above — stack the label on its own row above the field instead of the left label column.
                // Hidden for the Display Types it cannot reach (a card, a graph well): see
                // DisplayTypeCatalog.SupportsLabelAbove. The row is built either way and only its display is
                // flipped, because the second widgetField callback below has to be able to bring it back when
                // the user switches Display Type — this panel is NOT rebuilt on that change.
                var labelAboveToggle = new Toggle("Label Above Field");
                labelAboveToggle.value = bindingNode.LabelAbove;
                labelAboveToggle.style.display = DisplayTypeCatalog.SupportsLabelAbove(
                        bindingNode.DisplayType, ResolveSelectedNodeFieldType(bindingNode))
                    ? DisplayStyle.Flex : DisplayStyle.None;
                labelAboveToggle.tooltip = "Put the field's label on its own row above the field instead of in the inspector's left label column.";
                labelAboveToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Label Above Field");
                    bindingNode.LabelAbove = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(labelAboveToggle);

                // Tooltip — rendered here (after Label) per the panel ordering. The code [Tooltip] shows greyed
                // as the default; type to override, clear it to hide the tooltip entirely (no fallback to code),
                // and the reset arrow restores the code default. Content — never in the Preset Editor.
                if (!_presetMode)
                    generalSection.Add(Identity(BuildOverridableField(
                        "Tooltip",
                        _selectedNode.Tooltip,
                        ResolveCodeTooltip(_selectedNode),
                        "Change Tooltip",
                        v => _selectedNode.Tooltip = v,
                        refreshHierarchy: false,
                        debounceText: true)));

                var isReadOnlyField = new Toggle("Read-Only");
                isReadOnlyField.value = bindingNode.IsReadOnly;
                isReadOnlyField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Read-Only");
                    bindingNode.IsReadOnly = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(isReadOnlyField);

                // Add Help Chip — sits BELOW Read-Only. When on, reveals a Help Text box (expandable, with the
                // "T" text-styling button) and a Left/Right chip-placement picker.
                var addHelpChipToggle = new Toggle("Add Help Chip") { value = bindingNode.ShowHelpChip };
                addHelpChipToggle.tooltip = "Show a round \"?\" chip beside this field that reveals a help card (markdown + rich text tags).";

                var helpChipOptions = new VisualElement();
                helpChipOptions.style.display = bindingNode.ShowHelpChip ? DisplayStyle.Flex : DisplayStyle.None;

                var helpTextField = new TextField("Help Text") { value = bindingNode.HelpText };
                TextAreaHelper.MakeWrappingResizableTextArea(helpTextField); // wrapping + drag-to-resize (like Message)
                helpTextField.tooltip = "Help text; supports markdown (**bold**, *italics*, `code`, {Color|text}, " +
                    "[links](https://…)) and Unity rich text tags (<b>, <color=…>, <size=…>, …).";
                helpTextField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change Help Text", () => bindingNode.HelpText = evt.newValue));
                FlushTextEditOnBlur(helpTextField);
                helpChipOptions.Add(Identity(WithTextButton(helpTextField,
                    () => bindingNode.HelpTextStyle, v => bindingNode.HelpTextStyle = v, "helpText",
                    RichTextFormattingHelp)));

                helpChipOptions.Add(BuildImageAlignmentRow("Chip Placement",
                    () => bindingNode.HelpChipAlignment, v => bindingNode.HelpChipAlignment = v,
                    "Change Help Chip Placement", includeCenter: false, defaultValue: ImageAlignment.Right));

                addHelpChipToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Add Help Chip");
                    bindingNode.ShowHelpChip = evt.newValue;
                    helpChipOptions.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(addHelpChipToggle);
                generalSection.Add(helpChipOptions);

                // When the AssetPreview widget is chosen the preview is implied, so the legacy "Show Asset
                // Preview" toggle has been removed, and the settings are shown when AssetPreview is active.
                bool isAssetPreviewWidget = bindingNode.DisplayType == DisplayType.AssetPreview;

                var previewSettingsContainer = new VisualElement();
                previewSettingsContainer.style.display = isAssetPreviewWidget ? DisplayStyle.Flex : DisplayStyle.None;

                // Preview Mode
                var previewModeField = new EnumField("Preview Mode", bindingNode.AssetPreviewMode);
                previewModeField.tooltip = "Standard: object field + thumbnail. Thumbnail Only: just the image (with alignment).";
                previewSettingsContainer.Add(previewModeField);

                // Thumbnail Size
                var sizeRow = new VisualElement();
                sizeRow.AddToClassList("unity-base-field");
                sizeRow.style.flexDirection = FlexDirection.Row;
                sizeRow.style.alignItems = Align.Center;
                sizeRow.style.marginBottom = 2;
                sizeRow.style.display = DisplayStyle.Flex;

                var sizeLabel = new Label("Thumbnail Size");
                sizeLabel.AddToClassList("unity-base-field__label");
                sizeRow.Add(sizeLabel);

                var sizeControlsContainer = new VisualElement();
                sizeControlsContainer.AddToClassList("unity-base-field__input");
                sizeControlsContainer.style.flexDirection = FlexDirection.Row;
                sizeControlsContainer.style.alignItems = Align.Center;
                sizeControlsContainer.style.flexGrow = 1;

                var previewSizeSlider = new Slider(16f, 128f);
                previewSizeSlider.value = bindingNode.PreviewSize;
                previewSizeSlider.style.flexGrow = 1;
                previewSizeSlider.style.marginRight = 4;

                var previewSizeField = new FloatField();
                previewSizeField.value = bindingNode.PreviewSize;
                previewSizeField.isDelayed = true;
                previewSizeField.style.width = 45;
                previewSizeField.style.marginLeft = 0;
                previewSizeField.style.marginRight = 0;
                previewSizeField.style.paddingLeft = 2;
                previewSizeField.style.paddingRight = 2;

                previewSizeSlider.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Thumbnail Size", () =>
                    {
                        bindingNode.PreviewSize = evt.newValue;
                        previewSizeField.SetValueWithoutNotify(evt.newValue);
                    }, liveRebuild: true);
                });
                FlushValueEditOnBlur(previewSizeSlider);

                previewSizeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Thumbnail Size");
                    var clamped = Mathf.Clamp(evt.newValue, 16f, 128f);
                    bindingNode.PreviewSize = clamped;
                    previewSizeSlider.SetValueWithoutNotify(clamped);
                    OnModification();
                    RefreshPreview();
                });
                SyncClampedDisplay(previewSizeField, () => bindingNode.PreviewSize);

                sizeControlsContainer.Add(previewSizeSlider);
                sizeControlsContainer.Add(previewSizeField);
                sizeRow.Add(sizeControlsContainer);
                previewSettingsContainer.Add(sizeRow);

                // Preview Placement — where the thumbnail sits relative to the object field (Standard mode).
                var previewPlacementField = BuildPlacementButtonRow<ElementPlacement>(
                    "Preview Placement",
                    new (string, ElementPlacement, string)[]
                    {
                        (SasquatchIcons.Ids.ArrowLeft, ElementPlacement.Left, "Thumbnail on the left, sharing the field's row"),
                        (SasquatchIcons.Ids.ArrowUp, ElementPlacement.Above, "Thumbnail above the field"),
                        (SasquatchIcons.Ids.ArrowRight, ElementPlacement.Right, "Thumbnail on the right, sharing the field's row (default)"),
                        (SasquatchIcons.Ids.ArrowDown, ElementPlacement.Below, "Thumbnail below the field"),
                    },
                    () => bindingNode.PreviewPlacement,
                    v => bindingNode.PreviewPlacement = v,
                    ElementPlacement.Right,
                    "Change Preview Placement");
                previewPlacementField.style.display = bindingNode.AssetPreviewMode == AssetPreviewMode.Standard ? DisplayStyle.Flex : DisplayStyle.None;
                previewSettingsContainer.Add(previewPlacementField);

                // Preview Alignment (Thumbnail Only positions the thumbnail; Expandable aligns the preview in the fold)
                var alignRow = new VisualElement();
                alignRow.AddToClassList("unity-base-field");
                alignRow.style.flexDirection = FlexDirection.Row;
                alignRow.style.alignItems = Align.Center;
                alignRow.style.marginBottom = 2;
                alignRow.style.display = (bindingNode.AssetPreviewMode == AssetPreviewMode.ThumbnailOnly || bindingNode.AssetPreviewMode == AssetPreviewMode.Expandable)
                    ? DisplayStyle.Flex : DisplayStyle.None;

                var alignLabel = new Label("Preview Alignment");
                alignLabel.AddToClassList("unity-base-field__label");
                alignRow.Add(alignLabel);

                var alignButtonsContainer = new VisualElement();
                alignButtonsContainer.AddToClassList("unity-base-field__input");
                alignButtonsContainer.style.flexDirection = FlexDirection.Row;
                alignButtonsContainer.style.alignItems = Align.Center;
                alignButtonsContainer.style.justifyContent = Justify.FlexEnd;
                alignButtonsContainer.style.flexGrow = 1;

                var previewAlignments = new[]
                {
                    (icon: SasquatchIcons.Ids.AlignStartVertical, value: ImageAlignment.Left, tooltip: "Align preview left"),
                    (icon: SasquatchIcons.Ids.AlignCenterVertical, value: ImageAlignment.Center, tooltip: "Align preview center"),
                    (icon: SasquatchIcons.Ids.AlignEndVertical, value: ImageAlignment.Right, tooltip: "Align preview right")
                };

                var alignButtons = new List<Button>();
                void SyncPreviewAlignment()
                {
                    for (int i = 0; i < previewAlignments.Length; i++)
                    {
                        bool active = bindingNode.PreviewAlignment == previewAlignments[i].value;
                        alignButtons[i].style.backgroundColor = active ? DesignerPalette.AccentFillSoft : DesignerPalette.ButtonNeutralBg;
                        alignButtons[i].Q<SasquatchIconElement>().Tint = active ? Color.white : DesignerPalette.IconIdle;
                    }
                }

                for (int i = 0; i < previewAlignments.Length; i++)
                {
                    var alignVal = previewAlignments[i].value;
                    var btn = new Button();
                    btn.Add(SasquatchIcons.Create(previewAlignments[i].icon, 13, DesignerPalette.IconIdle));
                    btn.tooltip = previewAlignments[i].tooltip;
                    btn.style.width = 24;
                    btn.style.height = 18;
                    btn.style.paddingLeft = 0;
                    btn.style.paddingRight = 0;
                    btn.style.marginLeft = 2;
                    btn.style.marginRight = 0;
                    btn.style.alignItems = Align.Center;
                    btn.style.justifyContent = Justify.Center;

                    btn.clicked += () =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Preview Alignment");
                        bindingNode.PreviewAlignment = alignVal;
                        OnModification();
                        RefreshPreview();
                        SyncPreviewAlignment();
                    };
                    AddSegmentedHover(btn, () => bindingNode.PreviewAlignment == alignVal, SyncPreviewAlignment);
                    alignButtons.Add(btn);
                    alignButtonsContainer.Add(btn);
                }
                SyncPreviewAlignment();
                alignRow.Add(alignButtonsContainer);
                previewSettingsContainer.Add(alignRow);

                // Interactive (orbit / pan / zoom) — a live 3D viewport for prefabs & meshes (other asset types keep
                // the static thumbnail). Only the hovered preview renders; the rest stay idle.
                var assetInteractiveToggle = new Toggle("Interactive (orbit/pan/zoom)");
                assetInteractiveToggle.tooltip = "Drag to orbit, middle-drag to pan, Alt+scroll to zoom a prefab or mesh. " +
                                            "Only the hovered preview renders at a time. Other asset types stay static.";
                assetInteractiveToggle.value = bindingNode.AssetPreviewInteractive;
                assetInteractiveToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Interactive Asset Preview");
                    bindingNode.AssetPreviewInteractive = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                previewSettingsContainer.Add(assetInteractiveToggle);

                previewModeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Preview Mode");
                    bindingNode.AssetPreviewMode = (AssetPreviewMode)evt.newValue;
                    var mode = bindingNode.AssetPreviewMode;
                    // Size applies to all modes; "below field" is Standard-only; alignment applies to Thumbnail Only
                    // (positions the thumbnail) and Expandable (aligns the preview in the fold body).
                    sizeRow.style.display = DisplayStyle.Flex;
                    previewPlacementField.style.display = mode == AssetPreviewMode.Standard ? DisplayStyle.Flex : DisplayStyle.None;
                    alignRow.style.display = (mode == AssetPreviewMode.ThumbnailOnly || mode == AssetPreviewMode.Expandable)
                        ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                    RefreshPreview();
                });



                // Min/Max range fields — shown for the widgets whose bounds the designer owns: MinMaxSlider,
                // ProgressBar, and now the plain Slider (whose bounds otherwise came ONLY from a code [Range]).
                var minMaxContainer = new VisualElement();
                minMaxContainer.style.display = (bindingNode.DisplayType == DisplayType.MinMaxSlider || bindingNode.DisplayType == DisplayType.ProgressBar || bindingNode.DisplayType == DisplayType.Slider) ? DisplayStyle.Flex : DisplayStyle.None;

                float defaultMin = 0f;
                float defaultMax = 100f;
                if (targetType != null && !string.IsNullOrEmpty(bindingNode.PropertyPath))
                {
                    var fi = ResolveSelectedNodeFieldInfo(bindingNode, out _);
                    if (fi != null)
                    {
                        // A plain Slider mirrors BindingFactory.Slider's OWN fallback bounds, so the "default"
                        // shown here matches what the slider actually uses when unset: 0..1 for a float/double
                        // slider, 0..100 for an int one (the pre-existing default carried by defaultMax).
                        if (bindingNode.DisplayType == DisplayType.Slider
                            && (fi.FieldType == typeof(float) || fi.FieldType == typeof(double)))
                        {
                            defaultMax = 1f;
                        }
                        // [Range] seeds these defaults for the numeric Progress Bar / Slider. The Min-Max Slider is
                        // a Vector2 — Unity can't draw [Range] on it — so it ignores the attribute and shows the
                        // plain default, its bounds set here in the designer instead.
                        var rangeAttr = Attribute.GetCustomAttribute(fi, typeof(RangeAttribute)) as RangeAttribute;
                        if (rangeAttr != null && fi.FieldType != typeof(Vector2) && fi.FieldType != typeof(Vector2Int))
                        {
                            defaultMin = rangeAttr.min;
                            defaultMax = rangeAttr.max;
                        }
                    }
                }

                var lowLimitField = BuildOverridableFloatField(
                    "Range Min",
                    bindingNode.RangeMin,
                    defaultMin,
                    "Change Range Min",
                    val => bindingNode.RangeMin = val,
                    RefreshPreview
                );
                minMaxContainer.Add(lowLimitField);

                var highLimitField = BuildOverridableFloatField(
                    "Range Max",
                    bindingNode.RangeMax,
                    defaultMax,
                    "Change Range Max",
                    val => bindingNode.RangeMax = val,
                    RefreshPreview
                );
                minMaxContainer.Add(highLimitField);

                generalSection.Add(minMaxContainer);

                var displayStyleFoldout = new Foldout();
                SasquatchIcons.SkinFoldout(displayStyleFoldout);
                Action updateDisplayStyleFoldoutVisibility = () =>
                {
                    if (displayStyleFoldout == null) return;
                    bool anyVisible = false;
                    foreach (var child in displayStyleFoldout.contentContainer.Children())
                    {
                        if (child.style.display != DisplayStyle.None)
                        {
                            anyVisible = true;
                            break;
                        }
                    }
                    displayStyleFoldout.style.display = anyVisible ? DisplayStyle.Flex : DisplayStyle.None;
                };

                // The way IN to the embedded script's own layout, pinned to the TOP of this section: it is a
                // NAVIGATION action, not another style toggle, so burying it between two checkboxes read as
                // misfiled. Hides itself when the node embeds nothing, so it never offers a dead end. The
                // hierarchy/canvas right-click is the fast path; this is the discoverable one. See
                // SasquatchLayoutDesignerWindow.Navigation.cs.
                displayStyleFoldout.Add(BuildInlineEditorDrillInRow(bindingNode));

                VisualElement searchableContainer = null;
                VisualElement polymorphicSearchableContainer = null;
                var targetTypeForDropdown = ResolveTargetType();

                // DropDown widget options — the unified Tag/Layer/Enum/Method dropdown. Shown only
                // when DisplayType == DropDown. Source decides what fills it (Auto picks by field type); the Method
                // field appears only for Source == Method; Searchable applies ONLY to the enum/method sources
                // (the Tags/Layer popups are shown without a search box), so it hides for Tags/Layers.
                var dropDownContainer = new VisualElement();
                dropDownContainer.style.display = bindingNode.DisplayType == DisplayType.DropDown ? DisplayStyle.Flex : DisplayStyle.None;

                // Resolve the bound field's type so we know which sub-controls are relevant.
                bool ddIsEnum = false, ddIsString = false, ddIsInt = false, ddIsLayerMask = false;
                var ddTargetType = ResolveTargetType();
                if (ddTargetType != null && !string.IsNullOrEmpty(bindingNode.PropertyPath))
                {
                    var ddFieldType = ResolveSelectedNodeFieldType(bindingNode);
                    if (ddFieldType != null)
                    {
                        ddIsEnum = ddFieldType.IsEnum;
                        ddIsString = ddFieldType == typeof(string);
                        ddIsInt = ddFieldType == typeof(int) || ddFieldType == typeof(long);
                        ddIsLayerMask = ddFieldType == typeof(LayerMask) || ddFieldType == typeof(UnityEngine.LayerMask);
                    }
                }

                // Mirrors BindingFactory.CreateDropDown's Auto resolution (string→Tags, int→Layer): Searchable
                // is meaningful only when the EFFECTIVE source is enum or method.
                bool DropdownSearchableApplies()
                {
                    switch (bindingNode.DropdownSource)
                    {
                        case DropdownSource.Tags:
                        case DropdownSource.Layer:
                        case DropdownSource.LayerMask:
                            return false;
                        case DropdownSource.Method:
                            return true;
                        default: // Auto
                            if (ddIsEnum) return true;
                            return !(ddIsString || ddIsInt); // string→Tags / int→Layer hide it; else→Method shows it
                    }
                }

                var choices = new List<DropdownSource>();
                if (ddIsEnum)
                {
                    // No choices, source selector not needed
                }
                else if (ddIsString)
                {
                    choices.Add(DropdownSource.Auto);
                    choices.Add(DropdownSource.Tags);
                    choices.Add(DropdownSource.Method);
                }
                else if (ddIsInt)
                {
                    choices.Add(DropdownSource.Auto);
                    choices.Add(DropdownSource.Layer);
                    choices.Add(DropdownSource.Method);
                }
                else if (ddIsLayerMask)
                {
                    choices.Add(DropdownSource.Auto);
                    choices.Add(DropdownSource.LayerMask);
                }
                else
                {
                    choices.Add(DropdownSource.Auto);
                    choices.Add(DropdownSource.Method);
                }

                if (!choices.Contains(bindingNode.DropdownSource) && choices.Count > 0)
                {
                    bindingNode.DropdownSource = choices[0];
                }

                var dropdownMethodContainer = new VisualElement();
                dropdownMethodContainer.style.display = bindingNode.DropdownSource == DropdownSource.Method ? DisplayStyle.Flex : DisplayStyle.None;
                var dropdownMethodField = new TextField("Value Source Method");
                dropdownMethodField.tooltip = "A parameterless method on the target returning a collection (IEnumerable) of options — e.g. IEnumerable<string> GetCategories(). Instance or static.";
                dropdownMethodField.value = bindingNode.ValueSourceMethod;
                dropdownMethodField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change Value Source Method", () => bindingNode.ValueSourceMethod = evt.newValue));
                Identity(dropdownMethodField);
                FlushTextEditOnBlur(dropdownMethodField);
                AutocompleteTextField.Attach(dropdownMethodField, () =>
                {
                    var t = ResolveTargetType();
                    return t != null ? GetValueSourceMethodNames(t) : Array.Empty<string>();
                }, s => MethodSourcePreview.GetSnippet(ResolveTargetType(), s.Value));
                dropdownMethodContainer.Add(dropdownMethodField);

                string FormatDropdownSource(DropdownSource val)
                {
                    if (val == DropdownSource.LayerMask) return "Layer Mask";
                    return val.ToString();
                }

                VisualElement dropdownSourceFieldElement = null;
                if (choices.Count > 0 && !ddIsEnum)
                {
                    var dropdownSourceField = new PopupField<DropdownSource>("Source", choices, bindingNode.DropdownSource, FormatDropdownSource, FormatDropdownSource);
                    dropdownSourceField.tooltip = "What fills the dropdown. Auto picks by field type (enum → its values, string → Tags, int → Layer, LayerMask → LayerMask). Tags/Layer pull Unity's project tag/layer lists; Method reads a named method (below).";
                    dropdownSourceField.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Dropdown Source");
                        bindingNode.DropdownSource = evt.newValue;
                        dropdownMethodContainer.style.display = bindingNode.DropdownSource == DropdownSource.Method ? DisplayStyle.Flex : DisplayStyle.None;
                        if (searchableContainer != null)
                        {
                            bool showSearchable = bindingNode.DisplayType == DisplayType.DropDown && DropdownSearchableApplies();
                            searchableContainer.style.display = showSearchable ? DisplayStyle.Flex : DisplayStyle.None;
                        }
                        updateDisplayStyleFoldoutVisibility();
                        OnModification();
                        RefreshPreview();
                    });
                    dropdownSourceFieldElement = dropdownSourceField;
                }

                if (dropdownSourceFieldElement != null)
                {
                    dropDownContainer.Add(dropdownSourceFieldElement);
                }
                dropDownContainer.Add(dropdownMethodContainer);

                // Text resize options (only show if Widget is Text)
                var textContainer = new VisualElement();
                textContainer.style.display = bindingNode.DisplayType == DisplayType.Text ? DisplayStyle.Flex : DisplayStyle.None;
                var textResizeField = new EnumField("Text Resize", bindingNode.TextResize);
                textResizeField.tooltip = "Resizable: forces the field multiline and adds a drag-to-resize handle. Fixed: respects standard Unity [TextArea] / [Multiline] layout without resize handles.";
                textResizeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Text Resize");
                    bindingNode.TextResize = (TextResizeMode)evt.newValue;
                    // Debounced preview rebuild only — a synchronous RefreshPreview here rebuilds the canvas
                    // mid-selection, which makes the dropdown click intermittently fail to commit. Same
                    // caveat as Display Mode / Reorder Style.
                    OnModification();
                });
                textContainer.Add(textResizeField);

                // Box Height (px) — an explicit height for the text box, honoured in BOTH resize modes.
                // 0 = auto (natural height, or the [TextArea]/[Multiline] box). This is the ONLY height
                // control a Fixed box has — it has no grip. A Resizable one can also be dragged by its grip,
                // and the drag writes this SAME field, so the row and the handle can never disagree.
                // No liveApply: the height feeds the grip strip, the min-height floors and the frame chord
                // fit, so a style poke would leave those stale — the debounced rebuild is the honest path.
                var textBoxHeightField = new Slider("Box Height", 0f, BindingFactory.TextBoxMaxHeight) { showInputField = true };
                textBoxHeightField.tooltip = "Explicit height of the text box in pixels; 0 = auto (its natural height, or the "
                                           + "[TextArea] / [Multiline] box). Applies in both Fixed and Resizable mode — on a "
                                           + "Resizable field, dragging the grip writes this same value. Anything at or below "
                                           + BindingFactory.TextBoxCollapseHeight + "px collapses back to auto.";
                textContainer.Add(CreateResettableNumberField<float>(
                    textBoxHeightField, 0f,
                    () => bindingNode.TextBoxHeight,
                    // TextBoxHeight is a RESIZE-CLASS field — without ClaimResizeAuthority, Save merges the
                    // registry's value back over this row and the typed height silently reverts. The setter is
                    // the shared funnel: CreateResettableNumberField's ↺ reset routes through it too.
                    v => { ClaimResizeAuthority(); bindingNode.TextBoxHeight = v; },
                    BindingFactory.ClampTextBoxHeight,
                    "Change Text Box Height"));

                var textHandleSizeField = new EnumField("Resize Handle Size", bindingNode.TextResizeHandleSize);
                textHandleSizeField.tooltip = "The size of the grip resize handle: Compact (centered pill), Large (first 35% with left margin), or FullWidth (full width with left/right margins).";

                var gripAlignmentField = new EnumField("Grip Alignment", bindingNode.GripAlignment);
                gripAlignmentField.tooltip = "Horizontal alignment of the grip inside the text box (Left, Center, or Right). Only applies to Compact and Large handle sizes.";
                gripAlignmentField.style.display = bindingNode.TextResizeHandleSize == TextResizeHandleSize.FullWidth ? DisplayStyle.None : DisplayStyle.Flex;
                gripAlignmentField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Grip Alignment");
                    bindingNode.GripAlignment = (GripAlignment)evt.newValue;
                    OnModification();
                });

                textHandleSizeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Resize Handle Size");
                    bindingNode.TextResizeHandleSize = (TextResizeHandleSize)evt.newValue;
                    gripAlignmentField.style.display = bindingNode.TextResizeHandleSize == TextResizeHandleSize.FullWidth ? DisplayStyle.None : DisplayStyle.Flex;
                    OnModification();
                });

                textContainer.Add(textHandleSizeField);
                textContainer.Add(gripAlignmentField);

                var textPlaceholderField = new TextField("Placeholder") { value = bindingNode.TextPlaceholder };
                textPlaceholderField.tooltip = "Greyed hint shown over the field while it's empty (like an HTML placeholder). Empty = none.";
                // Live per-keystroke feedback on the canvas (like every other text-editing row) with the undo/save
                // riding the debounce. liveRebuild rebuilds this node in place so the placeholder appears/updates as
                // you type instead of only committing on Enter/blur (the old isDelayed=true behavior).
                textPlaceholderField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change Text Placeholder", () => bindingNode.TextPlaceholder = evt.newValue,
                        liveRebuild: true));
                FlushTextEditOnBlur(textPlaceholderField);
                textContainer.Add(textPlaceholderField);

                // Path/Browse mode — Plain (a normal string field) or Path (adds a browse icon button). The folder/
                // filter sub-options only show in Path mode; the file filter only shows when browsing files.
                var pathFolderToggle = new Toggle("Browse Folders");
                pathFolderToggle.tooltip = "Browse for a folder instead of a file.";
                pathFolderToggle.style.marginLeft = 15;
                pathFolderToggle.value = bindingNode.PathIsFolder;

                var pathFilterField = new TextField("File Filter") { value = bindingNode.PathFilter, isDelayed = true };
                pathFilterField.tooltip = "Comma-separated extension filter for the file picker, e.g. \"png,jpg\". Empty = any file.";
                pathFilterField.style.marginLeft = 15;

                var pathModeField = new EnumField("Input Mode", bindingNode.TextPathMode);
                pathModeField.tooltip = "Plain: a normal string field. Path: adds a browse button that opens a file/folder panel.";
                void SyncPathRows()
                {
                    bool path = bindingNode.TextPathMode == TextPathMode.Path;
                    pathFolderToggle.style.display = path ? DisplayStyle.Flex : DisplayStyle.None;
                    pathFilterField.style.display = (path && !bindingNode.PathIsFolder) ? DisplayStyle.Flex : DisplayStyle.None;
                }
                pathModeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Text Input Mode");
                    bindingNode.TextPathMode = (TextPathMode)evt.newValue;
                    SyncPathRows();
                    OnModification();
                    RefreshPreview();
                });
                pathFolderToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Browse Folders");
                    bindingNode.PathIsFolder = evt.newValue;
                    SyncPathRows();
                    OnModification();
                    RefreshPreview();
                });
                pathFilterField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change File Filter");
                    bindingNode.PathFilter = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                textContainer.Add(pathModeField);
                textContainer.Add(pathFolderToggle);
                textContainer.Add(pathFilterField);
                SyncPathRows();

                // textContainer belongs to the Display Style/Options foldout below, not to generalSection.

                // Display Style/Options is its OWN top-level section (assigned to displayStyleSection and added
                // to _propertiesContainer directly above Appearance).
                displayStyleFoldout.text = "Display Style/Options";
                displayStyleFoldout.value = _displayStyleExpanded;
                displayStyleFoldout.style.marginTop = 10;
                displayStyleFoldout.style.unityFontStyleAndWeight = FontStyle.Bold;
                // Register on the foldout's OWN toggle (not the foldout) so child bool toggles inside the
                // content aren't mistaken for the foldout's expand state (see Appearance below).
                displayStyleFoldout.Q<Toggle>()?.RegisterValueChangedCallback(evt => _displayStyleExpanded = evt.newValue);

                displayStyleFoldout.Add(dropDownContainer);

                // Unified "Searchable" toggle at the top of Display Style/Options
                searchableContainer = new VisualElement();
                bool initialShowSearchable = bindingNode.DisplayType == DisplayType.DropDown && DropdownSearchableApplies();
                searchableContainer.style.display = initialShowSearchable ? DisplayStyle.Flex : DisplayStyle.None;

                var searchableToggle = new Toggle("Searchable");
                searchableToggle.tooltip = "Show a type-to-search box in the dropdown popup (offered for the enum and method sources only; the Tags/Layers popups are shown without a search box).";
                searchableToggle.value = bindingNode.SearchableDropdown;
                searchableToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Searchable");
                    bindingNode.SearchableDropdown = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                searchableContainer.Add(searchableToggle);
                displayStyleFoldout.Add(searchableContainer);

                // Searchable toggle for the Polymorphic (SerializeReference) type picker. Separate from the
                // dropdown searchable above (it binds to PolymorphicSearchable, which defaults ON).
                polymorphicSearchableContainer = new VisualElement();
                polymorphicSearchableContainer.style.display =
                    bindingNode.DisplayType == DisplayType.SerializeReference ? DisplayStyle.Flex : DisplayStyle.None;

                var polySearchableToggle = new Toggle("Searchable");
                polySearchableToggle.tooltip = "Show a type-to-search box in the polymorphic type picker.";
                polySearchableToggle.value = bindingNode.PolymorphicSearchable;
                polySearchableToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Searchable");
                    bindingNode.PolymorphicSearchable = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                polymorphicSearchableContainer.Add(polySearchableToggle);

                var polyPeekToggle = new Toggle("Code Peek");
                polyPeekToggle.tooltip = "Hovering a type in the picker previews its declaration.";
                polyPeekToggle.value = bindingNode.PolymorphicCodePeek;
                polyPeekToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Polymorphic Code Peek");
                    bindingNode.PolymorphicCodePeek = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
