                stepperStyleGroup.Add(stepRadiusRow);
                stepperStyleGroup.Add(stepSizeStyleField);
                stepperStyleGroup.Add(stepHoverAnimField);
                stepperStyleGroup.Add(stepHoverColorRow);
                stepperStyleGroup.Add(stepPressedColorRow);
                stepperStyleGroup.Add(stepPlusColorRow);
                stepperStyleGroup.Add(stepMinusColorRow);
                SyncStepperClassicRows();

                stepperToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Numeric Stepper");
                    bindingNode.ShowStepper = evt.newValue;
                    stepSizeField.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                    stepPlacementField.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                    stepperStyleGroup.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
