                bool colorOptionsApply = ResolveSelectedNodeFieldType(bindingNode) == typeof(Color);
                var colorFieldContainer = new VisualElement();
                colorFieldContainer.style.display =
                    ((bindingNode.DisplayType == DisplayType.Default || bindingNode.DisplayType == DisplayType.ColorPalette) && colorOptionsApply)
                        ? DisplayStyle.Flex : DisplayStyle.None;

                var colorModeField = new EnumField("Color Mode", bindingNode.ColorFieldMode);
                colorModeField.tooltip = "Default: a standard 0–1 color picker. HDR: an intensity-aware picker (like Shader Graph) whose color can exceed 1, for bloom / emissive values.";
                colorModeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Color Mode");
                    bindingNode.ColorFieldMode = (ColorFieldMode)evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                var colorShowAlphaToggle = new Toggle("Show Alpha") { value = bindingNode.ColorShowAlpha };
                colorShowAlphaToggle.tooltip = "Whether the alpha channel is editable in the color picker (imported from [ColorUsage]).";
                colorShowAlphaToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Color Show Alpha");
                    bindingNode.ColorShowAlpha = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                colorFieldContainer.Add(colorModeField);
                colorFieldContainer.Add(colorShowAlphaToggle);
                displayStyleFoldout.Add(colorFieldContainer);

                // Axis Color Pips — X/Y/Z-tinted markers inside each component field (Unity handle
                // convention). Offered on the Default widget for the whole vector family, and on Vector
                // Sliders, whose per-axis value boxes take the same pip (that widget only renders
                // Vector3/Vector4 — anything else falls back to a plain field with no components to dress).
                // Applicability resolved once per panel build, same pattern as the stepper.
                var axisPipsFieldType = ResolveSelectedNodeFieldType(bindingNode);
                var axisPipsContainer = new VisualElement();
                axisPipsContainer.style.display =
                    AxisPips.AppliesTo(bindingNode.DisplayType, axisPipsFieldType) ? DisplayStyle.Flex : DisplayStyle.None;
                var axisPipsToggle = new Toggle("Axis Color Pips");
                axisPipsToggle.tooltip = "Tint a small pip inside each component field — or, on Vector Sliders, each axis value box — with its axis color (X red, Y green, Z blue — Unity's handle convention; W stays neutral).";
                axisPipsToggle.value = bindingNode.VectorAxisPips;
                axisPipsToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Axis Color Pips");
                    bindingNode.VectorAxisPips = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                axisPipsContainer.Add(axisPipsToggle);
                displayStyleFoldout.Add(axisPipsContainer);

                // Create Asset Button — Default / InlineEditor / AssetPreview widgets bound to a
                // ScriptableObject-reference field: a "Create" button shown while the reference is null.
                // Applicability is resolved once per panel build (same pattern as the DropDown sub-controls).
                var caFieldType = ResolveSelectedNodeFieldType(bindingNode);
                bool createAssetApplies = caFieldType != null &&
                    typeof(ScriptableObject).IsAssignableFrom(caFieldType) &&
                    AssetCreateUtility.GetCreatableTypes(caFieldType).Count > 0;

                var createAssetContainer = new VisualElement();
                createAssetContainer.style.display =
                    (createAssetApplies &&
                     (bindingNode.DisplayType == DisplayType.Default ||
                      bindingNode.DisplayType == DisplayType.InlineEditor ||
                      bindingNode.DisplayType == DisplayType.AssetPreview)) ? DisplayStyle.Flex : DisplayStyle.None;

                var createAssetToggle = new Toggle("Create Asset Button");
                createAssetToggle.tooltip = "While this ScriptableObject reference is empty, show a Create button that saves a new asset of the field's type (abstract types offer their concrete subclasses) and assigns it.";
                createAssetToggle.value = bindingNode.CreateAssetEnabled;
                createAssetToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Create Asset Button");
                    bindingNode.CreateAssetEnabled = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                createAssetContainer.Add(createAssetToggle);
                displayStyleFoldout.Add(createAssetContainer);

                // Helper variables to dynamically toggle corner radius visibility
                VisualElement cornerRadiusControl = null;
                Action updateCornerRadiusVisibility = () =>
                {
                    if (cornerRadiusControl == null) return;
                    var kind = bindingNode.DisplayType;
                    var ws = bindingNode.DisplayStyleData;
                    bool hide = (kind == DisplayType.MinMaxSlider)
                             || (kind == DisplayType.Toggle && ws.toggleStyle == ToggleStyle.Checkbox)
                             || (kind == DisplayType.Default)
                             || (kind == DisplayType.DropDown)
                             || (kind == DisplayType.AssetPreview)
                             || (kind == DisplayType.AudioPreview)
                             || (kind == DisplayType.InlineEditor)
                             || (kind == DisplayType.ColorPalette)
                             || (kind == DisplayType.UnityEvent) // the card owns its own corner radii; this knob does nothing
                             || (kind == DisplayType.ParticleSystemPreview) // the panel hardcodes its own radii; this knob does nothing
                             || (kind == DisplayType.AnimationCurveEditor) // the curve well owns its own radii; this knob does nothing
                             || (kind == DisplayType.Gradient) // the gradient strip owns its own radii; this knob does nothing
                             || (kind == DisplayType.EnumBadgeGrid) // badges own their own radii; this knob does nothing
                             || (kind == DisplayType.XYPad) // the pad hardcodes its own radii; this knob does nothing
                             || (kind == DisplayType.Rating) // pips have no radius; this knob does nothing
                             || (kind == DisplayType.Dictionary) // the Key/Value table owns its own frame + cell radii; this knob does nothing
                             || (kind == DisplayType.SerializeReference);
                    cornerRadiusControl.style.display = hide ? DisplayStyle.None : DisplayStyle.Flex;
                };
                Action updateToggleColorsVisibility = null;

                // (The "Widget Size" enum was removed — it scaled font/height via the sq-size USS classes but
                // was unwanted. DisplayStyleData.size remains for serialization back-compat.)

                // Text Resize + Resize Handle — built earlier but added here. Its own DisplayType == Text gating
                // plus the widget-kind visibility callback drive its show/hide.
                displayStyleFoldout.Add(textContainer);

                // Toggle Styling sub-elements
                var toggleStyleContainer = new VisualElement();
                toggleStyleContainer.style.display = bindingNode.DisplayType == DisplayType.Toggle ? DisplayStyle.Flex : DisplayStyle.None;

                var toggleStyleField = new EnumField("Toggle Style", bindingNode.DisplayStyleData.toggleStyle);
                toggleStyleContainer.Add(toggleStyleField);

                var toggleSizeField = new EnumField("Size", bindingNode.DisplayStyleData.toggleSize);
                toggleSizeField.tooltip = "Overall size of the toggle switch/box.";
                toggleSizeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Toggle Size");
                    var ws = bindingNode.DisplayStyleData; ws.toggleSize = (SliderSize)evt.newValue; bindingNode.DisplayStyleData = ws;
                    OnModification(); RefreshPreview();
                });
                toggleStyleContainer.Add(toggleSizeField);

                // ON/OFF contrast warning. Declared HERE, built further down next to the Show ON/OFF row, so
                // the fill-colour callbacks above can call the sync without a forward reference.
                //
                // An AUTHORED ON/OFF text colour wins outright in the widget — the colour picker has to do
                // exactly what it says. But that means picking a pale fill under an old authored ink leaves
                // the word unreadable with nothing on screen to explain why, which is precisely how this
                // shipped in the first place. So the designer says it out loud rather than the widget
                // quietly overruling the user.
                VisualElement onOffContrastWarnRow = null;
                Label onOffContrastWarnLabel = null;
                void SyncOnOffContrastWarning()
                {
                    if (onOffContrastWarnRow == null) return;
                    var d = bindingNode.DisplayStyleData;
                    // The overlay is a SWITCH affordance, and there is nothing to warn about unless the user
                    // has actually authored an ink — auto-contrast can never produce an unreadable one.
                    bool applies = d.toggleShowOnOff
                                   && d.toggleStyle != ToggleStyle.Checkbox
                                   && d.toggleStyle != ToggleStyle.ModernCheckbox
                                   && bindingNode.ToggleOnOffTextStyle.color.isOverridden;
                    if (!applies) { onOffContrastWarnRow.style.display = DisplayStyle.None; return; }

                    // The word wears ONE authored colour across BOTH states, so judge it against both fills
                    // and report the worse — warning only about ON would let a bad OFF fill through silently.
                    Color authored = bindingNode.ToggleOnOffTextStyle.color.value;
                    Color onBg = BindingFactory.ResolveToggleOnOffBackdrop(bindingNode, true);
                    Color offBg = BindingFactory.ResolveToggleOnOffBackdrop(bindingNode, false);
                    float onRatio = BindingFactory.ReadoutContrast(WidgetPalette.Composite(onBg, authored), onBg);
                    float offRatio = BindingFactory.ReadoutContrast(WidgetPalette.Composite(offBg, authored), offBg);
                    float worst = Mathf.Min(onRatio, offRatio);
                    if (worst >= BindingFactory.MinReadoutContrast)
                    {
                        onOffContrastWarnRow.style.display = DisplayStyle.None;
                        return;
                    }
                    onOffContrastWarnLabel.text =
                        $"ON/OFF text is {worst:0.0}:1 on the {(onRatio <= offRatio ? "ON" : "OFF")} fill — hard to read "
                        + $"(needs {BindingFactory.MinReadoutContrast:0}:1). Clear the color in the T panel and it "
                        + "auto-picks one that reads.";
                    onOffContrastWarnRow.style.display = DisplayStyle.Flex;
                }

                // Toggle colors container (visible for all toggle styles)
                var checkboxColorsContainer = new VisualElement();
                checkboxColorsContainer.style.display = DisplayStyle.Flex;

                // Inside (Fill) Color
                var chkFillRow = new VisualElement();
                chkFillRow.style.flexDirection = FlexDirection.Row;
                chkFillRow.style.alignItems = Align.Center;
                chkFillRow.style.marginBottom = 2;
                var chkFillColorField = new ColorField("Fill Color");
                chkFillColorField.tooltip = "The background fill color of the toggle when checked.";
                chkFillColorField.value = bindingNode.DisplayStyleData.toggleFillColor.a > 0.001f ? bindingNode.DisplayStyleData.toggleFillColor : new Color(0.15f, 0.15f, 0.15f, 1f);
                chkFillColorField.style.flexGrow = 1;
                var chkFillColorReset = MakeStyleResetButton();
                bool IsChkFillColorOverridden() => bindingNode.DisplayStyleData.toggleFillColor.a > 0.001f;
                void SyncChkFillColorReset() => ApplyOverrideChrome(chkFillColorField, chkFillColorReset, IsChkFillColorOverridden());
                chkFillColorField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Toggle Fill Color", () =>
                    {
                        var ws = bindingNode.DisplayStyleData; ws.toggleFillColor = evt.newValue; bindingNode.DisplayStyleData = ws;
                        SyncChkFillColorReset();
                        // Modern Checkbox paints its fill on the checkmark BOX, not the input track.
                        LivePokeChild(bindingNode,
                            ws.toggleStyle == ToggleStyle.ModernCheckbox ? "unity-toggle__checkmark" : "unity-toggle__input",
                            i => i.style.backgroundColor = evt.newValue);
                        // …and the ON/OFF word re-derives its contrast off that same fill. Without this the
                        // ink only caught up at the debounced commit, so the one moment the user is actually
                        // choosing a fill is the one moment the preview lies about how it will read.
                        LivePokeCanvasElement(bindingNode, el => BindingFactory.PokeToggleOnOffInk(el, bindingNode));
                        SyncOnOffContrastWarning();
                    });
                });
                FlushValueEditOnBlur(chkFillColorField);
                void DoChkFillColorReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Toggle Fill Color");
                    var ws = bindingNode.DisplayStyleData; ws.toggleFillColor = Color.clear; bindingNode.DisplayStyleData = ws;
                    chkFillColorField.SetValueWithoutNotify(new Color(0.15f, 0.15f, 0.15f, 1f));
                    OnModification(); RefreshPreview(); SyncChkFillColorReset(); SyncOnOffContrastWarning();
                }
                chkFillColorReset.clicked += DoChkFillColorReset;
                AddStyleResetContextMenu(chkFillRow, IsChkFillColorOverridden, DoChkFillColorReset);
                chkFillRow.Add(chkFillColorField);
                chkFillRow.Add(chkFillColorReset);
                checkboxColorsContainer.Add(chkFillRow);

                // Inside (Fill) Color on OFF
                var chkFillOffRow = new VisualElement();
                chkFillOffRow.style.flexDirection = FlexDirection.Row;
                chkFillOffRow.style.alignItems = Align.Center;
                chkFillOffRow.style.marginBottom = 2;
                var chkFillOffColorField = new ColorField("Fill Color (Off)");
                chkFillOffColorField.tooltip = "The background fill color of the toggle when unchecked.";
                chkFillOffColorField.value = bindingNode.DisplayStyleData.toggleFillColorOff.a > 0.001f ? bindingNode.DisplayStyleData.toggleFillColorOff : new Color(0.15f, 0.15f, 0.15f, 1f);
                chkFillOffColorField.style.flexGrow = 1;
                var chkFillOffColorReset = MakeStyleResetButton();
                bool IsChkFillOffColorOverridden() => bindingNode.DisplayStyleData.toggleFillColorOff.a > 0.001f;
                void SyncChkFillOffColorReset() => ApplyOverrideChrome(chkFillOffColorField, chkFillOffColorReset, IsChkFillOffColorOverridden());
                chkFillOffColorField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Toggle Fill Color on OFF", () =>
                    {
                        var ws = bindingNode.DisplayStyleData; ws.toggleFillColorOff = evt.newValue; bindingNode.DisplayStyleData = ws;
                        SyncChkFillOffColorReset();
                        LivePokeChild(bindingNode,
                            ws.toggleStyle == ToggleStyle.ModernCheckbox ? "unity-toggle__checkmark" : "unity-toggle__input",
                            i => i.style.backgroundColor = evt.newValue);
                        LivePokeCanvasElement(bindingNode, el => BindingFactory.PokeToggleOnOffInk(el, bindingNode));
                        SyncOnOffContrastWarning();
                    });
                });
                FlushValueEditOnBlur(chkFillOffColorField);
                void DoChkFillOffColorReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Toggle Fill Color on OFF");
                    var ws = bindingNode.DisplayStyleData; ws.toggleFillColorOff = Color.clear; bindingNode.DisplayStyleData = ws;
                    chkFillOffColorField.SetValueWithoutNotify(new Color(0.15f, 0.15f, 0.15f, 1f));
                    OnModification(); RefreshPreview(); SyncChkFillOffColorReset(); SyncOnOffContrastWarning();
                }
                chkFillOffColorReset.clicked += DoChkFillOffColorReset;
                AddStyleResetContextMenu(chkFillOffRow, IsChkFillOffColorOverridden, DoChkFillOffColorReset);
                chkFillOffRow.Add(chkFillOffColorField);
                chkFillOffRow.Add(chkFillOffColorReset);
                checkboxColorsContainer.Add(chkFillOffRow);

                updateToggleColorsVisibility = () =>
                {
                    var style = bindingNode.DisplayStyleData.toggleStyle;
                    bool hideFill = (style == ToggleStyle.Checkbox);
                    chkFillRow.style.display = hideFill ? DisplayStyle.None : DisplayStyle.Flex;
                    chkFillOffRow.style.display = hideFill ? DisplayStyle.None : DisplayStyle.Flex;
                };
                updateToggleColorsVisibility();

                // Knob Color
                var chkKnobRow = new VisualElement();
                chkKnobRow.style.flexDirection = FlexDirection.Row;
                chkKnobRow.style.alignItems = Align.Center;
                chkKnobRow.style.marginBottom = 2;
                var chkKnobColorField = new ColorField("Knob Color");
                chkKnobColorField.tooltip = "The checkmark tick or sliding knob color.";
                chkKnobColorField.value = bindingNode.DisplayStyleData.toggleKnobColor.a > 0.001f ? bindingNode.DisplayStyleData.toggleKnobColor : Color.white;
                chkKnobColorField.style.flexGrow = 1;
                var chkKnobColorReset = MakeStyleResetButton();
                bool IsChkKnobColorOverridden() => bindingNode.DisplayStyleData.toggleKnobColor.a > 0.001f;
                void SyncChkKnobColorReset() => ApplyOverrideChrome(chkKnobColorField, chkKnobColorReset, IsChkKnobColorOverridden());
                chkKnobColorField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Toggle Knob Color", () =>
                    {
                        var ws = bindingNode.DisplayStyleData; ws.toggleKnobColor = evt.newValue; bindingNode.DisplayStyleData = ws;
                        SyncChkKnobColorReset();
                        if (ws.toggleStyle == ToggleStyle.ModernCheckbox)
                            LivePokeChild(bindingNode, "sasq-modern-checkbox__tick",
                                k => { if (k is SasquatchIconElement icon) icon.Tint = evt.newValue; });
                        else
                            LivePokeChild(bindingNode, "unity-toggle__checkmark", k => k.style.backgroundColor = evt.newValue);
                    });
                });
                FlushValueEditOnBlur(chkKnobColorField);
                void DoChkKnobColorReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Toggle Knob Color");
                    var ws = bindingNode.DisplayStyleData; ws.toggleKnobColor = Color.clear; bindingNode.DisplayStyleData = ws;
                    chkKnobColorField.SetValueWithoutNotify(Color.white);
                    OnModification(); RefreshPreview(); SyncChkKnobColorReset();
                }
                chkKnobColorReset.clicked += DoChkKnobColorReset;
                AddStyleResetContextMenu(chkKnobRow, IsChkKnobColorOverridden, DoChkKnobColorReset);
                chkKnobRow.Add(chkKnobColorField);
                chkKnobRow.Add(chkKnobColorReset);
                checkboxColorsContainer.Add(chkKnobRow);

                // Outline Color
                var chkOutlineRow = new VisualElement();
                chkOutlineRow.style.flexDirection = FlexDirection.Row;
                chkOutlineRow.style.alignItems = Align.Center;
                chkOutlineRow.style.marginBottom = 2;
                var chkOutlineColorField = new ColorField("Outline Color");
                chkOutlineColorField.tooltip = "The toggle outline / border color.";
                chkOutlineColorField.value = bindingNode.DisplayStyleData.toggleOutlineColor.a > 0.001f ? bindingNode.DisplayStyleData.toggleOutlineColor : new Color(0.24f, 0.24f, 0.24f, 1f);
                chkOutlineColorField.style.flexGrow = 1;
                var chkOutlineColorReset = MakeStyleResetButton();
                bool IsChkOutlineColorOverridden() => bindingNode.DisplayStyleData.toggleOutlineColor.a > 0.001f;
                void SyncChkOutlineColorReset() => ApplyOverrideChrome(chkOutlineColorField, chkOutlineColorReset, IsChkOutlineColorOverridden());
                chkOutlineColorField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Toggle Outline Color", () =>
                    {
                        var ws = bindingNode.DisplayStyleData; ws.toggleOutlineColor = evt.newValue; bindingNode.DisplayStyleData = ws;
                        SyncChkOutlineColorReset();
                        LivePokeChild(bindingNode,
                            ws.toggleStyle == ToggleStyle.ModernCheckbox ? "unity-toggle__checkmark" : "unity-toggle__input",
                            i =>
                        {
                            i.style.borderTopColor = evt.newValue; i.style.borderBottomColor = evt.newValue;
                            i.style.borderLeftColor = evt.newValue; i.style.borderRightColor = evt.newValue;
                        });
                    });
                });
                FlushValueEditOnBlur(chkOutlineColorField);
                void DoChkOutlineColorReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Toggle Outline Color");
                    var ws = bindingNode.DisplayStyleData; ws.toggleOutlineColor = Color.clear; bindingNode.DisplayStyleData = ws;
                    chkOutlineColorField.SetValueWithoutNotify(new Color(0.24f, 0.24f, 0.24f, 1f));
                    OnModification(); RefreshPreview(); SyncChkOutlineColorReset();
                }
                chkOutlineColorReset.clicked += DoChkOutlineColorReset;
                AddStyleResetContextMenu(chkOutlineRow, IsChkOutlineColorOverridden, DoChkOutlineColorReset);
                chkOutlineRow.Add(chkOutlineColorField);
                chkOutlineRow.Add(chkOutlineColorReset);
                checkboxColorsContainer.Add(chkOutlineRow);

                toggleStyleContainer.Add(checkboxColorsContainer);

                // Show ON/OFF Text
                var showOnOffToggle = new Toggle("Show ON/OFF Text");
                showOnOffToggle.value = bindingNode.DisplayStyleData.toggleShowOnOff;

                var showOnOffWrapper = WithTextButton(showOnOffToggle,
                    () => bindingNode.ToggleOnOffTextStyle,
                    v => bindingNode.ToggleOnOffTextStyle = v,
                    "toggleOnOff",
                    // Setting or clearing the ink in the T panel is the one edit that flips this verdict most
                    // often, and it moves no geometry — the skin pass would never notice.
                    onTextStyleChanged: () => SyncOnOffContrastWarning());
                // ON/OFF overlay text is a SWITCH affordance — both checkbox looks hide it.
                bool ShowOnOffApplies(ToggleStyle ts) => ts != ToggleStyle.Checkbox && ts != ToggleStyle.ModernCheckbox;
                showOnOffWrapper.style.display = ShowOnOffApplies(bindingNode.DisplayStyleData.toggleStyle) ? DisplayStyle.Flex : DisplayStyle.None;

                toggleStyleField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Toggle Style");
                    var ws = bindingNode.DisplayStyleData;
                    ws.toggleStyle = (ToggleStyle)evt.newValue;
                    bindingNode.DisplayStyleData = ws;
                    showOnOffWrapper.style.display = ShowOnOffApplies(ws.toggleStyle) ? DisplayStyle.Flex : DisplayStyle.None;
                    updateCornerRadiusVisibility(); // Hide Corner Radius for Checkbox toggle
                    updateToggleColorsVisibility(); // Hide Fill colors for Checkbox toggle
                    updateDisplayStyleFoldoutVisibility();
                    OnModification();
                    RefreshPreview();
                    SyncOnOffContrastWarning(); // both checkbox looks drop the overlay entirely
                });

                showOnOffToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Toggle Show ON/OFF");
                    var ws = bindingNode.DisplayStyleData;
                    ws.toggleShowOnOff = evt.newValue;
                    bindingNode.DisplayStyleData = ws;
                    OnModification();
                    RefreshPreview();
                    SyncOnOffContrastWarning();
                });
                toggleStyleContainer.Add(showOnOffWrapper);

                onOffContrastWarnRow = new VisualElement();
                onOffContrastWarnRow.style.display = DisplayStyle.None;
                onOffContrastWarnRow.style.flexDirection = FlexDirection.Row;
                onOffContrastWarnRow.style.alignItems = Align.FlexStart;
                onOffContrastWarnRow.style.marginLeft = 6;
                onOffContrastWarnRow.style.marginBottom = 4;
                onOffContrastWarnRow.style.paddingTop = 3;
                onOffContrastWarnRow.style.paddingBottom = 3;
                onOffContrastWarnRow.style.paddingLeft = 5;
                onOffContrastWarnRow.style.paddingRight = 5;
                onOffContrastWarnRow.style.backgroundColor = WidgetPalette.WarningCalloutBg;
                onOffContrastWarnRow.style.borderLeftWidth = 2;
                onOffContrastWarnRow.style.borderLeftColor = WidgetPalette.WarningCalloutBorder;
                onOffContrastWarnRow.style.borderTopLeftRadius = 3;
                onOffContrastWarnRow.style.borderBottomLeftRadius = 3;
                onOffContrastWarnLabel = new Label();
                onOffContrastWarnLabel.style.whiteSpace = WhiteSpace.Normal; // it wraps; the panel is narrow
                onOffContrastWarnLabel.style.fontSize = 10;
                onOffContrastWarnLabel.style.flexShrink = 1;
                onOffContrastWarnLabel.style.color = WidgetPalette.WarningCalloutText;
                onOffContrastWarnRow.Add(onOffContrastWarnLabel);
                toggleStyleContainer.Add(onOffContrastWarnRow);

                SyncChkFillColorReset();
                SyncChkFillOffColorReset();
                SyncChkKnobColorReset();
                SyncChkOutlineColorReset();
                SyncOnOffContrastWarning();

                displayStyleFoldout.Add(toggleStyleContainer);

                // Min/Max Slider styling sub-elements
                var minMaxStyleContainer = new VisualElement();
                minMaxStyleContainer.style.display = bindingNode.DisplayType == DisplayType.MinMaxSlider ? DisplayStyle.Flex : DisplayStyle.None;

                var showLabelsToggle = new Toggle("Show Min/Max Values");
                showLabelsToggle.value = !bindingNode.DisplayStyleData.minMaxHideValues;

                // Label sub-options are only relevant when labels are shown.
                var labelOptions = new VisualElement();
                labelOptions.style.display = !bindingNode.DisplayStyleData.minMaxHideValues ? DisplayStyle.Flex : DisplayStyle.None;

                // The "T" styles the VALUE read-outs' text — but only while they're plain labels. Once "Editable
                // Values" is on they become number fields, styled through the "Field Styling" section instead, so
                // the T hides then (both drive the SAME MinMaxLabelTextStyle, so styling survives the toggle).
                var showLabelsWrapper = WithTextButton(showLabelsToggle,
                    () => bindingNode.MinMaxLabelTextStyle,
                    v => bindingNode.MinMaxLabelTextStyle = v,
                    "minMaxLabel",
                    tExtraVisible: () => bindingNode.DisplayStyleData.minMaxReadOnlyValues);
                minMaxStyleContainer.Add(showLabelsWrapper);

                showLabelsToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Min/Max Values");
                    var ws = bindingNode.DisplayStyleData;
                    ws.minMaxHideValues = !evt.newValue;
                    bindingNode.DisplayStyleData = ws;
                    labelOptions.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                    RefreshPreview();
                    RefreshProperties(); // hiding the labels also drops the "Field Styling" section
                });

                var editableField = new Toggle("Editable Values");
                editableField.value = !bindingNode.DisplayStyleData.minMaxReadOnlyValues;
                editableField.tooltip = "Render the labels as number fields you can type into (or drag the slider).";
                editableField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Min/Max Editable");
                    var ws = bindingNode.DisplayStyleData;
                    ws.minMaxReadOnlyValues = !evt.newValue;
                    bindingNode.DisplayStyleData = ws;
                    OnModification();
                    RefreshPreview();
                    RefreshProperties(); // editable ⇒ swap the row's "T" for the "Field Styling" section (and back)
                });
                labelOptions.Add(editableField);

                var formatPresets = new List<string> { "0", "0.0", "0.00", "0.000" };
                string currentFormat = bindingNode.DisplayStyleData.minMaxLabelFormat;
                if (string.IsNullOrEmpty(currentFormat)) currentFormat = "0.00";
                if (!formatPresets.Contains(currentFormat))
                {
                    formatPresets.Add(currentFormat);
                }
                var labelFormatField = new DropdownField("Field Format", formatPresets, currentFormat);
                labelFormatField.tooltip = "Numeric format for the values (e.g. \"0\", \"0.00\").";
                labelFormatField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Min/Max Field Format");
                    var ws = bindingNode.DisplayStyleData;
                    ws.minMaxLabelFormat = evt.newValue;
                    bindingNode.DisplayStyleData = ws;
                    OnModification();
                    RefreshPreview();
                });
                labelOptions.Add(labelFormatField);

                var minMaxPlacementRow = new VisualElement();
                minMaxPlacementRow.AddToClassList("unity-base-field");
                minMaxPlacementRow.style.flexDirection = FlexDirection.Row;
                minMaxPlacementRow.style.alignItems = Align.Center;
                minMaxPlacementRow.style.marginBottom = 2;

                var minMaxPlacementLbl = new Label("Field Placement");
                minMaxPlacementLbl.AddToClassList("unity-base-field__label");

                var minMaxButtonsContainer = new VisualElement();
                minMaxButtonsContainer.AddToClassList("unity-base-field__input");
                minMaxButtonsContainer.style.flexDirection = FlexDirection.Row;
                minMaxButtonsContainer.style.alignItems = Align.Center;
                minMaxButtonsContainer.style.flexGrow = 1;

                var minMaxPlacementReset = MakeStyleResetButton();
                bool IsMinMaxPlacementOverridden() => bindingNode.DisplayStyleData.sliderFieldPlacement != SliderFieldPlacement.Below;
                void SyncMinMaxPlacementReset() => ApplyOverrideChrome(minMaxButtonsContainer, minMaxPlacementReset, IsMinMaxPlacementOverridden());

                var minMaxPlacements = new (string icon, SliderFieldPlacement value, string tip)[]
                {
                    (SasquatchIcons.Ids.ArrowLeft, SliderFieldPlacement.Left, "Labels/fields on the sides of the slider"),
                    (SasquatchIcons.Ids.ArrowUp, SliderFieldPlacement.Above, "Labels/fields above the slider"),
                    (SasquatchIcons.Ids.ArrowRight, SliderFieldPlacement.Right, "Labels/fields on the sides of the slider"),
                    (SasquatchIcons.Ids.ArrowDown, SliderFieldPlacement.Below, "Labels/fields below the slider (default)"),
                };
                var minMaxPlacementButtons = new List<Button>();
                void SyncMinMaxPlacement()
                {
                    for (int i = 0; i < minMaxPlacements.Length; i++)
                    {
                        bool active = bindingNode.DisplayStyleData.sliderFieldPlacement == minMaxPlacements[i].value;
                        if (minMaxPlacements[i].value == SliderFieldPlacement.Left || minMaxPlacements[i].value == SliderFieldPlacement.Right)
                        {
                            active = bindingNode.DisplayStyleData.sliderFieldPlacement == SliderFieldPlacement.Left || bindingNode.DisplayStyleData.sliderFieldPlacement == SliderFieldPlacement.Right;
                        }
                        minMaxPlacementButtons[i].style.backgroundColor = active ? DesignerPalette.AccentFillSoft : DesignerPalette.ButtonNeutralBg;
                        minMaxPlacementButtons[i].Q<SasquatchIconElement>().Tint = active ? Color.white : DesignerPalette.IconIdle;
                    }
                }
                foreach (var p in minMaxPlacements)
                {
                    var btn = new Button();
                    btn.Add(SasquatchIcons.Create(p.icon, 11, DesignerPalette.IconIdle));
                    btn.tooltip = p.tip;
                    btn.style.width = 24; btn.style.height = 18;
                    btn.style.paddingLeft = 0; btn.style.paddingRight = 0;
                    btn.style.marginLeft = 2; btn.style.marginRight = 0;
                    btn.style.alignItems = Align.Center;
                    btn.style.justifyContent = Justify.Center;
                    var captured = p.value;
                    btn.clicked += () =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Min/Max Field Placement");
                        var ws = bindingNode.DisplayStyleData; ws.sliderFieldPlacement = captured; bindingNode.DisplayStyleData = ws;
                        OnModification(); RefreshPreview(); SyncMinMaxPlacement();
                        SyncMinMaxPlacementReset();
                    };
                    // Left/Right share one visual state here (sides), mirroring SyncMinMaxPlacement.
                    AddSegmentedHover(btn, () =>
                    {
                        var pl = bindingNode.DisplayStyleData.sliderFieldPlacement;
                        if (captured == SliderFieldPlacement.Left || captured == SliderFieldPlacement.Right)
                            return pl == SliderFieldPlacement.Left || pl == SliderFieldPlacement.Right;
                        return pl == captured;
                    }, SyncMinMaxPlacement);
                    minMaxPlacementButtons.Add(btn);
                    minMaxButtonsContainer.Add(btn);
                }

                void DoMinMaxPlacementReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Min/Max Field Placement");
                    var ws = bindingNode.DisplayStyleData; ws.sliderFieldPlacement = SliderFieldPlacement.Below; bindingNode.DisplayStyleData = ws;
                    OnModification(); RefreshPreview(); SyncMinMaxPlacement();
                    SyncMinMaxPlacementReset();
                }
                minMaxPlacementReset.clicked += DoMinMaxPlacementReset;
                AddStyleResetContextMenu(minMaxPlacementRow, IsMinMaxPlacementOverridden, DoMinMaxPlacementReset);

                minMaxPlacementRow.Add(minMaxPlacementLbl);
                minMaxPlacementRow.Add(minMaxButtonsContainer);
                minMaxPlacementRow.Add(minMaxPlacementReset);
                labelOptions.Add(minMaxPlacementRow);

                SyncMinMaxPlacement();
                SyncMinMaxPlacementReset();

                minMaxStyleContainer.Add(labelOptions);
                displayStyleFoldout.Add(minMaxStyleContainer);

                // Progress Bar styling options
                var progressBarStyleContainer = new VisualElement();
                progressBarStyleContainer.style.display = bindingNode.DisplayType == DisplayType.ProgressBar ? DisplayStyle.Flex : DisplayStyle.None;

                var interactiveToggle = new Toggle("Interactive (drag to set)");
                interactiveToggle.value = bindingNode.ProgressBarInteractive;
                interactiveToggle.tooltip = "Allow clicking and dragging anywhere on the progress bar in the inspector to edit the field value in real time.";
                interactiveToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Progress Bar Interactive");
                    bindingNode.ProgressBarInteractive = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                progressBarStyleContainer.Add(interactiveToggle);

                var pbValueFillToggle = new Toggle("Value-Based Fill");
                pbValueFillToggle.value = bindingNode.ProgressBarValueFill;
                pbValueFillToggle.tooltip = "Ramp the fill color by value using the editable gradient below (classic health-bar look), overriding the flat Fill Color.";
                progressBarStyleContainer.Add(pbValueFillToggle);

                // The editable value-fill gradient (our custom control, Expandable style), pre-filled
                // red→yellow→green. Shown only while Value-Based Fill is on; the flat Fill Color row hides then.
                // Callback + show/hide are wired below, once the Fill Color row exists.
                var pbFillGradientSection = BuildProgressFillGradientSection(bindingNode);
                progressBarStyleContainer.Add(pbFillGradientSection);

                var pbTextModeField = new EnumField("Text Display Mode", bindingNode.ProgressBarTextMode);
                pbTextModeField.tooltip = "Configure how value information is overlayed on the progress bar track.";
                pbTextModeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Progress Bar Text Mode");
                    bindingNode.ProgressBarTextMode = (ProgressBarTextMode)evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                progressBarStyleContainer.Add(pbTextModeField);

                var pbBackdropToggle = new Toggle("Text Backdrop");
                pbBackdropToggle.value = bindingNode.ProgressBarTextBackdrop;
                pbBackdropToggle.tooltip = "Sit the readout text on a soft dark pill — guaranteed readability over any bar colors (great for low-vision users). Off = the text adapts its color to the fill and track automatically.";
                pbBackdropToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Progress Bar Text Backdrop");
                    bindingNode.ProgressBarTextBackdrop = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                progressBarStyleContainer.Add(pbBackdropToggle);

                var pbColorField = new ColorField("Fill Color");
                pbColorField.value = bindingNode.ProgressBarColor.a > 0.001f ? bindingNode.ProgressBarColor : BindingFactory.ProgressFillDefault;
                pbColorField.tooltip = "Override the default progress bar fill accent color.";
                pbColorField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Progress Bar Fill Color", () =>
                    {
                        bindingNode.ProgressBarColor = evt.newValue;
                        LivePokeChild(bindingNode, "sasq-progress-fill", f => f.style.backgroundColor = evt.newValue);
                        // Keep the split readout legible mid-drag: the fill-side copy re-picks its
                        // contrast color live (the commit's rebuild re-resolves it authoritatively).
                        LivePokeChild(bindingNode, "sasq-progress-label--fill",
                            l => l.style.color = BindingFactory.ContrastingReadoutColor(evt.newValue));
                    });
                });
                FlushValueEditOnBlur(pbColorField);
                progressBarStyleContainer.Add(pbColorField);

                // Value-Based Fill drives the gradient (and hides the flat Fill Color); wire it now that both exist.
                void SyncProgressValueFill(bool on)
                {
                    pbFillGradientSection.style.display = on ? DisplayStyle.Flex : DisplayStyle.None;
                    pbColorField.style.display = on ? DisplayStyle.None : DisplayStyle.Flex;
                }
                pbValueFillToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Progress Bar Value Fill");
                    bindingNode.ProgressBarValueFill = evt.newValue;
                    SyncProgressValueFill(evt.newValue);
                    OnModification();
                    RefreshPreview();
                });
                SyncProgressValueFill(bindingNode.ProgressBarValueFill);

                // Swatch default mirrors the USS .sasq-progress-track background (#2b2b2b). The ↺ reset +
                // dim chrome appear only once the color is overridden (a.a > 0), matching the sibling Slider
                // "Track Color" row — clear (alpha 0) is the unset sentinel, so reset just wipes to clear.
                var pbBgColorRow = new VisualElement();
                pbBgColorRow.style.flexDirection = FlexDirection.Row;
                pbBgColorRow.style.alignItems = Align.Center;
                pbBgColorRow.style.marginBottom = 2;

                var pbBgDefaultSwatch = new Color(0.169f, 0.169f, 0.169f, 1f);
                var pbBgColorField = new ColorField("Track Color");
                pbBgColorField.value = bindingNode.ProgressBarBgColor.a > 0.001f ? bindingNode.ProgressBarBgColor : pbBgDefaultSwatch;
                pbBgColorField.tooltip = "Override the background track container color.";
                pbBgColorField.style.flexGrow = 1;

                var pbBgColorReset = MakeStyleResetButton();
                bool IsPbBgColorOverridden() => bindingNode.ProgressBarBgColor.a > 0.001f;
                void SyncPbBgColorReset() => ApplyOverrideChrome(pbBgColorField, pbBgColorReset, IsPbBgColorOverridden());

                pbBgColorField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Progress Bar Track Color", () =>
                    {
                        bindingNode.ProgressBarBgColor = evt.newValue;
                        SyncPbBgColorReset();
                        LivePokeChild(bindingNode, "sasq-progress-track", t => t.style.backgroundColor = evt.newValue);
                        // Base readout copy re-picks its contrast color against the new track live.
                        // (Q finds the base copy first in tree order; the fill copy is untouched.)
                        // Skip in Text Backdrop mode — there the first match is the pill copy, which
                        // stays light-on-dark regardless of track color.
                        if (!bindingNode.ProgressBarTextBackdrop)
                            LivePokeChild(bindingNode, "sasq-progress-label",
                                l => l.style.color = BindingFactory.ContrastingReadoutColor(evt.newValue));
                    });
