                var pbThicknessField = new Slider("Height (px)", 0f, 48f) { showInputField = true };
                pbThicknessField.tooltip = "Height of the progress bar track in pixels (0-48). 0 = the stylesheet default.";
                progressBarStyleContainer.Add(CreateResettableNumberField<float>(
                    pbThicknessField, 0f,
                    () => bindingNode.ProgressBarThickness,
                    v => bindingNode.ProgressBarThickness = v,
                    v => Mathf.Clamp(v, 0f, 48f),
                    "Change Progress Bar Thickness",
                    // Live-grow the rendered track height as the slider drags — instant feedback, no rebuild.
                    liveApply: v => LivePokeCanvasElement(bindingNode, el =>
                    {
                        var track = el.Q(className: "sasq-progress-track");
                        if (track != null) track.style.height = v > 0f ? new StyleLength(v) : new StyleLength(StyleKeyword.Null);
                    })));

                displayStyleFoldout.Add(progressBarStyleContainer);

                // Color Palette styling options (DisplayType == ColorPalette)
                var colorPaletteContainer = new VisualElement();
                colorPaletteContainer.style.display = bindingNode.DisplayType == DisplayType.ColorPalette ? DisplayStyle.Flex : DisplayStyle.None;

                // Pick which palette in the project library this field shows. The leading null choice means
                // "(Project Default)" — the field stores no id and follows the library's default palette.
                var paletteLibrary = SasquatchPaletteLibraryManager.Current;
                var paletteChoices = new List<SasquatchColorPaletteLibrary.Palette> { null };
                paletteChoices.AddRange(paletteLibrary.Palettes);
                string FormatPaletteChoice(SasquatchColorPaletteLibrary.Palette p) => p == null ? "(Project Default)" : p.DisplayName;
                var currentPalette = paletteLibrary.GetPalette(bindingNode.ColorPaletteId);
                // PopupField's defaultVALUE ctor throws on a null default, but null is a legitimate
                // choice here (index 0 = "(Project Default)") and is the default for any binding
                // without an assigned palette. Use the defaultINDEX ctor, which accepts it.
                int paletteIndex = Mathf.Max(0, paletteChoices.IndexOf(currentPalette));
                var paletteField = new PopupField<SasquatchColorPaletteLibrary.Palette>(
                    "Palette", paletteChoices, paletteIndex, FormatPaletteChoice, FormatPaletteChoice);
                paletteField.tooltip = "Which palette (from the project's Color Palette library) this field shows. " +
                    "Choose \"(Project Default)\" to follow the library's default palette.";
                paletteField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Color Palette");
                    bindingNode.ColorPaletteId = evt.newValue != null ? evt.newValue.Id : "";
                    OnModification();
                    RefreshPreview();
                });
                colorPaletteContainer.Add(paletteField);

                var paletteButtonsRow = new VisualElement();
                paletteButtonsRow.style.flexDirection = FlexDirection.Row;
                paletteButtonsRow.style.marginBottom = 4;
                var newPaletteBtn = new Button(() =>
                {
                    var p = SasquatchColorPaletteWindow.CreatePalette("New Palette");
                    if (p == null) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Assign New Color Palette");
                    bindingNode.ColorPaletteId = p.Id;
                    paletteChoices.Add(p);
                    paletteField.SetValueWithoutNotify(p);
                    SasquatchColorPaletteWindow.Open(p);
                    OnModification();
                    RefreshPreview();
                })
                { text = "New Palette" };
                newPaletteBtn.tooltip = "Create a new palette in the library, assign it to this field, and open it for editing.";
                newPaletteBtn.style.flexGrow = 1;
                var openWindowBtn = new Button(() => SasquatchColorPaletteWindow.Open(paletteLibrary.GetPalette(bindingNode.ColorPaletteId))) { text = "Open Window" };
                openWindowBtn.tooltip = "Open the Color Palette window to browse and edit palettes.";
                openWindowBtn.style.flexGrow = 1;
                openWindowBtn.style.marginLeft = 4;
                paletteButtonsRow.Add(newPaletteBtn);
                paletteButtonsRow.Add(openWindowBtn);
                colorPaletteContainer.Add(paletteButtonsRow);

                // Columns row declared up front so the layout field's callback can show/hide it (grid only).
                var paletteColumnsRow = new VisualElement();
                paletteColumnsRow.style.display = bindingNode.ColorPaletteLayout == ColorPaletteLayout.Grid ? DisplayStyle.Flex : DisplayStyle.None;

                var paletteLayoutField = new EnumField("Layout", bindingNode.ColorPaletteLayout);
                paletteLayoutField.tooltip = "Grid: wrapping square swatches. Bar: one continuous rounded strip of segments.";
                paletteLayoutField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Color Palette Layout");
                    var layout = (ColorPaletteLayout)evt.newValue;
                    bindingNode.ColorPaletteLayout = layout;
                    paletteColumnsRow.style.display = layout == ColorPaletteLayout.Grid ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                    RefreshPreview();
                });
                colorPaletteContainer.Add(paletteLayoutField);

                var columnsField = new IntegerField("Columns (0 = auto)");
                columnsField.tooltip = "Fixed swatches per row. 0 auto-wraps fixed-size squares to the available width.";
                columnsField.value = bindingNode.ColorPaletteColumns;
                columnsField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Color Palette Columns", () => bindingNode.ColorPaletteColumns = Mathf.Max(0, evt.newValue), liveRebuild: true);
                });
                FlushValueEditOnBlur(columnsField);
                paletteColumnsRow.Add(columnsField);

                var swatchSpacingField = new FloatField("Swatch Spacing");
                swatchSpacingField.tooltip = "Gap around each grid swatch, in pixels. 0 makes them touch — they can never overlap.";
                paletteColumnsRow.Add(CreateResettableNumberField<float>(
                    swatchSpacingField, 1f,
                    () => bindingNode.ColorSwatchSpacing,
                    v => bindingNode.ColorSwatchSpacing = v,
                    v => Mathf.Max(0f, v),
                    "Change Swatch Spacing"));
                colorPaletteContainer.Add(paletteColumnsRow);

                var swatchSizeField = new FloatField("Swatch Size");
                swatchSizeField.tooltip = "Swatch edge length in pixels (grid) or bar height.";
                colorPaletteContainer.Add(CreateResettableNumberField<float>(
                    swatchSizeField, 22f,
                    () => bindingNode.ColorSwatchSize,
                    v => bindingNode.ColorSwatchSize = v,
                    v => Mathf.Clamp(v, 10f, 80f),
                    "Change Swatch Size"));

                var copyOnClickToggle = new Toggle("Copy Hex On Click");
                copyOnClickToggle.tooltip = "Also copy the picked color's hex code to the clipboard when a swatch is clicked.";
                copyOnClickToggle.value = bindingNode.ColorCopyOnClick;
                copyOnClickToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Copy Hex On Click");
