                barPlacementRow.style.flexDirection = FlexDirection.Row;
                barPlacementRow.style.alignItems = Align.Center;
                barPlacementRow.style.marginBottom = 2;
                barPlacementRow.style.display = bindingNode.ColorShowBar ? DisplayStyle.Flex : DisplayStyle.None;

                var barPlacementLbl = new Label("Bar Placement");
                barPlacementLbl.AddToClassList("unity-base-field__label");

                var barPlacementButtonsContainer = new VisualElement();
                barPlacementButtonsContainer.AddToClassList("unity-base-field__input");
                barPlacementButtonsContainer.style.flexDirection = FlexDirection.Row;
                barPlacementButtonsContainer.style.alignItems = Align.Center;
                barPlacementButtonsContainer.style.flexGrow = 1;

                var barPlacements = new (string icon, ColorBarPlacement value, string tip)[]
                {
                    (SasquatchIcons.Ids.ArrowLeft, ColorBarPlacement.Left, "Bar left of the palette (same row)"),
                    (SasquatchIcons.Ids.ArrowUp, ColorBarPlacement.Above, "Bar above the palette (own row)"),
                    (SasquatchIcons.Ids.ArrowRight, ColorBarPlacement.Right, "Bar right of the palette (same row, default)"),
                    (SasquatchIcons.Ids.ArrowDown, ColorBarPlacement.Below, "Bar below the palette (own row)"),
                };
                var barPlacementButtons = new List<Button>();
                void SyncBarPlacement()
                {
                    for (int i = 0; i < barPlacements.Length; i++)
                    {
                        bool active = bindingNode.ColorBarPlacement == barPlacements[i].value;
                        barPlacementButtons[i].style.backgroundColor = active ? DesignerPalette.AccentFillSoft : DesignerPalette.ButtonNeutralBg;
                        barPlacementButtons[i].Q<SasquatchIconElement>().Tint = active ? Color.white : DesignerPalette.IconIdle;
                    }
                }
                foreach (var p in barPlacements)
                {
                    var btn = new Button();
                    btn.Add(SasquatchIcons.Create(p.icon, 11, DesignerPalette.IconIdle));
                    btn.tooltip = p.tip;
                    btn.style.width = 24; btn.style.height = 18;
                    btn.style.paddingLeft = 0; btn.style.paddingRight = 0;
                    btn.style.marginLeft = 2; btn.style.marginRight = 0;
                    btn.style.alignItems = Align.Center;
                    btn.style.justifyContent = Justify.Center;
                    var captured = p.value;
                    btn.clicked += () =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Color Bar Placement");
                        bindingNode.ColorBarPlacement = captured;
                        OnModification(); RefreshPreview(); SyncBarPlacement();
                    };
                    AddSegmentedHover(btn, () => bindingNode.ColorBarPlacement == captured, SyncBarPlacement);
                    barPlacementButtons.Add(btn);
                    barPlacementButtonsContainer.Add(btn);
                }
                barPlacementRow.Add(barPlacementLbl);
                barPlacementRow.Add(barPlacementButtonsContainer);
                colorPaletteContainer.Add(barPlacementRow);

                showBarToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Show Color Bar");
                    bindingNode.ColorShowBar = evt.newValue;
                    barPlacementRow.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification(); RefreshPreview();
                });
                SyncBarPlacement();

                displayStyleFoldout.Add(colorPaletteContainer);

                // Unity Event styling options (DisplayType == UnityEvent)
                var unityEventContainer = new VisualElement();
                unityEventContainer.style.display = bindingNode.DisplayType == DisplayType.UnityEvent ? DisplayStyle.Flex : DisplayStyle.None;

                var ueCompactToggle = new Toggle("Compact Rows");
                ueCompactToggle.tooltip = "Lay each listener out on one dense line instead of a roomy card.";
                ueCompactToggle.value = bindingNode.UnityEventCompact;
                ueCompactToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle UnityEvent Compact");
                    bindingNode.UnityEventCompact = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                unityEventContainer.Add(ueCompactToggle);

                var ueExpandedToggle = new Toggle("Default to Open");
                ueExpandedToggle.tooltip = "Whether the event opens by default (vs collapsed) in the inspector.";
                ueExpandedToggle.value = bindingNode.UnityEventDefaultToOpen;
                ueExpandedToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle UnityEvent Default to Open");
                    bindingNode.UnityEventDefaultToOpen = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                unityEventContainer.Add(ueExpandedToggle);

                var uePeekToggle = new Toggle("Code Peek");
                uePeekToggle.tooltip = "Hovering a function in the Select Function popup previews its source code.";
                uePeekToggle.value = bindingNode.UnityEventCodePeek;
                uePeekToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle UnityEvent Code Peek");
                    bindingNode.UnityEventCodePeek = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                unityEventContainer.Add(uePeekToggle);

                // Shared overridable-color control: ↺ reset + right-click reset, dim-when-inheriting, and a
                // full-alpha default swatch — same as every other color option.
                unityEventContainer.Add(CreateOverridableColorElement("Accent Color",
                    () => bindingNode.UnityEventAccentColor,
                    v => bindingNode.UnityEventAccentColor = v,
                    RefreshPreview));
                unityEventContainer.Add(CreateOverridableColorElement("Card Color",
                    () => bindingNode.UnityEventCardColor,
                    v => bindingNode.UnityEventCardColor = v,
                    RefreshPreview));

                displayStyleFoldout.Add(unityEventContainer);

                // Slider styling/options (DisplayType == Slider / MinMaxSlider / VectorSliders): show-field +
                // placement (Slider-only), the center-bar color (MinMax-only), plus the shared knob/bar look
                // (all three kinds). Vector Sliders reuse the look rows; their per-axis fields have no placement/
                // show-field option (those rows stay hidden).
                var sliderStyleContainer = new VisualElement();
                sliderStyleContainer.style.display = (bindingNode.DisplayType == DisplayType.Slider
                    || bindingNode.DisplayType == DisplayType.MinMaxSlider
                    || bindingNode.DisplayType == DisplayType.VectorSliders) ? DisplayStyle.Flex : DisplayStyle.None;

                // Row for Show Field
                var showFieldRow = new VisualElement();
                showFieldRow.style.flexDirection = FlexDirection.Row;
                showFieldRow.style.alignItems = Align.Center;
                showFieldRow.style.marginBottom = 2;
                showFieldRow.style.display = bindingNode.DisplayType == DisplayType.Slider ? DisplayStyle.Flex : DisplayStyle.None;

                var sliderShowFieldToggle = new Toggle("Show Field");
                sliderShowFieldToggle.tooltip = "Show an editable value field alongside the slider.";
                sliderShowFieldToggle.value = !bindingNode.DisplayStyleData.sliderHideField;
                sliderShowFieldToggle.style.flexGrow = 1;

                var showFieldReset = MakeStyleResetButton();
                bool IsShowFieldOverridden() => bindingNode.DisplayStyleData.sliderHideField;
                void SyncShowFieldReset() => ApplyOverrideChrome(sliderShowFieldToggle, showFieldReset, IsShowFieldOverridden());

                var placementRow = new VisualElement();
                placementRow.AddToClassList("unity-base-field");
                placementRow.style.flexDirection = FlexDirection.Row;
                placementRow.style.alignItems = Align.Center;
                placementRow.style.marginBottom = 2;
                placementRow.style.display = (bindingNode.DisplayType == DisplayType.Slider && !bindingNode.DisplayStyleData.sliderHideField) ? DisplayStyle.Flex : DisplayStyle.None;

                var placementLbl = new Label("Field Placement");
                placementLbl.AddToClassList("unity-base-field__label");

                // A 3x3 pivot grid (like the particle Play Button Placement): the 8 OUTER cells are the field's
                // positions around the slider — top row = Above (left/center/right), middle row = beside it
                // (Left / — / Right), bottom row = Below (left/center/right). The middle cell is inert (a field
                // can't sit on the bar). One click sets BOTH placement and its Above/Below alignment.
                var placementInput = new VisualElement();
                placementInput.AddToClassList("unity-base-field__input");
                placementInput.style.flexGrow = 1;
                placementInput.style.alignItems = Align.FlexEnd; // right-align the grid like the other rows

                var placementReset = MakeStyleResetButton();
                placementReset.style.alignSelf = Align.Center;   // center against the 3-row grid
                bool IsPlacementOverridden() => bindingNode.DisplayStyleData.sliderFieldPlacement != SliderFieldPlacement.Right;
                void SyncPlacementReset() => ApplyOverrideChrome(placementInput, placementReset, IsPlacementOverridden());

                // Row-major cell → (placement, alignment). inert = the middle cell (no meaningful position).
                var placementCells = new (SliderFieldPlacement placement, SliderFieldAlignment align, bool inert, string tip)[]
                {
                    (SliderFieldPlacement.Above, SliderFieldAlignment.Left,   false, "Field above, left-aligned"),
                    (SliderFieldPlacement.Above, SliderFieldAlignment.Center, false, "Field above, centered"),
                    (SliderFieldPlacement.Above, SliderFieldAlignment.Right,  false, "Field above, right-aligned"),
                    (SliderFieldPlacement.Left,  SliderFieldAlignment.Center, false, "Field left of the slider"),
                    (default,                    default,                     true,  null),
                    (SliderFieldPlacement.Right, SliderFieldAlignment.Center, false, "Field right of the slider (default)"),
                    (SliderFieldPlacement.Below, SliderFieldAlignment.Left,   false, "Field below, left-aligned"),
                    (SliderFieldPlacement.Below, SliderFieldAlignment.Center, false, "Field below, centered"),
                    (SliderFieldPlacement.Below, SliderFieldAlignment.Right,  false, "Field below, right-aligned"),
                };

                bool IsPlacementCellActive(int i)
                {
                    if (placementCells[i].inert) return false;
                    var pl = bindingNode.DisplayStyleData.sliderFieldPlacement;
                    if (placementCells[i].placement == SliderFieldPlacement.Left)  return pl == SliderFieldPlacement.Left;
                    if (placementCells[i].placement == SliderFieldPlacement.Right) return pl == SliderFieldPlacement.Right;
                    return pl == placementCells[i].placement
                        && bindingNode.DisplayStyleData.sliderFieldAlignment == placementCells[i].align;
                }

                var placementButtons = new List<Button>();
                void SyncSliderPlacement()
                {
                    for (int i = 0; i < placementButtons.Count; i++)
                    {
                        if (placementCells[i].inert) continue;
                        placementButtons[i].style.backgroundColor = IsPlacementCellActive(i)
                            ? DesignerPalette.AccentFillSoft : DesignerPalette.ButtonNeutralBg;
                    }
                }

                var placementGrid = new VisualElement();
                placementGrid.style.flexDirection = FlexDirection.Column;
                for (int r = 0; r < 3; r++)
                {
                    var gridRow = new VisualElement();
                    gridRow.style.flexDirection = FlexDirection.Row;
                    for (int c = 0; c < 3; c++)
                    {
                        int idx = r * 3 + c;
                        var btn = new Button();
                        btn.style.width = 16; btn.style.height = 16;
                        btn.style.paddingLeft = 0; btn.style.paddingRight = 0;
                        btn.style.paddingTop = 0; btn.style.paddingBottom = 0;
                        btn.style.marginLeft = 1; btn.style.marginRight = 1;
                        btn.style.marginTop = 1; btn.style.marginBottom = 1;
                        if (placementCells[idx].inert)
                        {
                            // No position here — a dim, non-interactive spacer that keeps the 3x3 shape.
                            btn.SetEnabled(false);
                            btn.style.backgroundColor = DesignerPalette.ButtonNeutralBg;
                        }
                        else
                        {
                            btn.tooltip = placementCells[idx].tip;
                            var captured = placementCells[idx];
                            btn.clicked += () =>
                            {
                                Undo.RecordObject(_clonedLayoutAsset, "Change Field Placement");
                                var ws = bindingNode.DisplayStyleData;
                                ws.sliderFieldPlacement = captured.placement;
                                ws.sliderFieldAlignment = captured.align;
                                bindingNode.DisplayStyleData = ws;
                                OnModification(); RefreshPreview(); SyncSliderPlacement();
                                SyncPlacementReset();
                            };
                            AddSegmentedHover(btn, () => IsPlacementCellActive(idx), SyncSliderPlacement);
                        }
                        placementButtons.Add(btn);
                        gridRow.Add(btn);
                    }
                    placementGrid.Add(gridRow);
                }
                placementInput.Add(placementGrid);

                void DoPlacementReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Field Placement");
                    var ws = bindingNode.DisplayStyleData;
                    ws.sliderFieldPlacement = SliderFieldPlacement.Right;
                    ws.sliderFieldAlignment = SliderFieldAlignment.Center;
                    bindingNode.DisplayStyleData = ws;
                    OnModification(); RefreshPreview(); SyncSliderPlacement();
                    SyncPlacementReset();
                }
                placementReset.clicked += DoPlacementReset;
                AddStyleResetContextMenu(placementRow, IsPlacementOverridden, DoPlacementReset);

                placementRow.Add(placementLbl);
                placementRow.Add(placementInput);
                placementRow.Add(placementReset);

                sliderShowFieldToggle.RegisterValueChangedCallback(evt =>
                {
                    var ws = bindingNode.DisplayStyleData; ws.sliderHideField = !evt.newValue; bindingNode.DisplayStyleData = ws;
                    placementRow.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification(); RefreshPreview();
                    SyncShowFieldReset();
                });

                void DoShowFieldReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Show Field");
                    var ws = bindingNode.DisplayStyleData; ws.sliderHideField = false; bindingNode.DisplayStyleData = ws;
                    sliderShowFieldToggle.SetValueWithoutNotify(true);
                    placementRow.style.display = DisplayStyle.Flex;
                    OnModification(); RefreshPreview();
                    SyncShowFieldReset();
                }
                showFieldReset.clicked += DoShowFieldReset;
                AddStyleResetContextMenu(showFieldRow, IsShowFieldOverridden, DoShowFieldReset);

                showFieldRow.Add(sliderShowFieldToggle);
                showFieldRow.Add(showFieldReset);
                sliderStyleContainer.Add(showFieldRow);
                sliderStyleContainer.Add(placementRow);

                var knobShapeRow = new VisualElement();
                knobShapeRow.style.flexDirection = FlexDirection.Row;
                knobShapeRow.style.alignItems = Align.Center;
                knobShapeRow.style.marginBottom = 2;

                // Capsule reads ridiculous as a range handle, so a Min-Max Slider doesn't offer it
                // (ApplySliderLook also demotes stale Capsule data to Default on min-max).
                var knobShapeChoices = new List<SliderKnobShape>
                    { SliderKnobShape.Default, SliderKnobShape.Square, SliderKnobShape.Capsule, SliderKnobShape.Rectangle, SliderKnobShape.Grip };
                if (bindingNode.DisplayType == DisplayType.MinMaxSlider) knobShapeChoices.Remove(SliderKnobShape.Capsule);
                var knobShapeCurrent = knobShapeChoices.Contains(bindingNode.DisplayStyleData.sliderKnobShape)
                    ? bindingNode.DisplayStyleData.sliderKnobShape : SliderKnobShape.Default;
                var knobShapeField = new PopupField<SliderKnobShape>("Knob Shape", knobShapeChoices, knobShapeCurrent,
                    s => ObjectNames.NicifyVariableName(s.ToString()), s => ObjectNames.NicifyVariableName(s.ToString()));
                knobShapeField.tooltip = "Knob shape: Default, Square, Capsule (single sliders only), Rectangle, or Grip (a mixer-fader cap with grip ridges).";
                knobShapeField.style.flexGrow = 1;

                var knobShapeReset = MakeStyleResetButton();
                bool IsKnobShapeOverridden() => bindingNode.DisplayStyleData.sliderKnobShape != SliderKnobShape.Default;
                void SyncKnobShapeReset() => ApplyOverrideChrome(knobShapeField, knobShapeReset, IsKnobShapeOverridden());

                var knobRoundnessRow = new VisualElement();
                knobRoundnessRow.style.flexDirection = FlexDirection.Row;
                knobRoundnessRow.style.alignItems = Align.Center;
                knobRoundnessRow.style.marginBottom = 2;
                knobRoundnessRow.style.display = (bindingNode.DisplayStyleData.sliderKnobShape == SliderKnobShape.Square || bindingNode.DisplayStyleData.sliderKnobShape == SliderKnobShape.Rectangle) ? DisplayStyle.Flex : DisplayStyle.None;

                var knobRoundnessField = new FloatField("Knob Roundness");
                knobRoundnessField.tooltip = "Corner radius of a Square or Rectangle knob (px).";
                knobRoundnessField.value = bindingNode.DisplayStyleData.sliderKnobRoundness;
                knobRoundnessField.style.flexGrow = 1;

                var knobRoundnessReset = MakeStyleResetButton();
                bool IsKnobRoundnessOverridden() => bindingNode.DisplayStyleData.sliderKnobRoundness > 0.001f;
                void SyncKnobRoundnessReset() => ApplyOverrideChrome(knobRoundnessField, knobRoundnessReset, IsKnobRoundnessOverridden());

                knobShapeField.RegisterValueChangedCallback(evt =>
                {
                    var ws = bindingNode.DisplayStyleData; ws.sliderKnobShape = evt.newValue; bindingNode.DisplayStyleData = ws;
                    knobRoundnessRow.style.display = (ws.sliderKnobShape == SliderKnobShape.Square || ws.sliderKnobShape == SliderKnobShape.Rectangle) ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification(); RefreshPreview();
                    SyncKnobShapeReset();
                });

                void DoKnobShapeReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Knob Shape");
                    var ws = bindingNode.DisplayStyleData; ws.sliderKnobShape = SliderKnobShape.Default; bindingNode.DisplayStyleData = ws;
                    knobShapeField.SetValueWithoutNotify(SliderKnobShape.Default);
                    knobRoundnessRow.style.display = DisplayStyle.None;
                    OnModification(); RefreshPreview();
                    SyncKnobShapeReset();
                }
                knobShapeReset.clicked += DoKnobShapeReset;
                AddStyleResetContextMenu(knobShapeRow, IsKnobShapeOverridden, DoKnobShapeReset);

                knobShapeRow.Add(knobShapeField);
                knobShapeRow.Add(knobShapeReset);
                sliderStyleContainer.Add(knobShapeRow);

                knobRoundnessField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Knob Roundness", () =>
                    {
                        var ws = bindingNode.DisplayStyleData; ws.sliderKnobRoundness = Mathf.Max(0f, evt.newValue); bindingNode.DisplayStyleData = ws;
                        SyncKnobRoundnessReset();
                    }, liveRebuild: true);
                });
                FlushValueEditOnBlur(knobRoundnessField);

                void DoKnobRoundnessReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Knob Roundness");
                    var ws = bindingNode.DisplayStyleData; ws.sliderKnobRoundness = 0f; bindingNode.DisplayStyleData = ws;
                    knobRoundnessField.SetValueWithoutNotify(0f);
                    OnModification(); RefreshPreview();
                    SyncKnobRoundnessReset();
                }
                knobRoundnessReset.clicked += DoKnobRoundnessReset;
                AddStyleResetContextMenu(knobRoundnessRow, IsKnobRoundnessOverridden, DoKnobRoundnessReset);

                knobRoundnessRow.Add(knobRoundnessField);
                knobRoundnessRow.Add(knobRoundnessReset);
                sliderStyleContainer.Add(knobRoundnessRow);

                var barColorRow = new VisualElement();
                barColorRow.style.flexDirection = FlexDirection.Row;
                barColorRow.style.alignItems = Align.Center;
                barColorRow.style.marginBottom = 2;

                var barColorField = new ColorField("Track Color");
                barColorField.tooltip = "The slider track color.";
                barColorField.value = bindingNode.DisplayStyleData.sliderBarColor.a > 0.001f ? bindingNode.DisplayStyleData.sliderBarColor : new Color(0.24f, 0.24f, 0.24f, 1f);
                barColorField.style.flexGrow = 1;

                var barColorReset = MakeStyleResetButton();
                bool IsBarColorOverridden() => bindingNode.DisplayStyleData.sliderBarColor.a > 0.001f;
                void SyncBarColorReset() => ApplyOverrideChrome(barColorField, barColorReset, IsBarColorOverridden());

                barColorField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Track Color", () =>
                    {
                        var ws = bindingNode.DisplayStyleData; ws.sliderBarColor = evt.newValue; bindingNode.DisplayStyleData = ws;
                        SyncBarColorReset();
                        // Children (plural): Vector Sliders render one tracker per axis — poke them all.
                        LivePokeChildren(bindingNode, "unity-base-slider__tracker", t => t.style.backgroundColor = evt.newValue);
                    });
                });
                FlushValueEditOnBlur(barColorField);

                void DoBarColorReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Bar Color");
                    var ws = bindingNode.DisplayStyleData; ws.sliderBarColor = Color.clear; bindingNode.DisplayStyleData = ws;
                    barColorField.SetValueWithoutNotify(new Color(0.24f, 0.24f, 0.24f, 1f));
                    OnModification(); RefreshPreview();
                    SyncBarColorReset();
                }
                barColorReset.clicked += DoBarColorReset;
                AddStyleResetContextMenu(barColorRow, IsBarColorOverridden, DoBarColorReset);

                barColorRow.Add(barColorField);
                barColorRow.Add(barColorReset);
                sliderStyleContainer.Add(barColorRow);

                var barHoverColorRow = new VisualElement();
                barHoverColorRow.style.flexDirection = FlexDirection.Row;
                barHoverColorRow.style.alignItems = Align.Center;
                barHoverColorRow.style.marginBottom = 2;

                var barHoverColorField = new ColorField("Track Hover Color");
                barHoverColorField.tooltip = "Track color while the pointer hovers the slider. Reset (alpha 0) = no hover tint.";
                // Show an opaque swatch when unset so the picker opens ready-to-use (full alpha); the stored value
                // stays clear until edited, so the reset chrome still reflects the true unset/overridden state.
                barHoverColorField.value = bindingNode.DisplayStyleData.sliderBarHoverColor.a > 0.001f ? bindingNode.DisplayStyleData.sliderBarHoverColor : new Color(0.32f, 0.32f, 0.32f, 1f);
                barHoverColorField.style.flexGrow = 1;

                var barHoverColorReset = MakeStyleResetButton();
                bool IsBarHoverColorOverridden() => bindingNode.DisplayStyleData.sliderBarHoverColor.a > 0.001f;
                void SyncBarHoverColorReset() => ApplyOverrideChrome(barHoverColorField, barHoverColorReset, IsBarHoverColorOverridden());

                barHoverColorField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Slider Track Hover Color", () =>
                    {
                        var ws = bindingNode.DisplayStyleData; ws.sliderBarHoverColor = evt.newValue; bindingNode.DisplayStyleData = ws;
                        SyncBarHoverColorReset();
                    });
                });
                FlushValueEditOnBlur(barHoverColorField);

                void DoBarHoverColorReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Slider Track Hover Color");
                    var ws = bindingNode.DisplayStyleData; ws.sliderBarHoverColor = Color.clear; bindingNode.DisplayStyleData = ws;
                    barHoverColorField.SetValueWithoutNotify(new Color(0.32f, 0.32f, 0.32f, 1f));
                    OnModification(); RefreshPreview();
                    SyncBarHoverColorReset();
                }
                barHoverColorReset.clicked += DoBarHoverColorReset;
                AddStyleResetContextMenu(barHoverColorRow, IsBarHoverColorOverridden, DoBarHoverColorReset);

                barHoverColorRow.Add(barHoverColorField);
                barHoverColorRow.Add(barHoverColorReset);
                sliderStyleContainer.Add(barHoverColorRow);

                var knobColorRow = new VisualElement();
                knobColorRow.style.flexDirection = FlexDirection.Row;
                knobColorRow.style.alignItems = Align.Center;
                knobColorRow.style.marginBottom = 2;

                var knobColorField = new ColorField("Knob Color");
                knobColorField.tooltip = "The slider knob (dragger) color.";
                knobColorField.value = bindingNode.DisplayStyleData.sliderKnobColor.a > 0.001f ? bindingNode.DisplayStyleData.sliderKnobColor : new Color(0.6f, 0.6f, 0.6f, 1f);
                knobColorField.style.flexGrow = 1;

                var knobColorReset = MakeStyleResetButton();
                bool IsKnobColorOverridden() => bindingNode.DisplayStyleData.sliderKnobColor.a > 0.001f;
                void SyncKnobColorReset() => ApplyOverrideChrome(knobColorField, knobColorReset, IsKnobColorOverridden());

                knobColorField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Knob Color", () =>
                    {
                        var ws = bindingNode.DisplayStyleData; ws.sliderKnobColor = evt.newValue; bindingNode.DisplayStyleData = ws;
                        SyncKnobColorReset();
                        // Children (plural): Vector Sliders render one dragger per axis — poke them all.
                        LivePokeChildren(bindingNode, "unity-base-slider__dragger", d => d.style.backgroundColor = evt.newValue);
                    });
                });
                FlushValueEditOnBlur(knobColorField);

                void DoKnobColorReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Knob Color");
                    var ws = bindingNode.DisplayStyleData; ws.sliderKnobColor = Color.clear; bindingNode.DisplayStyleData = ws;
                    knobColorField.SetValueWithoutNotify(new Color(0.6f, 0.6f, 0.6f, 1f));
                    OnModification(); RefreshPreview();
                    SyncKnobColorReset();
                }
                knobColorReset.clicked += DoKnobColorReset;
                AddStyleResetContextMenu(knobColorRow, IsKnobColorOverridden, DoKnobColorReset);

                knobColorRow.Add(knobColorField);
                knobColorRow.Add(knobColorReset);
                sliderStyleContainer.Add(knobColorRow);

                var knobHoverColorRow = new VisualElement();
                knobHoverColorRow.style.flexDirection = FlexDirection.Row;
                knobHoverColorRow.style.alignItems = Align.Center;
                knobHoverColorRow.style.marginBottom = 2;

                var knobHoverColorField = new ColorField("Knob Hover Color");
                knobHoverColorField.tooltip = "The knob color while the mouse is over it. Unset = automatically derived from the Knob Color so hover feedback never disappears.";
                knobHoverColorField.value = bindingNode.DisplayStyleData.sliderKnobHoverColor.a > 0.001f ? bindingNode.DisplayStyleData.sliderKnobHoverColor : new Color(0.75f, 0.75f, 0.75f, 1f);
                knobHoverColorField.style.flexGrow = 1;

                var knobHoverColorReset = MakeStyleResetButton();
                bool IsKnobHoverColorOverridden() => bindingNode.DisplayStyleData.sliderKnobHoverColor.a > 0.001f;
                void SyncKnobHoverColorReset() => ApplyOverrideChrome(knobHoverColorField, knobHoverColorReset, IsKnobHoverColorOverridden());

                knobHoverColorField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Knob Hover Color", () =>
                    {
                        var ws = bindingNode.DisplayStyleData; ws.sliderKnobHoverColor = evt.newValue; bindingNode.DisplayStyleData = ws;
                        SyncKnobHoverColorReset();
                    });
                });
                FlushValueEditOnBlur(knobHoverColorField);

                void DoKnobHoverColorReset()
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Knob Hover Color");
                    var ws = bindingNode.DisplayStyleData; ws.sliderKnobHoverColor = Color.clear; bindingNode.DisplayStyleData = ws;
                    knobHoverColorField.SetValueWithoutNotify(new Color(0.75f, 0.75f, 0.75f, 1f));
                    OnModification(); RefreshPreview();
                    SyncKnobHoverColorReset();
