                var particleBgDefault = new Color(0.13f, 0.13f, 0.15f, 1f); // matches BindingNode's particleBackgroundColor default

                // Push a live edit onto the already-rendered particle preview (best-of-both-worlds: instant canvas
                // update per tick, undo/save still debounced) instead of a full node rebuild that re-inits the
                // preview renderer each tick. PokeParticleRestyle = per-tick cheap update; PokeParticleReRender =
                // once at commit, re-develop a frozen VFX poster so a zoom/background change actually reframes.
                void PokeParticleRestyle() => LivePokeChild(bindingNode, "sasq-particle-preview-panel",
                    panel => { if (BindingFactory.s_particleLiveRestyle.TryGetValue(panel, out var a)) a(); });
                void PokeParticleReRender() => LivePokeChild(bindingNode, "sasq-particle-preview-panel",
                    panel => { if (BindingFactory.s_particleForceReRender.TryGetValue(panel, out var a)) a(); });

                // Reset-to-default chrome for a plain particle option: a ↺ button (shown only when the value
                // differs from its default) + right-click "Reset to default", matching the other style controls.
                // Returns a sync Action the field's own value-changed callbacks must call so the ↺ shows/hides live.
                Action AttachParticleReset(VisualElement addTo, VisualElement contextTarget, string undoLabel, Func<bool> isDefault, Action applyDefault)
                {
                    var resetBtn = MakeStyleResetButton();
                    resetBtn.style.marginLeft = 4;
                    Action sync = () => resetBtn.style.display = isDefault() ? DisplayStyle.None : DisplayStyle.Flex;
                    void DoReset()
                    {
                        Undo.RecordObject(_clonedLayoutAsset, undoLabel);
                        applyDefault(); // set the model field to its default AND push it into the control(s)
                        sync();
                        OnModification();
                        RefreshPreview();
                    }
                    resetBtn.clicked += DoReset;
                    AddStyleResetContextMenu(contextTarget, () => !isDefault(), DoReset);
                    addTo.Add(resetBtn);
                    sync();
                    return sync;
                }

                // Preview Mode (top of the options) — Field and Thumbnail / Standard / Thumbnail Only / Expandable.
                var particleModeField = new EnumField("Preview Mode", bindingNode.ParticlePreviewMode);
                particleModeField.tooltip = "Field and Thumbnail: object field with the live preview stacked below it. Standard: field left, preview right, on one line. Thumbnail Only: just the preview (assign via the corner button or drag-and-drop). Expandable: a caret left of the field spring-opens the preview.";
                particlePreviewContainer.Add(particleModeField);

                // Interactive (orbit / pan / zoom) — drag to orbit, middle-drag to pan, Alt+scroll to zoom, plus the
                // Reset-view + 2D overlay buttons. Default ON; turn off for a fixed, click-to-play-only preview.
                var particleInteractiveToggle = new Toggle("Interactive (orbit/pan/zoom)");
                particleInteractiveToggle.value = bindingNode.ParticlePreviewInteractive;
                particleInteractiveToggle.tooltip = "Drag to orbit · middle-drag to pan · Alt+scroll to zoom, plus Reset-view + 2D overlay buttons. Off = a fixed view that only plays/stops on click.";
                particleInteractiveToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Particle Interactive");
                    bindingNode.ParticlePreviewInteractive = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                particlePreviewContainer.Add(particleInteractiveToggle);

                // Play On Open (Expandable mode only) — directly below Preview Mode. Auto-play on open; stops on close.
                var particlePlayOnOpenToggle = new Toggle("Play On Open");
                particlePlayOnOpenToggle.value = bindingNode.ParticlePlayOnOpen;
                particlePlayOnOpenToggle.tooltip = "Expandable mode: start playing automatically when the preview is opened (it always stops when closed).";
                particlePlayOnOpenToggle.style.display = bindingNode.ParticlePreviewMode == ParticlePreviewMode.Expandable ? DisplayStyle.Flex : DisplayStyle.None;
                particlePlayOnOpenToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Play On Open");
                    bindingNode.ParticlePlayOnOpen = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                particlePreviewContainer.Add(particlePlayOnOpenToggle);

                // Default to Open (Expandable mode only) — the fold opens by default until the user collapses it.
                var particleStartExpandedToggle = new Toggle("Default to Open");
                particleStartExpandedToggle.value = bindingNode.ParticleDefaultToOpen;
                particleStartExpandedToggle.tooltip = "Expandable mode: the preview fold opens by default (until the user collapses it).";
                particleStartExpandedToggle.style.display = bindingNode.ParticlePreviewMode == ParticlePreviewMode.Expandable ? DisplayStyle.Flex : DisplayStyle.None;
                particleStartExpandedToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Particle Default to Open");
                    bindingNode.ParticleDefaultToOpen = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                particlePreviewContainer.Add(particleStartExpandedToggle);

                // Thumbnail Size (16-256 slider + numeric field) + reset-to-default.
                var particleSizeRow = new VisualElement();
                particleSizeRow.AddToClassList("unity-base-field");
                particleSizeRow.style.flexDirection = FlexDirection.Row;
                particleSizeRow.style.alignItems = Align.Center;
                particleSizeRow.style.marginBottom = 2;

                var particleSizeLabel = new Label("Thumbnail Size");
                particleSizeLabel.AddToClassList("unity-base-field__label");
                particleSizeRow.Add(particleSizeLabel);

                var particleSizeControls = new VisualElement();
                particleSizeControls.AddToClassList("unity-base-field__input");
                particleSizeControls.style.flexDirection = FlexDirection.Row;
                particleSizeControls.style.alignItems = Align.Center;
                particleSizeControls.style.flexGrow = 1;

                var particleSizeSlider = new Slider(16f, 256f);
                particleSizeSlider.value = bindingNode.ParticleThumbnailSize;
                particleSizeSlider.style.flexGrow = 1;
                particleSizeSlider.style.marginRight = 4;

                var particleSizeField = new FloatField();
                particleSizeField.value = bindingNode.ParticleThumbnailSize;
                particleSizeField.isDelayed = true;
                particleSizeField.style.width = 45;
                particleSizeField.style.paddingLeft = 2;
                particleSizeField.style.paddingRight = 2;

                Action syncSizeReset = null;
                particleSizeSlider.RegisterValueChangedCallback(evt =>
                {
                    // Reset chrome syncs at COMMIT, never per tick: the ↺ button lives in the row being
                    // dragged, and toggling it as the value crosses the DEFAULT reflows the row mid-drag —
                    // the held slider narrows, the knob shifts, and the value perturbs (the crossing-default
                    // snap). Same rule at every debounced slider/color site below.
                    HandleDebouncedValueEdit("Change Thumbnail Size", () =>
                    {
                        bindingNode.ParticleThumbnailSize = evt.newValue;
                        particleSizeField.SetValueWithoutNotify(evt.newValue);
                        PokeParticleRestyle();
                    }, onCommit: () => syncSizeReset?.Invoke());
                });
                FlushValueEditOnBlur(particleSizeSlider);
                particleSizeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Thumbnail Size");
                    var clamped = Mathf.Clamp(evt.newValue, 16f, 256f);
                    bindingNode.ParticleThumbnailSize = clamped;
                    particleSizeSlider.SetValueWithoutNotify(clamped);
                    syncSizeReset?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                SyncClampedDisplay(particleSizeField, () => bindingNode.ParticleThumbnailSize);

                particleSizeControls.Add(particleSizeSlider);
                particleSizeControls.Add(particleSizeField);
                syncSizeReset = AttachParticleReset(particleSizeControls, particleSizeRow, "Reset Thumbnail Size",
                    () => Mathf.Approximately(bindingNode.ParticleThumbnailSize, 128f),
                    () => { bindingNode.ParticleThumbnailSize = 128f; particleSizeSlider.SetValueWithoutNotify(128f); particleSizeField.SetValueWithoutNotify(128f); });
                particleSizeRow.Add(particleSizeControls);
                particlePreviewContainer.Add(particleSizeRow);

                // Preview Zoom (0.25-6 slider + numeric field) + reset. VFX-only: a VFX Graph's culling bounds
                // overshoot the visible particles, so this magnifies the camera past them to fill the thumbnail
                // (ParticleSystems ignore it — they already frame tight from sampled particle positions).
                var particleZoomRow = new VisualElement();
                particleZoomRow.AddToClassList("unity-base-field");
                particleZoomRow.style.flexDirection = FlexDirection.Row;
                particleZoomRow.style.alignItems = Align.Center;
                particleZoomRow.style.marginBottom = 2;

                var particleZoomLabel = new Label("Preview Zoom (VFX)");
                particleZoomLabel.AddToClassList("unity-base-field__label");
                particleZoomLabel.tooltip = "VFX Graph only: magnifies the preview camera so the effect fills the thumbnail (its culling bounds are larger than the visible particles).";
                particleZoomRow.Add(particleZoomLabel);

                var particleZoomControls = new VisualElement();
                particleZoomControls.AddToClassList("unity-base-field__input");
                particleZoomControls.style.flexDirection = FlexDirection.Row;
                particleZoomControls.style.alignItems = Align.Center;
                particleZoomControls.style.flexGrow = 1;

                var particleZoomSlider = new Slider(0.25f, 6f);
                particleZoomSlider.value = bindingNode.ParticlePreviewZoom;
                particleZoomSlider.style.flexGrow = 1;
                particleZoomSlider.style.marginRight = 4;

                var particleZoomField = new FloatField();
                particleZoomField.value = bindingNode.ParticlePreviewZoom;
                particleZoomField.isDelayed = true;
                particleZoomField.style.width = 45;
                particleZoomField.style.paddingLeft = 2;
                particleZoomField.style.paddingRight = 2;

                Action syncZoomReset = null;
                particleZoomSlider.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Preview Zoom", () =>
                    {
                        bindingNode.ParticlePreviewZoom = evt.newValue;
                        particleZoomField.SetValueWithoutNotify(evt.newValue);
                        PokeParticleRestyle();
                    }, onCommit: () => { syncZoomReset?.Invoke(); PokeParticleReRender(); });
                });
                FlushValueEditOnBlur(particleZoomSlider);
                particleZoomField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Preview Zoom");
                    var clamped = Mathf.Clamp(evt.newValue, 0.25f, 6f);
                    bindingNode.ParticlePreviewZoom = clamped;
                    particleZoomSlider.SetValueWithoutNotify(clamped);
                    syncZoomReset?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                SyncClampedDisplay(particleZoomField, () => bindingNode.ParticlePreviewZoom);

                particleZoomControls.Add(particleZoomSlider);
                particleZoomControls.Add(particleZoomField);
                syncZoomReset = AttachParticleReset(particleZoomControls, particleZoomRow, "Reset Preview Zoom",
                    () => Mathf.Approximately(bindingNode.ParticlePreviewZoom, 1f),
                    () => { bindingNode.ParticlePreviewZoom = 1f; particleZoomSlider.SetValueWithoutNotify(1f); particleZoomField.SetValueWithoutNotify(1f); });
                particleZoomRow.Add(particleZoomControls);
                particlePreviewContainer.Add(particleZoomRow);

                // Preview Alignment (Left / Center / Right) — same segmented icons as the asset preview. Applies to
                // Field and Thumbnail, Thumbnail Only, and Expandable (not Standard, where the preview is inline).
                var particleAlignRow = new VisualElement();
                particleAlignRow.AddToClassList("unity-base-field");
                particleAlignRow.style.flexDirection = FlexDirection.Row;
                particleAlignRow.style.alignItems = Align.Center;
                particleAlignRow.style.marginBottom = 2;
                particleAlignRow.style.display = bindingNode.ParticlePreviewMode != ParticlePreviewMode.Standard ? DisplayStyle.Flex : DisplayStyle.None;

                var particleAlignLabel = new Label("Preview Alignment");
                particleAlignLabel.AddToClassList("unity-base-field__label");
                particleAlignRow.Add(particleAlignLabel);

                var particleAlignButtonsContainer = new VisualElement();
                particleAlignButtonsContainer.AddToClassList("unity-base-field__input");
                particleAlignButtonsContainer.style.flexDirection = FlexDirection.Row;
                particleAlignButtonsContainer.style.alignItems = Align.Center;
                particleAlignButtonsContainer.style.justifyContent = Justify.FlexEnd;
                particleAlignButtonsContainer.style.flexGrow = 1;

                var particleAlignments = new[]
                {
                    (icon: SasquatchIcons.Ids.AlignStartVertical, value: ImageAlignment.Left, tooltip: "Align preview left"),
                    (icon: SasquatchIcons.Ids.AlignCenterVertical, value: ImageAlignment.Center, tooltip: "Align preview center"),
                    (icon: SasquatchIcons.Ids.AlignEndVertical, value: ImageAlignment.Right, tooltip: "Align preview right")
                };

                var particleAlignButtons = new List<Button>();
                void SyncParticleAlign()
                {
                    for (int i = 0; i < particleAlignments.Length; i++)
                    {
                        bool active = bindingNode.PreviewAlignment == particleAlignments[i].value;
                        particleAlignButtons[i].style.backgroundColor = active ? DesignerPalette.AccentFillSoft : DesignerPalette.ButtonNeutralBg;
                        particleAlignButtons[i].Q<SasquatchIconElement>().Tint = active ? Color.white : DesignerPalette.IconIdle;
                    }
                }

                for (int i = 0; i < particleAlignments.Length; i++)
                {
                    var alignVal = particleAlignments[i].value;
                    var btn = new Button();
                    btn.Add(SasquatchIcons.Create(particleAlignments[i].icon, 13, DesignerPalette.IconIdle));
                    btn.tooltip = particleAlignments[i].tooltip;
                    btn.style.width = 24;
                    btn.style.height = 18;
                    btn.style.paddingLeft = 0;
                    btn.style.paddingRight = 0;
                    btn.style.marginLeft = 2;
                    btn.style.marginRight = 0;
                    btn.style.alignItems = Align.Center;
                    btn.style.justifyContent = Justify.Center;
                    btn.clicked += () =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Preview Alignment");
                        bindingNode.PreviewAlignment = alignVal;
                        OnModification();
                        RefreshPreview();
                        SyncParticleAlign();
                    };
                    AddSegmentedHover(btn, () => bindingNode.PreviewAlignment == alignVal, SyncParticleAlign);
                    particleAlignButtons.Add(btn);
                    particleAlignButtonsContainer.Add(btn);
                }
                SyncParticleAlign();
                particleAlignRow.Add(particleAlignButtonsContainer);
                particlePreviewContainer.Add(particleAlignRow);

                // Background Color (behind the rendered effect; drives both the panel and the preview camera) + reset.
                var particleBgColorRow = new VisualElement();
                particleBgColorRow.style.flexDirection = FlexDirection.Row;
                particleBgColorRow.style.alignItems = Align.Center;
                particleBgColorRow.style.marginBottom = 2;

                var particleBgColorField = new ColorField("Background Color");
                particleBgColorField.style.flexGrow = 1;
                particleBgColorField.value = bindingNode.ParticleBackgroundColor;
                Action syncBgReset = null;
                particleBgColorField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Particle Background Color", () =>
                    {
                        bindingNode.ParticleBackgroundColor = evt.newValue;
                        // Panel bg + camera clear update instantly; a frozen VFX poster recolors via the
                        // paused re-render and re-develops its best-frame poster on commit.
                        PokeParticleRestyle();
                    }, onCommit: () => { syncBgReset?.Invoke(); PokeParticleReRender(); });
                });
                FlushValueEditOnBlur(particleBgColorField);
                particleBgColorRow.Add(particleBgColorField);
                syncBgReset = AttachParticleReset(particleBgColorRow, particleBgColorRow, "Reset Background Color",
                    () => bindingNode.ParticleBackgroundColor == particleBgDefault,
                    () => { bindingNode.ParticleBackgroundColor = particleBgDefault; particleBgColorField.SetValueWithoutNotify(particleBgDefault); });
                particlePreviewContainer.Add(particleBgColorRow);

                // Play Button Placement — a 3x3 Rect-Transform-style pivot grid over the 9 PreviewAnchor positions.
                var particlePosRow = new VisualElement();
                particlePosRow.AddToClassList("unity-base-field");
                particlePosRow.style.flexDirection = FlexDirection.Row;
                particlePosRow.style.alignItems = Align.FlexStart;
                particlePosRow.style.marginBottom = 2;

                var particlePosLabel = new Label("Play Button Placement");
                particlePosLabel.AddToClassList("unity-base-field__label");
                particlePosRow.Add(particlePosLabel);

                var particlePosInput = new VisualElement();
                particlePosInput.AddToClassList("unity-base-field__input");
                particlePosInput.style.flexGrow = 1;
                particlePosInput.style.alignItems = Align.FlexEnd; // align the grid to the right like the other rows

                var pivotGrid = new VisualElement();
                pivotGrid.style.flexDirection = FlexDirection.Column;

                var pivotButtons = new List<Button>();
                void SyncParticlePivot()
                {
                    for (int i = 0; i < pivotButtons.Count; i++)
                    {
                        bool active = (int)bindingNode.ParticlePlayButtonAnchor == i;
                        pivotButtons[i].style.backgroundColor = active ? DesignerPalette.AccentFillSoft : DesignerPalette.ButtonNeutralBg;
                    }
                }
                for (int r = 0; r < 3; r++)
                {
                    var gridRow = new VisualElement();
                    gridRow.style.flexDirection = FlexDirection.Row;
                    for (int c = 0; c < 3; c++)
                    {
                        var anchorVal = (PreviewAnchor)(r * 3 + c);
                        var btn = new Button();
                        btn.tooltip = ObjectNames.NicifyVariableName(anchorVal.ToString());
                        btn.style.width = 16;
                        btn.style.height = 16;
                        btn.style.paddingLeft = 0;
                        btn.style.paddingRight = 0;
                        btn.style.paddingTop = 0;
                        btn.style.paddingBottom = 0;
                        btn.style.marginLeft = 1;
                        btn.style.marginRight = 1;
                        btn.style.marginTop = 1;
                        btn.style.marginBottom = 1;
                        btn.clicked += () =>
                        {
                            Undo.RecordObject(_clonedLayoutAsset, "Change Play Button Placement");
                            bindingNode.ParticlePlayButtonAnchor = anchorVal;
                            OnModification();
                            RefreshPreview();
                            SyncParticlePivot();
                        };
                        AddSegmentedHover(btn, () => bindingNode.ParticlePlayButtonAnchor == anchorVal, SyncParticlePivot);
                        pivotButtons.Add(btn);
                        gridRow.Add(btn);
                    }
                    pivotGrid.Add(gridRow);
                }
                SyncParticlePivot();
                particlePosInput.Add(pivotGrid);
                particlePosRow.Add(particlePosInput);
                particlePreviewContainer.Add(particlePosRow);

                // Play Button Offset — a manual pixel nudge applied on top of the anchor + reset-to-default.
                var particleOffsetRow = new VisualElement();
                particleOffsetRow.style.flexDirection = FlexDirection.Row;
                particleOffsetRow.style.alignItems = Align.Center;
                particleOffsetRow.style.marginBottom = 2;

                var particleOffsetField = new Vector2Field("Play Button Offset");
                particleOffsetField.style.flexGrow = 1;
                particleOffsetField.value = bindingNode.ParticlePlayButtonOffset;
                particleOffsetField.tooltip = "Nudge the play/stop button in pixels from its anchored position.";
                Action syncOffsetReset = null;
                particleOffsetField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Play Button Offset", () =>
                    {
                        bindingNode.ParticlePlayButtonOffset = evt.newValue;
                        PokeParticleRestyle();
                    }, onCommit: () => syncOffsetReset?.Invoke());
                });
                FlushValueEditOnBlur(particleOffsetField);
                particleOffsetRow.Add(particleOffsetField);
                syncOffsetReset = AttachParticleReset(particleOffsetRow, particleOffsetRow, "Reset Play Button Offset",
                    () => bindingNode.ParticlePlayButtonOffset == Vector2.zero,
                    () => { bindingNode.ParticlePlayButtonOffset = Vector2.zero; particleOffsetField.SetValueWithoutNotify(Vector2.zero); });
                particlePreviewContainer.Add(particleOffsetRow);

                // Play Button Size (px width; height scales to keep the badge's aspect).
                var particleBtnSizeRow = new VisualElement();
                particleBtnSizeRow.AddToClassList("unity-base-field");
                particleBtnSizeRow.style.flexDirection = FlexDirection.Row;
                particleBtnSizeRow.style.alignItems = Align.Center;
                particleBtnSizeRow.style.marginBottom = 2;

                var particleBtnSizeLabel = new Label("Play Button Size");
                particleBtnSizeLabel.AddToClassList("unity-base-field__label");
                particleBtnSizeRow.Add(particleBtnSizeLabel);

                var particleBtnSizeControls = new VisualElement();
                particleBtnSizeControls.AddToClassList("unity-base-field__input");
                particleBtnSizeControls.style.flexDirection = FlexDirection.Row;
                particleBtnSizeControls.style.alignItems = Align.Center;
                particleBtnSizeControls.style.flexGrow = 1;

                var particleBtnSizeSlider = new Slider(24f, 96f);
                particleBtnSizeSlider.value = bindingNode.ParticlePlayButtonWidth;
                particleBtnSizeSlider.style.flexGrow = 1;
                particleBtnSizeSlider.style.marginRight = 4;

                var particleBtnSizeField = new FloatField();
                particleBtnSizeField.value = bindingNode.ParticlePlayButtonWidth;
                particleBtnSizeField.isDelayed = true;
                particleBtnSizeField.style.width = 45;
                particleBtnSizeField.style.paddingLeft = 2;
                particleBtnSizeField.style.paddingRight = 2;

                Action syncBtnSizeReset = null;
                particleBtnSizeSlider.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Play Button Size", () =>
                    {
                        bindingNode.ParticlePlayButtonWidth = evt.newValue;
                        particleBtnSizeField.SetValueWithoutNotify(evt.newValue);
                        PokeParticleRestyle();
                    }, onCommit: () => syncBtnSizeReset?.Invoke());
                });
                FlushValueEditOnBlur(particleBtnSizeSlider);
                particleBtnSizeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Play Button Size");
                    var clamped = Mathf.Clamp(evt.newValue, 24f, 96f);
                    bindingNode.ParticlePlayButtonWidth = clamped;
                    particleBtnSizeSlider.SetValueWithoutNotify(clamped);
                    syncBtnSizeReset?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                SyncClampedDisplay(particleBtnSizeField, () => bindingNode.ParticlePlayButtonWidth);

                particleBtnSizeControls.Add(particleBtnSizeSlider);
                particleBtnSizeControls.Add(particleBtnSizeField);
                syncBtnSizeReset = AttachParticleReset(particleBtnSizeControls, particleBtnSizeRow, "Reset Play Button Size",
                    () => Mathf.Approximately(bindingNode.ParticlePlayButtonWidth, 32f),
                    () => { bindingNode.ParticlePlayButtonWidth = 32f; particleBtnSizeSlider.SetValueWithoutNotify(32f); particleBtnSizeField.SetValueWithoutNotify(32f); });
                particleBtnSizeRow.Add(particleBtnSizeControls);
                particlePreviewContainer.Add(particleBtnSizeRow);

                // Mode change → show/hide the Expandable-only Play On Open toggle and the alignment row (hidden for Standard).
                particleModeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Particle Preview Mode");
                    bindingNode.ParticlePreviewMode = (ParticlePreviewMode)evt.newValue;
                    particlePlayOnOpenToggle.style.display = bindingNode.ParticlePreviewMode == ParticlePreviewMode.Expandable ? DisplayStyle.Flex : DisplayStyle.None;
                    particleStartExpandedToggle.style.display = bindingNode.ParticlePreviewMode == ParticlePreviewMode.Expandable ? DisplayStyle.Flex : DisplayStyle.None;
                    particleAlignRow.style.display = bindingNode.ParticlePreviewMode != ParticlePreviewMode.Standard ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                    RefreshPreview();
                });

                displayStyleFoldout.Add(particlePreviewContainer);

                // ----- Animation Curve editor options (DisplayType == AnimationCurveEditor) -----
                var curveContainer = new VisualElement();
                curveContainer.style.display = bindingNode.DisplayType == DisplayType.AnimationCurveEditor ? DisplayStyle.Flex : DisplayStyle.None;

                // Editor Mode — Inline well vs Expandable caret panel vs Expandable + field preview.
                var curveModeField = new EnumField("Editor Mode", bindingNode.CurveEditorMode);
                curveModeField.tooltip = "Inline: a compact, live-editable graph well under the field. Expandable: a caret that spring-opens the editor. Expandable + Field Preview: a caret AND a small always-visible preview of the curve beside the field.";

                var curveStartExpandedToggle = new Toggle("Default to Open") { value = bindingNode.WidgetDefaultToOpen };
                curveStartExpandedToggle.tooltip = "When Expandable, the fold starts open (until the user collapses it).";
                curveStartExpandedToggle.style.marginLeft = 14;
                bool curveIsExpandable = bindingNode.CurveEditorMode == CurveEditorMode.Expandable || bindingNode.CurveEditorMode == CurveEditorMode.ExpandableWithPreview;
                curveStartExpandedToggle.style.display = curveIsExpandable ? DisplayStyle.Flex : DisplayStyle.None;
                curveStartExpandedToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Open By Default");
                    bindingNode.WidgetDefaultToOpen = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });

                curveModeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Curve Editor Mode");
                    bindingNode.CurveEditorMode = (CurveEditorMode)evt.newValue;
                    bool expandable = bindingNode.CurveEditorMode == CurveEditorMode.Expandable || bindingNode.CurveEditorMode == CurveEditorMode.ExpandableWithPreview;
                    curveStartExpandedToggle.style.display = expandable ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                    RefreshPreview();
                });
                curveContainer.Add(curveModeField);
                curveContainer.Add(curveStartExpandedToggle);

                // Resizable — drag a handle at the bottom of the well to size it (like a resizable text box). When
                // on, the fixed Well Height row is hidden (the handle owns the height instead). Default on.
                Action syncCurveHeightVis = null;
                var curveResizableToggle = new Toggle("Resizable") { value = bindingNode.CurveResizable };
                curveResizableToggle.tooltip = "Drag a handle at the bottom of the well to resize it. When on, the fixed Well Height option is hidden.";
                curveResizableToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Curve Resizable");
                    bindingNode.CurveResizable = evt.newValue;
                    syncCurveHeightVis?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                curveContainer.Add(curveResizableToggle);

                // Well Height (24-160 slider + numeric field) + reset-to-default (mirrors the particle Thumbnail Size row).
                var curveHeightRow = new VisualElement();
                curveHeightRow.AddToClassList("unity-base-field");
                curveHeightRow.style.flexDirection = FlexDirection.Row;
                curveHeightRow.style.alignItems = Align.Center;
                curveHeightRow.style.marginBottom = 2;
                var curveHeightLabel = new Label("Well Height");
                curveHeightLabel.AddToClassList("unity-base-field__label");
                curveHeightRow.Add(curveHeightLabel);
                var curveHeightControls = new VisualElement();
                curveHeightControls.AddToClassList("unity-base-field__input");
                curveHeightControls.style.flexDirection = FlexDirection.Row;
                curveHeightControls.style.alignItems = Align.Center;
                curveHeightControls.style.flexGrow = 1;
                var curveHeightSlider = new Slider(24f, 160f) { value = bindingNode.CurveWellHeight };
                curveHeightSlider.style.flexGrow = 1;
                curveHeightSlider.style.marginRight = 4;
                var curveHeightField = new FloatField { value = bindingNode.CurveWellHeight, isDelayed = true };
                curveHeightField.style.width = 45;
                Action syncCurveHeightReset = null;
                curveHeightSlider.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Curve Well Height", () =>
                    {
                        bindingNode.CurveWellHeight = evt.newValue;
                        curveHeightField.SetValueWithoutNotify(evt.newValue);
                        LivePokeCurveWell(bindingNode, w => w.style.height = evt.newValue);
                    }, onCommit: () => syncCurveHeightReset?.Invoke());
                });
                FlushValueEditOnBlur(curveHeightSlider);
                curveHeightField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Curve Well Height");
                    var clamped = Mathf.Clamp(evt.newValue, 24f, 160f);
                    bindingNode.CurveWellHeight = clamped;
                    curveHeightSlider.SetValueWithoutNotify(clamped);
                    syncCurveHeightReset?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                SyncClampedDisplay(curveHeightField, () => bindingNode.CurveWellHeight);
                curveHeightControls.Add(curveHeightSlider);
                curveHeightControls.Add(curveHeightField);
                syncCurveHeightReset = AttachParticleReset(curveHeightControls, curveHeightRow, "Reset Curve Well Height",
                    () => Mathf.Approximately(bindingNode.CurveWellHeight, 56f),
                    () => { bindingNode.CurveWellHeight = 56f; curveHeightSlider.SetValueWithoutNotify(56f); curveHeightField.SetValueWithoutNotify(56f); });
                curveHeightRow.Add(curveHeightControls);
                curveContainer.Add(curveHeightRow);

                // Well Height is meaningless when Resizable owns the height — hide it then.
                syncCurveHeightVis = () => curveHeightRow.style.display = bindingNode.CurveResizable ? DisplayStyle.None : DisplayStyle.Flex;
                syncCurveHeightVis();

                // Color rows (each with a ↺ reset to its BindingNode default). Returns the row so callers can show/hide it.
                VisualElement AddCurveColorRow(string label, string tip, Func<Color> get, Action<Color> set, Color def, string undo)
                {
                    var row = new VisualElement();
                    row.AddToClassList("unity-base-field");
                    row.style.flexDirection = FlexDirection.Row;
                    row.style.alignItems = Align.Center;
                    row.style.marginBottom = 2;
                    var lbl = new Label(label);
                    lbl.AddToClassList("unity-base-field__label");
                    if (!string.IsNullOrEmpty(tip)) lbl.tooltip = tip;
                    row.Add(lbl);
                    var input = new VisualElement();
                    input.AddToClassList("unity-base-field__input");
                    input.style.flexDirection = FlexDirection.Row;
                    input.style.alignItems = Align.Center;
                    input.style.flexGrow = 1;
                    var cf = new ColorField { showAlpha = true, value = get() };
                    cf.style.flexGrow = 1;
                    Action sync = null;
                    cf.RegisterValueChangedCallback(evt =>
                    {
                        HandleDebouncedValueEdit(undo, () =>
                        {
                            set(evt.newValue);
                            // Curve line/fill/background are painted from the live node — just repaint the control.
                            LivePokeCanvasElement(bindingNode, el => el.Query<SasquatchCurveControl>().ForEach(c => c.MarkDirtyRepaint()));
                        }, onCommit: () => sync?.Invoke());
                    });
                    FlushValueEditOnBlur(cf);
                    input.Add(cf);
                    sync = AttachParticleReset(input, row, undo, () => get() == def, () => { set(def); cf.SetValueWithoutNotify(def); });
                    row.Add(input);
                    curveContainer.Add(row);
                    return row;
                }

                AddCurveColorRow("Curve Color", "The curve stroke color.",
                    () => bindingNode.CurveLineColor, v => bindingNode.CurveLineColor = v,
                    new Color(0.45f, 0.78f, 1f, 1f), "Change Curve Color");
                AddCurveColorRow("Fill Color", "The soft wash under the curve.",
                    () => bindingNode.CurveFillColor, v => bindingNode.CurveFillColor = v,
                    new Color(0.45f, 0.78f, 1f, 0.14f), "Change Curve Fill Color");
                AddCurveColorRow("Background Color", "The graph well background.",
                    () => bindingNode.CurveBackgroundColor, v => bindingNode.CurveBackgroundColor = v,
                    new Color(0.118f, 0.118f, 0.118f, 1f), "Change Curve Background");

                // Well border — color (theme-aware default via override) + width (0-6). Mirrors the gradient border.
                curveContainer.Add(CreateOverridableColorElement("Border Color",
                    () => bindingNode.CurveBorderColor, v => bindingNode.CurveBorderColor = v, RefreshPreview,
                    liveApply: () => LivePokeCurveWell(bindingNode, w => BindingFactory.ApplyCurveWellBorder(w, bindingNode))));

                var curveBorderWidthRow = new VisualElement();
                curveBorderWidthRow.AddToClassList("unity-base-field");
                curveBorderWidthRow.style.flexDirection = FlexDirection.Row;
                curveBorderWidthRow.style.alignItems = Align.Center;
                curveBorderWidthRow.style.marginBottom = 2;
                var curveBorderWidthLabel = new Label("Border Width");
                curveBorderWidthLabel.AddToClassList("unity-base-field__label");
                curveBorderWidthRow.Add(curveBorderWidthLabel);
                var curveBorderWidthControls = new VisualElement();
                curveBorderWidthControls.AddToClassList("unity-base-field__input");
                curveBorderWidthControls.style.flexDirection = FlexDirection.Row;
                curveBorderWidthControls.style.alignItems = Align.Center;
                curveBorderWidthControls.style.flexGrow = 1;
                var curveBorderWidthSlider = new Slider(0f, 6f) { value = bindingNode.CurveBorderWidth };
                curveBorderWidthSlider.style.flexGrow = 1;
                curveBorderWidthSlider.style.marginRight = 4;
                var curveBorderWidthField = new FloatField { value = bindingNode.CurveBorderWidth, isDelayed = true };
                curveBorderWidthField.style.width = 45;
                Action syncCurveBorderWidthReset = null;
                curveBorderWidthSlider.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Curve Border Width", () =>
                    {
                        bindingNode.CurveBorderWidth = Mathf.Round(evt.newValue);
                        curveBorderWidthSlider.SetValueWithoutNotify(bindingNode.CurveBorderWidth);
                        curveBorderWidthField.SetValueWithoutNotify(bindingNode.CurveBorderWidth);
                        LivePokeCurveWell(bindingNode, w => BindingFactory.ApplyCurveWellBorder(w, bindingNode));
                    }, onCommit: () => syncCurveBorderWidthReset?.Invoke());
                });
                FlushValueEditOnBlur(curveBorderWidthSlider);
                curveBorderWidthField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Curve Border Width");
                    var clamped = Mathf.Clamp(Mathf.Round(evt.newValue), 0f, 6f);
                    bindingNode.CurveBorderWidth = clamped;
                    curveBorderWidthSlider.SetValueWithoutNotify(clamped);
                    syncCurveBorderWidthReset?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                SyncClampedDisplay(curveBorderWidthField, () => bindingNode.CurveBorderWidth);
                curveBorderWidthControls.Add(curveBorderWidthSlider);
                curveBorderWidthControls.Add(curveBorderWidthField);
                syncCurveBorderWidthReset = AttachParticleReset(curveBorderWidthControls, curveBorderWidthRow, "Reset Curve Border Width",
                    () => Mathf.Approximately(bindingNode.CurveBorderWidth, 1f),
                    () => { bindingNode.CurveBorderWidth = 1f; curveBorderWidthSlider.SetValueWithoutNotify(1f); curveBorderWidthField.SetValueWithoutNotify(1f); });
                curveBorderWidthRow.Add(curveBorderWidthControls);
                curveContainer.Add(curveBorderWidthRow);

                // Show Grid toggle + grid-color row (shown only when the grid is on).
                VisualElement curveGridColorRow = null;
                System.Action syncCurveGridSizeVis = null; // the Grid Size row shows whenever the grid OR snapping is on
                var curveShowGridToggle = new Toggle("Show Grid") { value = bindingNode.CurveShowGrid };
                curveShowGridToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Curve Grid");
                    bindingNode.CurveShowGrid = evt.newValue;
                    if (curveGridColorRow != null) curveGridColorRow.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                    syncCurveGridSizeVis?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                curveContainer.Add(curveShowGridToggle);
                curveGridColorRow = AddCurveColorRow("Grid Color", "The value/time grid line color.",
                    () => bindingNode.CurveGridColor, v => bindingNode.CurveGridColor = v,
                    new Color(1f, 1f, 1f, 0.06f), "Change Curve Grid Color");
                curveGridColorRow.style.display = bindingNode.CurveShowGrid ? DisplayStyle.Flex : DisplayStyle.None;

                // Fixed Y range: when off, the editor auto-frames to the curve's value bounds.
                var curveFixedYToggle = new Toggle("Fixed Y Range") { value = bindingNode.CurveRangeMin.isOverridden && bindingNode.CurveRangeMax.isOverridden };
                curveFixedYToggle.tooltip = "Off: the editor auto-frames to the curve's value range. On: pin the Y axis to the Min/Max below.";
                var curveYRangeRow = new VisualElement();
                curveYRangeRow.style.flexDirection = FlexDirection.Row;
                curveYRangeRow.style.alignItems = Align.Center;
                curveYRangeRow.style.marginBottom = 2;
                var curveYMinField = new FloatField("Min Y") { value = bindingNode.CurveRangeMin.value };
                curveYMinField.style.flexGrow = 1;
