                curveYRangeRow.Add(curveYMaxField);
                void SyncCurveYRangeVisibility() => curveYRangeRow.style.display = curveFixedYToggle.value ? DisplayStyle.Flex : DisplayStyle.None;
                curveFixedYToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Fixed Curve Y Range");
                    var lo = bindingNode.CurveRangeMin; lo.isOverridden = evt.newValue; bindingNode.CurveRangeMin = lo;
                    var hi = bindingNode.CurveRangeMax; hi.isOverridden = evt.newValue; bindingNode.CurveRangeMax = hi;
                    SyncCurveYRangeVisibility();
                    OnModification();
                    RefreshPreview();
                });
                curveYMinField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Curve Min Y", () =>
                    {
                        var lo = bindingNode.CurveRangeMin; lo.value = evt.newValue; bindingNode.CurveRangeMin = lo;
                    });
                });
                FlushValueEditOnBlur(curveYMinField);
                curveYMaxField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Curve Max Y", () =>
                    {
                        var hi = bindingNode.CurveRangeMax; hi.value = evt.newValue; bindingNode.CurveRangeMax = hi;
                    });
                });
                FlushValueEditOnBlur(curveYMaxField);
                curveContainer.Add(curveFixedYToggle);
                curveContainer.Add(curveYRangeRow);
                SyncCurveYRangeVisibility();

                // Snap-to-grid toggle + the shared Grid Size (one size drives both the grid lines and the snap step).
                var curveSnapToggle = new Toggle("Snap To Grid") { value = bindingNode.CurveSnapToGrid };
                curveSnapToggle.tooltip = "Snap dragged keyframes onto the value/time grid — keys land line-to-line. Set the spacing with Grid Size below.";
                curveSnapToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Curve Snap To Grid");
                    bindingNode.CurveSnapToGrid = evt.newValue;
                    syncCurveGridSizeVis?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                curveContainer.Add(curveSnapToggle);

                // Grid Size (value-axis curve units) — the time axis derives a matching square step.
                var curveGridSizeField = new FloatField("Grid Size");
                curveGridSizeField.tooltip = "Spacing of the value axis' grid lines, in curve units. The time axis picks the closest clean step that keeps the cells SQUARE, and Snap To Grid lands keys on the drawn lines of both axes — a smaller size = a finer grid and tighter snapping.";
                var curveGridSizeRow = CreateResettableNumberField<float>(
                    curveGridSizeField, 0.25f,
                    () => bindingNode.CurveGridSize,
                    v => bindingNode.CurveGridSize = v,
                    v => Mathf.Clamp(v, 0.001f, 1000f),
                    "Change Curve Grid Size");
                curveContainer.Add(curveGridSizeRow);
                syncCurveGridSizeVis = () => curveGridSizeRow.style.display =
                    (bindingNode.CurveShowGrid || bindingNode.CurveSnapToGrid) ? DisplayStyle.Flex : DisplayStyle.None;
                syncCurveGridSizeVis();

                var curveReadOnlyToggle = new Toggle("Read-Only Inline") { value = bindingNode.CurveReadOnlyInline };
                curveReadOnlyToggle.tooltip = "Make the inline well view-only; the curve stays editable in the resizable window.";
                curveReadOnlyToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Curve Read-Only Inline");
                    bindingNode.CurveReadOnlyInline = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                curveContainer.Add(curveReadOnlyToggle);

                // Editable Max-Y / Max-X overlays (LineRenderer-style): show small editable fields over the graph
