                var curveEditMaxYToggle = new Toggle("Editable Max Y") { value = bindingNode.CurveEditableMaxY };
                curveEditMaxYToggle.tooltip = "Show an editable Max-Y field over the top of the graph to rescale the value axis (Frame All clears it).";
                curveEditMaxYToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Curve Editable Max Y");
                    bindingNode.CurveEditableMaxY = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                curveContainer.Add(curveEditMaxYToggle);

                var curveEditMaxXToggle = new Toggle("Editable Max X") { value = bindingNode.CurveEditableMaxX };
                curveEditMaxXToggle.tooltip = "Show an editable Max-X field at the right of the graph to rescale the time axis (Frame All clears it).";
                curveEditMaxXToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Curve Editable Max X");
                    bindingNode.CurveEditableMaxX = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                curveContainer.Add(curveEditMaxXToggle);

                displayStyleFoldout.Add(curveContainer);

                // ----- Gradient editor options (DisplayType == Gradient) -----
                var gradientContainer = new VisualElement();
                gradientContainer.style.display = bindingNode.DisplayType == DisplayType.Gradient ? DisplayStyle.Flex : DisplayStyle.None;

                // Editor Mode — Inline strip vs Expandable caret panel vs Expandable + field preview.
                var gradientModeField = new EnumField("Editor Mode", bindingNode.GradientEditorMode);
                gradientModeField.tooltip = "Inline: a compact, live-editable strip under the field. Expandable: a caret that spring-opens the editor. Expandable + Field Preview: a caret AND a small always-visible preview of the gradient beside the field.";

                var gradientStartExpandedToggle = new Toggle("Default to Open") { value = bindingNode.WidgetDefaultToOpen };
                gradientStartExpandedToggle.tooltip = "When Expandable, the fold starts open (until the user collapses it).";
                gradientStartExpandedToggle.style.marginLeft = 14;
                bool gradientIsExpandable = bindingNode.GradientEditorMode == GradientEditorMode.Expandable || bindingNode.GradientEditorMode == GradientEditorMode.ExpandableWithPreview;
                gradientStartExpandedToggle.style.display = gradientIsExpandable ? DisplayStyle.Flex : DisplayStyle.None;
                gradientStartExpandedToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Open By Default");
                    bindingNode.WidgetDefaultToOpen = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });

                gradientModeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Gradient Editor Mode");
                    bindingNode.GradientEditorMode = (GradientEditorMode)evt.newValue;
                    bool expandable = bindingNode.GradientEditorMode == GradientEditorMode.Expandable || bindingNode.GradientEditorMode == GradientEditorMode.ExpandableWithPreview;
                    gradientStartExpandedToggle.style.display = expandable ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                    RefreshPreview();
                });
                gradientContainer.Add(gradientModeField);
                gradientContainer.Add(gradientStartExpandedToggle);

                // Pin Layout — faithful Dual-Track vs compact Merged split-hemisphere.
                var gradientPinLayoutField = new EnumField("Pin Layout", bindingNode.GradientPinLayout);
                gradientPinLayoutField.tooltip = "Dual Track: alpha pins on top, color pins on bottom (faithful Unity model, up to 8 each). Merged: split-hemisphere pins editing color + alpha together (unions key times; Dual Track is the lossless escape hatch).";
                gradientPinLayoutField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Gradient Pin Layout");
                    bindingNode.GradientPinLayout = (GradientPinLayout)evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                gradientContainer.Add(gradientPinLayoutField);

                // HDR — let color keys exceed 1 (the pin color picker gains an intensity control). Imported from
                // [GradientUsage(hdr)]; the strip clamps for display (like Unity's own), the stored keys stay HDR.
                var gradientHdrToggle = new Toggle("HDR") { value = bindingNode.GradientHdr };
                gradientHdrToggle.tooltip = "Author HDR color keys — the pin color picker gains an intensity control so colors can exceed 1 (for bloom / emissive gradients).";
                gradientHdrToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Gradient HDR");
                    bindingNode.GradientHdr = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                gradientContainer.Add(gradientHdrToggle);

                // Resizable — drag a handle at the bottom of the strip to size it. When on, the fixed Strip Height row is hidden.
                Action syncGradientHeightVis = null;
                var gradientResizableToggle = new Toggle("Resizable") { value = bindingNode.GradientResizable };
                gradientResizableToggle.tooltip = "Drag a handle at the bottom of the strip to resize it. When on, the fixed Strip Height option is hidden.";
                gradientResizableToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Gradient Resizable");
                    bindingNode.GradientResizable = evt.newValue;
                    syncGradientHeightVis?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                gradientContainer.Add(gradientResizableToggle);

                // Strip Height (18-80 slider + numeric field) + reset-to-default (mirrors the curve Well Height row).
                var gradientHeightRow = new VisualElement();
                gradientHeightRow.AddToClassList("unity-base-field");
                gradientHeightRow.style.flexDirection = FlexDirection.Row;
                gradientHeightRow.style.alignItems = Align.Center;
                gradientHeightRow.style.marginBottom = 2;
                var gradientHeightLabel = new Label("Strip Height");
                gradientHeightLabel.AddToClassList("unity-base-field__label");
                gradientHeightRow.Add(gradientHeightLabel);
                var gradientHeightControls = new VisualElement();
                gradientHeightControls.AddToClassList("unity-base-field__input");
                gradientHeightControls.style.flexDirection = FlexDirection.Row;
                gradientHeightControls.style.alignItems = Align.Center;
                gradientHeightControls.style.flexGrow = 1;
                var gradientHeightSlider = new Slider(18f, 80f) { value = bindingNode.GradientWellHeight };
                gradientHeightSlider.style.flexGrow = 1;
                gradientHeightSlider.style.marginRight = 4;
                var gradientHeightField = new FloatField { value = bindingNode.GradientWellHeight, isDelayed = true };
                gradientHeightField.style.width = 45;
                Action syncGradientHeightReset = null;
                gradientHeightSlider.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Gradient Strip Height", () =>
                    {
                        bindingNode.GradientWellHeight = evt.newValue;
                        gradientHeightField.SetValueWithoutNotify(evt.newValue);
                        LivePokeGradientWell(bindingNode, w => w.style.height = evt.newValue);
                    }, onCommit: () => syncGradientHeightReset?.Invoke());
                });
                FlushValueEditOnBlur(gradientHeightSlider);
                gradientHeightField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Gradient Strip Height");
                    var clamped = Mathf.Clamp(evt.newValue, 18f, 80f);
                    bindingNode.GradientWellHeight = clamped;
                    gradientHeightSlider.SetValueWithoutNotify(clamped);
                    syncGradientHeightReset?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                SyncClampedDisplay(gradientHeightField, () => bindingNode.GradientWellHeight);
                gradientHeightControls.Add(gradientHeightSlider);
                gradientHeightControls.Add(gradientHeightField);
                syncGradientHeightReset = AttachParticleReset(gradientHeightControls, gradientHeightRow, "Reset Gradient Strip Height",
                    () => Mathf.Approximately(bindingNode.GradientWellHeight, 28f),
                    () => { bindingNode.GradientWellHeight = 28f; gradientHeightSlider.SetValueWithoutNotify(28f); gradientHeightField.SetValueWithoutNotify(28f); });
                gradientHeightRow.Add(gradientHeightControls);
                gradientContainer.Add(gradientHeightRow);

                // Strip Height is meaningless when Resizable owns the height — hide it then.
                syncGradientHeightVis = () => gradientHeightRow.style.display = bindingNode.GradientResizable ? DisplayStyle.None : DisplayStyle.Flex;
                syncGradientHeightVis();

                // Color rows (each with a ↺ reset to its BindingNode default).
                VisualElement AddGradientColorRow(string label, string tip, Func<Color> get, Action<Color> set, Color def, string undo)
                {
                    var row = new VisualElement();
                    row.AddToClassList("unity-base-field");
                    row.style.flexDirection = FlexDirection.Row;
                    row.style.alignItems = Align.Center;
                    row.style.marginBottom = 2;
                    var lbl = new Label(label);
                    lbl.AddToClassList("unity-base-field__label");
                    if (!string.IsNullOrEmpty(tip)) lbl.tooltip = tip;
                    row.Add(lbl);
                    var input = new VisualElement();
                    input.AddToClassList("unity-base-field__input");
                    input.style.flexDirection = FlexDirection.Row;
                    input.style.alignItems = Align.Center;
                    input.style.flexGrow = 1;
                    var cf = new ColorField { showAlpha = true, value = get() };
                    cf.style.flexGrow = 1;
                    Action sync = null;
                    cf.RegisterValueChangedCallback(evt =>
                    {
                        HandleDebouncedValueEdit(undo, () =>
                        {
                            set(evt.newValue);
                            // Gradient border color lives as an inline style on the well — re-apply from the node.
                            LivePokeGradientWell(bindingNode, w => BindingFactory.ApplyGradientWellBorder(w, bindingNode));
                        }, onCommit: () => sync?.Invoke());
                    });
                    FlushValueEditOnBlur(cf);
                    input.Add(cf);
                    sync = AttachParticleReset(input, row, undo, () => get() == def, () => { set(def); cf.SetValueWithoutNotify(def); });
                    row.Add(input);
                    gradientContainer.Add(row);
                    return row;
                }

                AddGradientColorRow("Border", "The strip well border color.",
                    () => bindingNode.GradientBorderColor, v => bindingNode.GradientBorderColor = v,
                    new Color(0.247f, 0.247f, 0.247f, 1f), "Change Gradient Border");

                // Border Width (0-6 slider + numeric field) + reset-to-default (1).
                var gradientBorderWidthRow = new VisualElement();
                gradientBorderWidthRow.AddToClassList("unity-base-field");
                gradientBorderWidthRow.style.flexDirection = FlexDirection.Row;
                gradientBorderWidthRow.style.alignItems = Align.Center;
                gradientBorderWidthRow.style.marginBottom = 2;
                var gradientBorderWidthLabel = new Label("Border Width");
                gradientBorderWidthLabel.AddToClassList("unity-base-field__label");
                gradientBorderWidthRow.Add(gradientBorderWidthLabel);
                var gradientBorderWidthControls = new VisualElement();
                gradientBorderWidthControls.AddToClassList("unity-base-field__input");
                gradientBorderWidthControls.style.flexDirection = FlexDirection.Row;
                gradientBorderWidthControls.style.alignItems = Align.Center;
                gradientBorderWidthControls.style.flexGrow = 1;
                var gradientBorderWidthSlider = new Slider(0f, 6f) { value = bindingNode.GradientBorderWidth };
                gradientBorderWidthSlider.style.flexGrow = 1;
                gradientBorderWidthSlider.style.marginRight = 4;
                var gradientBorderWidthField = new FloatField { value = bindingNode.GradientBorderWidth, isDelayed = true };
                gradientBorderWidthField.style.width = 45;
                Action syncGradientBorderWidthReset = null;
                gradientBorderWidthSlider.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Gradient Border Width", () =>
                    {
                        bindingNode.GradientBorderWidth = Mathf.Round(evt.newValue);
                        gradientBorderWidthSlider.SetValueWithoutNotify(bindingNode.GradientBorderWidth);
                        gradientBorderWidthField.SetValueWithoutNotify(bindingNode.GradientBorderWidth);
                        LivePokeGradientWell(bindingNode, w => BindingFactory.ApplyGradientWellBorder(w, bindingNode));
                    }, onCommit: () => syncGradientBorderWidthReset?.Invoke());
                });
                FlushValueEditOnBlur(gradientBorderWidthSlider);
                gradientBorderWidthField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Gradient Border Width");
                    var clamped = Mathf.Clamp(Mathf.Round(evt.newValue), 0f, 6f);
                    bindingNode.GradientBorderWidth = clamped;
                    gradientBorderWidthSlider.SetValueWithoutNotify(clamped);
                    syncGradientBorderWidthReset?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                SyncClampedDisplay(gradientBorderWidthField, () => bindingNode.GradientBorderWidth);
                gradientBorderWidthControls.Add(gradientBorderWidthSlider);
                gradientBorderWidthControls.Add(gradientBorderWidthField);
                syncGradientBorderWidthReset = AttachParticleReset(gradientBorderWidthControls, gradientBorderWidthRow, "Reset Gradient Border Width",
                    () => Mathf.Approximately(bindingNode.GradientBorderWidth, 1f),
                    () => { bindingNode.GradientBorderWidth = 1f; gradientBorderWidthSlider.SetValueWithoutNotify(1f); gradientBorderWidthField.SetValueWithoutNotify(1f); });
                gradientBorderWidthRow.Add(gradientBorderWidthControls);
                gradientContainer.Add(gradientBorderWidthRow);

                // Read-Only Inline.
                var gradientReadOnlyToggle = new Toggle("Read-Only Inline") { value = bindingNode.GradientReadOnlyInline };
                gradientReadOnlyToggle.tooltip = "Make the inline strip view-only; the gradient stays editable in the resizable window.";
                gradientReadOnlyToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Gradient Read-Only Inline");
                    bindingNode.GradientReadOnlyInline = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                gradientContainer.Add(gradientReadOnlyToggle);

                // NOTE: the active palette is chosen via the inline gear in the editor (not here); the checkerboard
                // is always on with hardcoded colors. So those options are intentionally not exposed in this panel.
                var gradientPaletteDotToggle = new Toggle("Palette Match Ring") { value = bindingNode.GradientShowPaletteDot };
                gradientPaletteDotToggle.tooltip = "Draw a slim accent ring around any pin whose color matches a swatch in the active palette.";
                gradientPaletteDotToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Gradient Palette Dot");
                    bindingNode.GradientShowPaletteDot = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                gradientContainer.Add(gradientPaletteDotToggle);

                displayStyleFoldout.Add(gradientContainer);

                // ----- Enum Badge Grid options (DisplayType == EnumBadgeGrid) -----
                var enumBadgeContainer = new VisualElement();
                enumBadgeContainer.style.display = bindingNode.DisplayType == DisplayType.EnumBadgeGrid ? DisplayStyle.Flex : DisplayStyle.None;

                // Resolve whether the bound field is a [Flags] enum (build-time): only those are multi-select, so
                // the None/All quick-chip option is only meaningful — and only shown — for them. The resolved
                // type also feeds the per-value styling editor below.
                var ebEnumType = ResolveSelectedNodeFieldType(bindingNode);
                bool enumBadgeIsFlags = ebEnumType != null && ebEnumType.IsEnum
                    && ebEnumType.IsDefined(typeof(System.FlagsAttribute), false);

                // Columns — fixed grid columns, or 0 to auto-wrap. With a ↺ reset-to-default (0).
                var enumBadgeColumnsField = new IntegerField("Columns (0 = auto)");
                enumBadgeColumnsField.tooltip = "Fixed number of grid columns, or 0 to auto-wrap badges to fit the width.";
                enumBadgeContainer.Add(CreateResettableNumberField<int>(
                    enumBadgeColumnsField, 0,
                    () => bindingNode.EnumBadgeColumns,
                    v => bindingNode.EnumBadgeColumns = v,
                    v => Mathf.Max(0, v),
                    "Change Enum Badge Columns"));

                // Badge Height (px) — a draggable slider (live poke while dragging, one coalesced undo per drag,
                // like the progress bar Height) with a ↺ reset-to-default (20).
                var enumBadgeHeightField = new Slider("Badge Height", 14f, 60f) { showInputField = true };
                enumBadgeHeightField.tooltip = "Height of each badge in pixels (14-60).";
                enumBadgeContainer.Add(CreateResettableNumberField<float>(
                    enumBadgeHeightField, 20f,
                    () => bindingNode.EnumBadgeHeight,
                    v => bindingNode.EnumBadgeHeight = v,
                    v => Mathf.Clamp(v, 14f, 60f),
                    "Change Enum Badge Height",
                    liveApply: v => LivePokeCanvasElement(bindingNode, el =>
                        el.Query(className: "sasq-enum-badge").ForEach(b => { b.style.height = v; b.style.minHeight = v; }))));

                // Badge Width (px) — a fixed width for every badge, or 0 to size each one to its own label.
                // Columns WINS: a fixed column count already dictates the badge width, so this row only bites
                // while Columns is 0 (auto-wrap) and is greyed out otherwise rather than silently doing nothing.
                var enumBadgeWidthField = new Slider("Badge Width", 0f, 400f) { showInputField = true };
                enumBadgeWidthField.tooltip = "Fixed width for every badge in pixels; 0 sizes each badge to its label. "
                                            + "Ignored while Columns is set — the column count decides the width.";
                var enumBadgeWidthRow = CreateResettableNumberField<float>(
                    enumBadgeWidthField, 0f,
                    () => bindingNode.EnumBadgeWidth,
                    v => bindingNode.EnumBadgeWidth = v,
                    v => Mathf.Clamp(v, 0f, 400f),
                    "Change Enum Badge Width",
                    liveApply: v => LivePokeCanvasElement(bindingNode, el =>
                    {
                        if (bindingNode.EnumBadgeColumns > 0) return; // columns own the width — nothing to poke
                        el.Query(className: "sasq-enum-badge").ForEach(b =>
                        {
                            if (v > 0f) { b.style.width = v; b.style.minWidth = v; b.style.flexShrink = 0f; }
                            else { b.style.width = StyleKeyword.Null; b.style.minWidth = StyleKeyword.Null; b.style.flexShrink = StyleKeyword.Null; }
                        });
                    }));
                // Polled rather than driven off the Columns field's change event: the ↺ reset writes Columns with
                // SetValueWithoutNotify, so an event-only gate would sit stale after a reset-to-auto.
                bool enumBadgeWidthEnabled = bindingNode.EnumBadgeColumns == 0;
                enumBadgeWidthRow.SetEnabled(enumBadgeWidthEnabled);
                enumBadgeWidthRow.schedule.Execute(() =>
                {
                    bool want = bindingNode.EnumBadgeColumns == 0;
                    if (want == enumBadgeWidthEnabled) return;
                    enumBadgeWidthEnabled = want;
                    enumBadgeWidthRow.SetEnabled(want);
                }).Every(250);
                enumBadgeContainer.Add(enumBadgeWidthRow);

                // Badge Spacing — draggable slider too; no cheap poke (the gap==0 → USS-default case needs a real
                // rebuild), so it rides the live single-node rebuild path (liveApply==null ⇒ liveRebuild:true).
                var enumBadgeSpacingField = new Slider("Badge Spacing", 0f, 24f) { showInputField = true };
                enumBadgeSpacingField.tooltip = "Gap between badges in pixels. 0 = the stylesheet default.";
                enumBadgeContainer.Add(CreateResettableNumberField<float>(
                    enumBadgeSpacingField, 0f,
                    () => bindingNode.EnumBadgeSpacing,
                    v => bindingNode.EnumBadgeSpacing = v,
                    v => Mathf.Max(0f, v),
                    "Change Enum Badge Spacing"));

                // Text Backdrop — the label (and its per-value icon) on a dark pill inside the chip.
                var enumBadgeBackdropToggle = new Toggle("Text Backdrop") { value = bindingNode.EnumBadgeTextBackdrop };
                enumBadgeBackdropToggle.tooltip = "Sit each badge's label — and its icon — on a soft dark pill inside the chip, "
                    + "for guaranteed readability over any accent or per-value color. The pill only shows on a selected badge; "
                    + "its space is reserved either way, so the grid never re-flows as you click.";
                enumBadgeBackdropToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Enum Badge Text Backdrop");
                    bindingNode.EnumBadgeTextBackdrop = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                enumBadgeContainer.Add(enumBadgeBackdropToggle);

                // Show All / None quick chips — [Flags] enums only.
                if (enumBadgeIsFlags)
                {
                    var enumBadgeAllNoneToggle = new Toggle("Show All/None") { value = bindingNode.EnumBadgeShowAllNone };
                    enumBadgeAllNoneToggle.tooltip = "Show the None and All quick chips (the None chip is hidden when the enum already declares a 0 value).";
                    enumBadgeAllNoneToggle.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Toggle Enum Badge All/None");
                        bindingNode.EnumBadgeShowAllNone = evt.newValue;
                        OnModification();
                        RefreshPreview();
                    });
                    enumBadgeContainer.Add(enumBadgeAllNoneToggle);
                }

                // Include [Obsolete] members.
                var enumBadgeObsoleteToggle = new Toggle("Include Obsolete") { value = bindingNode.EnumBadgeIncludeObsolete };
                enumBadgeObsoleteToggle.tooltip = "Also surface enum members marked [Obsolete] as badges (otherwise hidden unless currently set).";
                enumBadgeObsoleteToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Enum Badge Obsolete");
                    bindingNode.EnumBadgeIncludeObsolete = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                enumBadgeContainer.Add(enumBadgeObsoleteToggle);

                // Active Color — reuses DisplayStyleData.accent (the active/selected badge tint).
                enumBadgeContainer.Add(CreateOverridableColorElement("Accent Color",
                    () => bindingNode.DisplayStyleData.accent,
                    val => { var ws = bindingNode.DisplayStyleData; ws.accent = val; bindingNode.DisplayStyleData = ws; },
                    RefreshPreview));

                // Per-value styling: custom tint + leading icon for individual enum members.
                // Per-member colors/icons are keyed to ONE enum's member names — identity, so it never fans out.
                enumBadgeContainer.Add(Identity(BuildEnumBadgeOverridesEditor(bindingNode, ebEnumType)));

                displayStyleFoldout.Add(enumBadgeContainer);

                // ----- Rating options (DisplayType == Rating) -----
                var ratingContainer = new VisualElement();
                ratingContainer.style.display = bindingNode.DisplayType == DisplayType.Rating ? DisplayStyle.Flex : DisplayStyle.None;

                var ratingCountField = new IntegerField("Pips");
                ratingCountField.tooltip = "How many rating pips to show (1-10).";
                ratingContainer.Add(CreateResettableNumberField<int>(
                    ratingCountField, 5,
                    () => bindingNode.RatingCount,
                    v => bindingNode.RatingCount = v,
                    v => Mathf.Clamp(v, 1, 10),
                    "Change Rating Pips"));

                var ratingStyleField = new EnumField("Icon", bindingNode.RatingStyle);
                ratingStyleField.tooltip = "Which glyph each pip draws (stars / hearts / dots).";
                ratingStyleField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Rating Icon");
                    bindingNode.RatingStyle = (RatingIconStyle)evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                ratingContainer.Add(ratingStyleField);

                // Pip Size — draggable slider (live rebuild per drag, one coalesced undo) + ↺ reset-to-default (15).
                // Getter treats a legacy 0/unset as the effective default 15 so it reads as "not overridden".
                var ratingSizeSlider = new Slider("Pip Size", 8f, 48f) { showInputField = true };
                ratingSizeSlider.tooltip = "Glyph size of each pip in pixels (8-48). Default 15.";
                ratingContainer.Add(CreateResettableNumberField<float>(
                    ratingSizeSlider, 15f,
                    () => bindingNode.RatingPipSize <= 0f ? 15f : bindingNode.RatingPipSize,
                    v => bindingNode.RatingPipSize = v,
                    v => Mathf.Clamp(v, 8f, 48f),
                    "Change Rating Pip Size"));

                ratingContainer.Add(CreateOverridableColorElement("Selected Color",
                    () => bindingNode.RatingSelectedColor,
                    val => bindingNode.RatingSelectedColor = val,
                    RefreshPreview));
                ratingContainer.Add(CreateOverridableColorElement("Unselected Color",
                    () => bindingNode.RatingUnselectedColor,
                    val => bindingNode.RatingUnselectedColor = val,
                    RefreshPreview));
                ratingContainer.Add(CreateOverridableColorElement("Hover Color",
                    () => bindingNode.RatingHoverColor,
                    val => bindingNode.RatingHoverColor = val,
                    RefreshPreview));

                var ratingAnimateToggle = new Toggle("Animate") { value = bindingNode.RatingAnimate };
                ratingAnimateToggle.tooltip = "Play the hover/press scale spring on pips (on by default).";
                ratingAnimateToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Rating Animation");
                    bindingNode.RatingAnimate = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                ratingContainer.Add(ratingAnimateToggle);

                displayStyleFoldout.Add(ratingContainer);

                // ----- Dictionary table (Display Type = Dictionary, OR any SerializedDictionary field) -----
                // TWO routes reach the Sasquatch dictionary table, and both must offer these rows or the
                // control is dead on one of them - so the gate is DisplayTypeCatalog.ShowsDictionaryTable,
                // the single predicate the quick-edit popup and the live builder ask as well.
                var dictionaryContainer = new VisualElement();
                dictionaryContainer.style.display =
                    DisplayTypeCatalog.ShowsDictionaryTable(bindingNode.DisplayType, axisPipsFieldType)
                        ? DisplayStyle.Flex : DisplayStyle.None;

                var dictStyleField = new EnumField("Dictionary Style", bindingNode.DictionaryStyle);
                dictStyleField.tooltip =
                    "The overall look of the Key / Value table.\n\n" +
                    "Table - bordered shell with a column header (the default).\n" +
                    "Minimal - no shell; quiet column hints and air.\n" +
                    "Ledger - recessed well, zebra rows, one continuous rule down the column split.\n" +
                    "Mapping - the key becomes a chip with an arrow to the value; no column header.\n\n" +
                    "Independent of Row Frame below, so every style works with every frame.";

                // Row Frame is declared BEFORE the style callback so the style row can refresh its dependent
                // colour row too (a style change never alters the frame, but both share one sync helper and
                // keeping them in one place is what stops the two rows drifting out of agreement).
                var dictFrameField = new EnumField("Row Frame", bindingNode.DictionaryRowSeparator);
                dictFrameField.tooltip =
                    "The per-row surface, exactly as a List collection uses it - same enum, same renderer.\n\n" +
                    "None - bare rows (the default).\n" +
                    "Line - a hairline between rows, never after the last one.\n" +
                    "Card - a filled tray per row with a left edge rail. This is the one for tall values " +
                    "(a struct, a nested list): the rail is the only cue that scales with row height.";

                var dictFrameColorRow = CreateOverridableColorElement("Frame Color",
                    () => bindingNode.DictionarySeparatorColor,
                    val => bindingNode.DictionarySeparatorColor = val,
                    RefreshPreview);
                dictFrameColorRow.tooltip =
                    "Tint of the row frame: the hairline in Line mode, the left edge rail in Card mode. " +
                    "Unset tracks the theme.";

                // Frame Colour is meaningless with no frame to tint, so it hides rather than sitting there
                // inert - the same call the collection's separator colour row makes.
                Action syncDictFrameColorVisibility = () =>
                    dictFrameColorRow.style.display =
                        bindingNode.DictionaryRowSeparator != CollectionRowSeparator.None
                            ? DisplayStyle.Flex : DisplayStyle.None;

                dictStyleField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Dictionary Style");
                    bindingNode.DictionaryStyle = (DictionaryTableStyle)evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                dictionaryContainer.Add(dictStyleField);

                dictFrameField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Dictionary Row Frame");
                    bindingNode.DictionaryRowSeparator = (CollectionRowSeparator)evt.newValue;
                    syncDictFrameColorVisibility();
                    OnModification();
                    RefreshPreview();
                });
                dictionaryContainer.Add(dictFrameField);
                dictionaryContainer.Add(dictFrameColorRow);
                syncDictFrameColorVisibility();

                displayStyleFoldout.Add(dictionaryContainer);

                // ----- XY Pad options (DisplayType == XYPad) -----
                var xyPadContainer = new VisualElement();
                xyPadContainer.style.display = bindingNode.DisplayType == DisplayType.XYPad ? DisplayStyle.Flex : DisplayStyle.None;
                xyPadContainer.Add(BuildImageAlignmentRow("Alignment",
                    () => bindingNode.XYPadAlignment, v => bindingNode.XYPadAlignment = v, "Change XY Pad Alignment"));
                // X/Y range, set here in the designer (defaults 0..1). Like the other vector displays it
                // ignores any [Range] attribute, so the bounds stay in the layout and a Revert stays clean.
                xyPadContainer.Add(BuildOverridableFloatField("Range Min", bindingNode.RangeMin, 0f,
                    "Change Range Min", val => bindingNode.RangeMin = val, RefreshPreview));
                xyPadContainer.Add(BuildOverridableFloatField("Range Max", bindingNode.RangeMax, 1f,
                    "Change Range Max", val => bindingNode.RangeMax = val, RefreshPreview));

                // Per-part colors (each with a ↺ reset to the theme default: handle → accent, bg → well, grid → border).
                xyPadContainer.Add(CreateOverridableColorElement("Handle Color",
                    () => bindingNode.XYPadHandleColor, v => bindingNode.XYPadHandleColor = v, RefreshPreview));
                xyPadContainer.Add(CreateOverridableColorElement("Background Color",
                    () => bindingNode.XYPadBackgroundColor, v => bindingNode.XYPadBackgroundColor = v, RefreshPreview));
                xyPadContainer.Add(CreateOverridableColorElement("Grid Color",
                    () => bindingNode.XYPadGridColor, v => bindingNode.XYPadGridColor = v, RefreshPreview));

                // Grid + snap (mirrors the curve widget). Grid Size is shown whenever the grid OR snapping is on.
                System.Action syncXYPadGridSizeVis = null;
                var xyPadShowGridToggle = new Toggle("Show Grid") { value = bindingNode.XYPadShowGrid };
                xyPadShowGridToggle.tooltip = "Draw a value grid across the pad every Grid Size units, with a center crosshair anchor. Off = a clean pad with just the handle.";
                xyPadShowGridToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle XY Pad Grid");
                    bindingNode.XYPadShowGrid = evt.newValue;
                    syncXYPadGridSizeVis?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                xyPadContainer.Add(xyPadShowGridToggle);

                var xyPadSnapToggle = new Toggle("Snap To Grid") { value = bindingNode.XYPadSnapToGrid };
                xyPadSnapToggle.tooltip = "Snap a dragged handle onto the grid lines — it lands on clean multiples of Grid Size. Set the spacing with Grid Size below.";
                xyPadSnapToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle XY Pad Snap To Grid");
                    bindingNode.XYPadSnapToGrid = evt.newValue;
                    syncXYPadGridSizeVis?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                xyPadContainer.Add(xyPadSnapToggle);

                var xyPadGridSizeField = new FloatField("Grid Size");
                xyPadGridSizeField.tooltip = "Grid line spacing in value units (the same units as Range Min/Max). Snap To Grid lands the handle on these lines — a smaller size = a finer grid and tighter snapping.";
                var xyPadGridSizeRow = CreateResettableNumberField<float>(
                    xyPadGridSizeField, 0.25f,
                    () => bindingNode.XYPadGridSize,
                    v => bindingNode.XYPadGridSize = v,
                    v => Mathf.Clamp(v, 0.001f, 1000f),
                    "Change XY Pad Grid Size");
                xyPadContainer.Add(xyPadGridSizeRow);
                syncXYPadGridSizeVis = () => xyPadGridSizeRow.style.display =
                    (bindingNode.XYPadShowGrid || bindingNode.XYPadSnapToGrid) ? DisplayStyle.Flex : DisplayStyle.None;
                syncXYPadGridSizeVis();

                System.Action syncXYPadCrosshairVis = null;
                var xyPadCrosshairToggle = new Toggle("Handle Crosshair") { value = bindingNode.XYPadHandleCrosshair };
                xyPadCrosshairToggle.tooltip = "Draw full-width crosshair lines through the handle that follow it as you drag (default off) — an aiming aid, separate from the grid.";
                xyPadCrosshairToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle XY Pad Handle Crosshair");
                    bindingNode.XYPadHandleCrosshair = evt.newValue;
                    syncXYPadCrosshairVis?.Invoke();
                    OnModification();
                    RefreshPreview();
                });
                xyPadContainer.Add(xyPadCrosshairToggle);

                var xyPadCrosshairThicknessField = new FloatField("Crosshair Thickness");
                xyPadCrosshairThicknessField.tooltip = "Line thickness of the handle crosshair, in pixels.";
                var xyPadCrosshairThicknessRow = CreateResettableNumberField<float>(
                    xyPadCrosshairThicknessField, 1f,
                    () => bindingNode.XYPadCrosshairThickness,
                    v => bindingNode.XYPadCrosshairThickness = v,
                    v => Mathf.Clamp(v, 0.5f, 8f),
                    "Change XY Pad Crosshair Thickness");
                xyPadContainer.Add(xyPadCrosshairThicknessRow);

                var xyPadCrosshairColorRow = CreateOverridableColorElement("Crosshair Color",
                    () => bindingNode.XYPadCrosshairColor, v => bindingNode.XYPadCrosshairColor = v, RefreshPreview);
                xyPadCrosshairColorRow.tooltip = "Handle-crosshair line color. Leave unset to track the grid color.";
                xyPadContainer.Add(xyPadCrosshairColorRow);

                syncXYPadCrosshairVis = () =>
                {
                    var vis = bindingNode.XYPadHandleCrosshair ? DisplayStyle.Flex : DisplayStyle.None;
                    xyPadCrosshairThicknessRow.style.display = vis;
                    xyPadCrosshairColorRow.style.display = vis;
                };
                syncXYPadCrosshairVis();

                var xyPadEditableToggle = new Toggle("Editable Fields") { value = bindingNode.XYPadEditableFields };
                xyPadEditableToggle.tooltip = "Show editable X/Y number fields under the pad you can type into (default off = a compact read-only readout).";
                xyPadEditableToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle XY Pad Editable Fields");
                    bindingNode.XYPadEditableFields = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                xyPadContainer.Add(xyPadEditableToggle);
                displayStyleFoldout.Add(xyPadContainer);

                // ----- Vector Sliders options (DisplayType == VectorSliders) -----
                var vectorSlidersContainer = new VisualElement();
                vectorSlidersContainer.style.display = bindingNode.DisplayType == DisplayType.VectorSliders ? DisplayStyle.Flex : DisplayStyle.None;

                // Per-axis range, set here in the designer (defaults -1..1). A [Range] attribute on a vector
                // is deliberately ignored — Unity can't draw it there, so the bounds live in the layout.
                vectorSlidersContainer.Add(BuildOverridableFloatField("Range Min", bindingNode.RangeMin, -1f,
                    "Change Range Min", val => bindingNode.RangeMin = val, RefreshPreview));
                vectorSlidersContainer.Add(BuildOverridableFloatField("Range Max", bindingNode.RangeMax, 1f,
                    "Change Range Max", val => bindingNode.RangeMax = val, RefreshPreview));

                var vectorNormalizeToggle = new Toggle("Show Normalize") { value = bindingNode.VectorShowNormalize };
                vectorNormalizeToggle.tooltip = "Show the Normalize button that rescales the vector to unit length.";

                // Everything below is the Normalize button's own options + full appearance — shown only while on.
                var normStyleGroup = new VisualElement();
                normStyleGroup.style.display = bindingNode.VectorShowNormalize ? DisplayStyle.Flex : DisplayStyle.None;

                normStyleGroup.Add(BuildImageAlignmentRow("Normalize Alignment",
                    () => bindingNode.VectorNormalizeAlignment, v => bindingNode.VectorNormalizeAlignment = v, "Change Normalize Alignment"));

                var normStyleField = new EnumField("Button Style", bindingNode.NormalizeButtonStyle);
                normStyleField.tooltip = "Visual preset for the Normalize button (Classic = stock Unity chrome).";
                var normAccentRow = CreateOverridableColorElement("Accent Color",
                    () => bindingNode.NormalizeButtonAccent, v => bindingNode.NormalizeButtonAccent = v, RefreshPreview);
                var normRadiusRow = CreateOverridableFloatElement("Corner Radius",
                    () => bindingNode.NormalizeButtonCornerRadius, v => bindingNode.NormalizeButtonCornerRadius = v, RefreshPreview);
                var normSizeField = MakeButtonSizeField("Size", bindingNode.NormalizeButtonSize);
                var normHoverAnimField = new EnumField("Hover Animation", bindingNode.NormalizeButtonHoverAnimation);
                var normHoverColorRow = CreateOverridableColorElement("Hover Color",
                    () => bindingNode.NormalizeButtonHoverColor, v => bindingNode.NormalizeButtonHoverColor = v, RefreshPreview);
                var normPressedColorRow = CreateOverridableColorElement("Pressed Color",
                    () => bindingNode.NormalizeButtonPressedColor, v => bindingNode.NormalizeButtonPressedColor = v, RefreshPreview);

                // Accent / radius / hover motion + colors do nothing on the stock (Classic) button.
                void SyncNormClassicRows()
                {
                    var show = bindingNode.NormalizeButtonStyle == ButtonStyle.Classic ? DisplayStyle.None : DisplayStyle.Flex;
                    normAccentRow.style.display = show;
                    normRadiusRow.style.display = show;
                    normHoverAnimField.style.display = show;
                    normHoverColorRow.style.display = show;
                    normPressedColorRow.style.display = show;
                }
                normStyleField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Normalize Button Style");
                    bindingNode.NormalizeButtonStyle = (ButtonStyle)evt.newValue;
                    SyncNormClassicRows();
                    OnModification();
                    RefreshPreview();
                });
                normSizeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Normalize Button Size");
                    bindingNode.NormalizeButtonSize = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                normHoverAnimField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Normalize Hover Animation");
                    bindingNode.NormalizeButtonHoverAnimation = (ButtonHoverAnimation)evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                normStyleGroup.Add(normStyleField);
                normStyleGroup.Add(normAccentRow);
                normStyleGroup.Add(normRadiusRow);
                normStyleGroup.Add(normSizeField);
                normStyleGroup.Add(normHoverAnimField);
                normStyleGroup.Add(normHoverColorRow);
                normStyleGroup.Add(normPressedColorRow);
                SyncNormClassicRows();

                vectorNormalizeToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Vector Normalize");
                    bindingNode.VectorShowNormalize = evt.newValue;
                    normStyleGroup.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                    RefreshPreview();
                });
                vectorSlidersContainer.Add(vectorNormalizeToggle);
                vectorSlidersContainer.Add(normStyleGroup);
                displayStyleFoldout.Add(vectorSlidersContainer);

#if SASQ_CUSTOM_WIDGET
                // ----- Custom Widget options (DisplayType == CustomWidget) -----
                // Pick the SasquatchCustomWidget asset and map its NON-primary inputs to sibling properties (the
                // primary input is fed by this binding's own Property Path). The New/Edit → composer buttons are
                // added by CustomWidgetComposerHooks once the composer window exists.
                static string GetCwInputMap(BindingNode n, string inputName)
                {
                    if (n.CustomWidgetInputs == null) return "";
                    foreach (var m in n.CustomWidgetInputs)
                        if (m.InputName == inputName) return m.PropertyPath ?? "";
                    return "";
                }
                static void SetCwInputMap(BindingNode n, string inputName, string path)
                {
                    n.CustomWidgetInputs ??= new List<CustomWidgetInputMap>();
                    for (int i = 0; i < n.CustomWidgetInputs.Count; i++)
                    {
                        if (n.CustomWidgetInputs[i].InputName == inputName)
                        {
                            if (string.IsNullOrEmpty(path)) { n.CustomWidgetInputs.RemoveAt(i); return; }
                            n.CustomWidgetInputs[i] = new CustomWidgetInputMap(inputName, path);
                            return;
                        }
                    }
                    if (!string.IsNullOrEmpty(path)) n.CustomWidgetInputs.Add(new CustomWidgetInputMap(inputName, path));
                }

                var customWidgetContainer = new VisualElement();
                customWidgetContainer.style.display = bindingNode.DisplayType == DisplayType.CustomWidget ? DisplayStyle.Flex : DisplayStyle.None;

                var cwAssetField = new ObjectField("Widget Asset")
                {
                    objectType = typeof(SasquatchCustomWidget),
                    allowSceneObjects = false,
                    value = CustomWidgetLibrary.Resolve(bindingNode.CustomWidgetGuid)
                };
                cwAssetField.tooltip = "The custom widget asset (radial graph, gauge, bar cluster…) that renders this field. The bound field feeds the widget's primary input.";

                var cwInputsContainer = new VisualElement();
                cwInputsContainer.style.marginLeft = 14;

                Action rebuildCwInputRows = null;
                rebuildCwInputRows = () =>
                {
                    cwInputsContainer.Clear();
                    var cw = CustomWidgetLibrary.Resolve(bindingNode.CustomWidgetGuid);
                    if (cw == null || cw.Inputs == null) return;
                    var primaryInput = cw.PrimaryInput;
                    bool anyMapped = false;
                    foreach (var inp in cw.Inputs)
                    {
                        if (inp == null || inp == primaryInput || string.IsNullOrEmpty(inp.Name)) continue;
                        anyMapped = true;
                        var mapField = new TextField(inp.Name) { value = GetCwInputMap(bindingNode, inp.Name) };
                        mapField.tooltip = $"Sibling property path feeding the '{inp.Name}' input ({inp.Kind}).";
                        mapField.RegisterValueChangedCallback(evt =>
                            HandleDebouncedTextEdit("Map Custom Widget Input", () => SetCwInputMap(bindingNode, inp.Name, evt.newValue)));
                        FlushTextEditOnBlur(mapField);
                        AutocompleteTextField.Attach(mapField, () =>
                        {
                            var targetType = ResolveTargetType();
                            if (targetType == null) return Array.Empty<string>();
                            var all = SasquatchReflectionUtility.GetSerializableProperties(targetType);
                            string basePath = GetEffectiveBasePath(bindingNode, _clonedLayoutAsset?.Root, "") ?? "";
                            if (!string.IsNullOrEmpty(basePath))
                            {
                                string prefix = basePath + ".";
                                return all.Where(p => !p.isCollection && p.path.StartsWith(prefix)).Select(p => p.path.Substring(prefix.Length));
                            }
                            var collPrefixes = all.Where(p => p.isCollection).Select(p => p.path + ".").ToList();
                            return all.Where(p => !p.isCollection && !collPrefixes.Any(cp => p.path.StartsWith(cp))).Select(p => p.path);
                        }, s => FieldPathSnippet(s.Value, GetEffectiveBasePath(bindingNode, _clonedLayoutAsset?.Root, "")));
                        cwInputsContainer.Add(mapField);
                    }
                    if (!anyMapped)
                    {
                        var note = new Label("This widget has only a primary input (fed by the field above).");
                        note.style.whiteSpace = WhiteSpace.Normal;
                        note.style.opacity = 0.7f;
                        cwInputsContainer.Add(note);
                    }
                };

                cwAssetField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Assign Custom Widget");
                    var w = evt.newValue as SasquatchCustomWidget;
                    bindingNode.CustomWidgetGuid = w != null ? CustomWidgetLibrary.GuidOf(w) : "";
                    rebuildCwInputRows();
                    OnModification();
                    RefreshPreview();
                });

                customWidgetContainer.Add(cwAssetField);
                customWidgetContainer.Add(cwInputsContainer);
                rebuildCwInputRows();
                // Extension point: composer New/Edit buttons attach here (see CustomWidgetComposerHooks).
                CustomWidgetComposerHooks.AttachDesignerButtons(customWidgetContainer, () => bindingNode, cwAssetField, rebuildCwInputRows,
                    () => { OnModification(); RefreshPreview(); });
                displayStyleFoldout.Add(customWidgetContainer);
#endif

                displayStyleFoldout.Add(previewSettingsContainer);

                // Corner Radius override — hidden for MinMaxSlider (it does nothing there) and AssetPreview.
                cornerRadiusControl = CreateOverridableFloatElement("Corner Radius",
                    () => bindingNode.DisplayStyleData.cornerRadius,
                    val => { var ws = bindingNode.DisplayStyleData; ws.cornerRadius = val; bindingNode.DisplayStyleData = ws; },
                    RefreshPreview, liveApply: () => LivePokeWidgetRadius(bindingNode));
                updateCornerRadiusVisibility();
                displayStyleFoldout.Add(cornerRadiusControl);

                // ----- Rich Text Preview (Text widget) — sits BELOW Corner Radius -----
                // Master toggle: turn a plain Text field into a split-pane editor (live formatted preview + an
                // optional formatting toolbar that wraps the highlighted text). Its sub-options reveal when on.
                var textRichContainer = new VisualElement();
                textRichContainer.style.display = bindingNode.DisplayType == DisplayType.Text ? DisplayStyle.Flex : DisplayStyle.None;

                var richPreviewToggle = new Toggle("Rich Text Preview") { value = bindingNode.RichTextPreview };
                // Tooltip text must never contain literal < > — the editor tooltip window renders with a
                // rich-text style, so real tags get parsed and eaten (this one collapsed to a 10px sliver).
                // Show tag examples with ‹ › lookalikes instead.
                richPreviewToggle.tooltip = "Show a live, formatted preview under the text box so markup like ‹b›, ‹color› and ‹size› renders as you type — with a toolbar that wraps the highlighted text in the matching tag.";

                var richSubGroup = new VisualElement();
                richSubGroup.style.display = bindingNode.RichTextPreview ? DisplayStyle.Flex : DisplayStyle.None;
                richSubGroup.style.marginLeft = 14;

                var richToolbarToggle = new Toggle("Show Formatting Toolbar") { value = bindingNode.RichTextToolbar };
                richToolbarToggle.tooltip = "Show the Bold / Italic / Underline / Color / Size / More toolbar above the text box. Each control wraps the highlighted text; the Color chips come from this field's palette.";
                richToolbarToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Rich Text Toolbar");
                    bindingNode.RichTextToolbar = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                richSubGroup.Add(richToolbarToggle);

                // Preview Background — the formatted "result bubble" backing (unset ⇒ dark slate).
                richSubGroup.Add(CreateOverridableColorElement("Preview Background",
                    () => bindingNode.RichTextPreviewBackground,
                    val => bindingNode.RichTextPreviewBackground = val,
                    RefreshPreview));

                // Preview Corner Radius — explicitly for the preview bubble (distinct from the field's Corner Radius).
                richSubGroup.Add(CreateOverridableFloatElement("Preview Corner Radius",
                    () => bindingNode.RichTextPreviewCornerRadius,
                    val => bindingNode.RichTextPreviewCornerRadius = val,
                    RefreshPreview));

                richPreviewToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Rich Text Preview");
                    bindingNode.RichTextPreview = evt.newValue;
                    richSubGroup.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                    RefreshPreview();
                });
                textRichContainer.Add(richPreviewToggle);
                textRichContainer.Add(richSubGroup);
                displayStyleFoldout.Add(textRichContainer);

                // Initial evaluation of foldout visibility based on default widget options
                updateDisplayStyleFoldoutVisibility();

                // Hand the foldout to the outer scope; it's added to _propertiesContainer above Appearance.
                displayStyleSection = displayStyleFoldout;

                widgetField.RegisterValueChangedCallback(evt =>
                {
                    var kind = (DisplayType)evt.newValue;
                    // "Label Above Field" lives in the GENERAL section, not this foldout, but it is per-Display
                    // Type all the same and the panel is not rebuilt on a Display Type change — so it is flipped
                    // from here with everything else that shows and hides.
                    // The field type matters as much as the kind here: a SerializedDictionary reaches the same
                    // titled table on Default, so the toggle must stay hidden for it whatever Display Type the
                    // user picks. axisPipsFieldType is this node's resolved field type, captured above.
                    labelAboveToggle.style.display = DisplayTypeCatalog.SupportsLabelAbove(kind, axisPipsFieldType)
                        ? DisplayStyle.Flex : DisplayStyle.None;
                    minMaxContainer.style.display = (kind == DisplayType.MinMaxSlider || kind == DisplayType.ProgressBar || kind == DisplayType.Slider) ? DisplayStyle.Flex : DisplayStyle.None;
                    minMaxStyleContainer.style.display = kind == DisplayType.MinMaxSlider ? DisplayStyle.Flex : DisplayStyle.None;
                    progressBarStyleContainer.style.display = kind == DisplayType.ProgressBar ? DisplayStyle.Flex : DisplayStyle.None;
                    colorPaletteContainer.style.display = kind == DisplayType.ColorPalette ? DisplayStyle.Flex : DisplayStyle.None;
                    unityEventContainer.style.display = kind == DisplayType.UnityEvent ? DisplayStyle.Flex : DisplayStyle.None;
                    if (kind == DisplayType.ProgressBar)
                    {
                        interactiveToggle.value = true;
                    }

                    bool isMinMax = kind == DisplayType.MinMaxSlider;
                    bool isSlider = kind == DisplayType.Slider;
                    bool isVectorSliders = kind == DisplayType.VectorSliders;
                    sliderStyleContainer.style.display = (isSlider || isMinMax || isVectorSliders) ? DisplayStyle.Flex : DisplayStyle.None;
                    showFieldRow.style.display = isSlider ? DisplayStyle.Flex : DisplayStyle.None;
                    placementRow.style.display = (isSlider && !bindingNode.DisplayStyleData.sliderHideField) ? DisplayStyle.Flex : DisplayStyle.None;
                    centerBarColorRow.style.display = isMinMax ? DisplayStyle.Flex : DisplayStyle.None;

                    updateCornerRadiusVisibility(); // Dynamically show/hide corner radius based on kind and style
                    toggleStyleContainer.style.display = kind == DisplayType.Toggle ? DisplayStyle.Flex : DisplayStyle.None;
                    textContainer.style.display = kind == DisplayType.Text ? DisplayStyle.Flex : DisplayStyle.None;
                    if (searchableContainer != null)
                    {
                        bool showSearchable = kind == DisplayType.DropDown && DropdownSearchableApplies();
                        searchableContainer.style.display = showSearchable ? DisplayStyle.Flex : DisplayStyle.None;
                    }
                    if (polymorphicSearchableContainer != null)
                    {
                        polymorphicSearchableContainer.style.display =
                            kind == DisplayType.SerializeReference ? DisplayStyle.Flex : DisplayStyle.None;
                    }
                    dropDownContainer.style.display = kind == DisplayType.DropDown ? DisplayStyle.Flex : DisplayStyle.None;
                    dropdownMenuStyleContainer.style.display = (kind == DisplayType.DropDown || kind == DisplayType.SerializeReference) ? DisplayStyle.Flex : DisplayStyle.None;
                    // AssetPreview implies the preview: force-show the settings.
                    bool isAssetPrev = kind == DisplayType.AssetPreview;
                    previewSettingsContainer.style.display = isAssetPrev ? DisplayStyle.Flex : DisplayStyle.None;
                    audioPreviewContainer.style.display = kind == DisplayType.AudioPreview ? DisplayStyle.Flex : DisplayStyle.None;
                    particlePreviewContainer.style.display = kind == DisplayType.ParticleSystemPreview ? DisplayStyle.Flex : DisplayStyle.None;
                    curveContainer.style.display = kind == DisplayType.AnimationCurveEditor ? DisplayStyle.Flex : DisplayStyle.None;
                    gradientContainer.style.display = kind == DisplayType.Gradient ? DisplayStyle.Flex : DisplayStyle.None;
                    enumBadgeContainer.style.display = kind == DisplayType.EnumBadgeGrid ? DisplayStyle.Flex : DisplayStyle.None;
                    ratingContainer.style.display = kind == DisplayType.Rating ? DisplayStyle.Flex : DisplayStyle.None;
                    xyPadContainer.style.display = kind == DisplayType.XYPad ? DisplayStyle.Flex : DisplayStyle.None;
                    vectorSlidersContainer.style.display = kind == DisplayType.VectorSliders ? DisplayStyle.Flex : DisplayStyle.None;
#if SASQ_CUSTOM_WIDGET
                    customWidgetContainer.style.display = kind == DisplayType.CustomWidget ? DisplayStyle.Flex : DisplayStyle.None;
#endif
                    textRichContainer.style.display = kind == DisplayType.Text ? DisplayStyle.Flex : DisplayStyle.None;
                    minimizableContainer.style.display = kind == DisplayType.InlineEditor ? DisplayStyle.Flex : DisplayStyle.None;
                    stepperContainer.style.display =
                        (kind == DisplayType.Default && stepperApplies) ? DisplayStyle.Flex : DisplayStyle.None;
                    axisPipsContainer.style.display =
                        AxisPips.AppliesTo(kind, axisPipsFieldType) ? DisplayStyle.Flex : DisplayStyle.None;
                    // Same predicate as the build above. Note this stays visible for a SerializedDictionary
                    // field whatever the user picks in Display Type, because the table is auto-routed for that
                    // shape - the rows are live there regardless of the kind.
                    dictionaryContainer.style.display =
                        DisplayTypeCatalog.ShowsDictionaryTable(kind, axisPipsFieldType)
                            ? DisplayStyle.Flex : DisplayStyle.None;
                    colorFieldContainer.style.display =
                        ((kind == DisplayType.Default || kind == DisplayType.ColorPalette) && colorOptionsApply)
                            ? DisplayStyle.Flex : DisplayStyle.None;
                    createAssetContainer.style.display =
                        (createAssetApplies &&
                         (kind == DisplayType.Default || kind == DisplayType.InlineEditor || kind == DisplayType.AssetPreview))
                            ? DisplayStyle.Flex : DisplayStyle.None;

                    updateDisplayStyleFoldoutVisibility();
                });
            }
            else if (_selectedNode is ContainerNode containerNode)
            {
                // NOTE: the container's scope field is NOT here at the top — it sits at the bottom of this
                // branch as "Scope (Advanced)". It's a power-user struct-rebasing field normally managed
                // automatically by the Tools, so it deliberately doesn't lead the panel.
                var kindField = new EnumField("Container Type", containerNode.Type);
                kindField.RegisterValueChangedCallback(evt =>
                {
                    var oldKind = containerNode.Type;
                    var newKind = (ContainerType)evt.newValue;
                    if (oldKind == newKind) return;

                    // The structural migration itself lives in ContainerTypeMigration (beside
                    // FrameShapeMigration) because THREE edit points change a container's type and the other
                    // two used to assign the enum raw. This one is the only one that can reasonably raise a
                    // modal, so it owns the single lossy decision — how to treat existing tab content when
                    // leaving Tabs — and hands the answer down.
                    var leaveTabs = LeaveTabsMode.KeepAsGroups;
                    if (ContainerTypeMigration.WouldRestructureTabs(containerNode, newKind, out int tabCount, out int contentCount))
                    {
                        int choice = EditorUtility.DisplayDialogComplex(
                            "Convert Tabs",
                            $"This Tabs container has {tabCount} tab(s) containing {contentCount} item(s).\n\n" +
                            $"How should they be handled when converting to {ObjectNames.NicifyVariableName(newKind.ToString())}?",
                            "Flatten items in",      // 0
                            "Cancel",                // 1
                            "Keep tabs as groups");  // 2
                        if (choice == 1) { kindField.SetValueWithoutNotify(oldKind); return; }
                        leaveTabs = choice == 0 ? LeaveTabsMode.Flatten : LeaveTabsMode.KeepAsGroups;
                    }

                    Undo.RecordObject(_clonedLayoutAsset, "Change Container Type");
                    ContainerTypeMigration.Apply(containerNode, newKind, leaveTabs);
                    OnModification();
                    // Defer the rebuild to next frame so the dropdown finishes closing first; rebuilding
                    // the properties panel mid-ChangeEvent intermittently drops the selection.
                    rootVisualElement.schedule.Execute(() =>
                    {
                        RefreshHierarchy();
                        RefreshProperties();
                        RefreshPreview();
                    }).ExecuteLater(1);
                });
                // Container Type is hidden in the Preset Editor — the one row here that DOES carry but must not
                // be offered: the kind is the preset's own identity (you picked "Card" in the WIDGETS list), and
                // ContainerTransfers copies Type, so re-typing it here would silently make every future Card
                // drop arrive as whatever kind was left in the row.
                if (!_presetMode) generalSection.Add(kindField);

                // Title is available on EVERY container type. Card/Foldout/Tabs render it as
                // their header; Rows/Columns/Grid render it as a header above their content.
                var titleRow = new VisualElement();
                titleRow.style.flexDirection = FlexDirection.Row;
                titleRow.style.alignItems = Align.Center;

                var titleField = new TextField("Title");
                titleField.value = containerNode.Title;
                titleField.tooltip = "Optional. Shown as a header above the container.";
                titleField.style.flexGrow = 1f;
                titleField.style.flexShrink = 1f;
                titleField.style.minWidth = 50;
                titleField.style.marginRight = 6;
                titleField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change Container Title", () => containerNode.Title = evt.newValue,
                        refreshHierarchy: true, liveRebuild: true));
                FlushTextEditOnBlur(titleField);
                titleRow.Add(titleField);

                // (The standalone |< >< >| title-alignment buttons that used to sit here — setting Style.justify
                // — were removed: the title's "T" panel already has an Align control, which now carries this same
                // button styling. Existing Style.justify overrides still render; new alignment is set via the T.)

                // The title TEXT is content (dropped on preset capture); TitleTextStyle is styling and travels.
                if (_presetMode)
                    generalSection.Add(BuildPresetTextStyleRow("Title",
                        "each container keeps its own title text",
                        () => containerNode.TitleTextStyle, v => containerNode.TitleTextStyle = v, "title"));
                else
                    generalSection.Add(Identity(WithTextButton(titleRow,
                        () => containerNode.TitleTextStyle, v => containerNode.TitleTextStyle = v, "title")));

                // Section Tint — color-code this section (tinted header + body wash + a full-color accent rail
                // down the left edge) so complex inspectors are easier to scan. Shown for EVERY container type,
                // Tabs included: the tint applies whenever it's set (LayoutTreeBuilder.ApplySectionTint keys off
                // SectionTintColor.isOverridden, not the type), so hiding the field for Tabs left a stale tint
                // that couldn't be edited or cleared. Tabs additionally get the "Active Tab Color" below (which
                // tints the selected tab button — a different thing). Unset by default.
                // EXCEPT Frames: the builder deliberately ignores tint/stripe there (the hard left rail would
                // corrupt a circle/pill ring), so the dead controls are hidden rather than shown doing nothing.
                if (containerNode.Type != ContainerType.Frame)
                {
                    generalSection.Add(CreateOverridableColorElement("Section Tint",
                        () => containerNode.SectionTintColor,
                        v => containerNode.SectionTintColor = v,
                        RefreshPreview));

                    // Accent Stripe — a full-color rail down the left edge ONLY (no header/body wash); the
                    // lighter-weight alternative to Section Tint. When both are set, Section Tint wins.
                    var accentStripeRow = CreateOverridableColorElement("Accent Stripe",
                        () => containerNode.AccentStripeColor,
                        v => containerNode.AccentStripeColor = v,
                        RefreshPreview,
                        liveApply: () => LivePokeCanvasElement(containerNode, el =>
                        {
                            var c = containerNode.AccentStripeColor.value; c.a = 1f; // rail is drawn opaque
                            el.style.borderLeftColor = c; el.style.borderLeftWidth = 3;
                        }));
                    accentStripeRow.tooltip = "A color rail down the section's left edge only (no tinted header/body). " +
                                              "If Section Tint is also set, Section Tint takes over.";
                    generalSection.Add(accentStripeRow);
                }

                if (containerNode.Type == ContainerType.Foldout)
                {
                    var expandedField = new Toggle("Default to Open");
                    expandedField.value = containerNode.DefaultToOpen;
                    expandedField.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Foldout Default to Open");
                        containerNode.DefaultToOpen = evt.newValue;
                        OnModification();
                        RefreshPreview();
                    });
                    generalSection.Add(expandedField);

                    // Toggle group: pick ONE bool field on the target and it becomes the group's header
                    // checkbox (no separate flag, no second field to wire). Empty = plain foldout.
                    // A group toggle NAMES A FIELD on one specific target type, so it's content: neither
                    // GroupTogglePath nor GroupToggleAlignment is in a carry list, and the Preset Editor hides
                    // the picker together with the Bool Alignment row it gates (the alignment alone would be a
                    // control for a checkbox that can never exist).
                    bool showGroupToggle = !_presetMode;

                    // A group toggle resolves against the container's OUTER scope — BuildToggleGroup binds
                    // `basePath + "." + GroupTogglePath`, and basePath there is the path this container was
                    // BUILT with, i.e. everything above it minus its own PropertyPath. GetEffectiveBasePath
                    // returns exactly that when asked for the container itself, so suggestions, the code peek
                    // and the warning hint all speak the same relative language the stored value does.
                    string ToggleBasePath() =>
                        GetEffectiveBasePath(containerNode, _clonedLayoutAsset?.Root, "") ?? "";

                    // Live (not captured): the target type can change under an open panel, exactly as the
                    // Property Path and Method Name providers assume.
                    IEnumerable<string> BoolPathSuggestions()
                    {
                        var t = ResolveTargetType();
                        if (t == null) return Array.Empty<string>();
                        var all = SasquatchReflectionUtility.GetSerializableProperties(t);
                        var bools = all.Where(p => p.type == typeof(bool));

                        string basePath = ToggleBasePath();
                        if (!string.IsNullOrEmpty(basePath))
                        {
                            string prefix = basePath + ".";
                            return bools.Where(p => p.path.StartsWith(prefix, StringComparison.Ordinal))
                                        .Select(p => p.path.Substring(prefix.Length))
                                        .ToList();
                        }
                        // A bool that lives on a collection's ELEMENT type needs an index to bind, so it can
                        // never be a header checkbox here — same exclusion the Property Path list makes.
                        var collPrefixes = all.Where(p => p.isCollection).Select(p => p.path + ".").ToList();
                        return bools.Where(p => !collPrefixes.Any(cp => p.path.StartsWith(cp, StringComparison.Ordinal)))
                                    .Select(p => p.path)
                                    .ToList();
                    }

                    // Bool-alignment buttons (same |< >< >| style as the Rows/Columns/Grid title alignment).
                    // Created up front so the toggle-property callback can show/hide the whole row.
                    var alignContainer = new VisualElement();
                    var alignRow = new VisualElement();
                    alignRow.style.flexDirection = FlexDirection.Row;
                    alignRow.style.alignItems = Align.Center;
                    alignRow.style.marginTop = 2;

                    var alignLabel = new Label("Bool Alignment");
                    alignLabel.tooltip = "Where the header checkbox + name sit within the group bar.";
                    alignLabel.style.flexGrow = 1f;
                    alignRow.Add(alignLabel);

                    var alignBtnGroup = new VisualElement();
                    alignBtnGroup.style.flexDirection = FlexDirection.Row;
                    alignBtnGroup.style.alignItems = Align.Center;
                    alignBtnGroup.style.flexShrink = 0f;

                    var boolAligns = new[]
                    {
                        (icon: SasquatchIcons.Ids.AlignStartVertical, value: GroupToggleAlignment.Left, tooltip: "Align bool left"),
                        (icon: SasquatchIcons.Ids.AlignCenterVertical, value: GroupToggleAlignment.Center, tooltip: "Align bool center"),
                        (icon: SasquatchIcons.Ids.AlignEndVertical, value: GroupToggleAlignment.Right, tooltip: "Align bool right")
                    };

                    foreach (var a in boolAligns)
                    {
                        var btn = new Button();
                        bool active = containerNode.GroupToggleAlignment == a.value;
                        btn.Add(SasquatchIcons.Create(a.icon, 13, active ? Color.white : DesignerPalette.IconIdle));
                        btn.tooltip = a.tooltip;
                        btn.style.width = 24;
                        btn.style.height = 18;
                        btn.style.paddingLeft = 0;
                        btn.style.paddingRight = 0;
                        btn.style.marginLeft = 2;
                        btn.style.marginRight = 0;
                        btn.style.alignItems = Align.Center;
                        btn.style.justifyContent = Justify.Center;

                        btn.style.backgroundColor = active
                            ? DesignerPalette.AccentFillSoft
                            : DesignerPalette.ButtonNeutralBg;
                        AddSegmentedHover(btn, () => containerNode.GroupToggleAlignment == a.value);

                        btn.clicked += () =>
                        {
                            Undo.RecordObject(_clonedLayoutAsset, "Change Group Toggle Alignment");
                            containerNode.GroupToggleAlignment = a.value;
                            OnModification();
                            RefreshProperties(); // re-render so the active-button highlight moves
                            RefreshPreview();
                        };
                        alignBtnGroup.Add(btn);
                    }
                    alignRow.Add(alignBtnGroup);
                    alignContainer.Add(alignRow);

                    void ApplyTogglePath(string path)
                    {
                        containerNode.GroupTogglePath = string.IsNullOrEmpty(path) ? "" : path;
                        // Keep the legacy flag in sync so older readers still see a consistent state.
                        containerNode.HasGroupToggle = !string.IsNullOrEmpty(containerNode.GroupTogglePath);
                        alignContainer.style.display = string.IsNullOrEmpty(containerNode.GroupTogglePath)
                            ? DisplayStyle.None : DisplayStyle.Flex;
                        // A bool path turns this Foldout into a toggle GROUP — the opaque .sasq-group shell,
                        // which swallows Appearance ▸ Background Color. Clearing it hands the row back.
                        syncGroupShellGatedRows?.Invoke();
                    }

                    // ONE control for every case, built like the other path fields (Property Path, Scope,
                    // Collection Path) and the Button's Method Name: type-to-filter suggestions, a hover code
                    // peek showing the bool's declaration + attributes, and a placeholder that says what an
                    // EMPTY value means. It replaced a DropdownField, which could only ever show a flat
                    // unsearchable list, had no peek, and refused any path its enumeration missed — while the
                    // autocomplete twin below it (built for the unresolvable-type case) already had all three.
                    var togglePathField = new TextField("Toggle Property");
                    togglePathField.value = containerNode.GroupTogglePath ?? "";
                    togglePathField.tooltip = "Pick a bool field on the target script: it becomes this group's header " +
                                              "checkbox, and the contents grey out when it's off. Empty = plain foldout.";
                    PlaceholderText.Attach(togglePathField, "none — plain foldout");

                    // Same affordance as the Button's Method Name hint, for the same reason: a path that was
                    // renamed, deleted or retyped in code otherwise shows up only as a checkbox that silently
                    // stops rendering (BuildToggleGroup hides an unbindable toggle in the live inspector).
                    var togglePathHint = new Label();
                    togglePathHint.style.fontSize = 10;
                    togglePathHint.style.opacity = 0.7f;
                    togglePathHint.style.whiteSpace = WhiteSpace.Normal;
                    togglePathHint.style.marginTop = 1;
                    togglePathHint.style.marginBottom = 3;
                    togglePathHint.style.color = DesignerPalette.ToastWarning;
                    togglePathHint.style.display = DisplayStyle.None;

                    void SyncTogglePathHint()
                    {
                        string path = togglePathField.value;
                        var t = ResolveTargetType();
                        // Mid-compile the type is a stale snapshot, so a path that IS about to resolve would
                        // read as broken — say nothing rather than cry wolf.
                        if (string.IsNullOrEmpty(path) || t == null || EditorApplication.isCompiling)
                        {
                            togglePathHint.style.display = DisplayStyle.None;
                            return;
                        }

                        string basePath = ToggleBasePath();
                        string full = string.IsNullOrEmpty(basePath) ? path : basePath + "." + path;
                        // Checked against the SAME enumeration the suggestions come from, so the list and the
                        // warning can never disagree about what counts as bindable.
                        var match = SasquatchReflectionUtility.GetSerializableProperties(t)
                            .FirstOrDefault(p => p.path == full);
                        if (match.type == typeof(bool))
                        {
                            togglePathHint.style.display = DisplayStyle.None;
                            return;
                        }

                        togglePathHint.text = match.type != null
                            ? $"'{path}' is a {FriendlyTypeName(match.type)} — a header checkbox needs a bool."
                            : $"'{path}' isn't a serialized bool on {t.Name} — renamed or removed? Pick one from the list.";
                        togglePathHint.style.display = DisplayStyle.Flex;
                    }

                    // Picking a bool that is ALSO a field inside this group is the normal way in — import every
                    // field, wrap them, then promote one — and it leaves two controls for one value. The group's
                    // copy wins and the field stops rendering (GroupToggleMirror); the canvas dims it and pips it,
                    // and this says why at the control that caused it. A NOTE, not a warning: nothing is broken,
                    // and clearing the path hands the field straight back.
                    var toggleMirrorNote = new Label();
                    toggleMirrorNote.style.fontSize = 10;
                    toggleMirrorNote.style.opacity = 0.7f;
                    toggleMirrorNote.style.whiteSpace = WhiteSpace.Normal;
                    toggleMirrorNote.style.marginTop = 1;
                    toggleMirrorNote.style.marginBottom = 3;
                    toggleMirrorNote.style.color = DesignerPalette.TextMuted;
                    toggleMirrorNote.style.display = DisplayStyle.None;

                    void SyncToggleMirrorNote()
                    {
                        // Asked against the TYPED value, not the node: the model write is debounced, so reading
                        // containerNode.GroupTogglePath here would answer for the previous keystroke.
                        string path = togglePathField.value;
                        bool shadows = GroupToggleMirror.HasExplicitMirror(containerNode, path);
                        toggleMirrorNote.style.display = shadows ? DisplayStyle.Flex : DisplayStyle.None;
                        if (shadows)
                            toggleMirrorNote.text = $"'{path}' is also a field in this group — the header checkbox " +
                                                    "edits it, so that field is hidden in the Inspector until you clear this.";
                    }

                    togglePathField.RegisterValueChangedCallback(evt =>
                    {
                        // refreshTokens: the Bindings palette counts a group-toggle bool as USED (GatherBoundPaths'
                        // derived set), so the token bank goes stale on this edit exactly as it would on a
                        // Property Path edit. The old dropdown never refreshed it.
                        HandleDebouncedTextEdit("Change Group Toggle Property",
                            () => ApplyTogglePath(evt.newValue), refreshTokens: true);
                        SyncTogglePathHint(); // cheap live feedback — stays per-keystroke, as the method hint does
                        SyncToggleMirrorNote();
                    });
                    FlushTextEditOnBlur(togglePathField);
                    AutocompleteTextField.Attach(togglePathField, BoolPathSuggestions,
                        s => FieldPathSnippet(s.Value, ToggleBasePath()));

                    if (showGroupToggle)
                    {
                        // Identity: a group toggle NAMES a field on one target type. The dropdown was never
                        // tagged, so multi-edit showed a control that MultiEditMirror.IdentityFields then
                        // refused to fan out — visible, and dead.
                        generalSection.Add(Identity(togglePathField));
                        generalSection.Add(Identity(togglePathHint));
                        generalSection.Add(Identity(toggleMirrorNote));
                        SyncTogglePathHint();
                        SyncToggleMirrorNote();
                    }

                    alignContainer.style.display = string.IsNullOrEmpty(containerNode.GroupTogglePath)
                        ? DisplayStyle.None : DisplayStyle.Flex;
                    if (showGroupToggle) generalSection.Add(alignContainer);
                }

                // Tabs: recolor the active tab's header. Alpha 0 (old layouts) reads as the built-in blue, so
                // the field shows the effective color and we keep a visible alpha when the user picks one.
                if (containerNode.Type == ContainerType.Tabs)
                {
                    var defaultAccent = WidgetPalette.TabSelectedFallback; // what the Tabs widget renders when unset

                    // Field + ↺ reset row, mirroring the Section Tint / Accent Stripe overridable colors: the reset
                    // appears only when a custom color is set and restores the built-in blue ("unset" is alpha 0,
                    // which the Tabs widget reads as the fallback).
                    var accentRow = new VisualElement();
                    accentRow.style.flexDirection = FlexDirection.Row;
                    accentRow.style.alignItems = Align.Center;
                    accentRow.style.marginBottom = 4;

                    var accentField = new ColorField("Active Tab Color");
                    accentField.style.flexGrow = 1;
                    accentField.value = containerNode.TabAccentColor.a > 0f ? containerNode.TabAccentColor : defaultAccent;
                    accentField.tooltip = "Header tint for the selected tab. The other tabs stay neutral grey.";

                    var accentReset = MakeStyleResetButton();
                    void SyncAccentReset() => ApplyOverrideChrome(accentField, accentReset, containerNode.TabAccentColor.a > 0f);

                    accentField.RegisterValueChangedCallback(evt =>
                    {
                        HandleDebouncedValueEdit("Change Active Tab Color", () =>
                        {
                            var c = evt.newValue;
                            if (c.a <= 0f) c.a = 0.8f; // never let alpha 0 round-trip to "unset" (= default)
                            containerNode.TabAccentColor = c;
                            SyncAccentReset();
                        }, liveRebuild: true);
                    });
                    FlushValueEditOnBlur(accentField);

                    void ResetAccent()
                    {
                        CommitPendingValueEdit(); // close any open picker-drag burst before this discrete reset's record
                        Undo.RecordObject(_clonedLayoutAsset, "Reset Active Tab Color");
                        containerNode.TabAccentColor = default;            // alpha 0 = unset → the built-in blue
                        accentField.SetValueWithoutNotify(defaultAccent);
                        OnModification();
                        RefreshPreview();
                        SyncAccentReset();
                    }
                    accentReset.clicked += ResetAccent;
                    AddStyleResetContextMenu(accentRow, () => containerNode.TabAccentColor.a > 0f, ResetAccent);

                    accentRow.Add(accentField);
                    accentRow.Add(accentReset);
                    SyncAccentReset();
                    generalSection.Add(accentRow);

                    // The kanban organizer — built here, added below General Settings (see stash above).
                    // Not in the Preset Editor: it authors the container's CHILDREN (tabs and their contents),
                    // and a preset never carries structure — ContainerTransfers has no Children/TabLabel entry,
                    // so any tab arranged here would vanish on capture.
                    // The organizer moves THIS container's items between THIS container's tabs — a per-node
                    // structural tool, so it is identity and stands down for a multi-selection.
                    if (!_presetMode) tabOrganizerSection = Identity(BuildTabOrganizer(containerNode));
                }

                // Frame: shape + size/alignment + fill + overlay (+ split) controls. Shape changes crossing
                // the split/non-split boundary restructure children via FrameShapeMigration, mirroring the
                // Tabs conversion flow above. Shape changes rebuild this whole panel (deferred, the
                // kindField precedent), so per-shape rows are added conditionally; the Fill Source rows
                // switch via show/hide instead (a rebuild would re-derive "None" — see the Fill section).
                if (containerNode.Type == ContainerType.Frame)
                {
                    var frame = containerNode.Frame;

                    var shapeField = new EnumField("Frame Shape", frame.Shape);
                    shapeField.tooltip = "The clip shape — everything inside the frame is clipped to it. " +
                                         "Diagonal Split turns the frame into two panes divided by a tilted seam.";
                    shapeField.RegisterValueChangedCallback(evt =>
                    {
                        var oldShape = frame.Shape;
                        var newShape = (FrameShape)evt.newValue;
                        if (oldShape == newShape) return;

                        bool wasSplit = oldShape == FrameShape.DiagonalSplit;
                        bool isSplit = newShape == FrameShape.DiagonalSplit;

                        // ENTERING split with children that already have a pane pair's shape (exactly two
                        // containers). That shape is genuinely ambiguous: it is what a "keep panes as groups"
                        // exit leaves behind — those must come home as the panes, or the round trip buries
                        // both inside a new Pane A — but it is equally what two Cards the user authored look
                        // like, and adopting THOSE silently turns two ordinary groups into structural panes,
                        // which can no longer be moved, are only emptied by Delete, and are destroyed by
                        // "Flatten items in". Nothing in the model tells the two apart, so ask. This is the
                        // only edit point that can: every other caller (paste, multi-edit, a live quick-edit)
                        // takes the non-destructive AdoptExistingPanes default. Asked BEFORE the shape is
                        // written, because the query reads the CURRENT shape to know we are entering.
                        var enterSplit = EnterSplitMode.AdoptExistingPanes;
                        if (!wasSplit && isSplit
                            && FrameShapeMigration.WouldAdoptExistingPanes(containerNode, out int adoptCount))
                        {
                            int adoptChoice = EditorUtility.DisplayDialogComplex(
                                "Split This Frame",
                                $"This frame already holds two groups ({adoptCount} item(s) inside them).\n\n" +
                                "A Diagonal Split frame's two children ARE its panes, so those groups can " +
                                "become Pane A and Pane B — but panes are structural: after this they " +
                                "cannot be moved or deleted on their own.\n\n" +
                                "Or keep them as ordinary groups, both placed inside a new Pane A.",
                                "Use as the panes",         // 0
                                "Cancel",                   // 1
                                "Keep groups, use Pane A"); // 2
                            if (adoptChoice == 1) { shapeField.SetValueWithoutNotify(oldShape); return; }
                            if (adoptChoice == 2) enterSplit = EnterSplitMode.WrapIntoPaneA;
                        }

                        // Leaving split with real pane content: ask, like the Tabs conversion above.
                        bool keepPanesAsGroups = false;
                        if (wasSplit && !isSplit && FrameShapeMigration.CountPaneContent(containerNode) > 0)
                        {
                            int choice = EditorUtility.DisplayDialogComplex(
                                "Convert Split Frame",
                                $"This split frame's panes contain {FrameShapeMigration.CountPaneContent(containerNode)} item(s).\n\n" +
                                "How should they be handled when leaving Diagonal Split?",
                                "Flatten items in",       // 0
                                "Cancel",                 // 1
                                "Keep panes as groups");  // 2
                            if (choice == 1) { shapeField.SetValueWithoutNotify(oldShape); return; }
                            keepPanesAsGroups = choice == 2;
                        }

                        Undo.RecordObject(_clonedLayoutAsset, "Change Frame Shape");
                        if (!wasSplit && isSplit) FrameShapeMigration.ToSplit(containerNode, enterSplit);
                        else if (wasSplit && !isSplit) FrameShapeMigration.FromSplit(containerNode, keepPanesAsGroups);
                        frame.Shape = newShape;

                        // A split must never START invisible: layouts saved before seams had visible
                        // defaults carry width 0 + unset color — entering split with BOTH untouched
                        // seeds the default seam. A deliberately styled (or deliberately cleared-and-
                        // colored) seam is left alone.
                        if (!wasSplit && isSplit && frame.SeamWidth <= 0f && !frame.SeamColor.isOverridden)
                        {
                            frame.SeamWidth = FrameSettings.DefaultSeamWidth;
                            frame.SeamColor = new OverridableColor { isOverridden = true, value = FrameSettings.DefaultSeamColor };
                        }

                        // The fan-out to the rest of a multi-selection happens inside OnModification, which
                        // cannot prompt per node — so hand it the answer the user just gave, once.
                        MirrorNextEnterSplit(enterSplit);

                        OnModification();
                        rootVisualElement.schedule.Execute(() =>
                        {
                            RefreshHierarchy();
                            RefreshProperties();
                            RefreshPreview();
                        }).ExecuteLater(1);
                    });
                    generalSection.Add(shapeField);

                    // ---- Size & placement ----
                    // Width/height ride the shared Style so grips, StyleApplier and presets all agree.
                    bool aspectLocked = frame.Shape == FrameShape.Circle
                        || ((frame.Shape == FrameShape.RoundedRect || frame.Shape == FrameShape.Pill) && frame.LockAspect);

                    // These setters MUST mark the designer as the resize authority: SaveActiveAsset's
                    // MergeResizeFields copies Style.width/height from the REGISTERED layout back onto
                    // the clone (preserving live-inspector resizes) unless _designerResizedSinceClone is
                    // set — without it, panel-edited frame sizes silently revert on Save (the canvas drag
                    // grips already set it via onLayoutEdited: OnLayoutResizedFromPreview).
                    var widthRow = CreateOverridableFloatElement("Width",
                        () => containerNode.Style.width,
                        v => { var s = containerNode.Style; s.width = v; containerNode.Style = s; ClaimResizeAuthority(); },
                        RefreshPreview, liveApply: () => StyleLivePoke(containerNode));
                    widthRow.tooltip = "Fixed width in pixels. Unset (↺) = stretch to the full row.";
                    generalSection.Add(widthRow);

                    var heightRow = CreateOverridableFloatElement("Height",
                        () => containerNode.Style.height,
                        v => { var s = containerNode.Style; s.height = v; containerNode.Style = s; ClaimResizeAuthority(); },
                        RefreshPreview, liveApply: () => StyleLivePoke(containerNode));
                    heightRow.tooltip = "Grow-only minimum height in pixels. Unset (↺) = fit the content.";
                    heightRow.style.display = aspectLocked ? DisplayStyle.None : DisplayStyle.Flex;
                    generalSection.Add(heightRow);

                    // Left/Center/Right placement of a fixed-width frame within its row (the shared
                    // |< >< >| buttons). Maps onto Style.alignSelf; no effect while Width is unset.
                    generalSection.Add(BuildImageAlignmentRow("Alignment",
                        () =>
                        {
                            if (!containerNode.Style.alignSelf.isOverridden) return ImageAlignment.Left;
                            var a = containerNode.Style.alignSelf.value;
                            return a == Align.Center ? ImageAlignment.Center
                                 : a == Align.FlexEnd ? ImageAlignment.Right
                                 : ImageAlignment.Left;
                        },
                        v =>
                        {
                            var s = containerNode.Style;
                            s.alignSelf = new OverridableEnum<Align>
                            {
                                isOverridden = true,
                                value = v == ImageAlignment.Center ? Align.Center
                                      : v == ImageAlignment.Right ? Align.FlexEnd
                                      : Align.FlexStart
                            };
                            containerNode.Style = s;
                        },
                        "Change Frame Alignment"));

                    // Aspect lock (Circle is implicitly 1:1, so its rows are hidden). Toggling the lock
                    // also swaps the Height row in/out — a locked frame derives height from width.
                    if (frame.Shape == FrameShape.RoundedRect || frame.Shape == FrameShape.Pill)
                    {
                        var ratioField = new FloatField("Aspect Ratio (W:H)");
                        ratioField.value = frame.AspectRatio;
                        ratioField.tooltip = "Width divided by height — 1 is square, 1.78 is 16:9.";
                        ratioField.style.display = frame.LockAspect ? DisplayStyle.Flex : DisplayStyle.None;
                        ratioField.RegisterValueChangedCallback(evt =>
                        {
                            HandleDebouncedValueEdit("Change Frame Aspect Ratio", () =>
                            {
                                frame.AspectRatio = evt.newValue;                    // setter clamps
                            }, liveRebuild: true);
                        });
                        FlushValueEditOnBlur(ratioField);
                        SyncClampedDisplay(ratioField, () => frame.AspectRatio);      // show the clamp, not mid-keystroke

                        var lockField = new Toggle("Lock Aspect Ratio");
                        lockField.value = frame.LockAspect;
                        lockField.tooltip = "Derive the frame's height from its width so the shape keeps its proportions.";
                        lockField.RegisterValueChangedCallback(evt =>
                        {
                            Undo.RecordObject(_clonedLayoutAsset, "Change Frame Lock Aspect");
                            frame.LockAspect = evt.newValue;
                            ratioField.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                            heightRow.style.display = evt.newValue ? DisplayStyle.None : DisplayStyle.Flex;
                            OnModification();
                            RefreshPreview();
                        });
                        generalSection.Add(lockField);
                        generalSection.Add(ratioField);
                    }

                    // ---- Fill ----
                    // ONE fill source at a time (never both pickers): a static Image asset, or a
                    // Texture2D/Sprite Field on the target (each object shows its own image). The source
                    // is derived from data only when this panel BUILDS; after that the dropdown's live
                    // value drives which picker row shows (show/hide, the overlaySub pattern). Switching
                    // must NOT rebuild the panel: right after a switch BOTH paths are still empty, so a
                    // rebuild would re-derive "None" and snap the dropdown straight back.
                    const string srcNone = "None", srcImage = "Image", srcField = "Field";
                    string currentSource = !string.IsNullOrEmpty(frame.FillBindingPath) ? srcField
                                         : !string.IsNullOrEmpty(frame.FillTextureGuid) ? srcImage
                                         : srcNone;
                    var sourceField = new DropdownField("Fill Source",
                        new List<string> { srcNone, srcImage, srcField }, currentSource);
                    sourceField.tooltip = "What fills the frame behind its content: nothing (background color only), " +
                                          "a fixed Image asset, or a Texture/Sprite Field on the target so each object " +
                                          "shows its own picture (e.g. a character's portrait).";

                    var fillTexField = new ObjectField("Image") { objectType = typeof(Texture2D), allowSceneObjects = false };
                    fillTexField.tooltip = "The fill texture (same image for every object of this type). " +
                                           "Stored by GUID so it survives asset moves/renames.";
                    if (!string.IsNullOrEmpty(frame.FillTextureGuid))
                    {
                        var p = AssetDatabase.GUIDToAssetPath(frame.FillTextureGuid);
                        if (!string.IsNullOrEmpty(p)) fillTexField.SetValueWithoutNotify(AssetDatabase.LoadAssetAtPath<Texture2D>(p));
                    }
                    fillTexField.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Frame Fill Image");
                        string guid = "";
                        if (evt.newValue != null)
                        {
                            var p = AssetDatabase.GetAssetPath(evt.newValue);
                            if (!string.IsNullOrEmpty(p)) guid = AssetDatabase.AssetPathToGUID(p);
                        }
                        frame.FillTextureGuid = guid;
                        OnModification();
                        RefreshPreview();
                    });

                    const string frameFillNone = "(None)";
                    var frameTexPaths = new List<string>();
                    var frameTargetType = ResolveTargetType();
                    if (frameTargetType != null)
                    {
                        frameTexPaths = SasquatchReflectionUtility.GetSerializableProperties(frameTargetType)
                            .Where(p => p.type == typeof(Texture2D) || p.type == typeof(Sprite))
                            .Select(p => p.path)
                            .ToList();
                    }
                    var bindChoices = new List<string> { frameFillNone };
                    bindChoices.AddRange(frameTexPaths);
                    string currentBind = string.IsNullOrEmpty(frame.FillBindingPath) ? frameFillNone : frame.FillBindingPath;
                    if (!bindChoices.Contains(currentBind)) bindChoices.Add(currentBind); // keep a stale path visible
                    var bindField = new DropdownField("Field") { choices = bindChoices, value = currentBind };
                    bindField.tooltip = "A Texture2D or Sprite field on the target script: each object fills the " +
                                        "frame with its OWN image, live-updating when the field changes.";
                    bindField.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Frame Fill Binding");
                        frame.FillBindingPath = evt.newValue == frameFillNone ? "" : evt.newValue;
                        OnModification();
                        RefreshPreview();
                    });

                    // Fit/zoom/focus rows shared by both sources (hidden while the source is None).
                    var fillCommonSub = new VisualElement();
                    {
                        // Fit / Stretch only — the ImageBanner precedent ("Scale & Crop" doesn't earn its
                        // place; Stretch + Zoom + Focus cover the crop use case). Legacy Scale-&-Crop data
                        // still renders; it shows as Stretch here and becomes Stretch when touched.
                        var scaleChoices = new List<string> { "Fit", "Stretch" };
                        string scaleInitial = frame.FillScaleMode == ImageBannerScaleMode.ScaleToFit ? "Fit" : "Stretch";
                        var fillModeField = new DropdownField("Scale Mode", scaleChoices, scaleInitial);
                        fillModeField.tooltip = "Fit = preserve the image's aspect (may letterbox); Stretch = fill the frame exactly.";
                        fillModeField.RegisterValueChangedCallback(evt =>
                        {
                            Undo.RecordObject(_clonedLayoutAsset, "Change Frame Fill Scale Mode");
                            frame.FillScaleMode = evt.newValue == "Fit"
                                ? ImageBannerScaleMode.ScaleToFit
                                : ImageBannerScaleMode.StretchToFill;
                            OnModification();
                            RefreshPreview();
                        });
                        fillCommonSub.Add(fillModeField);

                        var fillZoomField = new Slider("Zoom", FrameSettings.MinZoom, FrameSettings.MaxZoom)
                        {
                            value = frame.FillZoom,
                            showInputField = true
                        };
                        fillZoomField.tooltip = "Enlarges the fill image inside the frame; the shape crops the overflow.";
                        fillZoomField.RegisterValueChangedCallback(evt =>
                        {
                            HandleDebouncedValueEdit("Change Frame Fill Zoom", () =>
                            {
                                frame.FillZoom = evt.newValue;
                                // Zoom lives in the fill's background-size (computed by the frame's
                                // geometry refresh), not a transform — a scale would drag the fill's
                                // antialiased rounded corners out under the jagged stencil clip.
                                StyleLivePoke(_selectedNode);
                            });
                        });
                        FlushValueEditOnBlur(fillZoomField);
                        fillCommonSub.Add(fillZoomField);

                        var focusXField = new Slider("Focus X", 0f, 1f) { value = frame.FillFocus.x, showInputField = true };
                        focusXField.tooltip = "With Zoom above 1: which part of the image stays visible horizontally (0 = left edge, 1 = right edge).";
                        focusXField.RegisterValueChangedCallback(evt =>
                        {
                            HandleDebouncedValueEdit("Change Frame Fill Focus", () =>
                            {
                                frame.FillFocus = new Vector2(evt.newValue, frame.FillFocus.y);
                                StyleLivePoke(_selectedNode); // background-position pan, cheaper than a node rebuild
                            });
                        });
                        FlushValueEditOnBlur(focusXField);
                        fillCommonSub.Add(focusXField);

                        var focusYField = new Slider("Focus Y", 0f, 1f) { value = frame.FillFocus.y, showInputField = true };
                        focusYField.tooltip = "With Zoom above 1: which part of the image stays visible vertically (0 = top edge, 1 = bottom edge).";
                        focusYField.RegisterValueChangedCallback(evt =>
                        {
                            HandleDebouncedValueEdit("Change Frame Fill Focus", () =>
                            {
                                frame.FillFocus = new Vector2(frame.FillFocus.x, evt.newValue);
                                StyleLivePoke(_selectedNode); // background-position pan, cheaper than a node rebuild
                            });
                        });
                        FlushValueEditOnBlur(focusYField);
                        fillCommonSub.Add(focusYField);
                    }

                    System.Action syncFillRows = () =>
                    {
                        string src = sourceField.value;
                        fillTexField.style.display = src == srcImage ? DisplayStyle.Flex : DisplayStyle.None;
                        bindField.style.display = src == srcField ? DisplayStyle.Flex : DisplayStyle.None;
                        fillCommonSub.style.display = src != srcNone ? DisplayStyle.Flex : DisplayStyle.None;
                    };
                    sourceField.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Frame Fill Source");
                        if (evt.newValue == srcNone) { frame.FillBindingPath = ""; frame.FillTextureGuid = ""; }
                        else if (evt.newValue == srcImage) { frame.FillBindingPath = ""; }
                        else { frame.FillTextureGuid = ""; }
                        // Mirror the cleared path(s) into the pickers so a hidden row can't show a stale value later.
                        if (string.IsNullOrEmpty(frame.FillTextureGuid)) fillTexField.SetValueWithoutNotify(null);
                        if (string.IsNullOrEmpty(frame.FillBindingPath)) bindField.SetValueWithoutNotify(frameFillNone);
                        OnModification();
                        syncFillRows();
                        RefreshPreview();
                    });

                    // The whole Fill block is content: an Image asset by GUID, or a Texture/Sprite FIELD on one
                    // specific target type. CloneFrame strips both on capture (the ImageBanner precedent), so the
                    // Preset Editor hides the source picker and its two pickers. Fit / Zoom / Focus ride along
                    // with them — they only ever show once a source is chosen, and there is none here.
                    if (!_presetMode)
                    {
                        generalSection.Add(sourceField);
                        generalSection.Add(Identity(fillTexField));
                        generalSection.Add(Identity(bindField));
                        generalSection.Add(fillCommonSub);
                    }
                    syncFillRows();

                    // ---- Overlay (non-split): a GRADIENT wash between fill and content. The gradient's own
                    // colors + alpha replaced the old single-color picker and the Fade bool — a color fading
                    // to transparent is the classic edge scrim; any multi-stop ramp is now possible. Sub-rows
                    // follow the enable toggle.
                    if (frame.Shape != FrameShape.DiagonalSplit)
                    {
                        var overlaySub = new VisualElement();

                        var overlayToggle = new Toggle("Overlay") { value = frame.OverlayEnabled };
                        overlayToggle.tooltip = "A gradient wash painted between the fill image and the content — e.g. " +
                                                "darken the bottom edge so overlaid text stays readable. The gradient's " +
                                                "own colors and alpha define the wash (a color fading to transparent = " +
                                                "the classic edge scrim).";
                        overlayToggle.RegisterValueChangedCallback(evt =>
                        {
                            Undo.RecordObject(_clonedLayoutAsset, "Toggle Frame Overlay");
                            frame.OverlayEnabled = evt.newValue;
                            overlaySub.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                            OnModification();
                            RefreshPreview(); // add / remove the overlay layer
                        });
                        generalSection.Add(overlayToggle);

                        // The full gradient editor (presets, blend modes, draggable pins), bridged onto the
                        // frame's OverlayGradient via a scratch SO — the progress-fill precedent.
                        overlaySub.Add(BuildFrameOverlayGradientSection(containerNode));

                        var overlayEdgeField = new EnumField("Gradient Direction", frame.OverlayEdge);
                        overlayEdgeField.tooltip = "Which edge the gradient grows from — Bottom or Top — or Full to run " +
                                                   "the gradient across the whole frame (bottom to top).";
                        overlaySub.Add(overlayEdgeField);

                        var overlaySizeField = new Slider("Gradient Length %", FrameSettings.MinOverlayPercent, FrameSettings.MaxOverlayPercent)
                        {
                            value = frame.OverlaySizePercent,
                            showInputField = true
                        };
                        overlaySizeField.tooltip = "How far the gradient reaches from the edge, as a percentage of the frame's height.";
                        overlaySizeField.RegisterValueChangedCallback(evt =>
                        {
                            HandleDebouncedValueEdit("Change Frame Overlay Length", () =>
                            {
                                frame.OverlaySizePercent = evt.newValue;
                                // Coverage lives in the overlay's baked ramp (the element stays full-bleed for
                                // antialiased shape edges) — re-bake it in place.
                                LivePokeChild(_selectedNode, "sasq-frame-overlay", o => FrameBuilder.ApplyOverlayVisual(o, frame));
                            });
                        });
                        FlushValueEditOnBlur(overlaySizeField);
                        overlaySub.Add(overlaySizeField);

                        // Length only means something for an edge-hugging gradient — Full spans the whole
                        // frame, so the row would be a dead control there.
                        System.Action syncOverlayEdgeRows = () =>
                        {
                            bool fullEdge = frame.OverlayEdge == FrameOverlayEdge.Full;
                            overlaySizeField.style.display = fullEdge ? DisplayStyle.None : DisplayStyle.Flex;
                        };
                        overlayEdgeField.RegisterValueChangedCallback(evt =>
                        {
                            Undo.RecordObject(_clonedLayoutAsset, "Change Frame Overlay Direction");
                            frame.OverlayEdge = (FrameOverlayEdge)evt.newValue;
                            syncOverlayEdgeRows();
                            // Direction changes the ramp orientation — re-bake in place, no rebuild needed.
                            LivePokeChild(_selectedNode, "sasq-frame-overlay", o => FrameBuilder.ApplyOverlayVisual(o, frame));
                            OnModification();
                        });
                        syncOverlayEdgeRows();

                        overlaySub.style.display = frame.OverlayEnabled ? DisplayStyle.Flex : DisplayStyle.None;
                        generalSection.Add(overlaySub);
                    }

                    // Split seam controls (DiagonalSplit only — the panel rebuilds on shape change).
                    if (frame.Shape == FrameShape.DiagonalSplit)
                    {
                        var splitPosField = new Slider("Split Position", FrameSettings.MinSplitPos, FrameSettings.MaxSplitPos)
                        {
                            value = frame.SplitPosition,
                            showInputField = true
                        };
                        splitPosField.tooltip = "Where the seam's midpoint sits along the frame width (0.5 = centered).";
                        splitPosField.RegisterValueChangedCallback(evt =>
                        {
                            HandleDebouncedValueEdit("Change Frame Split Position", () => frame.SplitPosition = evt.newValue, liveRebuild: true);
                        });
                        FlushValueEditOnBlur(splitPosField);
                        generalSection.Add(splitPosField);

                        var splitAngleField = new Slider("Split Angle", -FrameSettings.MaxSplitAngle, FrameSettings.MaxSplitAngle)
                        {
                            value = frame.SplitAngle,
                            showInputField = true
                        };
                        splitAngleField.tooltip = "Seam tilt in degrees from vertical — flip the sign to flip between / and \\.";
                        splitAngleField.RegisterValueChangedCallback(evt =>
                        {
                            HandleDebouncedValueEdit("Change Frame Split Angle", () => frame.SplitAngle = evt.newValue, liveRebuild: true);
                        });
                        FlushValueEditOnBlur(splitAngleField);
                        generalSection.Add(splitAngleField);

                        var seamColorRow = CreateOverridableColorElement("Seam Color",
                            () => frame.SeamColor,
                            v => frame.SeamColor = v,
                            RefreshPreview);
                        seamColorRow.tooltip = "Optional line drawn along the seam (needs a Seam Width above 0).";
                        generalSection.Add(seamColorRow);

                        var seamWidthField = new FloatField("Seam Width");
                        seamWidthField.value = frame.SeamWidth;
                        seamWidthField.tooltip = "Seam line thickness in pixels; 0 = no drawn seam.";
                        seamWidthField.RegisterValueChangedCallback(evt =>
                        {
                            HandleDebouncedValueEdit("Change Frame Seam Width", () =>
                            {
                                frame.SeamWidth = evt.newValue;                        // setter clamps
                            }, liveRebuild: true);
                        });
                        FlushValueEditOnBlur(seamWidthField);
                        SyncClampedDisplay(seamWidthField, () => frame.SeamWidth);     // show the clamp, not mid-keystroke
                        generalSection.Add(seamWidthField);

                        // Per-pane image fills: painted under each pane's content, clipped at the seam
                        // (GUID round-trip, the shared Image-picker pattern).
                        System.Action<string, System.Func<string>, System.Action<string>> addPaneImageRow =
                            (label, getGuid, setGuid) =>
                        {
                            var paneTexField = new ObjectField(label) { objectType = typeof(Texture2D), allowSceneObjects = false };
                            paneTexField.tooltip = "Optional image painted behind this pane's content, clipped at the seam. " +
                                                   "A pane background color (on the pane itself) paints over it.";
                            if (!string.IsNullOrEmpty(getGuid()))
                            {
                                var p = AssetDatabase.GUIDToAssetPath(getGuid());
                                if (!string.IsNullOrEmpty(p)) paneTexField.SetValueWithoutNotify(AssetDatabase.LoadAssetAtPath<Texture2D>(p));
                            }
                            paneTexField.RegisterValueChangedCallback(evt =>
                            {
                                Undo.RecordObject(_clonedLayoutAsset, "Change Frame Pane Image");
                                string guid = "";
                                if (evt.newValue != null)
                                {
                                    var p = AssetDatabase.GetAssetPath(evt.newValue);
                                    if (!string.IsNullOrEmpty(p)) guid = AssetDatabase.AssetPathToGUID(p);
                                }
                                setGuid(guid);
                                OnModification();
                                RefreshPreview();
                            });
                            generalSection.Add(Identity(paneTexField));
                        };
                        // Both are texture assets — content, cleared by CloneFrame, hidden in the Preset Editor.
                        if (!_presetMode)
                        {
                            addPaneImageRow("Pane A Image", () => frame.PaneAFillGuid, v => frame.PaneAFillGuid = v);
                            addPaneImageRow("Pane B Image", () => frame.PaneBFillGuid, v => frame.PaneBFillGuid = v);
                        }
                    }
                }

                // Track count — how many columns (Columns) or row slots (Rows). In design mode this also drives
                // the visible empty drop-slots, so you can lay out an empty container first and drag fields in.
                // (Grid uses GridColumns too, but via its own Constraint block below.)
                if (containerNode.Type == ContainerType.Columns ||
                    containerNode.Type == ContainerType.Rows)
                {
                    string countLabel = containerNode.Type == ContainerType.Rows ? "Rows" : "Columns";
                    var colsField = new IntegerField(countLabel);
                    colsField.value = containerNode.GridColumns;
                    colsField.tooltip = containerNode.Type == ContainerType.Rows
                        ? "Track count: shows this many '+' drop slots and caps the rows — extra children wrap into a new column beside them. 0 = uncapped."
                        : "Track count: shows this many '+' drop slots and caps the columns — extra children wrap into a new row below. 0 = uncapped.";
                    colsField.RegisterValueChangedCallback(evt =>
                    {
                        HandleDebouncedValueEdit("Change Track Count", () => containerNode.GridColumns = Mathf.Max(0, evt.newValue), liveRebuild: true);
                    });
                    FlushValueEditOnBlur(colsField);
                    generalSection.Add(colsField);
                }

                // Grid: a Constraint (Flexible / Fixed Column Count / Fixed Row Count, like Unity's
                // GridLayoutGroup) + an axis-count field shown only for the fixed modes + independent
                // resize toggles for both axes (equal-width / auto-height by default).
                if (containerNode.Type == ContainerType.Grid)
                {
                    var constraintField = new EnumField("Constraint", containerNode.GridConstraint);
                    constraintField.tooltip = "Flexible: auto-fit columns by width. Fixed Column Count: you set the columns, rows flow. Fixed Row Count: you set the rows, columns flow.";
                    constraintField.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Grid Constraint");
                        containerNode.GridConstraint = (GridConstraint)evt.newValue;
                        OnModification();
                        // Deferred so the dropdown closes before we rebuild the panel (to show/hide the count).
                        rootVisualElement.schedule.Execute(() => { RefreshProperties(); RefreshPreview(); }).ExecuteLater(1);
                    });
                    generalSection.Add(constraintField);

                    if (containerNode.GridConstraint != GridConstraint.Flexible)
                    {
                        bool fixedRows = containerNode.GridConstraint == GridConstraint.FixedRowCount;
                        var countField = new IntegerField(fixedRows ? "Rows" : "Columns");
                        countField.value = containerNode.GridColumns;
                        countField.tooltip = fixedRows
                            ? "Number of rows — shown as reserved '+' tracks in design mode; columns flow to fit the items."
                            : "Number of columns — shown as reserved '+' cells in design mode; rows flow to fit the items.";
                        countField.RegisterValueChangedCallback(evt =>
                        {
                            HandleDebouncedValueEdit("Change Grid Count", () => containerNode.GridColumns = Mathf.Max(1, evt.newValue), liveRebuild: true);
                        });
                        FlushValueEditOnBlur(countField);
                        generalSection.Add(countField);
                    }

                    var colResizeToggle = new Toggle("Resizable Columns");
                    colResizeToggle.value = containerNode.GridResizableColumns;
                    colResizeToggle.tooltip = "Allow dragging vertical dividers to resize column widths (proportional). Off by default.";
                    colResizeToggle.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Toggle Grid Resizable Columns");
                        containerNode.GridResizableColumns = evt.newValue;
                        OnModification();
                        RefreshPreview();
                    });
                    generalSection.Add(colResizeToggle);

                    var rowResizeToggle = new Toggle("Resizable Rows");
                    rowResizeToggle.value = containerNode.GridResizableRows;
                    rowResizeToggle.tooltip = "Allow dragging horizontal dividers to resize row heights. Off by default.";
                    rowResizeToggle.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Toggle Grid Resizable Rows");
                        containerNode.GridResizableRows = evt.newValue;
                        OnModification();
                        RefreshPreview();
                    });
                    generalSection.Add(rowResizeToggle);
                }

                if (containerNode.Type == ContainerType.Columns || 
                    containerNode.Type == ContainerType.Rows || 
                    containerNode.Type == ContainerType.Grid)
                {
                    // Through the shared resettable-number row, so Spacing gets the same ↺ + right-click
                    // "Reset to default" affordance every other authored number carries. It shows only once
                    // the value differs from the default (0), and the dim chrome tells you at a glance
                    // whether this container's spacing was ever touched.
                    var gapField = new FloatField("Spacing");
                    gapField.tooltip = "Extra space between this container's children. 0 is the default.";
                    generalSection.Add(CreateResettableNumberField<float>(
                        gapField, 0f,
                        () => containerNode.Gap,
                        v => containerNode.Gap = v,
                        v => Mathf.Max(0f, v),
                        "Change Spacing"));
                }

                if (containerNode.Type == ContainerType.Columns)
                {
                    var alignField = CreateOverridableEnumElement<Align>(
                        "Vertical Alignment",
                        () => containerNode.Style.alignItems,
                        val => { var s = containerNode.Style; s.alignItems = val; containerNode.Style = s; },
                        RefreshPreview
                    );
                    alignField.tooltip = "Vertical alignment of the cells within a row: Stretch (uniform cell heights, default), FlexStart (Top), Center, FlexEnd (Bottom).";
                    generalSection.Add(alignField);
                }
                else if (containerNode.Type == ContainerType.Rows)
                {
                    var alignField = CreateOverridableEnumElement<Align>(
                        "Horizontal Alignment",
                        () => containerNode.Style.alignItems,
                        val => { var s = containerNode.Style; s.alignItems = val; containerNode.Style = s; },
                        RefreshPreview
                    );
                    alignField.tooltip = "Horizontal alignment of the stacked fields: Stretch (full width, default), FlexStart (Left), Center, FlexEnd (Right).";
                    generalSection.Add(alignField);
                }

                // Resizable toggle (Rows/Columns only): drag the dividers to resize tracks. Defaults ON for
                // containers you create, OFF for the root layout (so top-level fields aren't littered with
                // handles) — but it's toggleable either way. Backed by the tri-state TrackResizeMode: the
                // toggle shows the effective value and writes an explicit Enabled/Disabled on change.
                if (containerNode.Type == ContainerType.Columns || containerNode.Type == ContainerType.Rows)
                {
                    bool isRoot = _clonedLayoutAsset != null && containerNode == _clonedLayoutAsset.Root;
                    bool isRows = containerNode.Type == ContainerType.Rows;
                    var resizeToggle = new Toggle(isRows ? "Resizable Rows" : "Resizable Columns");
                    resizeToggle.value = LayoutTreeBuilder.TracksResizable(containerNode, isRoot);
                    resizeToggle.tooltip = isRows
                        ? "Show a drag handle under each row to set its height. Default: on for Rows you create, off for the root layout."
                        : "Show a drag handle between columns to resize their widths. Default: on for Columns you create, off for the root layout.";
                    resizeToggle.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Toggle Resizable");
                        containerNode.TrackResize = evt.newValue ? TrackResizeMode.Enabled : TrackResizeMode.Disabled;
                        OnModification();
                        RefreshPreview();
                    });
                    generalSection.Add(resizeToggle);
                }

                // Scope (Advanced) — the struct/class path-rebasing field: children of this container bind
                // RELATIVE to it. It's
                // normally created/managed automatically by the Tools (Group by [Header], dropping a struct
                // field), so hand-editing is a power-user action — kept out of the way down here.
                var scopeField = new TextField("Scope (Advanced)");
                scopeField.value = containerNode.PropertyPath;
                scopeField.style.marginTop = 8;
                scopeField.tooltip = "Advanced: a relative struct/class path. Children of this container bind relative to it — a container scoped to \"stats\" lets its children bind \"damage\" instead of \"stats.damage\". Usually set automatically when you group a nested struct; leave blank otherwise.";
                scopeField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change Container Path Scope", () => containerNode.PropertyPath = evt.newValue,
                        refreshHierarchy: true));
                FlushTextEditOnBlur(scopeField);
                AutocompleteTextField.Attach(scopeField, () =>
                {
                    var targetType = ResolveTargetType();
                    return targetType != null
                        ? SasquatchReflectionUtility.GetSerializableProperties(targetType).Select(p => p.path)
                        : Array.Empty<string>();
                }, s => FieldPathSnippet(s.Value));
                // A scope is a path into ONE target type's struct — identity, not styling (ContainerNode's
                // propertyPath is in no carry list). Hidden in the Preset Editor.
                if (!_presetMode) generalSection.Add(Identity(scopeField));

                // Expandable (opt-in, default OFF) for the eligible kinds — Rows/Columns/Grid/Card. Foldout has
                // its own Default to Open toggle above; Tabs and Frame are excluded. This is a build-time gate:
                // the panel is fully rebuilt when the Container Type dropdown changes, so no runtime display logic.
                bool canMinimize = containerNode.Type == ContainerType.Rows
                    || containerNode.Type == ContainerType.Columns
                    || containerNode.Type == ContainerType.Grid
                    || containerNode.Type == ContainerType.Card;
                if (canMinimize)
                {
                    var minimizableField = new Toggle("Expandable");
                    minimizableField.tooltip = "Allow collapsing/expanding this container by clicking its header.";
                    minimizableField.value = containerNode.Expandable;

                    var startExpandedField = new Toggle("Default to Open");
                    startExpandedField.tooltip = "If expandable, should this container open by default?";
                    startExpandedField.value = containerNode.DefaultToOpen;
                    startExpandedField.style.marginLeft = 15; // indent
                    startExpandedField.style.display = containerNode.Expandable ? DisplayStyle.Flex : DisplayStyle.None;

                    minimizableField.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Toggle Expandable Container");
                        containerNode.Expandable = evt.newValue;
                        startExpandedField.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                        // Expandable ON wraps this container in the opaque group shell, which swallows
                        // Background Color — re-derive the Appearance row rather than leave a dead control.
                        syncGroupShellGatedRows?.Invoke();
                        OnModification();
                        RefreshPreview();
                    });
                    generalSection.Add(minimizableField);

                    startExpandedField.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Container Default to Open");
                        containerNode.DefaultToOpen = evt.newValue;
                        OnModification();
                        RefreshPreview();
                    });
                    generalSection.Add(startExpandedField);
                }
            }
            else if (_selectedNode is CollectionNode collectionNode)
            {
                var pathField = new TextField("Property Path");
                pathField.value = collectionNode.PropertyPath;
                pathField.tooltip = "Path to the array or list property";
                pathField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change Collection Property Path", () => collectionNode.PropertyPath = evt.newValue,
                        refreshHierarchy: true, refreshTokens: true));
                FlushTextEditOnBlur(pathField);
                AutocompleteTextField.Attach(pathField, () =>
                {
                    var targetType = ResolveTargetType();
                    return targetType != null
                        ? SasquatchReflectionUtility.GetSerializableProperties(targetType).Where(p => p.isCollection).Select(p => p.path)
                        : Array.Empty<string>();
                }, s => FieldPathSnippet(s.Value));
                generalSection.Add(Identity(pathField));

                // Title — the collection's header text, plus the T button that styles it. The property's own
                // display name shows greyed as the default; type to rename the collection, clear it to hide the
                // title (the element count goes with it), and the reset arrow restores the default. Added below
                // Display Type (not here) so General Settings reads what → how → the header's own row:
                // Path, Display Type, then Title + Expandable.
                var collHeaderRow = WithTextButton(BuildOverridableField(
                    "Title",
                    collectionNode.TitleOverride,
                    OverridableTextRow.ResolveCollectionTitle(collectionNode),
                    "Change Collection Title",
                    v => collectionNode.TitleOverride = v,
                    refreshHierarchy: true,
                    fieldTooltip: "The collection's title row (its name + element count). Clear it to hide the title entirely.",
                    debounceText: true, liveRebuild: true),
                    () => collectionNode.HeaderTextStyle, v => collectionNode.HeaderTextStyle = v, "collheader");

                string CollectionModeInfo(CollectionDisplayMode m)
                {
                    if (m == CollectionDisplayMode.Table)
                        return "Table columns are the item-layout fields. Drag more fields from the Bindings panel (or use +T in the tree) to add columns; reorder or remove them in the layout tree.";
                    if (m == CollectionDisplayMode.Default)
                        return "Renders using Unity's standard PropertyField layout without custom styling.";
                    if (m == CollectionDisplayMode.CustomWidget)
                        return "Renders the WHOLE array as one Custom Widget (radial graph, bar cluster…). The array feeds the widget's primary list input; pick or create the widget asset below.";
                    if (m == CollectionDisplayMode.TagChips)
                        return "Renders this string collection as a wrapping row of removable chips with an inline “add” field — a compact multi-string editor.";
                    return "Configure a custom layout template for collection items using the +T button in the layout tree.";
                }

                var infoLabel = new Label(CollectionModeInfo(collectionNode.DisplayMode));

                var choices = new List<string> { "List" };
                if (IsGenericCollection(collectionNode.PropertyPath))
                {
                    choices.Add("Table");
                }
                choices.Add("Default");
                // Custom Widget renders the whole array as one widget — offered only for element types a widget's
                // primary list input can consume (bool → BoolList, float → FloatList).
                var cwElementType = ResolveCollectionElementType(collectionNode);
#if SASQ_CUSTOM_WIDGET
                bool cwSupported = cwElementType == typeof(bool) || cwElementType == typeof(float);
                if (cwSupported)
                {
                    choices.Add("Custom Widget");
                }
#endif
                // Tag Chips renders a string collection as removable chips + an inline add field — offered only
                // for string element types (string[] / List<string>).
                if (cwElementType == typeof(string))
                {
                    choices.Add("Tag Chips");
                }

                string initialChoice = ModeToChoice(collectionNode.DisplayMode);
                if (!choices.Contains(initialChoice))
                {
                    initialChoice = "List";
                    collectionNode.DisplayMode = CollectionDisplayMode.List;
                }

                var displayModeField = new DropdownField("Display Type", choices, initialChoice);
                displayModeField.tooltip = "How this array is drawn.\nList: stacked rows, each showing the full item layout.\nTable: one row per element, one column per item-layout field.\nDefault: standard Unity collection UI (no styling)."
#if SASQ_CUSTOM_WIDGET
                    + "\nCustom Widget: draw the whole array as one custom widget (offered for bool/float element lists)."
#endif
                    ;

#if SASQ_CUSTOM_WIDGET
                // ----- Custom Widget options (Display Type == Custom Widget) -----
                // The whole array feeds the widget's primary list input; non-primary inputs map to sibling
                // properties. Mirrors the field-level Custom Widget container (BindingNode) but on the collection.
                static string GetCollCwInputMap(CollectionNode n, string inputName)
                {
                    if (n.CustomWidgetInputs == null) return "";
                    foreach (var m in n.CustomWidgetInputs)
                        if (m.InputName == inputName) return m.PropertyPath ?? "";
                    return "";
                }
                static void SetCollCwInputMap(CollectionNode n, string inputName, string path)
                {
                    n.CustomWidgetInputs ??= new List<CustomWidgetInputMap>();
                    for (int i = 0; i < n.CustomWidgetInputs.Count; i++)
                    {
                        if (n.CustomWidgetInputs[i].InputName == inputName)
                        {
                            if (string.IsNullOrEmpty(path)) { n.CustomWidgetInputs.RemoveAt(i); return; }
                            n.CustomWidgetInputs[i] = new CustomWidgetInputMap(inputName, path);
                            return;
                        }
                    }
                    if (!string.IsNullOrEmpty(path)) n.CustomWidgetInputs.Add(new CustomWidgetInputMap(inputName, path));
                }

                var cwContainer = new VisualElement();
                cwContainer.style.display = collectionNode.DisplayMode == CollectionDisplayMode.CustomWidget ? DisplayStyle.Flex : DisplayStyle.None;

                var cwAssetField = new ObjectField("Widget Asset")
                {
                    objectType = typeof(SasquatchCustomWidget),
                    allowSceneObjects = false,
                    value = CustomWidgetLibrary.Resolve(collectionNode.CustomWidgetGuid)
                };
                cwAssetField.tooltip = "The custom widget asset that renders this whole array. The array feeds the widget's primary (list) input.";

                var cwInputsContainer = new VisualElement();
                cwInputsContainer.style.marginLeft = 14;

                Action rebuildCwInputRows = null;
                rebuildCwInputRows = () =>
                {
                    cwInputsContainer.Clear();
                    if (!(_selectedNode is CollectionNode cnRows)) return;
                    var cw = CustomWidgetLibrary.Resolve(cnRows.CustomWidgetGuid);
                    if (cw == null || cw.Inputs == null) return;
                    var primaryInput = cw.PrimaryInput;
                    bool anyMapped = false;
                    foreach (var inp in cw.Inputs)
                    {
                        if (inp == null || inp == primaryInput || string.IsNullOrEmpty(inp.Name)) continue;
                        anyMapped = true;
                        var mapField = new TextField(inp.Name) { value = GetCollCwInputMap(cnRows, inp.Name) };
                        mapField.tooltip = $"Sibling property path feeding the '{inp.Name}' input ({inp.Kind}).";
                        mapField.RegisterValueChangedCallback(evt =>
                        {
                            if (!(_selectedNode is CollectionNode cn)) return;
                            HandleDebouncedTextEdit("Map Custom Widget Input", () => SetCollCwInputMap(cn, inp.Name, evt.newValue));
                        });
                        FlushTextEditOnBlur(mapField);
                        AutocompleteTextField.Attach(mapField, () =>
                        {
                            var targetType = ResolveTargetType();
                            if (targetType == null) return Array.Empty<string>();
                            var all = SasquatchReflectionUtility.GetSerializableProperties(targetType);
                            string basePath = GetEffectiveBasePath(collectionNode, _clonedLayoutAsset?.Root, "") ?? "";
                            if (!string.IsNullOrEmpty(basePath))
                            {
                                string prefix = basePath + ".";
                                return all.Where(p => !p.isCollection && p.path.StartsWith(prefix)).Select(p => p.path.Substring(prefix.Length));
                            }
                            var collPrefixes = all.Where(p => p.isCollection).Select(p => p.path + ".").ToList();
                            return all.Where(p => !p.isCollection && !collPrefixes.Any(cp => p.path.StartsWith(cp))).Select(p => p.path);
                        }, s => FieldPathSnippet(s.Value, GetEffectiveBasePath(collectionNode, _clonedLayoutAsset?.Root, "")));
                        cwInputsContainer.Add(mapField);
                    }
                    if (!anyMapped)
                    {
                        var note = new Label("This widget has only a primary input (fed by the array itself).");
                        note.style.whiteSpace = WhiteSpace.Normal;
                        note.style.opacity = 0.7f;
                        cwInputsContainer.Add(note);
                    }
                };

                cwAssetField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Assign Custom Widget");
                    var wdg = evt.newValue as SasquatchCustomWidget;
                    cn.CustomWidgetGuid = wdg != null ? CustomWidgetLibrary.GuidOf(wdg) : "";
                    rebuildCwInputRows();
                    OnModification();
                    RefreshPreview();
                });

                cwContainer.Add(cwAssetField);
                cwContainer.Add(cwInputsContainer);
                rebuildCwInputRows();
                CustomWidgetComposerHooks.AttachDesignerButtons(cwContainer,
                    () => (_selectedNode as CollectionNode)?.CustomWidgetGuid,
                    g => { if (_selectedNode is CollectionNode cn) cn.CustomWidgetGuid = g; },
                    cwAssetField, rebuildCwInputRows,
                    () => { OnModification(); RefreshPreview(); });
#endif

                // Only the two styles we still offer. Arrows / Both are NOT deleted from the enum (None was
                // appended last to preserve serialized integers — see LayoutTreeBuilder.ResolveReorderStyle);
                // a layout that stored one keeps working and simply renders as Drag Handle. A PopupField of
                // an explicit list, not an EnumField, is what lets us drop members from the offer.
                var reorderChoices = new List<CollectionReorderStyle>
                {
                    CollectionReorderStyle.DragAndDrop, CollectionReorderStyle.None
                };
                var reorderField = new PopupField<CollectionReorderStyle>(
                    "Reorder Style", reorderChoices,
                    reorderChoices.Contains(collectionNode.ReorderStyle)
                        ? collectionNode.ReorderStyle
                        : LayoutTreeBuilder.ResolveReorderStyle(collectionNode.ReorderStyle),
                    v => v == CollectionReorderStyle.None ? "None" : "Drag Handle",
                    v => v == CollectionReorderStyle.None ? "None" : "Drag Handle");
                reorderField.tooltip = "Whether elements can be reordered in the live inspector by dragging their index gutter.";
                reorderField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Collection Reorder Style");
                    collectionNode.ReorderStyle = evt.newValue;
                    OnModification();
                });

                // The List's container-level look. Orthogonal to Row Frame below, which owns the row surface.
                var listStyleField = new EnumField("List Style", collectionNode.ListStyle);
                listStyleField.tooltip =
                    "The overall look of a List: Rows (bordered shell), Minimal (no shell, more air), " +
                    "or Timeline (a recessed well with a rail down it, each index a node on the rail).";
                listStyleField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change List Style");
                    collectionNode.ListStyle = (CollectionListStyle)evt.newValue;
                    OnModification();
                });

                var searchableField = new Toggle("Searchable");
                searchableField.tooltip = "Show a search/filter field at the top of the collection.";
                searchableField.value = collectionNode.Searchable;
                // Callback registered below, after UpdateDisplayFields + the dependent fields exist (it
                // toggles the "Search Field" row, so it must be able to see it — definite-assignment order).

                // Search Field — scopes the search box to ONE element field (blank = search all fields).
                var searchPropertyField = new TextField("Search Field");
                searchPropertyField.tooltip = "Limit the search box to one element field (e.g. \"itemName\"). Leave blank to search all fields.";
                searchPropertyField.value = collectionNode.SearchProperty;
                searchPropertyField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    HandleDebouncedTextEdit("Change Collection Search Field", () => cn.SearchProperty = evt.newValue);
                });
                FlushTextEditOnBlur(searchPropertyField);
                AutocompleteTextField.Attach(searchPropertyField, () =>
                {
                    var elemType = ResolveCollectionElementType(collectionNode);
                    return elemType != null
                        ? SasquatchReflectionUtility.GetSerializableProperties(elemType).Select(p => p.path)
                        : Array.Empty<string>();
                }, s => FieldPathSnippet(s.Value, owner: ResolveCollectionElementType(collectionNode)));

                var searchTray = MakeSubOptionTray();
                searchTray.Add(Identity(searchPropertyField));

                // Sortable — clickable Table headers + a List-mode sort dropdown (view-only sort).
                var enableSortingField = new Toggle("Sortable");
                enableSortingField.tooltip = "Let users sort rows: click a Table column header, or use the List-mode sort dropdown. View-only — the underlying list order is never changed.";
                enableSortingField.value = collectionNode.EnableSorting;
                enableSortingField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Sortable Collection");
                    cn.EnableSorting = evt.newValue;
                    OnModification();
                });

                // Paginate (+ Page Size) — render one page of rows at a time (the perf win for large lists).
                var enablePaginationField = new Toggle("Paginate");
                enablePaginationField.tooltip = "Render the list one page at a time. Only kicks in once there are more rows than the page size.";
                enablePaginationField.value = collectionNode.EnablePagination;

                var pageSizeField = new IntegerField("Page Size");
                pageSizeField.tooltip = "Rows per page when pagination is on.";
                pageSizeField.value = collectionNode.PageSize;
                pageSizeField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    int v = Mathf.Max(1, evt.newValue);
                    HandleDebouncedValueEdit("Change Collection Page Size", () => cn.PageSize = v, liveRebuild: true);
                });
                FlushValueEditOnBlur(pageSizeField);
                SyncClampedDisplay(pageSizeField, () => collectionNode.PageSize); // show the clamp, not mid-keystroke

                var pageStyleField = new EnumField("Page Navigator", collectionNode.PaginationDisplayStyle);
                pageStyleField.tooltip = "How the page navigator is shown: prev/next buttons, clickable page dots, or both.";
                pageStyleField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Change Pagination Display Style");
                    cn.PaginationDisplayStyle = (PaginationDisplayStyle)evt.newValue;
                    OnModification();
                });

                var paginateTray = MakeSubOptionTray();
                paginateTray.Add(pageSizeField);
                paginateTray.Add(pageStyleField);

                // Paginate callback registered below, after UpdateDisplayFields exists (it toggles Page Size).

                var minimizableField = new Toggle("Expandable");
                minimizableField.tooltip = "Allow collapsing/expanding the collection by clicking its header.";
                minimizableField.value = collectionNode.Expandable;

                var startExpandedField = new Toggle("Default to Open");
                startExpandedField.tooltip = "If collapsible, should the collection open by default?";
                startExpandedField.value = collectionNode.DefaultToOpen;

                var expandableTray = MakeSubOptionTray();
                expandableTray.Add(startExpandedField);
                expandableTray.style.display = collectionNode.Expandable ? DisplayStyle.Flex : DisplayStyle.None;

                var zebraStripingField = new Toggle("Zebra Striping");
                zebraStripingField.tooltip = "Tint alternating rows so long lists/tables are easier to scan.";
                zebraStripingField.value = collectionNode.ZebraStriping;

                var zebraColorRow = CreateOverridableColorElement("Zebra Color",
                    () => collectionNode.ZebraColor,
                    val => { collectionNode.ZebraColor = val; },
                    RefreshPreview);
                zebraColorRow.tooltip = "The odd-row tint; unset uses a faint theme wash.";

                var zebraTray = MakeSubOptionTray();
                zebraTray.Add(zebraColorRow);

                // Label only — the SERIALIZED name stays `rowSeparator`. Card is a look, not just a divider,
                // so "Row Frame" describes the axis better; renaming the field itself would fail the golden
                // corpus for no user-visible gain.
                var rowSeparatorField = new EnumField("Row Frame", collectionNode.RowSeparator);
                rowSeparatorField.tooltip =
                    "How each element's own surface is drawn. Composes with List Style above — every frame " +
                    "works with every style.\n\n" +
                    "Line — a hairline between rows (never after the last one). Best for short rows.\n" +
                    "Card — each row gets its own tray with a left edge rail. The rail is the only cue " +
                    "that grows with the row, so this is the one for tall rows (In-Line Editor Rows). " +
                    "Inside the Timeline style the tray drops its rail, because the timeline already owns " +
                    "the left edge; in a Table the tray is tighter, so it costs a table barely any height.\n" +
                    "None — no frame at all.";

                var rowSeparatorColorRow = CreateOverridableColorElement("Frame Color",
                    () => collectionNode.RowSeparatorColor,
                    val => { collectionNode.RowSeparatorColor = val; },
                    RefreshPreview);
                rowSeparatorColorRow.tooltip = "The hairline (Line) or the edge rail (Card); unset uses a theme default.";

                var separatorTray = MakeSubOptionTray();
                separatorTray.Add(rowSeparatorColorRow);

                // Per-element in-line editing. Only offered when it can do anything: the elements are
                // UnityEngine.Object references (a ScriptableObject/component list) and no item template is
                // designed — a template already decides what a row looks like.
                var inlineElementType = ResolveCollectionElementType(collectionNode);

                var elementInlineField = new Toggle("In-Line Editor Rows");
                elementInlineField.tooltip =
                    "Draw each element as an in-line editor — the object field plus that object's own " +
                    "inspector under a chevron — instead of a reference you can only reassign. Lets you edit " +
                    "the items of a ScriptableObject/component list in place, with no 'focused item' helper field.";
                elementInlineField.value = collectionNode.ElementInlineEditor;

                var elementOpenField = new Toggle("Rows Open by Default");
                elementOpenField.tooltip =
                    "Start every row expanded. Off keeps the list scannable — a collapsed row builds nothing " +
                    "until you open it, so long lists stay fast.";
                elementOpenField.value = collectionNode.ElementDefaultToOpen;

                // Drill into the ELEMENT type's layout — the same way in a single In-Line Editor binding gets,
                // since every row here is an editor for that one type. Pinned to the BOTTOM of the tray: it is a
                // NAVIGATION action, not another toggle. It hides ITSELF when there is nowhere to go, so it only
                // ever needs the tray's own gate around it.
                var elementDrillRow = BuildInlineEditorDrillInRow(collectionNode);
                elementDrillRow.style.marginTop = 3;

                var inlineTray = MakeSubOptionTray();
                inlineTray.Add(elementOpenField);
                inlineTray.Add(elementDrillRow);

                // ── The three option sections ────────────────────────────────────────────────────────────
                // Everything below Display Type is split by WHAT the option affects, so a name is findable by
                // guessing the section: the rows themselves / the controls above them / the per-element editor.
                // One flat column of all of them is impossible to scan.
                var rowsSection = CreatePersistedSection("Rows",
                    _collectionRowsExpanded, v => _collectionRowsExpanded = v);
                var listToolsSection = CreatePersistedSection("Search, Sort & Paging",
                    _collectionToolsExpanded, v => _collectionToolsExpanded = v);
                var inlineSection = CreatePersistedSection("In-Line Editors",
                    _collectionInlineExpanded, v => _collectionInlineExpanded = v);

                void UpdateDisplayFields(CollectionDisplayMode mode)
                {
                    // List/Table own the row ergonomics (reorder/search/paginate/…); Default (raw Unity) and
                    // CustomWidget (whole-array widget) hide them. CustomWidget instead reveals its asset picker.
                    bool active = mode == CollectionDisplayMode.List || mode == CollectionDisplayMode.Table;
#if SASQ_CUSTOM_WIDGET
                    cwContainer.style.display = mode == CollectionDisplayMode.CustomWidget ? DisplayStyle.Flex : DisplayStyle.None;
#endif
                    // Title lives in General Settings, not in the row-ergonomics set — every mode that draws a
                    // header of OURS honors it (List/Table titles, the label column on Tag Chips and a whole-array
                    // Custom Widget). Default is the one exception: Unity's own PropertyField owns that header, so
                    // the row would be a control that does nothing.
                    collHeaderRow.style.display =
                        mode == CollectionDisplayMode.Default ? DisplayStyle.None : DisplayStyle.Flex;
                    DisplayStyle on = active ? DisplayStyle.Flex : DisplayStyle.None;
                    reorderField.style.display = on;
                    // List ONLY — a Table has its own grid chrome, and offering a shell/gutter style there
                    // would be a control that does nothing.
                    listStyleField.style.display =
                        mode == CollectionDisplayMode.List ? DisplayStyle.Flex : DisplayStyle.None;
                    searchableField.style.display = on;
                    // Sub-option trays only open when active AND their parent toggle is on. Gating the TRAY
                    // (not each row) is what keeps its rail from surviving as an orphan hairline.
                    searchTray.style.display = (active && collectionNode.Searchable) ? DisplayStyle.Flex : DisplayStyle.None;
                    enableSortingField.style.display = on; // sorting exists in both List (dropdown) & Table (headers)
                    enablePaginationField.style.display = on;
                    paginateTray.style.display = (active && collectionNode.EnablePagination) ? DisplayStyle.Flex : DisplayStyle.None;
                    minimizableField.style.display = on;
                    expandableTray.style.display = (active && collectionNode.Expandable) ? DisplayStyle.Flex : DisplayStyle.None;
                    zebraStripingField.style.display = on;
                    zebraTray.style.display = (active && collectionNode.ZebraStriping) ? DisplayStyle.Flex : DisplayStyle.None;
                    rowSeparatorField.style.display = on;
                    separatorTray.style.display =
                        (active && collectionNode.RowSeparator != CollectionRowSeparator.None)
                            ? DisplayStyle.Flex : DisplayStyle.None;
                    bool inlineOn = SupportsInlineEditorRows(collectionNode, inlineElementType, mode);
                    elementInlineField.style.display = inlineOn ? DisplayStyle.Flex : DisplayStyle.None;
                    inlineTray.style.display = (inlineOn && collectionNode.ElementInlineEditor)
                        ? DisplayStyle.Flex : DisplayStyle.None;

                    // Roll the gates up to the section headers so Default / Custom Widget mode — which switches
                    // the whole set off at once — leaves no empty headers behind.
                    SyncSectionVisibility(rowsSection);
                    SyncSectionVisibility(listToolsSection);
                    SyncSectionVisibility(inlineSection);

                    // An expandable List/Table renders as the opaque .sasq-group shell, which swallows
                    // Appearance ▸ Background Color. Both inputs to that — Display Type and Expandable — land
                    // here, so this one call keeps the row honest for either.
                    syncGroupShellGatedRows?.Invoke();
                }

                // Registered here (not at declaration) so UpdateDisplayFields + every field it reads are
                // already definitely assigned — these callbacks reveal/hide indented dependent rows.
                searchableField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Searchable Collection");
                    cn.Searchable = evt.newValue;
                    UpdateDisplayFields(cn.DisplayMode); // reveal/hide the dependent "Search Field" row
                    OnModification();
                });

                enablePaginationField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Paginate Collection");
                    cn.EnablePagination = evt.newValue;
                    UpdateDisplayFields(cn.DisplayMode); // reveal/hide the dependent "Page Size" row
                    OnModification();
                });

                displayModeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Collection Display Mode");
                    var oldMode = collectionNode.DisplayMode;
                    var newMode = ChoiceToMode(evt.newValue);
                    collectionNode.DisplayMode = newMode;
                    if (newMode == CollectionDisplayMode.Table)
                    {
                        AutoFillTableColumnsIfEmpty(collectionNode);
                    }
                    ReseedCollectionForContext(collectionNode, oldMode, newMode); // context presets: restyle cells for the new mode
                    infoLabel.text = CollectionModeInfo(newMode);
                    UpdateDisplayFields(newMode);
                    OnModification();
                    RefreshHierarchy();
                    RefreshTokens();
                });

                // ── General Settings: what it binds to, how it draws, and its own header ──────────────────
                generalSection.Add(displayModeField);
                // The mode caption sits UNDER the dropdown it describes (it used to trail the whole panel,
                // where it read as a footnote to whatever row happened to be last).
                infoLabel.style.color = DesignerPalette.TextDisabled;
                infoLabel.style.whiteSpace = WhiteSpace.Normal;
                infoLabel.style.fontSize = 11;
                infoLabel.style.marginTop = 2;
                infoLabel.style.marginBottom = 6;
                infoLabel.style.marginLeft = 2;
                generalSection.Add(infoLabel);
#if SASQ_CUSTOM_WIDGET
                generalSection.Add(cwContainer);
#endif
                generalSection.Add(Identity(collHeaderRow));

                minimizableField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Expandable Collection");
                    cn.Expandable = evt.newValue;
                    UpdateDisplayFields(cn.DisplayMode); // reveal/hide the dependent "Default to Open"
                    OnModification();
                });
                generalSection.Add(minimizableField);

                startExpandedField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Change Collection Default to Open");
                    cn.DefaultToOpen = evt.newValue;
                    OnModification();
                });
                generalSection.Add(expandableTray);

                // ── Rows: how one element is drawn and reordered ──────────────────────────────────────────
                // List Style FIRST: it is the container-level choice, and Row Frame below refines it.
                rowsSection.Add(listStyleField);
                rowsSection.Add(reorderField);

                rowSeparatorField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Change Collection Row Separator");
                    cn.RowSeparator = (CollectionRowSeparator)evt.newValue;
                    UpdateDisplayFields(cn.DisplayMode); // reveal/hide the dependent Separator Color row
                    OnModification();
                    RefreshPreview();
                });
                rowsSection.Add(rowSeparatorField);
                rowsSection.Add(separatorTray);

                zebraStripingField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Zebra Striping");
                    cn.ZebraStriping = evt.newValue;
                    UpdateDisplayFields(cn.DisplayMode); // reveal/hide the dependent Zebra Color row
                    OnModification();
                    RefreshPreview();
                });
                rowsSection.Add(zebraStripingField);
                rowsSection.Add(zebraTray);

                // ── Search, Sort & Paging: the controls the collection draws ABOVE its rows ───────────────
                listToolsSection.Add(searchableField);
                listToolsSection.Add(searchTray);
                listToolsSection.Add(enableSortingField);
                listToolsSection.Add(enablePaginationField);
                listToolsSection.Add(paginateTray);

                // ── In-Line Editors: each row as an editor for the element itself ─────────────────────────
                elementInlineField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle In-Line Editor Rows");
                    cn.ElementInlineEditor = evt.newValue;
                    UpdateDisplayFields(cn.DisplayMode); // reveal/hide the dependent "Rows Open by Default"
                    OnModification();
                    RefreshPreview();
                });
                inlineSection.Add(elementInlineField);

                elementOpenField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is CollectionNode cn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Change In-Line Rows Default to Open");
                    cn.ElementDefaultToOpen = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                inlineSection.Add(inlineTray);

                UpdateDisplayFields(collectionNode.DisplayMode);

                extraSections = new List<VisualElement> { rowsSection, listToolsSection, inlineSection };

                // Polymorphic element menu — only for [SerializeReference] lists (interface/abstract element
                // type), whose elements render as branded type pickers. Mirrors the DropDown widget's
                // Searchable + menu styling; the values are propagated onto each element by LayoutTreeBuilder.
                // Build-time gated (the panel rebuilds on selection), so it needs no runtime display logic —
                // hence a plain section rather than one wired into UpdateDisplayFields.
                var polyElementType = ResolveCollectionElementType(collectionNode);
                if (polyElementType != null && (polyElementType.IsInterface || polyElementType.IsAbstract))
                {
                    var polySection = CreateFoldoutHeader("Polymorphic Menu");

                    var polySearchable = new Toggle("Searchable");
                    polySearchable.tooltip = "Show a type-to-search box in each element's polymorphic type picker.";
                    polySearchable.value = collectionNode.PolymorphicSearchable;
                    polySearchable.RegisterValueChangedCallback(evt =>
                    {
                        if (!(_selectedNode is CollectionNode cn)) return;
                        Undo.RecordObject(_clonedLayoutAsset, "Toggle Polymorphic Searchable");
                        cn.PolymorphicSearchable = evt.newValue;
                        OnModification();
                        RefreshPreview();
                    });
                    polySection.Add(polySearchable);

                    polySection.Add(CreateOverridableColorElement("Menu Background",
                        () => collectionNode.DropdownPopupBackground,
                        val => { collectionNode.DropdownPopupBackground = val; },
                        RefreshPreview));

                    polySection.Add(CreateOverridableColorElement("Item Hover Background",
                        () => collectionNode.DropdownItemHoverBackground,
                        val => { collectionNode.DropdownItemHoverBackground = val; },
                        RefreshPreview));

                    var polyTextHover = CreateOverridableColorElement("Text Hover Color",
                        () => collectionNode.DropdownItemHoverColor,
                        val => { collectionNode.DropdownItemHoverColor = val; },
                        RefreshPreview);
                    polySection.Add(WithTextButton(polyTextHover,
                        () => collectionNode.DropdownItemTextStyle,
                        val => { collectionNode.DropdownItemTextStyle = val; },
                        "dropdown-item"));

                    extraSections.Add(polySection);
                }
            }
            else if (_selectedNode is ButtonNode buttonNode)
            {
                // NOTE: these callbacks write to `_selectedNode` (re-cast each time) rather than the captured
                // `buttonNode`. A save re-clones the working tree, which orphans the captured reference and
                // would land edits on a dead node — reading the live selection keeps every edit on the
                // current tree.
                var textBtnField = new TextField("Button Text");
                textBtnField.value = buttonNode.ButtonText;
                textBtnField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is ButtonNode bn)) return;
                    HandleDebouncedTextEdit("Change Button Text", () => bn.ButtonText = evt.newValue,
                        refreshHierarchy: true, liveRebuild: true);
                });
                FlushTextEditOnBlur(textBtnField);
                // The label TEXT is content (absent from ButtonTransfers); LabelTextStyle is styling and travels.
                if (_presetMode)
                    generalSection.Add(BuildPresetTextStyleRow("Button Text",
                        "each button keeps its own label text",
                        () => ((ButtonNode)_selectedNode).LabelTextStyle,
                        v => ((ButtonNode)_selectedNode).LabelTextStyle = v, "buttontext"));
                else
                    generalSection.Add(Identity(WithTextButton(textBtnField,
                        () => ((ButtonNode)_selectedNode).LabelTextStyle, v => ((ButtonNode)_selectedNode).LabelTextStyle = v, "buttontext")));

                var methodField = new TextField("Method Name");
                methodField.value = buttonNode.MethodName;
                methodField.tooltip = "The C# method to invoke on click. Parameterless methods run immediately; " +
                                      "methods with parameters prompt for values first.";

                // Hint that only appears once the chosen method actually takes parameters — and then shows them.
                var methodHint = new Label();
                methodHint.style.fontSize = 10;
                methodHint.style.opacity = 0.7f;
                methodHint.style.whiteSpace = WhiteSpace.Normal;
                methodHint.style.marginTop = 1;
                methodHint.style.marginBottom = 3;

                System.Action updateMethodHint = () =>
                {
                    var targetType = ResolveTargetType();
                    var m = targetType != null ? ButtonInvoker.ResolveMethod(targetType, methodField.value) : null;
                    if (m != null && m.GetParameters().Length > 0)
                    {
                        methodHint.text = $"Prompts for {FormatParameterList(m)} when clicked.";
                        methodHint.style.color = StyleKeyword.Null;
                        methodHint.style.display = DisplayStyle.Flex;
                    }
                    else if (m == null && targetType != null && !string.IsNullOrEmpty(methodField.value) &&
                             !EditorApplication.isCompiling)
                    {
                        // Missing-method affordance: past-healing breaks (deleted, renamed with a changed
                        // signature, or ambiguous) surface HERE instead of only as a click-time console error.
                        methodHint.text = ButtonInvoker.HasMethodNamed(targetType, methodField.value)
                            ? $"'{methodField.value}' exists on {targetType.Name} but has parameters a button can't prompt for."
                            : $"'{methodField.value}' isn't on {targetType.Name} — renamed or removed? Pick a current method from the list.";
                        methodHint.style.color = DesignerPalette.ToastWarning;
                        methodHint.style.display = DisplayStyle.Flex;
                    }
                    else
                    {
                        methodHint.style.display = DisplayStyle.None;
                    }
                };

                methodField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is ButtonNode bn)) return;
                    HandleDebouncedTextEdit("Change Button Method Name", () =>
                    {
                        bn.MethodName = evt.newValue;
                        // Same commit stamps/clears the rename-heal fingerprint: a resolving name records
                        // its signature; a non-resolving one clears it (a typed-ahead name must not inherit
                        // the previous method's fingerprint, or the heal would later "fix" it back).
                        bn.MethodSignature = ButtonMethodSync.ComputeSignature(ResolveTargetType(), evt.newValue);
                    });
                    updateMethodHint(); // cheap live feedback — stays per-keystroke
                });
                FlushTextEditOnBlur(methodField);
                AutocompleteTextField.Attach(methodField, () =>
                {
                    var targetType = ResolveTargetType();
                    return targetType != null
                        ? GetInvokableMethodSuggestions(targetType)
                        : Array.Empty<AutocompleteTextField.Suggestion>();
                }, s => MethodSourcePreview.GetSnippet(ResolveTargetType(), s.Value));
                // What the button DOES is content: MethodName / MethodSignature are absent from ButtonTransfers,
                // and a method name is meaningless in a preset anyway — it names a method on one script, while a
                // preset styles every button you ever drop. Same for the confirm dialog's flag + its two strings.
                if (!_presetMode)
                {
                    generalSection.Add(Identity(methodField));
                    generalSection.Add(Identity(methodHint));
                    updateMethodHint();
                }

                var confirmToggle = new Toggle("Confirm Before Execute");
                confirmToggle.value = buttonNode.ConfirmBeforeExecute;
                confirmToggle.tooltip = "Show a Yes/Cancel dialog before running the method.";
                if (!_presetMode) generalSection.Add(confirmToggle);

                // Title + message live in a group that's only shown when confirmation is enabled.
                var confirmGroup = new VisualElement();
                confirmGroup.style.display = buttonNode.ConfirmBeforeExecute ? DisplayStyle.Flex : DisplayStyle.None;

                var confirmTitleField = new TextField("Confirm Title");
                confirmTitleField.value = buttonNode.ConfirmTitle;
                confirmTitleField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is ButtonNode bn)) return;
                    HandleDebouncedTextEdit("Change Confirm Title", () => bn.ConfirmTitle = evt.newValue);
                });
                FlushTextEditOnBlur(confirmTitleField);
                confirmGroup.Add(Identity(confirmTitleField));

                var confirmMessageField = new TextField("Confirm Message");
                confirmMessageField.value = buttonNode.ConfirmMessage;
                // Wrap to the panel width (no horizontal scrollbar) + a drag-grip to grow the box.
                TextAreaHelper.MakeWrappingResizableTextArea(confirmMessageField);
                confirmMessageField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is ButtonNode bn)) return;
                    HandleDebouncedTextEdit("Change Confirm Message", () => bn.ConfirmMessage = evt.newValue);
                });
                FlushTextEditOnBlur(confirmMessageField);
                confirmGroup.Add(Identity(confirmMessageField));

                if (!_presetMode) generalSection.Add(confirmGroup);

                confirmToggle.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is ButtonNode bn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Confirm Before Execute");
                    bn.ConfirmBeforeExecute = evt.newValue;
                    confirmGroup.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                });

                // ---- Appearance: style preset + accent/radius + size/width + optional icon. ----
                var appearanceHeader = new Label("Appearance");
                appearanceHeader.style.unityFontStyleAndWeight = FontStyle.Bold;
                appearanceHeader.style.marginTop = 8;
                generalSection.Add(appearanceHeader);

                var buttonStyleField = new EnumField("Button Style", buttonNode.StylePreset);
                buttonStyleField.tooltip = "Visual preset. Classic is Unity's stock button chrome; " +
                                           "the other presets draw from the accent color.";
                generalSection.Add(buttonStyleField);

                var accentRow = CreateOverridableColorElement("Accent Color",
                    () => ((ButtonNode)_selectedNode).AccentColor,
                    val => { ((ButtonNode)_selectedNode).AccentColor = val; },
                    RefreshPreview, liveApply: () => LivePokeButtonChrome((ButtonNode)_selectedNode));
                generalSection.Add(accentRow);

                var radiusRow = CreateOverridableFloatElement("Corner Radius",
                    () => ((ButtonNode)_selectedNode).CornerRadius,
                    val => { ((ButtonNode)_selectedNode).CornerRadius = val; },
                    RefreshPreview, liveApply: () => LivePokeButtonChrome((ButtonNode)_selectedNode));
                generalSection.Add(radiusRow);

                var hoverAnimField = new EnumField("Hover Animation", buttonNode.HoverAnimation);
                hoverAnimField.tooltip = "The hover/press motion this button plays. Bounce is the default; " +
                                         "None disables the motion; Lift/Grow/Pop are alternative feels. " +
                                         "Hover the button in the live preview (Interact mode) to try it.";
                hoverAnimField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is ButtonNode bn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Change Button Hover Animation");
                    bn.HoverAnimation = (ButtonHoverAnimation)evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(hoverAnimField);

                var hoverColorRow = CreateOverridableColorElement("Hover Color",
                    () => ((ButtonNode)_selectedNode).HoverColor,
                    val => { ((ButtonNode)_selectedNode).HoverColor = val; },
                    RefreshPreview);
                hoverColorRow.tooltip = "Background color while hovered; unset keeps the built-in subtle lighten.";
                generalSection.Add(hoverColorRow);

                var pressedColorRow = CreateOverridableColorElement("Pressed Color",
                    () => ((ButtonNode)_selectedNode).PressedColor,
                    val => { ((ButtonNode)_selectedNode).PressedColor = val; },
                    RefreshPreview);
                pressedColorRow.tooltip = "Background color while pressed (pointer down); unset keeps the spring dip only.";
                generalSection.Add(pressedColorRow);

                // Deliberately OUTSIDE SyncButtonStyleRows: the backdrop is about legibility, not the accent
                // chrome, so it applies to Classic too (a Classic button grows the same inner label).
                var textBackdropToggle = new Toggle("Text Backdrop");
                textBackdropToggle.value = buttonNode.TextBackdrop;
                textBackdropToggle.tooltip = "Sit the label — and the icon — on a soft dark pill inside the button, " +
                                             "for guaranteed readability over any accent color. Off = the preset's own " +
                                             "text color.";
                textBackdropToggle.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is ButtonNode bn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Button Text Backdrop");
                    bn.TextBackdrop = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(textBackdropToggle);

                // Accent + radius + hover motion/colors mean nothing on the stock Unity (Classic) button.
                void SyncButtonStyleRows(ButtonStyle preset)
                {
                    var show = preset == ButtonStyle.Classic ? DisplayStyle.None : DisplayStyle.Flex;
                    accentRow.style.display = show;
                    radiusRow.style.display = show;
                    hoverAnimField.style.display = show;
                    hoverColorRow.style.display = show;
                    pressedColorRow.style.display = show;
                }
                SyncButtonStyleRows(buttonNode.StylePreset);

                buttonStyleField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is ButtonNode bn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Change Button Style");
                    bn.StylePreset = (ButtonStyle)evt.newValue;
                    SyncButtonStyleRows(bn.StylePreset);
                    OnModification();
                    RefreshPreview();
                });

                var buttonSizeField = MakeButtonSizeField("Size", buttonNode.Size);
                buttonSizeField.tooltip = "Height preset for the button. Fine-tune it with Custom Height below — " +
                                          "any value there overrides the preset.";
                buttonSizeField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is ButtonNode bn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Change Button Size");
                    bn.Size = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(buttonSizeField);

                // Custom Height — the exact-pixels escape hatch from the five presets. Drag it and the canvas
                // button resizes every tick (an in-place chrome + icon poke, no rebuild) while the undo/save
                // is coalesced into one step per drag — the progress bar's Height (px) contract. 0 = follow
                // the Size preset above, which is what the ↺ resets to.
                var buttonHeightField = new Slider("Custom Height", 0f, ButtonNode.MaxCustomHeight) { showInputField = true };
                buttonHeightField.tooltip = "Exact button height in pixels, overriding the Size preset — the icon " +
                    $"scales with it. Drag it below {ButtonNode.MinCustomHeight:0} to hand the height back to the " +
                    "preset (0 = follow the preset).";
                generalSection.Add(CreateResettableNumberField<float>(
                    buttonHeightField, 0f,
                    () => ((ButtonNode)_selectedNode).CustomHeight,
                    v => ((ButtonNode)_selectedNode).CustomHeight = v,
                    // The track runs from 0 so it can REACH the "follow the preset" sentinel: everything
                    // below the floor collapses to 0 rather than sticking at a 3px sliver of a button.
                    v => v < ButtonNode.MinCustomHeight ? 0f : Mathf.Min(v, ButtonNode.MaxCustomHeight),
                    "Change Button Height",
                    // Resize the rendered button in place every tick — the slider is AHEAD of the model
                    // here (the burst's undo record is taken first), so the drag value is passed through
                    // rather than re-read off the node.
                    liveApply: v => LivePokeButtonHeight((ButtonNode)_selectedNode, v)));

                var fullWidthToggle = new Toggle("Full Width");
                fullWidthToggle.value = buttonNode.FullWidth;
                fullWidthToggle.tooltip = "Stretch across the row (the default) or hug the button's content.";
                fullWidthToggle.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is ButtonNode bn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Button Full Width");
                    bn.FullWidth = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(fullWidthToggle);

                // Icon picker: [label] [live glyph preview] [searchable dropdown] [clear]. The icon
                // side row only appears once an icon is chosen.
                var iconSideField = BuildPlacementButtonRow<ButtonIconPlacement>(
                    "Icon Placement",
                    new (string, ButtonIconPlacement, string)[]
                    {
                        (SasquatchIcons.Ids.ArrowLeft, ButtonIconPlacement.Left, "Icon left of the label (default)"),
                        (SasquatchIcons.Ids.ArrowUp, ButtonIconPlacement.Top, "Icon above the label"),
                        (SasquatchIcons.Ids.ArrowRight, ButtonIconPlacement.Right, "Icon right of the label"),
                        (SasquatchIcons.Ids.ArrowDown, ButtonIconPlacement.Bottom, "Icon below the label"),
                    },
                    () => buttonNode.IconPlacement,
                    v => buttonNode.IconPlacement = v,
                    ButtonIconPlacement.Left,
                    "Change Button Icon Placement");

                var iconRow = new VisualElement();
                iconRow.style.flexDirection = FlexDirection.Row;
                iconRow.style.alignItems = Align.Center;
                iconRow.style.marginBottom = 4;

                var iconRowLabel = new Label("Icon");
                iconRowLabel.style.minWidth = 120;
                iconRow.Add(iconRowLabel);

                var iconPreviewHost = new VisualElement();
                iconPreviewHost.style.width = 16;
                iconPreviewHost.style.height = 16;
                iconPreviewHost.style.marginRight = 4;
                iconPreviewHost.style.justifyContent = Justify.Center;
                iconPreviewHost.style.alignItems = Align.Center;
                iconRow.Add(iconPreviewHost);

                var iconPickButton = new Button();
                iconPickButton.style.flexGrow = 1;
                // Opt OUT of the options-panel spring sweep — a value read-out that happens to be clickable
                // reads better static than as a springy action button.
                iconPickButton.AddToClassList(OptionSprungClass);
                iconRow.Add(iconPickButton);

                var iconClearButton = new Button { text = "✕", tooltip = "Remove the icon." };
                iconClearButton.AddToClassList(OptionSprungClass);
                iconRow.Add(iconClearButton);

                void SyncIconRow()
                {
                    string id = (_selectedNode as ButtonNode)?.IconId ?? "";
                    bool hasIcon = !string.IsNullOrEmpty(id);
                    iconPickButton.text = hasIcon ? id : "None…";
                    iconClearButton.style.display = hasIcon ? DisplayStyle.Flex : DisplayStyle.None;
                    iconSideField.style.display = hasIcon ? DisplayStyle.Flex : DisplayStyle.None;
                    iconPreviewHost.Clear();
                    if (hasIcon) iconPreviewHost.Add(SasquatchIcons.Create(id, 14f));
                }

                void SetButtonIcon(string id, string undoName)
                {
                    if (!(_selectedNode is ButtonNode bn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, undoName);
                    bn.IconId = id;
                    SyncIconRow();
                    OnModification();
                    RefreshPreview();
                }

                iconPickButton.clicked += () =>
                {
                    var choices = new List<string>(SasquatchIcons.AllIds);
                    UnityEditor.PopupWindow.Show(iconPickButton.worldBound,
                        new SearchableDropdownPopup(null, "Button Icon", choices,
                            (_selectedNode as ButtonNode)?.IconId,
                            selected => SetButtonIcon(selected, "Change Button Icon"),
                            itemIcon: id => SasquatchIcons.Create(id, 14f), anchor: iconPickButton));
                };
                iconClearButton.clicked += () => SetButtonIcon("", "Remove Button Icon");

                SyncIconRow();
                // A button's icon is content, not styling — the WidgetPresetCatalog / StyleClipboard contract is
                // explicit about it, so IconId is absent from ButtonTransfers. Placement rides along: it only
                // shows once an icon is chosen, and there is no icon to place in a preset.
                if (!_presetMode)
                {
                    generalSection.Add(iconRow);
                    generalSection.Add(iconSideField);
                }
            }
            else if (_selectedNode is PropertyNode propertyNode)
            {
                var nameField = new TextField("Property Name");
                nameField.value = propertyNode.PropertyName;
                nameField.tooltip = "The C# property (getter) to display live. " +
                                    "Get-only or complex-typed properties show read-only; a writable simple-typed " +
                                    "property is editable (the setter runs on change).";

                // Live hint: the resolved value type + whether it'll render editable or read-only.
                var propHint = new Label();
                propHint.style.fontSize = 10;
                propHint.style.opacity = 0.7f;
                propHint.style.whiteSpace = WhiteSpace.Normal;
                propHint.style.marginTop = 1;
                propHint.style.marginBottom = 3;

                System.Action updatePropHint = () =>
                {
                    var targetType = ResolveTargetType();
                    var p = targetType != null ? PropertyInvoker.ResolveProperty(targetType, nameField.value) : null;
                    if (p != null)
                    {
                        bool editable = p.CanWrite && !((PropertyNode)_selectedNode).ForceReadOnly
                                        && PropertyInvoker.IsSimpleEditableType(p.PropertyType);
                        propHint.text = $"{FriendlyTypeName(p.PropertyType)} — {(editable ? "editable (writes via setter)" : "read-only")}";
                        propHint.style.display = DisplayStyle.Flex;
                    }
                    else
                    {
                        propHint.text = string.IsNullOrEmpty(nameField.value)
                            ? "" : "No readable property with that name on the target type.";
                        propHint.style.display = string.IsNullOrEmpty(nameField.value) ? DisplayStyle.None : DisplayStyle.Flex;
                    }
                };

                nameField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is PropertyNode pn)) return;
                    HandleDebouncedTextEdit("Change Property Name", () => pn.PropertyName = evt.newValue,
                        refreshHierarchy: true);
                    updatePropHint(); // cheap live feedback — stays per-keystroke
                });
                FlushTextEditOnBlur(nameField);
                AutocompleteTextField.Attach(nameField, () =>
                {
                    var targetType = ResolveTargetType();
                    return targetType != null
                        ? GetReadablePropertySuggestions(targetType)
                        : Array.Empty<AutocompleteTextField.Suggestion>();
                }, s => MethodSourcePreview.GetPropertySnippet(ResolveTargetType(), s.Value));
                generalSection.Add(Identity(nameField));
                generalSection.Add(Identity(propHint));
                updatePropHint();

                // Field + ↺ reset. Empty override = the nicified property name (the default), so the ↺ shows only
                // when a custom label is set and clears it back to empty. (Not the shared OverridableTextRow: that
                // uses a HiddenSentinel three-state model, which here would collide with the separate Hide Label
                // toggle below and the builder's "empty ⇒ nicified name" reading.)
                var labelRow = new VisualElement();
                labelRow.style.flexDirection = FlexDirection.Row;
                labelRow.style.alignItems = Align.Center;

                var labelOverrideField = new TextField("Label Override");
                labelOverrideField.style.flexGrow = 1;
                labelOverrideField.value = propertyNode.LabelOverride;
                labelOverrideField.tooltip = "Optional label text; empty uses a nicified property name.";

                var labelReset = MakeStyleResetButton();
                void SyncLabelReset() => labelReset.style.display =
                    string.IsNullOrEmpty(((PropertyNode)_selectedNode).LabelOverride) ? DisplayStyle.None : DisplayStyle.Flex;

                labelOverrideField.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is PropertyNode pn)) return;
                    HandleDebouncedTextEdit("Change Property Label",
                        () => { pn.LabelOverride = evt.newValue; SyncLabelReset(); }, liveRebuild: true);
                });
                FlushTextEditOnBlur(labelOverrideField);

                void ResetPropertyLabel()
                {
                    CommitPendingTextEdit(); // close any open typing burst before this discrete reset's own record
                    if (!(_selectedNode is PropertyNode pn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Reset Property Label");
                    pn.LabelOverride = string.Empty;
                    labelOverrideField.SetValueWithoutNotify(string.Empty);
                    OnModification();
                    RefreshPreview();
                    SyncLabelReset();
                }
                labelReset.clicked += ResetPropertyLabel;
                AddStyleResetContextMenu(labelRow,
                    () => !string.IsNullOrEmpty(((PropertyNode)_selectedNode).LabelOverride), ResetPropertyLabel);

                labelRow.Add(labelOverrideField);
                labelRow.Add(labelReset);
                SyncLabelReset();
                generalSection.Add(Identity(WithTextButton(labelRow,
                    () => ((PropertyNode)_selectedNode).LabelTextStyle,
                    v => ((PropertyNode)_selectedNode).LabelTextStyle = v, "propertylabel")));

                var hideLabelToggle = new Toggle("Hide Label");
                hideLabelToggle.value = propertyNode.HideLabel;
                hideLabelToggle.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is PropertyNode pn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Property Hide Label");
                    pn.HideLabel = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(hideLabelToggle);

                var forceReadOnlyToggle = new Toggle("Read-Only");
                forceReadOnlyToggle.value = propertyNode.ForceReadOnly;
                forceReadOnlyToggle.tooltip = "Display the value read-only even if the property has a usable setter.";
                forceReadOnlyToggle.RegisterValueChangedCallback(evt =>
                {
                    if (!(_selectedNode is PropertyNode pn)) return;
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Property Read-Only");
                    pn.ForceReadOnly = evt.newValue;
                    OnModification();
                    RefreshPreview();
                    updatePropHint();
                });
                generalSection.Add(forceReadOnlyToggle);
            }
            else if (_selectedNode is ScriptHeaderNode scriptHeader)
            {
                var hideIconToggle = new Toggle("Hide Icon");
                hideIconToggle.value = scriptHeader.HideIcon;
                hideIconToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Script Header Icon");
                    scriptHeader.HideIcon = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(hideIconToggle);

                var showSearchToggle = new Toggle("Show Search");
                showSearchToggle.value = scriptHeader.ShowSearch;
                showSearchToggle.tooltip = "Show the field-search magnifier in the header (hover-revealed, next to the " +
                                           "Live Debug bug). Off removes it and disables the inspector field search for this layout.";
                showSearchToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Script Header Search");
                    scriptHeader.ShowSearch = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                // ScriptHeaderTransfers carries Hide Icon + the text style, and nothing else. Show Search is a
                // per-LAYOUT behaviour switch (it disables that layout's inspector field search) rather than
                // styling, so it isn't in the list — and therefore isn't offered here.
                if (!_presetMode) generalSection.Add(showSearchToggle);

                var showDebugToggle = new Toggle("Show Live Debug");
                showDebugToggle.value = scriptHeader.ShowDebugToggle;
                showDebugToggle.tooltip = "Add the Live Debug button (bug glyph) to the header. Clicking it in the live " +
                                          "inspector records every field on this script while you play, and draws each " +
                                          "one's history as a graph under it. Off by default — this only adds the " +
                                          "button; nothing is recorded until it is switched on.";
                showDebugToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Live Debug Button");
                    scriptHeader.ShowDebugToggle = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                // Same reasoning as Show Search directly above: a per-LAYOUT behaviour switch, not styling, so it
                // stays out of ScriptHeaderTransfers and is not offered in preset mode.
                if (!_presetMode) generalSection.Add(showDebugToggle);

                // Icon Source picks EITHER a custom texture OR a built-in glyph — mutually exclusive by construction
                // (the enum flips which control shows/renders; neither stored value is cleared). Default is Custom, so
                // existing headers (texture-or-script-icon) are unchanged.
                var iconSourceField = new EnumField("Icon Source", scriptHeader.IconSource);
                iconSourceField.tooltip = "Custom = your own texture; Built In = a built-in icon " +
                                          "(same set as the Button widget). Ignored when Hide Icon is on.";
                // WHICH icon is content (a texture asset or a glyph id), so neither the source switch nor its two
                // pickers travel — only the Hide Icon toggle above does. All three are hidden in the Preset Editor.
                if (!_presetMode) generalSection.Add(Identity(iconSourceField));

                var iconField = new ObjectField("Custom Icon")
                {
                    objectType = typeof(Texture2D),
                    allowSceneObjects = false,
                    value = scriptHeader.CustomIcon
                };
                iconField.tooltip = "The texture to show. Empty = the script's own icon.";
                iconField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Script Header Icon");
                    scriptHeader.CustomIcon = evt.newValue as Texture2D;
                    OnModification();
                    RefreshPreview();
                });
                if (!_presetMode) generalSection.Add(Identity(iconField));

                // Built-in icon picker: [label] [live glyph preview] [searchable dropdown] [clear]. Reuses the exact
                // shared icon pipeline as Action Buttons (SasquatchIcons + SearchableDropdownPopup); the clear (✕) only
                // appears once an icon is chosen. Shaped as a real base field (unity-base-field + __label) so its label
                // rides the SAME theme label column as the Custom Icon field above — a bare row's label drifts left of it.
                var lucideRow = new VisualElement();
                lucideRow.AddToClassList("unity-base-field");
                lucideRow.style.flexDirection = FlexDirection.Row;
                lucideRow.style.alignItems = Align.Center;

                var lucideRowLabel = new Label("Built In Icon");
                lucideRowLabel.AddToClassList("unity-base-field__label");
                lucideRowLabel.tooltip = "Pick a built-in icon (same set as the Button widget).";
                lucideRow.Add(lucideRowLabel);

                var lucidePreviewHost = new VisualElement();
                lucidePreviewHost.style.width = 16;
                lucidePreviewHost.style.height = 16;
                lucidePreviewHost.style.marginRight = 4;
                lucidePreviewHost.style.justifyContent = Justify.Center;
                lucidePreviewHost.style.alignItems = Align.Center;
                lucideRow.Add(lucidePreviewHost);

                var lucidePickButton = new Button();
                lucidePickButton.style.flexGrow = 1;
                lucidePickButton.AddToClassList(OptionSprungClass);
                lucideRow.Add(lucidePickButton);

                var lucideClearButton = new Button { text = "✕", tooltip = "Remove the built-in icon." };
                lucideClearButton.AddToClassList(OptionSprungClass);
                lucideRow.Add(lucideClearButton);

                void SyncScriptHeaderLucideRow()
                {
                    string id = scriptHeader.IconId ?? "";
                    bool hasIcon = !string.IsNullOrEmpty(id);
                    lucidePickButton.text = hasIcon ? id : "None…";
                    lucideClearButton.style.display = hasIcon ? DisplayStyle.Flex : DisplayStyle.None;
                    lucidePreviewHost.Clear();
                    if (hasIcon) lucidePreviewHost.Add(SasquatchIcons.Create(id, 14f));
                }

                void SetScriptHeaderLucideIcon(string id, string undoName)
                {
                    Undo.RecordObject(_clonedLayoutAsset, undoName);
                    scriptHeader.IconId = id;
                    SyncScriptHeaderLucideRow();
                    OnModification();
                    RefreshPreview();
                }

                lucidePickButton.clicked += () =>
                {
                    var choices = new List<string>(SasquatchIcons.AllIds);
                    UnityEditor.PopupWindow.Show(lucidePickButton.worldBound,
                        new SearchableDropdownPopup(null, "Script Header Icon", choices,
                            scriptHeader.IconId,
                            selected => SetScriptHeaderLucideIcon(selected, "Change Script Header Built In Icon"),
                            itemIcon: id => SasquatchIcons.Create(id, 14f), anchor: lucidePickButton));
                };
                lucideClearButton.clicked += () => SetScriptHeaderLucideIcon("", "Remove Script Header Built In Icon");

                SyncScriptHeaderLucideRow();
                if (!_presetMode) generalSection.Add(lucideRow);

                // Show only the control for the active source; the enum toggles between them.
                void SyncScriptHeaderIconSource()
                {
                    bool custom = scriptHeader.IconSource == ScriptHeaderIconSource.Custom;
                    iconField.style.display = custom ? DisplayStyle.Flex : DisplayStyle.None;
                    lucideRow.style.display = custom ? DisplayStyle.None : DisplayStyle.Flex;
                }

                iconSourceField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Script Header Icon Source");
                    scriptHeader.IconSource = (ScriptHeaderIconSource)evt.newValue;
                    SyncScriptHeaderIconSource();
                    OnModification();
                    RefreshPreview();
                });
                SyncScriptHeaderIconSource();

                // The header's TEXT defaults to the script's own name and is per-layout content; TextStyle travels.
                if (_presetMode)
                {
                    generalSection.Add(BuildPresetTextStyleRow("Display Text",
                        "each header shows its own script name",
                        () => scriptHeader.TextStyle, v => scriptHeader.TextStyle = v, "scriptHeaderTitle"));
                }
                else
                {
                    var defaultText = GetDefaultScriptHeaderName();
                    var displayTextRow = BuildOverridableField(
                        "Display Text", scriptHeader.TextOverride, defaultText,
                        "Change Script Header Text", v => scriptHeader.TextOverride = v, refreshHierarchy: true,
                        // Best-of-both-worlds: no per-keystroke lag, yet the header text updates on the canvas as
                        // you type. Debounce owns the undo/save; the live poke rewrites the rendered title label
                        // in place each keystroke (matching the canvas builder's EffectiveTextOverride ?? default).
                        debounceText: true,
                        liveApply: () => LivePokeChild(scriptHeader, "sasq-script-header-title",
                            lbl => { if (lbl is Label l) l.text = scriptHeader.EffectiveTextOverride ?? defaultText; }));
                    generalSection.Add(Identity(WithTextButton(displayTextRow,
                        () => scriptHeader.TextStyle, v => scriptHeader.TextStyle = v, "scriptHeaderTitle")));
                }
            }
            else if (_selectedNode is HelpBoxNode helpBoxNode)
            {
                // Summary Text first — for an expandable box it's the line the user actually sees until
                // they expand it. Overridable-row convention ("{MessageType} Details" default shown
                // normal-weight, override bold, cleared = "(hidden)", ↺ restores) + a "T" style button.
                // Only visible while Expandable is on (a non-expandable box has no collapsed state).
                // Both strings here are content and are dropped on preset capture (HelpBoxTransfers carries the
                // two TEXT STYLES, the type, and the expand/collapse options — no message, no summary), so the
                // Preset Editor keeps the "T"s and drops the boxes.
                VisualElement summaryWrapper;
                if (_presetMode)
                {
                    summaryWrapper = BuildPresetTextStyleRow("Summary Text",
                        "each box keeps its own summary text",
                        () => helpBoxNode.SummaryTextStyle, v => helpBoxNode.SummaryTextStyle = v, "helpBoxSummary");
                }
                else
                {
                    var summaryRow = BuildOverridableField(
                        "Summary Text", helpBoxNode.CollapsedSummary, helpBoxNode.MessageType + " Details",
                        "Change HelpBox Summary", v => helpBoxNode.CollapsedSummary = v, refreshHierarchy: false,
                        "The line shown while the box is collapsed. Clear it to hide the text entirely.",
                        debounceText: true, liveRebuild: true);
                    summaryWrapper = Identity(WithTextButton(summaryRow,
                        () => helpBoxNode.SummaryTextStyle, v => helpBoxNode.SummaryTextStyle = v, "helpBoxSummary",
                        RichTextFormattingHelp));
                }
                // Summary Text lives BELOW "Expandable" (added into expandSettingsContainer further down), since
                // it only applies when expandable; it's also hidden for the Chip collapsed style (a "?" chip shows
                // no summary). Visibility within the container is gated on the collapsed style.
                summaryWrapper.style.display = helpBoxNode.CollapsedStyle == HelpBoxCollapsedStyle.SummaryLine ? DisplayStyle.Flex : DisplayStyle.None;

                var msgField = new TextField("Message");
                msgField.value = helpBoxNode.Message;
                // Wrap long messages to the panel width (no horizontal scrollbar) + a drag-grip to grow the box.
                TextAreaHelper.MakeWrappingResizableTextArea(msgField);
                msgField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change HelpBox Message", () => helpBoxNode.Message = evt.newValue,
                        liveRebuild: true));
                FlushTextEditOnBlur(msgField);
                if (_presetMode)
                    generalSection.Add(BuildPresetTextStyleRow("Message",
                        "each box keeps its own message text",
                        () => helpBoxNode.MessageTextStyle, v => helpBoxNode.MessageTextStyle = v, "message"));
                else
                    generalSection.Add(Identity(WithTextButton(msgField,
                        () => helpBoxNode.MessageTextStyle, v => helpBoxNode.MessageTextStyle = v, "message",
                        RichTextFormattingHelp)));

                var typeField = new EnumField("Message Type", helpBoxNode.MessageType);
                typeField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change HelpBox Type");
                    helpBoxNode.MessageType = (HelpBoxMessageType)evt.newValue;
                    OnModification();
                    RefreshPreview();
                    // Deferred so the dropdown closes before the rebuild; an unset Summary Text row shows
                    // the "{MessageType} Details" default, which just changed.
                    rootVisualElement.schedule.Execute(RefreshProperties).ExecuteLater(1);
                });
                generalSection.Add(typeField);

                var markdownToggle = new Toggle("Render Markdown");
                markdownToggle.value = helpBoxNode.RenderMarkdown;
                markdownToggle.tooltip =
                    "Render the message as lightweight markdown — **bold**, *italics*, `code`, {Color|text}, " +
                    "[links](https://…) — plus Unity rich text tags (<b>, <color=…>, <size=…>, …). " +
                    "Turn off to show the text exactly as typed.";
                markdownToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle HelpBox Render Markdown");
                    helpBoxNode.RenderMarkdown = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(markdownToggle);

                var isExpandableToggle = new Toggle("Expandable");
                isExpandableToggle.value = helpBoxNode.Expandable;

                var expandSettingsContainer = new VisualElement();
                expandSettingsContainer.style.display = helpBoxNode.Expandable ? DisplayStyle.Flex : DisplayStyle.None;

                var startExpandedToggle = new Toggle("Default to Open");
                startExpandedToggle.value = helpBoxNode.DefaultToOpen;
                startExpandedToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle HelpBox Default to Open");
                    helpBoxNode.DefaultToOpen = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                expandSettingsContainer.Add(startExpandedToggle);

                var collapsedStyleField = new EnumField("Collapsed As", helpBoxNode.CollapsedStyle);
                collapsedStyleField.tooltip = "How the collapsed state looks: Summary Line = a one-line summary + chevron; Chip = a compact round \"?\" reveal chip (like the Project Settings help chips).";

                // Chip alignment — only meaningful (and shown) for the Chip collapsed style.
                var chipAlignRow = BuildImageAlignmentRow("Chip Alignment",
                    () => helpBoxNode.ChipAlignment, v => helpBoxNode.ChipAlignment = v, "Change Chip Alignment");
                chipAlignRow.style.display = helpBoxNode.CollapsedStyle == HelpBoxCollapsedStyle.Chip ? DisplayStyle.Flex : DisplayStyle.None;

                collapsedStyleField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change HelpBox Collapsed Style");
                    var style = (HelpBoxCollapsedStyle)evt.newValue;
                    helpBoxNode.CollapsedStyle = style;
                    // Summary Text only for Summary Line; Chip Alignment only for Chip.
                    summaryWrapper.style.display = style == HelpBoxCollapsedStyle.SummaryLine ? DisplayStyle.Flex : DisplayStyle.None;
                    chipAlignRow.style.display = style == HelpBoxCollapsedStyle.Chip ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                    RefreshPreview();
                });
                expandSettingsContainer.Add(collapsedStyleField);
                expandSettingsContainer.Add(summaryWrapper); // Summary Text sits below "Expandable"
                expandSettingsContainer.Add(chipAlignRow);

                isExpandableToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle HelpBox Expandable");
                    helpBoxNode.Expandable = evt.newValue;
                    // The whole expand block (including Summary Text + Chip Alignment) shows only when expandable;
                    // the inner rows keep their own collapsed-style gating.
                    expandSettingsContainer.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                    RefreshPreview();
                });

                generalSection.Add(isExpandableToggle);
                generalSection.Add(expandSettingsContainer);
            }
            else if (_selectedNode is SpaceNode spaceNode)
            {
                // Attribute-owned spaces mirror a code [Space] and are locked — surface that here so the greyed
                // "can't delete" behaviour reads as intentional, and point at the real lever (the attribute).
                if (spaceNode.IsAttributeOwned)
                {
                    generalSection.Add(new HelpBox(
                        $"This space comes from a [Space] attribute on “{ValidationFieldLabel(null, spaceNode.OwnerFieldPath)}” in " +
                        "your script, so it can't be deleted here — remove the [Space] in code and it disappears " +
                        "automatically. You can still fine-tune its size and direction below.",
                        HelpBoxMessageType.Info));
                }

                // Flexible toggle up top; the fixed-size controls (Direction + pixels) sit below it and hide
                // when Flexible is on (a flex-grow space fills the parent's main axis, so neither applies).
                var flexToggle = new Toggle("Flexible");
                flexToggle.value = spaceNode.Flexible;
                flexToggle.tooltip = "Fill all leftover room instead of a fixed size (like GUILayout.FlexibleSpace). " +
                    "Most useful in a Columns row or a fixed-height container — it pushes siblings apart.";

                var fixedOptions = new VisualElement();
                fixedOptions.style.display = spaceNode.Flexible ? DisplayStyle.None : DisplayStyle.Flex;

                var directionField = new EnumField("Direction", spaceNode.Axis);
                directionField.tooltip = "Vertical = a gap between stacked (Rows) items; Horizontal = a gap between " +
                    "side-by-side (Columns/Grid) items. The drag grip follows this: bottom edge for Vertical, right for Horizontal.";
                directionField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Space Direction");
                    spaceNode.Axis = (SpaceAxis)evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                // Direction is deliberately absent from SpaceTransfers: it's CONTEXT, not styling (a gap is
                // Vertical inside Rows and Horizontal inside Columns, decided by where the space is dropped),
                // so a preset must not pin it — and the Preset Editor must not pretend it can.
                if (!_presetMode) fixedOptions.Add(directionField);

                var pxField = new FloatField("Space (px)");
                pxField.value = spaceNode.SpaceAmount;
                // NOT delayed: fire per tick while the value scrubs so the canvas placeholder resizes LIVE, the
                // same best-of-both-worlds pattern as Divider Thickness / Text Block Padding — one coalesced undo
                // record + one debounced commit land on release, but every tick live-rebuilds just this node in
                // place for instant feedback. (It was isDelayed=true, which is why the gap only updated on mouse-up.)
                pxField.tooltip = "Exact size of the gap in pixels. You can also drag the grip on the placeholder's edge.";
                pxField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Space Size", () =>
                    {
                        spaceNode.SpaceAmount = evt.newValue;                     // setter clamps to [0..800]
                    }, liveRebuild: true);
                });
                FlushValueEditOnBlur(pxField);
                SyncClampedDisplay(pxField, () => spaceNode.SpaceAmount); // show the clamp, not mid-keystroke
                fixedOptions.Add(pxField);

                flexToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Space Flexible");
                    spaceNode.Flexible = evt.newValue;
                    fixedOptions.style.display = evt.newValue ? DisplayStyle.None : DisplayStyle.Flex;
                    OnModification();
                    RefreshPreview();
                });

                generalSection.Add(flexToggle);
                generalSection.Add(fixedOptions);
            }
            else if (_selectedNode is TextBlockNode textBlockNode)
            {
                var textField = new TextField("Text") { value = textBlockNode.Text };
                // Wrapping + drag-to-resize text area (like the Info/Warning message).
                TextAreaHelper.MakeWrappingResizableTextArea(textField);
                textField.tooltip = "The text to display. Rendered as markdown (**bold**, *italics*, `code`, {Color|text}, [links](https://…)) plus Unity rich text tags (‹b›, ‹color=…›, ‹size=…›, …) when Render Markdown is on. The T button styles font/size/color/alignment.";
                textField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change Text Block", () => textBlockNode.Text = evt.newValue,
                        liveRebuild: true));
                FlushTextEditOnBlur(textField);
                // "T" text-styling button, like every other editable-text row in the designer. In the Preset
                // Editor the T is all that's left: TextBlockTransfers carries TextStyle, never the text.
                if (_presetMode)
                    generalSection.Add(BuildPresetTextStyleRow("Text",
                        "each text block keeps its own text",
                        () => textBlockNode.TextStyle, v => textBlockNode.TextStyle = v, "textblock"));
                else
                    generalSection.Add(Identity(WithTextButton(textField,
                        () => textBlockNode.TextStyle, v => textBlockNode.TextStyle = v, "textblock",
                        RichTextFormattingHelp)));

                var mdToggle = new Toggle("Render Markdown") { value = textBlockNode.RenderMarkdown };
                mdToggle.tooltip = "Render the text as lightweight markdown (bold/italics/code/links) plus Unity rich text tags (‹b›, ‹color=…›, ‹size=…›, …). Turn off to show it exactly as typed.";
                mdToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Text Block Markdown");
                    textBlockNode.RenderMarkdown = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(mdToggle);

                // Background / padding / rounding / max-width live in the "Display Style/Options" section.
                var tbStyle = CreateFoldoutHeader("Display Style/Options");

                // Padding + Corner Radius only take effect on the background CARD — the builder applies them inside
                // `if (BackgroundColor.isOverridden)` (rounding has nothing to round, and inner padding no box to
                // inset, without a fill). So gate their controls on a background being set, the same way Chip
                // Alignment / Crop Alpha gate on their prerequisite — no more sliders that silently do nothing.
                var cardOptions = new VisualElement();
                void SyncCardOptionsVisible() =>
                    cardOptions.style.display = textBlockNode.BackgroundColor.isOverridden ? DisplayStyle.Flex : DisplayStyle.None;

                var bgRow = CreateOverridableColorElement("Background",
                    () => textBlockNode.BackgroundColor, v => textBlockNode.BackgroundColor = v,
                    () => { RefreshPreview(); SyncCardOptionsVisible(); }); // covers the debounced commit + the ↺ reset
                // The helper's onValueChanged only lands at the debounced COMMIT (mouse-up). Register a second,
                // per-tick change callback on the ColorField itself so the card options appear the INSTANT a color
                // is picked while the HSV picker is still held — the same live feedback the canvas background gets.
                // (Registered AFTER the helper's own callback, so isOverridden is already true when this reads it;
                // the ↺ reset uses SetValueWithoutNotify so it won't fire here — the onValueChanged path hides it.)
                bgRow.Q<ColorField>()?.RegisterValueChangedCallback(_ => SyncCardOptionsVisible());
                tbStyle.Add(bgRow);

                var padSlider = new Slider("Padding", 0f, 40f) { value = textBlockNode.Padding, showInputField = true };
                padSlider.tooltip = "Inner padding in pixels between the text and the background card's edges.";
                padSlider.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Text Block Padding", () =>
                    {
                        textBlockNode.Padding = evt.newValue;                    // setter clamps
                    }, liveRebuild: true);
                });
                FlushValueEditOnBlur(padSlider);
                SyncClampedDisplay(padSlider, () => textBlockNode.Padding);
                cardOptions.Add(padSlider);

                var tbRound = new Slider("Corner Radius", 0f, TextBlockNode.MaxCornerRadius) { value = textBlockNode.CornerRadius, showInputField = true };
                tbRound.tooltip = "Round the background card's corners, in pixels.";
                tbRound.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Text Block Rounding", () =>
                    {
                        textBlockNode.CornerRadius = evt.newValue;                    // setter clamps
                    }, liveRebuild: true);
                });
                FlushValueEditOnBlur(tbRound);
                SyncClampedDisplay(tbRound, () => textBlockNode.CornerRadius);
                cardOptions.Add(tbRound);

                SyncCardOptionsVisible(); // match the current background state on first build
                tbStyle.Add(cardOptions);

                // Max Width re-caps the block on the canvas — routed through the shared resettable-number helper
                // (like the gold-standard progress-bar Height), so it previews live per keystroke / label-scrub with
                // one coalesced undo + save per burst AND gets the standard ↺ reset-to-default (0 = fill the
                // inspector) button + right-click reset. No liveApply → the helper falls back to an exact in-place
                // canvas rebuild each tick; the >= 0 clamp never fights typing (only a typed negative snaps to 0).
                var maxWidthField = new FloatField("Max Width") { value = textBlockNode.MaxWidth };
                maxWidthField.tooltip = "Maximum text width in pixels (0 = fill the inspector).";
                tbStyle.Add(CreateResettableNumberField<float>(
                    maxWidthField, 0f,
                    () => textBlockNode.MaxWidth,
                    v => textBlockNode.MaxWidth = v,
                    v => Mathf.Max(0f, v),
                    "Change Text Block Max Width"));

                displayStyleSection = tbStyle;
            }
            else if (_selectedNode is LabeledDividerNode dividerNode)
            {
                var titleField = new TextField("Title") { value = dividerNode.Title };
                titleField.tooltip = "Optional caption; leave empty for a plain rule. The T button's alignment places it left / center / right along the rule.";
                // Live caption: the rule's label updates on the canvas as you type (debounce still owns undo/save).
                titleField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change Divider Title", () => dividerNode.Title = evt.newValue,
                        refreshHierarchy: true, liveRebuild: true));
                FlushTextEditOnBlur(titleField);
                // "T" text-styling button, like every other editable-caption row in the designer. Styling-only in
                // the Preset Editor — LabeledDividerTransfers carries TitleTextStyle, never the caption itself.
                if (_presetMode)
                    generalSection.Add(BuildPresetTextStyleRow("Title",
                        "each divider keeps its own caption",
                        () => dividerNode.TitleTextStyle, v => dividerNode.TitleTextStyle = v, "title"));
                else
                    generalSection.Add(Identity(WithTextButton(titleField,
                        () => dividerNode.TitleTextStyle, v => dividerNode.TitleTextStyle = v, "title")));

                // Thickness / Corner Radius / Line Color live in their OWN "Display Style/Options" section
                // (systematic with bindings), not General Settings. Assigned to displayStyleSection, which the
                // panel adds directly above Appearance.
                var dividerStyleSection = CreateFoldoutHeader("Display Style/Options");

                // Thickness as a range slider (1-12) with a numeric field, instead of a bare empty number box.
                var thicknessSlider = new Slider("Thickness", LabeledDividerNode.MinThickness, LabeledDividerNode.MaxThickness)
                {
                    value = dividerNode.Thickness,
                    showInputField = true,
                };
                thicknessSlider.tooltip = "Rule thickness in pixels (1-12).";
                thicknessSlider.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Divider Thickness", () =>
                    {
                        dividerNode.Thickness = evt.newValue;                        // setter clamps
                    }, liveRebuild: true);
                });
                FlushValueEditOnBlur(thicknessSlider);
                SyncClampedDisplay(thicknessSlider, () => dividerNode.Thickness);     // reflect the clamp
                dividerStyleSection.Add(thicknessSlider);

                // Corner rounding (0 = square ends) so the rule can be a rounded pill.
                var roundingSlider = new Slider("Corner Radius", 0f, LabeledDividerNode.MaxCornerRadius)
                {
                    value = dividerNode.CornerRadius,
                    showInputField = true,
                };
                roundingSlider.tooltip = "Round the ends of the rule, in pixels (0 = square).";
                roundingSlider.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Divider Corner Radius", () =>
                    {
                        dividerNode.CornerRadius = evt.newValue;                        // setter clamps
                    }, liveRebuild: true);
                });
                FlushValueEditOnBlur(roundingSlider);
                SyncClampedDisplay(roundingSlider, () => dividerNode.CornerRadius);     // reflect the clamp
                dividerStyleSection.Add(roundingSlider);

                dividerStyleSection.Add(CreateOverridableColorElement("Line Color",
                    () => dividerNode.LineColor, v => dividerNode.LineColor = v, RefreshPreview));

                displayStyleSection = dividerStyleSection;
            }
            else if (_selectedNode is ImageBannerNode bannerNode)
            {
                var texField = new ObjectField("Image") { objectType = typeof(Texture2D), allowSceneObjects = false };
                texField.tooltip = "The texture to display. Stored by GUID so it survives asset moves/renames.";
                if (!string.IsNullOrEmpty(bannerNode.TextureGuid))
                {
                    var p = AssetDatabase.GUIDToAssetPath(bannerNode.TextureGuid);
                    if (!string.IsNullOrEmpty(p)) texField.SetValueWithoutNotify(AssetDatabase.LoadAssetAtPath<Texture2D>(p));
                }
                texField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Banner Image");
                    string guid = "";
                    if (evt.newValue != null)
                    {
                        var p = AssetDatabase.GetAssetPath(evt.newValue);
                        if (!string.IsNullOrEmpty(p)) guid = AssetDatabase.AssetPathToGUID(p);
                    }
                    bannerNode.TextureGuid = guid;
                    OnModification();
                    RefreshPreview();
                });
                // The texture is the one thing an Image widget preset can't carry (it's the content); everything
                // about how it's PRESENTED — alignment, scale mode, height, zoom, crop — does travel.
                if (!_presetMode) generalSection.Add(Identity(texField));

                // ImageBannerAlignment shares Left/Center/Right ordering with ImageAlignment → map via int so
                // the banner reuses the shared 3-button alignment row.
                generalSection.Add(BuildImageAlignmentRow("Alignment",
                    () => (ImageAlignment)(int)bannerNode.Alignment,
                    v => bannerNode.Alignment = (ImageBannerAlignment)(int)v,
                    "Change Banner Alignment", defaultValue: ImageAlignment.Center));

                // Scale Mode: only Fit / Stretch are offered — the old "Scale & Crop" no longer earns its place
                // (Fit + Zoom + Crop Alpha cover the crop use case). The enum value is kept for back-compat; a
                // legacy Scale-&-Crop layout shows as "Fit" and becomes Fit the moment this is touched.
                Toggle cropAlphaToggle = null; // declared early so the scale-mode callback can toggle its visibility
                var scaleChoices = new List<string> { "Fit", "Stretch" };
                string scaleInitial = bannerNode.ScaleMode == ImageBannerScaleMode.StretchToFill ? "Stretch" : "Fit";
                var scaleField = new DropdownField("Scale Mode", scaleChoices, scaleInitial);
                scaleField.tooltip = "Fit = preserve aspect (honors Alignment; combine with Zoom / Crop Alpha to crop); Stretch = fill the box exactly.";
                scaleField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Banner Scale Mode");
                    var mode = evt.newValue == "Stretch" ? ImageBannerScaleMode.StretchToFill : ImageBannerScaleMode.ScaleToFit;
                    bannerNode.ScaleMode = mode;
                    if (cropAlphaToggle != null)
                        cropAlphaToggle.style.display = mode == ImageBannerScaleMode.ScaleToFit ? DisplayStyle.Flex : DisplayStyle.None;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(scaleField);

                // Height drives the banner box on the canvas — preview it live per keystroke / label-scrub like the
                // gold-standard progress-bar Height, while the undo record + save coalesce into one per burst.
                // Non-delayed so the drag/typing fires ticks instead of only committing on Enter.
                var heightField = new FloatField("Height") { value = bannerNode.Height };
                heightField.tooltip = "Banner height in pixels (8-800).";
                heightField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Banner Height",
                        () => bannerNode.Height = evt.newValue,            // setter clamps to [8..800]
                        liveRebuild: true);                                // exact in-place canvas rebuild each tick
                });
                // Reflect the [8..800] clamp only when the edit settles, so mid-typing "120" isn't fought by the
                // min snapping the caret to "8" on the first keystroke.
                heightField.RegisterCallback<FocusOutEvent>(_ => heightField.SetValueWithoutNotify(bannerNode.Height));
                FlushValueEditOnBlur(heightField);
                generalSection.Add(heightField);

                var zoomField = new Slider("Zoom", ImageBannerNode.MinZoom, ImageBannerNode.MaxZoom) { value = bannerNode.Zoom, showInputField = true };
                zoomField.tooltip = "Uniform zoom on top of the scale mode (1 = unchanged). Above 1 enlarges the image and crops it to the box; applies to all scale modes.";
                zoomField.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Change Banner Zoom", () =>
                    {
                        bannerNode.Zoom = evt.newValue;                    // setter clamps
                        LivePokeCanvasElement(bannerNode, el =>
                        {
                            var img = el.Q<Image>();
                            if (img != null) img.style.scale = new Scale(new Vector2(bannerNode.Zoom, bannerNode.Zoom));
                        });
                    });
                });
                FlushValueEditOnBlur(zoomField);
                SyncClampedDisplay(zoomField, () => bannerNode.Zoom); // reflect the clamp, not mid-keystroke
                generalSection.Add(zoomField);

                cropAlphaToggle = new Toggle("Crop Alpha") { value = bannerNode.CropAlpha };
                cropAlphaToggle.tooltip = "Tighten the fit to the image's opaque (non-transparent) region so transparent margins don't waste space. Only applies to the Fit scale mode.";
                cropAlphaToggle.style.display = bannerNode.ScaleMode == ImageBannerScaleMode.ScaleToFit ? DisplayStyle.Flex : DisplayStyle.None;
                cropAlphaToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Banner Crop Alpha");
                    bannerNode.CropAlpha = evt.newValue;
                    OnModification();
                    RefreshPreview();
                });
                generalSection.Add(cropAlphaToggle);
            }
            else if (_selectedNode is EmbeddedEditorNode embeddedNode)
            {
                var targetType = ResolveTargetType();
                var genuineType = targetType != null ? SasquatchGeneratedEditors.GetGenuinePerTypeEditor(targetType) : null;

                if (genuineType == null)
                {
                    var noEd = new HelpBox(
                        targetType == null
                            ? "Select a target type first. This node re-inlines a type's OWN custom editor."
                            : $"'{targetType.Name}' has no [CustomEditor], so nothing will render here. This node re-inlines a type's own editor (whole, or a [SasquatchEmbed] slice).",
                        HelpBoxMessageType.Info);
                    generalSection.Add(noEd);
                }
                else
                {
                    var slices = EmbeddedEditorHost.DiscoverSlices(genuineType);
                    var choices = new List<string> { "Entire Editor" };
                    foreach (var s in slices) choices.Add(s.display);

                    int current = 0;
                    if (!string.IsNullOrEmpty(embeddedNode.SliceMethodName))
                    {
                        int found = slices.FindIndex(s => s.method == embeddedNode.SliceMethodName);
                        current = found >= 0 ? found + 1 : 0;
                    }

                    var sliceField = new DropdownField("Show", choices, current);
                    sliceField.tooltip = "Embed the whole editor, or just one [SasquatchEmbed]-tagged slice of it.";
                    sliceField.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Embedded Editor Slice");
                        int idx = choices.IndexOf(evt.newValue);
                        embeddedNode.SliceMethodName = (idx <= 0 || idx - 1 >= slices.Count) ? "" : slices[idx - 1].method;
                        OnModification();
                        RefreshPreview();
                    });
                    generalSection.Add(Identity(sliceField));

                    // The message adapts to whether force-takeover is already ON for this type: when it is, the
                    // "turn ON force-takeover" step is done, so confirm rather than nag about a step already
                    // taken. IsForceTakeoverOwn reads the type's OWN saved layout flag.
                    bool takingOver = LayoutRegistry.IsForceTakeoverOwn(targetType);
                    generalSection.Add(new HelpBox(
                        takingOver
                            ? $"Re-inlines {genuineType.Name}. Force-takeover is ON for this type, so this node draws in place of its own editor (the displaced editor keeps its OnSceneGUI). One editor instance is created per embed."
                            : $"Re-inlines {genuineType.Name}. The marquee workflow: turn ON force-takeover to displace this type's editor, then drop this node to re-embed just the part you liked (the displaced editor keeps its OnSceneGUI). One editor instance is created per embed.",
                        HelpBoxMessageType.Info));
                }
            }
#if SASQ_CUSTOM_WIDGET
            else if (_selectedNode is CustomWidgetNode cwNode)
            {
                // Standalone Custom Widget: pick/author the asset, then map EACH input (primary included) to a
                // property on the target. Unmapped inputs fall back to the widget's defaults, so it renders at once.
                string GetNodeInputMap(string inputName)
                {
                    if (cwNode.CustomWidgetInputs == null) return "";
                    foreach (var m in cwNode.CustomWidgetInputs)
                        if (m.InputName == inputName) return m.PropertyPath ?? "";
                    return "";
                }
                void SetNodeInputMap(string inputName, string path)
                {
                    cwNode.CustomWidgetInputs ??= new List<CustomWidgetInputMap>();
                    for (int i = 0; i < cwNode.CustomWidgetInputs.Count; i++)
                    {
                        if (cwNode.CustomWidgetInputs[i].InputName == inputName)
                        {
                            if (string.IsNullOrEmpty(path)) { cwNode.CustomWidgetInputs.RemoveAt(i); return; }
                            cwNode.CustomWidgetInputs[i] = new CustomWidgetInputMap(inputName, path);
                            return;
                        }
                    }
                    if (!string.IsNullOrEmpty(path)) cwNode.CustomWidgetInputs.Add(new CustomWidgetInputMap(inputName, path));
                }

                var cwAssetField = new ObjectField("Widget Asset")
                {
                    objectType = typeof(SasquatchCustomWidget),
                    allowSceneObjects = false,
                    value = CustomWidgetLibrary.Resolve(cwNode.CustomWidgetGuid)
                };
                cwAssetField.tooltip = "The custom widget this element renders. Click New… to author one in the Widget Studio (no data needed), then map its inputs to fields below.";
                generalSection.Add(cwAssetField);

                // The input MAP names property paths on one specific target type — PropertyPath by another name.
                var cwInputsContainer = Identity(new VisualElement());
                cwInputsContainer.style.marginLeft = 14;
                cwInputsContainer.style.marginTop = 4;

                Action rebuildCwNodeRows = null;
                rebuildCwNodeRows = () =>
                {
                    cwInputsContainer.Clear();
                    var cw = CustomWidgetLibrary.Resolve(cwNode.CustomWidgetGuid);
                    if (cw == null)
                    {
                        cwInputsContainer.Add(new HelpBox("Pick a widget asset above, or click New… to author one. Then map its inputs to fields here.", HelpBoxMessageType.Info));
                        return;
                    }
                    if (cw.Inputs == null || cw.Inputs.Count == 0)
                    {
                        cwInputsContainer.Add(new HelpBox("This widget has no inputs yet — add some in the Widget Studio's Data panel.", HelpBoxMessageType.Info));
                        return;
                    }
                    cwInputsContainer.Add(new Label("Map inputs → fields") { style = { unityFontStyleAndWeight = FontStyle.Bold, marginBottom = 2 } });
                    var primaryInp = cw.PrimaryInput;
                    foreach (var inp in cw.Inputs)
                    {
                        if (inp == null || string.IsNullOrEmpty(inp.Name)) continue;
                        var inpRef = inp;
                        string rowLabel = inp == primaryInp ? $"★ {inp.Name}" : inp.Name;
                        var mapField = new TextField(rowLabel) { value = GetNodeInputMap(inp.Name) };
                        mapField.tooltip = $"Property feeding the '{inp.Name}' input ({inp.Kind}){(inp == primaryInp ? " — the primary input" : "")}. Blank = use the widget's default.";
                        mapField.RegisterValueChangedCallback(evt =>
                            HandleDebouncedTextEdit("Map Custom Widget Input", () => SetNodeInputMap(inpRef.Name, evt.newValue)));
                        FlushTextEditOnBlur(mapField);
                        AutocompleteTextField.Attach(mapField, () =>
                        {
                            var targetType = ResolveTargetType();
                            if (targetType == null) return Array.Empty<string>();
                            var all = SasquatchReflectionUtility.GetSerializableProperties(targetType);
                            var collPrefixes = all.Where(p => p.isCollection).Select(p => p.path + ".").ToList();
                            return all.Where(p => !p.isCollection && !collPrefixes.Any(cp => p.path.StartsWith(cp))).Select(p => p.path);
                        }, s => FieldPathSnippet(s.Value));
                        cwInputsContainer.Add(mapField);
                    }
                };

                cwAssetField.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Assign Custom Widget");
                    var wobj = evt.newValue as SasquatchCustomWidget;
                    cwNode.CustomWidgetGuid = wobj != null ? CustomWidgetLibrary.GuidOf(wobj) : "";
                    rebuildCwNodeRows();
                    OnModification();
                    RefreshPreview();
                });

                generalSection.Add(cwInputsContainer);
                rebuildCwNodeRows();

                // New (author in the Studio) / Edit — same buttons the field-level custom widget uses.
                CustomWidgetComposerHooks.AttachDesignerButtons(generalSection,
                    () => cwNode.CustomWidgetGuid,
                    g => { cwNode.CustomWidgetGuid = g; },
                    cwAssetField, rebuildCwNodeRows,
                    () => { OnModification(); RefreshPreview(); });
            }
#endif

            _propertiesContainer.Add(generalSection);

            // ── Tab Organizer (Tabs container only) — kanban for moving items between tabs ──────────
            if (tabOrganizerSection != null)
            {
                _propertiesContainer.Add(tabOrganizerSection);
            }

            // ── Type-contributed sections (a collection's Rows / Search, Sort & Paging / …) ───────────
            if (extraSections != null)
            {
                foreach (var extra in extraSections)
                {
                    _propertiesContainer.Add(extra);
                }
            }

            // ── Display Style/Options (bindings only) — its own section, directly above Appearance ───
            if (displayStyleSection != null)
            {
                _propertiesContainer.Add(displayStyleSection);
            }

            // ── Prefix & Suffix (bindings only) ──────────────────────────────────────────────────
            // Deliberately OUTSIDE displayStyleFoldout: affixes apply to every Display Type, so this section
            // must not join the per-kind show/hide sweep that runs when the user switches widget kind.
            if (_selectedNode is BindingNode affixNode)
            {
                var affixSection = BuildAffixSection(affixNode);
                if (affixSection != null) _propertiesContainer.Add(affixSection);
            }

            // ── Appearance (Colors & Borders now; Text is added in a later pass) ─────────────────
            // Promoted above Advanced Styling — these are the most-reached-for "make it look right" controls.
            var appearanceFoldout = new Foldout();
            appearanceFoldout.text = "Appearance";
            appearanceFoldout.value = _appearanceExpanded;
            appearanceFoldout.style.marginTop = 10;
            appearanceFoldout.style.unityFontStyleAndWeight = FontStyle.Bold;
            // Register on the foldout's OWN toggle (not the foldout) so child bool toggles inside the content —
            // whose ChangeEvent<bool> also bubbles up — aren't mistaken for the foldout's expand state.
            appearanceFoldout.Q<Toggle>()?.RegisterValueChangedCallback(evt => _appearanceExpanded = evt.newValue);
            SasquatchIcons.SkinFoldout(appearanceFoldout);

            var colorsSection = CreateFoldoutHeader("Colors & Borders");
            // Hidden — not removed — while the node renders as the opaque .sasq-group shell: the row has to be
            // able to come BACK the moment "Expandable" is switched off, and that toggle doesn't rebuild this
            // panel. A collapsible container's working equivalent is Section Tint, which paints the header and
            // body themselves; a collection has no equivalent, but with Expandable off its frame paints nothing
            // and this row works as-is. (Border/Width/Radius all still land on the shell, so they stay.)
            var backgroundColorRow = CreateOverridableColorElement("Background Color", () => _selectedNode.Style.backgroundColor, val => { var s = _selectedNode.Style; s.backgroundColor = val; _selectedNode.Style = s; }, RefreshPreview, liveApply: () => StyleLivePoke(_selectedNode));
            colorsSection.Add(backgroundColorRow);
            syncGroupShellGatedRows = () =>
                backgroundColorRow.style.display = LayoutTreeBuilder.RendersAsOpaqueGroupShell(_selectedNode)
                    ? DisplayStyle.None
                    : DisplayStyle.Flex;
            syncGroupShellGatedRows();
            colorsSection.Add(CreateOverridableColorElement("Border Color", () => _selectedNode.Style.borderColor, val => { var s = _selectedNode.Style; s.borderColor = val; _selectedNode.Style = s; }, RefreshPreview, liveApply: () => StyleLivePoke(_selectedNode)));
            colorsSection.Add(CreateOverridableFloatElement("Border Width", () => _selectedNode.Style.borderWidth, val => { var s = _selectedNode.Style; s.borderWidth = val; _selectedNode.Style = s; }, RefreshPreview, liveApply: () => StyleLivePoke(_selectedNode)));
            // Circle/Pill frames derive their radius from the resolved size on every geometry pass (a
            // circle can't get any rounder), so the row would be a dead control — skip it for those
            // shapes. The panel rebuilds on a shape change, so this re-derives automatically.
            bool radiusIsShapeDerived = _selectedNode is ContainerNode radiusFrameNode
                && radiusFrameNode.Type == ContainerType.Frame
                && (radiusFrameNode.Frame.Shape == FrameShape.Circle || radiusFrameNode.Frame.Shape == FrameShape.Pill);
            if (!radiusIsShapeDerived)
                // "Box" Corner Radius: this rounds the node's OUTER background/border box (Style.borderRadius),
                // sibling to the Background/Border rows above it. Named distinctly from the widget-level
                // "Corner Radius" in Display Style/Options (DisplayStyleData.cornerRadius, which rounds a
                // widget's inner chrome) — and from a Button/HelpBox/etc.'s own radius — so both can coexist
                // without reading as a duplicate.
                colorsSection.Add(CreateOverridableFloatElement("Box Corner Radius", () => _selectedNode.Style.borderRadius, val => { var s = _selectedNode.Style; s.borderRadius = val; _selectedNode.Style = s; }, RefreshPreview, liveApply: () => StyleLivePoke(_selectedNode)));
            appearanceFoldout.Add(colorsSection);

            _propertiesContainer.Add(appearanceFoldout);

            // Field Styling — the binding's VALUE text + the input box background. Gated off for Toggle (no text box).
            // Min-Max is a special case: its value text is styled through MinMaxLabelTextStyle. While the read-outs are
            // plain labels, the "T" on the Show Min/Max Values row owns that; once "Editable Values" makes them number
            // FIELDS, the T hides and this section takes over — driving the SAME MinMaxLabelTextStyle so the styling
            // survives toggling Editable on/off. (Min-Max skips the Field Background row: its value fields sit outside
            // the widget's own input box, so a bg override can't reach them.) Text/bg are best-effort (Unity-internal input).
            if (_selectedNode is BindingNode fieldStyleNode && fieldStyleNode.DisplayType != DisplayType.Toggle)
            {
                bool isMinMaxField = fieldStyleNode.DisplayType == DisplayType.MinMaxSlider;
                bool showFieldStyling = !isMinMaxField
                    || (!fieldStyleNode.DisplayStyleData.minMaxHideValues && !fieldStyleNode.DisplayStyleData.minMaxReadOnlyValues);
                if (showFieldStyling)
                {
                    var fieldStyling = new Foldout();
                    fieldStyling.text = "Field Styling";
                    fieldStyling.value = _fieldStylingExpanded;
                    fieldStyling.style.marginTop = 4;
                    fieldStyling.style.unityFontStyleAndWeight = FontStyle.Bold;
                    fieldStyling.Q<Toggle>()?.RegisterValueChangedCallback(evt => _fieldStylingExpanded = evt.newValue);
                    SasquatchIcons.SkinFoldout(fieldStyling);

                    if (isMinMaxField)
                    {
                        fieldStyling.Add(BuildTextStylePanel(
                            () => ((BindingNode)_selectedNode).MinMaxLabelTextStyle,
                            v => { var n = (BindingNode)_selectedNode; n.MinMaxLabelTextStyle = v; },
                            RefreshPreview));
                    }
                    else
                    {
                        fieldStyling.Add(BuildTextStylePanel(
                            () => ((BindingNode)_selectedNode).FieldTextStyle,
                            v => { var n = (BindingNode)_selectedNode; n.FieldTextStyle = v; },
                            RefreshPreview));
                        fieldStyling.Add(CreateOverridableColorElement("Field Background",
                            () => ((BindingNode)_selectedNode).FieldBackground,
                            v => { var n = (BindingNode)_selectedNode; n.FieldBackground = v; },
                            RefreshPreview, liveApply: () => LivePokeFieldBackground((BindingNode)_selectedNode)));
                    }
                    _propertiesContainer.Add(fieldStyling);
                }
            }

            // ── Advanced Styling (layout only now: alignment, spacing, sizing) ──────────────────
            // Cut from the old panel: Flex Direction / Align Items / Justify Content / Flex Grow / Flex
            // Shrink — flexbox jargon made redundant by container Kind + the alignment/resize systems. The
            // fields stay on LayoutStyle (still applied by StyleApplier) so existing layouts are unchanged.
            var advFoldout = new Foldout();
            advFoldout.text = "Advanced Styling";
            advFoldout.value = _advancedStylingExpanded;
            advFoldout.style.marginTop = 10;
            advFoldout.style.unityFontStyleAndWeight = FontStyle.Bold;
            // Register on the foldout's OWN toggle (see Appearance above).
            advFoldout.Q<Toggle>()?.RegisterValueChangedCallback(evt => _advancedStylingExpanded = evt.newValue);
            SasquatchIcons.SkinFoldout(advFoldout);

            // Align in Parent — friendly Left/Center/Right/Stretch reframe of the raw "Align Self" enum.
            var alignInParent = CreateAlignInParentControl();
            alignInParent.style.marginLeft = 15; // refined to the measured value below once layout runs
            advFoldout.Add(alignInParent);

            var spacingSection = CreateFoldoutHeader("Spacing (Margins & Paddings)");

            // Indent "Align in Parent" to line up exactly with the Spacing foldout's label. The
            // checkmark-column width isn't a stable constant across editor versions, so measure
            // the label's real x once layout has produced it.
            var spacingLabel = spacingSection.Q<Label>(className: "unity-foldout__text")
                            ?? spacingSection.Q<Toggle>()?.Q<Label>();
            spacingLabel?.RegisterCallback<GeometryChangedEvent>(_ =>
            {
                float left = spacingLabel.ChangeCoordinatesTo(advFoldout.contentContainer, Vector2.zero).x;
                if (left > 0f) alignInParent.style.marginLeft = left;
            });
            spacingSection.Add(CreateSpacingControl("Margin", new (string, Func<OverridableFloat>, Action<OverridableFloat>)[]
            {
                ("Top",    () => _selectedNode.Style.marginTop,    val => { var s = _selectedNode.Style; s.marginTop = val; _selectedNode.Style = s; }),
                ("Right",  () => _selectedNode.Style.marginRight,  val => { var s = _selectedNode.Style; s.marginRight = val; _selectedNode.Style = s; }),
                ("Bottom", () => _selectedNode.Style.marginBottom, val => { var s = _selectedNode.Style; s.marginBottom = val; _selectedNode.Style = s; }),
                ("Left",   () => _selectedNode.Style.marginLeft,   val => { var s = _selectedNode.Style; s.marginLeft = val; _selectedNode.Style = s; }),
            }, RefreshPreview, liveApply: () => StyleLivePoke(_selectedNode)));
            spacingSection.Add(CreateSpacingControl("Padding", new (string, Func<OverridableFloat>, Action<OverridableFloat>)[]
            {
                ("Top",    () => _selectedNode.Style.paddingTop,    val => { var s = _selectedNode.Style; s.paddingTop = val; _selectedNode.Style = s; }),
                ("Right",  () => _selectedNode.Style.paddingRight,  val => { var s = _selectedNode.Style; s.paddingRight = val; _selectedNode.Style = s; }),
                ("Bottom", () => _selectedNode.Style.paddingBottom, val => { var s = _selectedNode.Style; s.paddingBottom = val; _selectedNode.Style = s; }),
                ("Left",   () => _selectedNode.Style.paddingLeft,   val => { var s = _selectedNode.Style; s.paddingLeft = val; _selectedNode.Style = s; }),
            }, RefreshPreview, liveApply: () => StyleLivePoke(_selectedNode)));
            advFoldout.Add(spacingSection);

            // Size: opt-in drag-to-resize handles in the inspector. Gated to where it makes sense — box-like
            // nodes (containers, buttons, help boxes), never the root, and width is hidden for a direct child of
            // a Columns/Grid track (those are already divider-resizable there).
            bool isRootNode = _clonedLayoutAsset != null && _selectedNode == _clonedLayoutAsset.Root;
            bool isBoxLike = _selectedNode is ContainerNode || _selectedNode is ButtonNode || _selectedNode is HelpBoxNode;
            var sizeParent = (_clonedLayoutAsset != null && _clonedLayoutAsset.Root != null)
                ? FindParent(_selectedNode, _clonedLayoutAsset.Root) : null;
            bool parentIsTrack = sizeParent is ContainerNode ptc &&
                                 (ptc.Type == ContainerType.Columns || ptc.Type == ContainerType.Grid);
            // An aspect-locked frame derives its height from its width — a height grip would fight the lock.
            // The SHARED predicate, so this row and the two renderers that draw the grip can never disagree
            // about which frames are locked (they did: the panel hid the toggle while both renderers happily
            // kept drawing the grip).
            bool frameAspectLocked = FrameBuilder.AspectLocked(_selectedNode);
            // Never in the Preset Editor: MakeWidthResizable / MakeHeightResizable are per-instance sizing —
            // ClearIdentity strips them from a type template, and no StyleClipboard transfer list names them.
            // …and never on a dictionary CELL TEMPLATE: AttachNodeResizeHandles runs inside BuildNode, which a
            // dictionary cell does not go through, and a per-row resize grip inside a two-column table would
            // be meaningless even if it did.
            bool isDictCellTemplate = IsDictionaryCellTemplate(_selectedNode);
            bool showWidthAdjust = isBoxLike && !isRootNode && !parentIsTrack && !_presetMode && !isDictCellTemplate;
            bool showHeightAdjust = isBoxLike && !isRootNode && !frameAspectLocked && !_presetMode && !isDictCellTemplate;

            if (showWidthAdjust || showHeightAdjust)
            {
                var sizeSection = CreateFoldoutHeader("Size");
                if (showWidthAdjust)
                    sizeSection.Add(CreateAllowAdjustToggle("Make Width Resizable",
                        "Show a drag grip in the inspector to resize this element's width (on the left edge when right-aligned, otherwise the right).",
                        () => _selectedNode.MakeWidthResizable, v => _selectedNode.MakeWidthResizable = v));
                if (showHeightAdjust)
                    sizeSection.Add(CreateAllowAdjustToggle("Make Height Resizable",
                        "Show a bottom-edge drag grip in the inspector to resize this element's height.",
                        () => _selectedNode.MakeHeightResizable, v => _selectedNode.MakeHeightResizable = v));
                advFoldout.Add(sizeSection);
            }

            _propertiesContainer.Add(advFoldout);

            // Validation Settings Section (only for BindingNode or CollectionNode) — and never on a dictionary
            // CELL TEMPLATE, whose cell is built outside BuildNode and so never reaches ValidationBinder.Attach.
            var validationSection = isDictCellTemplate
                ? null
                : BuildValidationSection(_selectedNode as BindingNode, _selectedNode as CollectionNode);
            if (validationSection != null) _propertiesContainer.Add(validationSection);

            // Conditions Section — sentence-style rules (outcome + all/any + one-level groups + multiple rules).
            // Absent from the Preset Editor: a condition tests a FIELD on one target type, so Conditions and
            // ConditionRules are stripped by ClearIdentity and carried by no transfer list. (A preset applies to
            // every type in the project — there is no field it could point at.)
            // Absent from a dictionary CELL TEMPLATE for the sibling reason: ConditionBinder.Bind is a BuildNode
            // step, and the export's cell lambda has no hook for a rule either — so the row would do nothing
            // in either renderer.
            if (!_presetMode && !isDictCellTemplate) _propertiesContainer.Add(BuildConditionalsSection());

            // LAST section in the panel, and appended before the scroll restore so that restore measures the
            // real content height rather than one that grows out from under it.
            AppendAnimationsSection();

            if (sameNode)
            {
                RestoreScrollOffsetRobust(_propertiesContainer, scrollPos);
            }

            // Re-run any active field search against the freshly rebuilt panel (self-heal).
            ReapplyPropertiesSearchAfterRebuild();

            // Top-tier multi-selection: state what is being edited and strip the per-node rows. LAST, so
            // identity stays hidden even while the search above is filtering the panel.
            if (multiTier == MultiEditTier.Identical) FinishMultiEditFullPanel();
        }

        // ---- Conditionals authoring (sentence-style rules) ----------------------------------------------------
        // A node carries a list of ConditionRule (outcome + all/any + items). Each item is a bare condition or a
        // one-level group. The UI reads as "Show this field when all of: …", with "+ condition / + group" to grow a
        // rule and "+ Add Rule" for an independent second outcome. The all/any switch only appears once there are
        // ≥2 items to combine, so simple cases stay clean. Structural edits rebuild the whole panel (RefreshProperties),
        // so captured indices are only ever used within a single render generation.

        private static readonly List<ConditionOperator> ConditionOperatorOrder = new List<ConditionOperator>
        {
            ConditionOperator.Equals, ConditionOperator.NotEquals,
            ConditionOperator.GreaterThan, ConditionOperator.GreaterThanOrEqual,
            ConditionOperator.LessThan, ConditionOperator.LessThanOrEqual,
            ConditionOperator.IsTrue, ConditionOperator.IsFalse,
            ConditionOperator.IsNull, ConditionOperator.IsNotNull,
        };

        private static readonly List<ConditionOutcome> ConditionOutcomeOrder = new List<ConditionOutcome>
        {
            ConditionOutcome.Show, ConditionOutcome.Hide, ConditionOutcome.Enable,
            ConditionOutcome.Disable, ConditionOutcome.WarningHighlight,
        };

        private static string ConditionOperatorLabel(ConditionOperator op)
        {
            switch (op)
            {
                case ConditionOperator.Equals: return "=";
                case ConditionOperator.NotEquals: return "≠";      // ≠
                case ConditionOperator.GreaterThan: return ">";
                case ConditionOperator.GreaterThanOrEqual: return "≥"; // ≥
                case ConditionOperator.LessThan: return "<";
                case ConditionOperator.LessThanOrEqual: return "≤";    // ≤
                case ConditionOperator.IsTrue: return "is true";
                case ConditionOperator.IsFalse: return "is false";
                case ConditionOperator.IsNull: return "is null";
                case ConditionOperator.IsNotNull: return "is not null";
                default: return op.ToString();
            }
        }

        private static bool ConditionOperatorIsUnary(ConditionOperator op) =>
            op == ConditionOperator.IsNull || op == ConditionOperator.IsNotNull ||
            op == ConditionOperator.IsTrue || op == ConditionOperator.IsFalse;

        private static string ConditionOutcomeLabel(ConditionOutcome o)
        {
            switch (o)
            {
                case ConditionOutcome.Show: return "Show";
                case ConditionOutcome.Hide: return "Hide";
                case ConditionOutcome.Enable: return "Enable";
                case ConditionOutcome.Disable: return "Disable";
                case ConditionOutcome.WarningHighlight: return "Highlight";
                default: return o.ToString();
            }
        }

        private static string CondMatchLabel(ConditionMatch m) => m == ConditionMatch.All ? "all" : "any";

        private static Color CondOutcomeColor(ConditionOutcome o)
        {
            switch (o)
            {
                case ConditionOutcome.Show: return new Color(0.30f, 0.69f, 0.31f);
                case ConditionOutcome.Hide: return new Color(0.90f, 0.42f, 0.31f);
                case ConditionOutcome.Enable: return new Color(0.26f, 0.60f, 0.88f);
                case ConditionOutcome.Disable: return new Color(0.55f, 0.55f, 0.58f);
                case ConditionOutcome.WarningHighlight: return new Color(0.95f, 0.66f, 0.13f);
                default: return new Color(0.5f, 0.5f, 0.5f);
            }
        }

        // Computed bool members (properties + parameterless methods) usable as condition drivers, e.g. ShowIf("IsValid").
        /// <summary>
        /// The bool members a condition's driver autocomplete offers: the user's OWN computed properties and
        /// parameterless bool methods. Both halves delegate to the house "user-declared, not Unity base-class
        /// noise" filters — <see cref="PropertyInvoker.GetReadableProperties"/> (which already drops anything
        /// declared in UnityEngine/UnityEditor and dedupes by name, most-derived winning) and
        /// <see cref="ButtonInvoker.IsUserActionMethod"/> — so this list can't drift from what the property
        /// picker and the button method picker offer. Unfiltered, a MonoBehaviour target offered Unity's
        /// inherited plumbing (useGUILayout, didStart, didAwake, runInEditMode, allowPrefabModeInPlayMode,
        /// IsInvoking, IsCoupledComponent), most of it non-public — 7 rows of noise around the 2 useful ones.
        ///
        /// Deliberately the SUGGESTION list only: <see cref="ConditionEvaluator"/> still resolves any bool
        /// member by name, so a layout already driven by e.g. isActiveAndEnabled keeps evaluating exactly as
        /// before — it simply stops being suggested.
        /// </summary>
        private static IEnumerable<string> GetBoolMemberNames(System.Type type)
        {
            if (type == null) yield break;
            var seen = new HashSet<string>();

            foreach (var p in PropertyInvoker.GetReadableProperties(type))
            {
                if (p.PropertyType == typeof(bool) && seen.Add(p.Name))
                    yield return p.Name;
            }

            const System.Reflection.BindingFlags flags =
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public |
                System.Reflection.BindingFlags.NonPublic;
            foreach (var m in type.GetMethods(flags))
            {
                if (m.ReturnType == typeof(bool) && m.GetParameters().Length == 0
                    && ButtonInvoker.IsUserActionMethod(m) && seen.Add(m.Name))
                    yield return m.Name;
            }
        }

        private Label CondMiniLabel(string text)
        {
            var l = new Label(text);
            l.style.unityTextAlign = TextAnchor.MiddleLeft;
            l.style.marginLeft = 2;
            l.style.marginRight = 2;
            l.style.opacity = 0.85f;
            return l;
        }

        private VisualElement CondSpacer()
        {
            var s = new VisualElement();
            s.style.flexGrow = 1;
            return s;
        }

        /// <summary>
        /// The one ✕ that removes a thing from the options panel — a condition, a group, a whole rule, an
        /// animation. It is deliberately the SAME control everywhere: a <see cref="StyleMiniButton"/> chip
        /// filled with <see cref="DesignerPalette.Danger"/> and a white glyph, matching the delete buttons the
        /// hierarchy and tab rows already use.
        ///
        /// Conditionals and Animations sit one directly above the other in the same panel and used to
        /// disagree — a stock grey button with a red glyph in one, a solid red chip in the other — which made
        /// two identical actions read as two different kinds of thing. Routing both through here is the fix,
        /// so a third caller cannot reintroduce the split.
        ///
        /// The fill is inline, and an inline <c>backgroundColor</c> kills Unity's stock <c>:hover</c>, so the
        /// tint is wired by hand via <see cref="AddChromeHoverTint"/> rather than left to the theme.
        /// </summary>
        private Button DeleteMiniButton(string tooltip, System.Action onClick)
        {
            var b = new Button(onClick);
            b.Add(SasquatchIcons.Create(SasquatchIcons.Ids.X, 10, Color.white));
            b.tooltip = tooltip;
            StyleMiniButton(b, DesignerPalette.Danger);
            // SQUARE, and exactly as tall as the fields it sits beside. Content-sized it measured 17x11
            // against 18px-tall popups and text fields — a letterbox slit you had to aim at, and the one
            // control in the row you cannot afford to mis-click, since it deletes. Pinning both axes to the
            // field height is what makes it a real target AND lines its top and bottom up with the row.
            b.style.width = DeleteMiniButtonSize;
            b.style.minWidth = DeleteMiniButtonSize;
            b.style.height = DeleteMiniButtonSize;
            b.style.flexShrink = 0f;
            // StyleMiniButton's padding was what SIZED the old button; with the box pinned above it can only
            // squeeze (and clip) the glyph the flex centring already places. Zero it, exactly as
            // StyleTableRowButton does for the live inspector's row actions.
            b.style.paddingLeft = 0;
            b.style.paddingRight = 0;
            b.style.paddingTop = 0;
            b.style.paddingBottom = 0;
            b.style.marginLeft = 4;
            AddChromeHoverTint(b, () => DesignerPalette.Danger);
            return b;
        }

        /// <summary>
        /// The ✕ box, in px. Matches Unity's single-line field height (18) so a delete sits flush with the
        /// popups and text fields on its row rather than floating in the middle of them.
        /// </summary>
        private const int DeleteMiniButtonSize = 18;

        /// <summary>
        /// A CARD-header ✕ — "delete this whole rule / group" — which is <see cref="DeleteMiniButton"/> in
        /// every respect but one: it is hover-revealed, faded out until the pointer is inside the card it
        /// would delete.
        ///
        /// The distinction is scope, not style. A condition row's ✕ removes the one line it sits on and stays
        /// visible, because that line is what you came to edit. A card's ✕ throws away the rule or group and
        /// everything in it — a much bigger action sitting permanently in the corner of every card, reading
        /// as clutter on the rules you are NOT working on and as a hazard on the one you are. Revealing it on
        /// card hover keeps it exactly one pointer-move away while the section stays quiet at rest. Same
        /// trade the live inspector's table and list rows already make (<c>.sasq-table-row-action</c>).
        ///
        /// Kept hit-testable while faded, like those rows: the only way to reach it is to be inside the card,
        /// which is what reveals it. And the space is RESERVED — an opacity fade, never display/visibility —
        /// so the header never reflows as the pointer travels down a stack of rules.
        /// </summary>
        private Button CardDeleteMiniButton(VisualElement card, string tooltip, System.Action onClick)
        {
            var b = DeleteMiniButton(tooltip, onClick);
            b.style.opacity = 0f;   // resting state; every later write goes through EditorSpringFX.RevealFade

            bool shown = false;
            void Reveal(bool on)
            {
                if (on == shown) return;
                shown = on;
                EditorSpringFX.RevealFade(b, on);
            }

            card.RegisterCallback<MouseEnterEvent>(_ => Reveal(true));
            card.RegisterCallback<MouseLeaveEvent>(_ => Reveal(false));
            // Enter/Leave alone is not enough here. Every structural edit inside a card ("+ condition",
            // "+ group", deleting a row) calls RefreshProperties, which rebuilds the panel UNDER a pointer
            // that never left — so the replacement card is born hidden and no MouseEnter is ever coming.
            // The first pointer move inside it re-arms the reveal; Reveal already early-outs when it is
            // showing, so this costs one bool compare per move.
            card.RegisterCallback<MouseMoveEvent>(_ => Reveal(true));
            return b;
        }

        /// <summary>Marker for a modifier chip, so the panel skin pass leaves its face alone.</summary>
        internal const string ModifierChipClass = "sq-modifier-chip";

        /// <summary>
        /// A "+ condition" / "+ group" MODIFIER — an action that adds a clause to the rule card it sits in,
        /// as opposed to "+ Add Rule", which adds a whole new rule to the section.
        ///
        /// Those are two different jobs, and while both wore the same solid grey button the eye could not tell
        /// them apart. So a modifier is a CHIP: outline only, half a step smaller, dimmed text, hugging its own
        /// content — visibly a lesser control than the one full-width solid button that closes the section.
        ///
        /// It paints its own hover/press because it has to. A transparent face is an inline
        /// <c>backgroundColor</c>, which kills Unity's stock <c>:hover</c>/<c>:active</c> — the exact trap that
        /// left the old ghost buttons feeling dead. Wiring it HERE (once, at build time) rather than in the
        /// skin pass is deliberate: <see cref="StylePropertiesPanel"/> re-runs on every geometry change and
        /// would stack a fresh set of callbacks each time.
        /// </summary>
        private Button MakeModifierChip(string label, string tooltip, System.Action onClick)
        {
            var chip = new Button(onClick) { text = label, tooltip = tooltip };
            chip.AddToClassList(ModifierChipClass);
            // No transform spring: this chip paints its own feedback, and a scale would fight that.
            chip.AddToClassList(OptionSprungClass);

            chip.style.height = 18;
            chip.style.alignSelf = Align.FlexStart;   // hug content — never stretch to the card width
            chip.style.fontSize = 10;
            chip.style.paddingLeft = 8;
            chip.style.paddingRight = 8;
            chip.style.paddingTop = 0;
            chip.style.paddingBottom = 0;
            chip.style.marginLeft = 0;
            chip.style.marginRight = 0;
            chip.style.borderTopLeftRadius = 3;
            chip.style.borderTopRightRadius = 3;
            chip.style.borderBottomLeftRadius = 3;
            chip.style.borderBottomRightRadius = 3;
            chip.style.borderTopWidth = 1;
            chip.style.borderBottomWidth = 1;
            chip.style.borderLeftWidth = 1;
            chip.style.borderRightWidth = 1;

            bool hot = false, pressed = false;
            void Paint()
            {
                bool lit = hot || pressed;
                chip.style.backgroundColor = pressed ? DesignerPalette.AccentWash
                                           : hot     ? DesignerPalette.AccentSoft
                                                     : Color.clear;
                var edge = lit ? DesignerPalette.HoverBorder : DesignerPalette.BorderMid;
                chip.style.borderTopColor = edge;
                chip.style.borderBottomColor = edge;
                chip.style.borderLeftColor = edge;
                chip.style.borderRightColor = edge;
                chip.style.color = lit ? DesignerPalette.TextBright : DesignerPalette.TextFaint;
            }

            chip.RegisterCallback<MouseEnterEvent>(_ => { hot = true; Paint(); });
            chip.RegisterCallback<MouseLeaveEvent>(_ => { hot = false; pressed = false; Paint(); });
            chip.RegisterCallback<PointerDownEvent>(_ => { pressed = true; Paint(); });
            chip.RegisterCallback<PointerUpEvent>(_ => { pressed = false; Paint(); });
            Paint();
            return chip;
        }

        private PopupField<ConditionMatch> CondMatchPopup(ConditionMatch current, System.Action<ConditionMatch> onChange)
        {
            var choices = new List<ConditionMatch> { ConditionMatch.All, ConditionMatch.Any };
            var p = new PopupField<ConditionMatch>(choices, current, CondMatchLabel, CondMatchLabel);
            p.tooltip = "all = every condition must match (AND); any = at least one matches (OR).";
            p.RegisterValueChangedCallback(evt => onChange(evt.newValue));
            return p;
        }

        // One condition row: [ driver ] [ op ▾ ] [ value ]  🗑  — editing conds[condIndex] in place (structs, so
        // written back by index). Used for both a bare item's single condition and each condition inside a group.
        private VisualElement BuildConditionRow(List<VisualCondition> conds, int condIndex, System.Action onDelete)
        {
            int index = condIndex;
            var cond = conds[index];

            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.flexWrap = Wrap.Wrap;
            row.style.alignItems = Align.Center;
            row.style.marginTop = 3;
            row.style.marginBottom = 3;

            var driver = new TextField();
            driver.value = cond.PropertyPath;
            driver.style.width = 104;
            driver.tooltip = "Driver: another field, a bool property / method (e.g. IsValid) to compute from code, " +
                             "or the built-in IsInPlayMode — true while the editor is in Play Mode.";
            driver.RegisterValueChangedCallback(evt =>
                HandleDebouncedTextEdit("Modify Condition Driver", () =>
                {
                    var c = conds[index];
                    c.PropertyPath = evt.newValue;
                    conds[index] = c;
                }));
            FlushTextEditOnBlur(driver);
            AutocompleteTextField.Attach(driver, () =>
            {
                var list = new List<AutocompleteTextField.Suggestion>();
                var taken = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var targetType = ResolveTargetType();
                if (targetType != null)
                {
                    // UnboundFieldSync's memo, not the raw call: this provider runs on EVERY keystroke in the
                    // driver field, and the raw call is a recursive walk of the target type's whole serialized
                    // graph. Read-only use — the memo hands back a shared list.
                    foreach (var p in UnboundFieldSync.GetAllProps(targetType))
                    {
                        taken.Add(p.path);
                        list.Add(new AutocompleteTextField.Suggestion(p.path));
                    }
                    foreach (var m in GetBoolMemberNames(targetType))
                    {
                        taken.Add(m);
                        list.Add(new AutocompleteTextField.Suggestion(m));
                    }
                }
                // Built-ins LEAD the list: nothing on the target type hints that they exist, so this list is the
                // only place a user ever meets one — and they are offered even with no resolved target type,
                // since editor state does not depend on one. SKIPPED when the target already carries a member of
                // that name, because the evaluator lets the real member win: offering ours would be a lie.
                for (int b = ConditionDrivers.All.Length - 1; b >= 0; b--)
                {
                    string builtIn = ConditionDrivers.All[b];
                    if (!taken.Contains(builtIn))
                        list.Insert(0, new AutocompleteTextField.Suggestion(builtIn, ConditionDrivers.Describe(builtIn)));
                }
                return list;
            }, s => ConditionDriverSnippet(s.Value));
            PlaceholderText.Attach(driver, "driver");
            row.Add(driver);

            // valueField is declared before the operator popup so the operator handler can toggle its visibility.
            var valueField = new TextField();

            var opField = new PopupField<ConditionOperator>(ConditionOperatorOrder, cond.Op, ConditionOperatorLabel, ConditionOperatorLabel);
            opField.style.marginLeft = 4;
            opField.style.minWidth = 40;
            row.Add(opField);

            valueField.value = cond.Value;
            valueField.style.width = 60;
            valueField.style.marginLeft = 4;
            valueField.tooltip = "Comparison value.";
            valueField.style.display = ConditionOperatorIsUnary(cond.Op) ? DisplayStyle.None : DisplayStyle.Flex;
            valueField.RegisterValueChangedCallback(evt =>
                HandleDebouncedTextEdit("Modify Condition Value", () =>
                {
                    var c = conds[index];
                    c.Value = evt.newValue;
                    conds[index] = c;
                }));
            FlushTextEditOnBlur(valueField);
            AutocompleteTextField.Attach(valueField, () =>
            {
                // A built-in driver (IsInPlayMode) is a bool and belongs to no target type, so it answers first.
                if (ConditionDrivers.IsBuiltIn(driver.value)) return new[] { "true", "false" };
                var targetType = ResolveTargetType();
                if (targetType == null) return Array.Empty<string>();
                var props = UnboundFieldSync.GetAllProps(targetType); // memoised; per-keystroke provider
                var match = props.FirstOrDefault(p => p.path == driver.value);
                if (match.type != null)
                {
                    if (match.type.IsEnum) return Enum.GetNames(match.type);
                    if (match.type == typeof(bool)) return new[] { "true", "false" };
                }
                return Array.Empty<string>();
            });
            PlaceholderText.Attach(valueField, "value");
            row.Add(valueField);

            opField.RegisterValueChangedCallback(evt =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Modify Condition Operator");
                var c = conds[index];
                c.Op = evt.newValue;
                conds[index] = c;
                valueField.style.display = ConditionOperatorIsUnary(evt.newValue) ? DisplayStyle.None : DisplayStyle.Flex;
                OnModification();
                RefreshPreview();
            });

            row.Add(DeleteMiniButton("Delete condition", onDelete));
            return row;
        }

        // A one-level group: an indented bordered box with its own all/any (shown only at ≥2 conditions) + rows.
        private VisualElement BuildGroupCard(ConditionRule rule, ConditionGroup group)
        {
            var box = new VisualElement();
            box.style.marginLeft = 10;
            box.style.marginTop = 4;
            box.style.marginBottom = 4;
            box.style.paddingLeft = 6;
            box.style.paddingRight = 4;
            box.style.paddingTop = 2;
            box.style.paddingBottom = 2;
            box.style.borderLeftWidth = 2;
            box.style.borderLeftColor = new Color(0.45f, 0.55f, 0.75f, 0.9f);
            box.style.backgroundColor = new Color(0.5f, 0.5f, 0.55f, 0.07f);

            var header = new VisualElement();
            header.style.flexDirection = FlexDirection.Row;
            header.style.alignItems = Align.Center;
            header.style.marginTop = 2;

            if (group.Conditions.Count >= 2)
            {
                header.Add(CondMatchPopup(group.Match, m =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Modify Group Match");
                    group.Match = m;
                    OnModification();
                    RefreshPreview();
                }));
                header.Add(CondMiniLabel("of:"));
            }
            else
            {
                header.Add(CondMiniLabel("Group:"));
            }
            header.Add(CondSpacer());
            // Revealed on hover of the GROUP box, not the rule card — the ✕ must belong to the thing it
            // deletes, and a group card sits inside a rule card, so hanging it off the rule would light up
            // every group at once.
            header.Add(CardDeleteMiniButton(box, "Delete group", () =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Delete Condition Group");
                rule.Items.Remove(group);
                OnModification();
                RefreshProperties();
                RefreshPreview();
            }));
            box.Add(header);

            for (int j = 0; j < group.Conditions.Count; j++)
            {
                int jj = j;
                box.Add(BuildConditionRow(group.Conditions, jj, () =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Delete Condition");
                    group.Conditions.RemoveAt(jj);
                    if (group.Conditions.Count == 0) rule.Items.Remove(group); // prune an emptied group
                    OnModification();
                    RefreshProperties();
                    RefreshPreview();
                }));
            }

            var addCond = MakeModifierChip("+ condition", "Add another condition to this group.", () =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Add Condition");
                group.Conditions.Add(new VisualCondition("", ConditionOperator.Equals, ""));
                OnModification();
                RefreshProperties();
                RefreshPreview();
            });
            addCond.style.marginTop = 2;
            box.Add(addCond);

            return box;
        }

        // One rule: "Outcome this field when all/any of:" + items (bare rows and group cards) + "+ condition / + group".
        private VisualElement BuildRuleCard(int ruleIndex)
        {
            var rules = _selectedNode.ConditionRules;
            var rule = rules[ruleIndex];

            var card = new VisualElement();
            card.style.marginTop = 4;
            card.style.marginBottom = 8;
            card.style.paddingLeft = 6;
            card.style.paddingRight = 4;
            card.style.paddingTop = 3;
            card.style.paddingBottom = 4;
            card.style.borderLeftWidth = 3;
            card.style.borderLeftColor = CondOutcomeColor(rule.Outcome);
            card.style.backgroundColor = new Color(0.5f, 0.5f, 0.5f, 0.06f);

            var header = new VisualElement();
            header.style.flexDirection = FlexDirection.Row;
            header.style.flexWrap = Wrap.Wrap;
            header.style.alignItems = Align.Center;

            var outcome = new PopupField<ConditionOutcome>(ConditionOutcomeOrder, rule.Outcome, ConditionOutcomeLabel, ConditionOutcomeLabel);
            outcome.style.minWidth = 78;
            outcome.tooltip = "What happens to this field when the rule matches.";
            outcome.RegisterValueChangedCallback(evt =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Modify Condition Outcome");
                rule.Outcome = evt.newValue;
                card.style.borderLeftColor = CondOutcomeColor(evt.newValue);
                OnModification();
                RefreshPreview();
            });
            header.Add(outcome);
            header.Add(CondMiniLabel("this field when"));

            if (rule.Items.Count >= 2)
            {
                header.Add(CondMatchPopup(rule.Match, m =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Modify Rule Match");
                    rule.Match = m;
                    OnModification();
                    RefreshPreview();
                }));
                header.Add(CondMiniLabel("of:"));
            }
            else
            {
                header.Add(CondMiniLabel(":"));
            }

            header.Add(CondSpacer());
            header.Add(CardDeleteMiniButton(card, "Delete rule", () =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Delete Condition Rule");
                rules.Remove(rule);
                OnModification();
                RefreshProperties();
                RefreshPreview();
            }));
            card.Add(header);

            for (int i = 0; i < rule.Items.Count; i++)
            {
                var item = rule.Items[i];
                if (item.IsGroup)
                {
                    card.Add(BuildGroupCard(rule, item));
                }
                else
                {
                    var capturedItem = item;
                    card.Add(BuildConditionRow(item.Conditions, 0, () =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Delete Condition");
                        rule.Items.Remove(capturedItem);
                        OnModification();
                        RefreshProperties();
                        RefreshPreview();
                    }));
                }
            }

            var footer = new VisualElement();
            footer.style.flexDirection = FlexDirection.Row;
            footer.style.marginTop = 3;

            var addCond = MakeModifierChip("+ condition", "Add another condition to this rule.", () =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Add Condition");
                rule.Items.Add(ConditionGroup.Leaf(new VisualCondition("", ConditionOperator.Equals, "")));
                OnModification();
                RefreshProperties();
                RefreshPreview();
            });

            var addGroup = MakeModifierChip("+ group",
                "A group of conditions with its own all/any — for mixed AND/OR like (A and B) or C.", () =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Add Group");
                rule.Items.Add(ConditionGroup.Group(ConditionMatch.All));
                OnModification();
                RefreshProperties();
                RefreshPreview();
            });
            addGroup.style.marginLeft = 6;

            footer.Add(addCond);
            footer.Add(addGroup);
            card.Add(footer);

            return card;
        }

        /// <summary>
        /// The "Validation Settings" section for a binding or a collection, or null when the node is neither.
        /// <para>Extracted from the properties-panel builder so the MULTI-EDIT lower tiers can reuse it rather
        /// than re-authoring it — validation means the same thing on a Slider and a Toggle, so it has no
        /// business being gated on Display Type.</para>
        /// <para><paramref name="requiredAppliesOverride"/> / <paramref name="rangeAppliesOverride"/> — null on
        /// a single selection, where the node's own bound type decides. A multi-selection passes the AND across
        /// the whole selection, so a range row is never offered because the PRIMARY happens to be numeric.</para>
        /// <para>Note what is NOT here any more: the four prose/hook rows used to be wrapped in
        /// <c>Identity(...)</c>. They fan out now — a validation method names a method on the layout's one
        /// target type, and the messages are prose set deliberately on the row in front of you. Their data twin
        /// left <c>MultiEditMirror.IdentityFields</c> in the same pass.</para>
        /// </summary>
        private VisualElement BuildValidationSection(BindingNode bNode, CollectionNode cNode,
                                                     bool? requiredAppliesOverride = null,
                                                     bool? rangeAppliesOverride = null)
        {
            if (bNode == null && cNode == null) return null;
            var validationSection = CreateFoldoutHeader("Validation Settings");
            
            if (bNode != null)
            {
                // Resolve the bound field's C# type so we only offer validators that make SENSE for it (blocking,
                // e.g., "Is Required" on a bool that always has a value) and word the default messages correctly.
                // Unknown type (unresolvable) → offer everything as a safe fallback.
                System.Type fieldType = ResolveSelectedNodeFieldType(bNode);
                bool typeUnknown = fieldType == null;
                bool isReference = fieldType != null && typeof(UnityEngine.Object).IsAssignableFrom(fieldType);
                bool isString = fieldType == typeof(string);
                bool isNumeric = DisplayTypeCatalog.IsSliderNumeric(fieldType);
                // "Is Required" only makes sense where a field can be empty/unset: object references (null) or
                // strings (blank). Numbers, bools, enums and structs ALWAYS hold a value — hide it there, unless
                // it's already enabled (so a nonsensical legacy setting can still be turned back off).
                bool requiredApplies = requiredAppliesOverride ?? (typeUnknown || isReference || isString || bNode.Required);
                // Range is numeric-only (or unknown / already-on).
                bool rangeApplies = rangeAppliesOverride ?? (typeUnknown || isNumeric || bNode.ValidateRange);

                string ReqLabel() => ValidationFieldLabel(bNode.EffectiveLabelOverride, bNode.PropertyPath);

                // NOTE on responsiveness: the per-keystroke value handlers below call ONLY OnModification(), which
                // schedules a DEBOUNCED preview rebuild. They intentionally do NOT also call RefreshPreview()
                // (an immediate full canvas rebuild) — doing both on every keystroke made typing in the message
                // fields laggy on complex layouts.

                if (requiredApplies)
                {
                    var requiredToggle = new Toggle("Is Required");
                    requiredToggle.value = bNode.Required;
                    requiredToggle.tooltip = isReference
                        ? "Show a warning if this reference is left unassigned (null)."
                        : "Show a warning if this field is left empty / blank.";
                    validationSection.Add(requiredToggle);

                    var reqMessageField = new TextField("Required Message");
                    reqMessageField.value = bNode.RequiredMessage;
                    reqMessageField.tooltip = "Custom warning message when empty.";
                    TextAreaHelper.MakeWrappingResizableTextArea(reqMessageField);
                    reqMessageField.style.display = bNode.Required ? DisplayStyle.Flex : DisplayStyle.None;
                    validationSection.Add(reqMessageField);

                    requiredToggle.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Toggle Required Validation");
                        bNode.Required = evt.newValue;
                        // Pre-fill a type-appropriate default the first time it's enabled (only when still blank).
                        if (evt.newValue && string.IsNullOrEmpty(bNode.RequiredMessage))
                        {
                            bNode.RequiredMessage = DefaultRequiredMessage(ReqLabel(), isReference);
                            reqMessageField.SetValueWithoutNotify(bNode.RequiredMessage);
                        }
                        reqMessageField.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                        OnModification();
                    });

                    reqMessageField.RegisterValueChangedCallback(evt =>
                        HandleDebouncedTextEdit("Change Required Message", () => bNode.RequiredMessage = evt.newValue));
                    FlushTextEditOnBlur(reqMessageField);
                }

                if (rangeApplies)
                {
                    var rangeToggle = new Toggle("Validate Range");
                    rangeToggle.value = bNode.ValidateRange;
                    rangeToggle.tooltip = "Show a warning if the numeric value goes outside the min/max validation range.";
                    validationSection.Add(rangeToggle);

                    var rangeSettingsGroup = new VisualElement();
                    rangeSettingsGroup.style.display = bNode.ValidateRange ? DisplayStyle.Flex : DisplayStyle.None;

                    // Declared up front so the Min/Max handlers can keep it in sync; added to the group after
                    // Min/Max below to preserve display order (Min, Max, Message).
                    var rangeMsgField = new TextField("Range Warning Message");
                    rangeMsgField.value = bNode.RangeValidationMessage;
                    rangeMsgField.tooltip = "Custom warning message when out of range.";
                    TextAreaHelper.MakeWrappingResizableTextArea(rangeMsgField);

                    // Keep the range message showing the current min/max WHILE it's still the auto-generated
                    // default (or empty). Once the author types their own text it stops matching the old default
                    // and is never overwritten again.
                    void SyncRangeDefaultMessage(float oldMin, float oldMax, bool oldHasMin, bool oldHasMax)
                    {
                        string label = ReqLabel();
                        string oldDefault = DefaultRangeMessage(label, oldMin, oldMax, oldHasMin, oldHasMax);
                        if (string.IsNullOrEmpty(bNode.RangeValidationMessage) || bNode.RangeValidationMessage == oldDefault)
                        {
                            bNode.RangeValidationMessage = DefaultRangeMessage(label, bNode.ValidationMin, bNode.ValidationMax, bNode.RangeHasMin, bNode.RangeHasMax);
                            rangeMsgField.SetValueWithoutNotify(bNode.RangeValidationMessage);
                        }
                    }

                    // Which bound(s) the rule enforces. A one-sided choice hides the other field and drops it
                    // from the check / clamp / message — this is what an imported [Min] lands on.
                    const string BoundBoth = "Minimum and Maximum";
                    const string BoundMinOnly = "Minimum only";
                    const string BoundMaxOnly = "Maximum only";
                    string CurrentBoundChoice() =>
                        bNode.RangeHasMin && bNode.RangeHasMax ? BoundBoth
                        : bNode.RangeHasMax ? BoundMaxOnly : BoundMinOnly;

                    var valMinField = new FloatField("Validation Min");
                    var valMaxField = new FloatField("Validation Max");
                    void SyncBoundFieldVisibility()
                    {
                        valMinField.style.display = bNode.RangeHasMin ? DisplayStyle.Flex : DisplayStyle.None;
                        valMaxField.style.display = bNode.RangeHasMax ? DisplayStyle.Flex : DisplayStyle.None;
                    }

                    var boundModeField = new DropdownField("Bounds",
                        new List<string> { BoundBoth, BoundMinOnly, BoundMaxOnly }, CurrentBoundChoice());
                    boundModeField.tooltip = "Which side(s) of the range to enforce. Pick one side for a minimum-only or maximum-only rule.";
                    boundModeField.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Change Validation Bounds");
                        bool oldHasMin = bNode.RangeHasMin, oldHasMax = bNode.RangeHasMax;
                        bNode.RangeHasMin = evt.newValue != BoundMaxOnly;
                        bNode.RangeHasMax = evt.newValue != BoundMinOnly;
                        SyncBoundFieldVisibility();
                        if (bNode.ValidateRange) SyncRangeDefaultMessage(bNode.ValidationMin, bNode.ValidationMax, oldHasMin, oldHasMax);
                        OnModification();
                    });
                    rangeSettingsGroup.Add(boundModeField);

                    valMinField.value = bNode.ValidationMin;
                    valMinField.RegisterValueChangedCallback(evt =>
                    {
                        HandleDebouncedValueEdit("Change Validation Min", () =>
                        {
                            float oldMin = bNode.ValidationMin;
                            bNode.ValidationMin = evt.newValue;
                            if (bNode.ValidateRange) SyncRangeDefaultMessage(oldMin, bNode.ValidationMax, bNode.RangeHasMin, bNode.RangeHasMax);
                        }, liveRebuild: true);
                    });
                    FlushValueEditOnBlur(valMinField);
                    rangeSettingsGroup.Add(valMinField);

                    valMaxField.value = bNode.ValidationMax;
                    valMaxField.RegisterValueChangedCallback(evt =>
                    {
                        HandleDebouncedValueEdit("Change Validation Max", () =>
                        {
                            float oldMax = bNode.ValidationMax;
                            bNode.ValidationMax = evt.newValue;
                            if (bNode.ValidateRange) SyncRangeDefaultMessage(bNode.ValidationMin, oldMax, bNode.RangeHasMin, bNode.RangeHasMax);
                        }, liveRebuild: true);
                    });
                    FlushValueEditOnBlur(valMaxField);
                    rangeSettingsGroup.Add(valMaxField);
                    SyncBoundFieldVisibility();

                    var clampToggle = new Toggle("Clamp to Range");
                    clampToggle.value = bNode.ClampToRange;
                    clampToggle.tooltip = "Force the value back into range as you edit (scrub or type) — an enforced MinValue/MaxValue. Silent: the value pins at the bound instead of showing a warning.";
                    clampToggle.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Toggle Clamp To Range");
                        bNode.ClampToRange = evt.newValue;
                        OnModification();
                    });
                    rangeSettingsGroup.Add(clampToggle);

                    rangeMsgField.RegisterValueChangedCallback(evt =>
                        HandleDebouncedTextEdit("Change Range Message", () => bNode.RangeValidationMessage = evt.newValue));
                    FlushTextEditOnBlur(rangeMsgField);
                    rangeSettingsGroup.Add(rangeMsgField);

                    validationSection.Add(rangeSettingsGroup);

                    rangeToggle.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Toggle Range Validation");
                        bNode.ValidateRange = evt.newValue;
                        if (evt.newValue && string.IsNullOrEmpty(bNode.RangeValidationMessage))
                        {
                            bNode.RangeValidationMessage = DefaultRangeMessage(ReqLabel(), bNode.ValidationMin, bNode.ValidationMax, bNode.RangeHasMin, bNode.RangeHasMax);
                            rangeMsgField.SetValueWithoutNotify(bNode.RangeValidationMessage);
                        }
                        rangeSettingsGroup.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                        OnModification();
                    });
                }

                // Custom Method validation — always available (a method can validate any type, bool included).
                var valMethodField = new TextField("Validation Method");
                valMethodField.value = bNode.ValidationMethod;
                valMethodField.tooltip = "A method on the target returning bool — parameterless, or taking 1 argument of the field's type — to run for custom validation.";
                validationSection.Add(valMethodField);

                var valMsgField = new TextField("Validation Message");
                valMsgField.value = bNode.ValidationMessage;
                valMsgField.tooltip = "Error message shown when validation fails.";
                TextAreaHelper.MakeWrappingResizableTextArea(valMsgField);
                valMsgField.style.display = !string.IsNullOrEmpty(bNode.ValidationMethod) ? DisplayStyle.Flex : DisplayStyle.None;
                validationSection.Add(valMsgField);

                valMethodField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change Validation Method", () =>
                    {
                        bNode.ValidationMethod = evt.newValue;
                        if (!string.IsNullOrEmpty(evt.newValue) && string.IsNullOrEmpty(bNode.ValidationMessage))
                        {
                            bNode.ValidationMessage = DefaultMethodMessage(ReqLabel());
                            valMsgField.SetValueWithoutNotify(bNode.ValidationMessage);
                        }
                        valMsgField.style.display = !string.IsNullOrEmpty(evt.newValue) ? DisplayStyle.Flex : DisplayStyle.None;
                    }));
                FlushTextEditOnBlur(valMethodField);

                AutocompleteTextField.Attach(valMethodField, () =>
                {
                    var targetType = ResolveTargetType();
                    return targetType != null ? GetValidationMethodNames(targetType) : Array.Empty<string>();
                }, s => MethodSourcePreview.GetSnippet(ResolveTargetType(), s.Value));

                valMsgField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change Validation Message", () => bNode.ValidationMessage = evt.newValue));
                FlushTextEditOnBlur(valMsgField);
            }
            else if (cNode != null)
            {
                // A collection can ALWAYS be empty, so on its own it always offers Required — hence the `?? true`
                // rather than re-deriving anything. The override only ever bites in multi-edit, where the
                // selection may also hold a binding that cannot be empty (a float, a bool); ticking the row then
                // would fan a rule onto a field that can never fail it.
                bool requiredApplies = requiredAppliesOverride ?? true;

                if (requiredApplies)
                {
                    // Required toggle for collection
                    var requiredToggle = new Toggle("Is Required");
                    requiredToggle.value = cNode.Required;
                    requiredToggle.tooltip = "Show a warning if this collection is empty.";
                    validationSection.Add(requiredToggle);

                    var reqMessageField = new TextField("Required Message");
                    reqMessageField.value = cNode.RequiredMessage;
                    reqMessageField.tooltip = "Custom warning message when empty.";
                    TextAreaHelper.MakeWrappingResizableTextArea(reqMessageField);
                    reqMessageField.style.display = cNode.Required ? DisplayStyle.Flex : DisplayStyle.None;
                    validationSection.Add(reqMessageField);

                    requiredToggle.RegisterValueChangedCallback(evt =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Toggle Required Validation");
                        cNode.Required = evt.newValue;
                        // Pre-fill a sensible "must have at least one item" default when first enabled (only when blank).
                        if (evt.newValue && string.IsNullOrEmpty(cNode.RequiredMessage))
                        {
                            cNode.RequiredMessage = DefaultCollectionRequiredMessage(
                                ValidationFieldLabel(null, cNode.PropertyPath));
                            reqMessageField.SetValueWithoutNotify(cNode.RequiredMessage);
                        }
                        reqMessageField.style.display = evt.newValue ? DisplayStyle.Flex : DisplayStyle.None;
                        OnModification(); // debounced rebuild; no immediate RefreshPreview (keeps typing smooth)
                    });

                    reqMessageField.RegisterValueChangedCallback(evt =>
                        HandleDebouncedTextEdit("Change Required Message", () => cNode.RequiredMessage = evt.newValue));
                    FlushTextEditOnBlur(reqMessageField);
                }

                // Custom Method validation
                var valMethodField = new TextField("Validation Method");
                valMethodField.value = cNode.ValidationMethod;
                valMethodField.tooltip = "A method on the target returning bool (parameterless) to run for custom validation.";
                validationSection.Add(valMethodField);

                var valMsgField = new TextField("Validation Message");
                valMsgField.value = cNode.ValidationMessage;
                valMsgField.tooltip = "Error message shown when validation fails.";
                TextAreaHelper.MakeWrappingResizableTextArea(valMsgField);
                valMsgField.style.display = !string.IsNullOrEmpty(cNode.ValidationMethod) ? DisplayStyle.Flex : DisplayStyle.None;
                validationSection.Add(valMsgField);

                valMethodField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change Validation Method", () =>
                    {
                        cNode.ValidationMethod = evt.newValue;
                        // Pre-fill a default message the first time a method is named (only when still blank).
                        if (!string.IsNullOrEmpty(evt.newValue) && string.IsNullOrEmpty(cNode.ValidationMessage))
                        {
                            cNode.ValidationMessage = DefaultMethodMessage(ValidationFieldLabel(null, cNode.PropertyPath));
                            valMsgField.SetValueWithoutNotify(cNode.ValidationMessage);
                        }
                        valMsgField.style.display = !string.IsNullOrEmpty(evt.newValue) ? DisplayStyle.Flex : DisplayStyle.None;
                    }));
                FlushTextEditOnBlur(valMethodField);

                AutocompleteTextField.Attach(valMethodField, () =>
                {
                    var targetType = ResolveTargetType();
                    return targetType != null ? GetValidationMethodNames(targetType) : Array.Empty<string>();
                }, s => MethodSourcePreview.GetSnippet(ResolveTargetType(), s.Value));

                valMsgField.RegisterValueChangedCallback(evt =>
                    HandleDebouncedTextEdit("Change Validation Message", () => cNode.ValidationMessage = evt.newValue));
                FlushTextEditOnBlur(valMsgField);
            }
            return validationSection;
        }

        private VisualElement BuildConditionalsSection()
        {
            // The followers were migrated AND stripped of their legacy lists back in ArmMultiEditMirror — before
            // the mirror snapshotted, which is the only order that works. See the comment there.
            ConditionModel.EnsureMigrated(_selectedNode);

            var rules = _selectedNode.ConditionRules;

            var section = CreateFoldoutHeader("Conditionals");

            // A rule list is one field, so an edit replaces every follower's whole list rather than merging.
            // Say so, with a count, before the user finds out by losing work.
            AppendMultiEditListBanner(section, MultiEditMirror.ConditionFields, "conditions");

            if (rules.Count == 0)
            {
                var hint = new Label("Show, hide, enable or disable this field based on other values — " +
                                     "or on the built-in IsInPlayMode, to surface debug fields only while the game runs.");
                hint.style.whiteSpace = WhiteSpace.Normal;
                hint.style.opacity = 0.7f;
                hint.style.marginBottom = 4;
                section.Add(hint);
            }
            else
            {
                for (int i = 0; i < rules.Count; i++)
                    section.Add(BuildRuleCard(i));
            }

            var addBtn = new Button(() =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Add Condition Rule");
                var rule = new ConditionRule(ConditionOutcome.Show, ConditionMatch.All);
                rule.Items.Add(ConditionGroup.Leaf(new VisualCondition("", ConditionOperator.Equals, "")));
                _selectedNode.ConditionRules.Add(rule);
                OnModification();
                RefreshProperties();
                RefreshPreview();
            }) { text = rules.Count == 0 ? "+ Add Condition" : "+ Add Rule" };
            addBtn.style.marginTop = 5;
            // Full-width, so it opts out of the spring sweep exactly like "+ Add Animation" — same
            // scale-paints-past-the-panel reason. Hover/press comes from the stock button USS.
            addBtn.AddToClassList(OptionSprungClass);
            section.Add(addBtn);

            return section;
        }

        /// <summary>
        /// A Properties-panel section. Note what this does NOT do: it sets no margins, no weight and no
        /// colours. The whole "Rails &amp; Rhythm" look — the two header tiers, the rail, the state colours, the
        /// spacing scale — is applied by <see cref="StylePropertiesPanel"/> as one pass over the finished
        /// tree, keyed off measured nesting depth rather than a level argument threaded through 22 call sites.
        /// The six sections still built with a bare <c>new Foldout()</c> are styled identically for the same
        /// reason, and a section added later needs to do nothing at all to match.
        /// </summary>
        private Foldout CreateFoldoutHeader(string label)
        {
            var foldout = new Foldout();
            foldout.text = label;
            foldout.value = true;
            SasquatchIcons.SkinFoldout(foldout);
            return foldout;
        }

        /// <summary>
        /// A <see cref="CreateFoldoutHeader"/> section whose open/closed state survives the panel rebuild that
        /// a Save triggers — without it, a section the user collapsed to get it out of the way springs back open
        /// on the next edit under Auto-Save, which defeats the point of collapsing it.
        /// </summary>
        private Foldout CreatePersistedSection(string label, bool expanded, Action<bool> remember)
        {
            var foldout = CreateFoldoutHeader(label);
            foldout.value = expanded;
            // Register on the foldout's OWN toggle, queried BEFORE any content is added — a child checkbox's
            // ChangeEvent&lt;bool&gt; bubbles up through the foldout, so listening on the foldout itself would
            // record a stray "Searchable" tick as the section's expand state. (Same trap as Appearance.)
            foldout.Q<Toggle>()?.RegisterValueChangedCallback(evt => remember(evt.newValue));
            return foldout;
        }

        /// <summary>
        /// The tray a toggle's sub-options live in: indented, with ONE continuous hairline down its left edge so
        /// the cluster reads as belonging to the row above it rather than as more rows in a flat column. One tray
        /// per parent toggle is what keeps that line unbroken — a border per row breaks at every row margin.
        /// </summary>
        private static VisualElement MakeSubOptionTray()
        {
            var tray = new VisualElement();
            tray.style.marginLeft = 9;
            tray.style.paddingLeft = 7;
            tray.style.marginBottom = 3;
            tray.style.borderLeftWidth = 1;
            tray.style.borderLeftColor = DesignerPalette.TreeGuide;
            return tray;
        }

        /// <summary>
        /// Hides a section outright once every row inside it is gated off, so a mode change can never leave an
        /// empty header standing. A collection's Display Type does exactly that: Default and Custom Widget switch
        /// the whole row-ergonomics set off in one go.
        /// </summary>
        private static void SyncSectionVisibility(VisualElement section)
        {
            if (section == null) return;
            var content = (section as Foldout)?.contentContainer ?? section;
            bool anyVisible = false;
            foreach (var child in content.Children())
            {
                if (child.style.display != DisplayStyle.None)
                {
                    anyVisible = true;
                    break;
                }
            }
            section.style.display = anyVisible ? DisplayStyle.Flex : DisplayStyle.None;
        }

        private const string OptionSprungClass = "sq-option-sprung";

        /// <summary>
        /// Gives every action button built into a rebuilt options panel (Properties / Animations) the standard
        /// hover-lift + press-dip spring. Those panels are reconstructed ad-hoc with many one-off Buttons
        /// (segmented widget controls, color-palette actions, +/▶/✕ rows, Add Condition/Animation, style-reset
        /// arrows); rather than wire each call site, we sweep the finished panel once per rebuild. Scoped to the
        /// panel's own container, so it only ever catches OUR buttons — section headers are Foldouts (a Toggle,
        /// not a Button) and Unity's composite fields expose no child Button. Idempotent via a marker class so a
        /// button that survives a rebuild is never double-wired.
        /// </summary>
        private static void ApplyOptionButtonSprings(VisualElement container)
        {
            if (container == null) return;
            container.Query<Button>().ForEach(b =>
            {
                if (b.ClassListContains(OptionSprungClass)) return;
                b.AddToClassList(OptionSprungClass);
                EditorSpringFX.ButtonSpring(b);
            });
        }

        // Display label for the curated Widget-Kind popup (shared with the quick-edit popup).
        private static string FormatDisplayType(DisplayType k) => DisplayTypeCatalog.Format(k);

        // The reset (counter-clockwise arrow) button shared by every style control. Same icon/sizing as
        // the Label/Tooltip/Header reset so the whole panel reads consistently. Visibility is the
        // caller's job (shown only when the value is overridden).
        private Button MakeStyleResetButton()
        {
            return OverridableTextRow.CreateResetButton("Reset to default");
        }

        // The second reset gesture: right-click → "Reset to default" (disabled when not overridden).
        private void AddStyleResetContextMenu(VisualElement target, Func<bool> isOverridden, Action doReset)
        {
            target.AddManipulator(new ContextualMenuManipulator(evt =>
                evt.menu.AppendAction("Reset to default",
                    _ => doReset(),
                    _ => isOverridden() ? DropdownMenuAction.Status.Normal : DropdownMenuAction.Status.Disabled)));
        }

        // Hover feedback for segmented (alignment/placement) button groups. Enter brightens the
        // button relative to its state; leave restores via the group's own Sync when provided
        // (the source of truth for active backgrounds), else recomputes from isActive.
        private static void AddSegmentedHover(Button btn, Func<bool> isActive, Action restore = null)
        {
            btn.RegisterCallback<MouseEnterEvent>(_ => btn.style.backgroundColor = isActive()
                ? DesignerPalette.SegmentHoverActiveBg
                : DesignerPalette.SegmentHoverIdleBg);
            if (restore != null)
            {
                btn.RegisterCallback<MouseLeaveEvent>(_ => restore());
            }
            else
            {
                btn.RegisterCallback<MouseLeaveEvent>(_ => btn.style.backgroundColor = isActive()
                    ? DesignerPalette.AccentFillSoft
                    : DesignerPalette.ButtonNeutralBg);
            }
        }

        // ---- Chrome-button hover tint (toolbar / canvas-header buttons with an INLINE face) --------------
        //
        // A button that sets style.backgroundColor loses Unity's stock :hover USS, so it needs a callback to
        // get any color feedback. The wrinkle is that most of these buttons ALSO have a color authority that
        // repaints them on a state change (UpdateSaveButtonText, SyncModeButtonColors, UpdateColumnButtons) —
        // and clicking one repaints it while the cursor is still on top of it, wiping the tint until the user
        // moves the mouse away and back. So the hover state lives on the element as a marker class and every
        // authority paints through ChromePaint, which honors it. One flag, one painter, no drift.
        private const string ChromeHoverClass = "sasq-chrome-hover";

        /// <summary>
        /// Paints <paramref name="ve"/>'s face, brightened when a chrome hover is active on it. Returns the
        /// color actually painted, so a caller that also picks a LABEL color contrasts against what's on
        /// screen rather than the rest color (Save does this — see PaintSaveButtonFace).
        /// </summary>
        private static Color ChromePaint(VisualElement ve, Color face)
        {
            if (ve == null) return face;
            var painted = ve.ClassListContains(ChromeHoverClass) ? DesignerPalette.Hovered(face) : face;
            ve.style.backgroundColor = painted;
            return painted;
        }

        /// <summary>
        /// Wires the hover tint on a chrome button. <paramref name="face"/> is read LIVE at fire time (never
        /// captured) so a button whose rest color depends on state — Save's clean/dirty fill, the mode pair's
        /// active/idle fill — tints the color it is actually wearing.
        /// </summary>
        private static void AddChromeHoverTint(VisualElement ve, Func<Color> face)
        {
            AddChromeHoverRepaint(ve, () => ChromePaint(ve, face()));
        }

        /// <summary>
        /// The same hover marker, but handing the actual painting to the element's own repaint authority — for
        /// buttons whose hover look is more than a background (the column toggles also lift their opacity).
        /// </summary>
        private static void AddChromeHoverRepaint(VisualElement ve, Action repaint)
        {
            if (ve == null) return;
            ve.RegisterCallback<MouseEnterEvent>(_ => { ve.AddToClassList(ChromeHoverClass); repaint(); });
            ve.RegisterCallback<MouseLeaveEvent>(_ => { ve.RemoveFromClassList(ChromeHoverClass); repaint(); });
        }

        /// <summary>
        /// A destructive action that shouldn't shout: ghost at rest (no fill, a red rule and a red label),
        /// solid red the moment you're on it. Two saturated fills in one toolbar just made its loudest colors
        /// argue — this leaves exactly ONE filled button (Save, the primary action) while Revert stays
        /// unmistakably destructive. It is confirmed by dialog either way, so the quieter rest state costs no
        /// safety, and it keeps red meaning "destructive" rather than merely "here is a button".
        /// </summary>
        private static void StyleGhostDangerButton(Button btn)
        {
            if (btn == null) return;
            void Paint()
            {
                bool hot = btn.ClassListContains(ChromeHoverClass);
                btn.style.backgroundColor = hot ? DesignerPalette.DangerStrong : Color.clear;
                btn.style.color = hot ? Color.white : DesignerPalette.DangerIcon;
            }
            btn.style.borderTopWidth = btn.style.borderBottomWidth =
                btn.style.borderLeftWidth = btn.style.borderRightWidth = 1;
            btn.style.borderTopColor = btn.style.borderBottomColor =
                btn.style.borderLeftColor = btn.style.borderRightColor = DesignerPalette.DangerStrong;
            Paint();
            AddChromeHoverRepaint(btn, Paint);
            EditorSpringFX.ButtonSpring(btn);
        }

        /// <summary>
        /// The search magnifier's chrome, shared by the Hierarchy, Canvas and Properties bars. Hovering fills the BUTTON
        /// with accent blue and forces the glyph white — which is why this can't just call
        /// <see cref="SearchActiveOverlay.TintSearchToggle"/>: the "search is open" tell is also accent blue,
        /// so an open + hovered magnifier would be a blue glyph on a blue face. Hover wins; open shows through
        /// again the moment the cursor leaves.
        /// </summary>
        internal static void PaintSearchToggle(Button toggle, bool open)
        {
            if (toggle == null) return;
            bool hot = toggle.ClassListContains(ChromeHoverClass);

            if (open)
            {
                // The bar is open, so the button WEARS the accent — that is what the colour reports. Hover
                // brightens the blue it already has rather than swapping to some other colour, exactly the move
                // the Design Mode button makes when it's the active one.
                toggle.style.backgroundColor = hot
                    ? DesignerPalette.Hovered(DesignerPalette.AccentFill)
                    : DesignerPalette.AccentFill;
            }
            else
            {
                // Closed, accent would be a lie: it would say "searching" to anyone who merely swept the cursor
                // past. A shut magnifier hovers like any other neutral chrome button — a lighter grey — and at
                // rest drops its inline face entirely (StyleKeyword.Null) so the stock button grey comes back.
                toggle.style.backgroundColor = hot
                    ? (StyleColor)DesignerPalette.SegmentHoverIdleBg
                    : (StyleColor)StyleKeyword.Null;
            }

            // Glyph follows its face: white reads on the accent fill, the normal icon tint on grey. (Hover no
            // longer needs a special case — the glyph never sits on a colour it can't be read against.)
            SearchActiveOverlay.TintSearchToggle(toggle, open, Color.white, SasquatchIcons.DefaultTint);
        }

        // A 2- or 3-icon Left/(Center)/Right segmented alignment picker for an ImageAlignment value — the same look
        // as the Asset Preview "Preview Alignment" row, factored out so XY Pad / Vector normalize / Image banner /
        // help chip all share ONE control. Pass includeCenter:false for a Left/Right-only picker. Reads/writes via
        // get/set; records Undo + refreshes on click.
        private VisualElement BuildImageAlignmentRow(string label, Func<ImageAlignment> get, Action<ImageAlignment> set, string undoLabel, bool includeCenter = true, ImageAlignment defaultValue = ImageAlignment.Left)
        {
            var row = new VisualElement();
            row.AddToClassList("unity-base-field");
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 2;

            var lbl = new Label(label);
            lbl.AddToClassList("unity-base-field__label");
            row.Add(lbl);

            var buttons = new VisualElement();
            buttons.AddToClassList("unity-base-field__input");
            buttons.style.flexDirection = FlexDirection.Row;
            buttons.style.alignItems = Align.Center;
            buttons.style.justifyContent = Justify.FlexEnd;
            buttons.style.flexGrow = 1;

            // ↺ reset — appears once the alignment differs from its serialized default, matching the sibling
            // segmented rows (BuildPlacementButtonRow / CreateSegmentedEnumControl both carry one). Each caller
            // passes the value its model field initializes to so "reset" restores the true default.
            var reset = MakeStyleResetButton();
            bool IsOverridden() => get() != defaultValue;
            void SyncReset() => ApplyOverrideChrome(buttons, reset, IsOverridden());

            var allDefs = new[]
            {
                (icon: SasquatchIcons.Ids.AlignStartVertical, value: ImageAlignment.Left, tip: "Align left"),
                (icon: SasquatchIcons.Ids.AlignCenterVertical, value: ImageAlignment.Center, tip: "Align center"),
                (icon: SasquatchIcons.Ids.AlignEndVertical, value: ImageAlignment.Right, tip: "Align right"),
            };
            var defs = includeCenter ? allDefs : new[] { allDefs[0], allDefs[2] };
            var btns = new List<Button>();
            void Sync()
            {
                for (int i = 0; i < defs.Length; i++)
                {
                    bool active = get() == defs[i].value;
                    btns[i].style.backgroundColor = active ? DesignerPalette.AccentFillSoft : DesignerPalette.ButtonNeutralBg;
                    btns[i].Q<SasquatchIconElement>().Tint = active ? Color.white : DesignerPalette.IconIdle;
                }
            }
            foreach (var d in defs)
            {
                var val = d.value;
                var btn = new Button();
                btn.Add(SasquatchIcons.Create(d.icon, 13, DesignerPalette.IconIdle));
                btn.tooltip = d.tip;
                btn.style.width = 24; btn.style.height = 18;
                btn.style.paddingLeft = 0; btn.style.paddingRight = 0;
                btn.style.marginLeft = 2; btn.style.marginRight = 0;
                btn.style.alignItems = Align.Center; btn.style.justifyContent = Justify.Center;
                btn.clicked += () =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, undoLabel);
                    set(val);
                    OnModification();
                    RefreshPreview();
                    Sync();
                    SyncReset();
                };
                AddSegmentedHover(btn, () => get() == val, Sync);
                btns.Add(btn);
                buttons.Add(btn);
            }
            row.Add(buttons);

            void DoReset()
            {
                Undo.RecordObject(_clonedLayoutAsset, undoLabel);
                set(defaultValue);
                OnModification();
                RefreshPreview();
                Sync();
                SyncReset();
            }
            reset.clicked += DoReset;
            AddStyleResetContextMenu(row, IsOverridden, DoReset);
            row.Add(reset);

            Sync();
            SyncReset();
            return row;
        }

        // A 4-icon segmented placement picker (the same look as the Min/Max slider's "Field Placement"),
        // reusable for any small directional enum. Each option lights up on exact match; a ↺ reset appears
        // once the value differs from `defaultValue`. Returns the whole row so callers can still toggle its
        // visibility (style.display) exactly like the EnumField it replaces.
        private VisualElement BuildPlacementButtonRow<TEnum>(
            string label,
            (string icon, TEnum value, string tip)[] options,
            Func<TEnum> getter,
            Action<TEnum> setter,
            TEnum defaultValue,
            string undoLabel) where TEnum : struct, System.Enum
        {
            var row = new VisualElement();
            row.AddToClassList("unity-base-field");
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 2;

            var lbl = new Label(label);
            lbl.AddToClassList("unity-base-field__label");

            var buttonsContainer = new VisualElement();
            buttonsContainer.AddToClassList("unity-base-field__input");
            buttonsContainer.style.flexDirection = FlexDirection.Row;
            buttonsContainer.style.alignItems = Align.Center;
            buttonsContainer.style.flexGrow = 1;

            var reset = MakeStyleResetButton();
            bool IsOverridden() => !EqualityComparer<TEnum>.Default.Equals(getter(), defaultValue);
            void SyncReset() => ApplyOverrideChrome(buttonsContainer, reset, IsOverridden());

            var buttons = new List<Button>();
            void Sync()
            {
                for (int i = 0; i < options.Length; i++)
                {
                    bool active = EqualityComparer<TEnum>.Default.Equals(getter(), options[i].value);
                    buttons[i].style.backgroundColor = active ? DesignerPalette.AccentFillSoft : DesignerPalette.ButtonNeutralBg;
                    buttons[i].Q<SasquatchIconElement>().Tint = active ? Color.white : DesignerPalette.IconIdle;
                }
            }
            foreach (var opt in options)
            {
                var btn = new Button();
                btn.Add(SasquatchIcons.Create(opt.icon, 11, DesignerPalette.IconIdle));
                btn.tooltip = opt.tip;
                btn.style.width = 24; btn.style.height = 18;
                btn.style.paddingLeft = 0; btn.style.paddingRight = 0;
                btn.style.marginLeft = 2; btn.style.marginRight = 0;
                btn.style.alignItems = Align.Center;
                btn.style.justifyContent = Justify.Center;
                var captured = opt.value;
                btn.clicked += () =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, undoLabel);
                    setter(captured);
                    OnModification(); RefreshPreview(); Sync(); SyncReset();
                };
                AddSegmentedHover(btn, () => EqualityComparer<TEnum>.Default.Equals(getter(), captured), Sync);
                buttons.Add(btn);
                buttonsContainer.Add(btn);
            }

            void DoReset()
            {
                Undo.RecordObject(_clonedLayoutAsset, undoLabel);
                setter(defaultValue);
                OnModification(); RefreshPreview(); Sync(); SyncReset();
            }
            reset.clicked += DoReset;
            AddStyleResetContextMenu(row, IsOverridden, DoReset);

            row.Add(lbl);
            row.Add(buttonsContainer);
            row.Add(reset);
            Sync();
            SyncReset();
            return row;
        }

        // A hidden scratch object that gives the SerializedProperty-based gradient control something to bind to
        // (layout nodes are a [SerializeReference] graph with no SerializedProperty of their own).
        private sealed class ProgressGradientHolder : ScriptableObject
        {
            public Gradient gradient = new Gradient();
        }

        // Builds the "Fill Gradient" Expandable section for a progress bar's Value-Based Fill. Reuses the custom
        // SasquatchGradientControl by bridging the node's Gradient through a throwaway ScriptableObject, and
        // mirrors every edit back onto the node.
        private VisualElement BuildProgressFillGradientSection(BindingNode node)
        {
            var holder = ScriptableObject.CreateInstance<ProgressGradientHolder>();
            holder.hideFlags = HideFlags.HideAndDontSave;
            holder.gradient = CopyGradient(node.ProgressBarFillGradient);
            var holderSO = new SerializedObject(holder);
            var gradientProp = holderSO.FindProperty("gradient");

            // Reuse the FULL custom gradient editor — pin color/alpha popover, preset ribbon, ruler/snap, and
            // Blend/Fixed/Perceptual mode — in the Expandable group style, bridged onto the node's Gradient via the
            // scratch holder. The pop-out window button is omitted (includeExpand:false): the scratch holder can't
            // safely outlive this row, and a persistent window would dangle after a panel rebuild.
            var editor = BindingFactory.CreateGradientEditor(node, gradientProp, "Fill Gradient",
                forceMode: GradientEditorMode.Expandable, forceStartExpanded: true, includeExpand: false,
                forceEditable: true);

            // Mirror scratch → node on every real change. The node write is cheap and runs every tick (skip no-op
            // fires so merely viewing never dirties the asset). The EXPENSIVE settle work — marking the asset dirty /
            // auto-saving and rebuilding the WHOLE design canvas — is DEBOUNCED: dragging a pin fires this callback
            // continuously, and doing a full canvas rebuild each tick tore every field down mid-drag (the "fields go
            // blank / jerky" bug). Debouncing rebuilds once after the drag settles, and collapses the drag to a
            // single undo step. (The gradient strip itself repaints live inside the control — no rebuild needed.)
            IVisualElementScheduledItem gradientSettle = null;
            bool gradientUndoRecorded = false;
            editor.TrackPropertyValueWithRefresh(gradientProp, _ =>
            {
                if (GradientsEqual(holder.gradient, node.ProgressBarFillGradient)) return;
                if (!gradientUndoRecorded)
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Progress Fill Gradient");
                    gradientUndoRecorded = true;
                }
                node.ProgressBarFillGradient = CopyGradient(holder.gradient);
                MarkDirtyBeforeSettle(); // never lose the edit even if the panel rebuilds before the settle fires
                gradientSettle?.Pause();
                gradientSettle = editor.schedule.Execute(() =>
                {
                    gradientUndoRecorded = false;
                    OnModification(); // marks dirty/saves + one debounced canvas rebuild
                });
                gradientSettle.ExecuteLater(120);
            });

            // Destroy the scratch object when the row is torn down (rebuild / selection change) — no leak.
            // A REAL detach only: a re-parent (dragging the designer's own window tab re-parents its whole
            // tree) re-attaches this row, and killing the holder leaves the control bound to a dead
            // SerializedObject. See PanelLifetime.
            PanelLifetime.OnRealDetach(editor, () =>
            {
                if (holder != null) UnityEngine.Object.DestroyImmediate(holder);
            });

            return editor;
        }

        // Builds the "Overlay Gradient" Expandable section for a Frame's overlay wash. Same bridge as the
        // progress-bar fill gradient (scratch SO → SasquatchGradientControl), but targets FrameSettings and
        // live-pokes the canvas overlay in place each tick (re-baking its ramp) instead of a full rebuild.
        private VisualElement BuildFrameOverlayGradientSection(ContainerNode frameNode)
        {
            var frame = frameNode.Frame;
            var holder = ScriptableObject.CreateInstance<ProgressGradientHolder>(); // reused: a lone "gradient" field
            holder.hideFlags = HideFlags.HideAndDontSave;
            holder.gradient = CopyGradient(frame.OverlayGradient);
            var holderSO = new SerializedObject(holder);
            var gradientProp = holderSO.FindProperty("gradient");

            // A frame is a ContainerNode, but the gradient control is BindingNode-typed. A config-only
            // BindingNode carries the control's display options (checkerboard, pin layout, palette) at their
            // defaults — the same defaults a progress-bar node has, since neither sets Gradient-display options.
            var cfgNode = new BindingNode();

            var editor = BindingFactory.CreateGradientEditor(cfgNode, gradientProp, "Overlay Gradient",
                forceMode: GradientEditorMode.Expandable, forceStartExpanded: true, includeExpand: false,
                forceEditable: true);

            // Mirror scratch → frame on every real change. The node write + canvas re-bake are cheap and run
            // every tick (skip no-op fires so merely viewing never dirties the asset). The EXPENSIVE settle
            // (dirty/save + one debounced rebuild) is deferred, and the drag collapses to a single undo step —
            // the progress-fill precedent (a full rebuild per tick blanked every field mid-drag).
            IVisualElementScheduledItem gradientSettle = null;
            bool gradientUndoRecorded = false;
            editor.TrackPropertyValueWithRefresh(gradientProp, _ =>
            {
                if (GradientsEqual(holder.gradient, frame.OverlayGradient)) return;
                if (!gradientUndoRecorded)
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Change Frame Overlay Gradient");
                    gradientUndoRecorded = true;
                }
                frame.OverlayGradient = CopyGradient(holder.gradient);
                MarkDirtyBeforeSettle(); // never lose the edit even if the panel rebuilds before the settle fires
                // Re-bake the canvas overlay in place so colors track the drag (reuses its owned texture).
                LivePokeChild(_selectedNode, "sasq-frame-overlay", o => FrameBuilder.ApplyOverlayVisual(o, frame));
                gradientSettle?.Pause();
                gradientSettle = editor.schedule.Execute(() =>
                {
                    gradientUndoRecorded = false;
                    OnModification(); // marks dirty/saves + one debounced canvas rebuild
                });
                gradientSettle.ExecuteLater(120);
            });

            // Destroy the scratch object when the row is torn down (rebuild / selection change) — no leak.
            // A REAL detach only, for the same reason as the progress-fill row above (see PanelLifetime).
            PanelLifetime.OnRealDetach(editor, () =>
            {
                if (holder != null) UnityEngine.Object.DestroyImmediate(holder);
            });

            return editor;
        }

        private static Gradient CopyGradient(Gradient src)
        {
            var g = new Gradient();
            if (src != null) { g.mode = src.mode; g.SetKeys(src.colorKeys, src.alphaKeys); }
            return g;
        }

        private static bool GradientsEqual(Gradient a, Gradient b)
        {
            if (a == null || b == null) return ReferenceEquals(a, b);
            if (a.mode != b.mode) return false;
            var ac = a.colorKeys; var bc = b.colorKeys;
            if (ac.Length != bc.Length) return false;
            for (int i = 0; i < ac.Length; i++)
                if (ac[i].color != bc[i].color || !Mathf.Approximately(ac[i].time, bc[i].time)) return false;
            var aa = a.alphaKeys; var ba = b.alphaKeys;
            if (aa.Length != ba.Length) return false;
            for (int i = 0; i < aa.Length; i++)
                if (!Mathf.Approximately(aa[i].alpha, ba[i].alpha) || !Mathf.Approximately(aa[i].time, ba[i].time)) return false;
            return true;
        }

        // Override-state chrome shared by every style control: show the ↺ only when overridden, and dim the
        // field when it's inheriting the default so "untouched vs. set" reads at a glance.
        //
        // The dim is NOT a raw opacity write — UI Toolkit composites opacity PER ELEMENT, so on a Slider row
        // the track reads straight through the knob and it goes see-through (the same defect read-only
        // inspector sliders had, and this panel has ~50 slider rows). The helper rebuilds the identical dim
        // in colour on any row holding a slider, and falls back to the plain one-line write on the rest.
        private static void ApplyOverrideChrome(VisualElement field, Button reset, bool overridden)
        {
            reset.style.display = overridden ? DisplayStyle.Flex : DisplayStyle.None;
            BindingFactory.ApplyDimWithSolidKnobs(field, !overridden);
        }

        // A plain numeric field (IntegerField / FloatField, i.e. BaseField&lt;T&gt;) with the same ↺ + right-click
        // "Reset to default" affordance as the overridable style rows: the value IS the override, so the reset
        // button + dim chrome appear only when it differs from <paramref name="defaultValue"/>. The supplied
        // <paramref name="clamp"/> keeps edits in range. Used for the Enum Badge Columns / Height options.
        // "Restyle in place": find this node's ALREADY-RENDERED element on the canvas and mutate it directly,
        // so a drag shows instantly WITHOUT the full RefreshPreview teardown (which is what made dragging laggy).
        // The debounced value-edit commit still does one real rebuild afterward to reconcile bindings/conditions/
        // dependent widgets, so the quick poke only has to be visually right, not authoritative. No-op when the
        // node isn't currently on the canvas (other design/preview mode, scrolled out of a virtualized list, …).
        // Canvas elements carry userData == their LayoutNode (LayoutTreeBuilder), which is how we locate it.
        private void LivePokeCanvasElement(LayoutNode node, Action<VisualElement> poke)
        {
            if (_canvasContent == null || node == null || poke == null) return;
            var target = _canvasContent.Query<VisualElement>().Where(e => ReferenceEquals(e.userData, node)).First();
            if (target != null) poke(target);
        }

        // Generic live poke for a node's LayoutStyle (background / border / radius / margin / padding / size):
        // re-runs the SAME StyleApplier the builder uses, so a drag on any Appearance style row updates the
        // rendered card in place. In Design mode .First() returns the design-card WRAPPER (which is exactly where
        // the box decoration is transferred), in Live mode the element itself — both correct. Theme is null: only
        // the OVERRIDE styles (the ones being dragged) need re-applying; base-token styles didn't change. Reset
        // back to default is handled by the debounced rebuild (StyleApplier only sets, never clears).
        private void StyleLivePoke(LayoutNode node)
        {
            LivePokeCanvasElement(node, el =>
            {
                StyleApplier.Apply(el, node, null);
                // Frames: StyleApplier just rewrote radius/padding/alignment INLINE on the clip root.
                // None of those change layout, so the GeometryChanged-driven shape pass never fires and
                // the safe-area cropping (plus circle/pill radii) lagged the drag — snapping in only on
                // the debounced commit (the "release pop"). Re-run the fix-up + geometry now so the
                // canvas clip tracks the drag in real time, WYSIWYG.
                if (node is ContainerNode frameNode && frameNode.Type == ContainerType.Frame)
                    FrameBuilder.RefreshLiveGeometry(el, frameNode);
            });
        }

        // Poke a descendant (by USS class) of the node's rendered element — the common shape for widget-internal
        // live styling (progress track, curve/gradient well, enum badges, swatches, …). No-op if not found.
        private void LivePokeChild(LayoutNode node, string className, Action<VisualElement> poke)
        {
            LivePokeCanvasElement(node, el =>
            {
                var child = el.Q(className: className);
                if (child != null) poke(child);
            });
        }

        // Multi-target counterpart of LivePokeChild: poke EVERY matching descendant, not just the first.
        // Widgets that render one matching sub-element PER AXIS (Vector Sliders: one tracker/dragger per
        // axis slider) need the poke fanned to all of them — .Q()'s first-match meant a Track/Knob Color
        // drag animated only slider X live while Y/Z waited for the release reconcile. Same shape as the
        // multi-edit "only the primary node animates" bug (LiveRebuildSelectedNodes), fixed the same way.
        // Single-element widgets get the identical result either way, so callers with a fan-out CHANCE
        // should prefer this one.
        private void LivePokeChildren(LayoutNode node, string className, Action<VisualElement> poke)
        {
            LivePokeCanvasElement(node, el => el.Query(className: className).ForEach(poke));
        }

        // Poke the REAL gradient / curve well (height / border), skipping the mini header preview. In
        // ExpandableWithPreview mode the collapsed-header preview strip ALSO carries the widget's well class
        // (.sasq-gradient-well / .sasq-curve-well) and, being added to the tree first, is what a plain .Q() would
        // return — so a height / border drag would resize the PREVIEW and only snap the actual well on the debounced
        // commit. The real well is the one WITHOUT the *-preview class; poke that so the drag tracks the visible
        // well live in every editor mode.
        private void LivePokeGradientWell(LayoutNode node, Action<VisualElement> poke)
            => LivePokeWellSkippingPreview(node, "sasq-gradient-well", "sasq-gradient-preview", poke);

        private void LivePokeCurveWell(LayoutNode node, Action<VisualElement> poke)
            => LivePokeWellSkippingPreview(node, "sasq-curve-well", "sasq-curve-preview", poke);

        private void LivePokeWellSkippingPreview(LayoutNode node, string wellClass, string previewClass, Action<VisualElement> poke)
        {
            LivePokeCanvasElement(node, el =>
            {
                var well = el.Query(className: wellClass)
                             .Where(w => !w.ClassListContains(previewClass)).First();
                if (well != null) poke(well);
            });
        }

        // DisplayStyleData.cornerRadius rounds a DIFFERENT deep sub-element per widget kind (text input, slider /
        // min-max tracker, progress track+fill, toggle track+knob). Spray the radius onto every known target under
        // the node — only the ones that exist for the current widget take effect; the rest are harmless no-ops.
        private static readonly string[] WidgetRadiusTargets =
        {
            "unity-text-field__input", "unity-base-text-field__input",
            "sasq-progress-track", "sasq-progress-fill",
            "unity-base-slider__tracker", "unity-min-max-slider__tracker",
            "unity-toggle__input", "unity-toggle__checkmark",
        };
        private void LivePokeWidgetRadius(BindingNode node)
        {
            float r = Mathf.Max(0f, node.DisplayStyleData.cornerRadius.value);
            LivePokeCanvasElement(node, el =>
            {
                foreach (var cls in WidgetRadiusTargets)
                    el.Query(className: cls).ForEach(t =>
                    {
                        t.style.borderTopLeftRadius = r; t.style.borderTopRightRadius = r;
                        t.style.borderBottomLeftRadius = r; t.style.borderBottomRightRadius = r;
                    });
            });
        }

        // DisplayStyleData.accent tints the widget's primary element — clearest on slider draggers. Sprayed like
        // the radius; niche accent sinks (rating/badge, painted) reconcile on the debounced rebuild.
        private void LivePokeWidgetAccent(BindingNode node)
        {
            if (!node.DisplayStyleData.accent.isOverridden) return;
            var c = node.DisplayStyleData.accent.value;
            LivePokeCanvasElement(node, el =>
            {
                el.Query(className: "unity-base-slider__dragger").ForEach(d => d.style.backgroundColor = c);
                el.Query(className: "unity-min-max-slider__dragger").ForEach(d => d.style.backgroundColor = c);
            });
        }

        // FieldBackground paints the field's input container (ApplyFieldStyle → .unity-base-field__input bg).
        private void LivePokeFieldBackground(BindingNode node)
        {
            if (!node.FieldBackground.isOverridden) return;
            LivePokeCanvasElement(node, el =>
                el.Query(className: "unity-base-field__input").ForEach(i => i.style.backgroundColor = node.FieldBackground.value));
        }

        // The rendered Button for a ButtonNode's canvas element. Design mode hands back the design-card
        // WRAPPER and Live mode the Button itself, so both are covered; ButtonWidgetClass is stamped on
        // every button the builder makes, Classic included (which carries no preset class at all).
        private static Button FindCanvasButton(VisualElement el)
        {
            return el as Button ?? el.Q<Button>(className: LayoutTreeBuilder.ButtonWidgetClass);
        }

        // Drag-time resize of the rendered button: min-height plus the icon that scales with it, in place.
        // customHeight comes from the SLIDER, not the node — the model is still one tick behind during a drag.
        private void LivePokeButtonHeight(ButtonNode node, float customHeight)
        {
            LivePokeCanvasElement(node, el =>
            {
                var btn = FindCanvasButton(el);
                if (btn != null) LayoutTreeBuilder.ApplyButtonHeight(btn, node, customHeight);
            });
        }

        // Buttons apply their whole look (accent / radius / hover / pressed) via ApplyButtonChrome — re-run it
        // against the rendered button to reflect any button color/radius drag live.
        private void LivePokeButtonChrome(ButtonNode node)
        {
            LivePokeCanvasElement(node, el =>
            {
                var btn = FindCanvasButton(el);
                if (btn != null) LayoutTreeBuilder.ApplyButtonChrome(btn, node);
            });
        }

        // Universal live-poke fallback for continuous controls that have NO cheap in-place poke (painted widgets,
        // values baked into captured build locals, structural / multi-element changes): rebuild JUST the selected
        // node's element on the canvas via LayoutTreeBuilder.RebuildNodeInPlace — cheaper than the full
        // RefreshPreview teardown (~1/N), and it reproduces binding / conditions / drag / design-card exactly.
        // Reads _selectedNode LIVE (never captured) because EVERY Properties-panel continuous control edits the
        // selected node. Best-effort: no-op when the node isn't on the canvas (RebuildNodeInPlace returns false and
        // the debounced commit reconciles on release). This is what closes the "debounced-only" long tail without
        // hand-wiring a per-widget poke for each control.
        // Returns true when the node's element was found and rebuilt — the canvas then EXACTLY matches the
        // model (RebuildNodeInPlace re-runs the real BuildNode), which is what lets the drag commit skip its
        // redundant full-canvas rebuild (see _valueEditBurstLiveReconciled).
        private bool LiveRebuildSelectedNode()
        {
            if (_canvasContent == null || _selectedNode == null) return false;
            var target = _canvasContent.Query<VisualElement>().Where(e => ReferenceEquals(e.userData, _selectedNode)).First();
            return target != null && LayoutTreeBuilder.RebuildNodeInPlace(target);
        }

        // Multi-selection counterpart: an in-place rebuild of EVERY selected node's canvas element. A multi-edit
        // continuous drag fans its model write to the whole selection, so the whole selection must repaint live —
        // not just the primary (that was the "only one node animates while dragging" bug). Single-select leaves
        // _selectedNodes empty, so this falls back to the single primary — letting the value-edit machinery call
        // it unconditionally. Returns true only when every targeted node was found and rebuilt.
        private bool LiveRebuildSelectedNodes()
        {
            if (_selectedNodes.Count == 0) return LiveRebuildSelectedNode();
            if (_canvasContent == null) return false;
            bool all = true;
            foreach (var n in _selectedNodes)
            {
                if (n == null) continue;
                var target = _canvasContent.Query<VisualElement>().Where(e => ReferenceEquals(e.userData, n)).First();
                if (target == null || !LayoutTreeBuilder.RebuildNodeInPlace(target)) all = false;
            }
            return all;
        }

        // Every selected node EXCEPT the primary, rebuilt in place. The counterpart to a poke-based drag: the
        // control that just fired poked (or rebuilt) the primary's element on its own, but the followers the
        // multi-edit mirror just wrote to have nothing pointing at them — without this they hold last tick's
        // pixels until the release reconcile. Best-effort per node, exactly like LiveRebuildSelectedNodes.
        private void LiveRebuildFollowerNodes()
        {
            if (_canvasContent == null || _selectedNodes.Count == 0) return;
            foreach (var n in _selectedNodes)
            {
                if (n == null || ReferenceEquals(n, _selectedNode)) continue;
                var target = _canvasContent.Query<VisualElement>().Where(e => ReferenceEquals(e.userData, n)).First();
                if (target != null) LayoutTreeBuilder.RebuildNodeInPlace(target);
            }
        }

        /// <summary>
        /// A <see cref="ButtonSize"/> dropdown listing the sizes in VISUAL order (Small → Huge), each entry
        /// naming the height it renders at. A plain <c>EnumField</c> would list them in the enum's
        /// serialization-fixed order instead — Medium, Small, Large, Huge — which reads as noise on a
        /// size picker. Used by every button-size row (button, stepper −/+, normalize, multi-edit).
        /// </summary>
        private static PopupField<ButtonSize> MakeButtonSizeField(string label, ButtonSize current)
        {
            var choices = new List<ButtonSize>(LayoutTreeBuilder.ButtonSizeOrder);
            return new PopupField<ButtonSize>(label, choices, Mathf.Max(0, choices.IndexOf(current)),
                LayoutTreeBuilder.ButtonSizeLabel, LayoutTreeBuilder.ButtonSizeLabel);
        }

        // liveApply (optional): runs EVERY drag tick with the clamped value to poke the already-rendered canvas
        // element in place — instant visual feedback without the full RefreshPreview teardown. The debounced
        // commit still rebuilds afterward to reconcile everything. Wire it (via LivePokeCanvasElement) for any
        // control whose change maps cleanly to a live style tweak.
        private VisualElement CreateResettableNumberField<T>(
            BaseField<T> field, T defaultValue, Func<T> getter, Action<T> setter, Func<T, T> clamp, string undoLabel,
            Action<T> liveApply = null)
            where T : System.IEquatable<T>
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 4;
            field.style.flexGrow = 1;
            field.SetValueWithoutNotify(getter());

            var reset = MakeStyleResetButton();
            Func<bool> overridden = () => !getter().Equals(defaultValue);
            Action sync = () => ApplyOverrideChrome(field, reset, overridden());

            field.RegisterValueChangedCallback(evt =>
            {
                T v = clamp(evt.newValue);
                liveApply?.Invoke(v); // instant in-place canvas poke — immediate feedback, no teardown
                // Sliders/scrub fires this per drag tick — coalesce the undo + save + canvas rebuild.
                // Reset chrome syncs at COMMIT only: the ↺ shares the dragged row, and toggling it as the
                // value crosses the DEFAULT reflows the row under the held pointer (knob shift + value
                // perturbation = the crossing-default snap).
                HandleDebouncedValueEdit(undoLabel, () =>
                {
                    setter(v);
                }, onCommit: () => sync(), liveRebuild: liveApply == null);
            });
            FlushValueEditOnBlur(field);
            // Show the clamp — but not mid-keystroke, where it would eat the digit being typed (a row clamped
            // to [10..80] turned the "2" of "22" into 10 and landed the second "2" as 102 → 80).
            SyncClampedDisplay(field, getter);

            Action doReset = () =>
            {
                CommitPendingValueEdit(); // close any open drag burst before this discrete reset's own record
                Undo.RecordObject(_clonedLayoutAsset, undoLabel);
                setter(defaultValue);
                field.SetValueWithoutNotify(defaultValue);
                liveApply?.Invoke(defaultValue); // instant reset feedback too
                OnModification();
                sync();
            };
            reset.clicked += () => doReset();
            AddStyleResetContextMenu(row, overridden, doReset);

            row.Add(field);
            row.Add(reset);
            sync();
            return row;
        }

        // A simple "Allow … Adjust" toggle that flips a bool on the selected node (reads _selectedNode live so
        // it survives the working-clone re-resolve). The drag handle itself is wired in LayoutTreeBuilder.
        // `after` runs once the write has landed and the preview has been rebuilt — for the one row whose value
        // also changes how the HIERARCHY draws (Visible in Inspector greys its row), which the canvas-only
        // RefreshPreview does not cover.
        private VisualElement CreateAllowAdjustToggle(string label, string tooltip, Func<bool> getter, Action<bool> setter,
                                                      Action after = null)
        {
            var toggle = new Toggle(label);
            toggle.tooltip = tooltip;
            toggle.value = getter();
            toggle.RegisterValueChangedCallback(evt =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Toggle " + label);
                setter(evt.newValue);
                OnModification();
                RefreshPreview();
                after?.Invoke();
            });
            return toggle;
        }

        /// <summary>
        /// Whether the "In-Line Editor Rows" option can do anything for this collection — the SOLE gate, so
        /// the option is never offered where the renderer would ignore it. Three conditions: the elements are
        /// <see cref="UnityEngine.Object"/> references (there is no embedded inspector for an int), no
        /// <see cref="CollectionNode.ItemLayout"/> is designed (a template already decides what a row looks
        /// like, and it wins), and the collection renders as a List — a Table row is a grid of cells with
        /// nowhere to put an inspector.
        /// </summary>
        internal static bool SupportsInlineEditorRows(CollectionNode node, Type elementType, CollectionDisplayMode mode)
        {
            return node != null
                   && elementType != null
                   && typeof(UnityEngine.Object).IsAssignableFrom(elementType)
                   && node.ItemLayout == null
                   && mode == CollectionDisplayMode.List;
        }

        /// <summary>
        /// Whether this collection can carry an ELEMENT TEMPLATE — a binding on the element ITSELF, stored as
        /// a <see cref="BindingNode"/> with an empty <c>PropertyPath</c> in the item layout. The SOLE offer
        /// gate, so the affordance never appears where it would be redundant or inert.
        /// <para>
        /// It is the only way to style a list whose elements are ATOMIC: a <c>List&lt;Vector2&gt;</c> has no
        /// sub-field to hang a widget on, so without a template its rows are stuck at whatever Unity draws.
        /// An element WITH bindable sub-fields is excluded — the Bindings panel already lists those, and
        /// dropping one builds the very same item layout, so offering both would be two ways to say the same
        /// thing. Polymorphic (<c>[SerializeReference]</c>) elements are excluded too: each of those rows is a
        /// TYPE PICKER rather than a value, and a template would fight the picker instead of styling it.
        /// </para>
        /// Deliberately mode-agnostic. The item layout is mode-agnostic data — it is a Table's Value column
        /// and a List's row body — so a template authored in one mode has to survive a switch to the other.
        /// </summary>
        internal static bool SupportsElementTemplate(Type elementType, bool isManagedReference)
        {
            return !isManagedReference && SasquatchReflectionUtility.IsAtomicElementType(elementType);
        }

        /// <summary>
        /// The Bindings-panel token that stands for a collection's ELEMENT. Prefixed like the existing
        /// <c>Widget:</c> / <c>Property:</c> tokens because it is not a serialized path either — the drop
        /// handler reads the collection path back off it and seeds that collection's item layout.
        /// </summary>
        internal const string ElementTokenPrefix = "Element:";

        // Overridable float row, no override checkbox: editing the field IS the override; the ↺ button and
        // right-click → Reset (both shown only when overridden) clear it back to default.
        private VisualElement CreateOverridableFloatElement(
            string label,
            Func<OverridableFloat> getter,
            Action<OverridableFloat> setter,
            Action onValueChanged,
            Action liveApply = null,
            float minValue = float.NegativeInfinity)
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 4;

            var field = new FloatField(label);
            field.style.flexGrow = 1;
            field.SetValueWithoutNotify(getter().value);

            var reset = MakeStyleResetButton();
            void SyncReset() => ApplyOverrideChrome(field, reset, getter().isOverridden);

            field.RegisterValueChangedCallback(evt =>
            {
                // Scrubbing the field label fires this per drag tick — write the model + chrome live, coalesce
                // the caller's follow-up (usually a canvas RefreshPreview) into the settle-time commit.
                HandleDebouncedValueEdit("Modify Style Value", () =>
                {
                    var current = getter();
                    // Rows with a floor (font Size) clamp here rather than storing a number the renderer
                    // would have to refuse: the field starts at 0 and a single label-scrub tick is enough to
                    // latch the override, which is how a field's value text ended up an unreadable smear.
                    // Below the floor, "no size" is what was meant — drop back to unset.
                    float wanted = evt.newValue;
                    bool floored = !float.IsNegativeInfinity(minValue);
                    if (floored && wanted < minValue)
                    {
                        current.isOverridden = wanted > 0f; // a partial scrub still means "smaller", so clamp
                        current.value = current.isOverridden ? minValue : 0f;
                    }
                    else
                    {
                        current.value = wanted;
                        current.isOverridden = true; // editing = override
                    }
                    setter(current);
                    SyncReset();
                    liveApply?.Invoke(); // instant in-place canvas poke (model already written above)
                }, onValueChanged, liveRebuild: liveApply == null);
            });
            FlushValueEditOnBlur(field);
            // The box shows what was STORED — but never mid-keystroke, or typing "10" into the floored font
            // Size row would read the "1" as a clamp to 4 and land the "0" on top of it as 40.
            SyncClampedDisplay(field, () => getter().value);

            void DoReset()
            {
                CommitPendingValueEdit(); // close any open scrub burst before this discrete reset's own record
                Undo.RecordObject(_clonedLayoutAsset, "Reset Style Value");
                var current = getter();
                current.isOverridden = false;
                current.value = 0f;
                setter(current);
                field.SetValueWithoutNotify(0f);
                OnModification();
                onValueChanged?.Invoke();
                SyncReset();
            }

            reset.clicked += DoReset;
            AddStyleResetContextMenu(row, () => getter().isOverridden, DoReset);

            row.Add(field);
            row.Add(reset);
            SyncReset();
            return row;
        }

        // Unity-UI-Builder-style box spacing control (Margin / Padding). Collapsed, the single header field sets
        // all four sides at once (and shows the mixed-value dash when the sides differ); the triangle expands to
        // per-side Top/Right/Bottom/Left fields. Built as a plain row (not a Foldout) so the value field lays out
        // cleanly — a real foldout header forces the inspector's wide aligned-label and squeezes the field. The
        // expand triangle is a sized glyph (Unity's native checkmark image can't be reused standalone). Every
        // field follows the shared no-checkbox / ↺ + right-click reset + dim-when-inheriting pattern.
        private VisualElement CreateSpacingControl(
            string label,
            (string name, Func<OverridableFloat> get, Action<OverridableFloat> set)[] sides,
            Action onValueChanged,
            Action liveApply = null)
        {
            var container = new VisualElement();

            var header = new VisualElement();
            header.style.flexDirection = FlexDirection.Row;
            header.style.alignItems = Align.Center;
            // Same gap below the header as between the per-side rows, so the combined field
            // doesn't sit tighter against its first sub-row than the sub-rows do against each other.
            header.style.marginBottom = 4;

            var perSide = new VisualElement();
            perSide.style.display = DisplayStyle.None;
            // 16 = the header's arrow column (14 + 2 margin), so Top/Right/... labels start at
            // exactly the same x as "Margin"/"Padding".
            perSide.style.marginLeft = 16;

            // Foldout-style chevron, matching the SkinFoldout chevrons. Pickable because the
            // click handler is registered on the arrow itself.
            bool expanded = false;
            var arrow = SasquatchIcons.Create(SasquatchIcons.Ids.ChevronRight, 12, SasquatchIcons.FoldoutChevronTint);
            arrow.pickingMode = PickingMode.Position;
            arrow.style.width = 14;
            arrow.style.marginRight = 2;
            void SetExpanded(bool e)
            {
                expanded = e;
                EditorSpringFX.Fold(perSide, e);
                EditorSpringFX.SpringCaret(arrow, e);
            }
            arrow.RegisterCallback<ClickEvent>(_ => SetExpanded(!expanded));
            header.Add(arrow);

            var combined = new FloatField(label);
            combined.style.flexGrow = 1;
            combined.tooltip = "Sets all four sides. Expand for per-side control.";
            if (combined.labelElement != null)
            {
                combined.labelElement.style.width = 150;
                combined.labelElement.style.minWidth = 150;
            }
            header.Add(combined);

            var combinedReset = MakeStyleResetButton();
            header.Add(combinedReset);

            var perSideFields = new FloatField[sides.Length];
            var perSideResets = new Button[sides.Length];

            bool AnyOverridden()
            {
                foreach (var sd in sides) if (sd.get().isOverridden) return true;
                return false;
            }

            void Refresh()
            {
                bool uniform = true;
                var first = sides[0].get();
                for (int i = 0; i < sides.Length; i++)
                {
                    var v = sides[i].get();
                    if (v.value != first.value || v.isOverridden != first.isOverridden) uniform = false;
                    if (perSideFields[i] != null)
                    {
                        perSideFields[i].SetValueWithoutNotify(v.value);
                        ApplyOverrideChrome(perSideFields[i], perSideResets[i], v.isOverridden);
                    }
                }

                combined.showMixedValue = !uniform;
                if (uniform) combined.SetValueWithoutNotify(first.value);
                ApplyOverrideChrome(combined, combinedReset, AnyOverridden());
            }

            combined.RegisterValueChangedCallback(evt =>
            {
                // Scrubbing sets all four sides per tick — write + refresh live, coalesce save/rebuild.
                HandleDebouncedValueEdit("Modify " + label, () =>
                {
                    foreach (var sd in sides)
                    {
                        var c = sd.get();
                        c.value = evt.newValue;
                        c.isOverridden = true;
                        sd.set(c);
                    }
                    Refresh();
                    liveApply?.Invoke();
                }, onValueChanged, liveRebuild: liveApply == null);
            });
            FlushValueEditOnBlur(combined);

            void ResetAll()
            {
                CommitPendingValueEdit();
                Undo.RecordObject(_clonedLayoutAsset, "Reset " + label);
                foreach (var sd in sides)
                {
                    var c = sd.get();
                    c.isOverridden = false;
                    c.value = 0f;
                    sd.set(c);
                }
                OnModification();
                onValueChanged?.Invoke();
                Refresh();
            }
            combinedReset.clicked += ResetAll;
            AddStyleResetContextMenu(header, AnyOverridden, ResetAll);

            container.Add(header);

            for (int i = 0; i < sides.Length; i++)
            {
                int idx = i;
                var sideRow = new VisualElement();
                sideRow.style.flexDirection = FlexDirection.Row;
                sideRow.style.alignItems = Align.Center;
                sideRow.style.marginBottom = 4;

                var f = new FloatField(sides[idx].name);
                f.style.flexGrow = 1;
                // Same label width as the combined field: with perSide indented by the header's
                // 16px arrow column, both labels AND both value fields line up exactly.
                if (f.labelElement != null)
                {
                    f.labelElement.style.width = 150;
                    f.labelElement.style.minWidth = 150;
                }
                var r = MakeStyleResetButton();
                perSideFields[idx] = f;
                perSideResets[idx] = r;

                f.RegisterValueChangedCallback(evt =>
                {
                    HandleDebouncedValueEdit("Modify " + label, () =>
                    {
                        var c = sides[idx].get();
                        c.value = evt.newValue;
                        c.isOverridden = true;
                        sides[idx].set(c);
                        Refresh();
                        liveApply?.Invoke();
                    }, onValueChanged, liveRebuild: liveApply == null);
                });
                FlushValueEditOnBlur(f);

                void ResetSide()
                {
                    CommitPendingValueEdit();
                    Undo.RecordObject(_clonedLayoutAsset, "Reset " + label);
                    var c = sides[idx].get();
                    c.isOverridden = false;
                    c.value = 0f;
                    sides[idx].set(c);
                    OnModification();
                    onValueChanged?.Invoke();
                    Refresh();
                }
                r.clicked += ResetSide;
                AddStyleResetContextMenu(sideRow, () => sides[idx].get().isOverridden, ResetSide);

                sideRow.Add(f);
                sideRow.Add(r);
                perSide.Add(sideRow);
            }

            container.Add(perSide);
            SetExpanded(false);
            Refresh();
            return container;
        }

        // Overridable color row — same no-checkbox / ↺ + right-click reset pattern as the float row.
        private VisualElement CreateOverridableColorElement(
            string label,
            Func<OverridableColor> getter,
            Action<OverridableColor> setter,
            Action onValueChanged,
            Action liveApply = null)
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 4;

            var field = new ColorField(label);
            field.style.flexGrow = 1;

            var initialColor = getter().value;
            if (!getter().isOverridden && initialColor.a == 0f)
            {
                initialColor.a = 1f;
            }
            field.SetValueWithoutNotify(initialColor);

            var reset = MakeStyleResetButton();
            void SyncReset() => ApplyOverrideChrome(field, reset, getter().isOverridden);

            field.RegisterValueChangedCallback(evt =>
            {
                // Dragging inside the HSV picker fires this continuously — write the model + chrome live,
                // coalesce the caller's follow-up (usually a canvas RefreshPreview) into the settle commit.
                HandleDebouncedValueEdit("Modify Style Value", () =>
                {
                    var current = getter();
                    current.value = evt.newValue;
                    current.isOverridden = true;
                    setter(current);
                    SyncReset();
                    liveApply?.Invoke(); // instant in-place canvas poke (model already written above)
                }, onValueChanged, liveRebuild: liveApply == null);
            });
            FlushValueEditOnBlur(field);

            void DoReset()
            {
                CommitPendingValueEdit(); // close any open picker-drag burst before this discrete reset's record
                Undo.RecordObject(_clonedLayoutAsset, "Reset Style Value");
                var current = getter();
                current.isOverridden = false;
                current.value = default;
                setter(current);
                field.SetValueWithoutNotify(new Color(0f, 0f, 0f, 1f));
                OnModification();
                onValueChanged?.Invoke();
                SyncReset();
            }

            reset.clicked += DoReset;
            AddStyleResetContextMenu(row, () => getter().isOverridden, DoReset);

            row.Add(field);
            row.Add(reset);
            SyncReset();
            return row;
        }

        // Per-value tint/icon editor for the Enum Badge Grid: one row per distinct enum member (name + overridable
        // color + a compact icon pick button), persisted into node.EnumBadgeOverrides (upsert by underlying value;
        // an all-default entry is dropped so the array stays tidy). Returns a collapsed foldout, or a muted hint
        // when the bound field isn't a resolvable enum.
        private VisualElement BuildEnumBadgeOverridesEditor(BindingNode node, System.Type enumType)
        {
            if (enumType == null || !enumType.IsEnum)
            {
                var hint = new Label("Bind an enum field to style individual values.");
                hint.style.color = DesignerPalette.TextMuted;
                hint.style.whiteSpace = WhiteSpace.Normal;
                hint.style.marginTop = 2;
                return hint;
            }

            var foldout = new Foldout { text = "Per-Value Styling", value = false };
            foldout.tooltip = "Give individual enum values a custom active tint and/or a leading icon.";

            EnumBadgeOverride GetOv(int v)
            {
                var arr = node.EnumBadgeOverrides;
                if (arr != null) foreach (var o in arr) if (o.value == v) return o;
                return new EnumBadgeOverride { value = v, iconId = "" };
            }
            void SetOv(EnumBadgeOverride ov)
            {
                var list = new List<EnumBadgeOverride>(node.EnumBadgeOverrides ?? System.Array.Empty<EnumBadgeOverride>());
                int idx = list.FindIndex(o => o.value == ov.value);
                bool isDefault = !ov.color.isOverridden && string.IsNullOrEmpty(ov.iconId);
                if (isDefault) { if (idx >= 0) list.RemoveAt(idx); }
                else if (idx >= 0) list[idx] = ov;
                else list.Add(ov);
                node.EnumBadgeOverrides = list.ToArray();
            }

            var values = System.Enum.GetValues(enumType);
            var names = System.Enum.GetNames(enumType);
            var seen = new HashSet<int>();
            for (int i = 0; i < values.Length; i++)
            {
                int v;
                try { v = unchecked((int)System.Convert.ToInt64(values.GetValue(i))); }
                catch { try { v = unchecked((int)System.Convert.ToUInt64(values.GetValue(i))); } catch { continue; } }
                if (!seen.Add(v)) continue; // dedupe aliases / compound values

                int captured = v;
                // Same label the inspector shows for this member — [InspectorName] included. Authoring a
                // per-value tint/icon against a name the live field never displays is a quiet trap.
                string label = EnumMemberLabel.Resolve(enumType, names[i]);

                var row = CreateOverridableColorElement(label,
                    () => GetOv(captured).color,
                    c => { var o = GetOv(captured); o.color = c; SetOv(o); },
                    RefreshPreview);

                // Compact icon pick button, inserted before the color row's ↺ reset (its last child).
                var iconBtn = new Button { tooltip = "Pick a leading icon for this badge (right-click to clear)." };
                iconBtn.style.width = 22;
                iconBtn.style.height = 18;
                iconBtn.style.marginLeft = 4;
                iconBtn.style.alignItems = Align.Center;
                iconBtn.style.justifyContent = Justify.Center;
                void SyncIconBtn()
                {
                    iconBtn.Clear();
                    string cur = GetOv(captured).iconId;
                    if (!string.IsNullOrEmpty(cur)) { iconBtn.text = ""; iconBtn.Add(SasquatchIcons.Create(cur, 13f)); }
                    else iconBtn.text = "+";
                }
                iconBtn.clicked += () =>
                {
                    var choices = new List<string>(SasquatchIcons.AllIds);
                    UnityEditor.PopupWindow.Show(iconBtn.worldBound,
                        new SearchableDropdownPopup(null, "Badge Icon", choices, GetOv(captured).iconId,
                            sel =>
                            {
                                Undo.RecordObject(_clonedLayoutAsset, "Change Badge Icon");
                                var o = GetOv(captured); o.iconId = sel; SetOv(o);
                                SyncIconBtn(); OnModification(); RefreshPreview();
                            },
                            itemIcon: id => SasquatchIcons.Create(id, 14f), anchor: iconBtn));
                };
                iconBtn.AddManipulator(new ContextualMenuManipulator(m =>
                    m.menu.AppendAction("Clear Icon", _ =>
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Clear Badge Icon");
                        var o = GetOv(captured); o.iconId = ""; SetOv(o);
                        SyncIconBtn(); OnModification(); RefreshPreview();
                    })));
                SyncIconBtn();

                int insertAt = Mathf.Max(0, row.childCount - 1); // before the reset button
                row.Insert(insertAt, iconBtn);
                foldout.Add(row);
            }
            return foldout;
        }

        // Overridable enum row — same no-checkbox / ↺ + right-click reset pattern as the float/color rows.
        private VisualElement CreateOverridableEnumElement<T>(
            string label,
            Func<OverridableEnum<T>> getter,
            Action<OverridableEnum<T>> setter,
            Action onValueChanged) where T : struct, Enum
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 4;

            var field = new EnumField(label, getter().value);
            field.style.flexGrow = 1;

            var reset = MakeStyleResetButton();
            void SyncReset() => ApplyOverrideChrome(field, reset, getter().isOverridden);

            field.RegisterValueChangedCallback(evt =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Modify Style Value");
                var current = getter();
                current.value = (T)evt.newValue;
                current.isOverridden = true;
                setter(current);
                OnModification();
                onValueChanged?.Invoke();
                SyncReset();
            });

            void DoReset()
            {
                Undo.RecordObject(_clonedLayoutAsset, "Reset Style Value");
                var current = getter();
                current.isOverridden = false;
                current.value = default;
                setter(current);
                field.SetValueWithoutNotify(default(T));
                OnModification();
                onValueChanged?.Invoke();
                SyncReset();
            }

            reset.clicked += DoReset;
            AddStyleResetContextMenu(row, () => getter().isOverridden, DoReset);

            row.Add(field);
            row.Add(reset);
            SyncReset();
            return row;
        }

        // Friendly "Align in Parent" control (Left / Center / Right → alignSelf FlexStart/Center/FlexEnd).
        private VisualElement CreateAlignInParentControl()
        {
            return CreateSegmentedEnumControl(
                "Align in Parent",
                "How this element sits within its parent. (Distinct from a container's own child-alignment.)",
                new (string, string, Align)[]
                {
                    (SasquatchIcons.Ids.AlignStartVertical, "Align left in parent", Align.FlexStart),
                    (SasquatchIcons.Ids.AlignCenterVertical, "Center in parent", Align.Center),
                    (SasquatchIcons.Ids.AlignEndVertical, "Align right in parent", Align.FlexEnd)
                },
                () => _selectedNode.Style.alignSelf,
                v => { var s = _selectedNode.Style; s.alignSelf = v; _selectedNode.Style = s; },
                RefreshPreview);
        }

        // Generic segmented-button row for an OverridableEnum: a label + one button per option + ↺/right-click
        // reset. Setting a value IS the override; the ↺ (shown only when overridden) clears it; the group dims
        // while inheriting. Reads through the getter/setter live so it survives the working-clone re-resolve.
        private VisualElement CreateSegmentedEnumControl<T>(
            string label, string tooltip,
            (string icon, string tip, T value)[] options,
            Func<OverridableEnum<T>> getter, Action<OverridableEnum<T>> setter,
            Action onChanged) where T : struct, Enum
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 4;

            var lbl = new Label(label);
            if (!string.IsNullOrEmpty(tooltip)) lbl.tooltip = tooltip;
            lbl.style.flexGrow = 1;
            lbl.style.flexShrink = 1;
            // Match a BaseField label's measured metrics — see CreateFontStyleControl.
            lbl.style.marginLeft = 3;
            lbl.style.height = 18;
            lbl.style.paddingTop = 2;
            lbl.style.unityTextAlign = TextAnchor.UpperLeft; // measured: the theme's field labels are UpperLeft
            row.Add(lbl);

            var group = new VisualElement();
            group.style.flexDirection = FlexDirection.Row;
            group.style.flexShrink = 0;

            var buttons = new List<Button>();
            var reset = MakeStyleResetButton();
            var activeBg = DesignerPalette.AccentFillSoft;
            var idleBg = DesignerPalette.ButtonNeutralBg;

            void Sync()
            {
                var cur = getter();
                for (int i = 0; i < options.Length; i++)
                {
                    bool active = cur.isOverridden && EqualityComparer<T>.Default.Equals(cur.value, options[i].value);
                    buttons[i].style.backgroundColor = active ? activeBg : idleBg;
                    buttons[i].Q<SasquatchIconElement>().Tint = active ? Color.white : DesignerPalette.IconIdle;
                }
                reset.style.display = cur.isOverridden ? DisplayStyle.Flex : DisplayStyle.None;
                group.style.opacity = cur.isOverridden ? 1f : 0.5f;
            }

            void SetValue(T value)
            {
                Undo.RecordObject(_clonedLayoutAsset, "Change " + label);
                var cur = getter();
                cur.isOverridden = true;
                cur.value = value;
                setter(cur);
                OnModification();
                onChanged?.Invoke();
                Sync();
            }

            void DoReset()
            {
                Undo.RecordObject(_clonedLayoutAsset, "Reset " + label);
                var cur = getter();
                cur.isOverridden = false;
                cur.value = default;
                setter(cur);
                OnModification();
                onChanged?.Invoke();
                Sync();
            }

            foreach (var opt in options)
            {
                var btn = new Button { tooltip = opt.tip };
                btn.Add(SasquatchIcons.Create(opt.icon, 13, DesignerPalette.IconIdle));
                btn.style.width = 24;
                btn.style.height = 18;
                btn.style.marginLeft = 2;
                btn.style.marginRight = 0;
                btn.style.paddingLeft = 0;
                btn.style.paddingRight = 0;
                btn.style.alignItems = Align.Center;
                btn.style.justifyContent = Justify.Center;
                var captured = opt.value;
                btn.clicked += () => SetValue(captured);
                AddSegmentedHover(btn, () =>
                {
                    var c = getter();
                    return c.isOverridden && EqualityComparer<T>.Default.Equals(c.value, captured);
                }, Sync);
                buttons.Add(btn);
                group.Add(btn);
            }

            reset.clicked += DoReset;
            AddStyleResetContextMenu(row, () => getter().isOverridden, DoReset);

            row.Add(group);
            row.Add(reset);
            Sync();
            return row;
        }

        // Compact |< >< >| horizontal text-alignment control for a TextStyle.align (OverridableEnum<TextAnchor>).
        // Wears the square-button look shared by the designer's other alignment rows, while keeping the override
        // semantics: setting a value IS the override, the ↺ / right-click clears it, and the group dims while
        // inheriting the default.
        private VisualElement CreateTextAlignControl(string label, string tooltip,
            Func<OverridableEnum<TextAnchor>> getter, Action<OverridableEnum<TextAnchor>> setter, Action onChanged)
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 4;

            var lbl = new Label(label);
            if (!string.IsNullOrEmpty(tooltip)) lbl.tooltip = tooltip;
            lbl.style.flexGrow = 1;
            lbl.style.flexShrink = 1;
            // Match a BaseField label's measured metrics — see CreateFontStyleControl.
            lbl.style.marginLeft = 3;
            lbl.style.height = 18;
            lbl.style.paddingTop = 2;
            lbl.style.unityTextAlign = TextAnchor.UpperLeft; // measured: the theme's field labels are UpperLeft
            row.Add(lbl);

            var group = new VisualElement();
            group.style.flexDirection = FlexDirection.Row;
            group.style.flexShrink = 0;

            var reset = MakeStyleResetButton();
            var activeBg = DesignerPalette.AccentFillSoft;
            var idleBg = DesignerPalette.ButtonNeutralBg;

            var options = new (string icon, TextAnchor value, string tip)[]
            {
                (SasquatchIcons.Ids.AlignLeft, TextAnchor.MiddleLeft, "Align text left"),
                (SasquatchIcons.Ids.AlignCenter, TextAnchor.MiddleCenter, "Align text center"),
                (SasquatchIcons.Ids.AlignRight, TextAnchor.MiddleRight, "Align text right"),
            };
            var buttons = new List<Button>();

            void Sync()
            {
                var cur = getter();
                for (int i = 0; i < options.Length; i++)
                {
                    bool active = cur.isOverridden && cur.value == options[i].value;
                    buttons[i].style.backgroundColor = active ? activeBg : idleBg;
                    buttons[i].Q<SasquatchIconElement>().Tint = active ? Color.white : DesignerPalette.IconIdle;
                }
                reset.style.display = cur.isOverridden ? DisplayStyle.Flex : DisplayStyle.None;
                group.style.opacity = cur.isOverridden ? 1f : 0.5f;
            }

            void SetValue(TextAnchor value)
            {
                Undo.RecordObject(_clonedLayoutAsset, "Change " + label);
                var cur = getter();
                cur.isOverridden = true;
                cur.value = value;
                setter(cur);
                OnModification();
                onChanged?.Invoke();
                Sync();
            }

            void DoReset()
            {
                Undo.RecordObject(_clonedLayoutAsset, "Reset " + label);
                var cur = getter();
                cur.isOverridden = false;
                cur.value = default;
                setter(cur);
                OnModification();
                onChanged?.Invoke();
                Sync();
            }

            foreach (var opt in options)
            {
                var btn = new Button { tooltip = opt.tip };
                btn.Add(SasquatchIcons.Create(opt.icon, 13, DesignerPalette.IconIdle));
                btn.style.width = 24;
                btn.style.height = 18;
                btn.style.paddingLeft = 0;
                btn.style.paddingRight = 0;
                btn.style.marginLeft = 2;
                btn.style.marginRight = 0;
                btn.style.alignItems = Align.Center;
                btn.style.justifyContent = Justify.Center;
                var captured = opt.value;
                btn.clicked += () => SetValue(captured);
                AddSegmentedHover(btn, () =>
                {
                    var c = getter();
                    return c.isOverridden && c.value == captured;
                }, Sync);
                buttons.Add(btn);
                group.Add(btn);
            }

            reset.clicked += DoReset;
            AddStyleResetContextMenu(row, () => getter().isOverridden, DoReset);

            row.Add(group);
            row.Add(reset);
            Sync();
            return row;
        }

        // Optional custom-font picker for a TextStyle.font (an ObjectField restricted to Font assets). null =
        // inherit the default font; the ↺ / right-click clears it; the field dims while inheriting — the same
        // convention as the other text-style controls.
        private VisualElement CreateFontControl(Func<TextStyle> get, Action<TextStyle> set, Action onChanged)
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 4;

            var fontField = new ObjectField("Font") { objectType = typeof(Font), allowSceneObjects = false };
            fontField.tooltip = "A custom font for this text. Leave empty to use the default font.";
            fontField.style.flexGrow = 1;
            fontField.style.flexShrink = 1;
            fontField.SetValueWithoutNotify(get().font);

            var reset = MakeStyleResetButton();

            void Sync()
            {
                bool has = get().font != null;
                reset.style.display = has ? DisplayStyle.Flex : DisplayStyle.None;
                fontField.style.opacity = has ? 1f : 0.5f;
            }

            fontField.RegisterValueChangedCallback(evt =>
            {
                Undo.RecordObject(_clonedLayoutAsset, "Change Font");
                var ts = get();
                ts.font = evt.newValue as Font;
                set(ts);
                OnModification();
                onChanged?.Invoke();
                Sync();
            });

            void DoReset()
            {
                Undo.RecordObject(_clonedLayoutAsset, "Reset Font");
                var ts = get();
                ts.font = null;
                set(ts);
                fontField.SetValueWithoutNotify(null);
                OnModification();
                onChanged?.Invoke();
                Sync();
            }
            reset.clicked += DoReset;
            AddStyleResetContextMenu(row, () => get().font != null, DoReset);

            row.Add(fontField);
            row.Add(reset);
            Sync();
            return row;
        }

        // Bold / Italic toggle pair driving a TextStyle.fontStyle (via get/set), mirroring the segmented
        // control's override / reset / dim behavior. `onChanged` runs after each edit.
        private VisualElement CreateFontStyleControl(Func<TextStyle> get, Action<TextStyle> set, Action onChanged)
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 4;

            var lbl = new Label("Style");
            lbl.style.flexGrow = 1;
            lbl.style.flexShrink = 1;
            // Match a BaseField label's measured metrics (3px root margin, 18px box, 2px top
            // padding, upper-left text) so this bare label lines up with the Size/Color/Font
            // field rows around it instead of sitting 3px left and a pixel high.
            lbl.style.marginLeft = 3;
            lbl.style.height = 18;
            lbl.style.paddingTop = 2;
            lbl.style.unityTextAlign = TextAnchor.UpperLeft; // measured: the theme's field labels are UpperLeft
            row.Add(lbl);

            var group = new VisualElement();
            group.style.flexDirection = FlexDirection.Row;
            group.style.flexShrink = 0;

            var reset = MakeStyleResetButton();
            var activeBg = DesignerPalette.AccentFill;
            var idleBg = DesignerPalette.ButtonNeutralBg;

            var boldBtn = new Button { text = "B" };
            boldBtn.style.unityFontStyleAndWeight = FontStyle.Bold;
            var italicBtn = new Button { text = "I" };
            italicBtn.style.unityFontStyleAndWeight = FontStyle.Italic;
            foreach (var b in new[] { boldBtn, italicBtn })
            {
                b.style.width = 24;
                b.style.height = 18;
                b.style.fontSize = 11;
                b.style.marginLeft = 2;
                b.style.marginRight = 0;
                b.style.paddingLeft = 0;
                b.style.paddingRight = 0;
            }

            bool CurBold() { var fs = get().fontStyle; return fs.isOverridden && (fs.value == FontStyle.Bold || fs.value == FontStyle.BoldAndItalic); }
            bool CurItalic() { var fs = get().fontStyle; return fs.isOverridden && (fs.value == FontStyle.Italic || fs.value == FontStyle.BoldAndItalic); }

            void Sync()
            {
                bool overridden = get().fontStyle.isOverridden;
                bool bold = CurBold(), italic = CurItalic();
                boldBtn.style.backgroundColor = bold ? activeBg : idleBg;
                boldBtn.style.color = bold ? Color.white : DesignerPalette.IconIdle;
                italicBtn.style.backgroundColor = italic ? activeBg : idleBg;
                italicBtn.style.color = italic ? Color.white : DesignerPalette.IconIdle;
                reset.style.display = overridden ? DisplayStyle.Flex : DisplayStyle.None;
                group.style.opacity = overridden ? 1f : 0.5f;
            }

            void SetBoldItalic(bool bold, bool italic)
            {
                var fsv = bold && italic ? FontStyle.BoldAndItalic : bold ? FontStyle.Bold : italic ? FontStyle.Italic : FontStyle.Normal;
                Undo.RecordObject(_clonedLayoutAsset, "Change Font Style");
                var ts = get();
                var cur = ts.fontStyle;
                cur.isOverridden = true;
                cur.value = fsv;
                ts.fontStyle = cur;
                set(ts);
                OnModification();
                onChanged?.Invoke();
                Sync();
            }

            void DoReset()
            {
                Undo.RecordObject(_clonedLayoutAsset, "Reset Font Style");
                var ts = get();
                var cur = ts.fontStyle;
                cur.isOverridden = false;
                cur.value = FontStyle.Normal;
                ts.fontStyle = cur;
                set(ts);
                OnModification();
                onChanged?.Invoke();
                Sync();
            }

            boldBtn.clicked += () => SetBoldItalic(!CurBold(), CurItalic());
            italicBtn.clicked += () => SetBoldItalic(CurBold(), !CurItalic());
            reset.clicked += DoReset;
            AddStyleResetContextMenu(row, () => get().fontStyle.isOverridden, DoReset);

            AddSegmentedHover(boldBtn, CurBold, Sync);
            AddSegmentedHover(italicBtn, CurItalic, Sync);

            group.Add(boldBtn);
            group.Add(italicBtn);
            row.Add(group);
            row.Add(reset);
            Sync();
            return row;
        }

        // The four text-styling controls (Style B/I · Size · Color · Align) bound to one TextStyle via get/set.
        private VisualElement BuildTextStylePanel(Func<TextStyle> get, Action<TextStyle> set, Action onChanged)
        {
            var panel = new VisualElement();
            panel.Add(CreateFontStyleControl(get, set, onChanged));
            // Floored at the renderer's readable minimum — this row is the ONE place a font size is authored,
            // and below the floor a run of glyphs stops being text (see TextStyleApplier.MinReadableFontSize).
            panel.Add(CreateOverridableFloatElement("Size", () => get().fontSize, val => { var ts = get(); ts.fontSize = val; set(ts); },
                onChanged, minValue: TextStyleApplier.MinReadableFontSize));
            panel.Add(CreateOverridableColorElement("Color", () => get().color, val => { var ts = get(); ts.color = val; set(ts); }, onChanged));
            panel.Add(CreateFontControl(get, set, onChanged));
            panel.Add(CreateTextAlignControl(
                "Alignment", "Horizontal alignment of this text.",
                () => get().align,
                v => { var ts = get(); ts.align = v; set(ts); },
                onChanged));
            return panel;
        }

        // Wraps a Properties text-entry field with a "T" button that toggles an attached, boxed text-styling
        // panel for THAT specific text. The T is accented when the text has any override; opening the panel
        // briefly flashes the matching text in the canvas (previewRole identifies which element to flash).
        // The shared "?" card for every markdown-capable text row (Message, Summary Text, Help Text, Text
        // Block): documents BOTH syntaxes those boxes render, written in the very markdown it documents —
        // literal syntax sits in `code` chips (a code span's contents are never parsed, and CodeHighlighter
        // defangs '<'), while each "→" result renders live as proof.
        private const string RichTextFormattingHelp =
            "Renders **markdown** and Unity **rich text** tags.\n" +
            "\n" +
            "**Markdown**\n" +
            "`**bold**` → **bold**\n" +
            "`*italics*` → *italics*\n" +
            "\\`code\\` → `code`\n" +
            "`{Red|text}` or `{#FF8800|text}` → {#FF8800|text}\n" +
            "`[label](https://url)` → a clickable link\n" +
            "\\`\\`\\` alone on a line opens/closes a code block\n" +
            "\n" +
            "**Rich text tags**\n" +
            "`<b>` `<i>` `<u>` `<s>` `<size=14>` `<color=#4EC9B0>` …\n" +
            "`<b><color=#4EC9B0>ready</color></b>` → <b><color=#4EC9B0>ready</color></b>\n" +
            "\n" +
            "Escape a marker to show it literally: `\\**` `\\<b>`.\n" +
            "Turn *Render Markdown* off to show text exactly as typed.";

        // ---- Preset Editor: rows whose STYLE travels but whose TEXT does not -------------------------------
        // A preset carries styling only. For a field-type preset that rule is LayoutPresetApplier.ClearIdentity
        // (it strips path/label/header/tooltip/conditions/animations/sizing); for a widget preset it's
        // StyleClipboard's per-kind transfer lists (an allow-list — anything absent is dropped on capture).
        // Either way an editable text box in the Preset Editor is pure noise: whatever the user types is thrown
        // away the moment the preset is captured. But the text's STYLE (LabelTextStyle / HeaderTextStyle /
        // TitleTextStyle / …) IS in both lists, and it matters — every imported field gets a label, a script
        // [Header] becomes a header — so the row can't just be deleted. This builds the same row minus the input:
        // label column, a muted note saying why, and the SAME "T" style button.
        private VisualElement BuildPresetTextStyleRow(string label, string note,
            Func<TextStyle> get, Action<TextStyle> set, string previewRole)
        {
            var row = new VisualElement();
            row.AddToClassList("unity-base-field"); // rides the theme's label column, like a real field row
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.marginBottom = 2;

            var rowLabel = new Label(label);
            rowLabel.AddToClassList("unity-base-field__label");
            row.Add(rowLabel);

            var hint = new Label(note);
            hint.AddToClassList("unity-base-field__input");
            hint.style.flexGrow = 1;
            hint.style.flexShrink = 1;
            hint.style.fontSize = 10f;
            hint.style.color = DesignerPalette.TextDisabled;
            hint.style.unityFontStyleAndWeight = FontStyle.Italic;
            hint.style.whiteSpace = WhiteSpace.Normal;
            row.Add(hint);

            return WithTextButton(row, get, set, previewRole);
        }

        /// <param name="onTextStyleChanged">Runs after an edit inside the T panel, alongside the preview
        /// refresh. For chrome that depends on WHAT the text style holds (the ON/OFF contrast warning) —
        /// a colour edit moves no geometry, so the Properties skin pass never sees it.</param>
        private VisualElement WithTextButton(VisualElement field, Func<TextStyle> get, Action<TextStyle> set, string previewRole,
            string helpText = null, Func<bool> tExtraVisible = null, Action onTextStyleChanged = null)
        {
            var wrapper = new VisualElement();

            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;

            // Transfer bottom margin from field to the row container so that elements align vertically cleanly.
            if (field.style.marginBottom != StyleKeyword.Null && field.style.marginBottom != StyleKeyword.Auto)
            {
                row.style.marginBottom = field.style.marginBottom;
                field.style.marginBottom = 0;
            }

            field.style.flexGrow = 1;
            row.Add(field);

            var tBtn = new Button { text = "T" };
            tBtn.tooltip = "Style this text (bold, italic, size, color, alignment)";
            OverridableTextRow.StyleAsFieldButton(tBtn);
            tBtn.style.unityFontStyleAndWeight = FontStyle.Bold;
            row.Add(tBtn);
            wrapper.Add(row);

            // Optional "?" help chip (the shared SasquatchHelpChip pattern): sits after the T button, reveals
            // a card directly under the row. Used by the Message / Summary Text rows to document the markdown
            // + rich-text syntax those boxes render.
            if (!string.IsNullOrEmpty(helpText))
            {
                var help = SasquatchHelpChip.Build(helpText, tooltip: "Formatting help");
                help.Chip.style.marginLeft = 2; // match the T button's spacing rhythm
                row.Add(help.Chip);
                wrapper.Add(help.Card);
            }

            var panel = new VisualElement();
            panel.style.display = DisplayStyle.None;
            panel.style.marginLeft = 6;
            panel.style.marginTop = 2;
            panel.style.marginBottom = 4;
            panel.style.paddingTop = 4;
            panel.style.paddingBottom = 2;
            panel.style.paddingLeft = 6;
            panel.style.paddingRight = 4;
            var edge = DesignerPalette.TextPanelEdge;
            panel.style.borderLeftWidth = 2;
            panel.style.borderTopWidth = 1;
            panel.style.borderRightWidth = 1;
            panel.style.borderBottomWidth = 1;
            panel.style.borderLeftColor = edge;
            panel.style.borderTopColor = edge;
            panel.style.borderRightColor = edge;
            panel.style.borderBottomColor = edge;
            panel.style.borderTopLeftRadius = 3;
            panel.style.borderTopRightRadius = 3;
            panel.style.borderBottomLeftRadius = 3;
            panel.style.borderBottomRightRadius = 3;

            void SyncT()
            {
                bool has = TextStyleApplier.HasAnyOverride(get());
                tBtn.style.color = has ? DesignerPalette.LinkText : DesignerPalette.TextButton;
            }

            panel.Add(BuildTextStylePanel(get, set, () => { RefreshPreview(); SyncT(); onTextStyleChanged?.Invoke(); }));
            wrapper.Add(panel);
            SyncT();

            // Re-open a box the user had open before this rebuild. The panel's open state is pure element
            // state, so EVERY RefreshProperties used to slam it shut — including the one a manual Save runs,
            // which is what made styling a title and saving mutually exclusive. Keyed by previewRole: it is
            // already unique within any one node's panel (it has to be — it also identifies which canvas text
            // the box flashes), and RefreshProperties clears the set whenever the panel changes node.
            bool reopen = !string.IsNullOrEmpty(previewRole) && _openTextStylePanels.Contains(previewRole);
            if (reopen)
            {
                panel.style.display = DisplayStyle.Flex;
                tBtn.style.backgroundColor = DesignerPalette.AccentFill;
            }

            if (field is Toggle toggleField)
            {
                // The T shows only while the gating toggle is ON and, when a caller supplies tExtraVisible,
                // while that predicate also holds — Min/Max hides it once "Editable Values" turns the read-outs
                // into number fields (which get their own "Field Styling" section instead). Panels that change
                // tExtraVisible's inputs rebuild via RefreshProperties, so this is re-evaluated on each build;
                // the toggle callback just keeps it correct within one build.
                void SyncTVisibility()
                {
                    bool show = toggleField.value && (tExtraVisible == null || tExtraVisible());
                    tBtn.style.display = show ? DisplayStyle.Flex : DisplayStyle.None;
                    if (!show)
                    {
                        panel.style.display = DisplayStyle.None;
                        tBtn.style.backgroundColor = DesignerPalette.ButtonNeutralBg;
                        // The row itself is gone, so the box is genuinely closed — forget it, or turning the
                        // gate back on would spring a panel open that the user never re-opened.
                        if (!string.IsNullOrEmpty(previewRole)) _openTextStylePanels.Remove(previewRole);
                    }
                }
                SyncTVisibility();
                toggleField.RegisterValueChangedCallback(evt => SyncTVisibility());
            }

            tBtn.clicked += () =>
            {
                bool open = panel.style.display == DisplayStyle.None;
                panel.style.display = open ? DisplayStyle.Flex : DisplayStyle.None;
                tBtn.style.backgroundColor = open ? DesignerPalette.AccentFill : DesignerPalette.ButtonNeutralBg;
                if (!string.IsNullOrEmpty(previewRole))
                {
                    if (open) _openTextStylePanels.Add(previewRole);
                    else _openTextStylePanels.Remove(previewRole);
                }
                SyncT();
                if (open) FlashPreviewText(previewRole);
            };

            return wrapper;
        }

        // Briefly highlights the selected node's matching text element in the canvas preview, so it's obvious
        // which text a "T" panel edits. previewRole maps to the class the builder tags that text with.
        private void FlashPreviewText(string previewRole)
        {
            if (_canvasContent == null || _selectedNode == null) return;

            VisualElement nodeEl = null;
            _canvasContent.Query<VisualElement>().ForEach(e => { if (nodeEl == null && ReferenceEquals(e.userData, _selectedNode)) nodeEl = e; });
            if (nodeEl == null) return;

            string cls = previewRole switch
            {
                "header" => "sasq-field-header",
                "label" => "unity-base-field__label",
                "field" => "unity-base-field__input",
                "title" => "sasq-node-title",
                "collheader" => "sasq-collection-header",
                "message" => "sasq-helpbox-message",
                "helpBoxSummary" => "sasq-help-expand-summary",
                "toggleOnOff" => "sq-toggle-onoff-label",
                "scriptHeaderTitle" => "sasq-script-header-title",
                "minMaxLabel" => "sq-minmax-label",
                _ => null
            };
            VisualElement target = cls != null ? nodeEl.Q<VisualElement>(className: cls) : null;
            // Fall back to known title classes (containers vary) or the node element itself (e.g. a button).
            if (target == null && previewRole == "title")
                target = nodeEl.Q<VisualElement>(className: "sasq-flow-header") ?? nodeEl.Q<VisualElement>(className: "sasq-group-title");
            if (target == null) target = nodeEl;

            var flash = DesignerPalette.FlashWash;
            target.style.backgroundColor = flash;
            target.schedule.Execute(() => target.style.backgroundColor = StyleKeyword.Null).ExecuteLater(450);
        }

        private void CancelActiveScrollRestoration(ScrollView scrollView)
        {
            if (scrollView == null) return;
            if (_activeScrollRestorations.TryGetValue(scrollView, out var state))
            {
                if (state.ScheduledItem != null)
                {
                    state.ScheduledItem.Pause();
                }
                if (state.OnGeom != null && scrollView.contentContainer != null)
                {
                    scrollView.contentContainer.UnregisterCallback(state.OnGeom);
                }
                if (state.CleanupScheduledItem != null)
                {
                    state.CleanupScheduledItem.Pause();
                }
                _activeScrollRestorations.Remove(scrollView);
            }
        }

        private void RestoreScrollOffsetRobust(ScrollView scrollView, Vector2 scrollPos)
        {
            if (scrollView == null) return;

            CancelActiveScrollRestoration(scrollView);

            scrollView.scrollOffset = scrollPos;

            var state = new ScrollRestorationState { Target = scrollPos };

            // One guarded re-apply. Returns false once the user has taken the scroll back, which tears the whole
            // restoration down — the timer, the geometry hook and the table entry — so nothing can touch the
            // offset again. See DecideScrollGuard for why "moved down" is unconditionally the user.
            Func<bool> apply = () =>
            {
                if (scrollView.panel == null) return false;
                float max = Mathf.Max(0f,
                    scrollView.contentContainer.layout.height - scrollView.contentViewport.layout.height);
                bool sawClamp = state.SawClamp;
                var decision = DecideScrollGuard(
                    scrollView.scrollOffset.y, state.Target.y, max, state.Frame, ref sawClamp);
                state.SawClamp = sawClamp;

                if (decision == ScrollGuardDecision.StandDown) return false;
                if (decision == ScrollGuardDecision.Write) scrollView.scrollOffset = state.Target;
                return true;
            };

            EventCallback<GeometryChangedEvent> onGeom = evt =>
            {
                if (!apply()) CancelActiveScrollRestoration(scrollView);
            };
            scrollView.contentContainer.RegisterCallback(onGeom);
            state.OnGeom = onGeom;

            IVisualElementScheduledItem scheduledItem = null;
            scheduledItem = scrollView.schedule.Execute(() =>
            {
                if (!apply())
                {
                    CancelActiveScrollRestoration(scrollView);
                    return;
                }
                state.Frame++;
                if (state.Frame > ScrollRestoreMaxReapplyFrames)
                {
                    scheduledItem?.Pause();
                }
            }).Every(ScrollRestoreReapplyIntervalMs);
            state.ScheduledItem = scheduledItem;

            IVisualElementScheduledItem cleanupItem = scrollView.schedule.Execute(() =>
            {
                if (scrollView != null && scrollView.contentContainer != null)
                {
                    scrollView.contentContainer.UnregisterCallback(onGeom);
                }
                if (_activeScrollRestorations.TryGetValue(scrollView, out var s) && s == state)
                {
                    _activeScrollRestorations.Remove(scrollView);
                }
            });
            cleanupItem.ExecuteLater(ScrollRestoreCleanupMs);
            state.CleanupScheduledItem = cleanupItem;

            _activeScrollRestorations[scrollView] = state;
        }

        /// <summary>
        /// The offset to restore a panel to after rebuilding it — i.e. the user's TRUE scroll position.
        ///
        /// <para>NOT simply <c>scrollView.scrollOffset</c>. If the PREVIOUS rebuild's restoration is still in
        /// flight (rapid edits: the 120ms preview debounce fires well inside the restoration window), the live
        /// offset may read CLAMPED — the rebuilt content is mid-relayout and shorter than its final height, so a
        /// bottom-of-panel offset comes back smaller. Capturing that made the canvas jump up ~a third of a page
        /// while typing fast into Label/Header/Tooltip, and made Properties walk upward while clicking through
        /// the Conditions section. The in-flight restoration's Target is the true offset.</para>
        ///
        /// <para>Every panel rebuild must capture through here. RefreshProperties used to read the live offset
        /// directly and had exactly the drift this exists to prevent.</para>
        /// </summary>
        private Vector2 CaptureScrollOffset(ScrollView scrollView)
        {
            if (scrollView == null) return Vector2.zero;
            return _activeScrollRestorations.TryGetValue(scrollView, out var activeRestoration)
                ? activeRestoration.Target
                : scrollView.scrollOffset;
        }

        private void PreserveScroll(ScrollView scrollView, Action rebuildAction)
        {
            if (scrollView == null)
            {
                rebuildAction();
                return;
            }

            if (_disableScrollPreservation)
            {
                rebuildAction();
                return;
            }

            var scrollPos = CaptureScrollOffset(scrollView);
            if (scrollView == _hierarchyContainer && _scrollToBottomOnHierarchyRefresh)
            {
                scrollPos = new Vector2(scrollPos.x, float.MaxValue);
                _scrollToBottomOnHierarchyRefresh = false;
            }

            rebuildAction();

            RestoreScrollOffsetRobust(scrollView, scrollPos);
        }

        // The blank-canvas "pick a script" card shown when no type is loaded (see RefreshPreview's null-clone
        // branch). Centered in the canvas, it's the sole entry affordance for a menu-opened, target-less window
        // — so someone whose inspector header is owned by a third-party asset can still reach the designer.
        private VisualElement BuildBlankStatePickerCard()
        {
            var card = new VisualElement();
            card.style.alignSelf = Align.Center;
            card.style.marginTop = 60;
            card.style.alignItems = Align.Center;
            card.style.paddingTop = 26; card.style.paddingBottom = 26;
            card.style.paddingLeft = 34; card.style.paddingRight = 34;
            card.style.backgroundColor = DesignerPalette.CardBg;
            card.style.borderTopLeftRadius = 8; card.style.borderTopRightRadius = 8;
            card.style.borderBottomLeftRadius = 8; card.style.borderBottomRightRadius = 8;
            var border = DesignerPalette.ToolCardBorder;
            card.style.borderTopWidth = 1; card.style.borderBottomWidth = 1;
            card.style.borderLeftWidth = 1; card.style.borderRightWidth = 1;
            card.style.borderTopColor = border; card.style.borderBottomColor = border;
            card.style.borderLeftColor = border; card.style.borderRightColor = border;

            var icon = SasquatchIcons.Create(SasquatchIcons.Ids.PencilRuler, 34, DesignerPalette.AccentFill);
            icon.style.marginBottom = 12;
            card.Add(icon);

            var title = new Label("Design an inspector");
            title.style.fontSize = 15;
            title.style.unityFontStyleAndWeight = FontStyle.Bold;
            title.style.color = DesignerPalette.TextHeader;
            card.Add(title);

            var subtitle = new Label("Pick a component or ScriptableObject script to start.");
            subtitle.style.marginTop = 4;
            subtitle.style.marginBottom = 16;
            subtitle.style.whiteSpace = WhiteSpace.Normal;
            subtitle.style.unityTextAlign = TextAnchor.MiddleCenter;
            subtitle.style.color = DesignerPalette.TextMuted;
            card.Add(subtitle);

            Button pickBtn = null;
            pickBtn = new Button(() => ShowScriptPickerPopup(pickBtn)) { text = "Pick a script…   ▾" };
            pickBtn.style.height = 26;
            pickBtn.style.paddingLeft = 16; pickBtn.style.paddingRight = 16;
            pickBtn.style.backgroundColor = DesignerPalette.AccentFill;
            pickBtn.style.color = Color.white;
            pickBtn.style.unityFontStyleAndWeight = FontStyle.Bold;
            pickBtn.style.borderTopWidth = 0; pickBtn.style.borderBottomWidth = 0;
            pickBtn.style.borderLeftWidth = 0; pickBtn.style.borderRightWidth = 0;
            pickBtn.style.borderTopLeftRadius = 4; pickBtn.style.borderTopRightRadius = 4;
            pickBtn.style.borderBottomLeftRadius = 4; pickBtn.style.borderBottomRightRadius = 4;
            EditorSpringFX.ButtonSpring(pickBtn);
            card.Add(pickBtn);

            return card;
        }

        // Opens the searchable "choose a script" popup over every editable type in the project
        // (SasquatchContextMenu.EnumerateEditableTypes). Picking one funnels straight into LoadTypeLayout, which
        // clones/refreshes/retitles and ends the blank state — so this card disappears with no extra plumbing.
        // Reachable from the blank-state card and from the toolbar's "Type ▾ ▸ Pick a different script…" entry.
        private void ShowScriptPickerPopup(VisualElement anchor)
        {
            if (anchor == null) return;
            var types = SasquatchContextMenu.EnumerateEditableTypes().ToList();

            // Count friendly-name collisions so only genuinely ambiguous entries carry a namespace suffix.
            var nameCounts = new Dictionary<string, int>();
            foreach (var t in types)
            {
                var n = SasquatchReflectionUtility.GetFriendlyTypeName(t);
                nameCounts.TryGetValue(n, out var c);
                nameCounts[n] = c + 1;
            }

            var choices = new List<string>(types.Count);
            var displayToType = new Dictionary<string, Type>(types.Count);
            foreach (var t in types)
            {
                var baseName = SasquatchReflectionUtility.GetFriendlyTypeName(t);
                string disp = (nameCounts.TryGetValue(baseName, out var c) && c > 1 && !string.IsNullOrEmpty(t.Namespace))
                    ? $"{baseName}  ({t.Namespace})"
                    : baseName;
                if (LayoutRegistry.HasOwnLayout(t)) disp += "  — has layout";
                // Final guard for identical name+namespace across assemblies: qualify with the assembly-qualified name.
                if (displayToType.ContainsKey(disp)) disp = $"{disp}  [{t.FullName}]";
                choices.Add(disp);
                displayToType[disp] = t;
            }

            var popup = new SearchableDropdownPopup(
                node: null,
                title: "Choose a script to design",
                choices: choices,
                currentValue: null,
                onSelect: selected =>
                {
                    if (displayToType.TryGetValue(selected, out var picked) && picked != null)
                        LoadTypeLayout(picked, null);
                },
                width: Mathf.Max(320f, anchor.worldBound.width),
                // Every choice here IS a class, and the list is long enough that same-named scripts have to be
                // told apart by namespace — so selecting one shows its declaration and the head of its body.
                codePeek: selected => displayToType.TryGetValue(selected, out var hovered)
                    ? MethodSourcePreview.GetTypeSnippet(hovered)
                    : null,
                anchor: anchor);
            UnityEditor.PopupWindow.Show(anchor.worldBound, popup);
        }

        // The Design-Mode / Live-Preview pair's single color authority: the active one wears the accent fill,
        // the other the neutral face. Painted through ChromePaint so a hovered button keeps its hover tint
        // across the repaint that follows a mode switch (the cursor is still on the button you just clicked).
        private void SyncModeButtonColors()
        {
            if (_designBtnRef != null)
            {
                ChromePaint(_designBtnRef, _designMode ? DesignerPalette.AccentFill : DesignerPalette.ButtonNeutralBg);
                _designBtnRef.style.color = _designMode ? Color.white : DesignerPalette.IconStrong;
            }
            if (_previewBtnRef != null)
            {
                ChromePaint(_previewBtnRef, !_designMode ? DesignerPalette.AccentFill : DesignerPalette.ButtonNeutralBg);
                _previewBtnRef.style.color = !_designMode ? Color.white : DesignerPalette.IconStrong;
            }
        }

        // The eye button's SINGLE painter: glyph, face, glyph tint, tooltip and enabled-ness, all derived from the
        // saved asset plus the chrome-hover marker. Called on build, from RefreshPreview (so loading a different type
        // repaints it), after a click, and on mouse enter/leave via AddChromeHoverRepaint.
        //
        // TWO rest states, so it needs TWO hover looks — a hover that only brightens the "showing" tint leaves the
        // hidden button dead under the cursor, which reads as a disabled control right when the user most needs to
        // believe it's still clickable (their inspector is currently NOT showing their layout).
        //   • SHOWING — a plain neutral chrome button; hover brightens the face and lifts the glyph to full ink.
        //   • HIDDEN  — GHOST AMBER, borrowed from StyleGhostDangerButton: amber rule + amber glyph on no fill at
        //     rest, and the amber comes in SOLID with a white glyph the moment you're on it. Ghost rather than a
        //     filled rest state on purpose — this toolbar deliberately keeps exactly one saturated fill (Save), and
        //     a second one parked next to it just makes the two argue.
        //
        // The DESIGNER deliberately keeps rendering a hidden layout: hiding switches off the real Inspector only, so
        // the canvas must stay live or the button would be a one-way door with nothing left to click back.
        private void SyncHideLayoutButton()
        {
            if (_hideLayoutBtnRef == null || _hideLayoutIconRef == null) return;

            // Preset mode has no target type at all — it edits preset assets, not a type's layout. Hidden outright
            // rather than disabled, alongside Export and Revert, which the preset toolbar drops for the same reason.
            _hideLayoutBtnRef.style.display = _presetMode ? DisplayStyle.None : DisplayStyle.Flex;
            var targetType = _presetMode ? null : ResolveTargetType();
            bool available = targetType != null;
            _hideLayoutBtnRef.SetEnabled(available);

            bool hidden = available && LayoutRegistry.IsLayoutHiddenOwn(targetType);
            bool hot = _hideLayoutBtnRef.ClassListContains(ChromeHoverClass);

            _hideLayoutIconRef.IconId = hidden ? SasquatchIcons.Ids.EyeOff : SasquatchIcons.Ids.Eye;

            float border = hidden ? 1 : 0;
            _hideLayoutBtnRef.style.borderTopWidth = _hideLayoutBtnRef.style.borderBottomWidth =
                _hideLayoutBtnRef.style.borderLeftWidth = _hideLayoutBtnRef.style.borderRightWidth = border;

            if (hidden)
            {
                _hideLayoutBtnRef.style.borderTopColor = _hideLayoutBtnRef.style.borderBottomColor =
                    _hideLayoutBtnRef.style.borderLeftColor = _hideLayoutBtnRef.style.borderRightColor =
                        DesignerPalette.ToastWarning;
                _hideLayoutBtnRef.style.backgroundColor = hot ? DesignerPalette.ToastWarning : Color.clear;
                _hideLayoutIconRef.Tint = hot ? Color.white : DesignerPalette.ToastWarning;
            }
            else
            {
                var face = DesignerPalette.ButtonNeutralBg;
                _hideLayoutBtnRef.style.backgroundColor = hot ? DesignerPalette.Hovered(face) : face;
                _hideLayoutIconRef.Tint = hot ? DesignerPalette.IconStrong : DesignerPalette.IconMuted;
            }

            _hideLayoutBtnRef.tooltip = hidden
                ? "HIDDEN in the Inspector. This layout is switched off, so the Inspector is showing what you'd see "
                  + "without Sasquatch Inspector. Your layout is untouched — click to show it again."
                : "Hide this layout in the Inspector. The Inspector shows what you'd see without Sasquatch Inspector "
                  + "(this type's own custom editor, or Unity's default) — handy for screenshots and before/after "
                  + "comparisons. Nothing is deleted; click again to bring it back.";
        }

        private void RefreshPreview()
        {
            if (_previewContainer == null || _canvasContent == null) return;
            PreserveScroll(_previewContainer, () =>
            {
                // Any rebuild (direct or debounced) satisfies a pending one — cancel it so we don't rebuild a
                // second time ~120ms later and destroy an element the user just clicked (reduces input jank).
                _pendingPreviewRebuild?.Pause();
                _canvasContent.Clear();

            SyncModeButtonColors();
            SyncHideLayoutButton();
            bool fieldsInteractive = _designMode && _designInteract;
            if (_interactToggleRef != null)
            {
                _interactToggleRef.style.display = _designMode ? DisplayStyle.Flex : DisplayStyle.None;
                _interactToggleRef.SetValueWithoutNotify(_designInteract);
            }
            if (_canvasDragController != null) _canvasDragController.FieldsInteractive = fieldsInteractive;

            if (_clonedLayoutAsset == null)
            {
                // Blank state (e.g. opened from Tools ▸ Sasquatch Inspector ▸ Layout Designer with nothing
                // selected): a centered card lets the user pick any editable script to start designing. It's
                // replaced by the real canvas the moment a type loads (LoadTypeLayout → RefreshPreview).
                _canvasContent.Add(BuildBlankStatePickerCard());
                UpdateConflictWarning(null);
                return;
            }

            // Resolve the type to preview (from the assigned test target, else the layout's target type).
            System.Type previewType = _testTarget != null ? _testTarget.GetType() : ResolveTargetType();

            if (previewType == null)
            {
                DestroyMockTarget();
                UpdateConflictWarning(null);
                var lbl = new Label("Assign a matching Test Target object or specify a valid Target Type to render the canvas.");
                lbl.style.whiteSpace = WhiteSpace.Normal;
                lbl.style.color = DesignerPalette.TextDisabled;
                _canvasContent.Add(lbl);
                return;
            }

            // ALWAYS preview against a throwaway mock instance — NEVER the real inspected object — so
            // editing any field (slider/float/string/bool/etc.) in Design or Live Preview can't change
            // the user's actual data. The mock persists across rebuilds (so test edits stick) and is
            // recreated only when the type changes; it's (re)seeded from the real test target's values
            // once whenever that target changes, so the canvas still reflects real data without writing
            // back to it.
            // Authoring a layout FOR an abstract ancestor: an abstract type can't be instantiated as the
            // canvas mock (CreateInstance would log an error and return null). Ask for a concrete-subclass
            // Test Target instead — the layout's base fields bind fine against a subclass instance.
            if (previewType.IsAbstract && _testTarget == null)
            {
                DestroyMockTarget();
                UpdateConflictWarning(null);
                var abstractLbl = new Label(
                    $"{previewType.Name} is abstract, so the canvas has nothing to preview against.\n" +
                    "Assign a Test Target that is a concrete subclass to see this layout rendered — the layout " +
                    "itself still binds (and saves) against " + previewType.Name + ".");
                abstractLbl.style.whiteSpace = WhiteSpace.Normal;
                abstractLbl.style.color = DesignerPalette.TextDisabled;
                _canvasContent.Add(abstractLbl);
                return;
            }

            if (_mockTarget == null || _mockTarget.GetType() != previewType)
            {
                DestroyMockTarget();
                if (typeof(ScriptableObject).IsAssignableFrom(previewType))
                {
                    _mockTarget = ScriptableObject.CreateInstance(previewType);
                }
                else if (typeof(MonoBehaviour).IsAssignableFrom(previewType))
                {
                    // Hide from the scene hierarchy + don't save — but NOT HideAndDontSave: that combo
                    // includes HideFlags.NotEditable, which makes the bound preview fields render disabled
                    // (greyed) and un-editable in BOTH Design and Live Preview. HideInHierarchy|DontSave
                    // keeps the throwaway mock invisible/unselectable yet fully editable.
                    var go = new GameObject("[Sasquatch Inspector Designer Mock]") { hideFlags = HideFlags.HideInHierarchy | HideFlags.DontSave };
                    _mockTarget = go.AddComponent(previewType);
                }
                _mockSeedSource = null;
            }

            if (_mockTarget != null && _testTarget != null && _mockSeedSource != _testTarget)
            {
                EditorUtility.CopySerialized(_testTarget, _mockTarget);
                _mockSeedSource = _testTarget;
            }

            UnityEngine.Object testTarget = _mockTarget;

            // Pass the live mock instance so the competing-editor probe reuses it instead of fabricating one.
            UpdateConflictWarning(previewType, testTarget);

            if (testTarget == null)
            {
                var lbl = new Label("Could not create a preview instance for this type.");
                lbl.style.whiteSpace = WhiteSpace.Normal;
                lbl.style.color = DesignerPalette.TextDisabled;
                _canvasContent.Add(lbl);
                return;
            }

            try
            {
                ConditionEvaluator.SuppressWarnings = true;

                var so = new SerializedObject(testTarget);
                _previewSerializedObject = so;
                var view = LayoutTreeBuilder.Build(
                    _clonedLayoutAsset,
                    so,
                    RefreshPreview,
                    null,
                    _designMode,
                    _selectedNode,
                    _designMode ? _canvasDragController : null,
                    null,
                    fieldsInteractive,
                    HasMultiSelection ? new HashSet<LayoutNode>(_selectedNodes) : null,
                    _showItemTemplates,
                    playAppearAnimations: !_previewHasAppeared,
                    onLayoutEdited: OnLayoutResizedFromPreview,
                    debugConditions: _debugConditions,
                    // Capture per-node build context so continuous-control drags can rebuild a single node in
                    // place (LiveRebuildSelectedNode) instead of tearing down the whole canvas each ~120ms.
                    captureNodeContexts: true
                );
                // After the first preview build, suppress Appear replays on subsequent RefreshPreview calls.
                // (No effect in Design Mode, where animations aren't applied at all.)
                _previewHasAppeared = true;

                if (view != null)
                {
                    _canvasContent.Add(view);
                    _canvasDragController?.SetCanvasRoot(view);
                }
            }
            catch (Exception ex)
            {
                var errLabel = new Label($"Preview Error:\n{ex.Message}\n{ex.StackTrace}");
                errLabel.style.color = DesignerPalette.ErrorText;
                errLabel.style.whiteSpace = WhiteSpace.Normal;
                _canvasContent.Add(errLabel);
            }
            finally
            {
                ConditionEvaluator.SuppressWarnings = false;
            }
            });

            // Re-run any active canvas search against the freshly built tree (self-heal). ONE site covers every
            // exit: the branches above `return` out of the PreserveScroll LAMBDA, and PreserveScroll invokes it
            // synchronously, so control always arrives here — placeholder cards, error card and real canvas alike.
            ReapplyCanvasSearchAfterRebuild();
        }

        private void AddChildNode(ContainerNode parent, int nodeType)
        {
            if (_clonedLayoutAsset == null || parent == null) return;

            // A split Frame's children are STRUCTURAL — exactly two panes, identity positional (see
            // SplitFramePaneOwner). Appending a third direct child strands it: the builder routes panes by
            // index (i == 0 / i == 1), so child 2 is never rendered, never reachable, and never removable.
            // "Add" is the one gesture with an obviously right answer, so redirect into pane A rather than
            // no-op'ing the button the way the move/drop path does — the user asked to put something in the
            // frame, and inside a pane is the only place that means anything.
            if (IsSplitFrame(parent))
            {
                var paneA = parent.Children?.OfType<ContainerNode>().FirstOrDefault();
                if (paneA == null) return; // already degenerate — adding would only deepen the damage
                parent = paneA;
            }

            Undo.RecordObject(_clonedLayoutAsset, "Add Layout Node");

            LayoutNode node;
            if (nodeType == 0)
            {
                node = new ContainerNode();
            }
            else if (nodeType == 1)
            {
                node = new BindingNode() { PropertyPath = "newProperty" };
            }
            else
            {
                node = new CollectionNode() { PropertyPath = "newCollection" };
            }

            if (parent.Children == null)
            {
                parent.Children = new List<LayoutNode>();
            }
            parent.Children.Add(node);

            // SetPrimarySelection, not a raw `_selectedNode = node` — the raw write leaves _selectedNodes and
            // _selectionAnchor pointing at the PREVIOUS selection, so a following Delete or multi-edit acts on
            // nodes the user can no longer see selected.
            SetPrimarySelection(node);
            OnModification();
            RefreshHierarchy();
            RefreshProperties();
            RefreshPreview();
        }

        // ---- Selection (single + multi) ----

        private bool HasMultiSelection => _selectedNodes.Count > 1;

        private bool IsNodeSelected(LayoutNode node) =>
            node != null && (node == _selectedNode || _selectedNodes.Contains(node));

        // Set the single primary selection and clear any multi-selection. Does NOT refresh.
        private void SetPrimarySelection(LayoutNode node)
        {
            _selectedNode = node;
            _selectionAnchor = node;
            _selectedNodes.Clear();
        }

        /// <summary>
        /// Everything the designer keys by node INSTANCE, held as POSITIONAL index paths. Undo/redo restores
        /// the asset by RE-DESERIALIZING it and a manual save re-clones it, so after either, every
        /// instance-keyed field points at a node that is no longer in the tree.
        /// </summary>
        private struct NodeStateSnapshot
        {
            public List<int> Primary;
            public List<List<int>> Group;
            public List<List<int>> Organizer;
            public List<int> OrganizerAnchor;
            public List<List<int>> Collapsed;
            // What the Properties panel was last BUILT for. Stranding these is what made a manual save look
            // to RefreshProperties like the user had clicked a different node — so it reset the scroll, wiped
            // the property search, and closed every open "T" text-styling box, mid-edit.
            public List<int> LastProperties;
            public List<List<int>> LastPropertiesSelection;
        }

        // Snapshot every instance-keyed piece of designer state as positional index paths, so it survives a tree
        // rewrite that swaps node objects (Apply/Override Presets replace upgraded bindings with new instances;
        // a save re-clones; undo re-deserializes). Paths that don't resolve are dropped. Pair with
        // RestoreNodeState. Covers the SELECTION, the Tab Organizer's own selection and the hierarchy's collapse
        // set — the last two used to be stranded by every one of these rewrites, springing the hierarchy open and
        // dropping the organizer's card highlight.
        private NodeStateSnapshot SnapshotNodeState(LayoutNode root)
        {
            return new NodeStateSnapshot
            {
                Primary = _selectedNode != null ? GetNodeIndexPath(_selectedNode, root) : null,
                Group = NodePathsFor(_selectedNodes, root),
                Organizer = NodePathsFor(_organizerSelection, root),
                OrganizerAnchor = _organizerAnchor != null ? GetNodeIndexPath(_organizerAnchor, root) : null,
                Collapsed = NodePathsFor(_collapsedNodes, root),
                LastProperties = _lastPropertiesNode != null ? GetNodeIndexPath(_lastPropertiesNode, root) : null,
                LastPropertiesSelection = _lastPropertiesSelection != null ? NodePathsFor(_lastPropertiesSelection, root) : null,
            };
        }

        private List<List<int>> NodePathsFor(IEnumerable<LayoutNode> nodes, LayoutNode root)
        {
            var paths = new List<List<int>>();
            if (nodes == null) return paths;
            foreach (var n in nodes)
            {
                var p = n != null ? GetNodeIndexPath(n, root) : null;
                if (p != null) paths.Add(p);
            }
            return paths;
        }

        // Re-point a snapshot onto the (possibly rewritten) tree: the WHOLE multi-selection is restored to the
        // current node objects, not just the primary — re-pointing only the primary used to silently drop the
        // rest of a multi-selection. Nodes that no longer resolve are dropped (never left dangling/stale).
        private void RestoreNodeState(NodeStateSnapshot snapshot, LayoutNode root)
        {
            _selectedNodes.Clear();
            if (snapshot.Group != null)
                foreach (var p in snapshot.Group)
                {
                    var n = LocateNodeByIndexPath(p, root);
                    if (n != null && !_selectedNodes.Contains(n)) _selectedNodes.Add(n);
                }
            var primaryNode = snapshot.Primary != null ? LocateNodeByIndexPath(snapshot.Primary, root) : null;
            _selectedNode = primaryNode;
            _selectionAnchor = primaryNode;

            _organizerSelection.Clear();
            if (snapshot.Organizer != null)
                foreach (var p in snapshot.Organizer)
                {
                    var n = LocateNodeByIndexPath(p, root);
                    if (n != null && !_organizerSelection.Contains(n)) _organizerSelection.Add(n);
                }
            _organizerAnchor = snapshot.OrganizerAnchor != null
                ? LocateNodeByIndexPath(snapshot.OrganizerAnchor, root) : null;

            _collapsedNodes.Clear();
            if (snapshot.Collapsed != null)
                foreach (var p in snapshot.Collapsed)
                {
                    var n = LocateNodeByIndexPath(p, root);
                    if (n != null) _collapsedNodes.Add(n);
                }

            // Re-point what the Properties panel was last built for, so the rebuild that follows a save /
            // undo / preset-apply still recognises "same node" and keeps the panel's scroll, its search
            // query and its open "T" boxes. Only re-point when the snapshot HAD a value — a null path must
            // not overwrite a live instance with null and force a spurious reset.
            if (snapshot.LastProperties != null)
                _lastPropertiesNode = LocateNodeByIndexPath(snapshot.LastProperties, root);
            if (snapshot.LastPropertiesSelection != null)
            {
                var restored = new HashSet<LayoutNode>();
                foreach (var p in snapshot.LastPropertiesSelection)
                {
                    var n = LocateNodeByIndexPath(p, root);
                    if (n != null) restored.Add(n);
                }
                _lastPropertiesSelection = restored;
            }
        }

        // Flattened depth-first node order, matching how RenderTree lays rows out (used for shift-range).
        private List<LayoutNode> BuildFlatNodeOrder()
        {
            var list = new List<LayoutNode>();
            void Walk(LayoutNode n)
            {
                if (n == null) return;
                list.Add(n);
                if (n is ContainerNode cn && cn.Children != null)
                {
                    foreach (var c in cn.Children) Walk(c);
                }
                else if (n is CollectionNode col && col.ItemLayout != null)
                {
                    Walk(col.ItemLayout);
                }
            }
            if (_clonedLayoutAsset?.Root != null) Walk(_clonedLayoutAsset.Root);
            return list;
        }

        // The selected nodes with no selected ancestor (so operations don't double-handle a subtree).
        private List<LayoutNode> TopmostSelected()
        {
            var set = _selectedNodes.Count > 0
                ? new List<LayoutNode>(_selectedNodes)
                : (_selectedNode != null ? new List<LayoutNode> { _selectedNode } : new List<LayoutNode>());
            return set.Where(n => n != null && !set.Any(o => o != n && IsAncestorOf(o, n))).ToList();
        }

        // True if the clicked element (or any ancestor) represents a LayoutNode — i.e. the click landed
        // on a node card / hierarchy row rather than empty space. Used to decide whether to deselect.
        private static bool ResolvesToLayoutNode(VisualElement target)
        {
            for (var ve = target; ve != null; ve = ve.parent)
            {
                if (ve.userData is LayoutNode) return true;
            }
            return false;
        }

        // Plain click: select just this node.
        private void SelectSingle(LayoutNode node)
        {
            // Clicking the already-selected node (or empty canvas with nothing selected) changes nothing —
            // don't touch any pane. Rebuilding the canvas here was the "click anywhere → jolt" bug.
            bool unchanged = node == _selectedNode && _selectedNodes.Count == 0;
            SetPrimarySelection(node);
            if (unchanged) return;
            RefreshAfterSelectionChange();
        }

        // Ctrl/Cmd click: toggle this node in/out of the selection.
        private void SelectAdditive(LayoutNode node)
        {
            if (node == null) { SelectSingle(null); return; }
            if (_selectedNode != null && !_selectedNodes.Contains(_selectedNode)) _selectedNodes.Add(_selectedNode);
            if (_selectedNodes.Contains(node)) _selectedNodes.Remove(node);
            else _selectedNodes.Add(node);
            _selectedNode = _selectedNodes.Count > 0 ? _selectedNodes[_selectedNodes.Count - 1] : null;
            _selectionAnchor = node;
            RefreshAfterSelectionChange();
        }

        // Shift click: select the contiguous range from the anchor to this node.
        private void SelectRange(LayoutNode node)
        {
            if (node == null || _selectionAnchor == null) { SelectSingle(node); return; }
            var order = BuildFlatNodeOrder();
            int a = order.IndexOf(_selectionAnchor);
            int b = order.IndexOf(node);
            if (a < 0 || b < 0) { SelectSingle(node); return; }
            int lo = Mathf.Min(a, b), hi = Mathf.Max(a, b);
            _selectedNodes.Clear();
            for (int i = lo; i <= hi; i++) _selectedNodes.Add(order[i]);
            _selectedNode = node; // primary follows the click; anchor stays
            RefreshAfterSelectionChange();
        }

        // Refreshes the panes after a selection-only change. Hierarchy + properties rebuild as before, but the
        // canvas gets its selection chrome re-applied IN PLACE whenever possible: a full RefreshPreview for a
        // mere click tears down and relayouts the whole preview, which visibly jolted the canvas (transient
        // scroll clamp + multi-pass widget geometry settling, worst with frames) on EVERY click. Falls back to
        // the full rebuild when the in-place pass can't represent the change (canvas not built yet, or a newly
        // selected node's card hidden inside an inactive tab — the rebuild's tab auto-switch has to run).
        private void RefreshAfterSelectionChange()
        {
            RefreshHierarchy();
            RefreshProperties();
            bool inPlace = _designMode
                && _canvasContent != null
                && LayoutTreeBuilder.TryUpdateSelectionChrome(
                    _canvasContent,
                    _selectedNode,
                    HasMultiSelection ? new HashSet<LayoutNode>(_selectedNodes) : null);
            if (!inPlace) RefreshPreview();
        }

        // Routes a hierarchy/canvas click through the right selection mode based on modifier keys.
        private void SelectFromClick(LayoutNode node, bool additive, bool range)
        {
            // Format painter: while armed, a node click PAINTS the copied style instead of
            // selecting. Canvas cards AND hierarchy rows both funnel through here.
            if (TryApplyStylePainter(node)) return;

            if (range) SelectRange(node);
            else if (additive) SelectAdditive(node);
            else SelectSingle(node);
        }

        // ---- Organizer & Bindings drag-only selection (independent of _selectedNode) ----

        // Properties (not readonly fields) so a live editor-skin flip restyles on the next rebuild.
        private static Color OrganizerCardNormal => DesignerPalette.OrganizerCardBg;
        private static Color OrganizerCardHover => DesignerPalette.OrganizerCardHoverBg;
        private static Color OrganizerCardSelected => DesignerPalette.RowSelectedBg;
        private static Color TokenRowNormalBg => DesignerPalette.RowBg;
        private static Color TokenRowHoverBg => DesignerPalette.RowHoverBg;
        private static Color TokenRowSelectedBg => DesignerPalette.RowSelectedBg;

        /// <summary>
        /// Shared squish behaviour for the two "name + gold [type] tag" row lists — the Bindings token panel and the
        /// Preset Editor's TYPES list. Both live in the resizable left panel, so both have to degrade gracefully:
        /// <list type="bullet">
        /// <item>The NAME yields first (big shrink weight) and CLIPS to an ellipsis. Shrinking alone is NOT enough —
        /// an unclipped label keeps painting its full text and lays it straight over the tag next to it.</item>
        /// <item>The TAG eats the slack (flex-grow) and right-aligns, so it trails at the card's right edge, and only
        /// shrinks once the name has bottomed out — otherwise a long type name spills past the card and drags the
        /// panel's horizontal scrollbar in with it.</item>
        /// </list>
        /// Shrink only engages on overflow, so a comfortably wide panel looks exactly as before.
        /// </summary>
        internal static void StyleTypeTagRowLabels(Label nameLbl, Label typeLbl)
        {
            nameLbl.style.flexShrink = 100f; // yields long before the tag gives up any width
            nameLbl.style.minWidth = 0;
            nameLbl.style.whiteSpace = WhiteSpace.NoWrap;
            nameLbl.style.overflow = Overflow.Hidden;
            nameLbl.style.textOverflow = TextOverflow.Ellipsis;

            typeLbl.style.flexGrow = 1f;
            typeLbl.style.flexShrink = 1f;
            typeLbl.style.minWidth = 0;
            typeLbl.style.marginLeft = 4;
            typeLbl.style.unityTextAlign = TextAnchor.MiddleRight;
            typeLbl.style.whiteSpace = WhiteSpace.NoWrap;
            typeLbl.style.overflow = Overflow.Hidden;
            typeLbl.style.textOverflow = TextOverflow.Ellipsis;
        }

        // Visual order of the organizer's cards (tab by tab) — for shift-range selection.
        private List<LayoutNode> BuildOrganizerNodeOrder()
        {
            var order = new List<LayoutNode>();
            if (_selectedNode is ContainerNode tabs && tabs.Type == ContainerType.Tabs && tabs.Children != null)
            {
                foreach (var tab in tabs.Children)
                    if (tab is ContainerNode tc && tc.Children != null)
                        foreach (var ch in tc.Children) if (ch != null) order.Add(ch);
            }
            return order;
        }

        // Click on a Tab Organizer card. Plain/ctrl/shift build _organizerSelection WITHOUT touching
        // _selectedNode (so the organizer stays open); it takes a DOUBLE-click to open that card's
        // properties, which navigates away from the organizer.
        private void SelectOrganizerCard(LayoutNode node, bool additive, bool range, int clickCount = 1)
        {
            if (node == null) return;

            if (clickCount >= 2 && !additive && !range)
            {
                _organizerSelection.Clear();
                SelectSingle(node); // opens the card's properties (leaves the organizer)
                return;
            }

            if (range && _organizerAnchor != null)
            {
                var ord = BuildOrganizerNodeOrder();
                int a = ord.IndexOf(_organizerAnchor), b = ord.IndexOf(node);
                if (a >= 0 && b >= 0)
                {
                    int lo = Mathf.Min(a, b), hi = Mathf.Max(a, b);
                    _organizerSelection.Clear();
                    for (int i = lo; i <= hi; i++) _organizerSelection.Add(ord[i]);
                }
                else { _organizerSelection.Clear(); _organizerSelection.Add(node); _organizerAnchor = node; }
            }
            else if (additive)
            {
                if (!_organizerSelection.Remove(node)) _organizerSelection.Add(node);
                _organizerAnchor = node;
            }
            else
            {
                _organizerSelection.Clear();
                _organizerSelection.Add(node);
                _organizerAnchor = node;
            }
            RefreshOrganizerHighlights();
        }

        // Re-applies the selected/normal background to every organizer card in place (no rebuild).
        private void RefreshOrganizerHighlights()
        {
            if (_propertiesContainer == null) return;
            _propertiesContainer.Query<VisualElement>(className: "organizer-card").ForEach(card =>
            {
                bool sel = card.userData is LayoutNode ln && _organizerSelection.Contains(ln);
                card.style.backgroundColor = sel ? OrganizerCardSelected : OrganizerCardNormal;
            });
        }

        // Visual order of the Bindings tab's draggable token rows — for shift-range selection.
        private List<string> BuildBindingTokenOrder()
        {
            var order = new List<string>();
            if (_tokenBankContainer != null)
                _tokenBankContainer.Query<VisualElement>(className: "sasq-token-row").ForEach(row =>
                {
                    if (row.userData is string p && !order.Contains(p)) order.Add(p);
                });
            return order;
        }

        // Click on a Bindings token. Plain/ctrl/shift build _bindingSelection for multi-drag, without
        // changing the inspected node.
        // Whether a token path is already bound in the layout (so its row shows the ping/lock state
        // rather than a draggable, multi-selectable token).
        private bool IsBindingPathBound(string path)
        {
            if (_clonedLayoutAsset?.Root == null || string.IsNullOrEmpty(path)) return false;
            var bound = new HashSet<string>();
            GatherBoundPaths(_clonedLayoutAsset.Root, "", bound, derivedPaths: bound);
            return bound.Contains(path);
        }

        // The Bindings palette is a click-to-gather list: a plain (or Ctrl) click TOGGLES the token in
        // and out of the selection — click to add, click the same one again to deselect — so you build
        // a multi-selection by clicking, no modifier required. Shift selects a contiguous range.
        private void SelectBindingToken(string path, bool additive, bool range)
        {
            if (string.IsNullOrEmpty(path)) return;
            // Only unused/draggable tokens are multi-selectable; bound rows keep their ping/lock behavior.
            if (IsBindingPathBound(path)) return;

            if (range && _bindingAnchor != null)
            {
                var ord = BuildBindingTokenOrder();
                int a = ord.IndexOf(_bindingAnchor), b = ord.IndexOf(path);
                if (a >= 0 && b >= 0)
                {
                    int lo = Mathf.Min(a, b), hi = Mathf.Max(a, b);
                    _bindingSelection.Clear();
                    for (int i = lo; i <= hi; i++) _bindingSelection.Add(ord[i]);
                }
                else if (!_bindingSelection.Contains(path)) _bindingSelection.Add(path);
                _bindingAnchor = path;
            }
            else
            {
                // Toggle (no "clear others"): add if absent, remove if already selected.
                if (!_bindingSelection.Remove(path)) _bindingSelection.Add(path);
                _bindingAnchor = path;
            }
            RefreshBindingHighlights();
        }

        // Re-applies the selected/normal background to every draggable token row in place.
        private void RefreshBindingHighlights()
        {
            if (_tokenBankContainer == null) return;
            _tokenBankContainer.Query<VisualElement>(className: "sasq-token-row").ForEach(row =>
            {
                if (!(row.userData is string p)) return;
                row.style.backgroundColor = _bindingSelection.Contains(p) ? TokenRowSelectedBg : TokenRowNormalBg;
            });
        }

        // Core removal: detaches a node from the tree (Children list or owning ItemLayout). No undo/refresh.
        // Call this ONLY from RemoveNodesGuarded — it is deliberately the chokepoint's single primitive, so
        // the split-pane and owned-spacer rules cannot be skipped by reaching past them.
        private bool RemoveNodeFromTree(LayoutNode node)
        {
            if (node == null || _clonedLayoutAsset == null || node == _clonedLayoutAsset.Root) return false;
            var parent = FindParent(node, _clonedLayoutAsset.Root);
            if (parent != null) { parent.Children.Remove(node); ClampActiveTab(parent); return true; }
            var owner = FindItemLayoutOwner(node, _clonedLayoutAsset.Root);
            if (owner != null) { owner.ItemLayout = null; return true; }
            // A dictionary's Key / Value cell template — the other in-tree node held by REFERENCE rather than
            // in a Children list, so FindParent cannot find it and it would otherwise be undeletable.
            var dictOwner = FindDictionaryTemplateOwner(node, _clonedLayoutAsset.Root);
            if (dictOwner != null)
            {
                if (dictOwner.DictionaryKeyTemplate == node) dictOwner.DictionaryKeyTemplate = null;
                else dictOwner.DictionaryValueTemplate = null;
                return true;
            }
            return false;
        }

        /// <summary>
        /// True when <paramref name="node"/> IS a dictionary Key / Value cell template.
        /// <para>
        /// <b>What it gates, and why the list is exactly this long.</b> A cell template is built by
        /// <c>SerializedDictionaryDrawer.BuildCellField</c>, which runs the widget CONSTRUCTOR plus the
        /// Appearance and Field Styling passes — NOT <c>LayoutTreeBuilder.BuildNode</c>. Everything BuildNode
        /// would otherwise attach after the widget therefore has nothing to act on inside a dictionary row:
        /// Validation, Conditions, Animations, the resize grips and the Visible-in-Inspector flag. Those rows
        /// are hidden rather than shown-and-inert, which is the rule the whole Designer keeps — an option you
        /// can see is an option that does something.
        /// </para>
        /// <para>
        /// The narrowness is deliberate and is an EXPORT decision, not a laziness one. The kit renders a
        /// dictionary cell through one <c>valueFactory:</c> lambda emitted by <c>DisplayTypeEmitter</c>, which
        /// carries the widget and its styling and has no hook for a condition, a validation wrapper or an
        /// animation. Wiring any of those live-only would open a live/export parity gap — the failure mode
        /// this codebase has shipped three times — so the reach stops where BOTH renderers stop. The Label row
        /// stays: it is what names the row in the hierarchy, and the renderers deliberately blank it in the
        /// cell (see EmitContext.DictionaryCell).
        /// </para>
        /// </summary>
        private bool IsDictionaryCellTemplate(LayoutNode node)
            => IsDictionaryCellTemplate(node, _clonedLayoutAsset?.Root);

        /// <summary>
        /// The window-free form of <see cref="IsDictionaryCellTemplate(LayoutNode)"/>, for the surfaces that
        /// have a layout but no designer instance — chiefly <c>QuickEditPopup</c>, which edits the SAME node
        /// from the live inspector and so must offer the same rows. ONE predicate, asked by both: a control
        /// the Properties panel hides and the popup shows is a control that does nothing, reached by the
        /// route most likely to be used.
        /// </summary>
        internal static bool IsDictionaryCellTemplate(LayoutNode node, LayoutNode root)
        {
            // CHEAP TEST FIRST. This is called once per HIERARCHY ROW (the visibility eye) and the owner
            // search walks the whole tree, so an unguarded version would be quadratic in the layout's size on
            // every refresh. Only a path-less BindingNode can BE a cell template, and almost nothing in a real
            // layout is one — a collection's element template is the only other node that gets this far, and
            // it is rejected by the walk.
            if (!(node is BindingNode bn) || !string.IsNullOrEmpty(bn.PropertyPath)) return false;
            return root != null && FindDictionaryTemplateOwner(node, root) != null;
        }

        /// <summary>
        /// The BindingNode whose Key or Value cell template IS <paramref name="child"/>, searching the tree.
        /// The dictionary twin of <see cref="FindItemLayoutOwner"/>, and it exists for the same reason: those
        /// two references are the only places a node lives outside a <c>Children</c> list, so every "who owns
        /// this?" question has to ask here as well or the node reads as orphaned.
        /// </summary>
        private static BindingNode FindDictionaryTemplateOwner(LayoutNode child, LayoutNode current)
        {
            if (current == null || child == null) return null;
            if (current is BindingNode bn)
            {
                if (bn.DictionaryKeyTemplate == child || bn.DictionaryValueTemplate == child) return bn;
                return FindDictionaryTemplateOwner(child, bn.DictionaryKeyTemplate)
                       ?? FindDictionaryTemplateOwner(child, bn.DictionaryValueTemplate);
            }
            if (current is CollectionNode col) return FindDictionaryTemplateOwner(child, col.ItemLayout);
            if (current is ContainerNode cn && cn.Children != null)
            {
                foreach (var sub in cn.Children)
                {
                    var found = FindDictionaryTemplateOwner(child, sub);
                    if (found != null) return found;
                }
            }
            return null;
        }

        // Losing a child can strand a Tabs container's active index past the end, so EVERY path that takes a
        // node out of a container has to re-clamp. Two sites reach it: RemoveNodeFromTree (i.e. everything
        // routed through the RemoveNodesGuarded chokepoint) and HandleNodeMoveDrop, which does its own index
        // maths and so clamps explicitly. A dangling index is survivable but wrong in two ways — the
        // builder falls back to tab 0, so the same "remove the open tab" gesture shows the FIRST tab when
        // dragged and the LAST when deleted, and the saved layout carries an out-of-range index.
        private static void ClampActiveTab(ContainerNode parent)
        {
            if (parent == null || parent.Type != ContainerType.Tabs) return;
            int count = parent.Children?.Count ?? 0;
            if (parent.ActiveTabIndex >= count) parent.ActiveTabIndex = Mathf.Max(0, count - 1);
        }

        // Every field node (binding/collection) in the tree → its resolved path (the key attribute-owned
        // spacers store in OwnerFieldPath). Mirrors UnboundFieldSync's path resolution; collection item-layout
        // element bindings are included so a nested field's owned spacer resolves too.
        private static void MapFieldPaths(LayoutNode node, string basePath, Dictionary<LayoutNode, string> map)
        {
            switch (node)
            {
                case BindingNode bn when !string.IsNullOrEmpty(bn.PropertyPath):
                    map[bn] = string.IsNullOrEmpty(basePath) ? bn.PropertyPath : basePath + "." + bn.PropertyPath;
                    break;
                case CollectionNode cn when !string.IsNullOrEmpty(cn.PropertyPath):
                    string rp = string.IsNullOrEmpty(basePath) ? cn.PropertyPath : basePath + "." + cn.PropertyPath;
                    map[cn] = rp;
                    if (cn.ItemLayout != null) MapFieldPaths(cn.ItemLayout, rp, map);
                    break;
                case ContainerNode c:
                    string nb = string.IsNullOrEmpty(c.PropertyPath) ? basePath
                        : (string.IsNullOrEmpty(basePath) ? c.PropertyPath : basePath + "." + c.PropertyPath);
                    if (c.Children != null) foreach (var ch in c.Children) MapFieldPaths(ch, nb, map);
                    break;
            }
        }

        // A node plus every descendant (children + collection item-layout), by reference.
        private static void CollectSubtree(LayoutNode node, HashSet<LayoutNode> into)
        {
            if (node == null || !into.Add(node)) return;
            if (node is ContainerNode c && c.Children != null)
                foreach (var ch in c.Children) CollectSubtree(ch, into);
            else if (node is CollectionNode col && col.ItemLayout != null)
                CollectSubtree(col.ItemLayout, into);
            else if (node is BindingNode bn)
            {
                CollectSubtree(bn.DictionaryKeyTemplate, into);
                CollectSubtree(bn.DictionaryValueTemplate, into);
            }
        }

        /// <summary>
        /// Delete-time gate for attribute-owned (locked) Space widgets. Returns true when the delete may
        /// proceed; false (after showing an explanatory dialog) when it would strand a locked spacer — i.e. an
        /// attribute-owned space is being removed WITHOUT the field it belongs to (and that field still exists).
        /// A locked space removed together with its field, or one whose owner field is already gone (a stale
        /// orphan), is allowed. This is a pure GATE — the matching spacer cascade is owned by
        /// <see cref="RemoveNodesGuarded"/>, so a removal path can no longer take the gate and forget the
        /// cleanup (or, as three paths did, skip both).
        /// </summary>
        private bool PrepareDeleteForLockedSpaces(IEnumerable<LayoutNode> requested)
        {
            if (_clonedLayoutAsset?.Root == null || requested == null) return true;

            var set = new HashSet<LayoutNode>();
            foreach (var n in requested) CollectSubtree(n, set);

            var fieldPaths = new Dictionary<LayoutNode, string>();
            MapFieldPaths(_clonedLayoutAsset.Root, "", fieldPaths);

            var deletedFieldPaths = new HashSet<string>();
            foreach (var n in set)
                if (fieldPaths.TryGetValue(n, out var p)) deletedFieldPaths.Add(p);

            var boundNow = new HashSet<string>(fieldPaths.Values);
            foreach (var n in set)
            {
                if (n is SpaceNode sn && sn.IsAttributeOwned
                    && boundNow.Contains(sn.OwnerFieldPath)
                    && !deletedFieldPaths.Contains(sn.OwnerFieldPath))
                {
                    ShowLockedSpaceDialog(sn.OwnerFieldPath);
                    return false;
                }
            }

            return true;
        }

        // Prune the attribute-owned spacers whose fields were just deleted (call after the removal, inside the
        // same undo record). A no-op for fields that never carried a [Space].
        private void CleanupOwnedSpacersFor(List<string> resolvedFieldPaths)
        {
            if (_clonedLayoutAsset?.Root == null || resolvedFieldPaths == null) return;
            foreach (var p in resolvedFieldPaths)
                UnboundFieldSync.RemoveOwnedSpacers(_clonedLayoutAsset.Root, p);
        }

        private void ShowLockedSpaceDialog(string ownerFieldPath)
        {
            string field = string.IsNullOrEmpty(ownerFieldPath) ? "a field" : "“" + ValidationFieldLabel(null, ownerFieldPath) + "”";
            EditorUtility.DisplayDialog(
                "Space is locked to a [Space] attribute",
                $"This space comes from a [Space] attribute on {field} in your script, so it can't be deleted here.\n\n" +
                "To remove it, delete the [Space] attribute above that field in your code — the space then " +
                "disappears automatically.\n\n" +
                "(Space widgets you add yourself in the designer can be deleted normally.)",
                "Got it");
        }

        // -------------------------------------------------------------------------------------------
        // THE node-removal chokepoint
        // -------------------------------------------------------------------------------------------

        /// <summary>
        /// Why nodes are coming out of the tree. The two kinds differ ONLY in how they treat a structural
        /// split-Frame pane and whether the attribute-owned spacer cascade runs; everything else is shared.
        /// </summary>
        private enum RemovalKind
        {
            /// <summary>A real delete — the node leaves the layout for good. A split-Frame pane is CLEARED
            /// instead of removed, and the attribute-owned [Space] spacers of every field going away are
            /// pruned with it.</summary>
            Delete,

            /// <summary>A relocation — the node is detached only to be re-inserted elsewhere. A split-Frame
            /// pane is REFUSED outright (it neither moves nor loses its contents) and nothing cascades, since
            /// no field is actually going away.</summary>
            Detach,
        }

        /// <summary>
        /// THE chokepoint for taking nodes out of the tree. Five paths used to apply these three structural
        /// rules ad-hoc, and between two and four of them missed one:
        ///   (a) a split Frame's panes are positional identity — exactly two, always — so they are never
        ///       removed: a Delete clears the pane, a Detach refuses it outright;
        ///   (b) removing a field node cascades to the attribute-owned [Space] spacers it owns;
        ///   (c) losing a child re-clamps the owning Tabs container's ActiveTabIndex (inside
        ///       <see cref="RemoveNodeFromTree"/>).
        /// The caller owns Undo recording, selection bookkeeping and refreshes; this only mutates the graph.
        /// Returns the nodes actually DETACHED, in the order supplied — a cleared or refused pane is not
        /// detached, so it is absent, which is what lets a move re-insert exactly what it took.
        /// </summary>
        private List<LayoutNode> RemoveNodesGuarded(IEnumerable<LayoutNode> nodes, RemovalKind kind)
        {
            var detached = new List<LayoutNode>();
            if (_clonedLayoutAsset?.Root == null || nodes == null) return detached;

            var requested = nodes.Where(n => n != null && n != _clonedLayoutAsset.Root).Distinct().ToList();
            if (requested.Count == 0) return detached;

            // Resolve the cascade against the PRE-removal tree: OwnerFieldPath is a RESOLVED path, and the
            // container chain that resolves it disappears along with the nodes.
            var ownedCleanup = kind == RemovalKind.Delete ? ResolveRemovedFieldPaths(requested) : null;

            foreach (var n in requested)
            {
                if (SplitFramePaneOwner(n) != null)
                {
                    if (kind == RemovalKind.Delete && n is ContainerNode pane) pane.Children = new List<LayoutNode>();
                    continue; // never detached, either way
                }
                // A dictionary Key / Value cell template may be DELETED but never RELOCATED. Deleting one is a
                // real gesture (✕KV removes both; this is the half of it). Moving one is not: it is bare by
                // construction — an empty PropertyPath binds "the cell the row already points at" — so in any
                // Children list it renders "BindingNode has no property path." The single-node path refuses
                // the same drop at HandleNodeMoveDrop, and the two have to agree or one drag says yes and a
                // multi-selection drag of the same node says no (the split-Frame pane precedent above).
                if (kind == RemovalKind.Detach
                    && FindDictionaryTemplateOwner(n, _clonedLayoutAsset.Root) != null) continue;
                if (RemoveNodeFromTree(n)) detached.Add(n);
            }

            // The spacer cascade takes nodes out too, and it prunes BY PATH rather than through
            // RemoveNodeFromTree — so its removals never saw the primitive's per-parent clamp.
            CleanupOwnedSpacersFor(ownedCleanup);
            if (ownedCleanup != null && ownedCleanup.Count > 0) ClampAllTabs(_clonedLayoutAsset.Root);

            return detached;
        }

        // Re-clamp every Tabs container in the tree. Only the spacer cascade needs this (it removes nodes
        // without going through RemoveNodeFromTree); everything else clamps per-parent as it detaches.
        private static void ClampAllTabs(LayoutNode node)
        {
            if (node is ContainerNode c)
            {
                ClampActiveTab(c);
                if (c.Children != null) foreach (var ch in c.Children) ClampAllTabs(ch);
            }
            else if (node is CollectionNode col && col.ItemLayout != null)
            {
                ClampAllTabs(col.ItemLayout);
            }
        }

        /// <summary>
        /// The resolved field paths that disappear when these subtrees come out — the key attribute-owned
        /// spacers carry in OwnerFieldPath. Must run against the PRE-removal tree.
        /// </summary>
        private List<string> ResolveRemovedFieldPaths(IEnumerable<LayoutNode> removed)
        {
            var paths = new List<string>();
            if (_clonedLayoutAsset?.Root == null || removed == null) return paths;

            var set = new HashSet<LayoutNode>();
            foreach (var n in removed) CollectSubtree(n, set);

            var fieldPaths = new Dictionary<LayoutNode, string>();
            MapFieldPaths(_clonedLayoutAsset.Root, "", fieldPaths);

            foreach (var n in set)
                if (fieldPaths.TryGetValue(n, out var p) && !paths.Contains(p)) paths.Add(p);
            return paths;
        }

        private void DeleteSelectedNodes()
        {
            if (_clonedLayoutAsset == null) return;
            var toDelete = TopmostSelected().Where(n => n != _clonedLayoutAsset.Root).ToList();
            if (toDelete.Count == 0) return;
            if (!PrepareDeleteForLockedSpaces(toDelete)) return;

            Undo.RecordObject(_clonedLayoutAsset, "Delete Layout Nodes");
            RemoveNodesGuarded(toDelete, RemovalKind.Delete);

            SetPrimarySelection(_clonedLayoutAsset.Root);
            OnModification();
            RefreshHierarchy();
            RefreshProperties();
            RefreshTokens();
            RefreshPreview();
        }

        // Removes an explicit set of nodes (a group dragged onto the delete zone / Bindings panel to
        // unbind, or the organizer's Delete key). Keeps a still-present primary selection — so an
        // organizer unbind leaves the Tabs container selected and the organizer open — and only falls
        // back to root when the primary itself was removed.
        private void DeleteNodes(IEnumerable<LayoutNode> nodes)
        {
            if (_clonedLayoutAsset == null || nodes == null) return;
            var list = nodes.Where(n => n != null && n != _clonedLayoutAsset.Root).Distinct().ToList();
            if (list.Count == 0) return;
            if (!PrepareDeleteForLockedSpaces(list)) return;

            Undo.RecordObject(_clonedLayoutAsset, "Remove Layout Nodes");
            RemoveNodesGuarded(list, RemovalKind.Delete);

            _selectedNodes.RemoveAll(list.Contains);
            _organizerSelection.RemoveAll(list.Contains);
            if (list.Contains(_selectedNode)) SetPrimarySelection(_clonedLayoutAsset.Root);

            OnModification();
            RefreshHierarchy();
            RefreshProperties();
            RefreshTokens();
            RefreshPreview();
        }

        /// <summary>
        /// The nodes a "Wrap selected in" would actually take, in tree order — the top-most selection when it
        /// is one run of siblings, empty when the wrap is impossible. Empty is what greys the menu entry, so an
        /// unwrappable selection reads as unavailable BEFORE the click instead of logging a warning after it.
        /// <para>
        /// Refused: the root (nothing to wrap it into), a selection spanning two parents (a container can only
        /// hold one run of siblings), and a split frame's panes — those are positional identity, exactly two,
        /// and the move/delete paths refuse them for the same reason (see <see cref="SplitFramePaneOwner"/>).
        /// </para>
        /// Shared by the hierarchy row menu and the canvas card menu, so both offer the same thing.
        /// </summary>
        private List<LayoutNode> WrapTargets()
        {
            var empty = new List<LayoutNode>();
            if (_clonedLayoutAsset == null || _clonedLayoutAsset.Root == null) return empty;

            var nodes = TopmostSelected().Where(n => n != null && n != _clonedLayoutAsset.Root).ToList();
            if (nodes.Count == 0) return empty;
            if (nodes.Any(n => SplitFramePaneOwner(n) != null)) return empty;

            var parent = FindParent(nodes[0], _clonedLayoutAsset.Root);
            if (parent == null) return empty;
            if (nodes.Any(n => FindParent(n, _clonedLayoutAsset.Root) != parent)) return empty;

            return nodes.OrderBy(n => parent.Children.IndexOf(n)).ToList();
        }

        // Right-click → wrap the current selection (siblings sharing one parent) in a new container.
        private void WrapSelected(ContainerType kind)
        {
            var ordered = WrapTargets();
            if (ordered.Count == 0) return;

            var parent = FindParent(ordered[0], _clonedLayoutAsset.Root);
            if (parent == null) return;
            int insertAt = parent.Children.IndexOf(ordered[0]);

            Undo.RecordObject(_clonedLayoutAsset, "Wrap Selected");
            var container = new ContainerNode { Type = kind };
            foreach (var n in ordered) { parent.Children.Remove(n); container.Children.Add(n); }
            insertAt = Mathf.Clamp(insertAt, 0, parent.Children.Count);
            parent.Children.Insert(insertAt, container);

            SetPrimarySelection(container);
            OnModification();
            RefreshHierarchy();
            RefreshProperties();
            RefreshPreview();
        }

        /// <summary>
        /// The "Wrap selected in ▸" submenu, offered identically by the hierarchy row menu and the canvas card
        /// menu — the gesture belongs wherever you happen to be looking, and the canvas is where you can see
        /// what you are grouping. <see cref="WrapTargets"/> decides whether the entries are live or greyed.
        /// <para>
        /// Rows / Columns / Card / Foldout only. A Grid means nothing until its column count is set, a Tabs
        /// container would have to re-home every wrapped node as its own tab (a structural change, not a wrap),
        /// and a Frame's shape settings and two-pane split make it the same story — none of the three is
        /// something to hand someone as a one-click action.
        /// </para>
        /// </summary>
        private void AddWrapSelectedMenuItems(GenericMenu menu)
        {
            var targets = WrapTargets();
            string suffix = targets.Count > 1 ? $" ({targets.Count})" : "";
            foreach (var kind in new[] { ContainerType.Rows, ContainerType.Columns, ContainerType.Card, ContainerType.Foldout })
            {
                var label = new GUIContent($"Wrap selected in/{kind}{suffix}");
                if (targets.Count > 0)
                {
                    var captured = kind;
                    menu.AddItem(label, false, () => WrapSelected(captured));
                }
                else
                {
                    menu.AddDisabledItem(label);
                }
            }
        }

        /// <summary>Test seam: the nodes a "Wrap selected in" would take (empty ⇒ the entries are greyed).</summary>
        internal List<LayoutNode> DebugWrapTargets() => WrapTargets();

        /// <summary>Test seam: wraps the selection exactly as the menu entry does.</summary>
        internal void DebugWrapSelected(ContainerType kind) => WrapSelected(kind);

        // -------------------------------------------------------------------------------------------
        // Taking a layout back apart — the two inverses of "Wrap selected in"
        // -------------------------------------------------------------------------------------------
        //
        // Wrapping was one click and un-wrapping was none: deleting a container took everything inside it
        // with it, so "I want the Card gone but the fields kept" meant dragging each child out by hand and
        // then deleting the empty shell. These are the two shapes that gap actually has — dissolve the whole
        // container, or promote just part of it — and they share one gate / one builder with Wrap.

        /// <summary>
        /// A split Frame IS its two panes: their identity is positional (exactly two, always), so the frame
        /// can never spill them into its parent and nothing can be lifted up into it.
        /// </summary>
        private static bool IsSplitFrame(ContainerNode c) =>
            c != null && c.Type == ContainerType.Frame && c.Frame.Shape == FrameShape.DiagonalSplit;

        /// <summary>
        /// The containers an "Unwrap container" would dissolve — empty when the gesture is impossible, which
        /// is what greys the entry BEFORE the click. The same single-gate shape as <see cref="WrapTargets"/>,
        /// and for the same reason.
        /// <para>
        /// Refused: anything that isn't a container, the root, an item-layout TEMPLATE (it hangs off a single
        /// ItemLayout reference, so <see cref="FindParent"/> finds no Children list for its kids to land in),
        /// a split Frame and its panes (see <see cref="IsSplitFrame"/>), and a direct child of a Tabs
        /// container — that child IS the tab, so dissolving it would quietly turn one tab into N tabs instead
        /// of flattening a level.
        /// </para>
        /// </summary>
        private List<ContainerNode> UnwrapTargets()
        {
            var empty = new List<ContainerNode>();
            if (_clonedLayoutAsset?.Root == null) return empty;

            return TopmostSelected()
                .OfType<ContainerNode>()
                .Where(c => c != _clonedLayoutAsset.Root && !IsSplitFrame(c) && SplitFramePaneOwner(c) == null)
                .Where(c =>
                {
                    var parent = FindParent(c, _clonedLayoutAsset.Root);
                    return parent != null && parent.Type != ContainerType.Tabs;
                })
                .ToList();
        }

        /// <summary>
        /// Dissolves each selected container: its children take its exact place in the parent, in order, and
        /// the container itself goes. The inverse of <see cref="WrapSelected"/> — a wrap you regret is one
        /// click away, and it is the only way to drop a Card/Foldout without deleting what it holds.
        /// </summary>
        private void UnwrapContainers()
        {
            var targets = UnwrapTargets();
            if (targets.Count == 0) return;

            Undo.RecordObject(_clonedLayoutAsset, targets.Count > 1 ? "Unwrap Containers" : "Unwrap Container");

            var freed = new List<LayoutNode>();
            LayoutNode reselect = null;

            foreach (var container in targets)
            {
                // Re-resolved per container instead of captured up front: an earlier unwrap in this same pass
                // can have moved this one, and an emptied parent can have shifted its index.
                var parent = FindParent(container, _clonedLayoutAsset.Root);
                if (parent == null) continue;
                int insertAt = parent.Children.IndexOf(container);
                if (insertAt < 0) continue;
                if (reselect == null) reselect = parent;

                // Held-open cells are the CONTAINER's plumbing: a cell slot is a track ordinal, and the tracks
                // leave with the container — so they die with it rather than riding up as blank cruft.
                var kids = (container.Children ?? new List<LayoutNode>())
                    .Where(n => n != null && !(n is EmptyCellNode))
                    .ToList();

                // Detach, never Delete: no field is leaving the layout, so the attribute-owned [Space] cascade
                // must NOT run and the locked-space prompt has nothing to ask about.
                var lifted = RemoveNodesGuarded(kids, RemovalKind.Detach);
                RemoveNodesGuarded(new LayoutNode[] { container }, RemovalKind.Detach);

                // Cell-aware exactly like a group move: dropping N nodes into a tracked parent has to consume
                // the cells they land in rather than shove past them.
                for (int i = 0; i < lifted.Count; i++)
                    EmptyCellFill.InsertAtCell(parent, lifted[i], insertAt + i);

                freed.AddRange(lifted);
            }

            // Land on what was freed, so it can be re-wrapped or dragged straight away. An empty container
            // frees nothing, so that case falls back to the parent it was dissolved into.
            SetPrimarySelection(freed.Count > 0 ? freed[0] : reselect);
            if (freed.Count > 1) _selectedNodes.AddRange(freed);

            OnModification();
            RefreshAll();
        }

        /// <summary>
        /// The nodes a "Move out of container" would promote one level, in tree order — empty when the move is
        /// impossible, which greys the entry before the click.
        /// <para>
        /// Refused: the root, a split Frame's panes, a selection spanning two parents (one move, two landing
        /// places), anything already at the top level or inside an item-layout template (no grandparent to
        /// move to), and a destination that cannot take a loose child — a Tabs container (whose children are
        /// tabs) or a split Frame (whose children are exactly two panes).
        /// </para>
        /// </summary>
        private List<LayoutNode> MoveOutTargets()
        {
            var empty = new List<LayoutNode>();
            if (_clonedLayoutAsset?.Root == null) return empty;

            var nodes = TopmostSelected().Where(n => n != null && n != _clonedLayoutAsset.Root).ToList();
            if (nodes.Count == 0) return empty;
            if (nodes.Any(n => SplitFramePaneOwner(n) != null)) return empty;

            var parent = FindParent(nodes[0], _clonedLayoutAsset.Root);
            if (parent == null) return empty;
            if (nodes.Any(n => FindParent(n, _clonedLayoutAsset.Root) != parent)) return empty;

            var dest = FindParent(parent, _clonedLayoutAsset.Root);
            if (dest == null || dest.Type == ContainerType.Tabs || IsSplitFrame(dest)) return empty;

            return nodes.OrderBy(n => parent.Children.IndexOf(n)).ToList();
        }

        /// <summary>
        /// Promotes the selection one level: it leaves its container and lands directly AFTER it, so the
        /// widgets stay where the eye expects them while the container keeps whatever is left. The
        /// partial-extract counterpart to <see cref="UnwrapContainers"/> — freeing one field out of a
        /// twelve-item Card would otherwise mean taking the other eleven apart too.
        /// </summary>
        private void MoveSelectedOutOfContainer()
        {
            var ordered = MoveOutTargets();
            if (ordered.Count == 0) return;

            var parent = FindParent(ordered[0], _clonedLayoutAsset.Root);
            var dest = parent != null ? FindParent(parent, _clonedLayoutAsset.Root) : null;
            if (dest == null) return;

            Undo.RecordObject(_clonedLayoutAsset, "Move Out Of Container");

            // Detach for the same reason Unwrap does: this is a relocation, not a deletion.
            var moved = RemoveNodesGuarded(ordered, RemovalKind.Detach);

            // Read AFTER the detach: emptying the container never touches dest.Children, but resolving the
            // landing index here keeps it honest if a guard refused part of the set.
            int at = dest.Children.IndexOf(parent);
            at = at < 0 ? dest.Children.Count : at + 1;
            for (int i = 0; i < moved.Count; i++)
                EmptyCellFill.InsertAtCell(dest, moved[i], at + i);

            // The container they left is deliberately KEPT, even when it ends up empty: the entry says "move
            // out", not "dissolve", and Unwrap sits right above it for the other reading.
            SetPrimarySelection(moved.Count > 0 ? moved[0] : (LayoutNode)parent);
            if (moved.Count > 1) _selectedNodes.AddRange(moved);

            OnModification();
            RefreshAll();
        }

        /// <summary>
        /// The two inverses of "Wrap selected in", built ONCE and offered by both the hierarchy row menu and
        /// the canvas card menu — two hand-written copies of a menu is exactly how the two panels drift apart.
        /// <see cref="UnwrapTargets"/> and <see cref="MoveOutTargets"/> decide whether each entry is live.
        /// <para>
        /// Two entries rather than one, because they answer different questions: "this Card was a mistake"
        /// wants the whole thing gone, while "this one field belongs outside it" needs the Card left standing.
        /// </para>
        /// </summary>
        private void AddUnwrapMenuItems(GenericMenu menu)
        {
            var containers = UnwrapTargets();
            string unwrapSuffix = containers.Count > 1 ? $" ({containers.Count})" : "";
            var unwrapLabel = new GUIContent($"Unwrap container{unwrapSuffix}");
            if (containers.Count > 0) menu.AddItem(unwrapLabel, false, UnwrapContainers);
            else menu.AddDisabledItem(unwrapLabel);

            var outs = MoveOutTargets();
            string outSuffix = outs.Count > 1 ? $" ({outs.Count})" : "";
            var moveLabel = new GUIContent($"Move out of container{outSuffix}");
            if (outs.Count > 0) menu.AddItem(moveLabel, false, MoveSelectedOutOfContainer);
            else menu.AddDisabledItem(moveLabel);
        }

        /// <summary>Test seam: the containers an "Unwrap container" would dissolve (empty ⇒ the entry is greyed).</summary>
        internal List<ContainerNode> DebugUnwrapTargets() => UnwrapTargets();

        /// <summary>Test seam: unwraps the selection exactly as the menu entry does.</summary>
        internal void DebugUnwrapContainers() => UnwrapContainers();

        /// <summary>Test seam: the nodes a "Move out of container" would promote (empty ⇒ the entry is greyed).</summary>
        internal List<LayoutNode> DebugMoveOutTargets() => MoveOutTargets();

        /// <summary>Test seam: promotes the selection exactly as the menu entry does.</summary>
        internal void DebugMoveSelectedOutOfContainer() => MoveSelectedOutOfContainer();

        // Group-drag: relocate the whole multi-selection as a block to the drop target.
        private void HandleGroupMove(LayoutNode target, DropRelation relation, int slot = -1)
        {
            var moved = MoveNodesAsBlock(TopmostSelected(), target, relation, slot, "Move Selected");
            if (moved.Count == 0) return;

            // Keep the moved block selected; primary = last moved.
            _selectedNodes.Clear();
            _selectedNodes.AddRange(moved);
            _selectedNode = moved[moved.Count - 1];
            _selectionAnchor = _selectedNode;

            OnModification();
            RefreshHierarchy();
            RefreshProperties();
            RefreshPreview();
        }

        // Organizer multi-drag: relocate the organizer's OWN selection as a block. Keeps _selectedNode
        // on the Tabs container so the organizer stays open and refreshes in place (rather than
        // navigating to a moved card), and keeps the moved cards selected.
        private void HandleOrganizerGroupMove(LayoutNode target, DropRelation relation, int slot = -1)
        {
            var moved = MoveNodesAsBlock(_organizerSelection, target, relation, slot, "Move Tab Items");
            if (moved.Count == 0) return;

            _organizerSelection.Clear();
            _organizerSelection.AddRange(moved);
            _organizerAnchor = moved[moved.Count - 1];

            OnModification();
            RefreshHierarchy();
            RefreshProperties(); // rebuilds the organizer; BuildOrganizerCard re-applies the highlight
            RefreshPreview();
        }

        // Detaches the given top-most nodes and re-inserts them as a contiguous block at the drop
        // target, preserving their relative (tree) order. Wraps each in a fresh tab when the
        // destination is a Tabs container (mirrors the single-move path). Records Undo only when
        // something actually moves. Returns the moved nodes in destination order (empty if none).
        // True while committing a drop that landed on a tracked container's CELL, whose slot is a track
        // ordinal rather than a model index (see CanvasDragController.CommittingCellTrack). Internal so
        // the drop tests can drive the same distinction the live drag does.
        internal bool IsCellTrackCommit()
            => _canvasDragController != null && _canvasDragController.CommittingCellTrack;

        private List<LayoutNode> MoveNodesAsBlock(IList<LayoutNode> topmost, LayoutNode target, DropRelation relation, int slot, string undoLabel)
        {
            var empty = new List<LayoutNode>();
            if (_clonedLayoutAsset == null || target == null || topmost == null) return empty;

            // Drop the root, the target itself, and any ancestor of the target (can't move a subtree
            // into its own descendant) — plus any structural split-Frame pane. Panes are positional
            // identity (exactly two, always); the single-node path refuses them at HandleNodeMoveDrop and
            // the block path has to agree, or the frame is left holding one child and the survivor jumps to
            // the left half with no gesture able to put it back. Filtered HERE rather than left to the
            // chokepoint so the slot re-basing and the re-insert both see the same block.
            var nodes = topmost
                .Where(n => n != null && n != _clonedLayoutAsset.Root && n != target && !IsAncestorOf(n, target))
                .Where(n => SplitFramePaneOwner(n) == null)
                .Distinct()
                .ToList();
            if (nodes.Count == 0) return empty;

            // Insert in tree order so the block keeps its relative arrangement.
            var order = BuildFlatNodeOrder();
            nodes = nodes.OrderBy(n => order.IndexOf(n)).ToList();

            Undo.RecordObject(_clonedLayoutAsset, undoLabel);

            // An explicit slot indexes the target's Children BEFORE the detach pass — capture how many
            // of the moving nodes sat before it so the index can be re-based afterwards.
            // ...unless it is a CELL slot, which is a TRACK ORDINAL: a lifted card's track stays held by a
            // temp "＋" pad, so tracks never renumber and there is nothing to re-base. See IsCellTrackCommit.
            int slotShift = 0;
            if (slot >= 0 && relation == DropRelation.AsChild && target is ContainerNode tcPre && tcPre.Children != null
                && !IsCellTrackCommit())
                foreach (var n in nodes) { int i = tcPre.Children.IndexOf(n); if (i >= 0 && i < slot) slotShift++; }

            // Detach everything first; destination indices are resolved afterwards. Anything the chokepoint
            // declines to detach drops out of the block rather than being "re-inserted" somewhere it never
            // left, so `nodes` from here on is exactly what will be re-parented.
            nodes = RemoveNodesGuarded(nodes, RemovalKind.Detach);
            if (nodes.Count == 0) return empty;

            ContainerNode destParent;
            int destIndex;
            if (relation == DropRelation.AsChild && target is ContainerNode tc)
            {
                destParent = tc;
                if (destParent.Children == null) destParent.Children = new List<LayoutNode>();
                destIndex = slot >= 0 ? Mathf.Clamp(slot - slotShift, 0, destParent.Children.Count) : destParent.Children.Count;
            }
            else
            {
                destParent = FindParent(target, _clonedLayoutAsset.Root);
                if (destParent == null)
                {
                    destParent = _clonedLayoutAsset.Root as ContainerNode;
                    destIndex = destParent?.Children.Count ?? 0;
                }
                else
                {
                    int ti = destParent.Children.IndexOf(target);
                    destIndex = relation == DropRelation.Above ? ti : ti + 1;
                }
            }
            if (destParent == null) return empty;
            if (destParent.Children == null) destParent.Children = new List<LayoutNode>();

            destIndex = Mathf.Clamp(destIndex, 0, destParent.Children.Count);
            // Dropping straight onto a Tabs container wraps each node in a new tab (no-op otherwise).
            // Cell-aware in a tracked container, like the single-node path: the block fills from the
            // targeted cell on, consuming held cells and holding open the ones it skips.
            for (int i = 0; i < nodes.Count; i++)
                EmptyCellFill.InsertAtCell(destParent, WrapAsTabIfNeeded(destParent, nodes[i]), destIndex + i);

            return nodes;
        }

        // Right-click menu on a hierarchy row: wrap / unwrap / delete the selection.
        private void AddRowContextMenu(VisualElement row, LayoutNode node)
        {
            row.RegisterCallback<ContextClickEvent>(evt =>
            {
                // Right-clicking a node outside the current selection selects it first.
                if (!IsNodeSelected(node)) SelectSingle(node);

                var menu = new GenericMenu();
                bool isRoot = node == _clonedLayoutAsset?.Root;
                int count = Mathf.Max(1, _selectedNodes.Count);
                string suffix = HasMultiSelection ? $" ({count})" : "";

                // Containers can be cosmetically renamed in the hierarchy (display-only; the Title
                // and everything on the canvas are untouched). Bindings already show their binding
                // name, so rename stays container-only.
                if (node is ContainerNode)
                {
                    menu.AddItem(new GUIContent("Rename _F2"), false, () => BeginHierarchyRename(node));
                    menu.AddSeparator("");
                }

                if (!isRoot)
                {
                    AddWrapSelectedMenuItems(menu);
                    AddUnwrapMenuItems(menu);
                    menu.AddSeparator("");
                    AddStyleClipboardMenuItems(menu, node, isRoot: false);
                    menu.AddSeparator("");
                    AddDuplicateMenuItem(menu, node);
                    menu.AddItem(new GUIContent(HasMultiSelection ? $"Delete selected{suffix}" : "Delete"), false, () =>
                    {
                        if (HasMultiSelection) DeleteSelectedNodes(); else DeleteNode(node);
                    });
                    menu.AddSeparator("");
                    // Named for its DESTINATION, so it pairs with the canvas card's "Ping in Hierarchy" — from
                    // either panel the entry says where you'll end up looking.
                    menu.AddItem(new GUIContent("Ping on Canvas"), false, () => SelectAndPingNode(node));
                    // Drill into the script an In-Line Editor embeds. Appends nothing for any other node.
                    AppendInlineEditorNavItems(menu, node);
                }
                else
                {
                    menu.AddDisabledItem(new GUIContent("Root node"));
                    menu.AddSeparator("");
                    AddStyleClipboardMenuItems(menu, node, isRoot: true);
                    menu.AddSeparator("");
                    menu.AddItem(new GUIContent("Ping on Canvas"), false, () => SelectAndPingNode(node));
                }
                menu.ShowAsContext();
                evt.StopPropagation();
            });
        }

        // Inline cosmetic rename of a container's hierarchy row (F2 / right-click → Rename): swaps
        // the row label for a TextField in place; Enter/blur commits, Escape cancels. The committed
        // name is display-only (HierarchyName) — the Title and the canvas are untouched. Typing the
        // Title verbatim stores no override, so the row keeps inheriting a later Title edit.
        private void BeginHierarchyRename(LayoutNode node)
        {
            if (!(node is ContainerNode cn) || _clonedLayoutAsset == null) return;

            VisualElement row = null;
            foreach (var hr in _hierRows)
                if (hr.Node == node) { row = hr.Row; break; }
            if (row == null || row.panel == null) return;

            var label = row.Q<Label>("sasq-hier-label");
            if (label == null || label.style.display == DisplayStyle.None) return; // already renaming

            var field = new TextField
            {
                value = !string.IsNullOrEmpty(cn.HierarchyName) ? cn.HierarchyName : (cn.Title ?? "")
            };
            field.style.flexGrow = 1;
            field.style.marginLeft = 0;
            field.style.marginRight = 4;
            row.Insert(row.IndexOf(label), field);
            label.style.display = DisplayStyle.None;

            bool done = false;
            void Commit(bool cancel)
            {
                if (done) return;
                done = true;
                if (!cancel)
                {
                    string v = field.value?.Trim();
                    string next = string.IsNullOrEmpty(v) ? null : v;
                    if (next != null && next == cn.Title) next = null; // Title verbatim = keep inheriting
                    string current = string.IsNullOrEmpty(cn.HierarchyName) ? null : cn.HierarchyName;
                    if (next != current)
                    {
                        Undo.RecordObject(_clonedLayoutAsset, "Rename Container");
                        cn.HierarchyName = next;
                        OnModification();
                    }
                }
                // Cosmetic-only: the hierarchy row re-renders; canvas/properties stay untouched.
                RefreshHierarchy();
            }
            field.RegisterCallback<KeyDownEvent>(e =>
            {
                if (e.keyCode == KeyCode.Return || e.keyCode == KeyCode.KeypadEnter) { Commit(false); e.StopPropagation(); }
                else if (e.keyCode == KeyCode.Escape) { Commit(true); e.StopPropagation(); }
            });
            field.RegisterCallback<FocusOutEvent>(_ => Commit(false));
            field.schedule.Execute(() => { field.Focus(); field.SelectAll(); });
        }

        // A split Frame's two panes are STRUCTURAL children (identity is positional — exactly two,
        // always): they never move between containers, and "deleting" one clears its contents instead
        // of breaking the invariant. Returns the owning split frame, or null when the node isn't a pane.
        private ContainerNode SplitFramePaneOwner(LayoutNode node)
        {
            if (_clonedLayoutAsset == null || _clonedLayoutAsset.Root == null || !(node is ContainerNode)) return null;
            var parent = FindParent(node, _clonedLayoutAsset.Root);
            return IsSplitFrame(parent) ? parent : null;
        }

        private void DeleteNode(LayoutNode node)
        {
            if (_clonedLayoutAsset == null || node == null || node == _clonedLayoutAsset.Root) return;

            // Structural pane: empty it rather than removing it (the frame always keeps two panes).
            if (SplitFramePaneOwner(node) is ContainerNode && node is ContainerNode paneToClear)
            {
                Undo.RecordObject(_clonedLayoutAsset, "Clear Frame Pane");
                paneToClear.Children = new List<LayoutNode>();
                OnModification();
                RefreshHierarchy();
                RefreshProperties();
                RefreshTokens();
                RefreshPreview();
                return;
            }

            if (!PrepareDeleteForLockedSpaces(new[] { node })) return;

            Undo.RecordObject(_clonedLayoutAsset, "Delete Layout Node");

            // Resolve the fall-back selection BEFORE the node comes out: the owning container, or — for a
            // CollectionNode's item-layout template, which lives in a single ItemLayout reference rather
            // than any Children list — the owning collection.
            LayoutNode reselect = (LayoutNode)FindParent(node, _clonedLayoutAsset.Root)
                                  ?? FindItemLayoutOwner(node, _clonedLayoutAsset.Root);
            RemoveNodesGuarded(new[] { node }, RemovalKind.Delete);

            if (_selectedNode == node)
            {
                SetPrimarySelection(reselect);
            }
            _selectedNodes.Remove(node);

            OnModification();
            RefreshHierarchy();
            RefreshProperties();
            RefreshTokens();
            RefreshPreview();
        }

        private void MoveNode(LayoutNode node, int direction)
        {
            if (_clonedLayoutAsset == null || node == null || node == _clonedLayoutAsset.Root) return;

            var parent = FindParent(node, _clonedLayoutAsset.Root);
            if (parent == null || parent.Children == null) return;

            int index = parent.Children.IndexOf(node);
            int targetIdx = index + direction;
            if (targetIdx >= 0 && targetIdx < parent.Children.Count)
            {
                Undo.RecordObject(_clonedLayoutAsset, "Reorder Layout Node");
                parent.Children.RemoveAt(index);
                parent.Children.Insert(targetIdx, node);

                OnModification();
                RefreshHierarchy();
                RefreshPreview();
            }
        }

        private ContainerNode FindParent(LayoutNode child, LayoutNode current)
        {
            if (current == null || child == null) return null;
            if (current is ContainerNode cn)
            {
                if (cn.Children != null && cn.Children.Contains(child)) return cn;
                if (cn.Children != null)
                {
                    foreach (var sub in cn.Children)
                    {
                        var found = FindParent(child, sub);
                        if (found != null) return found;
                    }
                }
            }
            else if (current is CollectionNode col)
            {
                if (col.ItemLayout == child) return null;
                var found = FindParent(child, col.ItemLayout);
                if (found != null) return found;
            }
            return null;
        }

        // The collection whose ITEM LAYOUT this node lives under, at any depth, or null when the node is not
        // in one. Distinct from FindItemLayoutOwner, which only answers for the item layout's ROOT node —
        // an element template usually sits one level down, inside the Panel item container.
        private CollectionNode FindOwningCollection(LayoutNode target)
        {
            return target == null ? null : FindOwningCollectionRecursive(_clonedLayoutAsset?.Root, null, target);
        }

        private static CollectionNode FindOwningCollectionRecursive(LayoutNode current, CollectionNode owner, LayoutNode target)
        {
            if (current == null) return null;
            if (ReferenceEquals(current, target)) return owner;
            if (current is ContainerNode c)
            {
                if (c.Children != null)
                    foreach (var child in c.Children)
                    {
                        var found = FindOwningCollectionRecursive(child, owner, target);
                        if (found != null) return found;
                    }
            }
            else if (current is CollectionNode col && col.ItemLayout != null)
            {
                // Descending into an item layout re-owns everything below it — including a NESTED
                // collection's own template, which belongs to the inner list, not the outer one.
                return FindOwningCollectionRecursive(col.ItemLayout, col, target);
            }
            return null;
        }

        // Returns the CollectionNode whose ItemLayout is (directly) the given node, searching the tree.
        // This is the one parent relationship FindParent intentionally can't express.
        private CollectionNode FindItemLayoutOwner(LayoutNode child, LayoutNode current)
        {
            if (current == null || child == null) return null;
            if (current is CollectionNode col)
            {
                if (col.ItemLayout == child) return col;
                return FindItemLayoutOwner(child, col.ItemLayout);
            }
            if (current is ContainerNode cn && cn.Children != null)
            {
                foreach (var sub in cn.Children)
                {
                    var found = FindItemLayoutOwner(child, sub);
                    if (found != null) return found;
                }
            }
            return null;
        }

        // When a collection is switched to Table mode and has no columns yet, seed one column (a
        // BindingNode) per *direct* element leaf field so the user gets an instant table. Mirrors the
        // +T / drop-to-add-column plumbing (Panel ContainerNode as ItemLayout). Never overwrites an
        // item layout that already has bindings, and leaves nested-struct fields for manual add (v1).
        private void AutoFillTableColumnsIfEmpty(CollectionNode collectionNode)
        {
            if (collectionNode == null || string.IsNullOrEmpty(collectionNode.PropertyPath)) return;
            if (collectionNode.ItemLayout != null && HasAnyBinding(collectionNode.ItemLayout)) return;

            var targetType = ResolveTargetType();
            if (targetType == null) return;

            string prefix = collectionNode.PropertyPath + ".";
            var elementFields = SasquatchReflectionUtility.GetSerializableProperties(targetType)
                .Where(p => !p.isCollection && p.path.StartsWith(prefix))
                .Select(p => p.path.Substring(prefix.Length))
                .Where(rel => !string.IsNullOrEmpty(rel) && !rel.Contains('.')) // direct element leaf fields only
                .ToList();

            // An ATOMIC element has no sub-fields, so its table is the one-column "Value" table — seed that
            // column as a REAL authored node (an element-template binding) rather than leaving the renderer
            // to synthesize a throwaway one. Synthesized columns are rebuilt on every build and so can carry
            // no styling; an authored one is selectable on the canvas and stylable like any other column.
            if (elementFields.Count == 0)
            {
                if (!SupportsElementTemplate(ResolveCollectionElementType(collectionNode),
                                             IsManagedReferenceCollection(collectionNode))) return;
                // One column, and it is the element itself — seeded BARE, so switching an atomic list to
                // Table and back leaves its List rows exactly as they were (see SetElementTemplate).
                SetElementTemplate(collectionNode);
                return;
            }

            if (!(collectionNode.ItemLayout is ContainerNode itemContainer))
            {
                itemContainer = new ContainerNode { StyleToken = "Panel" };
                collectionNode.ItemLayout = itemContainer;
            }
            if (itemContainer.Children == null) itemContainer.Children = new List<LayoutNode>();

            foreach (var rel in elementFields)
            {
                itemContainer.Children.Add(new BindingNode { PropertyPath = rel });
            }
        }

        private bool IsGenericCollection(string propertyPath)
        {
            var targetType = ResolveTargetType();
            if (targetType == null) return false;
            return SasquatchReflectionUtility.IsGenericCollection(targetType, propertyPath);
        }

        private string ModeToChoice(CollectionDisplayMode mode)
        {
            switch (mode)
            {
                case CollectionDisplayMode.List: return "List";
                case CollectionDisplayMode.Table: return "Table";
                case CollectionDisplayMode.Default: return "Default";
                case CollectionDisplayMode.CustomWidget: return "Custom Widget";
                case CollectionDisplayMode.TagChips: return "Tag Chips";
                default: return "List";
            }
        }

        private CollectionDisplayMode ChoiceToMode(string choice)
        {
            switch (choice)
            {
                case "List": return CollectionDisplayMode.List;
                case "Table": return CollectionDisplayMode.Table;
                case "Default": return CollectionDisplayMode.Default;
                case "Custom Widget": return CollectionDisplayMode.CustomWidget;
                case "Tag Chips": return CollectionDisplayMode.TagChips;
                default: return CollectionDisplayMode.List;
            }
        }

        private static bool HasAnyBinding(LayoutNode node)
        {
            switch (node)
            {
                case null: return false;
                case BindingNode _: return true;
                case ContainerNode c:
                    if (c.Children != null)
                    {
                        foreach (var child in c.Children)
                        {
                            if (HasAnyBinding(child)) return true;
                        }
                    }
                    return false;
                default: return false;
            }
        }

