        private void AddHoverHighlight(VisualElement row, Color normal, Color hover)
        {
            row.RegisterCallback<MouseEnterEvent>(evt => row.style.backgroundColor = hover);
            row.RegisterCallback<MouseLeaveEvent>(evt => row.style.backgroundColor = normal);
            EditorSpringFX.HoverScale(row, 1.03f, EditorSpringFX.HoverLiftConfig); // ~3% lift (Widgets/Tools cards)
            row.style.marginRight = Length.Percent(5); // narrow ~5% so the hover lift doesn't force a horizontal scrollbar
        }

        private System.Type ResolveTargetType()
        {
            if (_clonedLayoutAsset == null) return null;

            // Prefer the rename-proof MonoScript GUID; fall back to the legacy type-name string.
            var byGuid = ScriptGuidUtility.ResolveType(_clonedLayoutAsset.ScriptGuid);
            if (byGuid != null) return byGuid;

            return ResolveTypeFromName(_clonedLayoutAsset.TargetTypeName);
        }

        // The C# field type the given binding points at, accounting for its scope in the tree (collection
        // element types + scoped containers). Used to filter the Display Type popup to applicable kinds.
        // Returns null when unresolvable so the caller offers the unfiltered list. Mirrors the quick-edit
        // popup via the shared LayoutFieldTypeResolver.
        private System.Type ResolveSelectedNodeFieldType(BindingNode bn)
        {
            if (_clonedLayoutAsset == null || bn == null) return null;
            var root = _clonedLayoutAsset.Root;
            var indexPath = GetNodeIndexPath(bn, root);
            if (indexPath == null) return null;
            return LayoutFieldTypeResolver.ResolveBoundFieldType(ResolveTargetType(), root, indexPath, bn);
        }

        // Scope-aware FieldInfo for the binding (e.g. to read its [Range] attribute), companion to
        // ResolveSelectedNodeFieldType. Returns null when unresolvable.
        private System.Reflection.FieldInfo ResolveSelectedNodeFieldInfo(BindingNode bn, out System.Type fieldType)
        {
            fieldType = null;
            if (_clonedLayoutAsset == null || bn == null) return null;
            var root = _clonedLayoutAsset.Root;
            var indexPath = GetNodeIndexPath(bn, root);
            if (indexPath == null) return null;
            return LayoutFieldTypeResolver.ResolveBoundFieldInfo(ResolveTargetType(), root, indexPath, bn, out fieldType);
        }

        // The element type of the selected collection, scope-aware (List<T>/T[] -> T). Used to detect a
        // polymorphic ([SerializeReference]) list — whose elements render as type pickers — so its menu
        // styling options can be offered. Reuses the binding resolver by probing the collection's own path
        // in its parent scope. Returns null when unresolvable.
        // Context presets: when a collection is switched between List and Table, re-style its element fields from the
        // matching context override (identity preserved, config swapped). No-op unless a field type actually has an
        // enabled context override, so unrelated hand-tweaks survive an incidental mode flip. Gated by the per-user
        // "Use Layout Presets" toggle. The caller records _clonedLayoutAsset on Undo, so this runs in the same group.
        private void ReseedCollectionForContext(CollectionNode collectionNode, CollectionDisplayMode oldMode, CollectionDisplayMode newMode)
        {
            if (collectionNode == null || !LayoutPresetPrefs.UseLayoutPresets) return;
            var oldCtx = LayoutPresetApplier.ContextFor(oldMode);
            var newCtx = LayoutPresetApplier.ContextFor(newMode);
            if (!oldCtx.HasValue || !newCtx.HasValue) return; // only List <-> Table carry a per-field context
            var preset = LayoutPresetManager.Current;
            if (preset == null) return;
            var elementType = ResolveCollectionElementType(collectionNode);
            if (elementType == null) return;
            LayoutPresetApplier.ReseedCollectionContext(collectionNode, elementType, preset, oldCtx.Value, newCtx.Value);
        }

        private System.Type ResolveCollectionElementType(CollectionNode cn)
        {
            if (_clonedLayoutAsset == null || cn == null || string.IsNullOrEmpty(cn.PropertyPath)) return null;
            var root = _clonedLayoutAsset.Root;
            var indexPath = GetNodeIndexPath(cn, root);
            if (indexPath == null) return null;
            var probe = new BindingNode { PropertyPath = cn.PropertyPath };
            var colType = LayoutFieldTypeResolver.ResolveBoundFieldType(ResolveTargetType(), root, indexPath, probe);
            if (colType == null) return null;
            if (colType.IsArray) return colType.GetElementType();
            if (colType.IsGenericType && colType.GetGenericArguments().Length > 0) return colType.GetGenericArguments()[0];
            return null;
        }

        // True when the collection's elements are POLYMORPHIC ([SerializeReference]) — every row is a type
        // picker rather than a value, which is what excludes it from the element-template offer. Reads the
        // attribute off the FIELD (not the element type): a plain List<SomeClass> serializes by value.
        private bool IsManagedReferenceCollection(CollectionNode cn)
        {
            if (_clonedLayoutAsset == null || cn == null || string.IsNullOrEmpty(cn.PropertyPath)) return false;
            var root = _clonedLayoutAsset.Root;
            var indexPath = GetNodeIndexPath(cn, root);
            if (indexPath == null) return false;
            var probe = new BindingNode { PropertyPath = cn.PropertyPath };
            var fi = LayoutFieldTypeResolver.ResolveBoundFieldInfo(ResolveTargetType(), root, indexPath, probe, out _);
            return fi != null && Attribute.GetCustomAttribute(fi, typeof(SerializeReference)) != null;
        }

        // Same question as IsManagedReferenceCollection, but for a path resolved against the ROOT target type
        // — the form the Bindings panel has (it enumerates reflected paths, not layout nodes).
        private bool IsManagedReferenceCollectionPath(Type targetType, string path)
        {
            if (targetType == null || string.IsNullOrEmpty(path)) return false;
            var fi = BindingFactory.GetFieldInfoFromPropertyPath(targetType, path, out _);
            return fi != null && Attribute.GetCustomAttribute(fi, typeof(SerializeReference)) != null;
        }

        // Resolves a Type from an AssemblyQualifiedName/FullName string (the legacy key format).
        private static System.Type ResolveTypeFromName(string typeName)
        {
            if (string.IsNullOrEmpty(typeName)) return null;

            System.Type type = System.Type.GetType(typeName);
            if (type == null)
            {
                foreach (var assembly in System.AppDomain.CurrentDomain.GetAssemblies())
                {
                    type = assembly.GetType(typeName);
                    if (type != null) break;
                }
            }
            return type;
        }

        // Builds an "overridable float" row for a numeric setting (e.g. Range Min / Max). Two states:
        //   • unset      → the field shows the code/attribute default as a real, editable, NORMAL-weight value.
        //   • overridden → a custom value, shown BOLD (the prefab-style "changed" signal).
        //
        // Visual rule (matching Unity prefab overrides): DEFAULT = normal weight, OVERRIDDEN = bold. Editing the
        // shown value overrides it; a reset arrow (shown only when overridden) restores the code default.
        private VisualElement BuildOverridableFloatField(
            string label, 
            OverridableFloat current, 
            float codeDefault,
            string undoName, 
            System.Action<OverridableFloat> apply, 
            System.Action onValueChanged,
            string fieldTooltip = null)
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;

            var field = new FloatField(label);
            field.style.flexGrow = 1;
            field.style.flexShrink = 1;
            if (!string.IsNullOrEmpty(fieldTooltip)) field.tooltip = fieldTooltip;

            var reset = OverridableTextRow.CreateResetButton("Reset to the script default");

            OverridableFloat stored = current;

            float DisplayValueFor(OverridableFloat s)
            {
                return s.Resolve(codeDefault);
            }

            void UpdateChrome()
            {
                bool isOverride = stored.isOverridden;
                field.style.unityFontStyleAndWeight = isOverride ? FontStyle.Bold : FontStyle.Normal;
                reset.style.display = isOverride ? DisplayStyle.Flex : DisplayStyle.None;
            }

            void Commit(OverridableFloat newStored, bool syncValue)
            {
                stored = newStored;
                Undo.RecordObject(_clonedLayoutAsset, undoName);
                apply(stored);
                OnModification();
                onValueChanged?.Invoke();
                if (syncValue)
                    field.SetValueWithoutNotify(DisplayValueFor(stored));
                UpdateChrome();
            }

            field.SetValueWithoutNotify(DisplayValueFor(stored));

            field.RegisterValueChangedCallback(evt =>
            {
                // Scrubbing this field's label fires per tick — coalesce undo + save + rebuild; the model
                // write, stored state and bold/reset chrome still update live every tick.
                var newStored = new OverridableFloat { isOverridden = true, value = evt.newValue };
                HandleDebouncedValueEdit(undoName, () =>
                {
                    stored = newStored;
                    apply(stored);
                    UpdateChrome();
                }, onValueChanged, liveRebuild: true);
            });
            FlushValueEditOnBlur(field);

            reset.clicked += () =>
            {
                CommitPendingValueEdit(); // close any open scrub burst before this discrete reset
                var newStored = new OverridableFloat { isOverridden = false, value = 0f };
                Commit(newStored, syncValue: true);
            };

            row.Add(field);
            row.Add(reset);
            UpdateChrome();
            return row;
        }

        // The overridable-text row itself lives in OverridableTextRow (shared with the inspector
        // quick-edit popup); this wrapper supplies the designer's commit pipeline (undo on the working
        // clone + debounced save + hierarchy/preview refresh).
        private VisualElement BuildOverridableField(string label, string current, string codeDefault,
            string undoName, System.Action<string> apply, bool refreshHierarchy, string fieldTooltip = null,
            bool debounceText = false, System.Action liveApply = null, bool liveRebuild = false)
        {
            var row = OverridableTextRow.Create(label, current, codeDefault, stored =>
            {
                // Rows the user types free text into opt into the typing-burst path — the per-keystroke
                // undo snapshot + save + synchronous canvas (and hierarchy) rebuild is what made them laggy.
                if (debounceText)
                {
                    HandleDebouncedTextEdit(undoName, () => apply(stored), refreshHierarchy, liveRebuild: liveRebuild);
                    // liveApply (opt-in): after the model write, poke the already-rendered canvas element in
                    // place per keystroke for instant WYSIWYG — while the heavy undo/save/rebuild still ride
                    // the debounce. This is the text counterpart to the continuous-control liveApply (e.g. the
                    // progress-bar Height slider): live pixels now, one coalesced commit once typing pauses.
                    // apply() ran synchronously inside HandleDebouncedTextEdit, so the model is already fresh.
                    // (Rows whose canvas element can vanish when cleared pass liveRebuild instead — the in-place
                    // node rebuild above re-runs the conditional builder, which a text-only poke can't.)
                    liveApply?.Invoke();
                    return;
                }
                Undo.RecordObject(_clonedLayoutAsset, undoName);
                apply(stored);
                OnModification();
                if (refreshHierarchy) RefreshHierarchy();
                RefreshPreview();
            }, fieldTooltip);
            if (debounceText)
            {
                // Blur commits immediately (tabbing/clicking away should never wait out the debounce).
                FlushTextEditOnBlur(row);
                // The row's ↺ reset routes through the same commit delegate, but it's a CLICK, not typing —
                // flush the burst right away so the preview updates at the normal control cadence instead of
                // waiting out the typing pause. (Registered after Create's own clicked handler, so the commit
                // has already run when this fires.)
                var reset = row.Q<Button>();
                if (reset != null) reset.clicked += CommitPendingTextEdit;
            }
            return row;
        }

        private string GetDefaultScriptHeaderName()
        {
            MonoScript script = _previewSerializedObject?.FindProperty("m_Script")?.objectReferenceValue as MonoScript;
            string scriptName = script != null ? script.GetClass()?.Name : null;
            if (string.IsNullOrEmpty(scriptName))
            {
                var target = _previewSerializedObject != null ? _previewSerializedObject.targetObject : null;
                scriptName = target != null ? target.GetType().Name : "Script";
            }
            return scriptName;
        }

        // Code-default resolvers (shared statics in OverridableTextRow, bound to this window's target type).
        private string ResolveCodeTooltip(LayoutNode node) => OverridableTextRow.ResolveCodeTooltip(node, ResolveTargetType());
        private string ResolveCodeLabel(LayoutNode node) => OverridableTextRow.ResolveCodeLabel(node, ResolveTargetType());
        private string ResolveCodeHeader(LayoutNode node) => OverridableTextRow.ResolveCodeHeader(node, ResolveTargetType());

        // Button method suggestions: any user-declared method whose parameters we can all prompt for
        // (zero-param included). Built-in Unity/Object methods (MonoBehaviour.Invoke, ToString, ...) are
        // filtered out to keep the list clean. The parameter list rides along as the suggestion's Detail so
        // it shows (lighter/smaller) in the dropdown without being committed.
        private IEnumerable<AutocompleteTextField.Suggestion> GetInvokableMethodSuggestions(System.Type type)
        {
            if (type == null) return Array.Empty<AutocompleteTextField.Suggestion>();
            // Shared provider (also behind quick-edit and the in-inspector relink row), built on the SAME
            // filter the rename self-heal candidates use — a heal can only land on a method the dropdown
            // would have offered.
            return ButtonInvoker.GetMethodSuggestions(type);
        }

        // C# property suggestions for the PropertyNode picker: the target type's user-declared readable
        // properties (Unity base-class noise filtered by PropertyInvoker), sorted by name. The detail shows
        // the type and get/set shape so the user knows what will render.
        private IEnumerable<AutocompleteTextField.Suggestion> GetReadablePropertySuggestions(System.Type type)
        {
            if (type == null) return Array.Empty<AutocompleteTextField.Suggestion>();
            return PropertyInvoker.GetReadableProperties(type)
                .OrderBy(p => p.Name)
                .Select(p => new AutocompleteTextField.Suggestion(
                    p.Name,
                    FriendlyTypeName(p.PropertyType) + (p.CanWrite ? " { get; set; }" : " { get; }")));
        }

        // "(int amount, string reason)" for a parametered method, or null for a parameterless one.
        private static string FormatParameterList(System.Reflection.MethodInfo m)
        {
            var ps = m.GetParameters();
            if (ps.Length == 0) return null;
            return "(" + string.Join(", ", ps.Select(p => $"{FriendlyTypeName(p.ParameterType)} {p.Name}")) + ")";
        }

        private static string FriendlyTypeName(System.Type t)
        {
            if (t == typeof(int)) return "int";
            if (t == typeof(float)) return "float";
            if (t == typeof(double)) return "double";
            if (t == typeof(long)) return "long";
            if (t == typeof(bool)) return "bool";
            if (t == typeof(string)) return "string";
            return t.Name;
        }

        /// <summary>
        /// The hover peek for a serialized PROPERTY PATH suggestion: resolve the path against the target type
        /// down to its leaf FieldInfo, then show that field's declaration. The attributes above it are the
        /// point — a path tells you the field's name, never that it carries [Range] or [Tooltip]. A nested
        /// path lands on a plain [Serializable] class, which is exactly the case MethodSourcePreview's
        /// same-named-script fallback exists for.
        /// </summary>
        private string FieldPathSnippet(string propertyPath, string basePath = null, System.Type owner = null)
        {
            var root = owner ?? ResolveTargetType();
            if (root == null || string.IsNullOrEmpty(propertyPath)) return null;

            // A scoped node suggests paths RELATIVE to its container, and the suggestion list builds those by
            // trimming exactly `basePath + "."` off a full serializable path — so re-joining them restores the
            // real path, collection element steps and all. Unscoped nodes suggest full paths already.
            if (!string.IsNullOrEmpty(basePath))
            {
                string scoped = SnippetForFieldPath(root, basePath + "." + propertyPath);
                if (scoped != null) return scoped;
            }
            return SnippetForFieldPath(root, propertyPath);
        }

        private static string SnippetForFieldPath(System.Type owner, string path)
        {
            var field = ResolvePathField(owner, path);
            // `owner` is the hint: a nested path's leaf usually lives on a plain [Serializable] class written
            // in the owning script's OWN file, which nothing else can point us at.
            return field == null ? null : MethodSourcePreview.GetFieldSnippet(field.DeclaringType, field.Name, owner);
        }

        /// <summary>
        /// The leaf <see cref="System.Reflection.FieldInfo"/> a designer path points at. Unity's walker
        /// handles the serialized form ("inventory.Array.data[0].itemName"), but the designer's OWN suggestion
        /// list drops the element step for a collection's element fields — "inventory.itemName" is what a
        /// Table column is authored as — so a segment landing on a list or array steps into its element type.
        /// </summary>
        private static System.Reflection.FieldInfo ResolvePathField(System.Type owner, string path)
        {
            var direct = BindingFactory.GetFieldInfoFromPropertyPath(owner, path, out _);
            if (direct != null) return direct;

            var cur = owner;
            System.Reflection.FieldInfo field = null;
            foreach (string segment in path.Split('.'))
            {
                if (cur == null) return null;
                if (segment == "Array" || segment.StartsWith("data[", StringComparison.Ordinal))
                {
                    cur = ElementTypeOf(cur) ?? cur;
                    continue;
                }

                var element = ElementTypeOf(cur);
                if (element != null) cur = element;

                field = FieldIncludingBaseTypes(cur, segment);
                if (field == null) return null;
                cur = field.FieldType;
            }
            return field;
        }

        private static System.Type ElementTypeOf(System.Type type)
        {
            if (type == null) return null;
            if (type.IsArray) return type.GetElementType();
            if (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(List<>))
                return type.GetGenericArguments()[0];
            return null;
        }

        private static System.Reflection.FieldInfo FieldIncludingBaseTypes(System.Type type, string name)
        {
            const System.Reflection.BindingFlags flags =
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public |
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.DeclaredOnly;
            for (var t = type; t != null; t = t.BaseType)
            {
                var f = t.GetField(name, flags);
                if (f != null) return f;
            }
            return null;
        }

        /// <summary>
        /// The hover peek for a CONDITION DRIVER, which is offered as one flat list of serialized field paths
        /// and computed bool members — so it tries both: the path (which may be nested), then a member by
        /// name. The field's own tooltip invites you to point at code, so the peek has to answer for code.
        /// </summary>
        private string ConditionDriverSnippet(string driver)
        {
            // A built-in (IsInPlayMode) has no source to peek at — it is not a member of the target type — and
            // asking anyway costs a reflection miss on every hover.
            if (ConditionDrivers.IsBuiltIn(driver)) return null;
            return FieldPathSnippet(driver) ?? MethodSourcePreview.GetMemberSnippet(ResolveTargetType(), driver);
        }

        // Parameterless methods (instance or static) that return a collection — candidates for a
        // ValueDropdown options source. Excludes void and string (a string is IEnumerable<char> but not a
        // useful option list).
        private IEnumerable<string> GetValueSourceMethodNames(System.Type type)
        {
            if (type == null) return Array.Empty<string>();
            return type.GetMethods(System.Reflection.BindingFlags.Public |
                                   System.Reflection.BindingFlags.NonPublic |
                                   System.Reflection.BindingFlags.Instance |
                                   System.Reflection.BindingFlags.Static)
                .Where(m => m.GetParameters().Length == 0 && !m.IsSpecialName
                            && m.ReturnType != typeof(void) && m.ReturnType != typeof(string)
                            && typeof(System.Collections.IEnumerable).IsAssignableFrom(m.ReturnType))
                .Select(m => m.Name)
                .Distinct();
        }

        private IEnumerable<string> GetValidationMethodNames(System.Type type)
        {
            if (type == null) return Array.Empty<string>();
            return type.GetMethods(System.Reflection.BindingFlags.Public |
                                   System.Reflection.BindingFlags.NonPublic |
                                   System.Reflection.BindingFlags.Instance |
                                   System.Reflection.BindingFlags.Static)
                .Where(m => !m.IsSpecialName
                            && m.ReturnType == typeof(bool)
                            && (m.GetParameters().Length == 0 || m.GetParameters().Length == 1)
                            && IsUserDeclaredValidationMethod(m))
                .Select(m => m.Name)
                .Distinct();
        }

        // Keeps only methods the user actually wrote, mirroring ButtonInvoker.IsUserActionMethod: everything
        // inherited from object (Equals, …) or from Unity's own bases (IsInvoking, CompareTag,
        // TryGetComponent, …) is noise no one would validate against, so it's stripped from the dropdown.
        private static bool IsUserDeclaredValidationMethod(System.Reflection.MethodInfo m)
        {
            return m.DeclaringType != null
                   && m.DeclaringType != typeof(object)
                   && (m.DeclaringType.Namespace == null
                       || !m.DeclaringType.Namespace.StartsWith("UnityEngine"));
        }

        private void UpdateDataTokenCount()
        {
            if (_dataTokensTabBtn == null) return;

            if (_clonedLayoutAsset == null)
            {
                _dataTokensTabBtn.text = "Bindings";
                return;
            }

            var type = ResolveTargetType();
            if (type == null)
            {
                _dataTokensTabBtn.text = "Bindings";
                return;
            }

            var boundPaths = new HashSet<string>();
            var derivedPaths = new HashSet<string>();
            GatherBoundPaths(_clonedLayoutAsset.Root, "", boundPaths, derivedPaths);

            var props = UnboundFieldSync.GetAllProps(type); // memoised; runs on every committed designer edit
            int unused = 0;
            foreach (var prop in props)
            {
                // Derived (group-toggle) bools count as used, so they don't inflate the "unused" badge.
                if (boundPaths.Contains(prop.path) || derivedPaths.Contains(prop.path)) continue;
                // [HideInInspector] fields aren't bindable tokens (excluded from the list below), so they must
                // not inflate the badge either — otherwise it shows "(1)" for a field that isn't even listed.
                if (IsBulkPropertyHidden(type, prop.path)) continue;
                unused++;
            }

            if (unused == 0)
            {
                _dataTokensTabBtn.text = "Bindings";
            }
            else
            {
                // The count rides as RICH TEXT, not a badge child: Yoga only runs a measure function on leaf
                // nodes, so a child Label here would kill the Button's own text sizing. Tinting it instead of
                // wrapping it in parens is what makes it read as a count at a glance, and it stays legible on
                // the idle tab (where the label itself is dimmed) as well as the active one.
                var countHex = ColorUtility.ToHtmlStringRGB(DesignerPalette.DerivedCheck);
                _dataTokensTabBtn.text = $"Bindings <b><color=#{countHex}>{unused}</color></b>";
            }
        }

        /// <summary>
        /// Paints ONE left tab for its active/idle state. The build site and <see cref="UpdateTabVisuals"/>
        /// both go through here so the two can never drift apart.
        ///
        /// ACTIVE is the folder tab: <see cref="DesignerPalette.PanelBg"/> — the panel's own colour — the
        /// accent cap on its top edge, and <c>marginBottom -1</c> so it overhangs the bar's divider and that
        /// hairline stops at its edges. IDLE is fully transparent, so the recessed track shows through and
        /// the divider runs unbroken beneath it.
        ///
        /// Reads the palette LIVE rather than capturing it, so a skin flip lands on the next call.
        /// </summary>
        internal static void ApplyLeftTabVisual(Button tabBtn, bool active)
        {
            if (tabBtn == null) return;
            tabBtn.style.backgroundColor = active ? DesignerPalette.PanelBg : Color.clear;
            tabBtn.style.color = active ? DesignerPalette.TextBright : DesignerPalette.TextMuted;
            tabBtn.style.borderTopColor = active ? DesignerPalette.Accent : Color.clear;
            // The other three sides carry ZERO width, but they still need an inline colour. A rounded corner
            // is tessellated from BOTH of the edges that meet there, so the top-left/top-right arcs sample the
            // side border colour even at width 0 — and those colours are otherwise left to the editor theme,
            // whose `.unity-button:hover/:active/:focus` rules repaint them the instant you press a tab. That
            // painted a blue pinprick into the corner of the accent cap on every mouse-down. Only an INLINE
            // value outranks a USS pseudo-state, so pin all three here rather than trusting width 0 to hide
            // them; `focusable = false` at the build site closes the same leak from the other end.
            tabBtn.style.borderLeftColor = Color.clear;
            tabBtn.style.borderRightColor = Color.clear;
            tabBtn.style.borderBottomColor = Color.clear;
            tabBtn.style.unityFontStyleAndWeight = active ? FontStyle.Bold : FontStyle.Normal;
            tabBtn.style.marginBottom = active ? -1 : 0;
        }

        private void UpdateTabVisuals()
        {
            ApplyLeftTabVisual(_dataTokensTabBtn, _activeLeftTab == 0);
            ApplyLeftTabVisual(_widgetsTabBtn, _activeLeftTab == 1);
            ApplyLeftTabVisual(_toolsTabBtn, _activeLeftTab == 2);
        }

        private void RefreshTokens()
        {
            UpdateTabVisuals();
            UpdateDataTokenCount();
            if (_tokenBankContainer == null) return;
            _tokenBankContainer.Clear();

            if (_presetMode)
            {
                RenderPresetCategories();
                return;
            }

            // The token multi-selection only lives on the Bindings tab — drop it on Widgets/Tools.
            if (_activeLeftTab != 0) _bindingSelection.Clear();

            if (_activeLeftTab == 1)
            {
                RenderWidgetsPalette();
                return;
            }

            if (_activeLeftTab == 2)
            {
                RenderBulkTools();
                return;
            }

            var type = ResolveTargetType();
            if (type == null)
            {
                var lbl = new Label("Token Bank requires a valid target type.");
                lbl.style.color = DesignerPalette.TextDisabled;
                lbl.style.whiteSpace = WhiteSpace.Normal;
                _tokenBankContainer.Add(lbl);
                return;
            }

            var boundPaths = new HashSet<string>();
            var derivedPaths = new HashSet<string>();
            GatherBoundPaths(_clonedLayoutAsset.Root, "", boundPaths, derivedPaths);

            var props = UnboundFieldSync.GetAllProps(type) // memoised; rebuilt on every committed designer edit
                // [HideInInspector] fields aren't offered as bindable tokens (the developer hid them on purpose,
                // matching the Tools-tab import behavior). A hidden field that's somehow ALREADY bound/derived
                // still shows (dimmed/checked) so it stays manageable rather than silently vanishing.
                .Where(p => boundPaths.Contains(p.path) || derivedPaths.Contains(p.path) || !IsBulkPropertyHidden(type, p.path))
                .ToList();
            // Element fields of a collection (e.g. "modifications.modName") are shown indented under
            // their collection with their element-relative name, so they read as "fields of an item."
            var collectionPrefixes = props.Where(p => p.isCollection).Select(p => p.path + ".").ToList();

            // ELEMENT TEMPLATES. A collection whose elements are ATOMIC (List<Vector2>, List<float>, an enum
            // list) contributes no element fields above, so the panel showed the collection and nothing else
            // — and there was then no binding anywhere to hang a widget or any styling on. Give each one a
            // single synthetic child token standing for the element ITSELF, indented under its collection
            // exactly like a struct element's fields, so every collection reads the same way: here is what
            // one item is made of. Inserted BACKWARDS so the indices of the not-yet-visited entries hold.
            var elementTokens = new Dictionary<string, Type>();       // token path -> element type
            var templatedPaths = new HashSet<string>();               // collections already carrying one
            UnboundFieldSync.GatherElementTemplatePaths(_clonedLayoutAsset.Root, "", templatedPaths);
            for (int i = props.Count - 1; i >= 0; i--)
            {
                var cp = props[i];
                if (!cp.isCollection) continue;
                SasquatchReflectionUtility.IsCollectionType(cp.type, out var elemType);
                if (!SupportsElementTemplate(elemType, IsManagedReferenceCollectionPath(type, cp.path))) continue;
                string tokenPath = ElementTokenPrefix + cp.path;
                elementTokens[tokenPath] = elemType;
                props.Insert(i + 1, new SasquatchReflectionUtility.ReflectedProperty
                {
                    path = tokenPath,
                    type = elemType,
                    isCollection = false
                });
            }

            // Stretch, NOT FlexStart: a shrink-to-fit wrapper sized itself to the WIDEST token's natural
            // width, so a type whose fields are all short names ("slots", "label") rendered a column of
            // stunted cards hugging the left edge, while a type with one long path filled the panel — the
            // same panel looked like two different widgets. The overflow this wrapper was introduced to
            // contain is already handled by the rows themselves (flexShrink 0 on the icons/checks, and
            // minWidth 0 + NoWrap + ellipsis on the name label), so the hug bought nothing. Full width also
            // matches the Widgets/Tools cards, which have always stretched.
            var contentWrapper = new VisualElement();
            contentWrapper.style.alignSelf = Align.Stretch;
            contentWrapper.style.alignItems = Align.Stretch;
            contentWrapper.style.flexDirection = FlexDirection.Column;
            contentWrapper.style.maxWidth = Length.Percent(100);

            foreach (var prop in props)
            {
                string displayName = prop.path;
                bool isElementField = false;
                // The element token reads as a child of its collection like any other element field — same
                // indent, same ↳ glyph — because that is exactly what it is: the one "field" an atomic
                // element has, which is the element.
                bool isElementToken = elementTokens.ContainsKey(prop.path);
                if (isElementToken)
                {
                    displayName = "Element";
                    isElementField = true;
                }
                else
                {
                    foreach (var cp in collectionPrefixes)
                    {
                        if (prop.path.StartsWith(cp)) { displayName = prop.path.Substring(cp.Length); isElementField = true; break; }
                    }
                }

                var tokenRow = new VisualElement();
                tokenRow.style.flexDirection = FlexDirection.Row;
                tokenRow.style.alignItems = Align.Center;
                // Same card metrics as CreateWidgetPaletteRow — the three left tabs are one card family.
                tokenRow.style.paddingTop = 6;
                tokenRow.style.paddingBottom = 6;
                tokenRow.style.paddingLeft = 10;
                tokenRow.style.paddingRight = 10;
                tokenRow.style.marginBottom = 4;
                if (isElementField) tokenRow.style.marginLeft = 14; // indent under the collection
                
                var normalBg = DesignerPalette.RowBg;
                var hoverBg = DesignerPalette.RowHoverBg;
                tokenRow.style.backgroundColor = normalBg;
                tokenRow.style.borderTopWidth = 1;
                tokenRow.style.borderBottomWidth = 1;
                tokenRow.style.borderLeftWidth = 1;
                tokenRow.style.borderRightWidth = 1;
                tokenRow.style.borderTopColor = DesignerPalette.BorderMid;
                tokenRow.style.borderBottomColor = DesignerPalette.BorderMid;
                tokenRow.style.borderLeftColor = DesignerPalette.BorderMid;
                tokenRow.style.borderRightColor = DesignerPalette.BorderMid;
                tokenRow.style.borderTopLeftRadius = 4;
                tokenRow.style.borderTopRightRadius = 4;
                tokenRow.style.borderBottomLeftRadius = 4;
                tokenRow.style.borderBottomRightRadius = 4;

                if (isElementToken)
                {
                    tokenRow.tooltip =
                        "One item of this list. Drag it in to get a binding for the element itself — then " +
                        "give it a widget and style it like any other field, and every row follows.";
                }

                // An element template has no path of its own (that is the whole point), so "already in the
                // layout" is a STRUCTURAL question about its collection, not a lookup in boundPaths.
                bool isBound = isElementToken
                    ? templatedPaths.Contains(prop.path.Substring(ElementTokenPrefix.Length))
                    : boundPaths.Contains(prop.path);
                // "Derived" = the bool is in use as a group-toggle header checkbox, not an explicit binding.
                bool isDerived = !isBound && !isElementToken && derivedPaths.Contains(prop.path);
                if (isBound || isDerived)
                {
                    // Same dimmed shade as any used binding; the derived case is distinguished only by its check.
                    tokenRow.style.opacity = 0.5f;
                    if (isDerived)
                        tokenRow.tooltip = "Used as a group toggle — this bool drives a Foldout group's header checkbox.";

                    if (isBound)
                    {
                        tokenRow.AddToClassList("sasq-clickable");
                        // Hover must NOT just restore full opacity — at 100% a hovered used row is
                        // pixel-identical to an idle unused row. Brighten partially AND shift to the
                        // shared hover background so it reads as "hover", not as "unused".
                        tokenRow.RegisterCallback<MouseOverEvent>(_ =>
                        {
                            tokenRow.style.opacity = 0.85f;
                            tokenRow.style.backgroundColor = hoverBg;
                        });
                        tokenRow.RegisterCallback<MouseOutEvent>(_ =>
                        {
                            tokenRow.style.opacity = 0.5f;
                            tokenRow.style.backgroundColor = normalBg;
                        });
                        tokenRow.RegisterCallback<MouseDownEvent>(evt =>
                        {
                            if (evt.button != 0) return;
                            // The template has no path to look up, so ping the NODE — found through the
                            // collection it belongs to.
                            if (isElementToken) PingElementTemplate(prop.path.Substring(ElementTokenPrefix.Length));
                            else PingBinding(prop.path);
                        });
                    }
                }
                else
                {
                    // Unused → draggable AND multi-selectable. Tag the row so highlight/range queries
                    // find it, and use a selection-aware hover so a selected row keeps its blue.
                    string capturedPath = prop.path;
                    tokenRow.userData = capturedPath;
                    tokenRow.AddToClassList("sasq-token-row");
                    if (_bindingSelection.Contains(capturedPath)) tokenRow.style.backgroundColor = TokenRowSelectedBg;
                    tokenRow.RegisterCallback<MouseEnterEvent>(_ =>
                    {
                        if (!_bindingSelection.Contains(capturedPath)) tokenRow.style.backgroundColor = hoverBg;
                    });
                    tokenRow.RegisterCallback<MouseLeaveEvent>(_ =>
                        tokenRow.style.backgroundColor = _bindingSelection.Contains(capturedPath) ? TokenRowSelectedBg : normalBg);
                }
                EditorSpringFX.HoverScale(tokenRow, 1.03f, EditorSpringFX.HoverLiftConfig); // ~3% lift (Bindings tokens)
                tokenRow.style.marginRight = Length.Percent(5); // narrow ~5% so the hover lift doesn't force a horizontal scrollbar

                var iconEl = SasquatchIcons.Create(prop.isCollection ? SasquatchIcons.Ids.Layers
                    : (isElementField ? SasquatchIcons.Ids.CornerDownRight : SasquatchIcons.Ids.Diamond), 12);
                iconEl.style.marginRight = 6;
                tokenRow.Add(iconEl);

                var nameLbl = new Label(displayName);
                nameLbl.style.color = DesignerPalette.TextPrimary;
                nameLbl.style.flexShrink = 1;
                nameLbl.style.minWidth = 0;
                nameLbl.style.whiteSpace = WhiteSpace.NoWrap;
                nameLbl.style.overflow = Overflow.Hidden;
                nameLbl.style.textOverflow = TextOverflow.Ellipsis;

                if (_showBindingTypes && prop.type != null)
                {
                    tokenRow.Add(nameLbl);

                    var typeLbl = new Label($"[{SasquatchReflectionUtility.GetFriendlyTypeName(prop.type)}]");
                    typeLbl.style.fontSize = 10f;
                    typeLbl.style.color = DesignerPalette.TypeAccent;
                    StyleTypeTagRowLabels(nameLbl, typeLbl); // squish rules, shared with the Preset Editor's TYPES rows
                    tokenRow.Add(typeLbl);
                }
                else
                {
                    nameLbl.style.flexGrow = 1;
                    tokenRow.Add(nameLbl);
                }

                if (isBound && _preventDuplicateBindings)
                {
                    // Locked: this field is already in the layout and duplicates are disabled.
                    var checkIcon = SasquatchIcons.Create(SasquatchIcons.Ids.Check, 12, DesignerPalette.SuccessIcon);
                    checkIcon.style.marginLeft = 6;
                    checkIcon.pickingMode = PickingMode.Position; // tooltips need hover picking
                    checkIcon.tooltip = "Already in the layout. Turn off \"Disable Duplicate Bindings\" in the gear (settings) menu to add it again.";
                    tokenRow.Add(checkIcon);
                }
                else if (isDerived)
                {
                    // Distinct marker (soft blue check) so a derived toggle use is told apart from a green binding.
                    var derivedIcon = SasquatchIcons.Create(SasquatchIcons.Ids.Check, 12, DesignerPalette.DerivedCheck);
                    derivedIcon.style.marginLeft = 6;
                    derivedIcon.pickingMode = PickingMode.Position; // tooltips need hover picking
                    derivedIcon.tooltip = "Used as a group toggle";
                    tokenRow.Add(derivedIcon);
                }
                else if (_canvasDragController != null)
                {
                    // Draggable. When duplicates are allowed, an already-bound field stays draggable
                    // (dimmed) so it can be intentionally added more than once.
                    if (isBound)
                    {
                        var dupIcon = SasquatchIcons.Create(SasquatchIcons.Ids.Check, 12, DesignerPalette.CheckMuted);
                        dupIcon.style.marginLeft = 6;
                        dupIcon.pickingMode = PickingMode.Position; // tooltips need hover picking
                        dupIcon.tooltip = "Already in the layout — drag to add another copy (duplicates allowed).";
                        tokenRow.Add(dupIcon);
                    }
                    tokenRow.AddManipulator(new CanvasDragManipulator(
                        _canvasDragController, CanvasDragPayload.AddBinding(prop.path, prop.isCollection)));
                }

                contentWrapper.Add(tokenRow);
            }

            // C# properties — ALL readable, user-declared properties on the target type (Unity base-class
            // noise filtered by PropertyInvoker; no attribute needed). Split by whether they're in the layout
            // yet, so the section reads like the field tokens above it: a PLACED property is a used token
            // (top-level, dimmed, checked, click pings it), while the ones still ADDABLE collapse into ONE
            // "C# Properties" card — click to reveal their draggable rows, or drag the card to add them all.
            // Flooding the list with a row per property was what the card was introduced to avoid; bounding it
            // to the addable ones keeps that, without burying a placed property behind a fold.
            var allProps = new List<string>();
            foreach (var pi in PropertyInvoker.GetReadableProperties(type)) allProps.Add(pi.Name);
            allProps.Sort(System.StringComparer.OrdinalIgnoreCase);
            if (allProps.Count > 0)
            {
                var placedProps = new HashSet<string>();
                CollectPropertyNodeNames(_clonedLayoutAsset.Root, placedProps);

                // Already-placed properties ping (not re-add); the "add all" card only drops the rest.
                var unplacedProps = new List<string>();
                var placedInOrder = new List<string>();
                foreach (var p in allProps)
                {
                    if (placedProps.Contains(p)) placedInOrder.Add(p);
                    else unplacedProps.Add(p);
                }

                var headerLbl = new Label("C# PROPERTIES");
                headerLbl.style.fontSize = 10;
                headerLbl.style.unityFontStyleAndWeight = FontStyle.Bold;
                headerLbl.style.color = DesignerPalette.TextMuted;
                headerLbl.style.marginTop = 8;
                headerLbl.style.marginBottom = 4;
                contentWrapper.Add(headerLbl);

                var propNormalBg = DesignerPalette.RowBg;
                var propHoverBg = DesignerPalette.RowHoverBg;
                var propBorder = DesignerPalette.BorderMid;

                // ---- Placed properties: TOP-LEVEL rows, exactly like a used field token -------------------
                // A property that's already in the layout is not "noise to collapse away" — it's a binding the
                // user put there and will want to find again, so it sits at the same level as a used field
                // token: always visible, dimmed, checked, and a click PINGS its widget. Leaving these inside
                // the collapsed card meant the only thing on screen for a just-added property was the card
                // header, which toggles instead of pinging — reported as "clicking it doesn't ping the field".
                foreach (var propName in placedInOrder)
                    contentWrapper.Add(BuildPropertyTokenRow(propName, placed: true, indent: false));

                // ---- The collapsible card header (click = expand/collapse, drag = add the REST) -----------
                // Only rendered while something is still addable: with every property placed there is nothing
                // to add and nothing left to reveal, and a checked-but-inert header is the exact thing that
                // read as a broken ping.
                if (unplacedProps.Count > 0)
                {
                    var card = new VisualElement();
                    card.style.flexDirection = FlexDirection.Row;
                    card.style.alignItems = Align.Center;
                    card.style.paddingTop = 6; card.style.paddingBottom = 6;
                    card.style.paddingLeft = 10; card.style.paddingRight = 10;
                    card.style.marginBottom = 4;
                    card.style.backgroundColor = propNormalBg;
                    card.style.borderTopWidth = 1; card.style.borderBottomWidth = 1;
                    card.style.borderLeftWidth = 1; card.style.borderRightWidth = 1;
                    card.style.borderTopColor = propBorder; card.style.borderBottomColor = propBorder;
                    card.style.borderLeftColor = propBorder; card.style.borderRightColor = propBorder;
                    card.style.borderTopLeftRadius = 4; card.style.borderTopRightRadius = 4;
                    card.style.borderBottomLeftRadius = 4; card.style.borderBottomRightRadius = 4;
                    card.tooltip = "Click to list the properties that aren't in your layout yet; drag onto the canvas to add all of them.";

                    var chevron = SasquatchIcons.Create(SasquatchIcons.Ids.ChevronRight, 12); // single glyph; spun on toggle
                    chevron.style.marginRight = 4;
                    card.Add(chevron);
                    _propCardChevron = chevron;
                    EditorSpringFX.SpringCaret(chevron, _propertiesCardExpanded, animate: false);

                    var cardIcon = SasquatchIcons.Create(SasquatchIcons.Ids.Crosshair, 12);
                    cardIcon.style.marginRight = 6;
                    card.Add(cardIcon);

                    // The count is what the card CARRIES (and what a drag would add) — placed properties have
                    // their own rows above it, so counting them here would promise rows that aren't inside.
                    var cardLbl = new Label($"C# Properties ({unplacedProps.Count})");
                    cardLbl.style.color = DesignerPalette.TextPrimary;
                    cardLbl.style.flexGrow = 1;
                    cardLbl.style.whiteSpace = WhiteSpace.NoWrap;
                    cardLbl.style.overflow = Overflow.Hidden;
                    cardLbl.style.textOverflow = TextOverflow.Ellipsis;
                    card.Add(cardLbl);

                    card.RegisterCallback<MouseEnterEvent>(_ => card.style.backgroundColor = propHoverBg);
                    card.RegisterCallback<MouseLeaveEvent>(_ => card.style.backgroundColor = propNormalBg);
                    EditorSpringFX.HoverScale(card, 1.03f, EditorSpringFX.HoverLiftConfig); // ~3% lift (C# Properties card)
                    card.style.marginRight = Length.Percent(5); // narrow ~5% so the hover lift doesn't force a horizontal scrollbar

                    // Drag adds exactly what the card carries: the properties not already in the layout.
                    if (_canvasDragController != null)
                        card.AddManipulator(new CanvasDragManipulator(
                            _canvasDragController, CanvasDragPayload.AddProperties(unplacedProps)));

                    contentWrapper.Add(card);

                    // ---- The individual addable rows (each draggable on its own). Built into a
                    // container that spring-folds in place on expand/collapse (no full rebuild). ----
                    var propRows = new VisualElement();
                    propRows.style.display = _propertiesCardExpanded ? DisplayStyle.Flex : DisplayStyle.None;
                    _propCardRows = propRows;
                    contentWrapper.Add(propRows);
                    foreach (var propName in unplacedProps)
                        propRows.Add(BuildPropertyTokenRow(propName, placed: false, indent: true));
                }
                else
                {
                    // No card this pass — clear the fold targets so a stale toggle can't animate a
                    // detached container from the previous render.
                    _propCardRows = null;
                    _propCardChevron = null;
                }
            }

            _tokenBankContainer.Add(contentWrapper);

            // Drop selected tokens that no longer render as draggable (now bound, type changed, etc.).
            var liveTokens = BuildBindingTokenOrder();
            _bindingSelection.RemoveAll(p => !liveTokens.Contains(p));

            RefreshBindingHighlights();
        }

        // One row in the Bindings tab's "C# PROPERTIES" section. The two states are deliberately the same
        // pair a FIELD token has, so the property list behaves like the rest of the panel:
        //   placed  → dimmed + green check, `sasq-clickable`, click PINGS the node (never re-added, never
        //             multi-selected). Rendered at top level, so it's reachable without opening the card.
        //   unplaced→ a draggable/selectable token inside the collapsible card; `userData` must be the drag
        //             payload's Path ("Property:<name>") so the highlight/range queries and ResolveAddGroup
        //             line up (see BuildBindingTokenOrder).
        private VisualElement BuildPropertyTokenRow(string propertyName, bool placed, bool indent)
        {
            var normalBg = DesignerPalette.RowBg;
            var hoverBg = DesignerPalette.RowHoverBg;
            var border = DesignerPalette.BorderMid;
            string captured = propertyName;
            string tokenPath = "Property:" + captured;

            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.paddingTop = 6; row.style.paddingBottom = 6;
            row.style.paddingLeft = 10; row.style.paddingRight = 10;
            row.style.marginBottom = 4;
            if (indent) row.style.marginLeft = 12; // indent under the card so the grouping reads
            row.style.backgroundColor = normalBg;
            row.style.borderTopWidth = 1; row.style.borderBottomWidth = 1;
            row.style.borderLeftWidth = 1; row.style.borderRightWidth = 1;
            row.style.borderTopColor = border; row.style.borderBottomColor = border;
            row.style.borderLeftColor = border; row.style.borderRightColor = border;
            row.style.borderTopLeftRadius = 4; row.style.borderTopRightRadius = 4;
            row.style.borderBottomLeftRadius = 4; row.style.borderBottomRightRadius = 4;
            EditorSpringFX.HoverScale(row, 1.03f, EditorSpringFX.HoverLiftConfig); // ~3% lift (property rows)
            row.style.marginRight = Length.Percent(5); // narrow ~5% so the hover lift doesn't force a horizontal scrollbar

            if (placed) row.style.opacity = 0.5f;

            var icon = SasquatchIcons.Create(SasquatchIcons.Ids.Crosshair, 12);
            icon.style.marginRight = 6;
            row.Add(icon);

            var lbl = new Label(captured);
            lbl.style.color = DesignerPalette.TextPrimary;
            lbl.style.flexGrow = 1;
            lbl.style.whiteSpace = WhiteSpace.NoWrap;
            lbl.style.overflow = Overflow.Hidden;
            lbl.style.textOverflow = TextOverflow.Ellipsis;
            row.Add(lbl);

            if (placed)
            {
                var check = SasquatchIcons.Create(SasquatchIcons.Ids.Check, 12, DesignerPalette.CheckMuted);
                check.style.marginLeft = 6;
                check.pickingMode = PickingMode.Position; // tooltips need hover picking
                check.tooltip = "Already in the layout — click to ping it.";
                row.Add(check);

                row.AddToClassList("sasq-clickable");
                // Hover must NOT just restore full opacity — at 100% a hovered used row is pixel-identical
                // to an idle unused one. Shift to the shared hover background instead (the used-field-token
                // rule), so it reads as "hover", not as "unused".
                row.RegisterCallback<MouseEnterEvent>(_ =>
                {
                    row.style.opacity = 0.85f;
                    row.style.backgroundColor = hoverBg;
                });
                row.RegisterCallback<MouseLeaveEvent>(_ =>
                {
                    row.style.opacity = 0.5f;
                    row.style.backgroundColor = normalBg;
                });
                row.RegisterCallback<MouseDownEvent>(evt => { if (evt.button == 0) PingProperty(captured); });
                return row;
            }

            row.userData = tokenPath;
            row.AddToClassList("sasq-token-row");
            if (_bindingSelection.Contains(tokenPath)) row.style.backgroundColor = TokenRowSelectedBg;
            row.RegisterCallback<MouseEnterEvent>(_ =>
            {
                if (!_bindingSelection.Contains(tokenPath)) row.style.backgroundColor = hoverBg;
            });
            row.RegisterCallback<MouseLeaveEvent>(_ =>
                row.style.backgroundColor = _bindingSelection.Contains(tokenPath) ? TokenRowSelectedBg : normalBg);

            if (_canvasDragController != null)
                row.AddManipulator(new CanvasDragManipulator(
                    _canvasDragController, CanvasDragPayload.AddProperty(captured)));
            return row;
        }

        // Collects the property names already bound by PropertyNodes anywhere in the tree. This is what
        // splits the Bindings tab's "C# PROPERTIES" section: placed → a checked, pingable top-level row;
        // everything else → the collapsible "add these" card.
        private static void CollectPropertyNodeNames(LayoutNode node, HashSet<string> into)
        {
            if (node == null) return;
            if (node is PropertyNode pn && !string.IsNullOrEmpty(pn.PropertyName)) into.Add(pn.PropertyName);
            if (node is ContainerNode c && c.Children != null)
            {
                foreach (var child in c.Children) CollectPropertyNodeNames(child, into);
            }
            else if (node is CollectionNode col && col.ItemLayout != null)
            {
                CollectPropertyNodeNames(col.ItemLayout, into);
            }
        }

        private void RenderWidgetsPalette()
        {
            var containersContent = CreateToolSection("CONTAINERS", _widgetsContainersExpanded,
                v => _widgetsContainersExpanded = v, marginTop: 8);
            var elementsContent = CreateToolSection("ELEMENTS", _widgetsElementsExpanded,
                v => _widgetsElementsExpanded = v, marginTop: 14);

            foreach (var item in WidgetPaletteItems)
            {
                var section = item.type.StartsWith("Container:") ? containersContent : elementsContent;
                section.Add(CreateWidgetPaletteRow(item.icon, item.label, item.type, item.tooltip));
            }
        }

        private void RenderBulkTools()
        {
            if (_tokenBankContainer == null) return;
            _tokenBankContainer.Clear();

            var type = ResolveTargetType();
            if (type == null)
            {
                var lbl = new Label("Tools require a valid target type. Select an object or layout to begin.");
                lbl.style.color = DesignerPalette.TextDisabled;
                lbl.style.whiteSpace = WhiteSpace.Normal;
                lbl.style.paddingTop = 15;
                lbl.style.paddingLeft = 10;
                lbl.style.paddingRight = 10;
                _tokenBankContainer.Add(lbl);
                return;
            }

            // ---- Availability (computed once; RenderBulkTools re-runs on every edit/settings change) ----
            var root = _clonedLayoutAsset != null ? _clonedLayoutAsset.Root as ContainerNode : null;

            // How many script fields the import tools could still add. With "Disable Duplicate Bindings" on
            // and nothing unbound, every importer is a no-op, so grey them out (duplicates-allowed = always on).
            var boundPaths = new HashSet<string>();
            if (_clonedLayoutAsset != null && _clonedLayoutAsset.Root != null)
                GatherBoundPaths(_clonedLayoutAsset.Root, "", boundPaths, derivedPaths: boundPaths);
            bool hasUnbound = GetBulkAddProperties(type).Any(p => !boundPaths.Contains(p.path));
            bool importsEnabled = !_preventDuplicateBindings || hasUnbound;
            const string allBoundReason = "Every field is already in the layout.";

            bool layoutNonEmpty = root != null && root.Children != null && root.Children.Count > 0;

            // ---- SETUP & GENERATION (collapsible) ----
            var genContent = CreateToolSection("SETUP & GENERATION", _toolsSetupExpanded,
                v => _toolsSetupExpanded = v, marginTop: 8);

            // Use Layout Presets — per-user (EditorPrefs). When on, the import tools below apply the active Layout
            // Preset's widget + config per field type (rich text, gradient, curve, dropdown, asset preview…) instead
            // of plain default fields. On by default so the good widgets are the path of least resistance.
            var presetToggle = new Toggle("Use Layout Presets") { value = LayoutPresetPrefs.UseLayoutPresets };
            presetToggle.AddToClassList("sq-toggle");          // our rounded pill switch instead of the default checkbox
            presetToggle.AddToClassList("sq-toggle--rounded");
            EditorSpringFX.SpringToggleKnob(presetToggle);
            presetToggle.style.alignItems = Align.Center;
            presetToggle.tooltip = "Imported fields adopt your Layout Preset's default widget + configuration for " +
                                   "their type. Turn off to import plain Unity fields. Set in Project Settings → Sasquatch Inspector.";
            presetToggle.style.marginLeft = 2;
            presetToggle.style.marginBottom = 8;
            presetToggle.RegisterValueChangedCallback(evt => LayoutPresetPrefs.UseLayoutPresets = evt.newValue);
            genContent.Add(presetToggle);

            // Apply to Subclasses — per-LAYOUT (persisted by Save, unlike the per-user preset toggle above):
            // subclasses without a layout of their own inherit this one; editing a subclass then saves a
            // separate override. Hidden in preset/showcase sessions (they never save to the registry) and
            // for sealed types (no subclasses to apply to).
            if (!_presetMode && string.IsNullOrEmpty(_showcaseOverrideKey) && _clonedLayoutAsset != null && !type.IsSealed)
            {
                var inheritToggle = new Toggle("Apply to Subclasses") { value = _clonedLayoutAsset.ApplyToSubclasses };
                inheritToggle.AddToClassList("sq-toggle");
                inheritToggle.AddToClassList("sq-toggle--rounded");
                EditorSpringFX.SpringToggleKnob(inheritToggle);
                inheritToggle.style.alignItems = Align.Center;
                inheritToggle.tooltip = $"Subclasses of {type.Name} that have no layout of their own render with this one " +
                                        "(their extra fields are appended automatically) — including subclasses you write " +
                                        "later, with no need to come back here. Editing a subclass and saving creates a " +
                                        "separate override layout for it, which also stops the inheritance from reaching " +
                                        "ITS subclasses. Stored with this layout on save.";
                inheritToggle.style.marginLeft = 2;
                inheritToggle.style.marginBottom = 0;
                genContent.Add(inheritToggle);

                // Live read-out under the toggle: without it, ticking the box gives no feedback at all — you save
                // and nothing visibly happens, so "did that do anything?" / "what about subclasses I add later?"
                // are left open. Answers both at the point of decision. Recomputed on toggle (cheap — see
                // CountInheritingSubclasses) rather than via a full RenderBulkTools pass, which would rebuild
                // the whole panel and drop the toggle's focus.
                var inheritHint = new Label();
                inheritHint.style.fontSize = 10;
                inheritHint.style.color = DesignerPalette.TextMuted;
                inheritHint.style.whiteSpace = WhiteSpace.Normal;
                inheritHint.style.marginLeft = 2;
                inheritHint.style.marginBottom = 8;
                inheritHint.text = DescribeSubclassInheritance(type, _clonedLayoutAsset.ApplyToSubclasses);
                genContent.Add(inheritHint);

                inheritToggle.RegisterValueChangedCallback(evt =>
                {
                    Undo.RecordObject(_clonedLayoutAsset, "Toggle Apply to Subclasses");
                    _clonedLayoutAsset.ApplyToSubclasses = evt.newValue;
                    inheritHint.text = DescribeSubclassInheritance(type, evt.newValue);
                    OnModification();
                });
            }

            // Smart Attribute Import — the gold hover hint is the only "recommended" cue; nothing labels it.
            genContent.Add(CreateToolRow(
                SasquatchIcons.Ids.Sparkles,
                "Smart Attribute Import",
                "Import all fields formatted using attributes like [Range], [Header], [Space], and [TextArea]. Fields marked [HideInInspector] are skipped.",
                () => BulkAdd(BulkAddMode.FromScriptAttributes, "Smart Attribute Import"),
                hoverBorderColor: DesignerPalette.ToolAmber,
                enabled: importsEnabled, disabledReason: allBoundReason
            ));

            // Sync Missing — visible in EVERY sync mode. Under AutoAppend it's normally a no-op, but it is
            // the one rescue for a field the ledger records as "deliberately removed" (whether the user
            // actually removed it, or a past save swallowed it) — hiding it left such fields unreachable.
            genContent.Add(CreateToolRow(
                SasquatchIcons.Ids.RefreshCw,
                "Sync Missing",
                "Find and add any serializable fields not currently in the layout — including fields auto-sync " +
                "treats as deliberately removed. Useful when you update your C# script.",
                () => BulkAdd(BulkAddMode.RemainingOnly, "Sync Missing"),
                enabled: hasUnbound, disabledReason: "No unbound fields to add."
            ));

            // Group by [Header]
            genContent.Add(CreateToolRow(
                SasquatchIcons.Ids.Group,
                "Group by [Header]",
                "Add all fields, auto-creating Foldouts whenever a [Header] attribute is encountered on a field.",
                () => BulkAdd(BulkAddMode.ByHeader, "Group by [Header]"),
                enabled: importsEnabled, disabledReason: allBoundReason
            ));

            // Card Per Field
            genContent.Add(CreateToolRow(
                SasquatchIcons.Ids.GalleryVertical,
                "Card Per Field",
                "Add all fields, placing every field in its own individual Card container.",
                () => BulkAdd(BulkAddMode.EachInCard, "Card Per Field"),
                enabled: importsEnabled, disabledReason: allBoundReason
            ));

            // Flat Import
            genContent.Add(CreateToolRow(
                SasquatchIcons.Ids.List,
                "Flat Import",
                "Add all fields as a flat sequence of nodes at the root of the layout.",
                () => BulkAdd(BulkAddMode.Flat, "Flat Import"),
                enabled: importsEnabled, disabledReason: allBoundReason
            ));

            // Import C# Properties — deliberately separate from the field importers above (Smart/Flat
            // Import handle serialized FIELDS only). Adds a live, polled row for every readable C# property.
            bool hasProps = PropertyInvoker.GetReadableProperties(type).Any();
            genContent.Add(CreateToolRow(
                SasquatchIcons.Ids.Crosshair,
                "Import C# Properties",
                "Add a live, polled row for every readable C# property (computed getters, derived state). Separate from the field importers — properties are never part of Smart/Flat Import.",
                ImportProperties,
                enabled: hasProps, disabledReason: "This type has no readable C# properties."
            ));

            // ---- PRESETS (collapsible) ----
            var presetContent = CreateToolSection("PRESETS", _toolsPresetsExpanded,
                v => _toolsPresetsExpanded = v, marginTop: 14);

            // Apply Presets to Layout — upgrade every field still on the plain default widget to its preset widget +
            // config. Customized fields (already on a non-default widget) are left untouched. Explicit action, so it
            // ignores the "Use Layout Presets" toggle.
            presetContent.Add(CreateToolRow(
                SasquatchIcons.Ids.Sparkles,
                "Apply Presets to Layout",
                "Upgrade every field still on the plain default widget to its Layout Preset widget + configuration. " +
                "Fields you've already customized are left untouched.",
                ApplyPresetsToLayout,
                hoverBorderColor: DesignerPalette.ToolBlue,
                enabled: layoutNonEmpty, disabledReason: "Layout is empty — nothing to upgrade."
            ));

            // Override with Presets — force EVERY field (even customized ones) to its preset widget + config.
            // Destructive, so it's orange and confirms first. Explicit action; ignores the "Use Layout Presets" toggle.
            presetContent.Add(CreateToolRow(
                SasquatchIcons.Ids.Zap,
                "Override with Presets",
                "Reset EVERY field's widget + configuration to its Layout Preset default — INCLUDING fields you've " +
                "already customized. Labels, headers, conditions, animations and position are kept. Asks for confirmation.",
                OverridePresetsToLayout,
                hoverBorderColor: DesignerPalette.ToolOrange,
                iconColor: DesignerPalette.ToolOrangeIcon,
                enabled: layoutNonEmpty, disabledReason: "Layout is empty — nothing to override."
            ));

            // ---- CLEANUP / MAINTENANCE (collapsible) ----
            // (Expand/Collapse/Sort/Wrap/Flatten/Prune now live in the canvas "Layout ▾" dropdown.)
            var cleanupContent = CreateToolSection("CLEANUP / MAINTENANCE", _toolsCleanupExpanded,
                v => _toolsCleanupExpanded = v, marginTop: 14);

            // Remove Orphaned Bindings — visible in EVERY sync mode (AutoAppend's auto-prune deliberately
            // skips removals during compile/import windows, so a manual sweep still has a job).
            {
                var careful = DesignerPalette.ToolCareful; // "this removes things" hover hint
                bool hasOrphans = root != null && CountOrphanedBindings(root, "", type) > 0;
                cleanupContent.Add(CreateToolRow(
                    SasquatchIcons.Ids.Unlink,
                    "Remove Orphaned Bindings",
                    "Remove fields whose property no longer exists on the script (after a rename or delete). The inverse of Sync Missing.",
                    RemoveOrphanedBindings,
                    hoverBorderColor: careful,
                    enabled: hasOrphans, disabledReason: "No orphaned bindings — every field still resolves."
                ));
            }

            // Clear Layout (Destructive)
            cleanupContent.Add(CreateToolRow(
                SasquatchIcons.Ids.Eraser,
                "Clear Layout",
                "Remove all fields and containers. Reset to a blank slate.",
                ClearLayout,
                hoverBorderColor: DesignerPalette.ToolDanger,
                iconColor: DesignerPalette.ToolDangerIcon,
                enabled: layoutNonEmpty, disabledReason: "Layout is already empty."
            ));
        }

        // One-line read-out for the Apply to Subclasses toggle. The flag is inert until a SUBCLASS looks up a
        // layout, so with no subclasses the toggle looks like it does nothing — this states what it will do, including
        // the two rules that aren't otherwise visible: future subclasses are covered, and a subclass with its own
        // layout blocks inheritance from reaching further down.
        private static string DescribeSubclassInheritance(Type type, bool applyToSubclasses)
        {
            int inheriting = CountInheritingSubclasses(type, out int withOwnLayout);

            if (inheriting == 0 && withOwnLayout == 0)
                return applyToSubclasses
                    ? "No subclasses yet — any you add later will inherit this layout automatically."
                    : $"No subclasses of {type.Name} yet. Turn on to cover any you add later.";

            string blocked = withOwnLayout == 0 ? "" :
                $" {withOwnLayout} {(withOwnLayout == 1 ? "has its own layout" : "have their own layouts")} and {(withOwnLayout == 1 ? "is" : "are")} unaffected.";

            if (!applyToSubclasses)
                return inheriting == 0
                    ? $"Every subclass of {type.Name} already has its own layout."
                    : $"Off — {inheriting} {(inheriting == 1 ? "subclass uses" : "subclasses use")} the default inspector. Turn on to give {(inheriting == 1 ? "it" : "them")} this layout.{blocked}";

            return inheriting == 0
                ? $"Every subclass of {type.Name} already has its own layout — new ones will inherit this."
                : $"{inheriting} {(inheriting == 1 ? "subclass inherits" : "subclasses inherit")} this layout, plus any you add later.{blocked}";
        }

        // Mirrors LayoutRegistry.TryResolveInherited's BARRIER rule so the count can't lie: a derived type inherits
        // from `type` only when `type` is the NEAREST ancestor holding a layout. An intervening subclass with its
        // own layout stops the walk, and its descendants are credited to it, not to us. Abstract/open-generic
        // types are skipped — they are never inspected directly, so counting them would inflate the number.
        // Cheap enough to run per toggle-flip: TypeCache is prebuilt by Unity and HasOwnLayout is a dictionary hit.
        private static int CountInheritingSubclasses(Type type, out int withOwnLayout)
        {
            withOwnLayout = 0;
            int inheriting = 0;

            foreach (var derived in TypeCache.GetTypesDerivedFrom(type))
            {
                if (derived.IsAbstract || derived.IsGenericTypeDefinition) continue;

                if (LayoutRegistry.HasOwnLayout(derived)) { withOwnLayout++; continue; }

                var owner = derived.BaseType;
                while (owner != null && owner != type && !LayoutRegistry.HasOwnLayout(owner))
                    owner = owner.BaseType;

                if (owner == type) inheriting++;
            }
            return inheriting;
        }

        // The canvas "Layout ▾" dropdown: reorganization actions that aren't really "tools". Each item greys
        // out (AddDisabledItem) when it would be a no-op, reusing the same availability predicates as the
        // Tools tab. Shown at the cursor via ShowAsContext, matching the Hierarchy gear menu's idiom.
        private void ShowLayoutActionsMenu()
        {
            var menu = new GenericMenu();
            var root = _clonedLayoutAsset != null ? _clonedLayoutAsset.Root as ContainerNode : null;

            bool hasGroups = root != null && AnyExpandableGroup(root);
            AddLayoutMenuItem(menu, "Expand All Groups", hasGroups, () => SetAllFoldoutsExpanded(true));
            AddLayoutMenuItem(menu, "Collapse All Groups", hasGroups, () => SetAllFoldoutsExpanded(false));

            // Sort needs ≥2 sortable root items (a pinned Script Header doesn't count toward the sort).
            int sortable = 0;
            if (root != null && root.Children != null)
            {
                sortable = root.Children.Count;
                if (root.Children.Count > 0 && root.Children[0] is ScriptHeaderNode) sortable--;
            }
            AddLayoutMenuItem(menu, "Sort Root Alphabetically", sortable >= 2, SortRootAlphabetically);

            // Wrap is useful unless every root child is already sitting in its own Card.
            bool wrapNeeded = root != null && root.Children != null && root.Children.Count > 0
                && root.Children.Any(c => !(c is ContainerNode cn && cn.Type == ContainerType.Card));
            AddLayoutMenuItem(menu, "Wrap All in Cards", wrapNeeded, AddCardToAll);

            menu.AddSeparator("");

            bool hasNested = root != null && CountNestedContainers(root) > 0;
            AddLayoutMenuItem(menu, "Flatten / Ungroup All", hasNested, FlattenLayout);

            bool prunable = root != null && AnyPrunable(root);
            AddLayoutMenuItem(menu, "Prune Empty Groups", prunable, PruneEmptyGroups);

            menu.ShowAsContext();
        }

        // Enabled items run their action; disabled items render greyed so the menu says "nothing to do" too.
        private static void AddLayoutMenuItem(GenericMenu menu, string label, bool enabled, GenericMenu.MenuFunction action)
        {
            var content = new GUIContent(label);
            if (enabled) menu.AddItem(content, false, action);
            else menu.AddDisabledItem(content);
        }

        // "Export Editor" toolbar button handler. Exports the CURRENT on-screen layout (the working clone) as a
        // self-contained [CustomEditor] script. Guarded so an empty layout / preset / showcase mode shows a hint
        // instead of writing a useless file.
        private void ExportStandaloneEditor()
        {
            var type = ResolveTargetType();
            var root = _clonedLayoutAsset != null ? _clonedLayoutAsset.Root as ContainerNode : null;
            bool hasLayout = type != null && !_presetMode && string.IsNullOrEmpty(_showcaseOverrideKey)
                && root != null && root.Children != null && root.Children.Count > 0;
            if (!hasLayout)
            {
                EditorUtility.DisplayDialog("Export Standalone Editor",
                    "Design a layout (add at least one element) for this type before exporting.", "OK");
                return;
            }
            Export.StandaloneEditorExporter.ExportWithDialog(type, _clonedLayoutAsset);
        }

        // Builds a collapsible section: a clickable header row (▾/▸ arrow + title) plus its content
        // container, adds both to the left panel (shared by the Tools and Widgets tabs), and returns the
        // content for the caller to fill. `onToggle` persists the new expanded state; the section starts
        // in the `expanded` state.
        private VisualElement CreateToolSection(string title, bool expanded, System.Action<bool> onToggle, float marginTop)
        {
            var header = new VisualElement();
            header.style.flexDirection = FlexDirection.Row;
            header.style.alignItems = Align.Center;
            header.style.marginTop = marginTop;
            header.style.marginBottom = 8;
            header.style.marginLeft = 2;
            header.style.paddingTop = 2;
            header.style.paddingBottom = 2;

            var inactiveCol = DesignerPalette.TextFaint;
            var arrowInactiveCol = DesignerPalette.SectionArrow;
            var hoverCol = DesignerPalette.IconIdle;

            var arrow = SasquatchIcons.Create(SasquatchIcons.Ids.ChevronRight, 10, arrowInactiveCol);
            arrow.style.width = 14;
            arrow.style.marginRight = 2;
            header.Add(arrow);
            EditorSpringFX.SpringCaret(arrow, expanded, animate: false); // single glyph, spun on toggle

            var label = new Label(title);
            label.style.fontSize = 10;
            label.style.unityFontStyleAndWeight = FontStyle.Bold;
            label.style.color = inactiveCol;
            header.Add(label);

            var content = new VisualElement();
            content.style.display = expanded ? DisplayStyle.Flex : DisplayStyle.None;

            header.RegisterCallback<MouseEnterEvent>(_ =>
            {
                arrow.Tint = hoverCol;
                label.style.color = hoverCol;
            });
            header.RegisterCallback<MouseLeaveEvent>(_ =>
            {
                arrow.Tint = arrowInactiveCol;
                label.style.color = inactiveCol;
            });
            // Tracked locally (not read back from style.display) because the spring fold keeps
            // display:Flex until a collapse animation settles.
            bool sectionExpanded = expanded;
            header.RegisterCallback<MouseDownEvent>(evt =>
            {
                if (evt.button != 0) return;
                sectionExpanded = !sectionExpanded;
                EditorSpringFX.Fold(content, sectionExpanded);
                EditorSpringFX.SpringCaret(arrow, sectionExpanded);
                onToggle?.Invoke(sectionExpanded);
                evt.StopPropagation();
            });

            _tokenBankContainer.Add(header);
            _tokenBankContainer.Add(content);
            return content;
        }

        private enum ToastKind { Success, Info, Warning }

        // Shows a small animated toast in the top-right of the window summarizing a Tools action's
        // result (or why it couldn't run). Scoped to the Tools section by convention — only the tool
        // methods call this, so it never narrates drag/drop or other edits.
        private void ShowToolToast(string message, ToastKind kind)
        {
            if (_toastHost == null || string.IsNullOrEmpty(message)) return;

            Color accent;
            string icon;
            switch (kind)
            {
                case ToastKind.Success: accent = DesignerPalette.ToastSuccess; icon = SasquatchIcons.Ids.Check; break;
                case ToastKind.Warning: accent = DesignerPalette.ToastWarning; icon = SasquatchIcons.Ids.CircleAlert; break;
                default:                accent = DesignerPalette.ToastInfo; icon = SasquatchIcons.Ids.Info; break;
            }

            var toast = new VisualElement { pickingMode = PickingMode.Ignore };
            toast.style.flexDirection = FlexDirection.Row;
            toast.style.alignItems = Align.Center;
            toast.style.maxWidth = 320;
            toast.style.marginBottom = 6;
            toast.style.paddingTop = 8;
            toast.style.paddingBottom = 8;
            toast.style.paddingLeft = 10;
            toast.style.paddingRight = 12;
            toast.style.backgroundColor = DesignerPalette.ToastBg;
            toast.style.borderTopLeftRadius = 5;
            toast.style.borderTopRightRadius = 5;
            toast.style.borderBottomLeftRadius = 5;
            toast.style.borderBottomRightRadius = 5;
            toast.style.borderLeftWidth = 3;
            toast.style.borderTopWidth = 1;
            toast.style.borderRightWidth = 1;
            toast.style.borderBottomWidth = 1;
            toast.style.borderLeftColor = accent;
            var edge = DesignerPalette.BorderMid;
            toast.style.borderTopColor = edge;
            toast.style.borderRightColor = edge;
            toast.style.borderBottomColor = edge;

            var iconEl = SasquatchIcons.Create(icon, 14, accent);
            iconEl.style.width = 16;
            iconEl.style.marginRight = 8;
            toast.Add(iconEl);

            var msgLbl = new Label(message) { pickingMode = PickingMode.Ignore };
            msgLbl.style.color = DesignerPalette.TextBright;
            msgLbl.style.fontSize = 11;
            msgLbl.style.whiteSpace = WhiteSpace.Normal;
            msgLbl.style.flexShrink = 1;
            toast.Add(msgLbl);

            // Start faded + nudged right, then transition into the resting state next frame.
            toast.style.opacity = 0f;
            toast.style.translate = new Translate(new Length(24f, LengthUnit.Pixel), 0f);
            toast.style.transitionProperty = new List<StylePropertyName> { "opacity", "translate" };
            toast.style.transitionDuration = new List<TimeValue>
            {
                new TimeValue(200, TimeUnit.Millisecond),
                new TimeValue(200, TimeUnit.Millisecond)
            };
            toast.style.transitionTimingFunction = new List<EasingFunction>
            {
                new EasingFunction(EasingMode.EaseOutCubic),
                new EasingFunction(EasingMode.EaseOutCubic)
            };

            _toastHost.Insert(0, toast); // newest on top
            _toastHost.BringToFront();

            toast.schedule.Execute(() =>
            {
                toast.style.opacity = 1f;
                toast.style.translate = new Translate(new Length(0f, LengthUnit.Pixel), 0f);
            }).ExecuteLater(16);

            // Auto-dismiss: fade + slide out, then drop it from the tree.
            toast.schedule.Execute(() =>
            {
                toast.style.opacity = 0f;
                toast.style.translate = new Translate(new Length(24f, LengthUnit.Pixel), 0f);
                toast.schedule.Execute(() => toast.RemoveFromHierarchy()).ExecuteLater(240);
            }).ExecuteLater(2800);
        }

        // A single Tools-tab action card: icon + bold title on one row. The old two-line description now
        // lives in the tooltip so the panel scans at a glance. When `enabled` is false the card is dimmed,
        // unclickable, and its tooltip explains why (no hover highlight, no press animation on a dead card).
        private VisualElement CreateToolRow(string icon, string title, string description, System.Action onClick,
            Color? hoverBorderColor = null, Color? iconColor = null, bool enabled = true, string disabledReason = null)
        {
            var btn = new Button();
            btn.style.flexDirection = FlexDirection.Row;
            btn.style.alignItems = Align.Center;
            btn.style.paddingTop = 6;
            btn.style.paddingBottom = 6;
            btn.style.paddingLeft = 8;
            btn.style.paddingRight = 8;
            btn.style.marginBottom = 6;
            btn.style.borderTopWidth = 1;
            btn.style.borderBottomWidth = 1;
            btn.style.borderLeftWidth = 1;
            btn.style.borderRightWidth = 1;
            btn.style.borderTopLeftRadius = 4;
            btn.style.borderTopRightRadius = 4;
            btn.style.borderBottomLeftRadius = 4;
            btn.style.borderBottomRightRadius = 4;

            // The full description becomes the hover tooltip; a disabled card appends the "why".
            btn.tooltip = enabled || string.IsNullOrEmpty(disabledReason)
                ? description
                : description + "\n\n(" + disabledReason + ")";

            var normalBg = DesignerPalette.ToolCardBg;
            var hoverBg = DesignerPalette.ToolCardHoverBg;
            var borderCol = DesignerPalette.ToolCardBorder;

            btn.style.backgroundColor = normalBg;
            btn.style.borderTopColor = borderCol;
            btn.style.borderBottomColor = borderCol;
            btn.style.borderLeftColor = borderCol;
            btn.style.borderRightColor = borderCol;

            // The ~5% right inset must apply to EVERY row (it's normally set by AddHoverHighlight, which only runs
            // for enabled rows) — otherwise a disabled row stretches to full width and renders wider than its
            // siblings (e.g. "Import C# Properties" when the type has no readable properties).
            btn.style.marginRight = Length.Percent(5);

            if (enabled)
            {
                AddHoverHighlight(btn, normalBg, hoverBg);

                // Custom border color highlight on hover if specified (e.g. for recommended or clear buttons)
                if (hoverBorderColor.HasValue)
                {
                    btn.RegisterCallback<MouseOverEvent>(evt =>
                    {
                        btn.style.borderTopColor = hoverBorderColor.Value;
                        btn.style.borderBottomColor = hoverBorderColor.Value;
                        btn.style.borderLeftColor = hoverBorderColor.Value;
                        btn.style.borderRightColor = hoverBorderColor.Value;
                    });
                    btn.RegisterCallback<MouseOutEvent>(evt =>
                    {
                        btn.style.borderTopColor = borderCol;
                        btn.style.borderBottomColor = borderCol;
                        btn.style.borderLeftColor = borderCol;
                        btn.style.borderRightColor = borderCol;
                    });
                }

                // Punchy press feedback: dip in then spring back. Capture phase so the inner label/icon
                // can't swallow the press (mirrors AnimationBinder's click hook).
                btn.RegisterCallback<PointerDownEvent>(_ => EditorSpringFX.PressBounce(btn), TrickleDown.TrickleDown);

                btn.clicked += onClick;
            }
            else
            {
                // Greyed but still LIVE: a no-op tool should read as inert yet stay clickable/hoverable
                // (Unity's SetEnabled(false) would also kill the hover + the "why" tooltip). So mute the row,
                // keep the reason tooltip, lift it slightly on hover so it still feels interactive, and shake
                // on click as a wordless "nothing to do here" — we never run the real action (it'd no-op anyway).
                const float mutedOpacity = 0.4f;
                btn.style.opacity = mutedOpacity;
                btn.AddToClassList("sasq-clickable");
                btn.RegisterCallback<MouseOverEvent>(_ => btn.style.opacity = 0.6f);
                btn.RegisterCallback<MouseOutEvent>(_ => btn.style.opacity = mutedOpacity);
                btn.clicked += () => EditorSpringFX.Shake(btn, 0.3f);
            }

            // `icon` is a SasquatchIcons id. The 24px-wide slot keeps the old emoji-era alignment.
            var iconEl = SasquatchIcons.Create(icon, 16, iconColor);
            iconEl.style.width = 24;
            iconEl.style.marginRight = 8;
            btn.Add(iconEl);

            var titleLbl = new Label(title);
            titleLbl.style.fontSize = 11;
            titleLbl.style.unityFontStyleAndWeight = FontStyle.Bold;
            titleLbl.style.color = DesignerPalette.TextBright;
            titleLbl.style.flexGrow = 1;
            btn.Add(titleLbl);

            return btn;
        }

        private void SetAllFoldoutsExpanded(bool expanded)
        {
            string verb = expanded ? "Expand" : "Collapse";
            if (_clonedLayoutAsset == null || _clonedLayoutAsset.Root == null)
            {
                ShowToolToast($"{verb} All Groups: no layout loaded.", ToastKind.Warning);
                return;
            }

            Undo.RecordObject(_clonedLayoutAsset, expanded ? "Expand All Foldouts" : "Collapse All Foldouts");
            bool changed = SetAllFoldoutsExpandedRecursive(_clonedLayoutAsset.Root, expanded);
            if (changed)
            {
                OnModification();
                RefreshAll();
                ShowToolToast($"{verb}ed all groups.", ToastKind.Success);
            }
            else
            {
                ShowToolToast($"No groups to {verb.ToLowerInvariant()} — nothing changed.", ToastKind.Info);
            }
        }

        private bool SetAllFoldoutsExpandedRecursive(LayoutNode node, bool expanded)
        {
            if (node == null) return false;
            bool changed = false;

            if (node is ContainerNode containerNode)
            {
                // Foldouts are always collapsible; Rows/Columns/Grid/Card are collapsible only when
                // their Expandable option is on. Both seed their collapse state from DefaultToOpen.
                bool isExpandableGroup = containerNode.Type == ContainerType.Foldout
                    || (containerNode.Expandable
                        && (containerNode.Type == ContainerType.Rows
                         || containerNode.Type == ContainerType.Columns
                         || containerNode.Type == ContainerType.Grid
                         || containerNode.Type == ContainerType.Card));
                if (isExpandableGroup)
                {
                    if (containerNode.DefaultToOpen != expanded)
                    {
                        containerNode.DefaultToOpen = expanded;
                        changed = true;
                    }
                }

                if (containerNode.Children != null)
                {
                    foreach (var child in containerNode.Children)
                    {
                        if (SetAllFoldoutsExpandedRecursive(child, expanded))
                        {
                            changed = true;
                        }
                    }
                }
            }
            else if (node is CollectionNode collectionNode)
            {
                if (collectionNode.ItemLayout != null)
                {
                    if (SetAllFoldoutsExpandedRecursive(collectionNode.ItemLayout, expanded))
                    {
                        changed = true;
                    }
                }
            }

            return changed;
        }

        // True if the layout contains at least one group Expand/Collapse All would actually toggle
        // (a Foldout, or an Expandable Rows/Columns/Grid/Card). Mirrors the isExpandableGroup test
        // in SetAllFoldoutsExpandedRecursive so the "Layout" menu can grey those items out.
        private bool AnyExpandableGroup(LayoutNode node)
        {
            if (node is ContainerNode containerNode)
            {
                bool isExpandableGroup = containerNode.Type == ContainerType.Foldout
                    || (containerNode.Expandable
                        && (containerNode.Type == ContainerType.Rows
                         || containerNode.Type == ContainerType.Columns
                         || containerNode.Type == ContainerType.Grid
                         || containerNode.Type == ContainerType.Card));
                if (isExpandableGroup) return true;
                if (containerNode.Children != null)
                    foreach (var child in containerNode.Children)
                        if (AnyExpandableGroup(child)) return true;
            }
            else if (node is CollectionNode collectionNode && collectionNode.ItemLayout != null)
            {
                return AnyExpandableGroup(collectionNode.ItemLayout);
            }
            return false;
        }

        private void SortRootAlphabetically()
        {
            if (_clonedLayoutAsset == null || !(_clonedLayoutAsset.Root is ContainerNode root) ||
                root.Children == null || root.Children.Count <= 1)
            {
                ShowToolToast("Sort Root: nothing to sort (fewer than 2 items).", ToastKind.Info);
                return;
            }

            // Pins the ScriptHeaderNode to the top during sorting if it's the first element.
            int startIndex = 0;
            if (root.Children[0] is ScriptHeaderNode)
            {
                startIndex = 1;
            }

            if (root.Children.Count - startIndex <= 1)
            {
                ShowToolToast("Sort Root: nothing to sort (fewer than 2 items).", ToastKind.Info);
                return;
            }

            Undo.RecordObject(_clonedLayoutAsset, "Sort Root Alphabetically");
            
            var listToSort = new List<LayoutNode>();
            for (int i = startIndex; i < root.Children.Count; i++)
            {
                listToSort.Add(root.Children[i]);
            }
            
            listToSort.Sort((a, b) => string.Compare(GetNodeSortName(a), GetNodeSortName(b), StringComparison.OrdinalIgnoreCase));

            var resultList = new List<LayoutNode>(root.Children.Count);
            for (int i = 0; i < startIndex; i++)
            {
                resultList.Add(root.Children[i]);
            }
            resultList.AddRange(listToSort);

            root.Children = resultList;

            OnModification();
            RefreshAll();
            ShowToolToast($"Sorted {listToSort.Count} top-level items alphabetically.", ToastKind.Success);
        }

        private string GetNodeSortName(LayoutNode node)
        {
            if (node == null) return "";
            if (node is ContainerNode cn)
            {
                if (!string.IsNullOrEmpty(cn.Title)) return cn.Title;
                if (!string.IsNullOrEmpty(cn.PropertyPath)) return cn.PropertyPath;
                if (!string.IsNullOrEmpty(cn.StyleToken)) return cn.StyleToken;
                return "Container";
            }
            if (node is BindingNode bn)
            {
                if (!string.IsNullOrEmpty(bn.EffectiveLabelOverride)) return bn.EffectiveLabelOverride;
                if (!string.IsNullOrEmpty(bn.PropertyPath)) return bn.PropertyPath;
                return "Binding";
            }
            if (node is CollectionNode colNode)
            {
                if (!string.IsNullOrEmpty(colNode.PropertyPath)) return colNode.PropertyPath;
                return "Collection";
            }
            if (node is ButtonNode btn)
            {
                string btnName = !string.IsNullOrEmpty(btn.ButtonText) ? btn.ButtonText : btn.MethodName;
                if (!string.IsNullOrEmpty(btnName)) return btnName;
                return "Button";
            }
            if (node is HelpBoxNode hb)
            {
                if (!string.IsNullOrEmpty(hb.Message)) return hb.Message;
                return "Info/Warning";
            }
            if (node is ScriptHeaderNode)
            {
                return "Script Header";
            }
            if (node is SpaceNode)
            {
                return "Space";
            }
            if (node is LabeledDividerNode ldn)
            {
                return string.IsNullOrEmpty(ldn.Title) ? "Divider" : ldn.Title;
            }
            if (node is ImageBannerNode)
            {
                return "Image";
            }
            if (node is TextBlockNode tb)
            {
                return string.IsNullOrEmpty(tb.Text) ? "Text Block" : tb.Text;
            }
            if (node is EmbeddedEditorNode)
            {
                return "Embedded Editor";
            }
#if SASQ_CUSTOM_WIDGET
            if (node is CustomWidgetNode)
            {
                return "Custom Widget";
            }
#endif
            return "";
        }

        // ---------------------------------------------------------------------------------------
        // Cleanup / Maintenance tools
        // ---------------------------------------------------------------------------------------

        // Removes BindingNodes/CollectionNodes whose property path no longer resolves on the target
        // type (e.g. the field was renamed or deleted in the C# script). The inverse of Sync Missing.
        private void RemoveOrphanedBindings()
        {
            var type = ResolveTargetType();
            if (type == null || _clonedLayoutAsset == null || _clonedLayoutAsset.Root == null)
            {
                ShowToolToast("Remove Orphaned: select an object or layout with a valid target type first.", ToastKind.Warning);
                return;
            }

            // Pre-check so we never record an empty undo step when nothing is orphaned.
            int orphanCount = CountOrphanedBindings(_clonedLayoutAsset.Root, "", type);
            if (orphanCount == 0)
            {
                ShowToolToast($"Remove Orphaned: no orphans — every field still resolves on {type.Name}.", ToastKind.Info);
                return;
            }

            Undo.RecordObject(_clonedLayoutAsset, "Remove Orphaned Bindings");
            var orphans = new List<LayoutNode>();
            CollectOrphanedBindings(_clonedLayoutAsset.Root, "", type, orphans);
            // Through the chokepoint, so a removed field takes its attribute-owned [Space] with it and a
            // removed tab re-clamps its Tabs container — this path used to do neither.
            int removed = RemoveNodesGuarded(orphans, RemovalKind.Delete).Count;

            SetPrimarySelection(null); // a removed node may have been selected
            OnModification();
            RefreshAll();
            ShowToolToast($"Removed {removed} orphaned binding{(removed == 1 ? "" : "s")} that no longer resolve on {type.Name}.", ToastKind.Success);
        }

        // A binding/collection node is orphaned when its resolved path fails the sync engine's single
        // liveness rule (serializable path set + reflection fallback, gated on Unity actually
        // SERIALIZING the field) — so a field flipped to non-serialized (public → private,
        // [SerializeField] removed) is orphaned too, exactly as auto-sync treats it.
        private bool IsOrphanBinding(LayoutNode node, string basePath, System.Type type)
        {
            string path = null;
            if (node is BindingNode bn) path = bn.PropertyPath;
            else if (node is CollectionNode col) path = col.PropertyPath;
            if (string.IsNullOrEmpty(path)) return false;

            string resolved = string.IsNullOrEmpty(basePath) ? path : $"{basePath}.{path}";
            return !UnboundFieldSync.IsLivePath(type, resolved);
        }

        private int CountOrphanedBindings(LayoutNode node, string basePath, System.Type type)
        {
            int count = 0;
            if (node is ContainerNode container)
            {
                string nextBase = basePath;
                if (!string.IsNullOrEmpty(container.PropertyPath))
                    nextBase = string.IsNullOrEmpty(basePath) ? container.PropertyPath : $"{basePath}.{container.PropertyPath}";

                if (container.Children != null)
                {
                    foreach (var child in container.Children)
                    {
                        if (IsOrphanBinding(child, nextBase, type)) count++;
                        else count += CountOrphanedBindings(child, nextBase, type);
                    }
                }
            }
            else if (node is CollectionNode col && col.ItemLayout != null)
            {
                string resolved = string.IsNullOrEmpty(basePath) ? col.PropertyPath : $"{basePath}.{col.PropertyPath}";
                if (!IsOrphanBinding(col.ItemLayout, resolved, type))
                    count += CountOrphanedBindings(col.ItemLayout, resolved, type);
            }
            return count;
        }

        // Collect-then-remove (rather than rewriting Children in place) so the removal itself goes through
        // RemoveNodesGuarded, which is where the [Space] cascade and the Tabs re-clamp live. Traversal
        // mirrors CountOrphanedBindings exactly — an orphan's own subtree is never descended into, since it
        // leaves with its parent — so the pre-check count and the actual removal can no longer disagree.
        private void CollectOrphanedBindings(LayoutNode node, string basePath, System.Type type, List<LayoutNode> into)
        {
            if (node is ContainerNode container)
            {
                string nextBase = basePath;
                if (!string.IsNullOrEmpty(container.PropertyPath))
                    nextBase = string.IsNullOrEmpty(basePath) ? container.PropertyPath : $"{basePath}.{container.PropertyPath}";

                if (container.Children != null)
                {
                    foreach (var child in container.Children)
                    {
                        if (IsOrphanBinding(child, nextBase, type)) into.Add(child);
                        else CollectOrphanedBindings(child, nextBase, type, into);
                    }
                }
            }
            else if (node is CollectionNode col && col.ItemLayout != null)
            {
                string resolved = string.IsNullOrEmpty(basePath) ? col.PropertyPath : $"{basePath}.{col.PropertyPath}";
                if (!IsOrphanBinding(col.ItemLayout, resolved, type))
                    CollectOrphanedBindings(col.ItemLayout, resolved, type, into);
            }
        }

        // Pulls every nested field up to the root and drops the now-empty containers. Bindings inside
        // path-rebased containers (struct grouping) get their paths re-absolutized so they keep resolving.
        private void FlattenLayout()
        {
            if (_clonedLayoutAsset == null || !(_clonedLayoutAsset.Root is ContainerNode root) ||
                root.Children == null || root.Children.Count == 0)
            {
                ShowToolToast("Flatten: nothing to flatten (the layout is empty).", ToastKind.Info);
                return;
            }

            // Pre-check: if there are no nested containers, the layout is already flat.
            if (CountNestedContainers(root) == 0)
            {
                ShowToolToast("Flatten: layout is already flat — no groups to ungroup.", ToastKind.Info);
                return;
            }

            Undo.RecordObject(_clonedLayoutAsset, "Flatten Layout");

            var flat = new List<LayoutNode>();
            int containersRemoved = 0;
            LayoutStructureUtility.FlattenCollect(root, "", flat, ref containersRemoved);

            // Keep a Script Header pinned at the top, mirroring Sort Root.
            var header = flat.FirstOrDefault(n => n is ScriptHeaderNode);
            if (header != null) { flat.Remove(header); flat.Insert(0, header); }
            root.Children = flat;

            SetPrimarySelection(null); // a flattened container may have been selected
            OnModification();
            RefreshAll();
            ShowToolToast($"Flattened {containersRemoved} container{(containersRemoved == 1 ? "" : "s")} — moved every field to the root.", ToastKind.Success);
        }

        // Counts containers nested anywhere in the root tree (not descending into collection templates).
        private int CountNestedContainers(ContainerNode container)
        {
            int n = 0;
            if (container.Children != null)
                foreach (var c in container.Children)
                    if (c is ContainerNode cc) { n++; n += CountNestedContainers(cc); }
            return n;
        }

        // Flatten's collect/rebase mechanics live in LayoutStructureUtility (shared with the
        // orphaned-header cleanup's single-container dissolve).

        // Removes empty containers (Foldout/Card/etc.) left behind after deletions, cascading outward so
        // a container left holding only empty containers is removed too.
        private void PruneEmptyGroups()
        {
            if (_clonedLayoutAsset == null || _clonedLayoutAsset.Root == null)
            {
                ShowToolToast("Prune Empty Groups: no layout loaded.", ToastKind.Info);
                return;
            }

            if (!AnyPrunable(_clonedLayoutAsset.Root))
            {
                ShowToolToast("Prune Empty Groups: no empty containers to remove.", ToastKind.Info);
                return;
            }

            Undo.RecordObject(_clonedLayoutAsset, "Prune Empty Groups");
            var prunable = new List<LayoutNode>();
            CollectPrunableContainers(_clonedLayoutAsset.Root, prunable);
            // Through the chokepoint, so this stops being the one removal path that never re-clamps a Tabs
            // container's active index.
            int removed = RemoveNodesGuarded(prunable, RemovalKind.Delete).Count;

            SetPrimarySelection(null); // a pruned container may have been selected
            OnModification();
            RefreshAll();
            ShowToolToast($"Pruned {removed} empty container{(removed == 1 ? "" : "s")}.", ToastKind.Success);
        }

        // Containers a prune must never touch, no matter how empty they look:
        //   * a Frame is the ONE container that renders real content with zero children — its shape, fill,
        //     overlay and title are authored decoration, so an empty Frame is not an empty group;
        //   * a split Frame's two panes are structural (positional identity — exactly two, always). Panes are
        //     plain Rows containers, so the Frame check above does not cover them, and Pane B is empty by
        //     definition the instant FrameShapeMigration.ToSplit runs.
        private bool IsPruneProtected(ContainerNode c)
        {
            if (c == null) return false;
            if (c.Type == ContainerType.Frame) return true;
            return SplitFramePaneOwner(c) != null;
        }

        // True if removing empties would leave this container with no children (cascades through nesting).
        // Protection propagates outward — a container holding a protected child is not itself prunable — and
        // lives HERE rather than at the removal so WouldPrune / AnyPrunable / PruneEmptyGroups stay in
        // lockstep; a divergence enables the menu item and then reports "Pruned 0".
        private bool WouldPrune(ContainerNode c)
        {
            if (IsPruneProtected(c)) return false;
            if (c.Children == null || c.Children.Count == 0) return true;
            foreach (var child in c.Children)
            {
                if (child is ContainerNode cc) { if (!WouldPrune(cc)) return false; }
                else return false; // a non-container child keeps it alive
            }
            return true;
        }

        private bool AnyPrunable(LayoutNode node)
        {
            if (node is ContainerNode container && container.Children != null)
            {
                foreach (var child in container.Children)
                {
                    if (child is ContainerNode cc && WouldPrune(cc)) return true;
                    if (AnyPrunable(child)) return true;
                }
            }
            else if (node is CollectionNode col && col.ItemLayout != null)
            {
                if (AnyPrunable(col.ItemLayout)) return true;
            }
            return false;
        }

        // Bottom-up collect: a container's prunable descendants are listed BEFORE the container itself, so
        // handing the list to RemoveNodesGuarded detaches children ahead of their parents (a child of an
        // already-detached parent is unreachable from the root and would silently not count). WouldPrune
        // predicts the cascade rather than mutating to discover it, which is what keeps this identical to
        // the AnyPrunable pre-check. The root and a collection's item-layout root are never collected —
        // only their children.
        private void CollectPrunableContainers(LayoutNode node, List<LayoutNode> into)
        {
            if (node is ContainerNode container && container.Children != null)
            {
                foreach (var child in container.Children)
                {
                    CollectPrunableContainers(child, into);
                    if (child is ContainerNode cc && WouldPrune(cc)) into.Add(child);
                }
            }
            else if (node is CollectionNode col && col.ItemLayout != null)
            {
                CollectPrunableContainers(col.ItemLayout, into);
            }
        }

        private enum BulkAddMode { Flat, EachInCard, ByHeader, RemainingOnly, FromScriptAttributes }

        // Clears every node from the layout (after a confirm). Undoable via Ctrl+Z.
        private void ClearLayout()
        {
            if (_clonedLayoutAsset == null || !(_clonedLayoutAsset.Root is ContainerNode root) ||
                root.Children == null || root.Children.Count == 0)
            {
                ShowToolToast("Clear Layout: the layout is already empty.", ToastKind.Info);
                return;
            }

            if (!EditorUtility.DisplayDialog(
                    "Remove All Fields",
                    "Remove every field and container from this layout? You can undo this with Ctrl+Z.",
                    "Remove All", "Cancel"))
                return;

            int removed = root.Children.Count;
            Undo.RecordObject(_clonedLayoutAsset, "Remove All Fields");
            root.Children.Clear();
            SetPrimarySelection(null); // drop any now-dangling selection so the Properties panel resets
            OnModification();
            RefreshAll();
            ShowToolToast($"Cleared the layout — removed {removed} top-level node{(removed == 1 ? "" : "s")}.", ToastKind.Success);
        }

        // Top-level bindable fields for bulk-add (logic shared with the auto-sync engine). [HideInInspector]
        // fields are EXCLUDED: the developer explicitly asked Unity not to show them, so they shouldn't
        // auto-import as bindings. (Counting them was also a bug — Smart/Sync Import claimed a phantom
        // "added 1" and never greyed out, because their actual importers already skip hidden fields. Orphan
        // detection still uses the FULL field set, so any pre-existing binding to a hidden field stays valid.)
        private List<SasquatchReflectionUtility.ReflectedProperty> GetBulkAddProperties(System.Type type)
            => SasquatchReflectionUtility.GetTopLevelBindableProperties(type)
                .Where(p => !IsBulkPropertyHidden(type, p.path)).ToList();

        // True when the field at <paramref name="path"/> on <paramref name="type"/> is marked [HideInInspector].
        private static bool IsBulkPropertyHidden(System.Type type, string path)
        {
            var fi = BindingFactory.GetFieldInfoFromPropertyPath(type, path, out _);
            return UnboundFieldSync.IsHiddenInInspector(fi);
        }

        private void AddCardToAll()
        {
            if (_clonedLayoutAsset == null || !(_clonedLayoutAsset.Root is ContainerNode root) ||
                root.Children == null || root.Children.Count == 0)
            {
                ShowToolToast("Wrap All in Cards: nothing to wrap (the layout is empty).", ToastKind.Info);
                return;
            }

            Undo.RecordObject(_clonedLayoutAsset, "Add Card To All");

            int newlyWrapped = 0;
            var wrapped = new List<LayoutNode>(root.Children.Count);
            foreach (var child in root.Children)
            {
                // Skip anything already sitting in its own card.
                if (child is ContainerNode c && c.Type == ContainerType.Card)
                {
                    wrapped.Add(child);
                }
                else
                {
                    var card = new ContainerNode { Type = ContainerType.Card };
                    card.Children.Add(child);
                    wrapped.Add(card);
                    newlyWrapped++;
                }
            }
            root.Children = wrapped;

            OnModification();
            RefreshAll();
            ShowToolToast(newlyWrapped > 0
                ? $"Wrapped {newlyWrapped} node{(newlyWrapped == 1 ? "" : "s")} in cards."
                : "Wrap All in Cards: every node was already in a card.", ToastKind.Success);
        }

        // A fresh layout root, pre-seeded with the Script Header widget pinned at the top (our nicer take on
        // Unity's Script field). It's a normal node — delete it if unwanted, or re-add it from the Widgets palette.
        private static ContainerNode NewRootWithScriptHeader()
        {
            var root = new ContainerNode { Type = DefaultRootContainerTypeOrFallback() };
            root.Children.Add(new ScriptHeaderNode());
            return root;
        }

        // Structural import defaults come from the active Layout Preset (a project-wide, shippable choice) and are
        // read independently of the per-user "Use Layout Presets" widget toggle — they shape container STRUCTURE,
        // not per-field widgets. Fall back to the recommended shipped defaults if no preset resolves.
        // (Internal: the header-aware auto-sync creates its brand-new-header sections with the same default.)
        internal static ContainerType DefaultHeaderContainerTypeOrFallback()
        {
            var preset = LayoutPresetManager.Current;
            return preset != null ? preset.DefaultHeaderContainerType : ContainerType.Card;
        }

        private static ContainerType DefaultRootContainerTypeOrFallback()
        {
            var preset = LayoutPresetManager.Current;
            return preset != null ? preset.DefaultRootContainerType : ContainerType.Rows;
        }

        private void BulkAdd(BulkAddMode mode, string toolName)
        {
            var type = ResolveTargetType();
            if (type == null || _clonedLayoutAsset == null)
            {
                ShowToolToast($"{toolName}: select an object or layout with a valid target type first.", ToastKind.Warning);
                return;
            }

            if (!(_clonedLayoutAsset.Root is ContainerNode root))
            {
                root = NewRootWithScriptHeader();
                _clonedLayoutAsset.Root = root;
            }

            // Smart Attribute Import seeds the Script Header the layout is almost certainly going to want.
            // NewRootWithScriptHeader above only fires for a layout with no root at all, so the common path —
            // clear the layout, then re-import — left you dragging the header in by hand every single time.
            //
            // ONLY when the tree carries none. A user who deliberately deleted theirs, or moved it down into a
            // container, must never have it silently reinstated on the next import: this is a seed for the
            // empty case, not a rule the layout gets held to.
            bool needsScriptHeader = mode == BulkAddMode.FromScriptAttributes && !ContainsScriptHeader(root);

            var all = SasquatchReflectionUtility.GetSerializableProperties(type);
            var props = GetBulkAddProperties(type);

            // Sync Missing always skips fields already in the layout; every other mode skips them too
            // while "Disable Duplicate Bindings" is on, so the tools can't pile on duplicates.
            // Pass `bound` as derivedPaths too: a bool used as a Foldout's group-toggle header checkbox is
            // already in use even though it isn't an explicit BindingNode, so it must count as "bound" here
            // (otherwise Smart Import re-adds the field AND spawns a duplicate [Header] foldout for it).
            int skipped = 0;
            if (mode == BulkAddMode.RemainingOnly || _preventDuplicateBindings)
            {
                var bound = new HashSet<string>();
                GatherBoundPaths(_clonedLayoutAsset.Root, "", bound, derivedPaths: bound);
                var filtered = props.Where(p => !bound.Contains(p.path)).ToList();
                skipped = props.Count - filtered.Count;
                props = filtered;
            }

            // A missing Script Header is itself something to add, so "nothing to add" has to account for it —
            // otherwise re-importing a fully-bound layout bails out and silently declines to seed the header.
            if (props.Count == 0 && !needsScriptHeader)
            {
                ShowToolToast(skipped > 0
                    ? $"{toolName}: nothing to add — all {skipped} field{(skipped == 1 ? " is" : "s are")} already in the layout."
                    : $"{toolName}: no serializable fields found on this type.", ToastKind.Warning);
                return;
            }

            int added = props.Count;
            Undo.RecordObject(_clonedLayoutAsset, "Bulk Add Fields");

            // Before the import, so the header leads and the fields land beneath it — the same position
            // NewRootWithScriptHeader pins it at, and the one Sort Root and Flatten both preserve.
            if (needsScriptHeader) root.Children.Insert(0, new ScriptHeaderNode());

            // When the per-user "Use Layout Presets" toggle is on, new fields inherit their type's default widget +
            // config from the active preset; off ⇒ plain default fields (the historical behavior).
            var preset = LayoutPresetPrefs.UseLayoutPresets ? LayoutPresetManager.Current : null;

            // The non-attribute importers deliberately ignore [Space] — mark attribute-carrying fields as
            // accounted-for (declined) so the auto-sync engine doesn't retro-import the gap behind the tool's
            // back. Removing and re-adding the attribute in code re-arms the import as usual.
            void DeclineSpace(LayoutNode node, SasquatchReflectionUtility.ReflectedProperty p)
            {
                var fi = BindingFactory.GetFieldInfoFromPropertyPath(type, p.path, out _);
                if (UnboundFieldSync.TryGetSpaceBefore(fi, out _)) node.SpaceImported = true;
            }

            if (mode == BulkAddMode.FromScriptAttributes)
            {
                ImportAttributesIntoLayout(type, props, all, root, preset);
            }
            else if (mode == BulkAddMode.ByHeader)
            {
                ContainerNode currentSection = null;
                foreach (var p in props)
                {
                    var node = MakeFieldNode(p, all, preset);
                    DeclineSpace(node, p);
                    string header = GetFieldHeader(type, p.path);
                    if (!string.IsNullOrEmpty(header))
                    {
                        currentSection = new ContainerNode { Type = DefaultHeaderContainerTypeOrFallback(), Title = header, SourceHeader = header, DefaultToOpen = true };
                        root.Children.Add(currentSection);
                        // The [Header] becomes the section title — suppress this leading field's own header
                        // so the section name isn't rendered twice (title + inner decorator).
                        if (node is BindingNode leadBinding) leadBinding.Header = LayoutNode.HiddenSentinel;
                    }
                    (currentSection ?? root).Children.Add(node);
                }
            }
            else
            {
                foreach (var p in props)
                {
                    var node = MakeFieldNode(p, all, preset);
                    DeclineSpace(node, p);
                    if (mode == BulkAddMode.EachInCard)
                    {
                        var card = new ContainerNode { Type = ContainerType.Card };
                        card.Children.Add(node);
                        root.Children.Add(card);
                    }
                    else
                    {
                        root.Children.Add(node);
                    }
                }
            }

            OnModification();
            RefreshAll();

            // Name the Script Header explicitly. It is a node the user did not ask for by name, so the toast is
            // the only thing that tells them where it came from — and that it is an ordinary node they can delete.
            string msg = added > 0
                ? $"{toolName}: added {added} field{(added == 1 ? "" : "s")}{(needsScriptHeader ? " and a Script Header" : "")}."
                : $"{toolName}: added a Script Header.";
            if (skipped > 0) msg += $" Skipped {skipped} already in the layout.";
            ShowToolToast(msg, ToastKind.Success);
        }

        /// <summary>
        /// Whether a <see cref="ScriptHeaderNode"/> already exists anywhere in the root tree. Walks containers
        /// only — deliberately NOT into a collection's item template, where a header would belong to the ROW
        /// rather than to the inspector, and so does not count as the layout having one.
        /// </summary>
        private static bool ContainsScriptHeader(ContainerNode container)
        {
            if (container?.Children == null) return false;
            foreach (var child in container.Children)
            {
                if (child is ScriptHeaderNode) return true;
                if (child is ContainerNode nested && ContainsScriptHeader(nested)) return true;
            }
            return false;
        }

        // Upgrades every binding still on the plain Default widget to its preset widget + config, preserving each
        // binding's identity (label, header, conditions, position). Explicit action — ignores the "Use Layout
        // Presets" toggle and always applies the active preset.
        private void ApplyPresetsToLayout()
        {
            if (_clonedLayoutAsset == null || !(_clonedLayoutAsset.Root is ContainerNode))
            {
                ShowToolToast("Apply Presets to Layout: no layout loaded.", ToastKind.Warning);
                return;
            }

            var preset = LayoutPresetManager.Current;
            Undo.RecordObject(_clonedLayoutAsset, "Apply Presets to Layout");

            // The walk swaps upgraded bindings for new node objects, so any selection pointing at one would go
            // stale. Snapshot the WHOLE selection (primary + multi-selection) as positional paths and re-point every
            // node afterward — re-pointing only the primary used to silently drop the rest of a multi-selection.
            var selectionSnapshot = SnapshotNodeState(_clonedLayoutAsset.Root);

            int count = 0;
            _clonedLayoutAsset.Root = UpgradePresetsRecursive(_clonedLayoutAsset.Root, preset, ref count);

            // Preset templates carry Style.width/height and TextBoxHeight, so installing them is a resize edit —
            // without this the sizes the preset just applied revert on the next Save.
            if (count > 0) ClaimResizeAuthority();

            if (count > 0)
            {
                RestoreNodeState(selectionSnapshot, _clonedLayoutAsset.Root);
                OnModification();
                RefreshAll();
                ShowToolToast($"Applied presets — upgraded {count} field{(count == 1 ? "" : "s")} to their preset widgets.", ToastKind.Success);
            }
            else
            {
                ShowToolToast("Apply Presets: no plain default fields to upgrade.", ToastKind.Info);
            }
        }

        // Tree-rewrite: returns the (possibly replaced) node. A Default binding whose type has an enabled preset
        // template is swapped for a configured clone that keeps the original's identity; containers and collection
        // item-layouts recurse. The field type is resolved while the binding is still in the tree
        // (ResolveSelectedNodeFieldType locates it by reference), so the swap happens via the returned value.
        private LayoutNode UpgradePresetsRecursive(LayoutNode node, SasquatchLayoutPreset preset, ref int count, bool force = false, CollectionFieldContext? context = null)
        {
            if (node is BindingNode bn)
            {
                // Apply touches only plain-default bindings; Override (force) replaces any binding. Inside a
                // List/Table collection, prefer that context's override (falling back to the base preset).
                if (force || bn.DisplayType == DisplayType.Default)
                {
                    var t = ResolveSelectedNodeFieldType(bn);
                    if (t != null && LayoutPresetApplier.TryUpgrade(bn, t, preset, context, out var upgraded, force))
                    {
                        count++;
                        return upgraded;
                    }
                }
                return node;
            }

            if (node is ContainerNode cont && cont.Children != null)
            {
                for (int i = 0; i < cont.Children.Count; i++)
                    cont.Children[i] = UpgradePresetsRecursive(cont.Children[i], preset, ref count, force, context);
                return node;
            }

            if (node is CollectionNode col && col.ItemLayout != null)
            {
                // Its element fields are rendered in the collection's own context — resolve it and pass it down so
                // the item-layout leaves honor any List/Table override.
                col.ItemLayout = UpgradePresetsRecursive(col.ItemLayout, preset, ref count, force, LayoutPresetApplier.ContextFor(col.DisplayMode));
                return node;
            }

            return node;
        }

        // Override with Presets — the destructive sibling of ApplyPresetsToLayout: forces EVERY binding (even ones
        // already on a custom widget) to its preset widget + config, keeping only identity (label, header,
        // conditions, position). Confirmed via dialog. Explicit action — ignores the "Use Layout Presets" toggle.
        private void OverridePresetsToLayout()
        {
            if (_clonedLayoutAsset == null || !(_clonedLayoutAsset.Root is ContainerNode))
            {
                ShowToolToast("Override with Presets: no layout loaded.", ToastKind.Warning);
                return;
            }

            if (!EditorUtility.DisplayDialog("Override with Presets",
                    "Replace EVERY field's widget and configuration with its Layout Preset default?\n\n" +
                    "This overwrites widgets and settings you've already customized — every field is reset to " +
                    "exactly what your preset says for its type. Labels, headers, tooltips, conditions, animations " +
                    "and position are kept. You can still undo this with Ctrl+Z.",
                    "Override Everything", "Cancel"))
                return;

            var preset = LayoutPresetManager.Current;
            Undo.RecordObject(_clonedLayoutAsset, "Override with Presets");

            // The walk swaps overridden bindings for new node objects, so any selection pointing at one would go
            // stale. Snapshot the WHOLE selection (primary + multi-selection) and re-point every node afterward
            // (as ApplyPresets does) — re-pointing only the primary used to silently drop the rest of a selection.
            var selectionSnapshot = SnapshotNodeState(_clonedLayoutAsset.Root);

            int count = 0;
            _clonedLayoutAsset.Root = UpgradePresetsRecursive(_clonedLayoutAsset.Root, preset, ref count, force: true);

            // Same as ApplyPresetsToLayout: the installed templates carry resize-class fields.
            if (count > 0) ClaimResizeAuthority();

            if (count > 0)
            {
                RestoreNodeState(selectionSnapshot, _clonedLayoutAsset.Root);
                OnModification();
                RefreshAll();
                ShowToolToast($"Override with Presets — reset {count} field{(count == 1 ? "" : "s")} to their preset widgets.", ToastKind.Success);
            }
            else
            {
                ShowToolToast("Override with Presets: no fields matched an enabled preset category.", ToastKind.Info);
            }
        }

        // The dedicated "Import C# Properties" tool: adds a live PropertyNode for every readable C# property
        // not already in the layout. Kept separate from the field importers (BulkAdd) on purpose.
        private void ImportProperties()
        {
            var type = ResolveTargetType();
            if (type == null) return;
            var root = _clonedLayoutAsset?.Root as ContainerNode;
            if (root == null) return;

            if (!PropertyInvoker.GetReadableProperties(type).Any())
            {
                ShowToolToast("Import C# Properties: this type has no readable C# properties.", ToastKind.Warning);
                return;
            }

            Undo.RecordObject(_clonedLayoutAsset, "Import C# Properties");
            int added = ImportPropertiesIntoLayout(type, root);
            if (added == 0)
            {
                ShowToolToast("Import C# Properties: every property is already in the layout.", ToastKind.Warning);
                return;
            }

            OnModification();
            RefreshAll();
            ShowToolToast($"Import C# Properties: added {added} propert{(added == 1 ? "y" : "ies")}.", ToastKind.Success);
        }

        /// <summary>Imports C# inspector attributes ([Header], [Range], [Tooltip], …) from <paramref name="type"/> onto the matching layout nodes.
        /// When <paramref name="preset"/> is supplied each new binding inherits its type's default widget + config first; explicit attributes then override.</summary>
        public static void ImportAttributesIntoLayout(System.Type type, List<SasquatchReflectionUtility.ReflectedProperty> props, List<SasquatchReflectionUtility.ReflectedProperty> all, ContainerNode root, SasquatchLayoutPreset preset = null)
        {
            ContainerNode currentSection = null;
            foreach (var p in props)
            {
                var fi = BindingFactory.GetFieldInfoFromPropertyPath(type, p.path, out _);
                if (UnboundFieldSync.IsHiddenInInspector(fi))
                {
                    // A hidden field still opens a section for its own [Header].
                    string headerAttr = (Attribute.GetCustomAttribute(fi, typeof(HeaderAttribute)) as HeaderAttribute)?.header;
                    if (!string.IsNullOrEmpty(headerAttr))
                    {
                        currentSection = new ContainerNode { Type = DefaultHeaderContainerTypeOrFallback(), Title = headerAttr, SourceHeader = headerAttr, DefaultToOpen = true };
                        root.Children.Add(currentSection);
                    }
                    continue;
                }

                var node = MakeFieldNode(p, all, preset);

                if (fi != null)
                {
                    // Tooltip / Range / TextArea (shared with the auto-sync engine). Runs AFTER the
                    // preset is applied (in MakeFieldNode), so an explicit [Range]/[TextArea] wins over a preset.
                    UnboundFieldSync.ApplyPerFieldAttributes(fi, node);

                    // [Space] imports as a real, attribute-owned Space widget dropped in ABOVE the field (a
                    // [Space] decorator draws its gap above the field it decorates). [Space(n)] carries the pixel
                    // amount through. Flag the field's node as accounted-for AND stamp the spacer with the field's
                    // path so it's locked to the attribute. Dedupe against an existing owned spacer for this field
                    // (a stale orphan from old data) so a re-import can't stack a second gap.
                    bool hasSpace = UnboundFieldSync.TryGetSpaceBefore(fi, out float spaceHeight);
                    if (hasSpace) node.SpaceImported = true;
                    bool emitSpacer = hasSpace && !UnboundFieldSync.HasOwnedSpacer(root, p.path);

                    // Header grouping — a bulk-import-only concern (the sync engine never creates sections)
                    string header = (Attribute.GetCustomAttribute(fi, typeof(HeaderAttribute)) as HeaderAttribute)?.header;
                    if (!string.IsNullOrEmpty(header))
                    {
                        // The field also opens a section: the [Space] sits above the whole section, so it
                        // lands at root just before the section container rather than inside it.
                        if (emitSpacer) root.Children.Add(UnboundFieldSync.MakeSpaceNode(spaceHeight, p.path));
                        currentSection = new ContainerNode { Type = DefaultHeaderContainerTypeOrFallback(), Title = header, SourceHeader = header, DefaultToOpen = true };
                        root.Children.Add(currentSection);
                        // The [Header] becomes the section title — suppress this leading field's own header
                        // so the section name isn't rendered twice (title + inner decorator).
                        if (node is BindingNode leadBinding) leadBinding.Header = LayoutNode.HiddenSentinel;
                    }
                    else if (emitSpacer)
                    {
                        (currentSection ?? root).Children.Add(UnboundFieldSync.MakeSpaceNode(spaceHeight, p.path));
                    }
                }

                (currentSection ?? root).Children.Add(node);
            }
            // NOTE: C# properties are deliberately NOT imported here — Smart/Flat Import handle serialized
            // FIELDS only. Use the dedicated "Import C# Properties" tool (or the Bindings-tab card) for those.
        }

        // Adds a live PropertyNode for every readable C# property on the type that isn't already in the
        // layout. Backs the dedicated "Import C# Properties" tool and is reflected-by-name (no path scoping).
        // Returns how many were added.
        /// <summary>Adds layout nodes for <paramref name="type"/>'s bindable properties into <paramref name="root"/>; returns the number added.</summary>
        public static int ImportPropertiesIntoLayout(System.Type type, ContainerNode root)
        {
            if (type == null || root == null) return 0;
            if (root.Children == null) root.Children = new List<LayoutNode>();
            var existing = new HashSet<string>();
            CollectPropertyNodeNames(root, existing);
            int added = 0;
            foreach (var pi in PropertyInvoker.GetReadableProperties(type))
            {
                if (!existing.Add(pi.Name)) continue; // already present (or a dup name) — skip
                root.Children.Add(new PropertyNode { PropertyName = pi.Name });
                added++;
            }
            return added;
        }

        /// <summary>Creates the layout node for a single reflected property (a binding or a collection). When
        /// <paramref name="preset"/> is supplied, a new binding inherits its type's default widget + config.</summary>
        public static LayoutNode MakeFieldNode(SasquatchReflectionUtility.ReflectedProperty p, List<SasquatchReflectionUtility.ReflectedProperty> all, SasquatchLayoutPreset preset = null)
        {
            if (!p.isCollection)
                return LayoutPresetApplier.MakeConfiguredBinding(p.path, p.type, preset);

            // For a list/array, also auto-build its item-layout template from the element's fields so
            // each element renders its fields (like the default inspector). Element fields can't be
            // bound at the root, so this is the meaningful place for them.
            var collection = new CollectionNode { PropertyPath = p.path };
            var template = BuildCollectionItemTemplate(p.path, all, preset);
            if (template != null)
            {
                collection.ItemLayout = template;
                return collection;
            }

            // NO element fields to build a template FROM — the elements are ATOMIC (List<float>,
            // List<Vector2>, an enum list). Those still have exactly one thing that can go in an item
            // layout: a binding on the ELEMENT itself. Without it the import produced a list the user
            // could not style at all until they found the +T button, which is the one gap that made
            // "add a field, it appears laid out" untrue for a whole category of field. Seeded BARE, so
            // the rows render exactly as they did untemplated (see SetElementTemplate), and mode-agnostic
            // — it is a List's row body AND a Table's single "Value" column.
            SasquatchReflectionUtility.IsCollectionType(p.type, out var elementType);
            if (ShouldSeedElementTemplate(elementType, p.isManagedReference))
                SetElementTemplate(collection, elementType, preset);
            return collection;
        }

        /// <summary>
        /// Whether an AUTOMATIC import — Smart/Flat Import, Bulk Add, and the inspector-side auto-sync —
        /// should seed a brand-new collection's item layout with an ELEMENT TEMPLATE.
        /// <para>
        /// Narrower than <see cref="SupportsElementTemplate"/>, which is the gate for the user ASKING for one
        /// (+T, the Bindings panel's Element token, Table auto-fill). The extra exclusion is OBJECT-REFERENCE
        /// elements: a <c>List&lt;SomeAsset&gt;</c> already draws a perfectly good object row, and an item
        /// layout is precisely what <see cref="SupportsInlineEditorRows"/> tests the ABSENCE of — seeding one
        /// unasked would silently withdraw the "In-Line Editor Rows" option from every object list in the
        /// project. Asking for a template there is still one +T away; taking the option away is not undoable
        /// by any gesture the user would think to look for.
        /// </para>
        /// </summary>
        internal static bool ShouldSeedElementTemplate(Type elementType, bool isManagedReference)
        {
            if (!SupportsElementTemplate(elementType, isManagedReference)) return false;
            if (typeof(UnityEngine.Object).IsAssignableFrom(elementType)) return false;
            return true;
        }

        // Builds a Column item-template containing a binding for each direct element field of a
        // collection (paths like "modifications.modName" → relative "modName").
        /// <summary>Builds the default item-layout template for a collection's element type. Element bindings inherit
        /// preset widget + config (per element-field type) when <paramref name="preset"/> is supplied.</summary>
        public static ContainerNode BuildCollectionItemTemplate(string collectionPath, List<SasquatchReflectionUtility.ReflectedProperty> all, SasquatchLayoutPreset preset = null, CollectionFieldContext context = CollectionFieldContext.InList)
        {
            string prefix = collectionPath + ".";
            var template = new ContainerNode { Type = ContainerType.Rows };
            foreach (var p in all)
            {
                if (p.isCollection) continue;
                if (!p.path.StartsWith(prefix)) continue;
                string rel = p.path.Substring(prefix.Length);
                if (rel.Contains('.')) continue; // direct element fields only
                // A new collection defaults to List, so element fields inherit the InList context override (if any),
                // falling back to the base type preset.
                template.Children.Add(LayoutPresetApplier.MakeConfiguredBinding(rel, p.type, preset, context));
            }
            return template.Children.Count > 0 ? template : null;
        }

        private static string GetFieldHeader(System.Type type, string path)
        {
            var fi = BindingFactory.GetFieldInfoFromPropertyPath(type, path, out _);
            if (fi == null) return null;
            return (Attribute.GetCustomAttribute(fi, typeof(HeaderAttribute)) as HeaderAttribute)?.header;
        }

        private VisualElement CreateWidgetPaletteRow(string icon, string label, string displayType, string tooltipText)
        {
            var row = new VisualElement();
            row.style.flexDirection = FlexDirection.Row;
            row.style.alignItems = Align.Center;
            row.style.paddingTop = 6;
            row.style.paddingBottom = 6;
            row.style.paddingLeft = 10;
            row.style.paddingRight = 10;
            row.style.marginBottom = 4;
            
            var normalBg = DesignerPalette.RowBg;
            var hoverBg = DesignerPalette.RowHoverBg;
            row.style.backgroundColor = normalBg;
            AddHoverHighlight(row, normalBg, hoverBg);
            
            row.style.borderTopWidth = 1;
            row.style.borderBottomWidth = 1;
            row.style.borderLeftWidth = 1;
            row.style.borderRightWidth = 1;
            row.style.borderTopColor = DesignerPalette.BorderMid;
            row.style.borderBottomColor = DesignerPalette.BorderMid;
            row.style.borderLeftColor = DesignerPalette.BorderMid;
            row.style.borderRightColor = DesignerPalette.BorderMid;
            row.style.borderTopLeftRadius = 4;
            row.style.borderTopRightRadius = 4;
            row.style.borderBottomLeftRadius = 4;
            row.style.borderBottomRightRadius = 4;
            row.tooltip = tooltipText;

            var iconEl = SasquatchIcons.Create(icon, 14);
            iconEl.style.marginRight = 6;
            row.Add(iconEl);

            var nameLbl = new Label(label);
            nameLbl.style.flexGrow = 1;
            nameLbl.style.color = DesignerPalette.TextPrimary;
            nameLbl.style.unityFontStyleAndWeight = FontStyle.Bold;
            row.Add(nameLbl);

            if (_canvasDragController != null)
            {
                row.AddManipulator(new CanvasDragManipulator(
                    _canvasDragController, CanvasDragPayload.AddWidget(displayType, label)));
            }

            return row;
        }

        // Collects every explicitly-bound property path into `paths` (moved to UnboundFieldSync so the
        // inspector-side auto-sync can use it without a window; see docs there).
        private void GatherBoundPaths(LayoutNode node, string basePath, HashSet<string> paths, HashSet<string> derivedPaths = null)
            => UnboundFieldSync.GatherBoundPaths(node, basePath, paths, derivedPaths);

        private bool IsAncestorOf(LayoutNode potentialAncestor, LayoutNode potentialDescendant)
        {
            if (potentialAncestor == potentialDescendant) return true;
            if (potentialAncestor is ContainerNode container)
            {
                if (container.Children != null)
                {
                    foreach (var child in container.Children)
                    {
                        if (IsAncestorOf(child, potentialDescendant)) return true;
                    }
                }
            }
            else if (potentialAncestor is CollectionNode col && col.ItemLayout != null)
            {
                if (IsAncestorOf(col.ItemLayout, potentialDescendant)) return true;
            }
            return false;
        }

        private string GetEffectiveBasePath(LayoutNode targetNode, LayoutNode current, string currentBasePath)
        {
            if (current == null) return null;
            if (current == targetNode) return currentBasePath;

            if (current is ContainerNode container)
            {
                string nextBasePath = currentBasePath;
                if (!string.IsNullOrEmpty(container.PropertyPath))
                {
                    nextBasePath = string.IsNullOrEmpty(currentBasePath) ? container.PropertyPath : $"{currentBasePath}.{container.PropertyPath}";
                }

                if (container.Children != null)
                {
                    foreach (var child in container.Children)
                    {
                        string res = GetEffectiveBasePath(targetNode, child, nextBasePath);
                        if (res != null) return res;
                    }
                }
            }
            else if (current is CollectionNode col)
            {
                string nextBasePath = string.IsNullOrEmpty(currentBasePath) ? col.PropertyPath : $"{currentBasePath}.{col.PropertyPath}";
                if (col.ItemLayout == targetNode) return nextBasePath;

                if (col.ItemLayout != null)
                {
                    string res = GetEffectiveBasePath(targetNode, col.ItemLayout, nextBasePath);
                    if (res != null) return res;
                }
            }
            return null;
        }

        /// <summary>How a dropped node lands relative to its target: above, below, or as a child.</summary>
        public enum DropRelation
        {
            Above,
            Below,
            AsChild
        }

        private string GetEffectiveDropBasePath(LayoutNode targetNode)
        {
            return GetEffectiveDropBasePathRelative(targetNode, DropRelation.AsChild);
        }

        private string GetEffectiveDropBasePathRelative(LayoutNode targetNode, DropRelation relation)
        {
            if (_clonedLayoutAsset == null || _clonedLayoutAsset.Root == null) return "";

            string targetBasePath = GetEffectiveBasePath(targetNode, _clonedLayoutAsset.Root, "");
            if (targetBasePath == null) targetBasePath = "";

            if (relation == DropRelation.AsChild && targetNode is ContainerNode container && !string.IsNullOrEmpty(container.PropertyPath))
            {
                return string.IsNullOrEmpty(targetBasePath) ? container.PropertyPath : $"{targetBasePath}.{container.PropertyPath}";
            }

            // Dropping a field INTO a collection scopes it to the element, so strip the collection's own
            // path too (e.g. "modifications.modName" dropped on "modifications" → element-relative "modName").
            if (relation == DropRelation.AsChild && targetNode is CollectionNode collection && !string.IsNullOrEmpty(collection.PropertyPath))
            {
                return string.IsNullOrEmpty(targetBasePath) ? collection.PropertyPath : $"{targetBasePath}.{collection.PropertyPath}";
            }

            return targetBasePath;
        }

        private void HandlePropertyDrop(LayoutNode targetNode, string path, DropRelation relation)
        {
            HandlePropertyDrop(targetNode, path, relation, -1);
        }

        private void HandlePropertyDrop(LayoutNode targetNode, string path, DropRelation relation, int slotIndex)
        {
            if (_clonedLayoutAsset == null) return;

            // Remember the selection so a drop that lands inside the currently-open Tabs container keeps
            // that container selected — otherwise the Tab Organizer would navigate to the dropped item
            // and vanish, forcing the user to re-click the Tabs container after every drop.
            var prevSel = _selectedNode;

            // An ELEMENT token names a collection, not a place — the template it creates can only live in
            // that collection's item layout, so where it was dropped says nothing about where it goes.
            // Routed before everything below, which all assumes a path that lands at the drop site.
            if (!string.IsNullOrEmpty(path) && path.StartsWith(ElementTokenPrefix))
            {
                HandleElementTemplateDrop(path.Substring(ElementTokenPrefix.Length), targetNode, relation, slotIndex);
                return;
            }

            // Duplicate guard (drag & drop). Widgets ("Widget:...") can repeat freely; field bindings
            // can't be added twice while the setting is on. The token bank already locks bound tokens,
            // so this is mostly a safety net (and the enforcement point when that lock is bypassed).
            if (_preventDuplicateBindings && !string.IsNullOrEmpty(path)
                && !path.StartsWith("Widget:") && !path.StartsWith("Property:"))
            {
                var alreadyBound = new HashSet<string>();
                // derivedPaths too: a field already in use as a Foldout group-toggle bool counts as bound.
                GatherBoundPaths(_clonedLayoutAsset.Root, "", alreadyBound, derivedPaths: alreadyBound);
                if (alreadyBound.Contains(path)) return;
            }

            Undo.RecordObject(_clonedLayoutAsset, "Drop Property Token");

            LayoutNode newNode = CreateNodeForPath(path, targetNode, relation);
            if (newNode == null) return;

            InsertDroppedNode(newNode, targetNode, relation, slotIndex);

            // Dropping a NEW item into the Tab Organizer is organization, not navigation: if the item
            // landed inside the Tabs container the user is currently inspecting, keep that container
            // selected so the organizer stays open. Otherwise focus the fresh node as usual.
            if (prevSel is ContainerNode pc && pc.Type == ContainerType.Tabs && IsAncestorOf(pc, newNode))
                SetPrimarySelection(prevSel);
            else
                SetPrimarySelection(newNode);
            // Let the drag engine know which node was created so it can play the settle animation
            // on the fresh card after the rebuild.
            _canvasDragController?.NotifyCreatedNode(newNode);
            OnModification();
            RefreshAll();
        }

        // Puts a freshly created node where the drop asked for it: inside a container (honouring cell slots
        // and the Tabs wrap rule), inside a collection's item layout, or beside the target in its parent.
        // Extracted so the element-template drop can reuse the exact same landing rules when it has to
        // create the collection itself.
        private void InsertDroppedNode(LayoutNode newNode, LayoutNode targetNode, DropRelation relation, int slotIndex)
        {
            if (relation == DropRelation.AsChild && targetNode is ContainerNode container)
            {
                if (container.Children == null) container.Children = new List<LayoutNode>();
                // A direct child of a Tabs container must be a tab — wrap a loose drop in a new tab.
                var toInsert = WrapAsTabIfNeeded(container, newNode);
                // In a tracked container the slot is a CELL, not just a list position: dropping on the
                // third "＋" of a three-track Columns must land at index 2, holding cells 0-1 open. See
                // EmptyCellFill — untracked containers fall through to the plain insert this replaced.
                EmptyCellFill.InsertAtCell(container, toInsert, slotIndex);
            }
            else if (relation == DropRelation.AsChild && targetNode is CollectionNode collectionTarget)
            {
                // Dropping a field onto a collection builds/extends its item-layout template: create the
                // Panel item container if missing (mirrors the +T button), then add the binding inside it.
                AttachToItemLayout(collectionTarget, newNode);
            }
            else
            {
                var parent = FindParent(targetNode, _clonedLayoutAsset.Root);
                if (parent != null && parent.Children != null)
                {
                    int index = parent.Children.IndexOf(targetNode);
                    if (index >= 0)
                    {
                        int insertAt = relation == DropRelation.Above ? index : index + 1;
                        insertAt = Mathf.Clamp(insertAt, 0, parent.Children.Count);
                        parent.Children.Insert(insertAt, newNode);
                    }
                }
            }
        }

        // Adds a node to a collection's item-layout template, creating the Panel item container if this is
        // the first one (mirrors the +T button, so both routes produce the same shape).
        private static void AttachToItemLayout(CollectionNode collection, LayoutNode node)
        {
            if (!(collection.ItemLayout is ContainerNode itemContainer))
            {
                itemContainer = new ContainerNode { StyleToken = "Panel" };
                if (itemContainer.Children == null) itemContainer.Children = new List<LayoutNode>();
                // A NON-container item layout is a lone ELEMENT TEMPLATE, stored bare so a one-widget row
                // renders exactly like the untemplated row it replaced (see SetElementTemplate). Putting a
                // SECOND thing in the row does need a container — so WRAP it, never replace it, or the drop
                // silently deletes the template the user already styled.
                if (collection.ItemLayout != null) itemContainer.Children.Add(collection.ItemLayout);
                collection.ItemLayout = itemContainer;
            }
            if (itemContainer.Children == null) itemContainer.Children = new List<LayoutNode>();
            itemContainer.Children.Add(node);
        }

        /// <summary>
        /// Makes <paramref name="collection"/>'s item layout a lone element template and returns it.
        /// <para>
        /// Stored BARE — as the item layout itself, not inside the usual Panel item container. A container
        /// is a visible thing: it brings the Panel's card chrome and its own box, which turned a compact
        /// row of fields into a tall padded tray. Adding an element template must be a <em>pure</em> change
        /// — the row keeps the widget and spacing it already had, and only gains the ability to be styled —
        /// so the one node that renders one widget goes in with no wrapper at all. Every consumer already
        /// handles a bare item layout (the column collector, the hierarchy, the item-layout owner lookup,
        /// the sync walker); <see cref="AttachToItemLayout"/> wraps it if a second node ever arrives.
        /// </para>
        /// </summary>
        private static BindingNode SetElementTemplate(CollectionNode collection,
            Type elementType = null, SasquatchLayoutPreset preset = null)
        {
            // With an element type in hand the template is seeded like any other imported binding — same
            // preset lookup, in the InList context a new collection renders in. Callers with no type (the +T
            // button, the Bindings-panel drop) get the historical plain binding, which is also exactly what a
            // null preset produces, so the two routes agree whenever presets are off.
            var template = elementType != null
                ? LayoutPresetApplier.MakeConfiguredBinding("", elementType, preset, CollectionFieldContext.InList)
                : new BindingNode { PropertyPath = "" };
            if (collection.ItemLayout == null) collection.ItemLayout = template;
            else AttachToItemLayout(collection, template);
            return template;
        }

        /// <summary>
        /// True when this binding renders the Sasquatch Key/Value table over a resolvable dictionary type, so
        /// Key/Value cell templates apply to it. Delegates to
        /// <see cref="DisplayTypeCatalog.SupportsDictionaryCellTemplates"/> — the SINGLE predicate the
        /// hierarchy, the field-type resolver and the tests all ask, so they cannot drift into offering a
        /// control one of them ignores.
        /// </summary>
        private bool SupportsDictionaryCellTemplates(BindingNode bn) =>
            bn != null && DisplayTypeCatalog.SupportsDictionaryCellTemplates(bn.DisplayType, ResolveSelectedNodeFieldType(bn));

        /// <summary>
        /// Seeds BOTH dictionary cell templates on <paramref name="dictNode"/>, leaving any that already
        /// exists alone.
        /// <para>
        /// Each is a BARE binding with an EMPTY property path — the package-wide "bind the scope itself"
        /// convention, and the same shape <see cref="SetElementTemplate"/> seeds for an atomic list. Bare
        /// matters: a template dropped into a <c>ContainerNode { StyleToken = "Panel" }</c> would wrap every
        /// cell in card chrome and change the row's height, and seeding a template must not move a pixel
        /// until the author actually picks a Display Type.
        /// </para>
        /// <para>
        /// The Label overrides exist for the HIERARCHY, which names a path-less binding "Element" otherwise —
        /// a name that would be simply wrong on a dictionary. They never reach the rendered cell: both cells
        /// are built with <c>forceHideLabel</c>, because the column header already names them.
        /// </para>
        /// </summary>
        private static void SetDictionaryCellTemplates(BindingNode dictNode)
        {
            if (dictNode == null) return;
            if (dictNode.DictionaryKeyTemplate == null)
                dictNode.DictionaryKeyTemplate = new BindingNode { PropertyPath = "", LabelOverride = "Key" };
            if (dictNode.DictionaryValueTemplate == null)
                dictNode.DictionaryValueTemplate = new BindingNode { PropertyPath = "", LabelOverride = "Value" };
        }

        /// <summary>
        /// Commits a drop of the Bindings panel's ELEMENT token. Unlike every other token this one names a
        /// COLLECTION rather than a position: the binding it creates has an empty property path, which is
        /// only meaningful inside that collection's item layout, so the drop LOCATION is deliberately
        /// ignored when the collection is already in the layout. Dropping it somewhere else and getting an
        /// unbound binding would be the literal reading of the gesture and the useless one.
        /// <para>
        /// When the collection is NOT in the layout yet, the ask is still unambiguous — "show me this list,
        /// with styled rows" — so both are created, and THEN the drop location matters: the collection
        /// lands exactly where it was dropped.
        /// </para>
        /// </summary>
        private void HandleElementTemplateDrop(string collectionPath, LayoutNode targetNode, DropRelation relation, int slotIndex)
        {
            Undo.RecordObject(_clonedLayoutAsset, "Add Element Template");

            var template = EnsureElementTemplate(collectionPath, targetNode, relation, slotIndex);
            if (template == null) return;

            // Select the TEMPLATE, not the collection: the whole point of the gesture is to get at the
            // element's styling, and the properties panel is where that happens.
            SetPrimarySelection(template);
            _canvasDragController?.NotifyCreatedNode(template);
            OnModification();
            RefreshAll();
        }

        /// <summary>
        /// The element template of the collection at <paramref name="collectionPath"/>, creating the
        /// template (and the collection, at the drop site, if the layout has neither) when it is missing.
        /// Idempotent: a second drop of the same token returns the template already there rather than
        /// stacking a second unbound binding into the item layout. No undo/refresh — callers own those.
        /// </summary>
        private BindingNode EnsureElementTemplate(string collectionPath, LayoutNode targetNode, DropRelation relation, int slotIndex)
        {
            if (_clonedLayoutAsset?.Root == null || string.IsNullOrEmpty(collectionPath)) return null;

            var collection = FindNodeByPropertyPath(_clonedLayoutAsset.Root, "", collectionPath) as CollectionNode;
            if (collection == null)
            {
                // Same bare node CreateNodeForPath would have made for the collection token itself, so the
                // two routes to "this list is now in the layout" produce identical data.
                collection = new CollectionNode { PropertyPath = collectionPath };
                InsertDroppedNode(collection, targetNode, relation, slotIndex);
            }

            return UnboundFieldSync.FindElementTemplate(collection) ?? SetElementTemplate(collection);
        }

        // Builds the node a dropped token/widget path should create: "Widget:*" → the matching
        // container/button/help-box/header; otherwise a Binding (or Collection) whose path is made
        // drop-relative to the target's scope. Returns null for an unknown widget kind. Shared by the
        // single-drop (HandlePropertyDrop) and multi-drop (HandleMultiPropertyDrop) paths.
        private LayoutNode CreateNodeForPath(string path, LayoutNode targetNode, DropRelation relation)
        {
            if (string.IsNullOrEmpty(path)) return null;

            if (path.StartsWith("Widget:"))
            {
                string displayType = path.Substring("Widget:".Length);
                LayoutNode widget = null;
                if (displayType.StartsWith("Container"))
                {
                    var newContainer = new ContainerNode();
                    if (displayType.StartsWith("Container:"))
                    {
                        string kindStr = displayType.Substring("Container:".Length);
                        if (Enum.TryParse<ContainerType>(kindStr, out var parsedKind)) newContainer.Type = parsedKind;
                    }
                    widget = newContainer;
                }
                else if (displayType == "Button") widget = new ButtonNode();
                else if (displayType == "HelpBox") widget = new HelpBoxNode();
                else if (displayType == "ScriptHeader") widget = new ScriptHeaderNode();
                else if (displayType == "Property") widget = new PropertyNode();
                else if (displayType == "Space") widget = new SpaceNode();
                else if (displayType == "LabeledDivider") widget = new LabeledDividerNode();
                else if (displayType == "ImageBanner") widget = new ImageBannerNode();
                else if (displayType == "TextBlock") widget = new TextBlockNode();
                else if (displayType == "EmbeddedEditor") widget = new EmbeddedEditorNode();
#if SASQ_CUSTOM_WIDGET
                else if (displayType == "CustomWidget") widget = new CustomWidgetNode();
#endif
                // Stamp the user's saved default styling for this widget kind (if enabled + customized).
                return ApplyWidgetPreset(displayType, widget);
            }

            // A C# property token ("Property:<name>") from the Bindings tab — drops a pre-filled PropertyNode.
            // No path-scoping: properties are reflected by name on the root.
            if (path.StartsWith("Property:"))
            {
                return new PropertyNode { PropertyName = path.Substring("Property:".Length) };
            }

            // Strip the effective drop base path so the binding is scoped to where it lands.
            string dropBasePath = GetEffectiveDropBasePathRelative(targetNode, relation);
            string resolvedPath = path;
            if (!string.IsNullOrEmpty(dropBasePath))
            {
                string prefix = dropBasePath + ".";
                if (resolvedPath.StartsWith(prefix)) resolvedPath = resolvedPath.Substring(prefix.Length);
            }

            bool isCollection = false;
            System.Type type = ResolveTargetType();
            if (type != null)
            {
                var props = SasquatchReflectionUtility.GetSerializableProperties(type);
                var match = props.Find(p => p.path == path);
                isCollection = match.isCollection;
            }

            return isCollection
                ? (LayoutNode)new CollectionNode { PropertyPath = resolvedPath }
                : new BindingNode { PropertyPath = resolvedPath };
        }

        // Stamps the user's saved default STYLING for this palette widget onto a freshly created node (styling
        // only — never content/identity), so a dropped widget arrives pre-styled. A no-op unless the user has
        // enabled + customized this widget kind in the Presets editor (WIDGETS section). Applies on every manual
        // drop, independent of the field-import "Use Layout Presets" toggle. Returns the node unchanged otherwise.
        private LayoutNode ApplyWidgetPreset(string paletteType, LayoutNode node)
        {
            if (node != null
                && WidgetPresetCatalog.TryKindForPaletteType(paletteType, out var kind)
                && LayoutPresetManager.Current != null
                && LayoutPresetManager.Current.TryGetWidgetTemplate(kind, out var template))
                ApplyWidgetTemplate(template, node);
            return node;
        }

        // Multi-token add (Bindings tab multi-drag): create one node per path under the target, then a
        // single refresh. Mirrors HandlePropertyDrop's create/guard/insert but for a whole selection.
        // The drag engine only ever commits AsChild + an explicit slot, so the AsChild cases carry it.
        private void HandleMultiPropertyDrop(LayoutNode targetNode, List<string> paths, DropRelation relation, int slotIndex)
        {
            if (_clonedLayoutAsset == null || paths == null || paths.Count == 0) return;

            // See HandlePropertyDrop: a drop that lands inside the open Tabs container keeps that
            // container selected so the Tab Organizer stays put instead of jumping to the dropped items.
            var prevSel = _selectedNode;

            // Batch duplicate guard: seed with the already-bound paths, then Add() each — that both
            // skips fields already in the layout AND de-dupes within the batch. Null = duplicates allowed.
            HashSet<string> alreadyBound = null;
            if (_preventDuplicateBindings)
            {
                alreadyBound = new HashSet<string>();
                GatherBoundPaths(_clonedLayoutAsset.Root, "", alreadyBound, derivedPaths: alreadyBound);
            }

            Undo.RecordObject(_clonedLayoutAsset, "Drop Property Tokens");

            // Build every node first so placement can be decided from the WHOLE set — a batch dropped on a
            // Tabs container becomes ONE tab (below), which is only knowable once the full set exists.
            var created = new List<LayoutNode>();
            // An ELEMENT token in the batch is committed straight to its own collection — it names a
            // collection rather than a position, so it can never join the placement below. Tracked so a
            // batch of ONLY element tokens still counts as work done (created stays empty).
            LayoutNode lastTemplate = null;
            foreach (var path in paths)
            {
                if (string.IsNullOrEmpty(path)) continue;
                if (path.StartsWith(ElementTokenPrefix))
                {
                    var t = EnsureElementTemplate(path.Substring(ElementTokenPrefix.Length), targetNode, relation, slotIndex);
                    if (t != null) lastTemplate = t;
                    continue;
                }
                if (alreadyBound != null && !path.StartsWith("Widget:") && !alreadyBound.Add(path)) continue;

                var newNode = CreateNodeForPath(path, targetNode, relation);
                if (newNode == null) continue;
                created.Add(newNode);
            }

            if (created.Count == 0)
            {
                if (lastTemplate != null)
                {
                    SetPrimarySelection(lastTemplate);
                    OnModification();
                    RefreshAll();
                }
                return;
            }

            if (relation == DropRelation.AsChild && targetNode is ContainerNode container)
            {
                if (container.Children == null) container.Children = new List<LayoutNode>();
                if (container.Type == ContainerType.Tabs)
                {
                    // A direct child of a Tabs container is a tab. Dropping a BATCH here (e.g. onto the "+"
                    // new-tab target) means "make ONE tab out of all of these", not a tab per item — so the
                    // whole set goes into a single fresh tab (named like a "+" tab). A lone item keeps the
                    // normal wrap (a dropped container becomes the tab directly; a token gets a named wrapper).
                    LayoutNode tab = created.Count == 1
                        ? WrapAsTabIfNeeded(container, created[0])
                        : new ContainerNode
                        {
                            Type = ContainerType.Rows,
                            TabLabel = $"Tab {container.Children.Count + 1}",
                            Children = new List<LayoutNode>(created)
                        };
                    int at = slotIndex >= 0 ? Mathf.Clamp(slotIndex, 0, container.Children.Count) : container.Children.Count;
                    container.Children.Insert(at, tab);
                }
                else
                {
                    // A multi-token drop fills from the targeted CELL rightward — matching the landing
                    // preview, which highlights that cell and the ones after it.
                    int insertAt = slotIndex;
                    foreach (var newNode in created)
                    {
                        EmptyCellFill.InsertAtCell(container, newNode, insertAt);
                        if (insertAt >= 0) insertAt++;
                    }
                }
            }
            else if (relation == DropRelation.AsChild && targetNode is CollectionNode collectionTarget)
            {
                // Through the shared helper, so a batch dropped onto a collection that already holds a bare
                // element template WRAPS it rather than replacing it — the single-drop path's rule.
                foreach (var newNode in created) AttachToItemLayout(collectionTarget, newNode);
            }
            else
            {
                // Defensive sibling insert (the engine commits AsChild, so this is a fallback).
                var parent = FindParent(targetNode, _clonedLayoutAsset.Root);
                if (parent?.Children != null)
                {
                    int idx = parent.Children.IndexOf(targetNode);
                    if (idx >= 0)
                    {
                        int baseAt = relation == DropRelation.Above ? idx : idx + 1;
                        for (int i = 0; i < created.Count; i++)
                        {
                            int at = Mathf.Clamp(baseAt + i, 0, parent.Children.Count);
                            parent.Children.Insert(at, created[i]);
                        }
                    }
                }
            }

            // If the batch landed inside the Tabs container being inspected, keep it selected so the Tab
            // Organizer stays open (organizing, not navigating) — mirrors HandlePropertyDrop.
            if (prevSel is ContainerNode pc && pc.Type == ContainerType.Tabs
                && created.TrueForAll(n => IsAncestorOf(pc, n)))
            {
                SetPrimarySelection(prevSel);
            }
            // Keep the WHOLE dropped set selected on the canvas (primary = last) so it can be immediately
            // re-dragged as a block if it landed in the wrong spot — mirrors HandleGroupMove. A single
            // drop stays an ordinary single selection.
            else if (created.Count > 1)
            {
                _selectedNodes.Clear();
                _selectedNodes.AddRange(created);
                _selectedNode = created[created.Count - 1];
                _selectionAnchor = _selectedNode;
            }
            else
            {
                SetPrimarySelection(created[created.Count - 1]);
            }
            _canvasDragController?.NotifyCreatedNodes(created);
            OnModification();
            RefreshAll();
        }

        // A direct child of a Tabs container must itself be a tab (its own container). When a non-container
        // node (binding/button/collection/help box) — or a nested Tabs — lands straight on a Tabs container,
        // wrap it in a fresh tab so it renders as a real tab AND shows up in the Tab Organizer. A plain
        // container dropped in can serve as a tab directly, so it's returned untouched.
        private LayoutNode WrapAsTabIfNeeded(ContainerNode targetContainer, LayoutNode node)
        {
            if (targetContainer == null || targetContainer.Type != ContainerType.Tabs) return node;
            if (node is ContainerNode cn && cn.Type != ContainerType.Tabs) return node;
            return new ContainerNode
            {
                Type = ContainerType.Rows,
                TabLabel = GetNodeDisplayName(node),
                Children = new List<LayoutNode> { node }
            };
        }

        private void HandleNodeMoveDrop(LayoutNode draggedNode, LayoutNode targetNode, DropRelation relation)
        {
            HandleNodeMoveDrop(draggedNode, targetNode, relation, -1);
        }

        private void HandleNodeMoveDrop(LayoutNode draggedNode, LayoutNode targetNode, DropRelation relation, int slotIndex)
        {
            if (draggedNode == targetNode || IsAncestorOf(draggedNode, targetNode)) return;
            // Structural split-frame panes never move (identity is positional) — the drop is a no-op.
            if (SplitFramePaneOwner(draggedNode) != null) return;
            // A dictionary's Key / Value cell template never moves either, and for the same kind of reason:
            // it has exactly ONE home (which is why CanDuplicateNode refuses to copy it), and it is BARE by
            // construction — an empty PropertyPath means "the cell the row already points at", so anywhere
            // else it renders "BindingNode has no property path." Left unguarded this was worse than a bad
            // paste: the node lives in a reference rather than a Children list, so the hand-rolled detach
            // below (which knows only about ItemLayout) never unhooked it and the drop INSERTED it while the
            // dictionary went on pointing at it — one node, two parents. RemoveNodesGuarded refuses the
            // block path the same way, on the split-Frame pane precedent: the two must agree about one gesture.
            if (FindDictionaryTemplateOwner(draggedNode, _clonedLayoutAsset?.Root) != null) return;

            // Remember the selection so a move that lands inside the currently-open Tabs container keeps
            // that container selected — otherwise the Tab Organizer would vanish after every drop.
            var prevSel = _selectedNode;

            Undo.RecordObject(_clonedLayoutAsset, "Move Layout Node");

            var oldParent = FindParent(draggedNode, _clonedLayoutAsset.Root);

            // A CollectionNode's item-layout TEMPLATE is not in any Children list — it hangs off a single
            // ItemLayout reference — so FindParent cannot see it, and every detach below is a Children.Remove.
            // Dragging a template card out therefore INSERTED it at the destination while the collection went
            // on pointing at it: the same node reachable from two parents, so one edit silently changed two
            // places, and a shape-round-trip could turn it into a cycle. Detached here, before the branches,
            // because each of them resolves its insert position independently. RemoveNodeFromTree has always
            // had this fallback; this path never did.
            if (oldParent == null)
            {
                var oldItemOwner = FindItemLayoutOwner(draggedNode, _clonedLayoutAsset.Root);
                if (oldItemOwner != null) oldItemOwner.ItemLayout = null;
            }

            if (slotIndex >= 0 && relation == DropRelation.AsChild && targetNode is ContainerNode container)
            {
                if (oldParent == container)
                {
                    int oldIndex = container.Children.IndexOf(draggedNode);
                    if (oldIndex >= 0)
                    {
                        // A model-index slot shifts down when an earlier sibling is detached. A CELL slot
                        // does not: it is a TRACK ORDINAL, and a lifted card's track is held open by a
                        // temp "＋" pad, so the tracks never renumber. Re-basing one anyway moved every
                        // out-of-order drop one cell to the left of the cell it previewed on.
                        if (oldIndex < slotIndex && !IsCellTrackCommit())
                        {
                            slotIndex--;
                        }
                        container.Children.RemoveAt(oldIndex);
                    }
                }
                else if (oldParent != null && oldParent.Children != null)
                {
                    oldParent.Children.Remove(draggedNode);
                }

                if (container.Children == null) container.Children = new List<LayoutNode>();
                // Dropping straight onto a Tabs container wraps the node in a new tab (no-op otherwise).
                var toInsert = WrapAsTabIfNeeded(container, draggedNode);
                // Cell-aware in a tracked container (see HandlePropertyDrop): moving a widget onto a
                // later opening holds the cells before it, and onto a held cell consumes that placeholder.
                EmptyCellFill.InsertAtCell(container, toInsert, slotIndex);
            }
            else
            {
                if (oldParent != null && oldParent.Children != null)
                {
                    oldParent.Children.Remove(draggedNode);
                }

                if (relation == DropRelation.AsChild && targetNode is ContainerNode containerNode)
                {
                    if (containerNode.Children == null) containerNode.Children = new List<LayoutNode>();
                    containerNode.Children.Add(WrapAsTabIfNeeded(containerNode, draggedNode));
                }
                else
                {
                    var parent = FindParent(targetNode, _clonedLayoutAsset.Root);
                    if (parent != null && parent.Children != null)
                    {
                        int index = parent.Children.IndexOf(targetNode);
                        if (index >= 0)
                        {
                            int insertAt = relation == DropRelation.Above ? index : index + 1;
                            insertAt = Mathf.Clamp(insertAt, 0, parent.Children.Count);
                            parent.Children.Insert(insertAt, draggedNode);
                        }
                    }
                }
            }

            // The node left oldParent above (three branches, all plain List.Remove). If that was a Tabs
            // container showing the tab that just moved out, its active index is now past the end.
            ClampActiveTab(oldParent);

            // A drag that STARTED in the Tab Organizer is pure reorganization — moving a card between
            // tabs must never navigate the Properties panel to that card (the user only "selects" by
            // CLICKING, not by moving). Keep whatever was inspected (the Tabs container hosting the
            // organizer) so the kanban stays open, regardless of where the card landed. This is the
            // reliable signal; the topology check below only covers canvas/hierarchy drags that happen
            // to land inside an already-selected Tabs container.
            bool fromOrganizer = _canvasDragController != null
                                 && _canvasDragController.CommittingOrigin == DragOrigin.Organizer;
            if (fromOrganizer && prevSel != null)
                SetPrimarySelection(prevSel);
            else if (prevSel is ContainerNode pc && pc.Type == ContainerType.Tabs && IsAncestorOf(pc, draggedNode))
                SetPrimarySelection(prevSel);   // keep the Tab Organizer visible & refreshed
            else
                SetPrimarySelection(draggedNode);
            OnModification();
            RefreshAll();
        }

        // Reorders an array element on the previewed target object (collection items are the
        // target's actual data, not layout nodes). `to` is already the remove-and-insert index.
        private void MoveCollectionItem(string propertyPath, int from, int to)
        {
            if (_previewSerializedObject == null) return;
            var sp = _previewSerializedObject.FindProperty(propertyPath);
            if (sp == null || !sp.isArray) return;

            to = Mathf.Clamp(to, 0, sp.arraySize - 1);
            if (from == to) return;

            sp.MoveArrayElement(from, to);
            _previewSerializedObject.ApplyModifiedProperties();
            RefreshPreview();
        }


        // Re-baselines the auto-sync field snapshot; call whenever the working clone is (re)made.
        private void SnapshotFieldsAtCloneTime()
        {
            _fieldsAtCloneTime = null;
            var type = ResolveTargetType();
            if (type == null) return;
            _fieldsAtCloneTime = new List<string>();
            foreach (var p in SasquatchReflectionUtility.GetTopLevelBindableProperties(type))
                _fieldsAtCloneTime.Add(p.path);
            // Element leaf paths as well, or the Save ledger accounts for the top level only and every
            // unbound element field reads as brand-new to the next reconcile — re-adding, after every
            // single save, the table columns the user just deleted. Same set the inspector-side ledger
            // records (UnboundFieldSync.GetAllElementLeafPaths), which is what keeps the two in step.
            _fieldsAtCloneTime.AddRange(UnboundFieldSync.GetAllElementLeafPaths(type));
        }

        // The auto-sync ledger this save should store: everything the layout binds, plus every field that
        // existed when the editing session began. Fields left unbound at save are deliberate exclusions;
        // fields added to code mid-session that the user never bound stay "new" and auto-sync later.
        private List<string> BuildSaveLedger(System.Type targetType)
        {
            var ledger = new HashSet<string>();
            GatherBoundPaths(_clonedLayoutAsset.Root, "", ledger, ledger);
            if (_fieldsAtCloneTime != null)
            {
                ledger.UnionWith(_fieldsAtCloneTime);
            }
            else if (_clonedLayoutAsset.SyncedFieldPaths != null && _clonedLayoutAsset.SyncedFieldPaths.Count > 0)
            {
                // The clone-time baseline didn't survive (domain reload mid-session). Fall back to the ledger
                // the clone CARRIES — copied from the source asset at clone time and kept current by the
                // in-memory reconciles — NEVER to "all current code fields": a field added to the script
                // after the clone was taken is in the reflection set but absent from the tree being saved,
                // and ledgering it here would permanently exclude it from auto-append (the root cause of the
                // "auto-append sometimes does nothing, no pattern" bug). The carried ledger preserves
                // deliberate exclusions without swallowing anything new.
                ledger.UnionWith(_clonedLayoutAsset.SyncedFieldPaths);
            }
            else
            {
                // No baseline at all: a fresh, never-saved layout whose session crossed a reload. Every
                // current field was visible in this session's token bank, so unbound ones are deliberate
                // exclusions (the historical fresh-save semantic).
                foreach (var p in SasquatchReflectionUtility.GetTopLevelBindableProperties(targetType))
                    ledger.Add(p.path);
                foreach (var path in UnboundFieldSync.GetAllElementLeafPaths(targetType))
                    ledger.Add(path);
            }
            return new List<string>(ledger);
        }

        // Every live designer window, maintained by OnEnable/OnDisable. It answers IsEditingType in O(open
        // windows) instead of O(every loaded object in the editor) — measured at 1.83ms per inspector rebuild
        // before, on an ordinary dev project, and that figure was set by how much the BUYER has loaded rather
        // than by anything this package does.
        //
        // OnEnable/OnDisable bracket the window OBJECT's lifetime, which is exactly the set the old
        // Resources.FindObjectsOfTypeAll scan returned: CreateInstance runs OnEnable immediately (so a window
        // that was built but never shown still registers), a background dock tab stays enabled (so tabbing
        // away does not drop it), and a domain reload calls OnDisable on the way out and OnEnable on every
        // surviving window on the way back in — which is also what repopulates this list, since statics do not
        // survive the reload. Entries are still null-checked on read: Unity's fake-null makes a destroyed
        // window compare null, so nothing here can resurrect a dead one.
        private static readonly List<SasquatchLayoutDesignerWindow> _openDesigners =
            new List<SasquatchLayoutDesignerWindow>();

        // True when any open designer window is editing the given type. The real inspector's auto-sync
        // suppresses itself while this holds: the designer works on a CLONE, and a Save from a stale clone
        // would silently clobber fields the sync just added (same hazard MergeResizeFields exists for).
        /// <summary>True when a designer window is currently open editing <paramref name="type"/> (so auto-sync won't clobber the in-progress edits).</summary>
        public static bool IsEditingType(System.Type type)
        {
            if (type == null) return false;
            for (int i = 0; i < _openDesigners.Count; i++)
            {
                var window = _openDesigners[i];
                if (window != null && window._clonedLayoutAsset != null && window.ResolveTargetType() == type)
                    return true;
            }
            return false;
        }

        /// <summary>
        /// Re-runs the script catch-up on every open designer window editing <paramref name="type"/>. This is
        /// the deferred-removal re-arm's route while a designer holds the type: with the inspectors' auto-sync
        /// suppressed (IsEditingType), the windows own keeping BOTH their clone and the registered layout in
        /// step with the code — the catch-up does exactly that, and is a strict no-op when already in sync.
        /// </summary>
        // Deliberately still on the full scan rather than _openDesigners: this runs on a re-arm, not on the
        // inspector's rebuild path, so it has nothing to gain — and keeping the broadest possible reach for
        // the catch-up is worth more here than the microseconds.
        internal static void RearmCloneReconcile(System.Type type)
        {
            if (type == null) return;
            foreach (var window in Resources.FindObjectsOfTypeAll<SasquatchLayoutDesignerWindow>())
            {
                if (window != null && window._clonedLayoutAsset != null && window.ResolveTargetType() == type)
                    window.ReconcileCloneWithScript();
            }
        }

        /// <summary>
        /// A live-inspector CONTENT edit just landed on the REGISTERED layout for <paramref name="type"/> —
        /// a quick-edit popup commit, a colour-palette assign, a button relink. The mirror image of
        /// <see cref="RearmCloneReconcile"/>: that keeps an open clone in step with the SCRIPT, this keeps it
        /// in step with the live inspector.
        ///
        /// Any designer window holding that type is working on a clone taken BEFORE the edit, and its Save
        /// writes that clone's <c>Root</c> wholesale, rescuing only resize-class fields via
        /// <c>MergeResizeFields</c> — so without this the edit is silently destroyed. Three routes reach that
        /// Save and none of them looks dangerous: the Save button, window close / editor quit via
        /// <c>SaveChanges()</c>, and — sharpest — the quick-edit popup's OWN "Open in Designer" footer, which
        /// used to route through <c>PromptSaveIfDirty</c> and offer a dialog whose "Save" button was what
        /// lost the edit. (That route is now closed at the other end too: <c>LoadTypeLayout</c> early-outs
        /// when the window already holds this exact type.)
        ///
        /// Deliberately NOT wired to resize persists. `MergeResizeFields` already carries those into the
        /// designer's save, and adopting on every drag tick would fight it and churn the canvas.
        /// </summary>
        /// <param name="mutatedNodePath">Index path of the node the live edit touched, when the caller knows
        /// it. Only consulted for a DIRTY clone, where a wholesale adopt would destroy the user's own
        /// in-progress work; a clean clone always takes the registered layout entire.</param>
        /// <summary>
        /// An EXTERNAL change replaced layouts on disk (a version-control pull or revert, a hand-edited asset,
        /// a Restore Layouts Backup). Every open designer is holding a CLONE taken before that change, and its
        /// next Save writes that clone wholesale — so without this the external change is silently reverted, and
        /// the most painful case is the product's own restore button undoing itself.
        /// <para>Routes through the same <see cref="AdoptLiveEditIntoClone"/> policy as an in-process live edit:
        /// a CLEAN clone (the common case here — the user just pulled, they were not mid-edit) re-clones the
        /// registered layout entire; a DIRTY clone keeps the user's in-progress work rather than throwing it
        /// away. Passing no node path means a dirty clone deliberately adopts nothing: we cannot know which
        /// node an external rewrite touched, and guessing would be worse than leaving their work alone.</para>
        /// </summary>
        internal static void AdoptExternalLayoutChange(System.Type type)
        {
            if (type != null) { AdoptLiveLayoutEdit(type); return; }

            // Null type = "everything changed" (a backup restore). Re-adopt each open designer's own target.
            foreach (var window in Resources.FindObjectsOfTypeAll<SasquatchLayoutDesignerWindow>())
            {
                if (window == null || window._clonedLayoutAsset == null) continue;
                if (window._presetMode || !string.IsNullOrEmpty(window._showcaseOverrideKey)) continue;
                var target = window.ResolveTargetType();
                if (target != null) window.AdoptLiveEditIntoClone(target, null);
            }
        }

        internal static void AdoptLiveLayoutEdit(System.Type type, List<int> mutatedNodePath = null)
        {
            if (type == null) return;
            foreach (var window in Resources.FindObjectsOfTypeAll<SasquatchLayoutDesignerWindow>())
            {
                if (window == null || window._clonedLayoutAsset == null) continue;
                // Preset and Showcase sessions never persist to the inspector registry, so a live edit to a
                // registered layout is none of their business.
                if (window._presetMode || !string.IsNullOrEmpty(window._showcaseOverrideKey)) continue;
                if (window.ResolveTargetType() != type) continue;
                window.AdoptLiveEditIntoClone(type, mutatedNodePath);
            }
        }

        private void AdoptLiveEditIntoClone(System.Type type, List<int> mutatedNodePath)
        {
            if (!LayoutRegistry.TryGet(type, out var registered) || registered?.Root == null) return;
            // Under Auto-Save the clone's graph IS the registered graph, so the edit is already here.
            if (ReferenceEquals(registered.Root, _clonedLayoutAsset.Root)) return;

            if (!_isDirty)
            {
                // Nothing of the user's is at stake — take the registered layout entire, exactly as
                // re-opening the window on this type would.
                var nodeState = SnapshotNodeState(_clonedLayoutAsset.Root);
                var stale = _clonedLayoutAsset;
                AdoptWorkingClone(Instantiate(registered));
                ReleaseClone(stale);
                RestoreNodeState(nodeState, _clonedLayoutAsset.Root);
                if (_selectedNode == null) SetPrimarySelection(_clonedLayoutAsset.Root);
                _designerResizedSinceClone = false;
                SnapshotFieldsAtCloneTime();
                RefreshAll();
                return;
            }

            // The clone carries unsaved designer work, so a wholesale adopt would destroy the user's edits
            // to rescue somebody else's. Graft only the node the live edit touched — last write wins on THAT
            // node, and every other unsaved designer edit survives. With no path we cannot be that precise,
            // so we leave the clone alone rather than guess.
            if (mutatedNodePath == null || mutatedNodePath.Count == 0) return;

            var live = LocateNodeByIndexPath(mutatedNodePath, registered.Root);
            var mine = LocateNodeByIndexPath(mutatedNodePath, _clonedLayoutAsset.Root);
            if (live == null || mine == null || live.GetType() != mine.GetType()) return;

            var parent = FindParent(mine, _clonedLayoutAsset.Root);
            if (parent?.Children == null) return;
            int at = parent.Children.IndexOf(mine);
            if (at < 0) return;

            Undo.RecordObject(_clonedLayoutAsset, "Adopt Live Inspector Edit");
            var grafted = SnapshotNodeState(_clonedLayoutAsset.Root);
            parent.Children[at] = LayoutPresetApplier.DeepCloneNode(live);
            RestoreNodeState(grafted, _clonedLayoutAsset.Root);
            RefreshAll();
        }

        private void SaveActiveAsset()
        {
            if (_presetMode)
            {
                // Preset editor: flush the active target (type category or widget kind) + the preset asset to disk.
                if (_presetTarget != null)
                {
                    SyncCurrentPreset();
                    EditorUtility.SetDirty(_presetTarget);
                    AssetDatabase.SaveAssets();
                    ClearPresetDirty();
                }
                return;
            }

            if (_clonedLayoutAsset == null) return;

            // Showcase Sandbox session: persist per-page (EditorPrefs) instead of the shared inspector registry,
            // so the edit sticks for THIS page across restarts and never affects real inspectors. ToJson snapshots
            // the working tree, so passing the live Root is safe.
            if (!string.IsNullOrEmpty(_showcaseOverrideKey))
            {
                ShowcaseOverrides.Save(_showcaseOverrideKey, _clonedLayoutAsset.Root);
                _isDirty = false;
                UpdateSaveButtonText();
                return;
            }

            // Prefer the rename-proof GUID, fall back to the type-name string.
            System.Type targetType = ResolveTargetType();
            if (targetType == null)
            {
                Debug.LogWarning($"[Sasquatch Inspector] Cannot save: target could not be resolved (guid '{_clonedLayoutAsset.ScriptGuid}', type '{_clonedLayoutAsset.TargetTypeName}').");
                return;
            }

            // Preserve resize values (text-box height, table column width) edited in the REAL inspector
            // since this clone was made — the clone is a snapshot and would otherwise overwrite them on save.
            // Skip when the designer itself resized this session (then the clone's values are authoritative).
            if (!_designerResizedSinceClone && LayoutRegistry.TryGet(targetType, out var registeredLayout)
                && registeredLayout != null && registeredLayout.Root != null)
            {
                MergeResizeFields(registeredLayout.Root, _clonedLayoutAsset.Root);
            }

            // Snapshot the FULL selection (primary + multi-selection) as positional paths before we re-clone/
            // save, so it can be re-pointed onto the new tree below. Saving with several nodes selected must
            // leave them ALL selected — capturing only the primary collapsed a multi-edit session on every save.
            var selectionSnapshot = SnapshotNodeState(_clonedLayoutAsset.Root);

            string assetPath = _layoutAsset != null ? AssetDatabase.GetAssetPath(_layoutAsset) : null;
            bool isStandalone = !string.IsNullOrEmpty(assetPath) && assetPath != SasquatchPaths.DatabasePath;

            if (isStandalone)
            {
                // Complete-object undo, not RecordObject: RecordObject's flush-time DIFF of a [SerializeReference]
                // graph asset stalls every element detach while pending (see LayoutRegistry.Save for the measurement).
                Undo.RegisterCompleteObjectUndo(_layoutAsset, "Save Layout Asset Changes");
                _layoutAsset.ScriptGuid = _clonedLayoutAsset.ScriptGuid;
                _layoutAsset.TargetTypeName = _clonedLayoutAsset.TargetTypeName;
                _layoutAsset.Root = _clonedLayoutAsset.Root;
                // Write BOTH ledger lists (paths + parallel field types) exactly as LayoutRegistry.Save does, so a
                // user-opened standalone asset stays parity-consistent with the primary per-type store.
                LayoutRegistry.WriteLedger(_layoutAsset, targetType, BuildSaveLedger(targetType));
                _layoutAsset.ApplyToSubclasses = _clonedLayoutAsset.ApplyToSubclasses;

                // Stamps the schema version and writes the graph plain or packed per the Compress Layout Assets
                // setting (the same helper every registry persist site uses). Suppress the postprocessor's global
                // ForceRebuild for this write — the standalone branch does its own targeted RefreshInspectorsForType
                // at the end (LayoutRegistry.Save does the same for the type-driven branch).
                bool prevSuppress = SasquatchAssetPostprocessor.SuppressLayoutForceRebuild;
                SasquatchAssetPostprocessor.SuppressLayoutForceRebuild = true;
                try
                {
                    LayoutGraphStorage.SaveLayoutAsset(_layoutAsset);
                    AssetDatabase.SaveAssets();
                }
                finally { SasquatchAssetPostprocessor.SuppressLayoutForceRebuild = prevSuppress; }

                // Close any caller-left RecordObject snapshot before RefreshAll below tears down the canvas —
                // an open RecordObject snapshot of a [SerializeReference] asset makes every element detach pay
                // its diff (see LayoutRegistry.Save). No-op when nothing is pending.
                Undo.FlushUndoRecordObjects();

                _isDirty = false;
                UpdateSaveButtonText();

                // Re-clone after save to avoid aliasing in-memory changes onto the disk asset. Under Auto-Save
                // we do NOT re-clone: re-cloning on every keystroke orphans the property-panel field closures
                // (they captured the now-replaced node), so edits would land on a dead node and appear not to
                // "take". Skipping it keeps those closures valid.
                // Instantiate FIRST, then release the outgoing clone: if the clone throws we must not have
                // already destroyed the working copy. The old instance used to be simply dropped — a leaked
                // ScriptableObject plus its whole undo history, every manual save.
                if (!_autoSave)
                {
                    var stale = _clonedLayoutAsset;
                    AdoptWorkingClone(Instantiate(_layoutAsset));
                    ReleaseClone(stale);
                }
            }
            else
            {
                // Type-driven save: route through LayoutRegistry, which writes this type's own version-control-
                // friendly per-type layout asset (creating it under User Data/Layouts if needed).
                LayoutRegistry.Save(targetType, _clonedLayoutAsset.Root, BuildSaveLedger(targetType),
                    _clonedLayoutAsset.ApplyToSubclasses);

                _isDirty = false;
                UpdateSaveButtonText();

                // Re-populate the cloned/transient asset from the registry. Skipped under Auto-Save (see note above)
                // so the live property-panel field closures aren't orphaned by a per-keystroke re-clone.
                if (!_autoSave && LayoutRegistry.TryGet(targetType, out var savedAsset))
                {
                    _layoutAsset = null; // registry-managed: the layout lives in its per-type asset, not a hand-opened one
                    var stale = _clonedLayoutAsset;
                    AdoptWorkingClone(Instantiate(savedAsset));
                    ReleaseClone(stale); // same leak + stale-undo history as the standalone branch above
                }
            }

            // After a re-clone (manual save only) every selection ref is stale — re-point the WHOLE selection
            // (primary + multi) onto the new tree via the shared snapshot, then rebind the designer's panels to
            // it (their field closures captured the old nodes). Restoring only the primary used to collapse a
            // multi-edit session to a single node on every save. Safe here because a manual save isn't a
            // mid-typing interaction. Under Auto-Save we didn't re-clone, so every ref/closure is still valid —
            // leave them untouched.
            if (!_autoSave)
            {
                RestoreNodeState(selectionSnapshot, _clonedLayoutAsset.Root);
                // Pre-existing fallback: an unresolved primary lands on the root so the panel always has a
                // selection to show.
                if (_selectedNode == null)
                {
                    _selectedNode = _clonedLayoutAsset.Root;
                    _selectionAnchor = _selectedNode;
                }
                RefreshAll();
            }
            // Fresh clone after save → clear the designer-resized flag and re-baseline the field snapshot
            // for the next editing round.
            _designerResizedSinceClone = false;
            SnapshotFieldsAtCloneTime();

            // Refresh live inspectors so the saved layout shows immediately. The type-driven branch already did a
            // TARGETED refresh inside LayoutRegistry.Save (RefreshInspectorsForType), so refreshing again here would
            // be the redundant SECOND pass per designer save — only the standalone-asset branch, which writes the
            // file directly and never routes through LayoutRegistry.Save, still needs it. Targeted so unrelated
            // components/previews don't churn; covers both the fallback and displacement render paths.
            if (isStandalone)
                SasquatchEditorRegistrar.RefreshInspectorsForType(targetType);
        }

        // Copies the live-editable resize fields (text-box height, table column width) from `source` onto
        // structurally-matching nodes in `dest`. Used on save to keep inspector-side resizes. Best-effort:
        // only copies where the tree shapes line up (same node type + child counts), so it never lands a value
        // on the wrong node when the layouts have diverged structurally.
        private static void MergeResizeFields(LayoutNode source, LayoutNode dest)
        {
            if (source == null || dest == null || source.GetType() != dest.GetType()) return;

            // Identity guard — the pairing is BY INDEX, and index pairing is only trustworthy when the two
            // nodes really are the same authored node. Structural edits only happen in the designer, so
            // wherever identity diverges the clone is authoritative and skipping the subtree is exactly
            // right. Guards used to exist for three node kinds; SameMergeIdentity covers all thirteen.
            if (!SameMergeIdentity(source, dest)) return;

            // ColumnWeight / RowHeight live on the base node (Columns-container children AND Rows-container
            // children of any type, plus table columns), so copy them for every node — not just bindings.
            dest.ColumnWeight = source.ColumnWeight;
            dest.RowHeight = source.RowHeight;

            // Style.width / Style.height are live-draggable too (Allow Width/Height Adjust handles), so carry
            // just those two over without clobbering any other designer-side Style edits.
            var ds = dest.Style;
            ds.width = source.Style.width;
            ds.height = source.Style.height;
            dest.Style = ds;

            if (source is BindingNode sb && dest is BindingNode db)
            {
                db.TextBoxHeight = sb.TextBoxHeight;
            }
            else if (source is ContainerNode sc && dest is ContainerNode dc)
            {
                // Grid per-track sizes are live-editable in the inspector too — carry them over.
                if (sc.GridColumnWeights != null) dc.GridColumnWeights = new System.Collections.Generic.List<float>(sc.GridColumnWeights);
                if (sc.GridRowHeights != null) dc.GridRowHeights = new System.Collections.Generic.List<float>(sc.GridRowHeights);

                if (sc.Children != null && dc.Children != null && sc.Children.Count == dc.Children.Count)
                {
                    for (int i = 0; i < sc.Children.Count; i++)
                        MergeResizeFields(sc.Children[i], dc.Children[i]);
                }
            }
            else if (source is CollectionNode scol && dest is CollectionNode dcol)
            {
                MergeResizeFields(scol.ItemLayout, dcol.ItemLayout);
            }
        }

        /// <summary>
        /// Is this the same authored node? The CLR type is NOT identity — every button is a
        /// <c>ButtonNode</c>, every container kind (Circle Frame, Columns, Grid, Card…) is the same
        /// <c>ContainerNode</c> — so the save-time merge, which pairs the registered layout against the
        /// designer's clone BY INDEX, needs a real key or a designer reorder cross-copies sizes: the
        /// "circle resized + columns cut in half on Save" bug, and its sharper leaf twin, two Buttons in a
        /// Columns container swapping their divider-dragged widths.
        ///
        /// Cross-copying is worse than a symmetric swap: <c>StyleApplier</c> applies an overridden width with
        /// no <c>MakeWidthResizable</c> gate, while "Return to Default Size" IS gated on that flag — so a
        /// width landed on a non-resizable sibling renders and cannot be cleared from the inspector.
        ///
        /// Answering false is the SAFE direction and matches the merge's standing policy: structural edits
        /// only happen in the designer, so where identity diverges the clone is authoritative and simply
        /// keeps its own values. Guards previously existed for exactly three kinds; all thirteen are listed
        /// here, and a kind with no usable discriminator says so out loud rather than falling through
        /// silently. A NEW kind falls to the default and refuses the merge until someone gives it a key —
        /// closing the gap `memory/designer-save-merge-resize-authority.md` warned about.
        /// </summary>
        private static bool SameMergeIdentity(LayoutNode source, LayoutNode dest)
        {
            switch (source)
            {
                case BindingNode s when dest is BindingNode d:
                    return s.PropertyPath == d.PropertyPath;

                case CollectionNode s when dest is CollectionNode d:
                    return s.PropertyPath == d.PropertyPath;

                // Child count stays in the key: a container's resize payload includes the per-track lists,
                // which only line up when the track count does. Title/TabLabel/PropertyPath separate two
                // same-Type containers that the old count-only heuristic happily cross-copied.
                case ContainerNode s when dest is ContainerNode d:
                    return s.Type == d.Type
                        && (s.Children?.Count ?? 0) == (d.Children?.Count ?? 0)
                        && s.Title == d.Title
                        && s.TabLabel == d.TabLabel
                        && s.PropertyPath == d.PropertyPath;

                case ButtonNode s when dest is ButtonNode d:
                    return s.MethodName == d.MethodName && s.ButtonText == d.ButtonText;

                case PropertyNode s when dest is PropertyNode d:
                    return s.PropertyName == d.PropertyName;

                case TextBlockNode s when dest is TextBlockNode d:
                    return s.Text == d.Text;

                case HelpBoxNode s when dest is HelpBoxNode d:
                    return s.Message == d.Message && s.MessageType == d.MessageType;

                case LabeledDividerNode s when dest is LabeledDividerNode d:
                    return s.Title == d.Title;

                case ImageBannerNode s when dest is ImageBannerNode d:
                    return s.TextureGuid == d.TextureGuid;

                case EmbeddedEditorNode s when dest is EmbeddedEditorNode d:
                    return s.SliceMethodName == d.SliceMethodName;

                // An attribute-owned spacer is keyed by the field it mirrors. A hand-authored one carries no
                // identity at all, and neither does a plain Script Header — there is only ever one of those
                // in a layout. Both pair by index, which is harmless: nothing distinguishes them to swap.
                case SpaceNode s when dest is SpaceNode d:
                    return s.OwnerFieldPath == d.OwnerFieldPath;

                case ScriptHeaderNode _ when dest is ScriptHeaderNode _:
                    return true;
#if SASQ_CUSTOM_WIDGET
                case CustomWidgetNode s when dest is CustomWidgetNode d:
                    return s.CustomWidgetGuid == d.CustomWidgetGuid;
#endif
            }

            // A kind this switch has never heard of. New node kinds land here, and refusing the merge is the
            // conservative answer: the clone keeps its own resize values until someone gives the kind a key.
            return false;
        }

        private LayoutNode FindNodeByPropertyPath(LayoutNode node, string basePath, string targetPath)
        {
            if (node == null) return null;
            if (node is BindingNode bn && !string.IsNullOrEmpty(bn.PropertyPath))
            {
                string resolvedPath = string.IsNullOrEmpty(basePath) ? bn.PropertyPath : $"{basePath}.{bn.PropertyPath}";
                if (resolvedPath == targetPath) return bn;
            }
            else if (node is CollectionNode col && !string.IsNullOrEmpty(col.PropertyPath))
            {
                string resolvedPath = string.IsNullOrEmpty(basePath) ? col.PropertyPath : $"{basePath}.{col.PropertyPath}";
                if (resolvedPath == targetPath) return col;
                if (col.ItemLayout != null)
                {
                    var found = FindNodeByPropertyPath(col.ItemLayout, resolvedPath, targetPath);
                    if (found != null) return found;
                }
            }
            else if (node is ContainerNode container)
            {
                if (!string.IsNullOrEmpty(container.PropertyPath))
                {
                    string resolvedPath = string.IsNullOrEmpty(basePath) ? container.PropertyPath : $"{basePath}.{container.PropertyPath}";
                    if (resolvedPath == targetPath) return container;
                }

                string nextBasePath = basePath;
                if (!string.IsNullOrEmpty(container.PropertyPath))
                {
                    nextBasePath = string.IsNullOrEmpty(basePath) ? container.PropertyPath : $"{basePath}.{container.PropertyPath}";
                }

                if (container.Children != null)
                {
                    foreach (var child in container.Children)
                    {
                        var found = FindNodeByPropertyPath(child, nextBasePath, targetPath);
                        if (found != null) return found;
                    }
                }
            }
            return null;
        }

        private void ExpandAncestorsOf(LayoutNode node)
        {
            if (node == null || _clonedLayoutAsset == null || _clonedLayoutAsset.Root == null) return;
            ExpandAncestorsRecursive(_clonedLayoutAsset.Root, node);
        }

        private bool ExpandAncestorsRecursive(LayoutNode current, LayoutNode target)
        {
            if (current == null) return false;
            if (current == target) return true;

            bool isAncestor = false;
            if (current is ContainerNode container)
            {
                if (container.Children != null)
                {
                    foreach (var child in container.Children)
                    {
                        if (ExpandAncestorsRecursive(child, target))
                        {
                            isAncestor = true;
                        }
                    }
                }
            }
            else if (current is CollectionNode col && col.ItemLayout != null)
            {
                if (ExpandAncestorsRecursive(col.ItemLayout, target))
                {
                    isAncestor = true;
                }
            }

            if (isAncestor)
            {
                _collapsedNodes.Remove(current);
            }

            return isAncestor;
        }

        private void SelectAndPingNode(LayoutNode node)
        {
            if (node == null) return;
            ExpandAncestorsOf(node);
            _disableScrollPreservation = true;
            try
            {
                SelectSingle(node);
            }
            finally
            {
                _disableScrollPreservation = false;
            }
            PingNodeInPanels(node);
        }

        private void PingBinding(string propertyPath)
        {
            if (_clonedLayoutAsset == null || _clonedLayoutAsset.Root == null) return;
            var node = FindNodeByPropertyPath(_clonedLayoutAsset.Root, "", propertyPath);
            if (node != null)
            {
                SelectAndPingNode(node);
            }
        }

        // Pings the ELEMENT TEMPLATE of the collection at collectionPath — the Bindings tab's "Element"
        // token once it's in the layout. It cannot go through PingBinding: the template's own PropertyPath
        // is empty, so there is no path to search for. Find the collection, then its template.
        private void PingElementTemplate(string collectionPath)
        {
            if (_clonedLayoutAsset == null || _clonedLayoutAsset.Root == null) return;
            var collection = FindNodeByPropertyPath(_clonedLayoutAsset.Root, "", collectionPath) as CollectionNode;
            var template = UnboundFieldSync.FindElementTemplate(collection);
            if (template != null) SelectAndPingNode(template);
        }

        // Pings the first PropertyNode in the layout matching propertyName (used by the Bindings tab's
        // "C# Properties" rows: a placed property pings its node rather than re-adding it).
        private void PingProperty(string propertyName)
        {
            if (_clonedLayoutAsset == null || _clonedLayoutAsset.Root == null || string.IsNullOrEmpty(propertyName)) return;
            var node = FindPropertyNode(_clonedLayoutAsset.Root, propertyName);
            if (node != null) SelectAndPingNode(node);
        }

        private static PropertyNode FindPropertyNode(LayoutNode node, string propertyName)
        {
            if (node == null) return null;
            if (node is PropertyNode pn && pn.PropertyName == propertyName) return pn;
            if (node is ContainerNode c && c.Children != null)
            {
                foreach (var child in c.Children)
                {
                    var found = FindPropertyNode(child, propertyName);
                    if (found != null) return found;
                }
            }
            else if (node is CollectionNode col && col.ItemLayout != null)
            {
                return FindPropertyNode(col.ItemLayout, propertyName);
            }
            return null;
        }

        private List<int> GetNodeIndexPath(LayoutNode node, LayoutNode root)
        {
            var path = new List<int>();
            if (FindNodeIndexPathRecursive(node, root, path))
            {
                return path;
            }
            return null;
        }

        private bool FindNodeIndexPathRecursive(LayoutNode target, LayoutNode current, List<int> path)
        {
            if (current == target) return true;

            if (current is ContainerNode container && container.Children != null)
            {
                for (int i = 0; i < container.Children.Count; i++)
                {
                    path.Add(i);
                    if (FindNodeIndexPathRecursive(target, container.Children[i], path)) return true;
                    path.RemoveAt(path.Count - 1);
                }
            }
            else if (current is CollectionNode col && col.ItemLayout != null)
            {
                path.Add(-1); // -1 indicates ItemLayout
                if (FindNodeIndexPathRecursive(target, col.ItemLayout, path)) return true;
                path.RemoveAt(path.Count - 1);
            }
            // A dictionary's KEY / VALUE cell templates. Held by REFERENCE on the binding, exactly as a
            // collection holds its ItemLayout, so they get their own negative steps rather than an index.
            else if (current is BindingNode dictOwner)
            {
                if (dictOwner.DictionaryKeyTemplate != null)
                {
                    path.Add(LayoutFieldTypeResolver.DictionaryKeyStep);
                    if (FindNodeIndexPathRecursive(target, dictOwner.DictionaryKeyTemplate, path)) return true;
                    path.RemoveAt(path.Count - 1);
                }
                if (dictOwner.DictionaryValueTemplate != null)
                {
                    path.Add(LayoutFieldTypeResolver.DictionaryValueStep);
                    if (FindNodeIndexPathRecursive(target, dictOwner.DictionaryValueTemplate, path)) return true;
                    path.RemoveAt(path.Count - 1);
                }
            }
            return false;
        }

        private LayoutNode LocateNodeByIndexPath(List<int> path, LayoutNode root)
        {
            if (path == null || root == null) return null;
            LayoutNode current = root;
            foreach (int index in path)
            {
                if (index == LayoutFieldTypeResolver.DictionaryKeyStep
                    || index == LayoutFieldTypeResolver.DictionaryValueStep)
                {
                    if (!(current is BindingNode dictOwner)) return null;
                    current = index == LayoutFieldTypeResolver.DictionaryKeyStep
                        ? dictOwner.DictionaryKeyTemplate
                        : dictOwner.DictionaryValueTemplate;
                    if (current == null) return null;
                }
                else if (index == -1)
                {
                    if (current is CollectionNode col)
                    {
                        current = col.ItemLayout;
                    }
                    else
                    {
                        return null;
                    }
                }
                else
                {
                    if (current is ContainerNode container && container.Children != null && index >= 0 && index < container.Children.Count)
                    {
                        current = container.Children[index];
                    }
                    else
                    {
                        return null;
                    }
                }
            }
            return current;
        }

        // Remove the current type's layout so its inspector reverts to Unity's stock inspector.
        private void RevertToDefault()
        {
            var type = ResolveTargetType();
            if (type == null)
            {
                EditorUtility.DisplayDialog("Revert to Default",
                    "No target type is associated with this layout yet.", "OK");
                return;
            }

            bool confirmed = EditorUtility.DisplayDialog(
                "Revert to Default",
                $"Remove the Sasquatch layout for {type.Name}?\n\nIts inspector will revert to Unity's default. This can't be undone.",
                "Revert", "Cancel");
            if (!confirmed) return;

            LayoutRegistry.Remove(type);

            // Re-initialise the in-window layout to a FRESH EMPTY layout for the SAME type (the "no saved layout
            // yet" state) rather than destroying it. This keeps the designer pointed at the type — so
            // ResolveTargetType() still resolves and Smart Attribute Import can re-add everything — while the
            // canvas correctly reflects the removal (just the script header, no fields). Preserve the type's
            // identity (ScriptGuid + TargetTypeName) from the asset we're replacing.
            string keepGuid = _clonedLayoutAsset != null ? _clonedLayoutAsset.ScriptGuid : null;
            string keepTypeName = _clonedLayoutAsset != null ? _clonedLayoutAsset.TargetTypeName : null;
            if (_clonedLayoutAsset != null)
            {
                var stale = _clonedLayoutAsset;
                _clonedLayoutAsset = null;
                ReleaseClone(stale);
            }
            // A fresh clone means the DESIGNER has not resized anything in it yet, so Save must again defer
            // to live-inspector resizes. Leaving a stale `true` here suppressed the merge and clobbered the
            // NEXT type's real-inspector sizes.
            _designerResizedSinceClone = false;
            AdoptWorkingClone(CreateInstance<InspectorLayoutAsset>());
            _clonedLayoutAsset.Root = NewRootWithScriptHeader();
            _clonedLayoutAsset.TargetTypeName = !string.IsNullOrEmpty(keepTypeName) ? keepTypeName : type.AssemblyQualifiedName;
            if (string.IsNullOrEmpty(keepGuid))
            {
                // Instance shortcut only when the test target IS the edited type (ancestor authoring may
                // preview with a subclass instance — its GUID must not key the ancestor's layout).
                if (_testTarget != null && _testTarget.GetType() == type) ScriptGuidUtility.TryGetGuid(_testTarget, out keepGuid);
                if (string.IsNullOrEmpty(keepGuid)) ScriptGuidUtility.TryGetGuid(type, out keepGuid);
            }
            _clonedLayoutAsset.ScriptGuid = keepGuid;
            _layoutAsset = null;
            _isDirty = false;
            SnapshotFieldsAtCloneTime();

            // Seed the ledger, exactly as the other fresh-clone branch does (see LoadTypeLayout). Revert's whole
            // point is an EMPTY canvas, and a fresh asset's syncedFieldPaths is empty too — which is precisely the
            // "drained layout" signature UnboundFieldSync.ComputeDiff treats as never-synced, so it would mass-
            // insert every visible field back in. Without this, the next script recompile fires
            // ReconcileCloneWithScript (this clone is [SerializeField], and ScriptGuid/TargetTypeName are
            // deliberately preserved above so ResolveTargetType still resolves) and silently undoes the revert —
            // re-creating the layout asset outright when Auto-Save is on.
            UnboundFieldSync.SeedCloneLedgerWithCurrentFields(type, _clonedLayoutAsset);
            SetPrimarySelection(_clonedLayoutAsset.Root);
            _activeLeftTab = 2; // land on Tools (where "import everything" lives), matching the fresh-script case
            UpdateSaveButtonText();
            RefreshAll();

            // Rebuild live inspectors so the reverted object shows Unity's default immediately. Use the SAME full
            // tracker rebuild that "Remove Sasquatch Layout" uses (SasquatchContextMenu.Remove) — NOT the targeted
            // in-place RefreshInspectorsForType. When Revert is triggered from THIS designer window's own button, the
            // targeted in-place rebuild (a synchronous RebuildInspectorGUI run inside the button's UI Toolkit click
            // dispatch) left the reverted component's editor torn down but never recreated — an empty body under the
            // header — and it stayed wiped until the tracker was rebuilt some other way (e.g. closing and reopening
            // the designer). ForceRebuild is DEFERRED: it recreates every editor on the next inspector repaint,
            // outside the current event dispatch, which is exactly why the context-menu path is reliable. Revert is a
            // rare, deliberate action, so a full rebuild here is fine (unlike the hot post-SAVE path, which stays
            // targeted for performance). LayoutRegistry.Remove above already dropped this type's entry, so the
            // rebuilt editors resolve to Unity's default inspector. The designer stays open and pointed at the type
            // (its clone was just re-seeded to an empty layout for this type), so focus on the script is preserved.
            ActiveEditorTracker.sharedTracker.ForceRebuild();

            // Refresh this window's conflict notice for the reverted type (shows the informational notice again if
            // a competing [CustomEditor] exists, or nothing).
            UpdateConflictWarning(type);
        }

        // Called when a resize handle in the designer's PREVIEW is dragged (text box / table column). Marks
        // that the designer itself resized this session, so Save keeps the clone's values rather than merging
        // in the registered layout's (which would otherwise win — see SaveActiveAsset's merge for #1).
        private void OnLayoutResizedFromPreview()
        {
            ClaimResizeAuthority();
            OnModification();
        }

        // skipPreviewRebuild: the caller guarantees the canvas already reflects the model exactly (a drag
        // burst reconciled tick-by-tick via RebuildNodeInPlace) — run the save/dirty bookkeeping but leave
        // the canvas alone, so releasing a drag doesn't replay geometry-settling widgets (the release jerk).
        private void OnModification(bool skipPreviewRebuild = false)
        {
            if (_presetMode)
            {
                // Preset editor: persist the edited template (type category or widget kind) into the asset, then
                // re-render the live preview. The edit is in the asset but not yet on DISK, so this branch must
                // still mark preset-dirty — returning early would leave Save looking clean however much changed.
                SyncCurrentPreset();
                MarkPresetDirty();
                SchedulePreviewRebuild();
                return;
            }

            // Fan the edit just made on the primary out to the rest of a multi-selection. FIRST, so the
            // followers' writes land inside the caller's still-open Undo.RecordObject step and are already in
            // the tree when the auto-save below writes it. A no-op unless the top-tier multi-edit panel is up.
            MirrorMultiEditDelta();

            UpdateDataTokenCount();
            if (_autoSave)
            {
                SaveActiveAsset();
            }
            else
            {
                _isDirty = true;
                UpdateSaveButtonText();
            }
            // Re-bind the canvas to property/animation edits in both design and live preview.
            if (!skipPreviewRebuild) SchedulePreviewRebuild();
        }

        // Coalesce rapid edits (e.g. per-keystroke text changes) into a single preview rebuild so the
        // canvas re-binds without churning on every keystroke. Non-text edits feel instant at this delay.
        private void SchedulePreviewRebuild()
        {
            if (rootVisualElement == null)
            {
                RefreshPreview();
                return;
            }
            _pendingPreviewRebuild?.Pause();
            var item = rootVisualElement.schedule.Execute(RefreshPreview);
            item.ExecuteLater(PreviewRebuildDebounceMs);
            _pendingPreviewRebuild = item;
        }

        // Per-keystroke commits are what made the designer's text boxes laggy to type in: EVERY keystroke
        // snapshotted the whole asset for undo, saved the asset to disk (auto-save), and force-rebuilt the
        // canvas (and for some fields the hierarchy/tokens panels) synchronously. This coalesces a typing
        // burst into: ONE undo record (at burst start — the whole burst reverts together, like Unity's own
        // text fields), live node writes per keystroke (cheap), and one OnModification (save/dirty + debounced
        // preview rebuild) once the keystrokes pause. Fields whose text feeds the hierarchy tree or the
        // Bindings panel pass refreshHierarchy/refreshTokens so those rebuilds ride the SAME deferred commit.
        // The dirty flag is still raised immediately so the unsaved-changes close guard can never miss an
        // in-burst edit; blur and window teardown flush the commit early.
        // liveRebuild (opt-in): after each keystroke's model write, rebuild JUST the selected node's canvas
        // element in place (LiveRebuildSelectedNode) so text the user types — and its appearance/disappearance
        // when the string goes empty↔non-empty — shows on the canvas immediately, while the undo/save still
        // ride the debounce. This generalizes the Script Header "best of both worlds": that field can use a
        // cheap targeted text poke because its title label is always present, but fields whose canvas element
        // only exists while non-empty (header/label/title/message/…) need the conditional builder re-run, so
        // they rebuild the node instead. Guarded like the commit below (same node, not preset mode).
        private void HandleDebouncedTextEdit(string undoName, Action apply,
            bool refreshHierarchy = false, bool refreshTokens = false, bool liveRebuild = false)
        {
            if (!_textEditBurstActive)
            {
                Undo.RecordObject(_clonedLayoutAsset, undoName);
                _textEditBurstActive = true;
                _textEditBurstLiveReconciled = true; // optimistic until a keystroke fails to reconcile exactly
                _textEditBurstNode = _selectedNode;
            }
            apply();

            // Per-KEYSTROKE fan-out, for the same reason the value burst fans per tick: a text burst defers
            // OnModification too, so a multi-edit row typed into (a unit suffix, a placeholder) would otherwise
            // leave every follower unchanged until the typing settled. Identity rows are hidden in multi-edit
            // AND blocked by the mirror, so they fan nothing and this stays free on the paths that dominate.
            bool fannedOut = MirrorMultiEditDelta() > 0;

            // Track whether this keystroke left the canvas EXACTLY matching the model, so the commit can skip
            // its own rebuild — same contract (and same reason) as HandleDebouncedValueEdit.
            bool reconciled = liveRebuild && !_presetMode && ReferenceEquals(_selectedNode, _textEditBurstNode)
                              && LiveRebuildSelectedNodes();
            if (!reconciled)
            {
                _textEditBurstLiveReconciled = false;
                if (fannedOut && !liveRebuild) LiveRebuildFollowerNodes();
            }
            if (refreshHierarchy) _textEditNeedsHierarchyRefresh = true;
            if (refreshTokens) _textEditNeedsTokensRefresh = true;
            if (!_autoSave && !_presetMode && !_isDirty)
            {
                _isDirty = true;              // keep hasUnsavedChanges honest while the commit is pending
                UpdateSaveButtonText();
            }
            _pendingTextEditCommit?.Pause();
            var item = rootVisualElement.schedule.Execute(CommitPendingTextEdit);
            item.ExecuteLater(TextEditCommitDebounceMs);
            _pendingTextEditCommit = item;
        }

        // Raises the dirty flag for an edit whose real commit lands on a later settle tick, so the edit survives
        // a panel rebuild that beats the settle. The debounced text/value bursts above inline the same guard;
        // any OTHER deferred-commit site must call this rather than writing `_isDirty = true` raw.
        //
        // The guard is load-bearing in PRESET MODE specifically. A preset window has no layout database to save,
        // and OnModification's preset branch returns without ever clearing `_isDirty` — so a raw write strands
        // the flag for the window's lifetime. The next preset-row click then reaches LoadExplicitLayout's
        // "unsaved layout changes in the database" prompt while the clone is still the OUTGOING preview but the
        // preset target already points at the INCOMING entry, and answering Save writes the outgoing template
        // over the incoming preset — on disk, with no undo record. Preset dirtiness is _presetDirty's job.
        //
        // Skipping UpdateSaveButtonText is the quieter half of the same bug: the Save button keeps its clean
        // face while the window is genuinely dirty.
        private void MarkDirtyBeforeSettle()
        {
            if (!_autoSave && !_presetMode && !_isDirty)
            {
                _isDirty = true;
                UpdateSaveButtonText();
            }
        }

        // Declares that the DESIGNER (not the live inspector) is the authority on this clone's resize-class
        // fields, so Save keeps the clone's values instead of merging the registry's back over them.
        //
        // The resize class is: Style.width, Style.height, ColumnWeight, RowHeight, BindingNode.TextBoxHeight and
        // the grid track lists — the set MergeResizeFields copies. ANY designer-side code path that writes one
        // of them must call this, or the edit silently reverts on Save while every non-size edit beside it
        // sticks. Prefer calling it from the narrowest shared funnel a feature has (e.g. ApplyClipboardTo covers
        // all three style-paste entry points at once) rather than at each leaf call site.
        private void ClaimResizeAuthority() => _designerResizedSinceClone = true;

        // Ends the current typing burst (if any): runs the deferred save/dirty bookkeeping, schedules the
        // debounced preview rebuild, and performs any hierarchy/tokens refresh the burst deferred. Safe to
        // call at any time — a no-op when nothing is pending.
        private void CommitPendingTextEdit()
        {
            _pendingTextEditCommit?.Pause();
            _pendingTextEditCommit = null;
            if (!_textEditBurstActive) return;
            _textEditBurstActive = false;
            bool hierarchy = _textEditNeedsHierarchyRefresh;
            bool tokens = _textEditNeedsTokensRefresh;
            _textEditNeedsHierarchyRefresh = false;
            _textEditNeedsTokensRefresh = false;
            // Every debounced text edit is a Properties-panel row editing the selected node (verified across
            // all call sites), so an exact in-place rebuild of that node reconciles the canvas without the
            // full teardown — same release-jerk rationale as CommitPendingValueEdit. The hierarchy/tokens
            // panel refreshes below are independent of the canvas and still run either way.
            bool sameNode = ReferenceEquals(_selectedNode, _textEditBurstNode);
            _textEditBurstNode = null;
            // When EVERY keystroke of the burst reconciled exactly, the canvas ALREADY matches the model —
            // rebuilding again here only replays the one-frame unresolved-layout flash for no pixel change.
            bool liveReconciled = _textEditBurstLiveReconciled;
            _textEditBurstLiveReconciled = false;
            bool canvasReconciled = !_presetMode && sameNode
                                    && (liveReconciled || LiveRebuildSelectedNodes());
            OnModification(skipPreviewRebuild: canvasReconciled);
            if (hierarchy) RefreshHierarchy();
            if (tokens) RefreshTokens();
        }

        // Flushes the pending text commit when focus leaves a debounced field, so tabbing away / clicking
        // another control re-renders (and saves) immediately instead of waiting out the debounce.
        private void FlushTextEditOnBlur(VisualElement fieldOrRow)
        {
            fieldOrRow.RegisterCallback<FocusOutEvent>(_ => CommitPendingTextEdit(), TrickleDown.TrickleDown);
        }

        // Continuous-control counterpart to HandleDebouncedTextEdit: for sliders, scrubbable number fields and
        // dragged color pickers, whose ValueChanged fires many times per second. Dragging one used to snapshot
        // the whole asset for undo, (auto-)save it, and force a FULL synchronous canvas teardown+rebuild on
        // EVERY tick — that was the designer's slider/color lag. This coalesces a drag into: ONE undo record
        // (at burst start — the whole drag reverts together), the live model write per tick via `apply` (cheap:
        // the field/slider mirror + override chrome), and ONE OnModification (dirty/save + debounced preview
        // rebuild) once the value stops moving. The dirty flag is raised immediately so the unsaved-changes
        // close guard can never miss an in-flight drag; blur/undo/teardown/save flush the commit early.
        // `onCommit` runs once with that same commit for the rare control that must also rebuild a sibling
        // panel (e.g. a widget-option row that changes which options show) — never per tick.
        // liveRebuild (opt-in): after each tick's model write, rebuild JUST the selected node's canvas element in
        // place (LiveRebuildSelectedNode) for instant feedback — used by continuous controls that have no cheap
        // in-place style poke of their own. Controls WITH such a poke leave it false and poke inside `apply`
        // instead (near-free), so this never regresses the already-instant controls to the heavier rebuild path.
        // When EVERY tick of a burst reconciled exactly this way, the commit skips the full-canvas rebuild
        // outright (see CommitPendingValueEdit) — it would repaint identical pixels while replaying widgets
        // whose size settles over several frames, which read as a canvas jerk on mouse release.
        private void HandleDebouncedValueEdit(string undoName, Action apply, Action onCommit = null, bool liveRebuild = false)
        {
            if (!_valueEditBurstActive)
            {
                Undo.RecordObject(_clonedLayoutAsset, undoName);
                _valueEditBurstActive = true;
                _valueEditBurstLiveReconciled = true; // optimistic until a tick fails to reconcile exactly
                _valueEditBurstNode = _selectedNode;
            }
            apply();

            // Multi-edit fans out on EVERY tick, not just at the commit below. A burst defers OnModification
            // until the pointer is released, so mirroring only there left every follower's MODEL untouched for
            // the whole drag — the canvas repaint underneath was faithfully rebuilding them from unchanged
            // values, which read as "only the node I clicked last animates". Fanned first, so the repaint that
            // follows sees the new values rather than trailing them by a tick.
            bool fannedOut = MirrorMultiEditDelta() > 0;

            bool reconciled = liveRebuild && ReferenceEquals(_selectedNode, _valueEditBurstNode)
                              && LiveRebuildSelectedNodes();
            if (!reconciled)
            {
                _valueEditBurstLiveReconciled = false;
                // A poke-based control (liveRebuild:false) pokes the PRIMARY's element only — near-free, and
                // the whole reason those rows don't take the rebuild path. The followers we just wrote to have
                // no poke of their own, so they get the in-place rebuild instead.
                if (fannedOut && !liveRebuild) LiveRebuildFollowerNodes();
            }
            // A later tick in the same drag may carry a different onCommit (e.g. paired slider + field); keep
            // the most recent so the eventual commit runs the caller's freshest follow-up exactly once.
            if (onCommit != null) _pendingValueEditOnCommit = onCommit;
            if (!_autoSave && !_presetMode && !_isDirty)
            {
                _isDirty = true;              // keep hasUnsavedChanges honest while the commit is pending
                UpdateSaveButtonText();
            }
            // No scheduler (window not yet shown / torn down) ⇒ commit synchronously so nothing is lost.
            if (rootVisualElement == null) { CommitPendingValueEdit(); return; }
            _pendingValueEditCommit?.Pause();
            var item = rootVisualElement.schedule.Execute(() => CommitPendingValueEdit(deferWhileDragging: true));
            item.ExecuteLater(PreviewRebuildDebounceMs);
            _pendingValueEditCommit = item;
        }

        // Ends the current drag burst (if any): runs the deferred dirty/save bookkeeping + debounced preview
        // rebuild via OnModification, then the burst's queued follow-up. Safe to call any time — a no-op when
        // nothing is pending. Flushed on blur, undo/redo, teardown and save so an in-flight drag always lands.
        // deferWhileDragging (the SCHEDULED debounce path only): a pause mid-drag must not land the commit's
        // node rebuild under the still-held pointer — a heavy card (particle/VFX preview) visibly snaps when
        // its widget is swapped. Re-check until the pointer is released; explicit flush callers (blur, undo,
        // save, teardown) always commit immediately.
        private void CommitPendingValueEdit(bool deferWhileDragging = false)
        {
            if (deferWhileDragging && _valueEditBurstActive && rootVisualElement != null &&
                rootVisualElement.panel != null &&
                rootVisualElement.panel.GetCapturingElement(PointerId.mousePointerId) != null)
            {
                _pendingValueEditCommit?.Pause();
                var again = rootVisualElement.schedule.Execute(() => CommitPendingValueEdit(deferWhileDragging: true));
                again.ExecuteLater(150);
                _pendingValueEditCommit = again;
                return;
            }
            _pendingValueEditCommit?.Pause();
            _pendingValueEditCommit = null;
            if (!_valueEditBurstActive) return;
            _valueEditBurstActive = false;
            var onCommit = _pendingValueEditOnCommit;
            _pendingValueEditOnCommit = null;
            // If every tick was an exact in-place rebuild the canvas already shows the final model; if the
            // burst used approximate style pokes instead, reconcile the node in place NOW — every debounced
            // value edit is a Properties-panel row editing the selected node, so a successful exact rebuild
            // of that node makes the full-canvas rebuild redundant either way (skipping its teardown is
            // what kills the release jerk). Preset mode is excluded: its canvas derives from the synced
            // preset, not the clone. Falls back to the full rebuild whenever the in-place rebuild can't run
            // (layout root, node not on canvas, rebuild threw).
            bool sameNode = ReferenceEquals(_selectedNode, _valueEditBurstNode);
            _valueEditBurstNode = null;
            bool canvasReconciled = !_presetMode && sameNode
                && (_valueEditBurstLiveReconciled || LiveRebuildSelectedNodes());
            _valueEditBurstLiveReconciled = false;
            OnModification(skipPreviewRebuild: canvasReconciled);
            onCommit?.Invoke();
        }

        // Flushes a pending drag commit when focus leaves the control (tab away / click elsewhere), so the
        // canvas re-binds immediately instead of waiting out the debounce. Mirrors FlushTextEditOnBlur.
        private void FlushValueEditOnBlur(VisualElement fieldOrRow)
        {
            fieldOrRow.RegisterCallback<FocusOutEvent>(_ => CommitPendingValueEdit(), TrickleDown.TrickleDown);
        }

        // Focus lands on a field's INNER text element, never on the field itself, so a plain
        // `focusedElement != field` test reads "not focused" while the user is typing. Walk up from whatever
        // holds focus instead (same shape as the vector-slider guard). A LABEL SCRUB takes no keyboard focus,
        // so it reads as "not typing" and keeps its per-tick display updates.
        private static bool IsTypingInField(VisualElement field)
        {
            var focused = field?.focusController?.focusedElement as VisualElement;
            for (; focused != null; focused = focused.parent)
                if (focused == field) return true;
            return false;
        }

        // The display half of a CLAMPED numeric row, in one place. A clamped row has to show the value the model
        // actually took — but a FloatField notifies per KEYSTROKE, so pushing the clamp back mid-entry destroys
        // what is being typed: with a floor of 4, the "1" of "10" is rewritten to "4" and the next digit lands as
        // "40". (It eats decimals the same way: "1." parses as 1 and the dot is gone before ".5" can follow.) The
        // MODEL is still clamped on every tick — nothing downstream ever sees an out-of-range value — only the
        // DISPLAY waits, and catches up the moment entry ends.
        //
        // Reading the MODEL rather than remembering the last clamp is what keeps it honest when something else
        // writes the row: a paired slider drag, a ↺ reset, an undo. Register AFTER the row's own change callback
        // so the model is already written when this runs, and drop the row's own self-rewrite when you do.
        internal static void SyncClampedDisplay<T>(BaseField<T> field, Func<T> read)
        {
            void Show()
            {
                // Detached mid-edit (the Properties panel rebuilt under us): a fresh row owns the display now,
                // and `read` may be pointed at a node this row no longer describes.
                if (field.panel == null) return;
                field.SetValueWithoutNotify(read());
            }

            field.RegisterValueChangedCallback(_ => { if (!IsTypingInField(field)) Show(); });
            field.RegisterCallback<FocusOutEvent>(_ => Show());
            field.RegisterCallback<KeyDownEvent>(evt =>
            {
                // Enter usually blurs the field too; covering both costs nothing and does not depend on it.
                if (evt.keyCode == KeyCode.Return || evt.keyCode == KeyCode.KeypadEnter) Show();
            });
        }

        // Save's fill + label in one place. Both faces are tuned deep enough that white wins on all four
        // skin/state combinations AND on the hover tint — but the label is still DERIVED rather than hardcoded,
        // so a future re-tune that crosses the contrast line flips the text instead of quietly going unreadable
        // (which is exactly what the first pass at a bright-gold Save did).
        // Whether Save should wear its unsaved face. Preset mode keeps its own flag: its edits are already in the
        // asset (so the layout-database notion of dirty doesn't apply) but not yet written to disk.
        private bool IsSaveDirty => _presetMode ? _presetDirty : _isDirty;

        private void PaintSaveButtonFace()
        {
            if (_saveButton == null) return;
            var painted = ChromePaint(_saveButton, IsSaveDirty ? DesignerPalette.SaveDirtyBg : DesignerPalette.SaveBg);
            _saveButton.style.color = BindingFactory.ContrastingReadoutColor(painted);
        }

        private void UpdateSaveButtonText()
        {
            // Single funnel for every _isDirty change → keep Unity's native unsaved-changes guard in lockstep so
            // closing the window / quitting the editor with unsaved layout edits PROMPTS to save instead of
            // silently discarding the clone. See SaveChanges()/saveChangesMessage.
            // Preset mode is excluded on purpose (matching OnEnable): its edits live in the asset the moment they're
            // made, so closing the window can't lose them and a "save the database?" prompt would be a lie.
            hasUnsavedChanges = !_presetMode && _isDirty;

            if (_saveButton != null)
            {
                _saveButton.text = IsSaveDirty ? "Save*" : "Save";
                PaintSaveButtonFace();
            }

            // Same funnel keeps the toolbar's type-switcher label in sync (every load/save/dirty change
            // passes through here).
            UpdateTypeSwitcherButton();
        }

        // Shows/updates the toolbar's edited-type breadcrumb (whose last crumb is the "Type: <Name> ▾"
        // switcher) — hidden in preset/showcase sessions and when no target type resolves.
        private void UpdateTypeSwitcherButton() => RefreshBreadcrumb();

        // The ancestor-chain menu behind the type-switcher button. Ancestors are annotated with their
        // layout state; picking one re-targets the designer via the normal LoadTypeLayout flow (dirty
        // prompt + clone), keeping the current test target as the preview stand-in. When previewing with
        // a subclass instance, the downward chain back to its type is offered too.
        private void ShowTypeSwitcherMenu()
        {
            var current = ResolveTargetType();
            if (current == null) return;

            var menu = new GenericMenu();
            // Start-fresh entry: leave this type and go back to the blank-state picker to target a different script.
            menu.AddItem(new GUIContent("Pick a different script…"), false, ReturnToScriptPicker);
            menu.AddSeparator("");
            menu.AddDisabledItem(new GUIContent(current.Name + " (editing)"), true);

            for (var t = current.BaseType; t != null && SasquatchContextMenu.IsTypeEditable(t); t = t.BaseType)
            {
                var picked = t;
                string note = LayoutRegistry.HasOwnLayout(t) ? " — has layout" : " — no layout yet";
                menu.AddItem(new GUIContent("Base: " + t.Name + note), false, () => LoadTypeLayout(picked, _testTarget));
            }

            if (_testTarget != null)
            {
                var targetType = _testTarget.GetType();
                if (targetType != current && current.IsAssignableFrom(targetType))
                {
                    var chain = new List<Type>();
                    for (var t = targetType; t != null && t != current; t = t.BaseType) chain.Add(t);
                    chain.Reverse();
                    if (chain.Count > 0) menu.AddSeparator("");
                    foreach (var d in chain)
                    {
                        var picked = d;
                        string note = LayoutRegistry.HasOwnLayout(d) ? " — has layout" : " — no layout yet";
                        menu.AddItem(new GUIContent("Derived: " + d.Name + note), false, () => LoadTypeLayout(picked, _testTarget));
                    }
                }
            }

            menu.DropDown(_typeSwitcherButton.worldBound);
        }

        /// <summary>
        /// Unity's save-before-close/quit hook (fires when <see cref="EditorWindow.hasUnsavedChanges"/> is true and
        /// the user closes the window or quits the editor, choosing "Save"). Persists the working clone the same
        /// way the Save button does, then clears the unsaved flag via <c>base.SaveChanges()</c>.
        /// </summary>
        public override void SaveChanges()
        {
            // A pending typing-burst commit is satisfied by this save (node writes are applied live; only the
            // save/refresh was deferred) — end the burst so it can't re-dirty the asset after the close prompt.
            _pendingTextEditCommit?.Pause();
            _pendingTextEditCommit = null;
            _textEditBurstActive = false;
            _textEditBurstNode = null;
            // Same for an in-flight slider/color drag — end the burst so it can't re-dirty after the prompt.
            _pendingValueEditCommit?.Pause();
            _pendingValueEditCommit = null;
            _valueEditBurstActive = false;
            _pendingValueEditOnCommit = null;
            _valueEditBurstNode = null;
            SaveActiveAsset(); // safe for the showcase/standalone/database branches; no-op when no clone exists
            base.SaveChanges();
        }

        private static void StyleToolbarMini(Button btn)
        {
            btn.style.fontSize = 10;
            btn.style.paddingLeft = 6;
            btn.style.paddingRight = 6;
        }

        // Builds one column-visibility icon button: a 16x12 framed "square" with a shaded bar on the
        // left / center / right to represent that column. col: 0=left, 1=center(canvas), 2=right.
        private Button MakeColumnToggle(int col)
        {
            var btn = new Button(() => ToggleColumn(col));
            btn.text = "";
            btn.tooltip = col == 0 ? "Show/Hide left column" : col == 1 ? "Show/Hide center (canvas)" : "Show/Hide right column";
            btn.style.width = 26;
            btn.style.height = 20;
            btn.style.paddingLeft = 0; btn.style.paddingRight = 0; btn.style.paddingTop = 0; btn.style.paddingBottom = 0;
            btn.style.marginLeft = 2; btn.style.marginRight = 2;
            btn.style.alignItems = Align.Center;
            btn.style.justifyContent = Justify.Center;

            var frame = new VisualElement { pickingMode = PickingMode.Ignore };
            frame.style.width = 16;
            frame.style.height = 12;
            frame.style.borderTopWidth = 1; frame.style.borderBottomWidth = 1; frame.style.borderLeftWidth = 1; frame.style.borderRightWidth = 1;
            var frameColor = DesignerPalette.TextPrimary;
            frame.style.borderTopColor = frameColor; frame.style.borderBottomColor = frameColor; frame.style.borderLeftColor = frameColor; frame.style.borderRightColor = frameColor;
            // The bar is a FLEX child, not an absolutely-positioned one. Absolute offsets are measured from the
            // padding box (inside the 1px border), so the old hand-computed left:6 landed the center bar 1px
            // right of true center — visibly lopsided next to its two symmetric siblings. Letting flex place it
            // (padding 1 for the end insets + justify-content for the slot) is centered by construction.
            frame.style.flexDirection = FlexDirection.Row;
            frame.style.alignItems = Align.Stretch;
            frame.style.paddingLeft = 1; frame.style.paddingRight = 1; frame.style.paddingTop = 1; frame.style.paddingBottom = 1;
            frame.style.justifyContent = col == 0 ? Justify.FlexStart : col == 1 ? Justify.Center : Justify.FlexEnd;

            var bar = new VisualElement { pickingMode = PickingMode.Ignore };
            bar.style.width = 4;
            bar.style.flexShrink = 0;
            bar.style.backgroundColor = frameColor;
            frame.Add(bar);
            btn.Add(frame);

            // These buttons paint their own bevel face inline, which beats Unity's stock :hover USS — so
            // without this they were the only chrome in the toolbar with NO hover feedback at all.
            EditorSpringFX.ButtonSpring(btn);
            AddChromeHoverRepaint(btn, UpdateColumnButtons);
            return btn;
        }

        private bool IsColumnVisible(int col) => col == 0 ? _leftVisible : col == 1 ? _centerVisible : _rightVisible;

        private void SetColumnVisible(int col, bool visible)
        {
            if (col == 0) _leftVisible = visible;
            else if (col == 1) _centerVisible = visible;
            else _rightVisible = visible;
        }

        private void ToggleColumn(int col)
        {
            SetColumnVisible(col, !IsColumnVisible(col));
            // Never let all three hide — keep at least the canvas.
            if (!_leftVisible && !_centerVisible && !_rightVisible) _centerVisible = true;
            ApplyColumnVisibility();
        }

        // Right-click header → "Focus": show only this column.
        private void FocusColumn(int col)
        {
            _leftVisible = col == 0;
            _centerVisible = col == 1;
            _rightVisible = col == 2;
            ApplyColumnVisibility();
        }

        // -1 = no child collapsed; otherwise the index of the collapsed child. Tracked so we can
        // switch which child is collapsed (TwoPaneSplitView only collapses one at a time).
        private readonly Dictionary<TwoPaneSplitView, int> _splitCollapsed = new Dictionary<TwoPaneSplitView, int>();

        private void SetCollapsed(TwoPaneSplitView split, int index)
        {
            if (split == null) return;
            int cur = _splitCollapsed.TryGetValue(split, out var c) ? c : -1;
            if (cur == index) return;
            _splitCollapsed[split] = index;
            // Defer: collapse APIs touch internals not ready until the split's first layout.
            split.schedule.Execute(() =>
            {
                try
                {
                    if (cur != -1) split.UnCollapse();
                    if (index != -1) split.CollapseChild(index);
                }
                catch { /* not yet initialized; reapplied on next change */ }
            });
        }

        // Layout is two nested splits: outer = [left(0), inner(1)]; inner = [canvas(0), right(1)].
        // A split can only collapse ONE child, so "show left only" (hide canvas+right) is done by
        // collapsing the whole inner split (outer child 1) instead.
        private void ApplyColumnVisibility()
        {
            if (!_leftVisible && !_centerVisible && !_rightVisible) _centerVisible = true;

            if (!_centerVisible && !_rightVisible)
            {
                // Only the left column remains → hide the entire inner split.
                SetCollapsed(_innerSplit, -1);
                SetCollapsed(_outerSplit, 1);
            }
            else
            {
                SetCollapsed(_outerSplit, _leftVisible ? -1 : 0);
                if (!_centerVisible) SetCollapsed(_innerSplit, 0);
                else if (!_rightVisible) SetCollapsed(_innerSplit, 1);
                else SetCollapsed(_innerSplit, -1);
            }

            UpdateColumnButtons();
        }

        private void UpdateColumnButtons()
        {
            for (int i = 0; i < _columnButtons.Length; i++)
            {
                var btn = _columnButtons[i];
                if (btn == null) continue;
                bool visible = IsColumnVisible(i);
                // Visible = raised/active; hidden = pushed-in/inactive.
                ChromePaint(btn, visible ? DesignerPalette.BevelFaceRaised : DesignerPalette.BevelFaceSunken);
                // A hidden column sits at half opacity, which would mute the hover tint into nothing — bring it
                // most of the way up while the cursor is on it so the feedback reads on all six states.
                bool hot = btn.ClassListContains(ChromeHoverClass);
                btn.style.opacity = visible ? 1f : (hot ? 0.8f : 0.5f);
                var inset = visible ? DesignerPalette.BevelHighlight : DesignerPalette.BevelShadowDeep;
                btn.style.borderTopColor = inset; btn.style.borderLeftColor = inset;
                var raised = visible ? DesignerPalette.BevelShadow : DesignerPalette.BevelHighlightSoft;
                btn.style.borderBottomColor = raised; btn.style.borderRightColor = raised;
            }
        }

        // Adds a right-click menu to a column header: Focus (show only this) / Hide.
        private void AddColumnContextMenu(VisualElement header, int col)
        {
            if (header == null) return;
            header.RegisterCallback<ContextClickEvent>(evt =>
            {
                var menu = new GenericMenu();
                menu.AddItem(new GUIContent("Focus (hide others)"), false, () => FocusColumn(col));
                if (IsColumnVisible(col))
                {
                    menu.AddItem(new GUIContent("Hide"), false, () => { SetColumnVisible(col, false); ToggleColumnGuard(); });
                }
                else
                {
                    menu.AddItem(new GUIContent("Show"), false, () => { SetColumnVisible(col, true); ApplyColumnVisibility(); });
                }
                menu.ShowAsContext();
                evt.StopPropagation();
            });
        }

        private void ToggleColumnGuard()
        {
            if (!_leftVisible && !_centerVisible && !_rightVisible) _centerVisible = true;
            ApplyColumnVisibility();
        }

        // Returns the window so callers (e.g. the inspector quick-edit popup) can deep-link into it
        // — existing callers simply ignore the return value.
        /// <summary>Opens (or focuses) the designer for <paramref name="type"/>, optionally bound to a live object for preview.</summary>
        public static SasquatchLayoutDesignerWindow OpenWindowForType(Type type, UnityEngine.Object testTarget)
        {
            var window = GetWindow<SasquatchLayoutDesignerWindow>("Sasquatch Layout Designer");
            window.minSize = new Vector2(900, 600);
            window.Show();

            window.LoadTypeLayout(type, testTarget);
            return window;
        }

        // Opens the designer on an EXPLICIT, caller-supplied in-memory layout (e.g. the Showcase window's
        // curated demo layouts) instead of looking one up in the registry. The layout is cloned via
        // Instantiate, so designer edits never mutate the caller's original, and nothing is written to disk
        // unless the user explicitly Saves. The IsTypeEditable guard is intentionally skipped: the call is
        // explicit and curated (the normal guard only exists to stop selection auto-follow from loading Unity
        // built-ins).
        /// <summary>Opens (or focuses) the designer on an explicit in-memory <paramref name="layout"/> for
        /// <paramref name="type"/>, bound to <paramref name="testTarget"/> for preview. The layout is cloned;
        /// edits don't touch the caller's copy and aren't persisted unless the user Saves.</summary>
        public static SasquatchLayoutDesignerWindow OpenWindowWithLayout(InspectorLayoutAsset layout, UnityEngine.Object testTarget, Type type, string showcaseOverrideKey = null)
        {
            var window = GetWindow<SasquatchLayoutDesignerWindow>("Sasquatch Layout Designer");
            window.minSize = new Vector2(900, 600);
            window.Show();

            window.LoadExplicitLayout(layout, testTarget, type, showcaseOverrideKey);
            return window;
        }

        private void LoadExplicitLayout(InspectorLayoutAsset layout, UnityEngine.Object testTarget, Type type, string showcaseOverrideKey = null)
        {
            if (layout == null || layout.Root == null) return;

            _navStack.Clear();   // a Showcase/preset session has nothing to do with the trail (mirrors LoadTypeLayout)

            // Prompt to save the active layout if dirty (mirrors LoadTypeLayout). Shares PromptSaveIfDirty
            // rather than repeating the dialogs inline, so the Cancel/Escape behaviour cannot drift between
            // the two copies the way it used to. Cancel abandons the load and leaves the session untouched.
            if (!PromptSaveIfDirty()) return;

            CleanupClone();

            _layoutAsset = null; // database-managed/transient (no standalone asset backing it)
            _showcaseOverrideKey = showcaseOverrideKey; // route Save back to this Showcase page (if any)
            _testTarget = testTarget;

            // Clone so the showcase's original layout is never mutated by designer edits.
            // A fresh clone means the DESIGNER has not resized anything in it yet, so Save must again defer
            // to live-inspector resizes. Leaving a stale `true` here suppressed the merge and clobbered the
            // NEXT type's real-inspector sizes.
            _designerResizedSinceClone = false;
            AdoptWorkingClone(Instantiate(layout));
            if (type != null) _clonedLayoutAsset.TargetTypeName = type.AssemblyQualifiedName;
            string guid = null;
            // Instance shortcut only when the test target IS the edited type (see LoadTypeLayout).
            if (testTarget != null && (type == null || testTarget.GetType() == type)) ScriptGuidUtility.TryGetGuid(testTarget, out guid);
            if (string.IsNullOrEmpty(guid) && type != null) ScriptGuidUtility.TryGetGuid(type, out guid);
            _clonedLayoutAsset.ScriptGuid = guid;

            SnapshotFieldsAtCloneTime();

            SetPrimarySelection(_clonedLayoutAsset.Root);
            _isDirty = false;
            UpdateSaveButtonText();
            RefreshAll(disableScrollPreservation: true);
        }

        /// <summary>
        /// Selects the node at the given child-index path (-1 = descend into a collection's ItemLayout)
        /// in the freshly loaded layout, then scrolls the design canvas (and hierarchy) to it and pings
        /// it with a brief accent flash — the inspector quick-menu's "Open in Designer" deep link. The
        /// path is computed against the REGISTERED layout root; the designer's working CLONE is
        /// structurally identical, so the same path resolves to the corresponding cloned node. Falls
        /// back to the root when the path no longer resolves.
        /// </summary>
        public void SelectNodeByIndexPath(List<int> path)
        {
            if (_clonedLayoutAsset?.Root == null) return;
            var node = LocateNodeByIndexPath(path, _clonedLayoutAsset.Root) ?? _clonedLayoutAsset.Root;
            SelectAndPingNode(node);
        }

        // Locates the node's element in the design canvas and the hierarchy (both stamp the node into
        // userData), scrolls each into view, and flashes an accent overlay on it so the user's eye lands
        // exactly where the deep link points.
        private void PingNodeInPanels(LayoutNode node)
        {
            ScrollToAndPing(_previewContainer, node);
            ScrollToAndPing(_hierarchyContainer, node);
        }

        /// <summary>
        /// Whether the scroll offset moved since the ping last set it — i.e. the user grabbed the wheel and the
        /// ping must let go. Separate and testable because the deep-link ping re-applies for ~500ms, easily long
        /// enough for someone to start scrolling away from where they were just sent.
        /// </summary>
        internal static bool PingScrollWasTakenOver(float now, float lastApplied)
            => Mathf.Abs(now - lastApplied) > 0.5f;

        private void ScrollToAndPing(ScrollView scroll, LayoutNode node)
        {
            if (scroll == null || node == null) return;
            var element = scroll.Query<VisualElement>()
                                .Where(e => ReferenceEquals(e.userData, node))
                                .First();
            if (element == null) return;

            // A fresh ping owns the scroll — cancel any in-flight restoration so the two can't fight.
            CancelActiveScrollRestoration(scroll);

            // ScrollTo computed on the first (width-valid) layout pass lands SHORT on a tall canvas: the
            // widgets above keep growing for several more frames, pushing the target down after we've
            // already scrolled (the deep-link "spring fires but the object never comes into view" bug —
            // most visible on layouts tall enough to need real scrolling, like a full field showcase).
            // Fix: re-run ScrollTo across the settle window. ScrollTo recomputes from the element's
            // CURRENT position each call, so it tracks the target to its final resting place; once the
            // element is fully in view ScrollTo is a no-op, so the repeats cost nothing after it settles.
            // Ping (the one-shot flash + scale) fires exactly ONCE, the first time the element is laid out.
            var state = new ScrollRestorationState();
            bool pinged = false;
            bool everApplied = false;
            // Returns false once the ping should let go. Like RestoreScrollOffsetRobust, this window used to run
            // to completion no matter what the user did — for its full ~500ms the pinged element could not be
            // scrolled out of view, because the next tick dragged it straight back.
            Func<bool> apply = () =>
            {
                // A rebuild mid-window can detach the captured element; stop rather than scroll to a ghost.
                if (element.panel == null) return true;
                if (float.IsNaN(element.layout.width) || element.layout.width <= 0) return true;

                // The offset moved and it was not us: the user took the scroll. Nothing else can move it —
                // content GROWING never shifts the offset, and a shrink-clamp is close enough to a user scroll
                // that yielding is the right call either way.
                if (everApplied && PingScrollWasTakenOver(scroll.scrollOffset.y, state.Target.y)) return false;

                scroll.ScrollTo(element);
                // Keep Target current so a PreserveScroll that lands mid-window (a rebuild inside our
                // re-apply window) restores to the ping's live offset, not the state's default (0,0) — and so
                // the takeover check above has something to compare against.
                state.Target = scroll.scrollOffset;
                everApplied = true;
                if (!pinged)
                {
                    pinged = true;
                    QuickEditGlow.Ping(element);
                }
                return true;
            };

            // Every content relayout (including a late async preview finishing) re-tracks the target.
            EventCallback<GeometryChangedEvent> onGeom = evt =>
            {
                if (!apply()) CancelActiveScrollRestoration(scroll);
            };
            scroll.contentContainer.RegisterCallback(onGeom);
            state.OnGeom = onGeom;

            // Immediate attempt — handles the already-settled case (window already open) synchronously.
            apply();

            // Repeating backstop for frames that don't raise a content GeometryChanged.
            int frame = 0;
            IVisualElementScheduledItem scheduledItem = null;
            scheduledItem = scroll.schedule.Execute(() =>
            {
                if (!apply())
                {
                    CancelActiveScrollRestoration(scroll);
                    return;
                }
                frame++;
                if (frame > PingScrollMaxReapplyFrames) scheduledItem?.Pause();
            }).Every(ScrollRestoreReapplyIntervalMs);
            state.ScheduledItem = scheduledItem;

            // Tear both listeners down once the layout has settled (outlasts the repeat window).
            IVisualElementScheduledItem cleanupItem = scroll.schedule.Execute(() =>
            {
                if (scroll != null && scroll.contentContainer != null)
                {
                    scroll.contentContainer.UnregisterCallback(onGeom);
                }
                if (_activeScrollRestorations.TryGetValue(scroll, out var s) && s == state)
                {
                    _activeScrollRestorations.Remove(scroll);
                }
            });
            cleanupItem.ExecuteLater(PingScrollCleanupMs);
            state.CleanupScheduledItem = cleanupItem;

            // Register in the shared restoration table so CancelActiveScrollRestoration tears us down too.
            _activeScrollRestorations[scroll] = state;
        }

        // Save-or-discard prompt for the active working layout when it has unsaved changes. Called by the two
        // paths that abandon the current clone: switching to a different type (LoadTypeLayout) and returning to
        // the blank picker (ReturnToScriptPicker). LoadExplicitLayout repeats the same two dialogs inline, so
        // wording changes belong in both places. A no-op when nothing is dirty.
        /// <summary>
        /// Save-or-discard prompt for the active working layout. Returns TRUE to proceed with abandoning the
        /// clone, FALSE if the user cancelled and the session must be left exactly as it was. Every caller MUST
        /// honour a false return — the callers are the paths that then run <c>CleanupClone()</c>, which calls
        /// <c>Undo.ClearUndo</c> and destroys the clone, so a discarded session is not even on the undo stack.
        /// <para>Three-way on purpose. This was a two-button Save/Discard dialog, and the two-button overload
        /// returns false for Escape and for closing the window — so the reflex answer to an unexpected modal
        /// resolved to the DESTRUCTIVE one, with no way to say "never mind". Slot 1 is the Escape target, so
        /// Cancel sits there, matching OrphanedHeaderCleanup's "Decide Later". (Audit 2026-08-09, finding D2.)</para>
        /// </summary>
        private bool PromptSaveIfDirty()
        {
            bool dirtyAsset = _isDirty && _layoutAsset != null;
            bool dirtyDatabase = _isDirty && _clonedLayoutAsset != null && _layoutAsset == null;
            if (!dirtyAsset && !dirtyDatabase) return true; // nothing at stake — proceed

            string message = dirtyAsset
                ? $"You have unsaved changes on {AssetDatabase.GetAssetPath(_layoutAsset)}. Do you want to save them?"
                : "You have unsaved layout changes in the database. Do you want to save them?";

            int choice = EditorUtility.DisplayDialogComplex(
                "Unsaved Changes",
                message,
                "Save",     // 0
                "Cancel",   // 1 (cancel/Esc — keep editing, change nothing)
                "Discard"); // 2

            switch (choice)
            {
                case 0: SaveActiveAsset(); return true;
                case 2: return true;   // explicit, deliberate discard
                default: return false; // Cancel, Escape, or the window closed
            }
        }

        // Toolbar "Type ▾ ▸ Pick a different script…": drops the current type and returns to the blank-state
        // picker card so a different script can be targeted (the window is a singleton, so this is the only way
        // back to the picker once a layout is loaded). Mirrors LoadTypeLayout's front half — dirty prompt +
        // CleanupClone — but lands on the empty state instead of cloning a new type.
        private void ReturnToScriptPicker()
        {
            if (!PromptSaveIfDirty()) return; // Cancel: stay on the current type, keep the clone
            _navStack.Clear();   // the trail led to a type we're about to drop (mirrors LoadTypeLayout)
            CleanupClone(); // nulls _clonedLayoutAsset → ResolveTargetType() becomes null → picker shows
            _layoutAsset = null;
            _showcaseOverrideKey = null;
            _testTarget = null;
            _isDirty = false;
            UpdateSaveButtonText();          // hides the Type ▾ button (no type resolves anymore)
            RefreshAll(disableScrollPreservation: true); // RefreshPreview rebuilds the blank-state picker card
        }

        private void LoadTypeLayout(Type type, UnityEngine.Object testTarget)
        {
            if (type == null) return;

            // Never load Unity built-ins / non-user types into the designer (e.g. selecting a GameObject whose
            // only non-Transform component is a built-in like UnityEngine.Rendering.Volume). This is the single
            // chokepoint every entry point funnels through (selection auto-follow, OpenWindowForType, the context
            // menu, the quick-edit deep links), so guarding here closes them all. Placed before the save-prompt /
            // CleanupClone so an ineligible target is a pure no-op that never disturbs the current layout.
            if (!SasquatchContextMenu.IsTypeEditable(type)) return;

            // Already editing exactly this type, in an ordinary registry-backed session? Then this is not a
            // retarget at all — re-pointing the preview target is the whole job. The full teardown below
            // would raise the unsaved-changes prompt for a "switch" to where we already are, and that
            // prompt's Save button is precisely what destroys a live-inspector edit made since the clone was
            // taken. The quick-edit popup's own "Open in Designer" footer lands here, which is what made
            // that the sharpest route to losing an edit. Deliberately narrow: a drill-in (which preserves
            // the trail on purpose), a preset/Showcase session and a hand-opened standalone asset all still
            // take the full path, because for them "same type" does not mean "same session".
            if (!_navPreserveStack && !_presetMode && _layoutAsset == null
                && string.IsNullOrEmpty(_showcaseOverrideKey)
                && _clonedLayoutAsset != null && ResolveTargetType() == type)
            {
                _navStack.Clear();   // a non-preserve caller drops the trail, exactly as it does below
                _testTarget = testTarget;
                RefreshAll();
                return;
            }

            // Every OTHER caller of this chokepoint — the script picker, the ancestor switcher, selection
            // auto-follow, the quick-edit deep links — is a jump to an UNRELATED type, and a Back offering to
            // return somewhere that has nothing to do with what's on screen is worse than no Back at all.
            // Clearing here rather than at each call site means a new caller is correct without knowing this
            // exists; only the drill-in navigation itself opts out. See Navigation.cs.
            // Ask BEFORE mutating anything: on Cancel the session must be byte-identical to how it was, and
            // clearing the nav stack first would leave a visible side effect behind from a cancelled action.
            if (!PromptSaveIfDirty()) return;

            if (!_navPreserveStack) _navStack.Clear();

            CleanupClone();

            // A different type means a different layout, so a canvas or hierarchy query aimed at the old one is
            // meaningless. Clear them here (the bars stay open) — the refreshes that follow re-apply empty.
            ResetCanvasSearchForNewLayout();
            ResetHierarchySearchForNewLayout();

            _layoutAsset = null; // Indicating database-managed/transient
            _showcaseOverrideKey = null; // a normal type-load is never a Showcase override session
            _testTarget = testTarget;

            if (LayoutRegistry.TryGet(type, testTarget, out var registeredLayout))
            {
                // Clone-time AutoAppend parity: the registered layout can be STALE right here — fields added
                // to the script while no inspector rebuilt this type (or while a designer held it and
                // suppressed the inspectors' auto-sync) haven't been appended yet. Cloning the stale tree
                // while SnapshotFieldsAtCloneTime records the CURRENT code fields would ledger those fields
                // on Save without them ever entering the layout — permanently excluding them from
                // auto-append. Reconcile first (the same persisting call the inspector hot path makes; a
                // strict no-op when already in sync) so the clone — and the canvas — opens synced to the
                // script. AutoAppend mode only; the other modes keep drift user-visible by design. Skipped
                // when ANOTHER window still edits this type (mirrors the inspectors' IsEditingType guard —
                // this window's own clone was already released by CleanupClone above).
                var syncSettings = SasquatchSettingsManager.Current;
                if (syncSettings != null && syncSettings.UnboundFieldHandling == UnboundFieldSyncMode.AutoAppend &&
                    !IsEditingType(type))
                {
                    UnboundFieldSync.ReconcileLayout(type, registeredLayout, syncSettings.ApplyScriptAttributesOnSync);
                }
                // Button rename self-heal before cloning (every sync mode — it repairs existing bindings,
                // imports nothing), so the canvas opens showing the relinked name. Same other-window guard.
                if (!IsEditingType(type))
                    ButtonMethodSync.HealLayout(type, registeredLayout);
                // A fresh clone means the DESIGNER has not resized anything in it yet, so Save must again defer
                // to live-inspector resizes. Leaving a stale `true` here suppressed the merge and clobbered the
                // NEXT type's real-inspector sizes.
                _designerResizedSinceClone = false;
                AdoptWorkingClone(Instantiate(registeredLayout));
            }
            else
            {
                _designerResizedSinceClone = false; // fresh clone — see the sibling branch above
                AdoptWorkingClone(CreateInstance<InspectorLayoutAsset>());
                _clonedLayoutAsset.Root = NewRootWithScriptHeader();
                _clonedLayoutAsset.TargetTypeName = type.AssemblyQualifiedName;
                // Stamp the rename-proof GUID so a layout authored now survives later class/file renames.
                // The instance shortcut is only valid when the test target IS the edited type — when
                // authoring a layout FOR an ancestor with a subclass instance as the preview target, the
                // subclass's GUID must not be stamped onto the ancestor's layout.
                string newGuid = null;
                if (testTarget != null && testTarget.GetType() == type) ScriptGuidUtility.TryGetGuid(testTarget, out newGuid);
                if (string.IsNullOrEmpty(newGuid)) ScriptGuidUtility.TryGetGuid(type, out newGuid);
                _clonedLayoutAsset.ScriptGuid = newGuid;

                // Seed the fresh clone's ledger with the current code fields: a from-scratch session
                // starts with an empty canvas by DESIGN, and an empty ledger + empty tree otherwise
                // reads as the drained state whose reconcile mass-inserts every field (see
                // UnboundFieldSync.SeedCloneLedgerWithCurrentFields). Fields added to code AFTER this
                // moment stay unledgered, so the mid-session catch-up still appends them.
                UnboundFieldSync.SeedCloneLedgerWithCurrentFields(type, _clonedLayoutAsset);

                // Fresh script with no saved layout: land on the Tools tab. That's where the top
                // "import everything" action lives, which is the first thing most users reach for.
                _activeLeftTab = 2;
            }
            SnapshotFieldsAtCloneTime();

            SetPrimarySelection(_clonedLayoutAsset.Root);
            _isDirty = false;
            UpdateSaveButtonText();
            RefreshAll(disableScrollPreservation: true);
        }

        /// <summary>
        /// Returns the non-Sasquatch Inspector editor type that Unity would resolve for <paramref name="targetType"/>, or
        /// null if Sasquatch Inspector's own fallback editor wins (i.e. nothing competes). It asks Unity's
        /// public resolver via <see cref="UnityEditor.Editor.CreateEditor(UnityEngine.Object)"/> and checks whether
        /// the editor Unity picks is one of ours. This also catches editors that other inspector plugins inject at
        /// runtime without a <c>[CustomEditor]</c> attribute — an assembly scan of attributes would miss those.
        /// </summary>
        /// <param name="instance">Optional live instance of the type to probe with — avoids fabricating one (the
        /// designer passes its throwaway mock). When null or mismatched, a hidden throwaway instance is created and
        /// destroyed.</param>
        public static Type FindCompetingEditor(Type targetType, UnityEngine.Object instance = null)
        {
            if (targetType == null) return null;
            // CreateEditor needs a concrete UnityEngine.Object instance, so non-instantiable types can't compete.
            if (targetType.IsAbstract || targetType.IsGenericTypeDefinition) return null;
            if (!typeof(UnityEngine.Object).IsAssignableFrom(targetType)) return null;

            UnityEngine.Object probe = (instance != null && instance.GetType() == targetType) ? instance : null;
            bool fabricated = false;
            GameObject tempGo = null;
            UnityEditor.Editor probeEditor = null;
            try
            {
                if (probe == null)
                {
                    // No live instance supplied: fabricate a throwaway one. Hidden + DontSave so it never touches
                    // the scene/project. (Fabricating a MonoBehaviour runs its OnEnable in edit mode — the common
                    // designer path avoids this by passing the existing mock instance; the try/catch contains any
                    // misbehaving type.)
                    if (typeof(ScriptableObject).IsAssignableFrom(targetType))
                    {
                        probe = ScriptableObject.CreateInstance(targetType);
                    }
                    else if (typeof(Component).IsAssignableFrom(targetType))
                    {
                        tempGo = EditorUtility.CreateGameObjectWithHideFlags(
                            "SasquatchInspector_CompeteProbe", HideFlags.HideAndDontSave);
                        probe = tempGo.AddComponent(targetType);
                    }
                    else
                    {
                        return null; // not an inspectable object type (e.g. a raw asset importer target)
                    }
                    fabricated = true;
                }
                if (probe == null) return null;

                probeEditor = UnityEditor.Editor.CreateEditor(probe);
                if (probeEditor == null) return null;

                var editorType = probeEditor.GetType();
                // Our own fallback editors (and the base) are never "competitors".
                if (typeof(VisualInspectorEditor).IsAssignableFrom(editorType)) return null;
                return editorType;
            }
            catch
            {
                // Probing a hostile type must never throw into the designer; treat as "no competitor".
                return null;
            }
            finally
            {
                if (probeEditor != null) UnityEngine.Object.DestroyImmediate(probeEditor);
                if (fabricated)
                {
                    if (tempGo != null) UnityEngine.Object.DestroyImmediate(tempGo);
                    else if (probe != null) UnityEngine.Object.DestroyImmediate(probe);
                }
            }
        }

        private void UpdateConflictWarning(Type targetType, UnityEngine.Object instance = null)
        {
            if (_conflictWarningBox == null) return;

            _conflictWarningBox.Clear();
            _conflictWarningBox.style.display = DisplayStyle.None;

            if (targetType == null) return;

            // Case 1: a GENUINE per-type [CustomEditor] naming this exact type (the developer's or a third party's).
            // Unity always resolves it, so the layout can't draw via resolution. We offer a per-type FORCE TAKEOVER
            // — draw the layout in place of that editor's inspector body by panel displacement (public VisualElement
            // API). Default is to defer. The classifier reads the [CustomEditor] ctor-args; a blanket editor
            // another inspector framework injects without an attribute is NOT surfaced here (that's the global
            // "Take Over Other Inspectors" setting — case 2).
            Type genuine = SasquatchGeneratedEditors.GetGenuinePerTypeEditor(targetType);
            if (genuine != null)
            {
                // A Sasquatch-EXPORTED editor is a completely normal genuine editor here — the same Force
                // Takeover / Release toggle applies (taking over = this live layout draws; released = the file's
                // baked copy renders, the in-project preview of what package-less teammates get). Only the
                // wording differs so the user knows it's their own export, not a competitor.
                bool exported = Export.ExportMarker.IsExportedEditor(genuine);
                bool takingOver = LayoutRegistry.IsForceTakeoverOwn(targetType);
                StyleConflictBox();

                string text;
                if (exported)
                    text = takingOver
                        ? $"Sasquatch Inspector is taking over '{genuine.Name}' (your exported editor) — this live layout draws in the inspector. Release to preview the baked copy the exported file renders on its own."
                        : $"'{genuine.Name}' is your Sasquatch-exported editor — the inspector is showing its baked copy, so this layout won't display live. Force Takeover to keep designing, and use Export Editor again after big changes to refresh the baked copy.";
                else
                    text = takingOver
                        ? $"Sasquatch Inspector is taking over '{genuine.Name}' — this layout draws in place of that editor's inspector body."
                        : $"'{genuine.Name}' is a custom editor for this type, so it takes precedence — Sasquatch Inspector defers to it and this layout won't display.";
                _conflictWarningBox.Add(MakeConflictMessage(text));

                var toggle = new Button(() =>
                {
                    LayoutRegistry.SetForceTakeover(targetType, !takingOver);
                    UpdateConflictWarning(targetType, instance); // rebuild the box to reflect the new state
                    // Also rebuild the Properties panel so anything that reads the takeover state — e.g. an
                    // EmbeddedEditorNode's "Show" HelpBox — updates immediately, not only after a reselect.
                    // (_conflictWarningBox lives in previewPanel, so this Clear()ing the properties panel is safe.)
                    RefreshProperties();
                })
                { text = takingOver ? "Release" : "Force Takeover" };
                toggle.tooltip = takingOver
                    ? (exported
                        ? $"Show the baked copy '{genuine.Name}' renders on its own — what teammates without Sasquatch Inspector see."
                        : $"Hand this type's inspector back to '{genuine.Name}'.")
                    : $"Draw this Sasquatch Inspector layout in place of '{genuine.Name}'. Save your layout for it to take effect.";
                toggle.style.marginLeft = 8;
                toggle.style.flexShrink = 0;
                EditorSpringFX.ButtonSpring(toggle);
                _conflictWarningBox.Add(toggle);
                return;
            }

            // Case 2: a blanket competitor only matters while the global "Take Over Other Inspectors"
            // is OFF — with it ON, displacement draws this layout over the blanket's inspector body, so there is no
            // conflict to surface (and no recompile, unlike the old generated-stub takeover).
            if (!SasquatchSettingsManager.Current.TakeoverFromOtherInspectors)
            {
                var blanket = FindCompetingEditor(targetType, instance);
                if (blanket != null)
                {
                    StyleConflictBox();
                    var msg = MakeConflictMessage(
                        $"'{blanket.Name}' is drawing this type's inspector, so Sasquatch Inspector is deferring to it and " +
                        "this layout won't display. Turn on “Take Over Other Inspectors” in Project Settings ▸ " +
                        "Sasquatch Inspector and Sasquatch Inspector will draw your layout in place of it (no recompile).");
                    _conflictWarningBox.Add(msg);
                }
            }
        }

        // Shows + styles the conflict/takeover notice box (row layout, warning palette). Shared by both the
        // genuine-per-type-editor (force-takeover) case and the blanket-competitor case.
        private void StyleConflictBox()
        {
            _conflictWarningBox.style.display = DisplayStyle.Flex;
            _conflictWarningBox.style.flexDirection = FlexDirection.Row;
            _conflictWarningBox.style.alignItems = Align.Center;
            // Brand-blue info treatment. A translucent accent wash keeps the message text readable while reading
            // as an on-palette "heads-up" notice rather than an error.
            _conflictWarningBox.style.backgroundColor = DesignerPalette.AccentWashStrong;
            _conflictWarningBox.style.paddingTop = 4;
            _conflictWarningBox.style.paddingBottom = 4;
            _conflictWarningBox.style.paddingLeft = 10;
            _conflictWarningBox.style.paddingRight = 10;
            _conflictWarningBox.style.borderBottomWidth = 1;
            _conflictWarningBox.style.borderBottomColor = DesignerPalette.Accent;
        }

        // Builds the wrapping message Label for the conflict/takeover box (both branches use it). The crucial bit
        // is flexBasis=0 + minWidth=0: a wrapping Label's min-content width is its full single-line width, which
        // would push the row past the fixed-width preview pane and clip the flexShrink=0 action button. Zeroing the
        // basis/min-width lets the message wrap INSIDE the pane so the button stays fully visible at any width.
        internal static Label MakeConflictMessage(string text)
        {
            var msg = new Label(text);
            msg.style.color = DesignerPalette.TextPrimary;
            msg.style.fontSize = 11;
            msg.style.flexGrow = 1;
            msg.style.flexBasis = 0;
            msg.style.minWidth = 0;
            msg.style.whiteSpace = WhiteSpace.Normal;
            return msg;
        }

        // ---- Default validation messages -----------------------------------------------------------------------
        // Pre-fill sensible, label-aware message text when a validator is switched on, so authors aren't left
        // staring at a blank field. Callers only ever fill a message that is EMPTY (or still equals the previously
        // generated default), so user-typed text is never clobbered.

        /// <summary>A human-friendly field name for a default message: the explicit label override, else the
        /// nicified leaf of the property path (nested / collection-item paths → the leaf).</summary>
        private static string ValidationFieldLabel(string labelOverride, string propertyPath)
        {
            if (!string.IsNullOrEmpty(labelOverride)) return labelOverride;
            if (string.IsNullOrEmpty(propertyPath)) return "This field";
            string leaf = propertyPath;
            int dot = leaf.LastIndexOf('.');
            if (dot >= 0 && dot < leaf.Length - 1) leaf = leaf.Substring(dot + 1);
            return ObjectNames.NicifyVariableName(leaf);
        }

        // "assigned" reads right for an object reference (drag something in); "cannot be empty" fits a blank string.
        private static string DefaultRequiredMessage(string label, bool isReference) =>
            isReference ? $"{label} must be assigned." : $"{label} cannot be empty.";
        private static string DefaultRangeMessage(string label, float min, float max, bool hasMin, bool hasMax)
        {
            if (hasMin && hasMax) return $"{label} must be between {min} and {max}.";
            if (hasMin) return $"{label} must be at least {min}.";
            if (hasMax) return $"{label} must be at most {max}.";
            return $"{label} is unconstrained.";
        }
        private static string DefaultMethodMessage(string label) => $"{label} is invalid.";
        private static string DefaultCollectionRequiredMessage(string label) => $"{label} must have at least one item.";
    }
}
